--
-- Name: fn_auditoria_ddl(); Type: FUNCTION; Schema: auditoria; Owner: postgres
--

CREATE FUNCTION auditoria.fn_auditoria_ddl() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$

DECLARE
    r RECORD;

BEGIN

    FOR r IN
        SELECT *
        FROM pg_event_trigger_ddl_commands()

    LOOP

        INSERT INTO auditoria.logs_ddl (

            usuario_bd,
            tipo_evento,
            objeto_afectado,
            comando_sql

        )
        VALUES (

            session_user,
            TG_TAG,
            r.object_identity,
            current_query()

        );

    END LOOP;

END;
$$;


ALTER FUNCTION auditoria.fn_auditoria_ddl() OWNER TO postgres;

--
-- Name: fn_auditoria_dml(); Type: FUNCTION; Schema: auditoria; Owner: postgres
--

CREATE FUNCTION auditoria.fn_auditoria_dml() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$

BEGIN

    IF TG_TABLE_SCHEMA = 'auditoria' THEN
        RETURN NEW;
    END IF;

    INSERT INTO auditoria.logs_dml (

        usuario_bd,
        rol_bd,

        esquema_afectado,
        tabla_afectada,

        tipo_operacion,

        datos_anteriores,
        datos_nuevos,

        ip_cliente,
        aplicacion,

        query_sql

    )
    VALUES (

        session_user,
        current_user,

        TG_TABLE_SCHEMA,
        TG_TABLE_NAME,

        TG_OP,

        CASE
            WHEN TG_OP IN ('UPDATE','DELETE')
            THEN to_jsonb(OLD)
            ELSE NULL
        END,

        CASE
            WHEN TG_OP IN ('INSERT','UPDATE')
            THEN to_jsonb(NEW)
            ELSE NULL
        END,

        inet_client_addr()::TEXT,
        current_setting('application_name', true),

        current_query()
    );

    RETURN NEW;

END;
$$;


ALTER FUNCTION auditoria.fn_auditoria_dml() OWNER TO postgres;

--
-- Name: fn_instalar_auditoria(); Type: FUNCTION; Schema: auditoria; Owner: postgres
--

CREATE FUNCTION auditoria.fn_instalar_auditoria() RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE
    r RECORD;

BEGIN

    FOR r IN

        SELECT schemaname, tablename
        FROM pg_tables
        WHERE schemaname IN (

            SELECT esquema
            FROM auditoria.configuracion
            WHERE auditar = TRUE

        )

    LOOP

        EXECUTE format(

            '
            DROP TRIGGER IF EXISTS trg_auditoria ON %I.%I;

            CREATE TRIGGER trg_auditoria

            AFTER INSERT OR UPDATE OR DELETE
            ON %I.%I

            FOR EACH ROW

            EXECUTE FUNCTION auditoria.fn_auditoria_dml();
            ',

            r.schemaname,
            r.tablename,

            r.schemaname,
            r.tablename

        );

    END LOOP;

END;
$$;


ALTER FUNCTION auditoria.fn_instalar_auditoria() OWNER TO postgres;

