--
-- Name: fn_correo_a_pendiente(); Type: FUNCTION; Schema: modulo1; Owner: postgres
--

CREATE FUNCTION modulo1.fn_correo_a_pendiente() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.correo_electronico IS DISTINCT FROM NEW.correo_electronico THEN
        UPDATE modulo1.cuentas_usuarios
        SET id_estado_cuenta = 1
        WHERE id_usuario = NEW.id_usuario;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo1.fn_correo_a_pendiente() OWNER TO postgres;

--
-- Name: sp_actualizar_usuario(integer, integer, character varying, character varying, character varying, character varying, integer, integer, integer); Type: PROCEDURE; Schema: modulo1; Owner: postgres
--

CREATE PROCEDURE modulo1.sp_actualizar_usuario(IN p_id_actor integer, IN p_id_usuario integer, IN p_nombres character varying, IN p_apellidos character varying, IN p_correo_electronico character varying, IN p_telefono character varying, IN p_id_estado_cuenta integer, IN p_id_rol integer, IN p_version integer)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_es_admin BOOLEAN := FALSE;
    v_correo_actual VARCHAR;
    v_old_data JSONB;
BEGIN
    -- 1. Autoprotección del administrador
    IF p_id_actor = p_id_usuario AND (p_id_rol IS NOT NULL OR p_id_estado_cuenta IS NOT NULL) THEN
        RAISE EXCEPTION 'Operación denegada: Un administrador no puede modificar su propio rol ni cambiar su estado para evitar pérdida de privilegios.';
    END IF;

    -- Verificar si el actor es administrador
    SELECT EXISTS (
        SELECT 1 FROM modulo1.usuarios u 
        JOIN modulo1.roles r ON u.id_rol = r.id_rol 
        WHERE u.id_usuario = p_id_actor AND r.nombre_rol ILIKE '%Administrador%'
    ) INTO v_es_admin;

    -- Validar permisos de actor
    IF NOT v_es_admin AND p_id_actor != p_id_usuario THEN
        RAISE EXCEPTION 'Acceso restringido. No tiene permisos para modificar este usuario.';
    END IF;

    IF NOT v_es_admin AND (p_id_estado_cuenta IS NOT NULL OR p_id_rol IS NOT NULL) THEN
        RAISE EXCEPTION 'Acceso restringido. No tiene permisos para modificar campos críticos (Rol/Estado).';
    END IF;

    -- 2. Control de concurrencia optimista
    IF NOT EXISTS (SELECT 1 FROM modulo1.usuarios WHERE id_usuario = p_id_usuario AND version = p_version) THEN
        RAISE EXCEPTION 'Conflicto de actualización: El registro ha sido modificado por otro usuario o la versión proporcionada es incorrecta.';
    END IF;

    -- Validar formato
    IF p_nombres !~ '^[a-zA-ZáéíóúÁÉÍÓÚñÑ ]+$' OR p_apellidos !~ '^[a-zA-ZáéíóúÁÉÍÓÚñÑ ]+$' THEN
        RAISE EXCEPTION 'Error de formato. Los nombres y apellidos solo deben contener letras y espacios.';
    END IF;

    IF p_telefono IS NOT NULL AND p_telefono !~ '^[0-9]+$' THEN
        RAISE EXCEPTION 'Número telefónico inválido. Asegúrese de ingresar solo dígitos numéricos.';
    END IF;

    IF EXISTS (SELECT 1 FROM modulo1.usuarios WHERE correo_electronico = p_correo_electronico AND id_usuario != p_id_usuario) THEN
        RAISE EXCEPTION 'La dirección % ya se encuentra vinculada a otra cuenta.', p_correo_electronico;
    END IF;

    -- Capturar datos ANTES de actualizar
    SELECT row_to_json(u)::JSONB INTO v_old_data 
    FROM modulo1.usuarios u 
    WHERE u.id_usuario = p_id_usuario;

    SELECT correo_electronico INTO v_correo_actual 
    FROM modulo1.usuarios 
    WHERE id_usuario = p_id_usuario;

    -- Actualizar usuario (versión manejada por trigger)
    UPDATE modulo1.usuarios
    SET nombre = p_nombres,
        apellidos = p_apellidos,
        correo_electronico = p_correo_electronico,
        telefono = p_telefono,
        id_rol = COALESCE(p_id_rol, id_rol),
        fecha_actualizacion = CURRENT_TIMESTAMP
    WHERE id_usuario = p_id_usuario;

    -- Si cambió el correo: solo invalidar verificación, NO forzar estado Pendiente
    -- (el trigger trg_fn_validar_transicion_estado prohíbe Activo → Pendiente)
    IF v_correo_actual IS DISTINCT FROM p_correo_electronico THEN
        UPDATE modulo1.cuentas_usuarios
        SET tiene_correo_verificado = FALSE
        WHERE id_usuario = p_id_usuario;
    END IF;

    -- Actualizar estado de cuenta solo si se envió explícitamente (y el actor tiene permiso)
    IF p_id_estado_cuenta IS NOT NULL THEN
        UPDATE modulo1.cuentas_usuarios
        SET id_estado_cuenta = p_id_estado_cuenta,
            fecha_cambio_estado = CURRENT_TIMESTAMP,
            motivo_ultimo_cambio = 'Actualización administrativa por usuario ' || p_id_actor
        WHERE id_usuario = p_id_usuario;
    END IF;

    -- Auditoría
    CALL modulo1.sp_registrar_auditoria(
        p_id_actor,
        NULL,
        4,
        'Modulo 1',
        'ADMINISTRACION',
        'Actualización de datos del usuario ' || p_id_usuario,
        'exitoso',
        'activo',
        jsonb_build_object(
            'old_data', v_old_data,
            'new_data', jsonb_build_object(
                'nombres', p_nombres,
                'apellidos', p_apellidos,
                'correo', p_correo_electronico,
                'telefono', p_telefono,
                'id_rol', p_id_rol,
                'id_estado_cuenta', p_id_estado_cuenta
            )
        )
    );

EXCEPTION
    WHEN OTHERS THEN
        RAISE;
END;
$_$;


ALTER PROCEDURE modulo1.sp_actualizar_usuario(IN p_id_actor integer, IN p_id_usuario integer, IN p_nombres character varying, IN p_apellidos character varying, IN p_correo_electronico character varying, IN p_telefono character varying, IN p_id_estado_cuenta integer, IN p_id_rol integer, IN p_version integer) OWNER TO postgres;

--
-- Name: sp_crear_rol(character varying, character varying, jsonb); Type: PROCEDURE; Schema: modulo1; Owner: postgres
--

CREATE PROCEDURE modulo1.sp_crear_rol(IN p_nombre_rol character varying, IN p_descripcion character varying, IN p_permisos jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_rol INT;
    v_permiso JSONB;
    v_recurso_id INT;
    v_accion_id INT;
BEGIN
    -- Validar nombre único
    IF EXISTS (SELECT 1 FROM modulo1.roles WHERE nombre_rol = p_nombre_rol) THEN
        RAISE EXCEPTION 'Conflicto de identidad: El nombre de rol % ya se encuentra registrado.', p_nombre_rol;
    END IF;

    -- Validar que tenga al menos un permiso
    IF p_permisos IS NULL OR jsonb_array_length(p_permisos) = 0 THEN
        RAISE EXCEPTION 'Operación rechazada: Todo rol debe poseer al menos un permiso asociado.';
    END IF;

    -- Insertar rol
    INSERT INTO modulo1.roles (nombre_rol, descripcion, es_protegido)
    VALUES (p_nombre_rol, p_descripcion, FALSE)
    RETURNING id_rol INTO v_id_rol;

    -- Asignar permisos con validación de existencia
    FOR v_permiso IN SELECT * FROM jsonb_array_elements(p_permisos)
    LOOP
        v_recurso_id := (v_permiso->>'id_recurso')::INT;
        v_accion_id := (v_permiso->>'id_accion')::INT;

        IF NOT EXISTS (SELECT 1 FROM modulo1.recursos WHERE id_recurso = v_recurso_id) THEN
            RAISE EXCEPTION 'Recurso con id % no existe', v_recurso_id;
        END IF;

        IF NOT EXISTS (SELECT 1 FROM modulo1.acciones WHERE id_accion = v_accion_id) THEN
            RAISE EXCEPTION 'Acción con id % no existe', v_accion_id;
        END IF;

        INSERT INTO modulo1.permisos (
            nombre, descripcion, id_rol, id_recurso, id_accion
        ) VALUES (
            p_nombre_rol || '_permiso_' || v_recurso_id || '_' || v_accion_id,
            'Permiso asignado al rol ' || p_nombre_rol,
            v_id_rol,
            v_recurso_id,
            v_accion_id
        );
    END LOOP;

    -- COMMIT;  ← ELIMINADO: no se permite dentro de bloque con EXCEPTION
EXCEPTION
    WHEN OTHERS THEN
        -- ROLLBACK;  ← ELIMINADO: el RAISE relanza el error y el llamador debe hacer ROLLBACK
        RAISE;
END;
$$;


ALTER PROCEDURE modulo1.sp_crear_rol(IN p_nombre_rol character varying, IN p_descripcion character varying, IN p_permisos jsonb) OWNER TO postgres;

--
-- Name: sp_registrar_auditoria(integer, integer, integer, character varying, character varying, text, modulo1.enum_evento_resultado, character varying, jsonb); Type: PROCEDURE; Schema: modulo1; Owner: postgres
--

CREATE PROCEDURE modulo1.sp_registrar_auditoria(IN p_id_usuario integer, IN p_id_sesion integer, IN p_id_tipo_evento integer, IN p_modulo character varying, IN p_categoria character varying, IN p_descripcion text, IN p_resultado modulo1.enum_evento_resultado, IN p_estado character varying, IN p_detalle jsonb)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_fecha_actual TIMESTAMP := CURRENT_TIMESTAMP;
    v_hash_data TEXT;
    v_direccion_ip VARCHAR(45);
    v_user_agent VARCHAR(255);
    v_tiene_sesion_cols BOOLEAN := FALSE;
    v_tiene_hash_col BOOLEAN := FALSE;
    v_sql TEXT;
BEGIN
    -- Detectar si existen las columnas extendidas (para compatibilidad)
    SELECT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'modulo1' AND table_name = 'eventos' AND column_name = 'id_sesion'
    ) INTO v_tiene_sesion_cols;

    SELECT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'modulo1' AND table_name = 'eventos' AND column_name = 'hash_integridad'
    ) INTO v_tiene_hash_col;

    -- Obtener datos de sesión si existe la columna y el id_sesion es válido
    IF v_tiene_sesion_cols AND p_id_sesion IS NOT NULL THEN
        SELECT direccion_ip, agente_usuario 
        INTO v_direccion_ip, v_user_agent
        FROM modulo1.sesiones 
        WHERE id_sesion = p_id_sesion;
    END IF;

    -- Validar existencia de usuario
    IF NOT EXISTS (SELECT 1 FROM modulo1.usuarios WHERE id_usuario = p_id_usuario) THEN
        RAISE EXCEPTION 'Error de auditoría: El usuario especificado no existe.';
    END IF;

    -- Preparar detalle extendido
    p_detalle := p_detalle || jsonb_build_object(
        'direccion_ip', COALESCE(v_direccion_ip, 'no_disponible'),
        'user_agent', COALESCE(v_user_agent, 'no_disponible')
    );

    -- Construir INSERT dinámico según columnas disponibles
    IF v_tiene_sesion_cols AND v_tiene_hash_col THEN
        -- Versión extendida con hash de integridad
        v_hash_data := COALESCE(p_id_usuario::TEXT, '0') || '|' || 
                       COALESCE(p_id_tipo_evento::TEXT, '0') || '|' || 
                       COALESCE(p_modulo, '') || '|' || 
                       v_fecha_actual::TEXT || '|' || 
                       COALESCE(p_resultado::TEXT, '');

        INSERT INTO modulo1.eventos (
            tipo_evento, descripcion, fecha_evento, modulo, 
            resultado, detalle, id_usuario, categoria, estado,
            id_sesion, hash_integridad
        ) VALUES (
            p_id_tipo_evento, p_descripcion, v_fecha_actual, p_modulo, 
            p_resultado, p_detalle, p_id_usuario, p_categoria, p_estado,
            p_id_sesion,
			encode(modulo1.digest(v_hash_data::bytea, 'sha256'), 'hex')
        );
    ELSIF v_tiene_sesion_cols THEN
        -- Solo columna id_sesion extra
        INSERT INTO modulo1.eventos (
            tipo_evento, descripcion, fecha_evento, modulo, 
            resultado, detalle, id_usuario, categoria, estado,
            id_sesion
        ) VALUES (
            p_id_tipo_evento, p_descripcion, v_fecha_actual, p_modulo, 
            p_resultado, p_detalle, p_id_usuario, p_categoria, p_estado,
            p_id_sesion
        );
    ELSE
        -- Estructura básica (tu esquema actual)
        INSERT INTO modulo1.eventos (
            tipo_evento, descripcion, fecha_evento, modulo, 
            resultado, detalle, id_usuario, categoria, estado
        ) VALUES (
            p_id_tipo_evento, p_descripcion, v_fecha_actual, p_modulo, 
            p_resultado, p_detalle, p_id_usuario, p_categoria, p_estado
        );
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RAISE;
END;
$$;


ALTER PROCEDURE modulo1.sp_registrar_auditoria(IN p_id_usuario integer, IN p_id_sesion integer, IN p_id_tipo_evento integer, IN p_modulo character varying, IN p_categoria character varying, IN p_descripcion text, IN p_resultado modulo1.enum_evento_resultado, IN p_estado character varying, IN p_detalle jsonb) OWNER TO postgres;

--
-- Name: sp_registrar_usuario(character varying, character varying, character varying, character varying, date, modulo1.enum_usuario_genero, character varying, character varying, character varying, character varying); Type: PROCEDURE; Schema: modulo1; Owner: postgres
--

CREATE PROCEDURE modulo1.sp_registrar_usuario(IN p_tipo_identificacion character varying, IN p_numero_identificacion character varying, IN p_nombres character varying, IN p_apellidos character varying, IN p_fecha_nacimiento date, IN p_genero modulo1.enum_usuario_genero, IN p_correo_electronico character varying, IN p_contrasena_cifrada character varying, IN p_telefono character varying, IN p_direccion character varying)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_id_rol INT;
    v_id_usuario INT;
    v_id_estado_pendiente INT;
BEGIN
    -- Validaciones de formato
    IF p_nombres !~ '^[a-zA-ZáéíóúÁÉÍÓÚñÑ ]+$'
       OR p_apellidos !~ '^[a-zA-ZáéíóúÁÉÍÓÚñÑ ]+$' THEN
        RAISE EXCEPTION 'Formato inválido en nombres o apellidos';
    END IF;

    IF p_correo_electronico !~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$' THEN
        RAISE EXCEPTION 'Correo inválido';
    END IF;

    IF EXTRACT(YEAR FROM age(CURRENT_DATE, p_fecha_nacimiento)) < 18 THEN
        RAISE EXCEPTION 'Debe ser mayor de 18 años';
    END IF;

    IF EXISTS (SELECT 1 FROM modulo1.usuarios WHERE correo_electronico = p_correo_electronico) THEN
        RAISE EXCEPTION 'Correo ya registrado';
    END IF;

    IF EXISTS (SELECT 1 FROM modulo1.usuarios WHERE numero_identificacion = p_numero_identificacion) THEN
        RAISE EXCEPTION 'Identificación ya registrada';
    END IF;

    -- Obtener rol Productor (o el primer rol disponible)
    SELECT id_rol INTO v_id_rol
    FROM modulo1.roles
    WHERE nombre_rol ILIKE 'Productor'
    LIMIT 1;

    IF v_id_rol IS NULL THEN
        SELECT id_rol INTO v_id_rol FROM modulo1.roles ORDER BY id_rol LIMIT 1;
    END IF;

    IF v_id_rol IS NULL THEN
        RAISE EXCEPTION 'No existe ningún rol configurado en el sistema';
    END IF;

    -- Insertar usuario (version, fecha_registro y fecha_actualizacion tienen DEFAULT)
    INSERT INTO modulo1.usuarios (
        tipo_identificacion,
        numero_identificacion,
        nombre,
        apellidos,
        fecha_nacimiento,
        genero,
        correo_electronico,
        contrasena_cifrada,
        telefono,
        direccion,
        id_rol
    )
    VALUES (
        p_tipo_identificacion,
        p_numero_identificacion,
        p_nombres,
        p_apellidos,
        p_fecha_nacimiento,
        p_genero,
        p_correo_electronico,
        p_contrasena_cifrada,
        p_telefono,
        p_direccion,
        v_id_rol
    )
    RETURNING id_usuario INTO v_id_usuario;

    -- Obtener estado PENDIENTE
    SELECT id_estado_cuenta INTO v_id_estado_pendiente
    FROM modulo1.estados_cuentas
    WHERE nombre ILIKE '%PENDIENTE%'
    LIMIT 1;

    IF v_id_estado_pendiente IS NULL THEN
        v_id_estado_pendiente := 1;
    END IF;

    -- Crear cuenta de usuario
    INSERT INTO modulo1.cuentas_usuarios (
        id_usuario,
        id_estado_cuenta,
        tiene_correo_verificado
    )
    VALUES (
        v_id_usuario,
        v_id_estado_pendiente,
        FALSE
    );

    -- Auditoría (sin sesión activa en registro)
    CALL modulo1.sp_registrar_auditoria(
        v_id_usuario,
        NULL,
        1,
        'Modulo 1',
        'AUTENTICACION',
        'Registro usuario: ' || p_correo_electronico,
        'exitoso',
        'pendiente',
        jsonb_build_object(
            'id_usuario', v_id_usuario,
            'correo', p_correo_electronico,
            'rol', v_id_rol
        )
    );

EXCEPTION
    WHEN OTHERS THEN
        RAISE;
END;
$_$;


ALTER PROCEDURE modulo1.sp_registrar_usuario(IN p_tipo_identificacion character varying, IN p_numero_identificacion character varying, IN p_nombres character varying, IN p_apellidos character varying, IN p_fecha_nacimiento date, IN p_genero modulo1.enum_usuario_genero, IN p_correo_electronico character varying, IN p_contrasena_cifrada character varying, IN p_telefono character varying, IN p_direccion character varying) OWNER TO postgres;

--
-- Name: trg_fn_bloquear_eliminacion_rol_en_uso(); Type: FUNCTION; Schema: modulo1; Owner: postgres
--

CREATE FUNCTION modulo1.trg_fn_bloquear_eliminacion_rol_en_uso() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_count
    FROM modulo1.usuarios
    WHERE id_rol = OLD.id_rol;

    IF v_count > 0 THEN
        RAISE EXCEPTION 'ROLE_IN_USE'
            USING ERRCODE = 'P0005';
    END IF;

    RETURN OLD;
END;
$$;


ALTER FUNCTION modulo1.trg_fn_bloquear_eliminacion_rol_en_uso() OWNER TO postgres;

--
-- Name: trg_fn_fcm_limpiar_caducados(); Type: FUNCTION; Schema: modulo1; Owner: postgres
--

CREATE FUNCTION modulo1.trg_fn_fcm_limpiar_caducados() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM modulo1.dispositivos_fcm
    WHERE id_usuario = NEW.id_usuario AND ultimo_uso < now() - INTERVAL '30 days';
    RETURN NEW;
END; $$;


ALTER FUNCTION modulo1.trg_fn_fcm_limpiar_caducados() OWNER TO postgres;

