--

CREATE FUNCTION modulo1.trg_fn_incrementar_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.version             := OLD.version + 1;
    NEW.fecha_actualizacion := now();
    RETURN NEW;
END;
$$;


