-- Name: trg_fn_invalidar_sesiones_por_estado(); Type: FUNCTION; Schema: modulo1; Owner: postgres
--

CREATE FUNCTION modulo1.trg_fn_invalidar_sesiones_por_estado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
            IF NEW.id_estado_cuenta <> OLD.id_estado_cuenta THEN
                UPDATE modulo1.sesiones
                SET es_activa = FALSE
                WHERE id_cuenta_usuario = NEW.id_cuenta_usuario;
            END IF;
            RETURN NEW;
        END;
        $$;


