-- Name: trg_fn_proteger_auditoria(); Type: FUNCTION; Schema: modulo1; Owner: postgres
--

CREATE FUNCTION modulo1.trg_fn_proteger_auditoria() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'IMMUTABLE_RECORD: Los registros de auditoría no pueden ser modificados ni eliminados. Operación bloqueada: %', TG_OP
        USING ERRCODE = 'P0002';
