--
-- Name: trg_fn_proteger_estado_cuenta_admin(); Type: FUNCTION; Schema: modulo1; Owner: postgres
--

CREATE FUNCTION modulo1.trg_fn_proteger_estado_cuenta_admin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_es_protegido BOOLEAN;
    v_nombre_rol   VARCHAR(100);
BEGIN
    IF NEW.id_estado_cuenta = OLD.id_estado_cuenta THEN
        RETURN NEW;
    END IF;

    SELECT r.es_protegido, r.nombre_rol
      INTO v_es_protegido, v_nombre_rol
      FROM modulo1.usuarios  u
      JOIN modulo1.roles     r ON r.id_rol = u.id_rol
     WHERE u.id_usuario = NEW.id_usuario;

    IF v_es_protegido = TRUE THEN
        RAISE EXCEPTION
            'PROTECTED_ADMIN: No se puede cambiar el estado de la cuenta del usuario con rol protegido "%".',
            v_nombre_rol
            USING ERRCODE = 'P0004';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo1.trg_fn_proteger_estado_cuenta_admin() OWNER TO postgres;

--
-- Name: trg_fn_proteger_permisos_admin_delete(); Type: FUNCTION; Schema: modulo1; Owner: postgres
--

CREATE FUNCTION modulo1.trg_fn_proteger_permisos_admin_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Si el nombre del permiso comienza con "admin_"
    IF OLD.nombre ILIKE 'admin_%' THEN
        RAISE EXCEPTION
            'ADMIN_PERM_NO_DELETE: El permiso administrativo "%" no puede ser eliminado del sistema. Los permisos administrativos son registros permanentes e inmutables. Si desea desactivar un permiso, contacte al administrador del sistema con justificación de negocio.',
            OLD.nombre
        USING ERRCODE = 'P0204';
    END IF;

    RETURN OLD;
END;
$$;


ALTER FUNCTION modulo1.trg_fn_proteger_permisos_admin_delete() OWNER TO postgres;

--
-- Name: trg_fn_proteger_permisos_admin_insert(); Type: FUNCTION; Schema: modulo1; Owner: postgres
--

CREATE FUNCTION modulo1.trg_fn_proteger_permisos_admin_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_nombre_rol VARCHAR(100);
    v_es_admin   BOOLEAN;
BEGIN
    -- Si el nombre del permiso comienza con "admin_"
    IF NEW.nombre ILIKE 'admin_%' THEN
        -- Validar que el rol sea el rol "admin"
        SELECT nombre_rol
        INTO   v_nombre_rol
        FROM   modulo1.roles
        WHERE  id_rol = NEW.id_rol;

        IF v_nombre_rol IS NULL THEN
            RAISE EXCEPTION
                'ADMIN_PERM_INVALID_ROLE: Intento de asignar permiso administrativo a un rol inexistente (ID: %).',
                NEW.id_rol
            USING ERRCODE = 'P0201';
        END IF;

        v_es_admin := (v_nombre_rol ILIKE '%Administrador%' OR v_nombre_rol = 'admin');

        IF NOT v_es_admin THEN
            RAISE EXCEPTION
                'ADMIN_PERM_ROLE_MISMATCH: Permiso administrativo "%" solo puede asignarse al rol "Administrador", no a "%".',
                NEW.nombre, v_nombre_rol
            USING ERRCODE = 'P0202';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo1.trg_fn_proteger_permisos_admin_insert() OWNER TO postgres;

--
-- Name: trg_fn_proteger_permisos_admin_update(); Type: FUNCTION; Schema: modulo1; Owner: postgres
--

CREATE FUNCTION modulo1.trg_fn_proteger_permisos_admin_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_es_admin_perm BOOLEAN;
BEGIN
    -- Detectar si es un permiso administrativo (por nombre)
    v_es_admin_perm := (OLD.nombre ILIKE 'admin_%');

    IF v_es_admin_perm THEN
        -- No se permite cambiar NADA en un permiso admin
        IF OLD.nombre           IS DISTINCT FROM NEW.nombre
           OR OLD.descripcion   IS DISTINCT FROM NEW.descripcion
           OR OLD.id_rol        IS DISTINCT FROM NEW.id_rol
           OR OLD.id_recurso    IS DISTINCT FROM NEW.id_recurso
           OR OLD.id_accion     IS DISTINCT FROM NEW.id_accion
           OR OLD.es_activo     IS DISTINCT FROM NEW.es_activo
        THEN
            RAISE EXCEPTION
                'ADMIN_PERM_IMMUTABLE: El permiso administrativo "%" es completamente inmutable. No se puede modificar ninguno de sus atributos. Contacte al administrador del sistema si requiere cambios.',
                OLD.nombre
            USING ERRCODE = 'P0203';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo1.trg_fn_proteger_permisos_admin_update() OWNER TO postgres;

--
-- Name: trg_fn_proteger_permisos_rol_admin(); Type: FUNCTION; Schema: modulo1; Owner: postgres
--

CREATE FUNCTION modulo1.trg_fn_proteger_permisos_rol_admin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_es_protegido BOOLEAN;
    v_nombre_rol   VARCHAR(100);
    v_id_rol       INTEGER;
BEGIN
    -- En DELETE usamos OLD; en UPDATE también OLD (el rol no cambia en un permiso)
    IF TG_OP = 'DELETE' THEN
        v_id_rol := OLD.id_rol;
    ELSE
        v_id_rol := OLD.id_rol;
    END IF;

    SELECT es_protegido, nombre_rol
      INTO v_es_protegido, v_nombre_rol
      FROM modulo1.roles
     WHERE id_rol = v_id_rol;

    IF v_es_protegido = TRUE THEN
        RAISE EXCEPTION
            'PROTECTED_ADMIN: Los permisos del rol protegido "%" no pueden ser modificados ni eliminados. Operación bloqueada: %.',
            v_nombre_rol, TG_OP
            USING ERRCODE = 'P0004';
    END IF;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo1.trg_fn_proteger_permisos_rol_admin() OWNER TO postgres;

--
-- Name: trg_fn_proteger_reasignacion_rol_admin(); Type: FUNCTION; Schema: modulo1; Owner: postgres
--

CREATE FUNCTION modulo1.trg_fn_proteger_reasignacion_rol_admin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_es_protegido BOOLEAN;
    v_nombre_rol   VARCHAR(100);
BEGIN
    IF NEW.id_rol = OLD.id_rol THEN
        RETURN NEW;
    END IF;

    SELECT es_protegido, nombre_rol
      INTO v_es_protegido, v_nombre_rol
      FROM modulo1.roles
     WHERE id_rol = OLD.id_rol;

    IF v_es_protegido = TRUE THEN
        RAISE EXCEPTION
            'PROTECTED_ADMIN: No se puede cambiar el rol del usuario porque su rol actual "%" es protegido.',
            v_nombre_rol
            USING ERRCODE = 'P0004';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo1.trg_fn_proteger_reasignacion_rol_admin() OWNER TO postgres;

--
-- Name: trg_fn_proteger_rol_admin(); Type: FUNCTION; Schema: modulo1; Owner: postgres
--

CREATE FUNCTION modulo1.trg_fn_proteger_rol_admin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' AND OLD.es_protegido = TRUE THEN
        RAISE EXCEPTION 'PROTECTED_ROLE: Rol protegido.'
            USING ERRCODE = 'P0004';
    END IF;

    IF TG_OP = 'UPDATE' AND OLD.es_protegido = TRUE AND NEW.nombre_rol <> OLD.nombre_rol THEN
        RAISE EXCEPTION 'PROTECTED_ROLE: No se puede modificar.'
            USING ERRCODE = 'P0004';
    END IF;

    IF TG_OP = 'UPDATE' AND OLD.es_protegido = TRUE AND NEW.es_protegido = FALSE THEN
        RAISE EXCEPTION 'PROTECTED_ROLE: No se puede desproteger.'
            USING ERRCODE = 'P0004';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo1.trg_fn_proteger_rol_admin() OWNER TO postgres;

--
-- Name: trg_fn_reset_intentos_al_activar(); Type: FUNCTION; Schema: modulo1; Owner: postgres
--

CREATE FUNCTION modulo1.trg_fn_reset_intentos_al_activar() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.id_estado_cuenta <> OLD.id_estado_cuenta
       AND NEW.id_estado_cuenta = (
           SELECT id_estado_cuenta
           FROM modulo1.estados_cuentas
           WHERE nombre = 'Activo'
       )
    THEN
        NEW.intentos_fallidos := 0;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo1.trg_fn_reset_intentos_al_activar() OWNER TO postgres;

