--
-- Name: trg_fn_validar_intentos_no_negativos(); Type: FUNCTION; Schema: modulo1; Owner: postgres
--

CREATE FUNCTION modulo1.trg_fn_validar_intentos_no_negativos() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.intentos_fallidos < 0 THEN
        RAISE EXCEPTION 'INVALID_STATE: intentos_fallidos no puede ser negativo'
            USING ERRCODE = 'P0007';
    END IF;

    RETURN NEW;
END;
