ALTER FUNCTION modulo1.trg_fn_validar_intentos_no_negativos() OWNER TO postgres;

--
-- Name: trg_fn_validar_permiso_minimo_rol(); Type: FUNCTION; Schema: modulo1; Owner: postgres
--

CREATE FUNCTION modulo1.trg_fn_validar_permiso_minimo_rol() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_count
    FROM modulo1.permisos
    WHERE id_rol = OLD.id_rol
      AND id_permiso <> OLD.id_permiso
      AND es_activo = TRUE;

    IF v_count = 0 THEN
        RAISE EXCEPTION
            'MIN_PERMISSION: No se puede eliminar el ultimo permiso activo.'
            USING ERRCODE = 'P0006';
    END IF;

    RETURN OLD;
END;
$$;


ALTER FUNCTION modulo1.trg_fn_validar_permiso_minimo_rol() OWNER TO postgres;

--
-- Name: trg_fn_validar_permiso_minimo_rol_update(); Type: FUNCTION; Schema: modulo1; Owner: postgres
--

CREATE FUNCTION modulo1.trg_fn_validar_permiso_minimo_rol_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    IF OLD.es_activo = TRUE AND NEW.es_activo = FALSE THEN

        SELECT COUNT(*) INTO v_count
        FROM modulo1.permisos
        WHERE id_rol = OLD.id_rol
          AND id_permiso <> OLD.id_permiso
          AND es_activo = TRUE;

        IF v_count = 0 THEN
            RAISE EXCEPTION 'MIN_PERMISSION: No se puede desactivar el último permiso activo.'
                USING ERRCODE = 'P0006';
        END IF;

    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo1.trg_fn_validar_permiso_minimo_rol_update() OWNER TO postgres;

--
-- Name: trg_fn_validar_transicion_estado(); Type: FUNCTION; Schema: modulo1; Owner: postgres
--

CREATE FUNCTION modulo1.trg_fn_validar_transicion_estado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado_origen  VARCHAR(55);
    v_estado_destino VARCHAR(55);
BEGIN
    IF NEW.id_estado_cuenta = OLD.id_estado_cuenta THEN
        RETURN NEW;
    END IF;

    SELECT nombre INTO v_estado_origen
    FROM modulo1.estados_cuentas WHERE id_estado_cuenta = OLD.id_estado_cuenta;

    SELECT nombre INTO v_estado_destino
    FROM modulo1.estados_cuentas WHERE id_estado_cuenta = NEW.id_estado_cuenta;

    IF v_estado_origen = 'Eliminado' THEN
        RAISE EXCEPTION 'INVALID_TRANSITION: Una cuenta Eliminada no puede cambiar a %.', v_estado_destino
            USING ERRCODE = 'P0003';
    END IF;

    IF NOT (
        (v_estado_origen = 'Pendiente' AND v_estado_destino IN ('Activo', 'Eliminado'))
        OR (v_estado_origen = 'Activo'    AND v_estado_destino IN ('Pendiente', 'Inactivo', 'Bloqueado', 'Eliminado'))
        OR (v_estado_origen = 'Inactivo'  AND v_estado_destino IN ('Activo', 'Eliminado'))
        OR (v_estado_origen = 'Bloqueado' AND v_estado_destino IN ('Activo', 'Inactivo', 'Eliminado'))
        OR (v_estado_origen = 'Pendiente Datos' AND v_estado_destino IN ('Activo', 'Eliminado'))
    ) THEN
        RAISE EXCEPTION 'INVALID_TRANSITION: Transición no permitida (% → %).', v_estado_origen, v_estado_destino
            USING ERRCODE = 'P0003';
    END IF;

    NEW.fecha_cambio_estado := now();
    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo1.trg_fn_validar_transicion_estado() OWNER TO postgres;

--
-- Name: fn_obtener_estado_actual_activo(integer); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.fn_obtener_estado_actual_activo(p_activo_id integer) RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_id_estado INT;
BEGIN
    -- Prioridad: último registro en el historial de estados
    SELECT id_estado_nuevo
    INTO   v_id_estado
    FROM   modulo2.historicos_estados_activos
    WHERE  id_activo_biologico = p_activo_id
    ORDER  BY fecha_cambio DESC, id_historico_estado_activo DESC
    LIMIT  1;

    -- Fallback: estado directo en activos_biologicos
    IF v_id_estado IS NULL THEN
        SELECT id_estado
        INTO   v_id_estado
        FROM   modulo2.activos_biologicos
        WHERE  id_activo_biologico = p_activo_id;
    END IF;

    RETURN v_id_estado;
END;
$$;


ALTER FUNCTION modulo2.fn_obtener_estado_actual_activo(p_activo_id integer) OWNER TO postgres;

--
-- Name: fn_obtener_fase_activa_activo(integer); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.fn_obtener_fase_activa_activo(p_activo_id integer) RETURNS TABLE(id_gestion_fases integer, id_ciclo_productiva integer, fecha_inicio time with time zone, fecha_finalizacion timestamp with time zone, es_activa boolean)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT gf.id_gestion_fases,
           gf.id_ciclo_productiva,
           gf.fecha_inicio,
           gf.fecha_finalizacion,
           gf.es_activa
    FROM   modulo2.gestiones_fases gf
    WHERE  gf.id_activo_biologico = p_activo_id
      AND  gf.es_activa = TRUE
    LIMIT 1;
END;
$$;


ALTER FUNCTION modulo2.fn_obtener_fase_activa_activo(p_activo_id integer) OWNER TO postgres;

--
-- Name: sp_calcular_indicadores_zootecnicos(integer, modulo2.enum_indicador_zootecnico_tipo, date, date, jsonb, integer); Type: PROCEDURE; Schema: modulo2; Owner: postgres
--

CREATE PROCEDURE modulo2.sp_calcular_indicadores_zootecnicos(IN p_activo_id integer, IN p_tipo_indicador modulo2.enum_indicador_zootecnico_tipo, IN p_fecha_inicio date, IN p_fecha_fin date, IN p_parametros jsonb, IN p_usuario_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tipo_activo     modulo2.enum_activo_biologico_tipo;
    v_dias            INT;
    v_peso_inicial    NUMERIC;
    v_peso_final      NUMERIC;
    v_total_eventos   INT;
    v_cantidad_base   INT;
    v_consumo_total   NUMERIC;
    v_ganancia_total  NUMERIC;
    v_resultado       NUMERIC;
    v_params_calc     JSONB;
BEGIN
    -- Validar existencia del activo y obtener tipo
    SELECT tipo
    INTO   v_tipo_activo
    FROM   modulo2.activos_biologicos
    WHERE  id_activo_biologico = p_activo_id;

    IF v_tipo_activo IS NULL THEN
        RAISE EXCEPTION
            'El activo biológico con ID % no existe.', p_activo_id;
    END IF;

    -- Validar rango de fechas
    IF p_fecha_inicio > p_fecha_fin THEN
        RAISE EXCEPTION
            'La fecha de inicio debe ser anterior a la fecha de fin.';
    END IF;

    v_dias := p_fecha_fin - p_fecha_inicio;
    IF v_dias = 0 THEN
        RAISE EXCEPTION
            'El rango de fechas debe ser mayor a un día.';
    END IF;

    -- -----------------------------------------------------------------------
    CASE p_tipo_indicador

        WHEN 'ganancia_peso' THEN
            -- Primer peso registrado en el rango
            SELECT ec.valor_medicion
            INTO   v_peso_inicial
            FROM   modulo2.eventos_activos ea
            JOIN   modulo2.eventos_crecimeinto ec ON ec.id_evento = ea.id_eventos
            WHERE  ea.id_activo_biologico = p_activo_id
              AND  UPPER(ec.tipo_medicion) LIKE '%PESO%'
              AND  DATE(ea.fecha) BETWEEN p_fecha_inicio AND p_fecha_fin
            ORDER  BY ea.fecha ASC
            LIMIT  1;

            -- Último peso registrado en el rango
            SELECT ec.valor_medicion
            INTO   v_peso_final
            FROM   modulo2.eventos_activos ea
            JOIN   modulo2.eventos_crecimeinto ec ON ec.id_evento = ea.id_eventos
            WHERE  ea.id_activo_biologico = p_activo_id
              AND  UPPER(ec.tipo_medicion) LIKE '%PESO%'
              AND  DATE(ea.fecha) BETWEEN p_fecha_inicio AND p_fecha_fin
            ORDER  BY ea.fecha DESC
            LIMIT  1;

            IF v_peso_inicial IS NULL OR v_peso_final IS NULL THEN
                RAISE EXCEPTION
                    'No hay suficientes registros de peso para calcular la ganancia '
                    'en el rango especificado (mínimo 2 mediciones).';
            END IF;

            v_resultado   := (v_peso_final - v_peso_inicial) / v_dias;
            v_params_calc := jsonb_build_object(
                'peso_inicial',   v_peso_inicial,
                'peso_final',     v_peso_final,
                'dias',           v_dias,
                'ganancia_diaria', v_resultado,
                'unidad',         'kg/dia'
            );

        WHEN 'tasa_morbilidad' THEN
            SELECT COUNT(*)
            INTO   v_total_eventos
            FROM   modulo2.eventos_activos ea
            JOIN   modulo2.eventos_sanitarios es ON es.id_evento = ea.id_eventos
            WHERE  ea.id_activo_biologico = p_activo_id
              AND  DATE(ea.fecha) BETWEEN p_fecha_inicio AND p_fecha_fin;

            IF v_tipo_activo = 'POBLACIONAL' THEN
                SELECT cantidad_inicial
                INTO   v_cantidad_base
                FROM   modulo2.detalles_activos_biologicos_poblacionales
                WHERE  id_activo_biologico = p_activo_id;
            ELSE
                v_cantidad_base := 1;
            END IF;

            IF v_cantidad_base IS NULL OR v_cantidad_base = 0 THEN
                RAISE EXCEPTION
                    'No se puede calcular la tasa de morbilidad: '
                    'cantidad base es cero o nula.';
            END IF;

            v_resultado   := (v_total_eventos::NUMERIC / v_cantidad_base) * 100;
            v_params_calc := jsonb_build_object(
                'eventos_sanitarios',  v_total_eventos,
                'cantidad_base',       v_cantidad_base,
                'tasa_morbilidad_pct', v_resultado
            );

        WHEN 'tasa_mortalidad' THEN
            SELECT COUNT(*)
            INTO   v_total_eventos
            FROM   modulo2.eventos_activos ea
            JOIN   modulo2.eventos_bajas eb ON eb.id_evento = ea.id_eventos
            WHERE  ea.id_activo_biologico = p_activo_id
              AND  DATE(ea.fecha) BETWEEN p_fecha_inicio AND p_fecha_fin
              AND  eb.tipo = 'muerte';

            IF v_tipo_activo = 'POBLACIONAL' THEN
                SELECT cantidad_inicial
                INTO   v_cantidad_base
                FROM   modulo2.detalles_activos_biologicos_poblacionales
                WHERE  id_activo_biologico = p_activo_id;
            ELSE
                v_cantidad_base := 1;
            END IF;

            IF v_cantidad_base IS NULL OR v_cantidad_base = 0 THEN
                RAISE EXCEPTION
                    'No se puede calcular la tasa de mortalidad: '
                    'cantidad base es cero o nula.';
            END IF;

            v_resultado   := (v_total_eventos::NUMERIC / v_cantidad_base) * 100;
            v_params_calc := jsonb_build_object(
                'muertes',            v_total_eventos,
                'cantidad_base',      v_cantidad_base,
                'tasa_mortalidad_pct', v_resultado
            );

        WHEN 'produccion_promedio' THEN
            SELECT COALESCE(AVG(ep.cantidad), 0)
            INTO   v_resultado
            FROM   modulo2.eventos_activos ea
            JOIN   modulo2.eventos_productivos ep ON ep.id_evento = ea.id_eventos
            WHERE  ea.id_activo_biologico = p_activo_id
              AND  DATE(ea.fecha) BETWEEN p_fecha_inicio AND p_fecha_fin;

            v_params_calc := jsonb_build_object(
                'produccion_promedio', v_resultado,
                'periodo_inicio',      p_fecha_inicio,
                'periodo_fin',         p_fecha_fin
            );

        WHEN 'conversion_alimenticia' THEN
            -- Ganancia de peso en el rango
            SELECT ec.valor_medicion
            INTO   v_peso_inicial
            FROM   modulo2.eventos_activos ea
            JOIN   modulo2.eventos_crecimeinto ec ON ec.id_evento = ea.id_eventos
            WHERE  ea.id_activo_biologico = p_activo_id
              AND  UPPER(ec.tipo_medicion) LIKE '%PESO%'
              AND  DATE(ea.fecha) BETWEEN p_fecha_inicio AND p_fecha_fin
            ORDER  BY ea.fecha ASC LIMIT 1;

            SELECT ec.valor_medicion
            INTO   v_peso_final
            FROM   modulo2.eventos_activos ea
            JOIN   modulo2.eventos_crecimeinto ec ON ec.id_evento = ea.id_eventos
            WHERE  ea.id_activo_biologico = p_activo_id
              AND  UPPER(ec.tipo_medicion) LIKE '%PESO%'
              AND  DATE(ea.fecha) BETWEEN p_fecha_inicio AND p_fecha_fin
            ORDER  BY ea.fecha DESC LIMIT 1;

            v_ganancia_total := COALESCE(v_peso_final - v_peso_inicial, 0);

            -- Consumo de alimento desde modulo5
            SELECT COALESCE(SUM(rca.cantidad_suministrada), 0)
            INTO   v_consumo_total
            FROM   modulo5.registros_consumo_alimentos rca
            WHERE  rca.id_activo_biologico = p_activo_id
              AND  DATE(rca.fecha_registro) BETWEEN p_fecha_inicio AND p_fecha_fin;

            IF v_ganancia_total = 0 THEN
                RAISE EXCEPTION
                    'La ganancia de peso es cero en el rango especificado. '
                    'No se puede calcular la conversión alimenticia (FCR).';
            END IF;

            v_resultado   := v_consumo_total / v_ganancia_total;
            v_params_calc := jsonb_build_object(
                'consumo_alimento', v_consumo_total,
                'ganancia_peso',    v_ganancia_total,
                'fcr',              v_resultado
            );

    END CASE;
    -- -----------------------------------------------------------------------

    -- Persistir indicador
    INSERT INTO modulo2.indicadores_zootecnicos (
        id_activo_biologico,
        rango_fecha,
        tipo,
        paramtros_calculo
    ) VALUES (
        p_activo_id,
        daterange(p_fecha_inicio, p_fecha_fin, '[]'),
        p_tipo_indicador,
        COALESCE(p_parametros, '{}'::jsonb) || v_params_calc
    );

    -- Auditoría
    CALL modulo1.sp_registrar_auditoria(
        p_usuario_id, NULL, 1, 'Modulo 2', 'INDICADORES',
        'Cálculo indicador ' || p_tipo_indicador::TEXT || ' — activo ' || p_activo_id,
        'exitoso', 'ACTIVO',
        jsonb_build_object(
            'id_activo',      p_activo_id,
            'tipo_indicador', p_tipo_indicador,
            'resultado',      v_params_calc
        )
    );
END;
$$;


ALTER PROCEDURE modulo2.sp_calcular_indicadores_zootecnicos(IN p_activo_id integer, IN p_tipo_indicador modulo2.enum_indicador_zootecnico_tipo, IN p_fecha_inicio date, IN p_fecha_fin date, IN p_parametros jsonb, IN p_usuario_id integer) OWNER TO postgres;

--
-- Name: sp_cambiar_estado_activo(integer, character varying, timestamp with time zone, text, integer, character varying); Type: PROCEDURE; Schema: modulo2; Owner: postgres
--

CREATE PROCEDURE modulo2.sp_cambiar_estado_activo(IN p_activo_id integer, IN p_estado_nuevo character varying, IN p_fecha_cambio timestamp with time zone, IN p_motivo text, IN p_usuario_id integer, IN p_modulo_origen character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_estado_actual INT;
    v_id_estado_nuevo  INT;
    v_nombre_actual    VARCHAR(25);
BEGIN
    -- Validar existencia del activo
    IF NOT EXISTS (
        SELECT 1 FROM modulo2.activos_biologicos
        WHERE id_activo_biologico = p_activo_id
    ) THEN
        RAISE EXCEPTION
            'El activo biológico con ID % no existe.', p_activo_id;
    END IF;

    -- Fecha no futura
    IF p_fecha_cambio > now() THEN
        RAISE EXCEPTION
            'La fecha de cambio de estado no puede ser futura.';
    END IF;

    -- Motivo obligatorio
    IF p_motivo IS NULL OR TRIM(p_motivo) = '' THEN
        RAISE EXCEPTION
            'El motivo del cambio de estado es obligatorio.';
    END IF;

    -- Validar modulo_origen (restricción CHECK en la tabla)
    IF p_modulo_origen IS NULL OR TRIM(p_modulo_origen) = '' THEN
        RAISE EXCEPTION
            'El campo modulo_origen es obligatorio.';
    END IF;

    -- Obtener estado actual
    v_id_estado_actual := modulo2.fn_obtener_estado_actual_activo(p_activo_id);

    SELECT nombre
    INTO   v_nombre_actual
    FROM   modulo2.estados_activos_biologicos
    WHERE  id_estado_activo_biologico = v_id_estado_actual;

    -- Bloquear si ya está en BAJA
    IF UPPER(v_nombre_actual) = 'BAJA' THEN
        RAISE EXCEPTION
            'El activo ID % se encuentra en estado BAJA definitivo. '
            'No se permiten cambios de estado.', p_activo_id;
    END IF;

    -- Resolver id del estado destino
    SELECT id_estado_activo_biologico
    INTO   v_id_estado_nuevo
    FROM   modulo2.estados_activos_biologicos
    WHERE  UPPER(nombre) = UPPER(p_estado_nuevo);

    IF v_id_estado_nuevo IS NULL THEN
        RAISE EXCEPTION
            'El estado "%" no existe en el catálogo de estados.', p_estado_nuevo;
    END IF;

    -- Insertar en historial; el trigger valida la transición y sincroniza
    INSERT INTO modulo2.historicos_estados_activos (
        id_activo_biologico,
        id_estado_nuevo,
        id_estado_anterior,
        fecha_cambio,
        motivo_cambio,
        modulo_origen,
        id_usuario
    ) VALUES (
        p_activo_id,
        v_id_estado_nuevo,
        v_id_estado_actual,
        p_fecha_cambio,
        p_motivo,
        p_modulo_origen,
        p_usuario_id
    );

    -- Auditoría
    CALL modulo1.sp_registrar_auditoria(
        p_usuario_id, NULL, 2, 'Modulo 2', 'ESTADOS',
        'Cambio de estado activo ' || p_activo_id || ': '
            || v_nombre_actual || ' → ' || p_estado_nuevo,
        'exitoso', 'ACTIVO',
        jsonb_build_object(
            'id_activo',       p_activo_id,
            'estado_anterior', v_nombre_actual,
            'estado_nuevo',    p_estado_nuevo,
            'modulo_origen',   p_modulo_origen
        )
    );
END;
$$;


ALTER PROCEDURE modulo2.sp_cambiar_estado_activo(IN p_activo_id integer, IN p_estado_nuevo character varying, IN p_fecha_cambio timestamp with time zone, IN p_motivo text, IN p_usuario_id integer, IN p_modulo_origen character varying) OWNER TO postgres;

--
-- Name: sp_cambiar_fase_activo(integer, integer, timestamp with time zone, text, integer, boolean); Type: PROCEDURE; Schema: modulo2; Owner: postgres
--

CREATE PROCEDURE modulo2.sp_cambiar_fase_activo(IN p_activo_id integer, IN p_fase_destino_id integer, IN p_fecha_cambio timestamp with time zone, IN p_motivo text, IN p_responsable_id integer, IN p_confirmacion_no_estandar boolean DEFAULT false)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_estado_actual INT;
    v_nombre_estado    VARCHAR(25);
    v_fase_actual      RECORD;
BEGIN
    -- Validar existencia del activo
    IF NOT EXISTS (
        SELECT 1 FROM modulo2.activos_biologicos
        WHERE id_activo_biologico = p_activo_id
    ) THEN
        RAISE EXCEPTION
            'El activo biológico con ID % no existe.', p_activo_id;
    END IF;

    -- Validar que la fase destino existe
    IF NOT EXISTS (
        SELECT 1 FROM modulo9.ciclos_productivos
        WHERE id_ciclo_productivo = p_fase_destino_id
    ) THEN
        RAISE EXCEPTION
            'El ciclo productivo (fase) con ID % no existe.', p_fase_destino_id;
    END IF;

    -- Validar estado operativo
    v_id_estado_actual := modulo2.fn_obtener_estado_actual_activo(p_activo_id);

    SELECT nombre
    INTO   v_nombre_estado
    FROM   modulo2.estados_activos_biologicos
    WHERE  id_estado_activo_biologico = v_id_estado_actual;

    IF UPPER(v_nombre_estado) IN ('CERRADO', 'BAJA') THEN
        RAISE EXCEPTION
            'No se puede cambiar la fase del activo ID % porque está en estado %.', 
            p_activo_id, v_nombre_estado;
    END IF;

    -- Obtener fase activa actual con bloqueo pesimista
    SELECT gf.id_gestion_fases,
           gf.id_ciclo_productiva,
           gf.fecha_inicio
    INTO   v_fase_actual
    FROM   modulo2.gestiones_fases gf
    WHERE  gf.id_activo_biologico = p_activo_id
      AND  gf.es_activa = TRUE
    LIMIT  1
    FOR    UPDATE;

    -- Validar que la fase destino es diferente a la actual
    IF v_fase_actual.id_ciclo_productiva IS NOT NULL
       AND v_fase_actual.id_ciclo_productiva = p_fase_destino_id THEN
        RAISE EXCEPTION
            'La fase destino (ID %) es igual a la fase activa actual del activo.', 
            p_fase_destino_id;
    END IF;

    -- Si hay fase activa, cerrarla
    IF v_fase_actual.id_gestion_fases IS NOT NULL THEN
        UPDATE modulo2.gestiones_fases
        SET    es_activa         = FALSE,
               fecha_finalizacion = p_fecha_cambio
        WHERE  id_gestion_fases = v_fase_actual.id_gestion_fases;
    END IF;

    -- Crear nueva fase activa
    INSERT INTO modulo2.gestiones_fases (
        id_activo_biologico,
        id_ciclo_productiva,
        fecha_inicio,
        es_activa,
        id_usuario
    ) VALUES (
        p_activo_id,
        p_fase_destino_id,
        p_fecha_cambio::timetz,
        TRUE,
        p_responsable_id
    );

    -- Auditoría
    CALL modulo1.sp_registrar_auditoria(
        p_responsable_id, NULL, 2, 'Modulo 2', 'FASES',
        'Cambio de fase del activo ' || p_activo_id,
        'exitoso', 'ACTIVO',
        jsonb_build_object(
            'id_activo',      p_activo_id,
            'fase_anterior',  v_fase_actual.id_ciclo_productiva,
            'fase_nueva',     p_fase_destino_id,
            'motivo',         p_motivo
        )
    );
END;
$$;


ALTER PROCEDURE modulo2.sp_cambiar_fase_activo(IN p_activo_id integer, IN p_fase_destino_id integer, IN p_fecha_cambio timestamp with time zone, IN p_motivo text, IN p_responsable_id integer, IN p_confirmacion_no_estandar boolean) OWNER TO postgres;

--
-- Name: sp_cerrar_ciclo_productivo(integer, timestamp with time zone, text, text, integer); Type: PROCEDURE; Schema: modulo2; Owner: postgres
--

CREATE PROCEDURE modulo2.sp_cerrar_ciclo_productivo(IN p_activo_id integer, IN p_fecha_cierre timestamp with time zone, IN p_motivo_cierre text, IN p_descripcion text, IN p_responsable_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_estado_actual INT;
    v_nombre_estado    VARCHAR(25);
    v_fase_activa      RECORD;
    v_id_evento        INT;
BEGIN
    -- Validar existencia del activo
    IF NOT EXISTS (
        SELECT 1 FROM modulo2.activos_biologicos
        WHERE id_activo_biologico = p_activo_id
    ) THEN
        RAISE EXCEPTION
            'El activo biológico con ID % no existe.', p_activo_id;
    END IF;

    -- Fecha no futura
    IF p_fecha_cierre > now() THEN
        RAISE EXCEPTION
            'La fecha de cierre del ciclo no puede ser futura.';
    END IF;

    -- Motivo obligatorio
    IF p_motivo_cierre IS NULL OR TRIM(p_motivo_cierre) = '' THEN
        RAISE EXCEPTION
            'El motivo del cierre del ciclo productivo es obligatorio.';
    END IF;

    -- Validar estado operativo
    v_id_estado_actual := modulo2.fn_obtener_estado_actual_activo(p_activo_id);

    SELECT nombre
    INTO   v_nombre_estado
    FROM   modulo2.estados_activos_biologicos
    WHERE  id_estado_activo_biologico = v_id_estado_actual;

    IF UPPER(v_nombre_estado) IN ('CERRADO', 'BAJA') THEN
        RAISE EXCEPTION
            'El activo ID % ya está en estado %. No se puede cerrar el ciclo.',
            p_activo_id, v_nombre_estado;
    END IF;

    -- Verificar existencia de fase activa
    SELECT gf.id_gestion_fases,
           gf.id_ciclo_productiva
    INTO   v_fase_activa
    FROM   modulo2.gestiones_fases gf
    WHERE  gf.id_activo_biologico = p_activo_id
      AND  gf.es_activa = TRUE
    LIMIT  1;

    IF v_fase_activa.id_gestion_fases IS NULL THEN
        RAISE EXCEPTION
            'El activo ID % no tiene una fase productiva activa. '
            'No se puede cerrar el ciclo.', p_activo_id;
    END IF;

    -- Cerrar la fase activa
    UPDATE modulo2.gestiones_fases
    SET    es_activa          = FALSE,
           fecha_finalizacion  = p_fecha_cierre
    WHERE  id_gestion_fases  = v_fase_activa.id_gestion_fases;

    -- Registrar evento de cierre
    INSERT INTO modulo2.eventos_activos (
        id_activo_biologico, fecha, descripcion, id_usuario
    ) VALUES (
        p_activo_id,
        p_fecha_cierre,
        COALESCE(p_descripcion, 'Cierre de ciclo productivo: ' || p_motivo_cierre),
        p_responsable_id
    )
    RETURNING id_eventos INTO v_id_evento;

    -- Cambiar estado a CERRADO (modulo_origen debe estar en el catálogo del CHECK)
    CALL modulo2.sp_cambiar_estado_activo(
        p_activo_id,
        'CERRADO',
        p_fecha_cierre,
        p_motivo_cierre,
        p_responsable_id,
        'modulo2'
    );

    -- Auditoría
    CALL modulo1.sp_registrar_auditoria(
        p_responsable_id, NULL, 2, 'Modulo 2', 'CICLO',
        'Cierre de ciclo productivo del activo ' || p_activo_id,
        'exitoso', 'CERRADO',
        jsonb_build_object(
            'id_activo',      p_activo_id,
            'id_fase_cerrada', v_fase_activa.id_gestion_fases,
            'id_evento_cierre', v_id_evento,
            'motivo',         p_motivo_cierre
        )
    );
END;
$$;


ALTER PROCEDURE modulo2.sp_cerrar_ciclo_productivo(IN p_activo_id integer, IN p_fecha_cierre timestamp with time zone, IN p_motivo_cierre text, IN p_descripcion text, IN p_responsable_id integer) OWNER TO postgres;

--
-- Name: sp_recalcular_metricas_lote(integer); Type: PROCEDURE; Schema: modulo2; Owner: postgres
--

CREATE PROCEDURE modulo2.sp_recalcular_metricas_lote(IN p_activo_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_infra_id        INT;
    v_cantidad_actual INT;
    v_peso_promedio   NUMERIC;
    v_superficie      NUMERIC(10,2);
BEGIN
    -- Obtener infraestructura y verificar que el activo existe y es POBLACIONAL
    SELECT id_infraestructura
    INTO   v_infra_id
    FROM   modulo2.activos_biologicos
    WHERE  id_activo_biologico = p_activo_id
      AND  tipo = 'POBLACIONAL';

    IF v_infra_id IS NULL THEN
        RAISE EXCEPTION
            'El activo ID % no existe o no es de tipo POBLACIONAL.', p_activo_id;
    END IF;

    -- Obtener métricas vigentes del lote
    SELECT cantidad_actual, peso_promedio
    INTO   v_cantidad_actual, v_peso_promedio
    FROM   modulo2.detalles_activos_biologicos_poblacionales
    WHERE  id_activo_biologico = p_activo_id;

    IF v_cantidad_actual IS NULL THEN
        RAISE EXCEPTION
            'No se encontraron detalles poblacionales para el activo ID %.', p_activo_id;
    END IF;

    -- Obtener superficie de la infraestructura
    SELECT superficie
    INTO   v_superficie
    FROM   modulo9.infraestructuras
    WHERE  id_infraestructura = v_infra_id;

    -- Actualizar biomasa_total y densidad
    UPDATE modulo2.detalles_activos_biologicos_poblacionales
    SET
        biomasa_total = v_cantidad_actual * v_peso_promedio,
        densidad      = CASE
                            WHEN v_superficie IS NOT NULL AND v_superficie > 0
                            THEN v_cantidad_actual::NUMERIC / v_superficie
                            ELSE 0
                        END
    WHERE id_activo_biologico = p_activo_id;
END;
$$;


ALTER PROCEDURE modulo2.sp_recalcular_metricas_lote(IN p_activo_id integer) OWNER TO postgres;

--
-- Name: sp_registrar_activo_biologico(modulo2.enum_activo_biologico_tipo, integer, character varying, integer, integer, modulo2.enum_activo_biologico_origen_financiero, numeric, integer, jsonb, integer); Type: PROCEDURE; Schema: modulo2; Owner: postgres
--

CREATE PROCEDURE modulo2.sp_registrar_activo_biologico(IN p_tipo modulo2.enum_activo_biologico_tipo, IN p_id_especie integer, IN p_identificador character varying, IN p_cantidad_inicial integer, IN p_fecha_inicio_ciclo integer, IN p_origen_financiero modulo2.enum_activo_biologico_origen_financiero, IN p_costo_adquisicion numeric, IN p_id_infraestructura integer, IN p_atributos_dinamicos jsonb, IN p_id_usuario integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_activo INT;
    v_id_estado_activo INT;
    v_superficie NUMERIC(10,2);
    v_especie_activa BOOLEAN;
    v_infra_activa BOOLEAN;
BEGIN
    -- 1. Validar especie activa
    SELECT es_activo INTO v_especie_activa FROM modulo9.especies WHERE id_especie = p_id_especie;
    IF NOT FOUND OR v_especie_activa = FALSE THEN
        RAISE EXCEPTION 'La especie con ID % no existe o no está activa.', p_id_especie;
    END IF;

    -- 2. Validar infraestructura activa
    SELECT superficie, es_activo INTO v_superficie, v_infra_activa
    FROM modulo9.infraestructuras
    WHERE id_infraestructura = p_id_infraestructura;
    IF NOT FOUND OR v_infra_activa = FALSE THEN
        RAISE EXCEPTION 'La infraestructura con ID % no existe o no está activa.', p_id_infraestructura;
    END IF;

    -- 3. Validar reglas por tipo
    IF p_tipo = 'INDIVIDUAL' THEN
        IF p_identificador IS NULL OR TRIM(p_identificador) = '' THEN
            RAISE EXCEPTION 'El identificador es obligatorio para activos INDIVIDUAL.';
        END IF;
        IF p_cantidad_inicial IS NOT NULL THEN
            RAISE EXCEPTION 'La cantidad inicial debe ser NULL para activos INDIVIDUAL.';
        END IF;
        IF (p_atributos_dinamicos->>'raza') IS NULL OR TRIM(p_atributos_dinamicos->>'raza') = '' THEN
            RAISE EXCEPTION 'El atributo "raza" es obligatorio para INDIVIDUAL.';
        END IF;
        IF (p_atributos_dinamicos->>'sexo') NOT IN ('Macho','Hembra') THEN
            RAISE EXCEPTION 'El atributo "sexo" debe ser Macho o Hembra.';
        END IF;
        IF (p_atributos_dinamicos->>'fecha_nacimiento') IS NULL THEN
            RAISE EXCEPTION 'El atributo "fecha_nacimiento" es obligatorio para INDIVIDUAL.';
        END IF;
    ELSIF p_tipo = 'POBLACIONAL' THEN
        IF p_identificador IS NOT NULL THEN
            RAISE EXCEPTION 'El identificador debe ser NULL para activos POBLACIONAL.';
        END IF;
        IF p_cantidad_inicial IS NULL OR p_cantidad_inicial <= 0 THEN
            RAISE EXCEPTION 'Cantidad inicial debe ser positiva para POBLACIONAL.';
        END IF;
    END IF;

    -- 4. Validar origen_financiero
    IF p_origen_financiero IN ('compra','donacion') THEN
        IF p_costo_adquisicion IS NULL OR p_costo_adquisicion <= 0 THEN
            RAISE EXCEPTION 'Costo de adquisición requerido para origen %.', p_origen_financiero;
        END IF;
        IF (p_atributos_dinamicos->>'soporte_documental') IS NULL OR TRIM(p_atributos_dinamicos->>'soporte_documental') = '' THEN
            RAISE EXCEPTION 'Soporte documental requerido para origen %.', p_origen_financiero;
        END IF;
    ELSIF p_origen_financiero = 'nacimiento' THEN
        IF p_costo_adquisicion IS NOT NULL THEN
            RAISE EXCEPTION 'Costo de adquisición debe ser NULL para origen nacimiento.';
        END IF;
    END IF;

    -- 5. Obtener estado inicial ACTIVO
    SELECT id_estado_activo_biologico INTO v_id_estado_activo
    FROM modulo2.estados_activos_biologicos
    WHERE nombre = 'Activo' LIMIT 1;
    IF v_id_estado_activo IS NULL THEN
        v_id_estado_activo := 1;  -- fallback
    END IF;

    -- 6. Insertar en activos_biologicos
    INSERT INTO modulo2.activos_biologicos(
        id_especie, identificador, id_infraestructura, tipo, fecha_inicio_ciclo,
        id_estado, descripcion, origen_financiero, costo_adquisicion,
        atributos_dinamicos, id_usuario, fecha_creacion
    ) VALUES (
        p_id_especie, p_identificador, p_id_infraestructura, p_tipo, p_fecha_inicio_ciclo,
        v_id_estado_activo, NULL, p_origen_financiero, p_costo_adquisicion,
        p_atributos_dinamicos, p_id_usuario, now()
    ) RETURNING id_activo_biologico INTO v_id_activo;

    -- 7. Insertar detalle según tipo
    IF p_tipo = 'INDIVIDUAL' THEN
        INSERT INTO modulo2.detalles_activos_individuales(
            id_activo_biologico, raza, sexo, fecha_nacimeinto, peso_inicial,
            fecha_creacion, id_usuario
        ) VALUES (
            v_id_activo,
            p_atributos_dinamicos->>'raza',
            p_atributos_dinamicos->>'sexo',
            (p_atributos_dinamicos->>'fecha_nacimiento')::TIMESTAMPTZ,
            (p_atributos_dinamicos->>'peso_inicial')::NUMERIC,
            now()::TIME,
            p_id_usuario
        );
    ELSE -- POBLACIONAL
        INSERT INTO modulo2.detalles_activos_biologicos_poblacionales(
            id_activo_biologico, cantidad_inicial, cantidad_actual,
            peso_promedio, biomasa_total, densidad
        ) VALUES (
            v_id_activo, p_cantidad_inicial, p_cantidad_inicial,
            COALESCE((p_atributos_dinamicos->>'peso_promedio')::NUMERIC, 0),
            COALESCE((p_atributos_dinamicos->>'peso_promedio')::NUMERIC, 0) * p_cantidad_inicial,
            (COALESCE((p_atributos_dinamicos->>'peso_promedio')::NUMERIC, 0) * p_cantidad_inicial) / NULLIF(v_superficie,0)
        );
    END IF;

    -- 8. (Eliminado) Registrar estado inicial en histórico: ya no se hace

    -- 9. Insertar primera fase activa (RF-37)
    INSERT INTO modulo2.gestiones_fases(
        id_activo_biologico, id_ciclo_productiva, fecha_inicio, es_activa, id_usuario
    )
    SELECT v_id_activo, cp.id_ciclo_productivo, CURRENT_TIME, TRUE, p_id_usuario
    FROM modulo9.ciclos_productivos cp
    JOIN modulo9.ciclos_productivos_biologicos cpb ON cpb.id_ciclo_productivo = cp.id_ciclo_productivo
    JOIN modulo9.ciclos_biologicos cb ON cb.id_ciclo_biologico = cpb.id_ciclo_biologico
    WHERE cb.id_especie = p_id_especie
    ORDER BY cb.duracion_dias ASC
    LIMIT 1;

    -- 10. Auditoría (snapshot inicial)
    INSERT INTO modulo2.auditoria_activos_biologicos(
        id_activo_biologico, id_usuario, campo_modificado, valor_anterior, valor_nuevo,
        fecha_cambio, modulo_origen
    ) VALUES (
        v_id_activo, p_id_usuario, 'REGISTRO_INICIAL', '{}'::JSONB,
        to_jsonb(ROW(v_id_activo, p_tipo, p_identificador)), now(), 'modulo2'
    );

    -- Registrar auditoría general
    CALL modulo1.sp_registrar_auditoria(
        p_id_usuario, NULL, 1, 'Modulo 2', 'ACTIVOS',
        'Registro de activo ' || COALESCE(p_identificador, 'Lote '||v_id_activo),
        'exitoso', 'ACTIVO',
        jsonb_build_object('id_activo', v_id_activo, 'tipo', p_tipo)
    );
END;
$$;


ALTER PROCEDURE modulo2.sp_registrar_activo_biologico(IN p_tipo modulo2.enum_activo_biologico_tipo, IN p_id_especie integer, IN p_identificador character varying, IN p_cantidad_inicial integer, IN p_fecha_inicio_ciclo integer, IN p_origen_financiero modulo2.enum_activo_biologico_origen_financiero, IN p_costo_adquisicion numeric, IN p_id_infraestructura integer, IN p_atributos_dinamicos jsonb, IN p_id_usuario integer) OWNER TO postgres;

--
-- Name: sp_registrar_activo_biologico(integer, integer, character varying, integer, modulo2.enum_activo_biologico_tipo, modulo2.enum_activo_biologico_origen_financiero, numeric, character varying, integer, integer, character varying, character varying, character varying, timestamp with time zone, numeric); Type: PROCEDURE; Schema: modulo2; Owner: postgres
--

CREATE PROCEDURE modulo2.sp_registrar_activo_biologico(IN p_id_usuario integer, IN p_id_especie integer, IN p_identificador character varying, IN p_id_infraestructura integer, IN p_tipo modulo2.enum_activo_biologico_tipo, IN p_origen_financiero modulo2.enum_activo_biologico_origen_financiero, IN p_costo_adquisicion numeric, IN p_descripcion character varying, IN p_cantidad_inicial integer DEFAULT NULL::integer, IN p_fecha_inicio_ciclo integer DEFAULT NULL::integer, IN p_soporte_documental character varying DEFAULT NULL::character varying, IN p_raza character varying DEFAULT NULL::character varying, IN p_sexo character varying DEFAULT NULL::character varying, IN p_fecha_nacimiento timestamp with time zone DEFAULT NULL::timestamp with time zone, IN p_peso_inicial numeric DEFAULT NULL::numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_activo        INT;
    v_id_estado_activo INT;
    v_atributos        JSONB;
BEGIN
    -- Validaciones por tipo
    IF p_tipo = 'INDIVIDUAL' THEN
        IF p_identificador IS NULL OR TRIM(p_identificador) = '' THEN
            RAISE EXCEPTION 'Para activos individuales, el identificador es obligatorio.';
        END IF;
        IF p_cantidad_inicial IS NOT NULL THEN
            RAISE EXCEPTION 'Para activos individuales, la cantidad inicial debe ser nula.';
        END IF;
        IF p_raza IS NULL OR TRIM(p_raza) = '' THEN
            RAISE EXCEPTION 'La raza es obligatoria para activos individuales.';
        END IF;
        IF p_sexo IS NULL OR UPPER(p_sexo) NOT IN ('MACHO', 'HEMBRA') THEN
            RAISE EXCEPTION 'El sexo debe ser ''Macho'' o ''Hembra''.';
        END IF;
        IF p_fecha_nacimiento IS NULL THEN
            RAISE EXCEPTION 'La fecha de nacimiento es obligatoria para activos individuales.';
        END IF;
    ELSIF p_tipo = 'POBLACIONAL' THEN
        IF p_identificador IS NOT NULL THEN
            RAISE EXCEPTION 'Para activos poblacionales, el identificador debe ser nulo.';
        END IF;
        IF p_cantidad_inicial IS NULL OR p_cantidad_inicial <= 0 THEN
            RAISE EXCEPTION
                'Para activos poblacionales, la cantidad inicial es obligatoria y mayor a cero.';
        END IF;
    END IF;

    -- Obtener id del estado ACTIVO (fallback a 1)
    SELECT id_estado_activo_biologico
    INTO   v_id_estado_activo
    FROM   modulo2.estados_activos_biologicos
    WHERE  nombre ILIKE '%ACTIVO%'
    LIMIT  1;

    IF v_id_estado_activo IS NULL THEN
        v_id_estado_activo := 1;
    END IF;

    -- Construir atributos dinámicos según origen financiero
    IF p_origen_financiero IN ('compra', 'donacion') THEN
        v_atributos := jsonb_build_object('soporte_documental', p_soporte_documental);
    ELSE
        v_atributos := '{}'::jsonb;
    END IF;

    -- Para POBLACIONAL, el trigger trg_fn_activo_biologico_coherencia_tipo
    -- busca cantidad_inicial dentro de atributos_dinamicos (JSONB), no como
    -- columna separada. Se debe incluir aquí para que pase la validación.
    IF p_tipo = 'POBLACIONAL' THEN
        v_atributos := v_atributos || jsonb_build_object('cantidad_inicial', p_cantidad_inicial);
    END IF;

    -- Insertar en activos_biologicos
    INSERT INTO modulo2.activos_biologicos (
        id_especie, identificador, id_infraestructura, tipo,
        id_estado, descripcion, origen_financiero, costo_adquisicion,
        fecha_inicio_ciclo, atributos_dinamicos, id_usuario, fecha_creacion
    ) VALUES (
        p_id_especie, p_identificador, p_id_infraestructura, p_tipo,
        v_id_estado_activo, p_descripcion, p_origen_financiero, p_costo_adquisicion,
        p_fecha_inicio_ciclo, v_atributos, p_id_usuario, now()
    )
    RETURNING id_activo_biologico INTO v_id_activo;

    -- Insertar detalle según tipo
    IF p_tipo = 'INDIVIDUAL' THEN
        INSERT INTO modulo2.detalles_activos_individuales (
            id_activo_biologico, raza, sexo, fecha_nacimeinto,
            peso_inicial, fecha_creacion, id_usuario
        ) VALUES (
            v_id_activo, p_raza, p_sexo, p_fecha_nacimiento,
            p_peso_inicial, now()::timetz, p_id_usuario
        );
    ELSIF p_tipo = 'POBLACIONAL' THEN
        INSERT INTO modulo2.detalles_activos_biologicos_poblacionales (
            id_activo_biologico, cantidad_actual, cantidad_inicial
        ) VALUES (
            v_id_activo, p_cantidad_inicial, p_cantidad_inicial
        );
    END IF;

    -- Auditoría
    CALL modulo1.sp_registrar_auditoria(
        p_id_usuario, NULL, 1, 'Modulo 2', 'ACTIVOS',
        'Registro activo: ' || COALESCE(p_identificador, 'Poblacional ID ' || v_id_activo),
        'exitoso', 'ACTIVO',
        jsonb_build_object('id_activo', v_id_activo, 'tipo', p_tipo)
    );
END;
$$;


ALTER PROCEDURE modulo2.sp_registrar_activo_biologico(IN p_id_usuario integer, IN p_id_especie integer, IN p_identificador character varying, IN p_id_infraestructura integer, IN p_tipo modulo2.enum_activo_biologico_tipo, IN p_origen_financiero modulo2.enum_activo_biologico_origen_financiero, IN p_costo_adquisicion numeric, IN p_descripcion character varying, IN p_cantidad_inicial integer, IN p_fecha_inicio_ciclo integer, IN p_soporte_documental character varying, IN p_raza character varying, IN p_sexo character varying, IN p_fecha_nacimiento timestamp with time zone, IN p_peso_inicial numeric) OWNER TO postgres;

--
-- Name: sp_registrar_activo_biologico(integer, integer, character varying, integer, modulo2.enum_activo_biologico_tipo, modulo2.enum_activo_biologico_origen_financiero, numeric, character varying, integer, integer, character varying, character varying, character varying, timestamp with time zone, numeric, numeric); Type: PROCEDURE; Schema: modulo2; Owner: postgres
--

CREATE PROCEDURE modulo2.sp_registrar_activo_biologico(IN p_id_usuario integer, IN p_id_especie integer, IN p_identificador character varying, IN p_id_infraestructura integer, IN p_tipo modulo2.enum_activo_biologico_tipo, IN p_origen_financiero modulo2.enum_activo_biologico_origen_financiero, IN p_costo_adquisicion numeric, IN p_descripcion character varying, IN p_cantidad_inicial integer DEFAULT NULL::integer, IN p_fecha_inicio_ciclo integer DEFAULT NULL::integer, IN p_soporte_documental character varying DEFAULT NULL::character varying, IN p_raza character varying DEFAULT NULL::character varying, IN p_sexo character varying DEFAULT NULL::character varying, IN p_fecha_nacimiento timestamp with time zone DEFAULT NULL::timestamp with time zone, IN p_peso_inicial numeric DEFAULT NULL::numeric, IN p_peso_promedio numeric DEFAULT 0)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_activo        INT;
    v_id_estado_activo INT;
    v_atributos        JSONB;
BEGIN
    -- Validaciones por tipo
    IF p_tipo = 'INDIVIDUAL' THEN
        IF p_identificador IS NULL OR TRIM(p_identificador) = '' THEN
            RAISE EXCEPTION 'Para activos individuales, el identificador es obligatorio.';
        END IF;
        IF p_cantidad_inicial IS NOT NULL THEN
            RAISE EXCEPTION 'Para activos individuales, la cantidad inicial debe ser nula.';
        END IF;
        IF p_raza IS NULL OR TRIM(p_raza) = '' THEN
            RAISE EXCEPTION 'La raza es obligatoria para activos individuales.';
        END IF;
        IF p_sexo IS NULL OR UPPER(p_sexo) NOT IN ('MACHO', 'HEMBRA') THEN
            RAISE EXCEPTION 'El sexo debe ser ''Macho'' o ''Hembra''.';
        END IF;
        IF p_fecha_nacimiento IS NULL THEN
            RAISE EXCEPTION 'La fecha de nacimiento es obligatoria para activos individuales.';
        END IF;
    ELSIF p_tipo = 'POBLACIONAL' THEN
        IF p_identificador IS NOT NULL THEN
            RAISE EXCEPTION 'Para activos poblacionales, el identificador debe ser nulo.';
        END IF;
        IF p_cantidad_inicial IS NULL OR p_cantidad_inicial <= 0 THEN
            RAISE EXCEPTION
                'Para activos poblacionales, la cantidad inicial es obligatoria y mayor a cero.';
        END IF;
    END IF;

    -- Obtener id del estado ACTIVO (fallback a 1)
    SELECT id_estado_activo_biologico
    INTO   v_id_estado_activo
    FROM   modulo2.estados_activos_biologicos
    WHERE  nombre ILIKE '%ACTIVO%'
    LIMIT  1;

    IF v_id_estado_activo IS NULL THEN
        v_id_estado_activo := 1;
    END IF;

    -- Construir atributos dinámicos según origen financiero
    IF p_origen_financiero IN ('compra', 'donacion') THEN
        v_atributos := jsonb_build_object('soporte_documental', p_soporte_documental);
    ELSE
        v_atributos := '{}'::jsonb;
    END IF;

    -- Para POBLACIONAL, el trigger trg_fn_activo_biologico_coherencia_tipo
    -- busca cantidad_inicial dentro de atributos_dinamicos (JSONB), no como
    -- columna separada. Se debe incluir aquí para que pase la validación.
    IF p_tipo = 'POBLACIONAL' THEN
        v_atributos := v_atributos || jsonb_build_object('cantidad_inicial', p_cantidad_inicial);
    END IF;

    -- Insertar en activos_biologicos
    INSERT INTO modulo2.activos_biologicos (
        id_especie, identificador, id_infraestructura, tipo,
        id_estado, descripcion, origen_financiero, costo_adquisicion,
        fecha_inicio_ciclo, atributos_dinamicos, id_usuario, fecha_creacion
    ) VALUES (
        p_id_especie, p_identificador, p_id_infraestructura, p_tipo,
        v_id_estado_activo, p_descripcion, p_origen_financiero, p_costo_adquisicion,
        p_fecha_inicio_ciclo, v_atributos, p_id_usuario, now()
    )
    RETURNING id_activo_biologico INTO v_id_activo;

    -- Insertar detalle según tipo
    IF p_tipo = 'INDIVIDUAL' THEN
        INSERT INTO modulo2.detalles_activos_individuales (
            id_activo_biologico, raza, sexo, fecha_nacimeinto,
            peso_inicial, fecha_creacion, id_usuario
        ) VALUES (
            v_id_activo, p_raza, p_sexo, p_fecha_nacimiento,
            p_peso_inicial, now()::timetz, p_id_usuario
        );
    ELSIF p_tipo = 'POBLACIONAL' THEN
        INSERT INTO modulo2.detalles_activos_biologicos_poblacionales (
            id_activo_biologico, cantidad_actual, cantidad_inicial,
            peso_promedio, biomasa_total, densidad
        ) VALUES (
            v_id_activo,
            p_cantidad_inicial,
            p_cantidad_inicial,
            COALESCE(p_peso_promedio, 0),
            p_cantidad_inicial * COALESCE(p_peso_promedio, 0),
            0
        );
    END IF;

    -- Auditoría
    CALL modulo1.sp_registrar_auditoria(
        p_id_usuario, NULL, 1, 'Modulo 2', 'ACTIVOS',
        'Registro activo: ' || COALESCE(p_identificador, 'Poblacional ID ' || v_id_activo),
        'exitoso', 'ACTIVO',
        jsonb_build_object('id_activo', v_id_activo, 'tipo', p_tipo)
    );
END;
$$;


