-- Name: sp_registrar_baja(integer, modulo2.enum_evento_bajas_tipo, timestamp with time zone, text, integer, integer); Type: PROCEDURE; Schema: modulo2; Owner: postgres
--

CREATE PROCEDURE modulo2.sp_registrar_baja(IN p_activo_id integer, IN p_tipo_baja modulo2.enum_evento_bajas_tipo, IN p_fecha_baja timestamp with time zone, IN p_motivo text, IN p_cantidad_afectada integer, IN p_usuario_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_estado_actual INT;
    v_nombre_estado    VARCHAR(25);
    v_tipo_activo      modulo2.enum_activo_biologico_tipo;
    v_cantidad_actual  INT;
    v_id_evento        INT;
BEGIN
    -- Validar existencia del activo
    IF NOT EXISTS (
        SELECT 1 FROM modulo2.activos_biologicos
        WHERE id_activo_biologico = p_activo_id
    ) THEN
        RAISE EXCEPTION
            'El activo biológico con ID % no existe.', p_activo_id;
    END IF;

    -- Fecha no futura
    IF p_fecha_baja > now() THEN
        RAISE EXCEPTION
            'La fecha de baja no puede ser futura.';
    END IF;

    -- Motivo obligatorio
    IF p_motivo IS NULL OR TRIM(p_motivo) = '' THEN
        RAISE EXCEPTION
            'El motivo de la baja es obligatorio.';
    END IF;

    -- Tipo y estado actual del activo
    SELECT tipo
    INTO   v_tipo_activo
    FROM   modulo2.activos_biologicos
    WHERE  id_activo_biologico = p_activo_id;

    v_id_estado_actual := modulo2.fn_obtener_estado_actual_activo(p_activo_id);

    SELECT nombre
    INTO   v_nombre_estado
    FROM   modulo2.estados_activos_biologicos
    WHERE  id_estado_activo_biologico = v_id_estado_actual;

    IF UPPER(v_nombre_estado) = 'BAJA' THEN
        RAISE EXCEPTION
            'El activo ID % ya se encuentra en estado BAJA.', p_activo_id;
    END IF;

    -- Validaciones adicionales para lotes
    IF v_tipo_activo = 'POBLACIONAL' THEN
        IF p_cantidad_afectada IS NULL OR p_cantidad_afectada <= 0 THEN
            RAISE EXCEPTION
                'Para activos poblacionales, la cantidad afectada debe ser mayor a cero.';
        END IF;

        SELECT cantidad_actual
        INTO   v_cantidad_actual
        FROM   modulo2.detalles_activos_biologicos_poblacionales
        WHERE  id_activo_biologico = p_activo_id;

        IF p_cantidad_afectada > v_cantidad_actual THEN
            RAISE EXCEPTION
                'La cantidad a dar de baja (%) supera la cantidad actual del lote (%).',
                p_cantidad_afectada, v_cantidad_actual;
        END IF;
    END IF;

    -- Registrar evento base
    INSERT INTO modulo2.eventos_activos (
        id_activo_biologico, fecha, descripcion, id_usuario
    ) VALUES (
        p_activo_id, p_fecha_baja, p_motivo, p_usuario_id
    )
    RETURNING id_eventos INTO v_id_evento;

    -- Insertar evento de baja
    -- (trg_baja_cantidad_valida y trg_baja_actualizar_cantidad_lote actúan aquí)
    INSERT INTO modulo2.eventos_bajas (
        id_evento,
        cantidad_afectada,
        detalles,
        tipo
    ) VALUES (
        v_id_evento,
        COALESCE(p_cantidad_afectada, 1),
        p_motivo,
        p_tipo_baja
    );

    -- INDIVIDUAL → siempre BAJA
    -- POBLACIONAL baja total → BAJA; parcial → sin cambio de estado
    IF v_tipo_activo = 'INDIVIDUAL' THEN
        CALL modulo2.sp_cambiar_estado_activo(
            p_activo_id, 'BAJA', p_fecha_baja, p_motivo, p_usuario_id, 'modulo2'
        );
    ELSIF v_tipo_activo = 'POBLACIONAL'
          AND p_cantidad_afectada >= v_cantidad_actual THEN
        CALL modulo2.sp_cambiar_estado_activo(
            p_activo_id, 'BAJA', p_fecha_baja, p_motivo, p_usuario_id, 'modulo2'
        );
    END IF;

    -- Auditoría
    CALL modulo1.sp_registrar_auditoria(
        p_usuario_id, NULL, 2, 'Modulo 2', 'BAJAS',
        'Baja del activo ' || p_activo_id || ' — tipo: ' || p_tipo_baja::TEXT,
        'exitoso', 'BAJA',
        jsonb_build_object(
            'id_activo',          p_activo_id,
            'tipo_baja',          p_tipo_baja,
            'cantidad_afectada',  p_cantidad_afectada,
            'motivo',             p_motivo
        )
    );
END;
$$;


ALTER PROCEDURE modulo2.sp_registrar_baja(IN p_activo_id integer, IN p_tipo_baja modulo2.enum_evento_bajas_tipo, IN p_fecha_baja timestamp with time zone, IN p_motivo text, IN p_cantidad_afectada integer, IN p_usuario_id integer) OWNER TO postgres;

--
-- Name: sp_registrar_evento_biologico(integer, text, timestamp with time zone, text, jsonb, integer); Type: PROCEDURE; Schema: modulo2; Owner: postgres
--

CREATE PROCEDURE modulo2.sp_registrar_evento_biologico(IN p_activo_id integer, IN p_tipo_evento text, IN p_fecha_evento timestamp with time zone, IN p_descripcion text, IN p_datos_evento jsonb, IN p_responsable_id integer)
    LANGUAGE plpgsql
    AS $$DECLARE
    v_id_estado_actual INT;
    v_nombre_estado    VARCHAR(25);
    v_id_evento        INT;
BEGIN
    -- Validar existencia del activo
    IF NOT EXISTS (
        SELECT 1 FROM modulo2.activos_biologicos
        WHERE id_activo_biologico = p_activo_id
    ) THEN
        RAISE EXCEPTION
            'El activo biológico con ID % no existe.', p_activo_id;
    END IF;

    -- Fecha no futura
    IF p_fecha_evento > now() THEN
        RAISE EXCEPTION
            'La fecha del evento no puede ser futura.';
    END IF;

    -- Datos del evento obligatorios
    IF p_datos_evento IS NULL THEN
        RAISE EXCEPTION
            'Los datos del evento (p_datos_evento) son obligatorios.';
    END IF;

    -- Validar estado operativo
    v_id_estado_actual := modulo2.fn_obtener_estado_actual_activo(p_activo_id);

    SELECT nombre
    INTO   v_nombre_estado
    FROM   modulo2.estados_activos_biologicos
    WHERE  id_estado_activo_biologico = v_id_estado_actual;

    IF UPPER(v_nombre_estado) IN ('CERRADO', 'BAJA') THEN
        RAISE EXCEPTION
            'No se pueden registrar eventos sobre el activo ID % en estado %.',
            p_activo_id, v_nombre_estado;
    END IF;

    -- Insertar evento base
    INSERT INTO modulo2.eventos_activos (
        id_activo_biologico, fecha, descripcion, id_usuario
    ) VALUES (
        p_activo_id, p_fecha_evento, p_descripcion, p_responsable_id
    )
    RETURNING id_eventos INTO v_id_evento;

    -- Insertar en tabla especializada según tipo
    CASE UPPER(TRIM(p_tipo_evento))

        WHEN 'CRECIMIENTO' THEN
            INSERT INTO modulo2.eventos_crecimeinto (
                id_evento,
                tipo_medicion,
                valor_medicion,
                unidad_medida,
                tipo_agregacion,
                frecuencia
            ) VALUES (
                v_id_evento,
                p_datos_evento->>'tipo_medicion',
                (p_datos_evento->>'valor_medicion')::NUMERIC(10,2),
                p_datos_evento->>'unidad_medida',
                p_datos_evento->>'tipo_agregacion',
                p_datos_evento->>'frecuencia'
            );

        WHEN 'SANITARIO' THEN
            INSERT INTO modulo2.eventos_sanitarios (
                id_evento,
                diagnostico,
                medicamento,
                dosis,
                unidad_dosis,
                frecuencia,
                tipo,
                duracion,
                observaciones
            ) VALUES (
                v_id_evento,
                p_datos_evento->>'diagnostico',
                p_datos_evento->>'medicamento',
                (p_datos_evento->>'dosis')::NUMERIC(10,2),
                p_datos_evento->>'unidad_dosis',
                (p_datos_evento->>'frecuencia')::INT,
                (p_datos_evento->>'tipo')::modulo2.enum_evento_sanitario_tipo,
                (p_datos_evento->>'duracion')::INT,
                p_datos_evento->>'observaciones'
            );

        WHEN 'PRODUCTIVO' THEN
            INSERT INTO modulo2.eventos_productivos (
                id_evento,
                cantidad,
                condiciones,
                id_metrica_produccion,
                id_ciclo_productivo
            ) VALUES (
                v_id_evento,
                (p_datos_evento->>'cantidad')::NUMERIC(12,3),
                p_datos_evento->>'condiciones',
                (p_datos_evento->>'id_metrica_produccion')::INT,
                (p_datos_evento->>'id_ciclo_productivo')::INT
            );

        WHEN 'REPRODUCTIVO' THEN
            DECLARE
                v_categoria modulo2.enum_evento_reproductivo_categoria;
            BEGIN
                v_categoria := LOWER(p_datos_evento->>'categoria')::modulo2.enum_evento_reproductivo_categoria;

                CASE v_categoria

                    WHEN 'servicio', 'inseminacion' THEN
                        INSERT INTO modulo2.eventos_reproductivos (
                            id_evento_reproductivo,
                            categoria,
                            id_padre,
                            resultado,
                            numero_cria,
                            id_madre
                        ) VALUES (
                            v_id_evento,
                            v_categoria,
                            (p_datos_evento->>'id_padre')::INT,
                            p_datos_evento->>'resultado',
                            0,
                            NULL
                        );

                    WHEN 'diagnostico' THEN
                        INSERT INTO modulo2.eventos_reproductivos (
                            id_evento_reproductivo,
                            categoria,
                            id_padre,
                            resultado,
                            numero_cria,
                            id_madre
                        ) VALUES (
                            v_id_evento,
                            v_categoria,
                            NULL,
                            p_datos_evento->>'resultado',
                            0,
                            NULL
                        );

                    WHEN 'parto', 'nacimiento' THEN
                        IF (p_datos_evento->>'numero_cria') IS NULL
                           OR (p_datos_evento->>'numero_cria')::INT < 1 THEN
                            RAISE EXCEPTION
                                'El número de crías es obligatorio y debe ser >= 1 para el evento %.', v_categoria;
                        END IF;

                        INSERT INTO modulo2.eventos_reproductivos (
                            id_evento_reproductivo,
                            categoria,
                            id_padre,
                            resultado,
                            numero_cria,
                            id_madre
                        ) VALUES (
                            v_id_evento,
                            v_categoria,
                            (p_datos_evento->>'id_padre')::INT,
                            p_datos_evento->>'resultado',
                            (p_datos_evento->>'numero_cria')::INT,
                            (p_datos_evento->>'id_madre')::INT
                        );

                    WHEN 'aborto' THEN
                        INSERT INTO modulo2.eventos_reproductivos (
                            id_evento_reproductivo,
                            categoria,
                            id_padre,
                            resultado,
                            numero_cria,
                            id_madre
                        ) VALUES (
                            v_id_evento,
                            v_categoria,
                            NULL,
                            p_datos_evento->>'resultado',
                            COALESCE((p_datos_evento->>'numero_cria')::INT, 0),
                            (p_datos_evento->>'id_madre')::INT
                        );

                END CASE;
            END;

        WHEN 'BAJA' THEN
            INSERT INTO modulo2.eventos_bajas (
                id_evento,
                cantidad_afectada,
                detalles,
                tipo
            ) VALUES (
                v_id_evento,
                (p_datos_evento->>'cantidad_afectada')::INT,
                p_datos_evento->>'detalles',
                (p_datos_evento->>'tipo')::modulo2.enum_evento_bajas_tipo
            );

        ELSE
            RAISE EXCEPTION
                'Tipo de evento "%" no reconocido. '
                'Use: CRECIMIENTO, SANITARIO, PRODUCTIVO, REPRODUCTIVO, BAJA.',
                p_tipo_evento;
    END CASE;

    -- Auditoría
    CALL modulo1.sp_registrar_auditoria(
        p_responsable_id, NULL, 1, 'Modulo 2', 'EVENTOS',
        'Registro evento ' || p_tipo_evento || ' — activo ' || p_activo_id,
        'exitoso', 'ACTIVO',
        jsonb_build_object(
            'id_evento',   v_id_evento,
            'tipo_evento', p_tipo_evento,
            'id_activo',   p_activo_id
        )
    );
END;$$;


ALTER PROCEDURE modulo2.sp_registrar_evento_biologico(IN p_activo_id integer, IN p_tipo_evento text, IN p_fecha_evento timestamp with time zone, IN p_descripcion text, IN p_datos_evento jsonb, IN p_responsable_id integer) OWNER TO postgres;

--
-- Name: sp_registrar_evento_sanitario(integer, text, integer, text, character varying, numeric, character varying, integer, modulo2.enum_evento_sanitario_tipo, integer, text); Type: PROCEDURE; Schema: modulo2; Owner: postgres
--

CREATE PROCEDURE modulo2.sp_registrar_evento_sanitario(IN p_id_activo_biologico integer, IN p_descripcion text, IN p_id_usuario integer, IN p_diagnostico text, IN p_medicamento character varying DEFAULT NULL::character varying, IN p_dosis numeric DEFAULT NULL::numeric, IN p_unidad_dosis character varying DEFAULT NULL::character varying, IN p_frecuencia integer DEFAULT NULL::integer, IN p_tipo modulo2.enum_evento_sanitario_tipo DEFAULT NULL::modulo2.enum_evento_sanitario_tipo, IN p_duracion integer DEFAULT NULL::integer, IN p_observaciones text DEFAULT NULL::text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_evento INT;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM modulo2.activos_biologicos
        WHERE id_activo_biologico = p_id_activo_biologico
    ) THEN
        RAISE EXCEPTION
            'El activo biológico con ID % no existe.', p_id_activo_biologico;
    END IF;

    IF p_diagnostico IS NULL OR TRIM(p_diagnostico) = '' THEN
        RAISE EXCEPTION 'El diagnóstico es obligatorio.';
    END IF;

    IF p_medicamento IS NOT NULL AND TRIM(p_medicamento) <> '' THEN
        IF p_unidad_dosis IS NULL OR TRIM(p_unidad_dosis) = '' THEN
            RAISE EXCEPTION
                'Se debe especificar la unidad de dosis cuando se administra medicamento.';
        END IF;
        IF p_dosis IS NULL OR p_dosis <= 0 THEN
            RAISE EXCEPTION 'La dosis debe ser un valor positivo.';
        END IF;
    ELSE
        p_unidad_dosis := COALESCE(p_unidad_dosis, '');
    END IF;

    INSERT INTO modulo2.eventos_activos (
        id_activo_biologico, fecha, descripcion, id_usuario
    ) VALUES (
        p_id_activo_biologico, CURRENT_TIMESTAMP, p_descripcion, p_id_usuario
    )
    RETURNING id_eventos INTO v_id_evento;

    INSERT INTO modulo2.eventos_sanitarios (
        id_evento, diagnostico, medicamento, dosis,
        unidad_dosis, frecuencia, tipo, duracion, observaciones
    ) VALUES (
        v_id_evento, p_diagnostico, p_medicamento, p_dosis,
        p_unidad_dosis, p_frecuencia, p_tipo, p_duracion, p_observaciones
    );

    CALL modulo1.sp_registrar_auditoria(
        p_id_usuario, NULL, 1, 'Modulo 2', 'SANIDAD',
        'Registro de evento sanitario para activo ID: ' || p_id_activo_biologico,
        'exitoso', 'ACTIVO',
        jsonb_build_object(
            'id_evento',   v_id_evento,
            'diagnostico', p_diagnostico,
            'medicamento', p_medicamento,
            'tipo',        p_tipo,
            'duracion',    p_duracion
        )
    );
END;
$$;


ALTER PROCEDURE modulo2.sp_registrar_evento_sanitario(IN p_id_activo_biologico integer, IN p_descripcion text, IN p_id_usuario integer, IN p_diagnostico text, IN p_medicamento character varying, IN p_dosis numeric, IN p_unidad_dosis character varying, IN p_frecuencia integer, IN p_tipo modulo2.enum_evento_sanitario_tipo, IN p_duracion integer, IN p_observaciones text) OWNER TO postgres;

--
-- Name: sp_registrar_evento_sanitario_con_estado(integer, modulo2.enum_evento_sanitario_tipo, timestamp with time zone, jsonb, integer); Type: PROCEDURE; Schema: modulo2; Owner: postgres
--

CREATE PROCEDURE modulo2.sp_registrar_evento_sanitario_con_estado(IN p_activo_id integer, IN p_tipo_evento_sanitario modulo2.enum_evento_sanitario_tipo, IN p_fecha_evento timestamp with time zone, IN p_datos jsonb, IN p_responsable_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_estado_actual INT;
    v_nombre_estado    VARCHAR(25);
    v_id_evento        INT;
    v_estado_nuevo     VARCHAR(25);
BEGIN
    -- Validar existencia del activo
    IF NOT EXISTS (
        SELECT 1 FROM modulo2.activos_biologicos
        WHERE id_activo_biologico = p_activo_id
    ) THEN
        RAISE EXCEPTION
            'El activo biológico con ID % no existe.', p_activo_id;
    END IF;

    -- Fecha no futura
    IF p_fecha_evento > now() THEN
        RAISE EXCEPTION
            'La fecha del evento sanitario no puede ser futura.';
    END IF;

    -- Validar estado operativo
    v_id_estado_actual := modulo2.fn_obtener_estado_actual_activo(p_activo_id);

    SELECT nombre
    INTO   v_nombre_estado
    FROM   modulo2.estados_activos_biologicos
    WHERE  id_estado_activo_biologico = v_id_estado_actual;

    IF UPPER(v_nombre_estado) IN ('CERRADO', 'BAJA') THEN
        RAISE EXCEPTION
            'No se pueden registrar eventos sanitarios sobre el activo ID % '
            'en estado %.', p_activo_id, v_nombre_estado;
    END IF;

    -- Insertar evento base
    INSERT INTO modulo2.eventos_activos (
        id_activo_biologico, fecha, descripcion, id_usuario
    ) VALUES (
        p_activo_id,
        p_fecha_evento,
        COALESCE(
            p_datos->>'descripcion',
            'Evento sanitario: ' || p_tipo_evento_sanitario::TEXT
        ),
        p_responsable_id
    )
    RETURNING id_eventos INTO v_id_evento;

    -- Insertar detalle sanitario
    -- (trg_evento_sanitario_secuencia valida la secuencia de diagnóstico previo)
    INSERT INTO modulo2.eventos_sanitarios (
        id_evento,
        diagnostico,
        medicamento,
        dosis,
        unidad_dosis,
        frecuencia,
        tipo,
        duracion,
        observaciones
    ) VALUES (
        v_id_evento,
        p_datos->>'diagnostico',
        p_datos->>'medicamento',
        (p_datos->>'dosis')::NUMERIC(10,2),
        p_datos->>'unidad_dosis',
        (p_datos->>'frecuencia')::INT,
        p_tipo_evento_sanitario,
        (p_datos->>'duracion')::INT,
        p_datos->>'observaciones'
    );

    -- Determinar cambio de estado según tipo sanitario
    v_estado_nuevo := CASE p_tipo_evento_sanitario
        WHEN 'TRATAMIENTO'        THEN 'EN_TRATAMIENTO'
        WHEN 'CONTROL_PREVENTIVO' THEN 'AISLADO'
        ELSE NULL
    END;

    -- Aplicar cambio de estado si corresponde y si no es redundante
    IF v_estado_nuevo IS NOT NULL
       AND UPPER(v_nombre_estado) <> UPPER(v_estado_nuevo) THEN
        CALL modulo2.sp_cambiar_estado_activo(
            p_activo_id,
            v_estado_nuevo,
            p_fecha_evento,
            'Cambio automático por evento sanitario: ' || p_tipo_evento_sanitario::TEXT,
            p_responsable_id,
            'modulo2'
        );
    END IF;

    -- Auditoría
    CALL modulo1.sp_registrar_auditoria(
        p_responsable_id, NULL, 1, 'Modulo 2', 'SANIDAD',
        'Evento sanitario con evaluación de estado — activo ' || p_activo_id,
        'exitoso', 'ACTIVO',
        jsonb_build_object(
            'id_evento',         v_id_evento,
            'tipo_sanitario',    p_tipo_evento_sanitario,
            'estado_resultante', COALESCE(v_estado_nuevo, v_nombre_estado)
        )
    );
END;
$$;


ALTER PROCEDURE modulo2.sp_registrar_evento_sanitario_con_estado(IN p_activo_id integer, IN p_tipo_evento_sanitario modulo2.enum_evento_sanitario_tipo, IN p_fecha_evento timestamp with time zone, IN p_datos jsonb, IN p_responsable_id integer) OWNER TO postgres;

--
-- Name: sp_transferencia_interna(integer, integer, integer, integer, text); Type: PROCEDURE; Schema: modulo2; Owner: postgres
--

CREATE PROCEDURE modulo2.sp_transferencia_interna(IN p_id_activo_biologico integer, IN p_id_infraestructura_origen integer, IN p_id_infraestructura_destino integer, IN p_id_usuario integer, IN p_motivo text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF p_id_infraestructura_origen = p_id_infraestructura_destino THEN
        RAISE EXCEPTION
            'La infraestructura de origen y destino no pueden ser la misma.';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM modulo2.activos_biologicos
        WHERE  id_activo_biologico = p_id_activo_biologico
          AND  id_infraestructura  = p_id_infraestructura_origen
    ) THEN
        RAISE EXCEPTION
            'El activo no se encuentra en la infraestructura de origen indicada.';
    END IF;

    INSERT INTO modulo2.movimientos (
        id_usuario, fecha_transferencia, tipo,
        id_activo_biologico, id_infraestructura_origen,
        id_infraestructura_destino, fecha_registro
    ) VALUES (
        p_id_usuario, CURRENT_TIMESTAMP, 'salida',
        p_id_activo_biologico, p_id_infraestructura_origen,
        p_id_infraestructura_destino, CURRENT_TIMESTAMP
    );

	INSERT INTO modulo2.movimientos (
        id_usuario, fecha_transferencia, tipo,
        id_activo_biologico, id_infraestructura_origen,
        id_infraestructura_destino, fecha_registro
    ) VALUES (
        p_id_usuario, CURRENT_TIMESTAMP, 'entrada',
        p_id_activo_biologico, p_id_infraestructura_origen,
        p_id_infraestructura_destino, CURRENT_TIMESTAMP
    );

    UPDATE modulo2.activos_biologicos
    SET    id_infraestructura = p_id_infraestructura_destino
    WHERE  id_activo_biologico = p_id_activo_biologico;

    CALL modulo1.sp_registrar_auditoria(
        p_id_usuario, NULL, 4, 'Modulo 2', 'LOGISTICA',
        'Transferencia del activo ' || p_id_activo_biologico
            || ' desde ' || p_id_infraestructura_origen
            || ' hacia ' || p_id_infraestructura_destino,
        'exitoso', 'ACTIVO',
        jsonb_build_object(
            'origen', p_id_infraestructura_origen,
            'destino', p_id_infraestructura_destino,
            'motivo', p_motivo
        )
    );
END;
$$;


ALTER PROCEDURE modulo2.sp_transferencia_interna(IN p_id_activo_biologico integer, IN p_id_infraestructura_origen integer, IN p_id_infraestructura_destino integer, IN p_id_usuario integer, IN p_motivo text) OWNER TO postgres;

--
-- Name: sp_transferir_activo(integer, modulo2.enum_activo_biologico_tipo, integer, integer, timestamp with time zone, text, integer); Type: PROCEDURE; Schema: modulo2; Owner: postgres
--

CREATE PROCEDURE modulo2.sp_transferir_activo(IN p_activo_id integer, IN p_tipo_activo modulo2.enum_activo_biologico_tipo, IN p_infraestructura_origen integer, IN p_infraestructura_destino integer, IN p_fecha_transferencia timestamp with time zone, IN p_motivo text, IN p_responsable_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tipo_real        modulo2.enum_activo_biologico_tipo;
    v_id_estado_actual INT;
    v_nombre_estado    VARCHAR(25);
    v_infra_origen_ok  BOOL;
    v_infra_destino_ok BOOL;
BEGIN
    -- Validar existencia y obtener tipo real del activo
    SELECT tipo
    INTO   v_tipo_real
    FROM   modulo2.activos_biologicos
    WHERE  id_activo_biologico = p_activo_id;

    IF v_tipo_real IS NULL THEN
        RAISE EXCEPTION
            'El activo biológico con ID % no existe.', p_activo_id;
    END IF;

    -- Validar coherencia del tipo pasado como parámetro
    IF v_tipo_real <> p_tipo_activo THEN
        RAISE EXCEPTION
            'El tipo declarado (%) no coincide con el tipo registrado (%) '
            'del activo ID %.', p_tipo_activo, v_tipo_real, p_activo_id;
    END IF;

    -- Origen ≠ destino
    IF p_infraestructura_origen = p_infraestructura_destino THEN
        RAISE EXCEPTION
            'La infraestructura de origen y destino no pueden ser la misma.';
    END IF;

    -- Validar estado operativo del activo
    v_id_estado_actual := modulo2.fn_obtener_estado_actual_activo(p_activo_id);

    SELECT nombre
    INTO   v_nombre_estado
    FROM   modulo2.estados_activos_biologicos
    WHERE  id_estado_activo_biologico = v_id_estado_actual;

    IF UPPER(v_nombre_estado) IN ('CERRADO', 'BAJA') THEN
        RAISE EXCEPTION
            'No se puede transferir el activo ID % porque está en estado %.',
            p_activo_id, v_nombre_estado;
    END IF;

    -- Validar que ambas infraestructuras existen y están activas
    SELECT es_activo
    INTO   v_infra_origen_ok
    FROM   modulo9.infraestructuras
    WHERE  id_infraestructura = p_infraestructura_origen;

    IF v_infra_origen_ok IS NULL THEN
        RAISE EXCEPTION
            'La infraestructura de origen (ID %) no existe.', p_infraestructura_origen;
    END IF;
    IF v_infra_origen_ok = FALSE THEN
        RAISE EXCEPTION
            'La infraestructura de origen (ID %) está inactiva.', p_infraestructura_origen;
    END IF;

    SELECT es_activo
    INTO   v_infra_destino_ok
    FROM   modulo9.infraestructuras
    WHERE  id_infraestructura = p_infraestructura_destino;

    IF v_infra_destino_ok IS NULL THEN
        RAISE EXCEPTION
            'La infraestructura de destino (ID %) no existe.', p_infraestructura_destino;
    END IF;
    IF v_infra_destino_ok = FALSE THEN
        RAISE EXCEPTION
            'La infraestructura de destino (ID %) está inactiva.', p_infraestructura_destino;
    END IF;

    -- Validar que el activo está en la infraestructura de origen
    IF NOT EXISTS (
        SELECT 1 FROM modulo2.activos_biologicos
        WHERE  id_activo_biologico = p_activo_id
          AND  id_infraestructura  = p_infraestructura_origen
    ) THEN
        RAISE EXCEPTION
            'El activo ID % no se encuentra en la infraestructura de origen (ID %).',
            p_activo_id, p_infraestructura_origen;
    END IF;

    -- Registrar movimiento
    INSERT INTO modulo2.movimientos (
        id_usuario,
        fecha_transferencia,
        tipo,
        id_activo_biologico,
        id_infraestructura_origen,
        id_infraestructura_destino,
        fecha_registro
    ) VALUES (
        p_responsable_id,
        p_fecha_transferencia,
        'salida',
        p_activo_id,
        p_infraestructura_origen,
        p_infraestructura_destino,
        now()
    );

    -- Actualizar infraestructura del activo
    UPDATE modulo2.activos_biologicos
    SET    id_infraestructura = p_infraestructura_destino
    WHERE  id_activo_biologico = p_activo_id;

    -- Auditoría
    CALL modulo1.sp_registrar_auditoria(
        p_responsable_id, NULL, 4, 'Modulo 2', 'LOGISTICA',
        'Transferencia activo ' || p_activo_id
            || ' de infra ' || p_infraestructura_origen
            || ' a infra ' || p_infraestructura_destino,
        'exitoso', 'ACTIVO',
        jsonb_build_object(
            'id_activo',  p_activo_id,
            'origen',     p_infraestructura_origen,
            'destino',    p_infraestructura_destino,
            'motivo',     p_motivo
        )
    );
END;
$$;


ALTER PROCEDURE modulo2.sp_transferir_activo(IN p_activo_id integer, IN p_tipo_activo modulo2.enum_activo_biologico_tipo, IN p_infraestructura_origen integer, IN p_infraestructura_destino integer, IN p_fecha_transferencia timestamp with time zone, IN p_motivo text, IN p_responsable_id integer) OWNER TO postgres;

--
-- Name: trg_auditar_activo_biologico(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_auditar_activo_biologico() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_id_usuario INTEGER;
    v_campo TEXT;
    v_old_val JSONB;
    v_new_val JSONB;
    v_columnas TEXT[] := ARRAY[
        'id_especie', 'identificador', 'id_infraestructura', 'tipo',
        'fecha_inicio_ciclo', 'id_estado', 'descripcion', 'origen_financiero',
        'costo_adquisicion', 'atributos_dinamicos'
    ];
BEGIN
    BEGIN
        v_id_usuario := current_setting('app.usuario_id')::INTEGER;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'No se encontró app.usuario_id en la sesión. '
                        'El backend debe establecer esta variable.';
    END;

    IF TG_OP = 'INSERT' THEN
        INSERT INTO modulo2.auditoria_activos_biologicos (
            id_activo_biologico,
            id_usuario,
            campo_modificado,
            valor_anterior,
            valor_nuevo,
            fecha_cambio,
            modulo_origen
        ) VALUES (
            NEW.id_activo_biologico,
            v_id_usuario,
            'INSERT',
            '{}'::jsonb,
            to_jsonb(NEW),  -- Convierte toda la fila a JSONB
            now(),
            'modulo2'
        );
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        FOREACH v_campo IN ARRAY v_columnas
        LOOP
            -- Obtener valor anterior como JSONB
            EXECUTE format('SELECT to_jsonb($1.%I)', v_campo) INTO v_old_val USING OLD;
            -- Obtener valor nuevo como JSONB
            EXECUTE format('SELECT to_jsonb($1.%I)', v_campo) INTO v_new_val USING NEW;

            IF v_old_val IS DISTINCT FROM v_new_val THEN
                INSERT INTO modulo2.auditoria_activos_biologicos (
                    id_activo_biologico,
                    id_usuario,
                    campo_modificado,
                    valor_anterior,
                    valor_nuevo,
                    fecha_cambio,
                    modulo_origen
                ) VALUES (
                    NEW.id_activo_biologico,
                    v_id_usuario,
                    v_campo,
                    COALESCE(v_old_val, 'null'::jsonb),
                    COALESCE(v_new_val, 'null'::jsonb),
                    now(),
                    'modulo2'
                );
            END IF;
        END LOOP;
        RETURN NEW;
    END IF;

    RETURN NULL;
END;
$_$;


ALTER FUNCTION modulo2.trg_auditar_activo_biologico() OWNER TO postgres;

--
-- Name: trg_fn_activo_biologico_bloquear_cambio_estado_directo(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_activo_biologico_bloquear_cambio_estado_directo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- pg_trigger_depth() = 0 significa que el UPDATE viene directo del usuario
    -- pg_trigger_depth() > 0 significa que viene desde dentro de otro trigger (el sincronizador)
    IF pg_trigger_depth() = 1 THEN
        RAISE EXCEPTION
            'DIRECT_STATE_CHANGE: No se permite modificar id_estado directamente '
            'en activos_biologicos (activo ID %). Los cambios de estado deben '
            'registrarse mediante INSERT en historicos_estados_activos para '
            'garantizar trazabilidad RF-44.',
            OLD.id_activo_biologico
        USING ERRCODE = 'P0211';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_activo_biologico_bloquear_cambio_estado_directo() OWNER TO postgres;

--
-- Name: trg_fn_activo_biologico_coherencia_tipo(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_activo_biologico_coherencia_tipo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.tipo = 'INDIVIDUAL' THEN
        IF NEW.identificador IS NULL OR TRIM(NEW.identificador) = '' THEN
            RAISE EXCEPTION 'MISSING_FIELD: Para activos de tipo INDIVIDUAL el identificador es obligatorio.'
            USING ERRCODE = 'P0202';
        END IF;
    ELSIF NEW.tipo = 'POBLACIONAL' THEN
        IF NEW.identificador IS NOT NULL THEN
            RAISE EXCEPTION 'INVALID_COMBINATION: Para activos POBLACIONAL el identificador debe ser nulo.'
            USING ERRCODE = 'P0203';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_activo_biologico_coherencia_tipo() OWNER TO postgres;

--
-- Name: trg_fn_activo_biologico_estado_inicial(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_activo_biologico_estado_inicial() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_estado_activo INTEGER;
BEGIN
    SELECT id_estado_activo_biologico INTO v_id_estado_activo
    FROM modulo2.estados_activos_biologicos
    WHERE UPPER(nombre) = 'ACTIVO'
    LIMIT 1;

    IF v_id_estado_activo IS NULL THEN
        RAISE EXCEPTION 'CONFIG_ERROR: El estado ACTIVO no existe en el catálogo de estados del activo biológico.'
        USING ERRCODE = 'P0204';
    END IF;

    NEW.id_estado := v_id_estado_activo;
    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_activo_biologico_estado_inicial() OWNER TO postgres;

--
-- Name: trg_fn_activo_biologico_inmutabilidad(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_activo_biologico_inmutabilidad() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.tipo <> OLD.tipo THEN
        RAISE EXCEPTION 'IMMUTABLE_FIELD: El campo tipo del activo biológico no puede modificarse después del registro. Valor original: %.', OLD.tipo
        USING ERRCODE = 'P0208';
    END IF;

    IF NEW.id_especie <> OLD.id_especie THEN
        RAISE EXCEPTION 'IMMUTABLE_FIELD: La especie del activo biológico no puede modificarse después del registro.'
        USING ERRCODE = 'P0208';
    END IF;

    IF NEW.origen_financiero <> OLD.origen_financiero THEN
        RAISE EXCEPTION 'IMMUTABLE_FIELD: El campo origen_financiero no puede modificarse después del registro. Es base para la valoración contable.'
        USING ERRCODE = 'P0208';
    END IF;

    IF (NEW.costo_adquisicion IS DISTINCT FROM OLD.costo_adquisicion) THEN
        RAISE EXCEPTION 'IMMUTABLE_FIELD: El campo costo_adquisicion es inmutable. Representa el costo histórico pagado y es base de RF-82.'
        USING ERRCODE = 'P0208';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_activo_biologico_inmutabilidad() OWNER TO postgres;

--
-- Name: trg_fn_activo_biologico_no_delete(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_activo_biologico_no_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'NO_PHYSICAL_DELETE: Los activos biológicos no pueden eliminarse físicamente. Use la gestión de estados (BAJA) para retirar un activo del sistema. Activo ID: %.', OLD.id_activo_biologico
    USING ERRCODE = 'P0233';
    RETURN NULL;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_activo_biologico_no_delete() OWNER TO postgres;

--
-- Name: trg_fn_activo_biologico_origen_financiero(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_activo_biologico_origen_financiero() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.origen_financiero IN ('compra', 'donacion') THEN
        IF NEW.costo_adquisicion IS NULL OR NEW.costo_adquisicion <= 0 THEN
            RAISE EXCEPTION 'FINANCIAL_RULE: El origen financiero % exige un costo_adquisicion mayor a cero. Valor recibido: %.', NEW.origen_financiero, NEW.costo_adquisicion
            USING ERRCODE = 'P0205';
        END IF;
        IF NEW.soporte_documental IS NULL OR TRIM(NEW.soporte_documental) = '' THEN
            RAISE EXCEPTION 'FINANCIAL_RULE: El origen financiero % exige soporte documental registrado.', NEW.origen_financiero
            USING ERRCODE = 'P0205';
        END IF;
    ELSIF NEW.origen_financiero = 'nacimiento' THEN
        IF NEW.costo_adquisicion IS NOT NULL THEN
            RAISE EXCEPTION 'FINANCIAL_RULE: Para origen nacimiento el costo_adquisicion debe ser nulo. Valor recibido: %.', NEW.costo_adquisicion
            USING ERRCODE = 'P0206';
        END IF;
        IF NEW.soporte_documental IS NOT NULL THEN
            RAISE EXCEPTION 'FINANCIAL_RULE: Para origen nacimiento el soporte_documental debe ser nulo.'
            USING ERRCODE = 'P0206';
        END IF;
    ELSIF NEW.origen_financiero = 'transferencia_interna' THEN
        IF NEW.costo_adquisicion IS NOT NULL AND NEW.costo_adquisicion <= 0 THEN
            RAISE EXCEPTION 'FINANCIAL_RULE: Si se registra costo_adquisicion en transferencia_interna debe ser mayor a cero. Valor recibido: %.', NEW.costo_adquisicion
            USING ERRCODE = 'P0207';
        END IF;
        IF NEW.costo_adquisicion IS NOT NULL
           AND (NEW.soporte_documental IS NULL OR TRIM(NEW.soporte_documental) = '') THEN
            RAISE EXCEPTION 'FINANCIAL_RULE: Si se registra costo_adquisicion en transferencia_interna el soporte_documental es obligatorio.'
            USING ERRCODE = 'P0207';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_activo_biologico_origen_financiero() OWNER TO postgres;

--
-- Name: trg_fn_activo_fecha_inicio_valida(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_activo_fecha_inicio_valida() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.fecha_inicio_ciclo IS NULL THEN
        RAISE EXCEPTION 'MISSING_FIELD: El campo fecha_inicio_ciclo es obligatorio.'
        USING ERRCODE = 'P0232';
    END IF;
    IF NEW.fecha_inicio_ciclo < DATE '1970-01-01' THEN
        RAISE EXCEPTION 'INVALID_DATE: La fecha_inicio_ciclo no puede ser anterior a 1970-01-01.'
        USING ERRCODE = 'P0232';
    END IF;
    IF NEW.fecha_inicio_ciclo > CURRENT_DATE THEN
        RAISE EXCEPTION 'INVALID_DATE: La fecha_inicio_ciclo no puede ser posterior a la fecha actual del sistema.'
        USING ERRCODE = 'P0232';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_activo_fecha_inicio_valida() OWNER TO postgres;

--
-- Name: trg_fn_asociacion_sensor_activo_unica(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_asociacion_sensor_activo_unica() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    IF NEW.tipo = 'directa' THEN
        SELECT COUNT(*) INTO v_count
        FROM modulo2.asociaciones_activos_sensores
        WHERE id_sensor  = NEW.id_sensor
          AND fecha_fin  > now()
          AND tipo       = 'directa';

        IF v_count > 0 THEN
            RAISE EXCEPTION 'SENSOR_CONFLICT: El sensor ID % ya tiene una asociación directa activa con otro activo individual. Desactive la asociación existente antes de crear una nueva.', NEW.id_sensor
            USING ERRCODE = 'P0229';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_asociacion_sensor_activo_unica() OWNER TO postgres;

--
-- Name: trg_fn_auditoria_activos_inmutable(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_auditoria_activos_inmutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION 'IMMUTABLE_AUDIT: La bitácora de auditoría de activos biológicos es append-only. Operación UPDATE bloqueada sobre el registro ID %. Violación de integridad contable (NIC 41 / ICA).',
            OLD.id_auditoria_activo_biologico_individual
        USING ERRCODE = 'P0252';
    END IF;

    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'IMMUTABLE_AUDIT: Eliminación física prohibida en la bitácora de auditoría. Registro ID %. La cadena de custodia no puede romperse. Solo se permite archivar, nunca borrar.',
            OLD.id_auditoria_activo_biologico_individual
        USING ERRCODE = 'P0252';
    END IF;

    RETURN NULL;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_auditoria_activos_inmutable() OWNER TO postgres;

--
-- Name: trg_fn_baja_actualizar_cantidad_lote(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_baja_actualizar_cantidad_lote() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_activo_id   INTEGER;
    v_tipo_activo modulo2.enum_activo_biologico_tipo;
    v_infra_id    INTEGER;
    v_superficie  NUMERIC(10,2);
BEGIN
    SELECT a.id_activo_biologico, a.tipo, a.id_infraestructura
    INTO v_activo_id, v_tipo_activo, v_infra_id
    FROM modulo2.activos_biologicos a
    JOIN modulo2.eventos_activos ea ON ea.id_activo_biologico = a.id_activo_biologico
    WHERE ea.id_eventos = NEW.id_evento;

    IF v_tipo_activo <> 'poblacional' THEN
        RETURN NEW;
    END IF;

    SELECT superficie INTO v_superficie
    FROM modulo9.infraestructuras
    WHERE id_infraestructura = v_infra_id;

    UPDATE modulo2.detalles_activos_biologicos_poblacionales
    SET cantidad_actual = GREATEST(0, cantidad_actual - NEW.cantidad_afectada),
        biomasa_total   = GREATEST(0, cantidad_actual - NEW.cantidad_afectada) * peso_promedio,
        densidad        = CASE
                              WHEN v_superficie IS NOT NULL AND v_superficie > 0
                              THEN GREATEST(0, cantidad_actual - NEW.cantidad_afectada)::NUMERIC / v_superficie
                              ELSE 0
                          END
    WHERE id_activo_biologico = v_activo_id;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_baja_actualizar_cantidad_lote() OWNER TO postgres;

--
-- Name: trg_fn_baja_cantidad_valida(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_baja_cantidad_valida() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_activo_id      INTEGER;
    v_tipo_activo    modulo2.enum_activo_biologico_tipo;
    v_cantidad_actual INTEGER;
BEGIN
    SELECT a.id_activo_biologico, a.tipo
    INTO v_activo_id, v_tipo_activo
    FROM modulo2.activos_biologicos a
    JOIN modulo2.eventos_activos ea ON ea.id_activo_biologico = a.id_activo_biologico
    WHERE ea.id_eventos = NEW.id_evento;

    IF v_tipo_activo = 'poblacional' THEN
        IF NEW.cantidad_afectada IS NULL OR NEW.cantidad_afectada <= 0 THEN
            RAISE EXCEPTION 'INVALID_VALUE: Para bajas en lotes la cantidad_afectada debe ser mayor a cero. Valor recibido: %.', NEW.cantidad_afectada
            USING ERRCODE = 'P0224';
        END IF;

        SELECT cantidad_actual INTO v_cantidad_actual
        FROM modulo2.detalles_activos_biologicos_poblacionales
        WHERE id_activo_biologico = v_activo_id;

        IF NEW.cantidad_afectada > v_cantidad_actual THEN
            RAISE EXCEPTION 'INVENTORY_INCONSISTENCY: La cantidad a dar de baja (%) es superior a la existencia actual del lote (%). Activo ID %.', NEW.cantidad_afectada, v_cantidad_actual, v_activo_id
            USING ERRCODE = 'P0225';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_baja_cantidad_valida() OWNER TO postgres;

--
-- Name: trg_fn_estado_activo_no_baja_modify(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_estado_activo_no_baja_modify() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ultimo_estado VARCHAR(25);
BEGIN
    -- Si viene del sincronizador interno, permitir
    IF pg_trigger_depth() > 1 THEN
        RETURN NEW;
    END IF;

    SELECT e.nombre INTO v_ultimo_estado
    FROM modulo2.historicos_estados_activos h
    JOIN modulo2.estados_activos_biologicos e
        ON e.id_estado_activo_biologico = h.id_estado_nuevo
    WHERE h.id_activo_biologico = OLD.id_activo_biologico
    ORDER BY h.fecha_cambio DESC
    LIMIT 1;

    IF UPPER(v_ultimo_estado) = 'BAJA' THEN
        RAISE EXCEPTION 'FINAL_STATE: El activo biológico ID % se encuentra en estado BAJA definitivo. No se permiten modificaciones sobre activos dados de baja.', OLD.id_activo_biologico
        USING ERRCODE = 'P0213';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_estado_activo_no_baja_modify() OWNER TO postgres;

--
-- Name: trg_fn_estado_activo_transicion_valida(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_estado_activo_transicion_valida() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_nombre_anterior VARCHAR(25);
    v_nombre_nuevo    VARCHAR(25);
    v_historial_count INTEGER;
BEGIN
    -- modulo_origen obligatorio
    IF NEW.modulo_origen IS NULL OR TRIM(NEW.modulo_origen) = '' THEN
        RAISE EXCEPTION 'MISSING_FIELD: El campo modulo_origen es obligatorio para trazabilidad.'
        USING ERRCODE = 'P0211';
    END IF;

    SELECT nombre INTO v_nombre_anterior
    FROM modulo2.estados_activos_biologicos
    WHERE id_estado_activo_biologico = NEW.id_estado_anterior;

    SELECT nombre INTO v_nombre_nuevo
    FROM modulo2.estados_activos_biologicos
    WHERE id_estado_activo_biologico = NEW.id_estado_nuevo;

    -- Contar si existe algún historial previo para este activo (excluyendo el que se está insertando)
    SELECT COUNT(*) INTO v_historial_count
    FROM modulo2.historicos_estados_activos
    WHERE id_activo_biologico = NEW.id_activo_biologico;

    -- Si es el primer registro, permitir estado_anterior = estado_nuevo
    IF v_historial_count = 0 AND NEW.id_estado_anterior = NEW.id_estado_nuevo THEN
        RETURN NEW;
    END IF;

    -- Desde BAJA no se permite ninguna transición
    IF UPPER(v_nombre_anterior) = 'BAJA' THEN
        RAISE EXCEPTION 'INVALID_TRANSITION: El activo está en estado BAJA definitivo.'
        USING ERRCODE = 'P0211';
    END IF;

    -- Cambio redundante (solo si no es el primer registro)
    IF NEW.id_estado_anterior = NEW.id_estado_nuevo THEN
        RAISE EXCEPTION 'REDUNDANT_TRANSITION: El estado nuevo es igual al estado actual. No se realizó ningún cambio real.'
        USING ERRCODE = 'P0211';
    END IF;

    -- Matriz de transiciones
    IF NOT (
        (UPPER(v_nombre_anterior) = 'ACTIVO'           AND UPPER(v_nombre_nuevo) IN ('INACTIVO','EN_TRATAMIENTO','AISLADO','CERRADO','BAJA'))
        OR (UPPER(v_nombre_anterior) = 'INACTIVO'      AND UPPER(v_nombre_nuevo) IN ('ACTIVO','EN_TRATAMIENTO','CERRADO','BAJA'))
        OR (UPPER(v_nombre_anterior) = 'EN_TRATAMIENTO' AND UPPER(v_nombre_nuevo) IN ('ACTIVO','INACTIVO','AISLADO','CERRADO','BAJA'))
        OR (UPPER(v_nombre_anterior) = 'AISLADO'       AND UPPER(v_nombre_nuevo) IN ('ACTIVO','INACTIVO','EN_TRATAMIENTO','CERRADO','BAJA'))
        OR (UPPER(v_nombre_anterior) = 'CERRADO'       AND UPPER(v_nombre_nuevo) = 'BAJA')
    ) THEN
        RAISE EXCEPTION 'INVALID_TRANSITION: La transición de estado "%" → "%" no está permitida.', v_nombre_anterior, v_nombre_nuevo
        USING ERRCODE = 'P0211';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_estado_activo_transicion_valida() OWNER TO postgres;

--
-- Name: trg_fn_estado_activo_unico_vigente(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_estado_activo_unico_vigente() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ultimo_estado INTEGER;
BEGIN
    SELECT id_estado_nuevo INTO v_ultimo_estado
    FROM modulo2.historicos_estados_activos
    WHERE id_activo_biologico = NEW.id_activo_biologico
    ORDER BY fecha_cambio DESC
    LIMIT 1;

    -- El estado anterior declarado debe coincidir con el último estado registrado
    IF v_ultimo_estado IS NOT NULL AND v_ultimo_estado <> NEW.id_estado_anterior THEN
        RAISE EXCEPTION 'STATE_INCONSISTENCY: El estado anterior declarado (ID %) no coincide con el último estado registrado para el activo (ID %). El historial de estados está desincronizado.', NEW.id_estado_anterior, v_ultimo_estado
        USING ERRCODE = 'P0212';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_estado_activo_unico_vigente() OWNER TO postgres;

--
-- Name: trg_fn_evento_activo_estado_valido(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_evento_activo_estado_valido() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ultimo_estado VARCHAR(25);
BEGIN
    SELECT e.nombre INTO v_ultimo_estado
    FROM modulo2.historicos_estados_activos h
    JOIN modulo2.estados_activos_biologicos e
        ON e.id_estado_activo_biologico = h.id_estado_nuevo
    WHERE h.id_activo_biologico = NEW.id_activo_biologico
    ORDER BY h.fecha_cambio DESC
    LIMIT 1;

    -- Si no hay historial, leer el estado directo del activo
    IF v_ultimo_estado IS NULL THEN
        SELECT e.nombre INTO v_ultimo_estado
        FROM modulo2.activos_biologicos a
        JOIN modulo2.estados_activos_biologicos e
            ON e.id_estado_activo_biologico = a.id_estado
        WHERE a.id_activo_biologico = NEW.id_activo_biologico;
    END IF;

    IF UPPER(v_ultimo_estado) IN ('CERRADO', 'BAJA') THEN
        RAISE EXCEPTION 'INVALID_STATE: No es posible registrar eventos sobre el activo ID %. El activo se encuentra en estado %, el cual no permite nuevos registros. Estados válidos: ACTIVO, EN_TRATAMIENTO, AISLADO.', NEW.id_activo_biologico, v_ultimo_estado
        USING ERRCODE = 'P0214';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_evento_activo_estado_valido() OWNER TO postgres;

--
-- Name: trg_fn_evento_crecimiento_recalcular_metricas(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_evento_crecimiento_recalcular_metricas() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_activo_id   INTEGER;
    v_tipo_activo modulo2.enum_activo_biologico_tipo;
    v_infra_id    INTEGER;
    v_superficie  NUMERIC(10,2);
    v_cantidad    INTEGER;
BEGIN
    SELECT a.id_activo_biologico, a.tipo, a.id_infraestructura
    INTO v_activo_id, v_tipo_activo, v_infra_id
    FROM modulo2.activos_biologicos a
    JOIN modulo2.eventos_activos ev ON ev.id_activo_biologico = a.id_activo_biologico
    WHERE ev.id_eventos = NEW.id_evento;

    -- Solo aplica para lotes poblacionalES
    IF v_tipo_activo <> 'POBLACIONAL' THEN
        RETURN NEW;
    END IF;

    SELECT superficie INTO v_superficie
    FROM modulo9.infraestructuras
    WHERE id_infraestructura = v_infra_id;

    SELECT cantidad_actual INTO v_cantidad
    FROM modulo2.detalles_activos_biologicos_poblacionales
    WHERE id_activo_biologico = v_activo_id;

    -- Recalcular solo cuando el evento registra peso promedio del lote
    IF UPPER(NEW.tipo_medicion) = 'PESO' AND UPPER(NEW.tipo_agregacion) = 'PROMEDIO' THEN
        UPDATE modulo2.detalles_activos_biologicos_poblacionales
        SET peso_promedio = NEW.valor_medicion,
            biomasa_total = v_cantidad * NEW.valor_medicion,
            densidad      = CASE
                                WHEN v_superficie IS NOT NULL AND v_superficie > 0
                                THEN v_cantidad::NUMERIC / v_superficie
                                ELSE 0
                            END
        WHERE id_activo_biologico = v_activo_id;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_evento_crecimiento_recalcular_metricas() OWNER TO postgres;

--
-- Name: trg_fn_evento_crecimiento_tipo_activo(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_evento_crecimiento_tipo_activo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tipo_activo   modulo2.enum_activo_biologico_tipo;
    v_tipo_medicion VARCHAR(55);
    v_unidad        VARCHAR(5);
BEGIN
    SELECT a.tipo INTO v_tipo_activo
    FROM modulo2.activos_biologicos a
    JOIN modulo2.eventos_activos ev ON ev.id_activo_biologico = a.id_activo_biologico
    WHERE ev.id_eventos = NEW.id_evento;

    v_tipo_medicion := UPPER(TRIM(NEW.tipo_medicion));
    v_unidad        := LOWER(TRIM(NEW.unidad_medida));

    -- Validar tipo_agregacion según tipo de activo
    IF v_tipo_activo = 'INDIVIDUAL' THEN
        IF NEW.tipo_agregacion IS NOT NULL AND TRIM(NEW.tipo_agregacion) <> '' THEN
            RAISE EXCEPTION 'INVALID_FIELD: Para activos INDIVIDUALES el campo tipo_agregacion debe ser nulo o vacío.'
            USING ERRCODE = 'P0216';
        END IF;
    ELSIF v_tipo_activo = 'poblacional' THEN
        IF NEW.tipo_agregacion IS NULL OR TRIM(NEW.tipo_agregacion) = '' THEN
            RAISE EXCEPTION 'MISSING_FIELD: Para activos LOTE (poblacional) el campo tipo_agregacion es obligatorio.'
            USING ERRCODE = 'P0216';
        END IF;
    END IF;

    -- Validar valor positivo
    IF NEW.valor_medicion <= 0 THEN
        RAISE EXCEPTION 'INVALID_VALUE: El valor de medición debe ser positivo y mayor a cero. Valor recibido: %.', NEW.valor_medicion
        USING ERRCODE = 'P0217';
    END IF;

    -- Validar coherencia unidad / tipo de medición
    IF v_tipo_medicion = 'PESO' AND v_unidad NOT IN ('kg', 'g', 'lb') THEN
        RAISE EXCEPTION 'UNIT_MISMATCH: Para medición de PESO solo se permiten unidades: kg, g, lb. Unidad recibida: %.', NEW.unidad_medida
        USING ERRCODE = 'P0218';
    END IF;

    IF v_tipo_medicion IN ('TALLA', 'LONGITUD', 'ALTURA') AND v_unidad NOT IN ('cm', 'm') THEN
        RAISE EXCEPTION 'UNIT_MISMATCH: Para medición de TALLA/LONGITUD/ALTURA solo se permiten unidades: cm, m. Unidad recibida: %.', NEW.unidad_medida
        USING ERRCODE = 'P0218';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_evento_crecimiento_tipo_activo() OWNER TO postgres;

--
-- Name: trg_fn_evento_fecha_coherente(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_evento_fecha_coherente() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_fecha_creacion TIMESTAMPTZ;
BEGIN
    IF NEW.fecha > now() THEN
        RAISE EXCEPTION 'INVALID_DATE: La fecha del evento (%) no puede ser futura. Fecha actual del sistema: %.', NEW.fecha, now()
        USING ERRCODE = 'P0215';
    END IF;

    SELECT fecha_creacion INTO v_fecha_creacion
    FROM modulo2.activos_biologicos
    WHERE id_activo_biologico = NEW.id_activo_biologico;

    IF v_fecha_creacion IS NOT NULL AND NEW.fecha < v_fecha_creacion THEN
        RAISE EXCEPTION 'INVALID_DATE: La fecha del evento (%) no puede ser anterior a la fecha de registro del activo (%).', NEW.fecha, v_fecha_creacion
        USING ERRCODE = 'P0215';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_evento_fecha_coherente() OWNER TO postgres;

--
-- Name: trg_fn_evento_productivo_duplicado(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_evento_productivo_duplicado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_activo_id    INTEGER;
    v_fecha_evento TIMESTAMPTZ;
    v_count        INTEGER;
BEGIN
    SELECT ea.id_activo_biologico, ea.fecha
    INTO v_activo_id, v_fecha_evento
    FROM modulo2.eventos_activos ea
    WHERE ea.id_eventos = NEW.id_evento;

    SELECT COUNT(*) INTO v_count
    FROM modulo2.eventos_productivos ep
    JOIN modulo2.eventos_activos ea ON ea.id_eventos = ep.id_evento
    WHERE ea.id_activo_biologico = v_activo_id
      AND ep.id_metrica_produccion = NEW.id_metrica_produccion
      AND DATE(ea.fecha) = DATE(v_fecha_evento);

    IF v_count > 0 THEN
        RAISE EXCEPTION 'DUPLICATE_EVENT: Ya existe un evento productivo para la misma métrica (ID %) en el activo ID % en la fecha %. No se permiten registros duplicados.', NEW.id_metrica_produccion, v_activo_id, DATE(v_fecha_evento)
        USING ERRCODE = 'P0223';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_evento_productivo_duplicado() OWNER TO postgres;

--
-- Name: trg_fn_evento_reproductivo_secuencia(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_evento_reproductivo_secuencia() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_activo_id   INTEGER;
    v_tipo_activo modulo2.enum_activo_biologico_tipo;
    v_count_previo INTEGER;
BEGIN
    SELECT a.id_activo_biologico, a.tipo
    INTO v_activo_id, v_tipo_activo
    FROM modulo2.activos_biologicos a
    JOIN modulo2.eventos_activos ev ON ev.id_activo_biologico = a.id_activo_biologico
    WHERE ev.id_eventos = NEW.id_evento_reproductivo;

    -- Para LOTE: solo se permite nacimiento
    IF v_tipo_activo = 'POBLACIONAL' AND NEW.categoria NOT IN ('nacimiento') THEN
        RAISE EXCEPTION 'TYPE_RESTRICTION: Para activos de tipo LOTE (poblacional) solo se permite el evento reproductivo nacimiento. Categoría recibida: %.', NEW.categoria
        USING ERRCODE = 'P0220';
    END IF;

    IF v_tipo_activo = 'INDIVIDUAL' THEN
        -- parto requiere diagnostico positivo previo
        IF NEW.categoria = 'parto' THEN
            SELECT COUNT(*) INTO v_count_previo
            FROM modulo2.eventos_reproductivos er
            JOIN modulo2.eventos_activos ea ON ea.id_eventos = er.id_evento_reproductivo
            WHERE ea.id_activo_biologico = v_activo_id
              AND er.categoria = 'diagnostico'
              AND UPPER(er.resultado) LIKE '%POSITIV%';

            IF v_count_previo = 0 THEN
                RAISE EXCEPTION 'SEQUENCE_VIOLATION: No se puede registrar parto sin un evento previo de diagnostico positivo para el activo ID %.', v_activo_id
                USING ERRCODE = 'P0221';
            END IF;
        END IF;

        -- nacimiento requiere parto previo
        IF NEW.categoria = 'nacimiento' THEN
            SELECT COUNT(*) INTO v_count_previo
            FROM modulo2.eventos_reproductivos er
            JOIN modulo2.eventos_activos ea ON ea.id_eventos = er.id_evento_reproductivo
            WHERE ea.id_activo_biologico = v_activo_id
              AND er.categoria = 'parto';

            IF v_count_previo = 0 THEN
                RAISE EXCEPTION 'SEQUENCE_VIOLATION: No se puede registrar nacimiento sin un evento previo de parto para el activo ID %.', v_activo_id
                USING ERRCODE = 'P0221';
            END IF;
        END IF;

        -- Número de crías en parto o nacimiento debe ser >= 1
        IF NEW.categoria IN ('parto', 'nacimiento') AND NEW.numero_cria < 1 THEN
            RAISE EXCEPTION 'INVALID_VALUE: El número de crías en un evento de % debe ser mayor o igual a 1. Valor recibido: %.', NEW.categoria, NEW.numero_cria
            USING ERRCODE = 'P0222';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_evento_reproductivo_secuencia() OWNER TO postgres;

--
-- Name: trg_fn_evento_sanitario_secuencia(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_evento_sanitario_secuencia() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_activo_id         INTEGER;
    v_tiene_diagnosticoo INTEGER;
BEGIN
    SELECT id_activo_biologico INTO v_activo_id
    FROM modulo2.eventos_activos
    WHERE id_eventos = NEW.id_evento;

    -- Si el evento tiene medicamento y dosis es TRATAMIENTO o VACUNACION:
    -- requiere diagnosticoO previo (evento sanitario sin medicamento con diagnóstico)
    IF NEW.medicamento IS NOT NULL AND TRIM(NEW.medicamento) <> ''
       AND NEW.dosis IS NOT NULL AND NEW.dosis > 0 THEN

        SELECT COUNT(*) INTO v_tiene_diagnosticoo
        FROM modulo2.eventos_sanitarios es_prev
        JOIN modulo2.eventos_activos ea_prev ON ea_prev.id_eventos = es_prev.id_evento
        WHERE ea_prev.id_activo_biologico = v_activo_id
          AND es_prev.diagnostico IS NOT NULL
          AND TRIM(es_prev.diagnostico) <> ''
          AND es_prev.medicamento IS NULL
          AND ea_prev.fecha < (
              SELECT fecha FROM modulo2.eventos_activos WHERE id_eventos = NEW.id_evento
          );

        IF v_tiene_diagnosticoo = 0 THEN
            RAISE EXCEPTION 'SEQUENCE_VIOLATION: No se puede registrar TRATAMIENTO o VACUNACION sin un evento de diagnosticoO previo para el activo ID %.', v_activo_id
            USING ERRCODE = 'P0219';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_evento_sanitario_secuencia() OWNER TO postgres;

--
-- Name: trg_fn_eventos_activos_inmutable(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_eventos_activos_inmutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'IMMUTABLE_RECORD: Los eventos biológicos son inmutables una vez registrados. Operación % sobre tabla % bloqueada.', TG_OP, TG_TABLE_NAME
    USING ERRCODE = 'P0231';
    RETURN NULL;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_eventos_activos_inmutable() OWNER TO postgres;

--
-- Name: trg_fn_fase_activo_estado_valido(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_fase_activo_estado_valido() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ultimo_estado VARCHAR(25);
BEGIN
    SELECT e.nombre INTO v_ultimo_estado
    FROM modulo2.historicos_estados_activos h
    JOIN modulo2.estados_activos_biologicos e
        ON e.id_estado_activo_biologico = h.id_estado_nuevo
    WHERE h.id_activo_biologico = NEW.id_activo_biologico
    ORDER BY h.fecha_cambio DESC
    LIMIT 1;

    -- Fallback al estado directo del activo si no hay historial aún
    IF v_ultimo_estado IS NULL THEN
        SELECT e.nombre INTO v_ultimo_estado
        FROM modulo2.activos_biologicos a
        JOIN modulo2.estados_activos_biologicos e
            ON e.id_estado_activo_biologico = a.id_estado
        WHERE a.id_activo_biologico = NEW.id_activo_biologico;
    END IF;

    IF UPPER(v_ultimo_estado) IN ('CERRADO', 'BAJA') THEN
        RAISE EXCEPTION 'INVALID_STATE: No se puede registrar o cambiar una fase en el activo ID % porque se encuentra en estado %. Solo se permiten cambios de fase en activos operativos.', NEW.id_activo_biologico, v_ultimo_estado
        USING ERRCODE = 'P0228';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_fase_activo_estado_valido() OWNER TO postgres;

--
-- Name: trg_fn_fase_solapamiento(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_fase_solapamiento() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ultima_fecha_fin TIMESTAMPTZ;
    v_inicio_ts        TIMESTAMPTZ;
BEGIN
    IF (TG_OP = 'INSERT') OR (NEW.fecha_inicio <> OLD.fecha_inicio) THEN

        SELECT fecha_finalizacion INTO v_ultima_fecha_fin
        FROM   modulo2.gestiones_fases
        WHERE  id_activo_biologico = NEW.id_activo_biologico
          AND  es_activa           = FALSE
          AND  fecha_finalizacion  IS NOT NULL
          AND  id_gestion_fases   <> COALESCE(NEW.id_gestion_fases, -1)
        ORDER  BY fecha_finalizacion DESC
        LIMIT  1;

        v_inicio_ts := NEW.fecha_inicio::timestamptz;

        IF v_ultima_fecha_fin IS NOT NULL AND v_inicio_ts < v_ultima_fecha_fin THEN
            RAISE EXCEPTION
                'PHASE_OVERLAP: La fecha de inicio (%) es anterior a la finalización (%).',
                v_inicio_ts, v_ultima_fecha_fin
            USING ERRCODE = 'P0227';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_fase_solapamiento() OWNER TO postgres;

--
-- Name: trg_fn_fase_unica_activa(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_fase_unica_activa() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    -- Solo valida si la fase resultante va a quedar activa
    IF NEW.es_activa = TRUE THEN
        SELECT COUNT(*) INTO v_count
        FROM modulo2.gestiones_fases
        WHERE id_activo_biologico = NEW.id_activo_biologico
          AND es_activa           = TRUE
          AND id_gestion_fases   <> COALESCE(NEW.id_gestion_fases, -1); -- excluye el registro actual en UPDATE

        IF v_count > 0 THEN
            RAISE EXCEPTION 'UNIQUE_ACTIVE_PHASE: El activo biológico ID % ya tiene una fase productiva activa. Finalice la fase actual antes de iniciar una nueva.', NEW.id_activo_biologico
            USING ERRCODE = 'P0226';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_fase_unica_activa() OWNER TO postgres;

--
-- Name: trg_fn_historial_estados_inmutable(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_historial_estados_inmutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'IMMUTABLE_RECORD: El historial de estados del activo biológico es inmutable. Operación % bloqueada. El historial es append-only.', TG_OP
    USING ERRCODE = 'P0230';
    RETURN NULL;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_historial_estados_inmutable() OWNER TO postgres;

--
-- Name: trg_fn_poblacional_cantidad_inmutable(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_poblacional_cantidad_inmutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.cantidad_inicial <> OLD.cantidad_inicial THEN
        RAISE EXCEPTION 'IMMUTABLE_FIELD: El campo cantidad_inicial es inmutable y no puede modificarse después del registro del lote. Valor original: %.', OLD.cantidad_inicial
        USING ERRCODE = 'P0210';
    END IF;

    IF NEW.cantidad_actual < 0 THEN
        RAISE EXCEPTION 'INVALID_VALUE: La cantidad_actual del lote no puede ser negativa. Valor intentado: %.', NEW.cantidad_actual
        USING ERRCODE = 'P0210';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_poblacional_cantidad_inmutable() OWNER TO postgres;

--
-- Name: trg_fn_poblacional_inicializar_metricas(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_poblacional_inicializar_metricas() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.cantidad_inicial <= 0 THEN
        RAISE EXCEPTION 'INVALID_VALUE: La cantidad_inicial del lote debe ser mayor a cero. Valor recibido: %.', NEW.cantidad_inicial
        USING ERRCODE = 'P0209';
    END IF;

    -- Forzar cantidad_actual = cantidad_inicial en el registro inicial
    NEW.cantidad_actual := NEW.cantidad_inicial;

    IF NEW.cantidad_actual < 0 THEN
        RAISE EXCEPTION 'INVALID_VALUE: La cantidad_actual no puede ser negativa.'
        USING ERRCODE = 'P0209';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_poblacional_inicializar_metricas() OWNER TO postgres;

--
-- Name: trg_fn_sincronizar_estado_activo(); Type: FUNCTION; Schema: modulo2; Owner: postgres
--

CREATE FUNCTION modulo2.trg_fn_sincronizar_estado_activo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE modulo2.activos_biologicos
    SET id_estado = NEW.id_estado_nuevo
    WHERE id_activo_biologico = NEW.id_activo_biologico;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo2.trg_fn_sincronizar_estado_activo() OWNER TO postgres;

--
-- Name: fn_actualizar_estado_sensor(); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_actualizar_estado_sensor() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.estado_calidad <> 'LECTURA_VALIDA'::modulo3.enum_telemetria_estado_calidad THEN
        RETURN NEW;
    END IF;

    INSERT INTO modulo3.estados_actuales_sensores (
        id_dispositivo_iot, id_sensor,
        ultimo_valor, ultima_unidad, ultimo_timestamp_captura,
        ultimo_timestamp_actualizacion,
        estado_semaforo, estado_calidad, estado_conectividad, dato_desactualizado
    ) VALUES (
        NEW.id_dispositivo_iot, NEW.id_sensor,
        NEW.valor_ajustado, NEW.unidad_medida, NEW.timestamp_captura,
        now(),
        'VERDE', NEW.estado_calidad,
        CASE WHEN NEW.estado_conectividad
             THEN 'ACTIVO'::modulo3.enum_estado_dispositivo
             ELSE 'SIN_SEÑAL'::modulo3.enum_estado_dispositivo
        END,
        FALSE
    )
    ON CONFLICT (id_sensor) DO UPDATE SET
        id_dispositivo_iot             = EXCLUDED.id_dispositivo_iot,
        ultimo_valor                   = EXCLUDED.ultimo_valor,
        ultima_unidad                  = EXCLUDED.ultima_unidad,
        ultimo_timestamp_captura       = EXCLUDED.ultimo_timestamp_captura,
        ultimo_timestamp_actualizacion = now(),
        estado_semaforo                = EXCLUDED.estado_semaforo,
        estado_calidad                 = EXCLUDED.estado_calidad,
        estado_conectividad            = EXCLUDED.estado_conectividad,
        dato_desactualizado            = FALSE;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo3.fn_actualizar_estado_sensor() OWNER TO postgres;

--
-- Name: fn_alerta_activa_existe(integer, modulo3.enum_tipo_alerta, integer); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_alerta_activa_existe(p_id_sensor integer, p_tipo_alerta modulo3.enum_tipo_alerta, p_ventana_min integer DEFAULT 30) RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_id_alerta INTEGER;
BEGIN
    SELECT id_alerta INTO v_id_alerta
    FROM modulo3.alertas
    WHERE id_sensor   = p_id_sensor
      AND tipo_alerta = p_tipo_alerta
      AND estado_alerta IN ('ACTIVA','EN_ATENCION')
      AND fecha_registro >= NOW() - (p_ventana_min || ' minutes')::INTERVAL
    ORDER BY fecha_registro DESC
    LIMIT 1;
    RETURN v_id_alerta;
END;
$$;


ALTER FUNCTION modulo3.fn_alerta_activa_existe(p_id_sensor integer, p_tipo_alerta modulo3.enum_tipo_alerta, p_ventana_min integer) OWNER TO postgres;

--
-- Name: FUNCTION fn_alerta_activa_existe(p_id_sensor integer, p_tipo_alerta modulo3.enum_tipo_alerta, p_ventana_min integer); Type: COMMENT; Schema: modulo3; Owner: postgres
--

COMMENT ON FUNCTION modulo3.fn_alerta_activa_existe(p_id_sensor integer, p_tipo_alerta modulo3.enum_tipo_alerta, p_ventana_min integer) IS 'RF-57 Fase 4: Deduplicación de alertas en ventana temporal configurable.';


--
-- Name: fn_alerta_contenido_inmutable(); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_alerta_contenido_inmutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.tipo_alerta                IS DISTINCT FROM NEW.tipo_alerta                OR
       OLD.origen_evento              IS DISTINCT FROM NEW.origen_evento              OR
       OLD.id_telemetria              IS DISTINCT FROM NEW.id_telemetria              OR
       OLD.id_evento_edge_computing   IS DISTINCT FROM NEW.id_evento_edge_computing   OR
       OLD.fecha_evento               IS DISTINCT FROM NEW.fecha_evento               OR
       OLD.fecha_generacion           IS DISTINCT FROM NEW.fecha_generacion           OR
       OLD.id_sensor                  IS DISTINCT FROM NEW.id_sensor                  OR
       OLD.tipo_variable              IS DISTINCT FROM NEW.tipo_variable
    THEN
        RAISE EXCEPTION
            'RF-57 [INMUTABILIDAD]: Contenido histórico de id_alerta=% es inmutable.',
            OLD.id_alerta USING ERRCODE = 'P0006';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo3.fn_alerta_contenido_inmutable() OWNER TO postgres;

--
-- Name: fn_alerta_historico_inicial(); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_alerta_historico_inicial() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO modulo3.historico_estados_alertas (
        id_alerta, estado_anterior, estado_nuevo, motivo, fecha_cambio
    ) VALUES (
        NEW.id_alerta, NEW.estado_alerta, NEW.estado_alerta,
        'Alerta creada · origen=' || NEW.origen_evento::text,
        now()
    );
    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo3.fn_alerta_historico_inicial() OWNER TO postgres;

