CREATE FUNCTION modulo3.fn_alerta_no_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'RF-57 [INMUTABILIDAD]: Alertas no pueden eliminarse. id_alerta=%',
        OLD.id_alerta USING ERRCODE = 'P0007';
END;
$$;


ALTER FUNCTION modulo3.fn_alerta_no_delete() OWNER TO postgres;

--
-- Name: fn_alerta_set_vencimiento(); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_alerta_set_vencimiento() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.fecha_vencimiento IS NULL THEN
        NEW.fecha_vencimiento := NEW.fecha_generacion + CASE NEW.severidad
            WHEN 'CRITICO'  THEN INTERVAL '5 minutes'
            WHEN 'MODERADO' THEN INTERVAL '30 minutes'
            WHEN 'LEVE'     THEN INTERVAL '2 hours'
            ELSE                 INTERVAL '2 hours'
        END;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo3.fn_alerta_set_vencimiento() OWNER TO postgres;

--
-- Name: fn_alerta_validar_transicion(); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_alerta_validar_transicion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.estado_alerta = NEW.estado_alerta THEN
        RETURN NEW;
    END IF;

    IF NOT (
        (OLD.estado_alerta = 'ACTIVA'      AND NEW.estado_alerta IN ('EN_ATENCION','DESCARTADA','VENCIDA','PENDIENTE_SINCRONIZACION')) OR
        (OLD.estado_alerta = 'EN_ATENCION' AND NEW.estado_alerta IN ('RESUELTA','VENCIDA'))
    ) THEN
        RAISE EXCEPTION
            'RF-57 [TRANSICION_INVALIDA]: % → % no permitida. id_alerta=%',
            OLD.estado_alerta, NEW.estado_alerta, OLD.id_alerta
            USING ERRCODE = 'P0005';
    END IF;

    IF NEW.estado_alerta = 'EN_ATENCION' THEN
        NEW.fecha_atencion   := COALESCE(NEW.fecha_atencion, now());
    ELSIF NEW.estado_alerta IN ('RESUELTA','DESCARTADA','VENCIDA') THEN
        NEW.fecha_resolucion := COALESCE(NEW.fecha_resolucion, now());
    END IF;

    INSERT INTO modulo3.historico_estados_alertas (
        id_alerta, estado_anterior, estado_nuevo, id_usuario, motivo, fecha_cambio
    ) VALUES (
        NEW.id_alerta, OLD.estado_alerta, NEW.estado_alerta,
        COALESCE(NEW.id_usuario_resolucion, NEW.id_usuario_atencion),
        CASE NEW.estado_alerta
            WHEN 'VENCIDA'    THEN 'SLA vencido sin atención'
            WHEN 'DESCARTADA' THEN COALESCE(NEW.motivo_descarte, 'Descarte manual')
            WHEN 'RESUELTA'   THEN COALESCE(NEW.diagnostico, 'Resolución confirmada')
            ELSE NULL
        END,
        now()
    );
    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo3.fn_alerta_validar_transicion() OWNER TO postgres;

--
-- Name: fn_bitacora_telemetria_persistida(); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_bitacora_telemetria_persistida() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_severidad  modulo3.enum_bitacora_ingest_severidad;
    v_estado_cal modulo3.enum_bitacora_ingest_estado_calidad;
BEGIN
    -- Mapeo con valores reales del enum: INFO | EMERGENCY | CRITICAL | WARNING
    v_severidad := CASE NEW.estado_calidad
        WHEN 'LECTURA_VALIDA'    THEN 'INFO'
        WHEN 'FUERA_DE_RANGO'   THEN 'WARNING'
        WHEN 'ERROR_CALIBRACION' THEN 'WARNING'
        ELSE                          'CRITICAL'   -- ← corregido (antes era 'ERROR')
    END::modulo3.enum_bitacora_ingest_severidad;

    v_estado_cal := NEW.estado_calidad::text::modulo3.enum_bitacora_ingest_estado_calidad;

    INSERT INTO modulo3.bitacora_ingest (
        id_telemetria, id_sensor, id_dispositivo_iot,
        estado_calidad, descripcion_text, severidad,
        fecha_evento, fecha_captura_dato
    ) VALUES (
        NEW.id_telemetria, NEW.id_sensor, NEW.id_dispositivo_iot,
        v_estado_cal,
        'Telemetría persistida · estado=' || NEW.estado_calidad::text
            || ' · calibrado=' || NEW.calibrado::text
            || ' · origen='   || NEW.origen::text,
        v_severidad,
        now(),
        NEW.timestamp_captura
    );
    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo3.fn_bitacora_telemetria_persistida() OWNER TO postgres;

--
-- Name: fn_buffer_dato_inmutable(); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_buffer_dato_inmutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.payload_raw::text  <> NEW.payload_raw::text OR
       OLD.checksum_dato      <> NEW.checksum_dato     OR
       OLD.fecha_captura      <> NEW.fecha_captura     OR
       OLD.buffer_sequence_id <> NEW.buffer_sequence_id
    THEN
        RAISE EXCEPTION
            'RF-54 [INMUTABILIDAD]: payload_raw/checksum/fecha_captura/sequence_id son inmutables. id_buffer=%',
            OLD.id_buffer USING ERRCODE = 'P0004';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo3.fn_buffer_dato_inmutable() OWNER TO postgres;

--
-- Name: fn_buffer_marcar_sincronizacion(); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_buffer_marcar_sincronizacion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.estado_buffer = 'CONFIRMADO'::modulo3.enum_buffers_estado_buffer
       AND OLD.estado_buffer <> 'CONFIRMADO'::modulo3.enum_buffers_estado_buffer
    THEN
        NEW.fecha_sincornizacion := now();
    END IF;

    IF NEW.estado_buffer = 'ENVIADO'::modulo3.enum_buffers_estado_buffer
       AND OLD.estado_buffer IN (
           'PENDIENTE'::modulo3.enum_buffers_estado_buffer,
           'ERROR'::modulo3.enum_buffers_estado_buffer)
    THEN
        NEW.intentos_envio := OLD.intentos_envio + 1;
        NEW.ultimo_intento := now();
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo3.fn_buffer_marcar_sincronizacion() OWNER TO postgres;

--
-- Name: fn_buffer_solo_delete_confirmado(); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_buffer_solo_delete_confirmado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.estado_buffer IS DISTINCT FROM 'CONFIRMADO'::modulo3.enum_buffers_estado_buffer THEN
        RAISE EXCEPTION
            'RF-54 [INTEGRIDAD]: Solo se eliminan buffers CONFIRMADOS. id_buffer=% estado=%',
            OLD.id_buffer, OLD.estado_buffer
            USING ERRCODE = 'P0003';
    END IF;
    RETURN OLD;
END;
$$;


ALTER FUNCTION modulo3.fn_buffer_solo_delete_confirmado() OWNER TO postgres;

--
-- Name: fn_calcular_indice_calidad(integer); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_calcular_indice_calidad(p_id_telemetria integer) RETURNS TABLE(indice_calidad integer, clasificacion text, apto_ia boolean, apto_nic41 boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tel              modulo3.telemetrias%ROWTYPE;
    v_serie            NUMERIC[];
    v_media            NUMERIC;
    v_desv             NUMERIC;
    v_n_real           INTEGER;
    v_congelado        BOOLEAN := FALSE;
    v_congelado_sev    TEXT;
    v_outlier          BOOLEAN := FALSE;
    v_drift            BOOLEAN := FALSE;
    v_drift_pct        NUMERIC;
    v_gap_anomalo      BOOLEAN := FALSE;
    v_descuento        INTEGER := 0;
    v_cal_offset       NUMERIC;
    v_cal_ganancia     NUMERIC;
    v_cal_encontrada   BOOLEAN;
    v_val_calib_esp    NUMERIC;
    v_ultima_ts        TIMESTAMPTZ;
    v_gap_real_min     INTEGER;
    v_frecuencia_esp   INTEGER;
    v_rep_consecutivas INTEGER;
    v_flags            JSONB := '{}';
    v_indice           INTEGER;
BEGIN
    SELECT * INTO v_tel FROM modulo3.telemetrias WHERE id_telemetria = p_id_telemetria;
    IF NOT FOUND THEN
        RETURN QUERY SELECT NULL::INTEGER, 'INDETERMINADA'::TEXT, FALSE, FALSE;
        RETURN;
    END IF;

    -- Serie histórica reciente (20 lecturas)
    SELECT ARRAY(
        SELECT valor_crudo FROM modulo3.telemetrias
        WHERE id_sensor = v_tel.id_sensor AND id_variable = v_tel.id_variable
          AND estado_calidad NOT IN ('ERROR_SENSOR','ERROR_AUTENTICACION')
          AND timestamp_captura < v_tel.timestamp_captura
        ORDER BY timestamp_captura DESC LIMIT 20
    ) INTO v_serie;

    v_n_real := array_length(v_serie, 1);
    IF v_n_real < 5 THEN
        RETURN QUERY SELECT NULL::INTEGER, 'INDETERMINADA'::TEXT, FALSE, FALSE;
        RETURN;
    END IF;

    -- Media y desviación estándar
    SELECT AVG(x), STDDEV(x) INTO v_media, v_desv FROM unnest(v_serie) AS x;
    v_desv := COALESCE(v_desv, 0);

    -- Congelamiento (últimos 5 iguales)
    SELECT COUNT(*) INTO v_rep_consecutivas
    FROM (
        SELECT valor_crudo AS val, COUNT(*) AS n
        FROM (SELECT valor_crudo FROM modulo3.telemetrias
              WHERE id_sensor = v_tel.id_sensor AND id_variable = v_tel.id_variable
                AND estado_calidad NOT IN ('ERROR_SENSOR','ERROR_AUTENTICACION')
              ORDER BY timestamp_captura DESC LIMIT 5) sub
        GROUP BY valor_crudo HAVING COUNT(*) = 5
    ) eq;

    IF v_rep_consecutivas > 0 THEN
        v_congelado := TRUE;
        v_congelado_sev := CASE WHEN 5 >= 20 THEN 'CRITICO' WHEN 5 >= 10 THEN 'MODERADO' ELSE 'LEVE' END;
        v_descuento := v_descuento + CASE v_congelado_sev
            WHEN 'LEVE' THEN 15 WHEN 'MODERADO' THEN 35 ELSE 90 END;
    END IF;

    -- Outlier
    IF v_desv > 0 AND ABS(v_tel.valor_crudo - v_media) > 3.0 * v_desv THEN
        v_outlier := TRUE;
        v_descuento := v_descuento + 20;
    END IF;

    -- Drift respecto a calibración
    SELECT p_offset, p_ganancia, p_encontrado
    INTO v_cal_offset, v_cal_ganancia, v_cal_encontrada
    FROM modulo3.fn_obtener_calibracion(v_tel.id_sensor, v_tel.id_dispositivo_iot);
    IF v_cal_encontrada THEN
        v_val_calib_esp := (v_media * v_cal_ganancia) + v_cal_offset;
        IF v_val_calib_esp <> 0 THEN
            v_drift_pct := ABS((v_media - v_val_calib_esp) / v_val_calib_esp * 100);
            IF v_drift_pct > 5.0 THEN
                v_drift := TRUE;
                v_descuento := v_descuento + CASE
                    WHEN v_drift_pct < 10 THEN 10
                    WHEN v_drift_pct < 20 THEN 25 ELSE 40 END;
            END IF;
        END IF;
    END IF;

    -- Gap temporal
    SELECT MAX(timestamp_captura), MAX(COALESCE(frecuencia_muestreo_min, 10))
    INTO v_ultima_ts, v_frecuencia_esp
    FROM modulo3.telemetrias
    WHERE id_sensor = v_tel.id_sensor AND id_variable = v_tel.id_variable
      AND timestamp_captura < v_tel.timestamp_captura;

    IF v_ultima_ts IS NOT NULL THEN
        v_gap_real_min := EXTRACT(EPOCH FROM (v_tel.timestamp_captura - v_ultima_ts))::INTEGER / 60;
        IF v_gap_real_min > v_frecuencia_esp * 2 THEN
            v_gap_anomalo := TRUE;
            v_descuento := v_descuento + 10;
        END IF;
    END IF;

    v_indice := GREATEST(0, 100 - v_descuento);

    RETURN QUERY
        SELECT v_indice,
               CASE
                   WHEN v_indice >= 80 THEN 'APTO'
                   WHEN v_indice >= 40 THEN 'APTO_CON_RESERVA'
                   ELSE 'NO_APTO'
               END,
               v_indice >= 40,
               v_indice >= 80;
END;
$$;


ALTER FUNCTION modulo3.fn_calcular_indice_calidad(p_id_telemetria integer) OWNER TO postgres;

--
-- Name: fn_calcular_semaforo(numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_calcular_semaforo(p_valor numeric, p_umbral_min numeric, p_umbral_max numeric, p_tolerancia numeric DEFAULT NULL::numeric) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_tol NUMERIC;
BEGIN
    v_tol := COALESCE(p_tolerancia, (p_umbral_max - p_umbral_min) * 0.10);
    IF p_valor >= p_umbral_min AND p_valor <= p_umbral_max THEN
        RETURN 'VERDE';
    ELSIF p_valor >= (p_umbral_min - v_tol) AND p_valor <= (p_umbral_max + v_tol) THEN
        RETURN 'AMARILLO';
    ELSE
        RETURN 'ROJO';
    END IF;
END;
$$;


ALTER FUNCTION modulo3.fn_calcular_semaforo(p_valor numeric, p_umbral_min numeric, p_umbral_max numeric, p_tolerancia numeric) OWNER TO postgres;

