-- Name: FUNCTION fn_calcular_semaforo(p_valor numeric, p_umbral_min numeric, p_umbral_max numeric, p_tolerancia numeric); Type: COMMENT; Schema: modulo3; Owner: postgres
--

COMMENT ON FUNCTION modulo3.fn_calcular_semaforo(p_valor numeric, p_umbral_min numeric, p_umbral_max numeric, p_tolerancia numeric) IS 'RF-58 / RF-59: Calcula estado VERDE/AMARILLO/ROJO dado valor y umbrales.';


--
-- Name: fn_calcular_thi(numeric, numeric); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_calcular_thi(p_temperatura numeric, p_humedad numeric) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    -- THI = T - (0.55 - 0.0055 × HR) × (T - 14.5)
    RETURN p_temperatura
         - (0.55 - 0.0055 * p_humedad) * (p_temperatura - 14.5);
END;
$$;


ALTER FUNCTION modulo3.fn_calcular_thi(p_temperatura numeric, p_humedad numeric) OWNER TO postgres;

