--

COMMENT ON FUNCTION modulo3.fn_calcular_thi(p_temperatura numeric, p_humedad numeric) IS 'RF-55.2 / RF-57: Fórmula THI para detección de estrés térmico.';


--
-- Name: fn_cerrar_vinculacion_reemplazada(); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_cerrar_vinculacion_reemplazada() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE modulo3.vinculaciones_lecturas SET
        fecha_fin_vinculacion = NEW.fecha_inicio_vinculacion,
        estado_vinculacion    = 'CORREGIDA'::modulo3.enum_estado_vinculacion
    WHERE  id_vinculacion_lectura = NEW.id_vinculacion_remplazada
      AND  fecha_fin_vinculacion IS NULL;

    IF NOT FOUND THEN
        RAISE WARNING 'RF-61: Vinculación a reemplazar id=% no existe o ya está cerrada.',
            NEW.id_vinculacion_remplazada;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo3.fn_cerrar_vinculacion_reemplazada() OWNER TO postgres;

--
-- Name: fn_clasificar_severidad(numeric); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_clasificar_severidad(p_pct_desviacion numeric) RETURNS modulo3.enum_buffer_nivel_severidad
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    IF    p_pct_desviacion <= 10  THEN RETURN 'LEVE';
    ELSIF p_pct_desviacion <= 25  THEN RETURN 'MODERADO';
    ELSE                               RETURN 'CRITICO';
    END IF;
END;
$$;


ALTER FUNCTION modulo3.fn_clasificar_severidad(p_pct_desviacion numeric) OWNER TO postgres;

