-- Name: FUNCTION fn_clasificar_severidad(p_pct_desviacion numeric); Type: COMMENT; Schema: modulo3; Owner: postgres
--

COMMENT ON FUNCTION modulo3.fn_clasificar_severidad(p_pct_desviacion numeric) IS 'RF-55.1: LEVE ≤10%, MODERADO ≤25%, CRITICO >25% de desviación.';


--
-- Name: fn_crear_paquete_inferencia(); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_crear_paquete_inferencia() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tipo_variable VARCHAR(50);
    v_valor         NUMERIC(12,4);
    v_estado_desv   modulo3.enum_tipo_evento_edge;
BEGIN
    -- Solo procesar si llegó al backend
    IF NEW.enviado_backend = FALSE THEN
        RETURN NEW;
    END IF;

    -- Solo ciertos tipos de evento generan paquete
    IF NEW.tipo_evento NOT IN (
        'ALERTA_GENERADA'::modulo3.enum_eventos_edge_computing_tipo_evento,
        'DATOS_PROCESADOS'::modulo3.enum_eventos_edge_computing_tipo_evento
    ) THEN
        RETURN NEW;
    END IF;

    -- Mapeo de tipo_evento → estado_desviacion
    v_estado_desv := CASE NEW.tipo_evento
        WHEN 'ALERTA_GENERADA' THEN
            CASE WHEN json_array_length(NEW.variables_involucradas) > 1
                THEN 'DESVIACION_COMPUESTA'
                ELSE 'DESVIACION_SIMPLE'
            END
        WHEN 'DATOS_PROCESADOS' THEN 'NORMAL'
        ELSE 'NORMAL'
    END::modulo3.enum_tipo_evento_edge;

    -- Extraer tipo_variable del primer elemento de variables_involucradas
    BEGIN
        v_tipo_variable := NEW.variables_involucradas::json -> 0 ->> 'tipo_variable';
        v_valor         := NEW.valor_evaluado;
    EXCEPTION WHEN OTHERS THEN
        v_tipo_variable := 'DESCONOCIDO';
        v_valor         := COALESCE(NEW.valor_evaluado, 0);
    END;

    INSERT INTO modulo3.paquetes_inferencia (
        id_sensor,
        id_dispositivo_iot,
        id_evento_edge_computing,
        tipo_variable,
        valor_numerico,
        estado_calidad,
        estado_desviacion,
        severidad,
        origen,
        contexto_incomplento,
        fecha_envio,
        estado_paquete,
        intento_envios
    ) VALUES (
        NEW.id_sensor,
        NEW.id_dispositivo_iot,
        NEW.id_evento_edge_computing,
        COALESCE(v_tipo_variable, 'DESCONOCIDO'),
        COALESCE(v_valor, 0),
        'LECTURA_VALIDA'::modulo3.enum_bitacora_ingest_estado_calidad,
        v_estado_desv,
        NEW.severidad,
        NEW.origen_dato::modulo3.enum_origen_dato,
        FALSE,
        now(),
        'PENDIENTE'::modulo3.enum_estado_paquete_inferencia,
        0
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo3.fn_crear_paquete_inferencia() OWNER TO postgres;

--
-- Name: fn_es_duplicado(integer, integer, timestamp with time zone, modulo3.enum_telemetria_origen); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_es_duplicado(p_id_sensor integer, p_id_variable integer, p_timestamp_captura timestamp with time zone, p_origen modulo3.enum_telemetria_origen) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_count
    FROM modulo3.telemetrias
    WHERE id_sensor        = p_id_sensor
      AND id_variable      = p_id_variable
      AND timestamp_captura = p_timestamp_captura
      AND origen           = p_origen;
    RETURN v_count > 0;
END;
$$;


ALTER FUNCTION modulo3.fn_es_duplicado(p_id_sensor integer, p_id_variable integer, p_timestamp_captura timestamp with time zone, p_origen modulo3.enum_telemetria_origen) OWNER TO postgres;

--
-- Name: FUNCTION fn_es_duplicado(p_id_sensor integer, p_id_variable integer, p_timestamp_captura timestamp with time zone, p_origen modulo3.enum_telemetria_origen); Type: COMMENT; Schema: modulo3; Owner: postgres
--

COMMENT ON FUNCTION modulo3.fn_es_duplicado(p_id_sensor integer, p_id_variable integer, p_timestamp_captura timestamp with time zone, p_origen modulo3.enum_telemetria_origen) IS 'RF-53 Fase 6: Verifica clave compuesta (sensor, variable, timestamp, origen).';


--
-- Name: fn_evaluar_umbral_edge(integer, numeric, timestamp with time zone); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_evaluar_umbral_edge(p_id_sensor integer, p_valor numeric, p_timestamp_captura timestamp with time zone DEFAULT now()) RETURNS TABLE(id_evento integer, severidad modulo3.enum_buffer_nivel_severidad, mensaje text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_regla           RECORD;
    v_umbral_min      NUMERIC;
    v_umbral_max      NUMERIC;
    v_desviacion      NUMERIC;
    v_severidad       modulo3.enum_buffer_nivel_severidad;
    v_evento_id       INTEGER;
    v_edge_tipo       modulo3.enum_tipo_evento_edge;
    v_id_dispositivo  INTEGER;
    v_variables_json  json;
BEGIN
    -- Obtener el dispositivo asociado al sensor
    SELECT s.id_dispositivo_iot INTO v_id_dispositivo
    FROM modulo9.sensores s
    WHERE s.id_sensores = p_id_sensor AND s.es_activo = TRUE;

    IF v_id_dispositivo IS NULL THEN
        RETURN QUERY SELECT NULL::INTEGER,
                            'LEVE'::modulo3.enum_buffer_nivel_severidad,
                            'Sensor no encontrado o inactivo'::TEXT;
        RETURN;
    END IF;

    -- Recorrer reglas activas con ejecución en Edge
    FOR v_regla IN
        SELECT ra.*
        FROM modulo3.reglas_alertas ra
        WHERE ra.es_activa         = TRUE
          AND ra.tiene_ejecutar_edge = TRUE
          AND ra.umbral_min IS NOT NULL
          AND ra.umbral_max IS NOT NULL
    LOOP
        v_umbral_min := v_regla.umbral_min;
        v_umbral_max := v_regla.umbral_max;

        -- Calcular desviación porcentual
        v_desviacion := modulo3.fn_porcentaje_desviacion(p_valor, v_umbral_min, v_umbral_max);

        -- Determinar severidad preliminar
        IF v_desviacion < 0 THEN
            v_severidad := 'LEVE'::modulo3.enum_buffer_nivel_severidad;
        ELSE
            v_severidad := modulo3.fn_clasificar_severidad(v_desviacion);
        END IF;

        -- Determinar el tipo de evento edge
        v_edge_tipo := CASE
            WHEN v_desviacion = 0 THEN 'NORMAL'::modulo3.enum_tipo_evento_edge
            WHEN v_desviacion > 0 THEN 'DESVIACION_SIMPLE'::modulo3.enum_tipo_evento_edge
            ELSE 'ERROR_CONFIGURACION'::modulo3.enum_tipo_evento_edge
        END;

        -- Construir JSON con variables involucradas
        v_variables_json := json_build_array(
            json_build_object(
                'tipo_variable', v_regla.tipo_sensor::text,
                'umbral_min', v_umbral_min,
                'umbral_max', v_umbral_max
            )
        );

        -- Llamar al procedimiento estándar
        CALL modulo3.sp_registrar_evento_edge(
            p_id_dispositivo        => v_id_dispositivo,
            p_id_sensor             => p_id_sensor,
            p_tipo_evento           => v_edge_tipo,
            p_valor_evaluado        => p_valor,
            p_umbral_min            => v_umbral_min,
            p_umbral_max            => v_umbral_max,
            p_id_regla_alerta       => v_regla.id_regla_alertas,
            p_variables_involucradas => v_variables_json,
            p_origen_dato           => 'TIEMPO_REAL'::modulo3.enum_origen_dato,
            p_estado_conectividad   => TRUE,
            p_metadatos             => '{}'::JSONB,
            p_id_evento             => v_evento_id,
            p_severidad             => v_severidad
        );

        -- Registrar en bitácora si la severidad lo amerita
        IF v_severidad >= 'MODERADO'::modulo3.enum_buffer_nivel_severidad THEN
            PERFORM modulo3.fn_registrar_bitacora(
                NULL,
                p_id_sensor,
                v_id_dispositivo,
                'ALERTA_GENERADA'::modulo3.enum_eventos_edge_computing_tipo_evento,
                'LECTURA_VALIDA'::modulo3.enum_bitacora_ingest_estado_calidad,
                format('Regla %s superada, severidad %s', v_regla.nombre, v_severidad),
                jsonb_build_object(
                    'regla', v_regla.nombre,
                    'tipo_sensor', v_regla.tipo_sensor,
                    'valor', p_valor,
                    'desviacion', round(v_desviacion, 2)
                ),
                CASE v_severidad
                    WHEN 'MODERADO' THEN 'WARNING'::modulo3.enum_bitacora_ingest_severidad
                    WHEN 'CRITICO' THEN 'CRITICAL'::modulo3.enum_bitacora_ingest_severidad
                    ELSE 'INFO'::modulo3.enum_bitacora_ingest_severidad
                END
            );
        END IF;

        -- Devolver el primer evento generado
        RETURN QUERY SELECT v_evento_id,
                            v_severidad,
                            format('Regla %s aplicada, desviación %s%%', v_regla.nombre, to_char(v_desviacion, 'FM990.00'));
        RETURN;
    END LOOP;

    -- Si ninguna regla se activó
    RETURN QUERY SELECT NULL::INTEGER,
                        'LEVE'::modulo3.enum_buffer_nivel_severidad,
                        'Sin regla aplicable'::TEXT;
END;
$$;


