--
-- Name: fn_ingesta_telemetria(integer, integer, integer, numeric, character varying, timestamp with time zone, timestamp with time zone, modulo3.enum_telemetria_origen, modulo3.enum_telemetria_categoria_variable, modulo3.enum_telemetria_tipo_dato, boolean, integer, numeric, numeric, numeric, numeric, numeric, boolean, jsonb); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_ingesta_telemetria(p_id_dispositivo integer, p_id_sensor integer, p_id_variable integer, p_valor_crudo numeric, p_unidad character varying, p_timestamp_captura timestamp with time zone, p_timestamp_envio timestamp with time zone, p_origen modulo3.enum_telemetria_origen, p_categoria_variable modulo3.enum_telemetria_categoria_variable, p_tipo_dato modulo3.enum_telemetria_tipo_dato, p_valor_agregado boolean, p_ventana_agregacion integer, p_latitud numeric, p_longitud numeric, p_nivel_bateria numeric, p_calidad_rssi numeric, p_calidad_snr numeric, p_estado_conectividad boolean, p_metadatos jsonb) RETURNS TABLE(id_telemetria integer, estado_calidad modulo3.enum_telemetria_estado_calidad, mensaje text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ts_procesamiento   TIMESTAMPTZ := NOW();
    v_valor_ajustado     NUMERIC(10,4);
    v_calibrado          BOOLEAN := FALSE;
    v_offset             NUMERIC;
    v_ganancia           NUMERIC;
    v_cal_encontrada     BOOLEAN;
    v_umbral_min         NUMERIC(8,2);
    v_umbral_max         NUMERIC(8,2);
    v_frecuencia_esp     INTEGER := NULL;   -- columna no disponible
    v_unidad_esperada    VARCHAR(10);
    v_latencia_ms        INTEGER;
    v_latencia_alta      BOOLEAN := FALSE;
    v_dato_buferizado    BOOLEAN;
    v_estado             modulo3.enum_telemetria_estado_calidad := 'LECTURA_VALIDA'::modulo3.enum_telemetria_estado_calidad;
    v_mensaje            TEXT := 'OK';
    vid_telemetria       INTEGER;
    -- valores por omisión internos
    v_tipo_dato           modulo3.enum_telemetria_tipo_dato;
    v_valor_agregado      BOOLEAN;
    v_ventana_agregacion  INTEGER;
    v_lat                NUMERIC;
    v_lon                NUMERIC;
    v_bateria            NUMERIC;
    v_rssi               NUMERIC;
    v_snr                NUMERIC;
    v_conectividad       BOOLEAN;
    v_metadatos          JSONB;
BEGIN
    v_tipo_dato          := COALESCE(p_tipo_dato, 'CRUDO'::modulo3.enum_telemetria_tipo_dato);
    v_valor_agregado     := COALESCE(p_valor_agregado, FALSE);
    v_ventana_agregacion := p_ventana_agregacion;
    v_lat                := p_latitud;
    v_lon                := p_longitud;
    v_bateria            := p_nivel_bateria;
    v_rssi               := p_calidad_rssi;
    v_snr                := p_calidad_snr;
    v_conectividad       := COALESCE(p_estado_conectividad, TRUE);
    v_metadatos          := COALESCE(p_metadatos, '{}'::JSONB);

    -- Fase 0: latencia
    v_latencia_ms   := EXTRACT(EPOCH FROM (v_ts_procesamiento - p_timestamp_envio))::INTEGER * 1000;
    v_latencia_alta := v_latencia_ms > 2000;

    -- Fase 1: validación estructural
    IF p_id_dispositivo IS NULL OR p_id_sensor IS NULL OR p_id_variable IS NULL
       OR p_valor_crudo IS NULL OR p_unidad IS NULL OR p_timestamp_captura IS NULL THEN
        RETURN QUERY SELECT NULL::INTEGER, NULL::modulo3.enum_telemetria_estado_calidad,
                            'ERROR_ESTRUCTURA: Campos obligatorios faltantes.'::TEXT;
        RETURN;
    END IF;

    -- Fase 2: autenticación
    IF NOT modulo3.fn_validar_dispositivo(p_id_dispositivo, p_id_sensor) THEN
        RETURN QUERY SELECT NULL::INTEGER, NULL::modulo3.enum_telemetria_estado_calidad,
                            'ERROR_AUTENTICACION: Dispositivo o sensor no activo.'::TEXT;
        RETURN;
    END IF;

    -- Fase 3: coherencia temporal
    IF p_timestamp_captura > v_ts_procesamiento THEN
        RETURN QUERY SELECT NULL::INTEGER, NULL::modulo3.enum_telemetria_estado_calidad,
                            'ERROR_TIEMPO: timestamp_captura futuro.'::TEXT;
        RETURN;
    END IF;

    v_dato_buferizado := (p_origen = 'BUFFER_LOCAL');
    IF v_dato_buferizado AND p_timestamp_captura < v_ts_procesamiento - INTERVAL '72 hours' THEN
        RETURN QUERY SELECT NULL::INTEGER, NULL::modulo3.enum_telemetria_estado_calidad,
                            'ERROR_TIEMPO: Dato buffer > 72h.'::TEXT;
        RETURN;
    END IF;

    -- Fase 4: unidad y rango (NO leemos frecuencia_muestreo porque no existe)
    SELECT va.unidad, ua.valor_min, ua.valor_max
    INTO v_unidad_esperada, v_umbral_min, v_umbral_max
    FROM modulo9.variables_ambientales va
    LEFT JOIN modulo9.umbrales_ambientales ua ON ua.id_variable_ambiental = va.id_variable_ambiental
    WHERE va.id_variable_ambiental = p_id_variable AND va.es_activo = TRUE
    LIMIT 1;

    IF v_unidad_esperada IS NOT NULL AND LOWER(p_unidad) <> LOWER(v_unidad_esperada) THEN
        RETURN QUERY SELECT NULL::INTEGER, NULL::modulo3.enum_telemetria_estado_calidad,
                            'ERROR_UNIDAD: Unidad incorrecta.'::TEXT;
        RETURN;
    END IF;

    -- Fase 5: valor físicamente imposible
    IF v_umbral_min IS NOT NULL AND v_umbral_max IS NOT NULL THEN
        IF p_valor_crudo > v_umbral_max * 5 OR p_valor_crudo < v_umbral_min * 5 * -1 THEN
            RETURN QUERY SELECT NULL::INTEGER, NULL::modulo3.enum_telemetria_estado_calidad,
                                'ERROR_SENSOR: Valor físicamente imposible.'::TEXT;
            RETURN;
        END IF;
    END IF;

    -- Fase 6: duplicados
    IF modulo3.fn_es_duplicado(p_id_sensor, p_id_variable, p_timestamp_captura, p_origen) THEN
        RETURN QUERY SELECT NULL::INTEGER, NULL::modulo3.enum_telemetria_estado_calidad,
                            'ERROR_DUPLICADO: Registro ya existe.'::TEXT;
        RETURN;
    END IF;

    -- Fase 7: calibración
    SELECT p_offset, p_ganancia, p_encontrado
    INTO v_offset, v_ganancia, v_cal_encontrada
    FROM modulo3.fn_obtener_calibracion(p_id_sensor, p_id_dispositivo);

    IF v_cal_encontrada THEN
        v_valor_ajustado := (p_valor_crudo * v_ganancia) + v_offset;
        v_calibrado      := TRUE;
    ELSE
        v_valor_ajustado := p_valor_crudo;
        v_calibrado      := FALSE;
        v_estado         := 'ERROR_CALIBRACION'::modulo3.enum_telemetria_estado_calidad;
        v_mensaje        := 'Sin calibración – se usa valor crudo.';
    END IF;

    -- Evaluar FUERA_DE_RANGO
    IF v_umbral_min IS NOT NULL AND v_umbral_max IS NOT NULL THEN
        IF v_valor_ajustado < v_umbral_min OR v_valor_ajustado > v_umbral_max THEN
            IF v_estado = 'LECTURA_VALIDA'::modulo3.enum_telemetria_estado_calidad THEN
                v_estado  := 'FUERA_DE_RANGO'::modulo3.enum_telemetria_estado_calidad;
                v_mensaje := 'Valor fuera de rango operativo.';
            END IF;
        END IF;
    END IF;

    -- Fase 8: dato agregado sin ventana
    IF v_valor_agregado AND v_ventana_agregacion IS NULL THEN
        RETURN QUERY SELECT NULL::INTEGER, NULL::modulo3.enum_telemetria_estado_calidad,
                            'ERROR_ESTRUCTURA: Agregado sin ventana.'::TEXT;
        RETURN;
    END IF;

    -- Fase 9: persistencia
    INSERT INTO modulo3.telemetrias (
        id_sensor, id_variable, id_dispositivo_iot,
        valor_crudo, valor_ajustado,
        timestamp_captura, timestamp_envio, timestamp_procesamiento,
        origen, estado_calidad, calibrado,
        latitud, longitud, metadatos,
        categoria_variable, unidad_medida,
        valor_agregado, ventana_agregacion_min,
        tipo_dato,
        latencia_alta, frecuencia_anomala,
        posible_drift, dato_buferizado,
        dato_agredado_edge, reloj_desincronizado,
        latencia_procesamiento_ms,
        nivel_bateria_pct, calidad_senal_rssi, calidad_senal_snr,
        frecuencia_muestreo_min, estado_conectividad
    )
    VALUES (
        p_id_sensor, p_id_variable, p_id_dispositivo,
        p_valor_crudo, v_valor_ajustado,
        p_timestamp_captura, p_timestamp_envio, v_ts_procesamiento,
        p_origen, v_estado, v_calibrado,
        v_lat, v_lon, v_metadatos,
        p_categoria_variable, p_unidad,
        v_valor_agregado, v_ventana_agregacion,
        v_tipo_dato,
        v_latencia_alta, FALSE,
        FALSE, v_dato_buferizado,
        (v_tipo_dato = 'EVENTO_EDGE'), FALSE,
        v_latencia_ms,
        v_bateria, v_rssi, v_snr,
        v_frecuencia_esp,  -- será NULL, lo que es válido
        v_conectividad
    )
    RETURNING telemetrias.id_telemetria INTO vid_telemetria;

    RETURN QUERY SELECT vid_telemetria, v_estado, v_mensaje;
END;
$$;


ALTER FUNCTION modulo3.fn_ingesta_telemetria(p_id_dispositivo integer, p_id_sensor integer, p_id_variable integer, p_valor_crudo numeric, p_unidad character varying, p_timestamp_captura timestamp with time zone, p_timestamp_envio timestamp with time zone, p_origen modulo3.enum_telemetria_origen, p_categoria_variable modulo3.enum_telemetria_categoria_variable, p_tipo_dato modulo3.enum_telemetria_tipo_dato, p_valor_agregado boolean, p_ventana_agregacion integer, p_latitud numeric, p_longitud numeric, p_nivel_bateria numeric, p_calidad_rssi numeric, p_calidad_snr numeric, p_estado_conectividad boolean, p_metadatos jsonb) OWNER TO postgres;

--
-- Name: fn_log_transicion_dispositivo(); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_log_transicion_dispositivo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.estado_actual IS NOT DISTINCT FROM NEW.estado_actual THEN
        RETURN NEW;
    END IF;

    INSERT INTO modulo3.historico_transiciones_dispositivos (
        id_dispositivo_iot, estado_anterior, estado_nuevo,
        causa_primaria, causa_secundar, id_usuairo_responsable, notas, fecha_transicion
    ) VALUES (
        NEW.id_dispositivo_iot, OLD.estado_actual, NEW.estado_actual,
        NEW.causa_primaria, NEW.causas_secundarias, NEW.id_usuario,
        'Transición automática de estado operativo', now()
    );

    -- Abrir período de inactividad para SIN_SEÑAL e INACTIVO
    IF NEW.estado_actual IN ('SIN_SEÑAL','INACTIVO') THEN
        INSERT INTO modulo3.periodos_inactividad (
            id_dispositivo_iot, sensores_afectados, fecha_inicio,
            estado_durante_periodo, causa_primaria, buffer_activo_durante
        ) VALUES (
            NEW.id_dispositivo_iot, ARRAY[]::integer[], now(),
            NEW.estado_actual, NEW.causa_primaria, FALSE
        );
    END IF;

    -- BUFFER_ACTIVO: período diferenciado (offline intencional)
    IF NEW.estado_actual = 'BUFFER_ACTIVO' THEN
        INSERT INTO modulo3.periodos_inactividad (
            id_dispositivo_iot, sensores_afectados, fecha_inicio,
            estado_durante_periodo, causa_primaria, buffer_activo_durante
        ) VALUES (
            NEW.id_dispositivo_iot, ARRAY[]::integer[], now(),
            NEW.estado_actual, NEW.causa_primaria, TRUE
        );
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo3.fn_log_transicion_dispositivo() OWNER TO postgres;

--
-- Name: fn_marcar_sensores_sin_senal(); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_marcar_sensores_sin_senal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- 'SIN_SEÑAL' con tilde — valor real del enum_estado_dispositivo
    IF NEW.estado_actual IN ('SIN_SEÑAL','INACTIVO') THEN
        UPDATE modulo3.estados_actuales_sensores SET
            dato_desactualizado            = TRUE,
            estado_conectividad            = NEW.estado_actual,
            estado_semaforo                = 'GRIS',
            ultimo_timestamp_actualizacion = now()
        WHERE id_dispositivo_iot = NEW.id_dispositivo_iot;

    ELSIF NEW.estado_actual = 'ACTIVO'
      AND OLD.estado_actual <> 'ACTIVO' THEN
        UPDATE modulo3.estados_actuales_sensores SET
            dato_desactualizado            = FALSE,
            estado_conectividad            = 'ACTIVO',
            ultimo_timestamp_actualizacion = now()
        WHERE id_dispositivo_iot = NEW.id_dispositivo_iot;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo3.fn_marcar_sensores_sin_senal() OWNER TO postgres;

--
-- Name: fn_obtener_calibracion(integer, integer); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_obtener_calibracion(p_id_sensor integer, p_id_dispositivo integer, OUT p_offset numeric, OUT p_ganancia numeric, OUT p_encontrado boolean) RETURNS record
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    -- Busca la calibración más reciente del sensor
    SELECT
        COALESCE(valor_referencia, 0),
        1.0,        -- ganancia por defecto si no se almacena separada
        TRUE
    INTO p_offset, p_ganancia, p_encontrado
    FROM modulo9.calibraciones
    WHERE id_sensor     = p_id_sensor
      AND id_dispositivo_iot = p_id_dispositivo
    ORDER BY fecha_calibracion DESC
    LIMIT 1;

    IF NOT FOUND THEN
        p_offset     := 0;
        p_ganancia   := 1;
        p_encontrado := FALSE;
    END IF;
END;
$$;


ALTER FUNCTION modulo3.fn_obtener_calibracion(p_id_sensor integer, p_id_dispositivo integer, OUT p_offset numeric, OUT p_ganancia numeric, OUT p_encontrado boolean) OWNER TO postgres;

--
-- Name: FUNCTION fn_obtener_calibracion(p_id_sensor integer, p_id_dispositivo integer, OUT p_offset numeric, OUT p_ganancia numeric, OUT p_encontrado boolean); Type: COMMENT; Schema: modulo3; Owner: postgres
--

COMMENT ON FUNCTION modulo3.fn_obtener_calibracion(p_id_sensor integer, p_id_dispositivo integer, OUT p_offset numeric, OUT p_ganancia numeric, OUT p_encontrado boolean) IS 'RF-53 Fase 7 / RF-62: Retorna offset y ganancia del sensor para calibración.';


--
-- Name: fn_porcentaje_desviacion(numeric, numeric, numeric); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_porcentaje_desviacion(p_valor numeric, p_umbral_min numeric, p_umbral_max numeric) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    v_desviacion NUMERIC := 0;
BEGIN
    IF p_valor > p_umbral_max THEN
        IF p_umbral_max = 0 THEN RETURN -1; END IF;  -- ERROR_CONFIGURACION
        v_desviacion := (p_valor - p_umbral_max) / p_umbral_max * 100;
    ELSIF p_valor < p_umbral_min THEN
        IF p_umbral_min = 0 THEN RETURN -1; END IF;  -- ERROR_CONFIGURACION
        v_desviacion := (p_umbral_min - p_valor) / p_umbral_min * 100;
    END IF;
    RETURN v_desviacion;
END;
$$;


ALTER FUNCTION modulo3.fn_porcentaje_desviacion(p_valor numeric, p_umbral_min numeric, p_umbral_max numeric) OWNER TO postgres;

--
-- Name: FUNCTION fn_porcentaje_desviacion(p_valor numeric, p_umbral_min numeric, p_umbral_max numeric); Type: COMMENT; Schema: modulo3; Owner: postgres
--

COMMENT ON FUNCTION modulo3.fn_porcentaje_desviacion(p_valor numeric, p_umbral_min numeric, p_umbral_max numeric) IS 'RF-55.1: Porcentaje de desviación respecto a umbrales; retorna -1 si umbral=0.';


--
-- Name: fn_procesar_heartbeat(); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_procesar_heartbeat() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado_actual   modulo3.enum_estado_dispositivo;
    v_estado_nuevo    modulo3.enum_estado_dispositivo := 'ACTIVO';
BEGIN
    SELECT estado_actual INTO v_estado_actual
    FROM   modulo3.estados_dispositivos_iot
    WHERE  id_dispositivo_iot = NEW.id_dispositivo_iot;

    IF NOT FOUND THEN
        INSERT INTO modulo3.estados_dispositivos_iot (
            id_dispositivo_iot, estado_actual, fecha_ultimo_contacto,
            id_ultimo_heardbeat, tiempo_sin_contacto, fecha_ultima_actualizacion
        ) VALUES (
            NEW.id_dispositivo_iot, 'ACTIVO', GREATEST(NEW.fecha_registro, NEW.fecha_recepcion),
            NEW.id_heartbeat, 0, now()
        );
        RETURN NEW;
    END IF;

    -- EN_MANTENIMIENTO no se cambia automáticamente
    IF v_estado_actual = 'EN_MANTENIMIENTO' THEN
        v_estado_nuevo := 'EN_MANTENIMIENTO';
    ELSE
        v_estado_nuevo := 'ACTIVO';
    END IF;

    UPDATE modulo3.estados_dispositivos_iot SET
        estado_actual              = v_estado_nuevo,
        fecha_ultimo_contacto      = GREATEST(COALESCE(fecha_ultimo_contacto,'1970-01-01'), NEW.fecha_recepcion),
        id_ultimo_heardbeat        = NEW.id_heartbeat,
        tiempo_sin_contacto        = 0,
        causa_primaria             = NULL,
        causas_secundarias         = NULL,
        fecha_ultima_actualizacion = now()
    WHERE id_dispositivo_iot = NEW.id_dispositivo_iot;

    -- Si venía de estado de fallo → registrar reconexión y cerrar período
    IF v_estado_actual IN ('SIN_SEÑAL','INACTIVO','BUFFER_ACTIVO') THEN
        INSERT INTO modulo3.historico_transiciones_dispositivos (
            id_dispositivo_iot, estado_anterior, estado_nuevo, notas, fecha_transicion
        ) VALUES (
            NEW.id_dispositivo_iot, v_estado_actual, v_estado_nuevo,
            'Reconexión por heartbeat id=' || NEW.id_heartbeat, now()
        );
        UPDATE modulo3.periodos_inactividad SET
            fecha_fin    = now(),
            duracion_min = EXTRACT(EPOCH FROM (now() - fecha_inicio))::integer / 60
        WHERE  id_dispositivo_iot = NEW.id_dispositivo_iot AND fecha_fin IS NULL;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo3.fn_procesar_heartbeat() OWNER TO postgres;

--
-- Name: fn_registrar_bitacora(integer, integer, integer, modulo3.enum_eventos_edge_computing_tipo_evento, modulo3.enum_bitacora_ingest_estado_calidad, text, jsonb, modulo3.enum_bitacora_ingest_severidad); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_registrar_bitacora(p_id_telemetria integer, p_id_sensor integer, p_id_dispositivo integer, p_tipo_evento modulo3.enum_eventos_edge_computing_tipo_evento, p_estado_calidad modulo3.enum_bitacora_ingest_estado_calidad, p_descripcion text, p_payload jsonb, p_severidad modulo3.enum_bitacora_ingest_severidad DEFAULT 'INFO'::modulo3.enum_bitacora_ingest_severidad) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    INSERT INTO modulo3.bitacora_ingest (
        id_telemetria, id_sensor, id_dispositivo_iot,
        tipo_evento, estado_calidad, descripcion_text,
        payload_recibido, severidad, fecha_evento
    ) VALUES (
        p_id_telemetria, p_id_sensor, p_id_dispositivo,
        p_tipo_evento, p_estado_calidad, p_descripcion,
        p_payload, p_severidad, NOW()
    );
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[fn_registrar_bitacora] Error: %', SQLERRM;
END;
$$;


