--
-- Name: fn_regla_alerta_versionamiento(); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_regla_alerta_versionamiento() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.umbral_min              IS DISTINCT FROM NEW.umbral_min              OR
       OLD.umbral_max              IS DISTINCT FROM NEW.umbral_max              OR
       OLD.umbrales_severdiad      IS DISTINCT FROM NEW.umbrales_severdiad      OR
       OLD.ventana_confirmacion_min IS DISTINCT FROM NEW.ventana_confirmacion_min OR
       OLD.es_regla_compuesta      IS DISTINCT FROM NEW.es_regla_compuesta
    THEN
        NEW.version_regla       := OLD.version_regla + 1;
        NEW.fecha_actualizacion := now()::time with time zone;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo3.fn_regla_alerta_versionamiento() OWNER TO postgres;

--
-- Name: fn_sincronizar_alerta_en_sensor(); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_sincronizar_alerta_en_sensor() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.estado_alerta = 'ACTIVA'::modulo3.enum_estado_alerta AND NEW.id_sensor IS NOT NULL THEN
        UPDATE modulo3.estados_actuales_sensores SET
            id_alerta               = NEW.id_alerta,
            estado_semaforo         = CASE NEW.severidad
                WHEN 'CRITICO'  THEN 'ROJO'
                WHEN 'MODERADO' THEN 'AMARILLO'
                ELSE                 'AMARILLO'
            END,
            ultimo_timestamp_actualizacion = now()
        WHERE id_sensor = NEW.id_sensor;
    END IF;

    IF TG_OP = 'UPDATE' AND NEW.estado_alerta IN ('RESUELTA','DESCARTADA') THEN
        UPDATE modulo3.estados_actuales_sensores SET
            id_alerta                      = NULL,
            ultimo_timestamp_actualizacion = now()
        WHERE id_alerta = OLD.id_alerta;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo3.fn_sincronizar_alerta_en_sensor() OWNER TO postgres;

