--
-- Name: fn_validar_dispositivo(integer, integer); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_validar_dispositivo(p_id_dispositivo integer, p_id_sensor integer) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_dispositivo_activo BOOLEAN;
    v_sensor_activo      BOOLEAN;
BEGIN
    SELECT es_activo INTO v_dispositivo_activo
    FROM modulo9.dispositivos_iot
    WHERE id_dispositivo_iot = p_id_dispositivo;

    SELECT es_activo INTO v_sensor_activo
    FROM modulo9.sensores
    WHERE id_sensores = p_id_sensor
      AND id_dispositivo_iot = p_id_dispositivo;

    RETURN COALESCE(v_dispositivo_activo, FALSE)
       AND COALESCE(v_sensor_activo, FALSE);
END;
$$;


