--
-- Name: fn_validar_timestamp_telemetria(); Type: FUNCTION; Schema: modulo3; Owner: postgres
--

CREATE FUNCTION modulo3.fn_validar_timestamp_telemetria() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.timestamp_captura > now() THEN
        RAISE EXCEPTION
            'RF-53 [ERROR_TIEMPO]: timestamp_captura (%) es posterior a la hora actual. Dato rechazado.',
            NEW.timestamp_captura
            USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
END;
$$;


