--
-- Name: sp_clasificar_estado_dispositivo(integer, integer, integer); Type: PROCEDURE; Schema: modulo3; Owner: postgres
--

CREATE PROCEDURE modulo3.sp_clasificar_estado_dispositivo(IN p_id_dispositivo integer, IN p_margen_tolerancia_min integer DEFAULT 5, IN p_umbral_inactivo_horas integer DEFAULT 6)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rec                RECORD;
    v_t_sin_contacto     INTERVAL;
    v_tiene_buffer_pend  BOOLEAN;
    v_estado_nuevo       modulo3.enum_estado_dispositivo;
    v_estado_actual      modulo3.enum_estado_dispositivo;
BEGIN
    -- Obtener la fila completa del estado actual del dispositivo
    SELECT edi.estado_actual,
           edi.fecha_ultimo_contacto,
           edi.id_ultimo_heardbeat
    INTO v_rec
    FROM modulo3.estados_dispositivos_iot edi
    WHERE edi.id_dispositivo_iot = p_id_dispositivo;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Dispositivo % no existe en estados_dispositivos_iot', p_id_dispositivo;
    END IF;

    v_estado_actual := v_rec.estado_actual;

    -- Si está en mantenimiento, no se modifica
    IF v_estado_actual = 'EN_MANTENIMIENTO'::modulo3.enum_estado_dispositivo THEN
        RETURN;
    END IF;

    -- Calcular tiempo sin contacto
    v_t_sin_contacto := NOW() - COALESCE(v_rec.fecha_ultimo_contacto, '1970-01-01'::TIMESTAMPTZ);

    -- Verificar existencia de buffers pendientes
    SELECT EXISTS (
        SELECT 1 FROM modulo3.buffers b
        WHERE b.id_dispositivo_iot = p_id_dispositivo
          AND b.estado_buffer IN ('PENDIENTE'::modulo3.enum_buffers_estado_buffer,
                                  'ERROR'::modulo3.enum_buffers_estado_buffer)
    ) INTO v_tiene_buffer_pend;

    -- Determinar nuevo estado según reglas de negocio
    IF v_t_sin_contacto <= INTERVAL '10 minutes' THEN        -- frecuencia de heartbeat típica
        v_estado_nuevo := 'ACTIVO'::modulo3.enum_estado_dispositivo;
    ELSIF v_tiene_buffer_pend THEN
        v_estado_nuevo := 'BUFFER_ACTIVO'::modulo3.enum_estado_dispositivo;
    ELSIF v_t_sin_contacto <= MAKE_INTERVAL(mins => p_margen_tolerancia_min) THEN
        v_estado_nuevo := 'SIN_SEÑAL'::modulo3.enum_estado_dispositivo;
    ELSIF v_t_sin_contacto > MAKE_INTERVAL(hours => p_umbral_inactivo_horas) THEN
        v_estado_nuevo := 'INACTIVO'::modulo3.enum_estado_dispositivo;
    ELSE
        v_estado_nuevo := 'SIN_SEÑAL'::modulo3.enum_estado_dispositivo;
    END IF;

    -- Actualizar si cambió
    IF v_estado_nuevo IS DISTINCT FROM v_estado_actual THEN
        UPDATE modulo3.estados_dispositivos_iot
        SET estado_actual              = v_estado_nuevo,
            tiempo_sin_contacto        = EXTRACT(EPOCH FROM v_t_sin_contacto)::INTEGER / 60,
            fecha_ultima_actualizacion = NOW()
        WHERE id_dispositivo_iot = p_id_dispositivo;
    END IF;
END;
$$;


ALTER PROCEDURE modulo3.sp_clasificar_estado_dispositivo(IN p_id_dispositivo integer, IN p_margen_tolerancia_min integer, IN p_umbral_inactivo_horas integer) OWNER TO postgres;

--
-- Name: sp_confirmar_sincronizacion_buffer(integer); Type: PROCEDURE; Schema: modulo3; Owner: postgres
--

CREATE PROCEDURE modulo3.sp_confirmar_sincronizacion_buffer(IN p_id_buffer integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE modulo3.buffers
    SET estado_buffer          = 'CONFIRMADO',
        fecha_sincornizacion   = NOW()
    WHERE id_buffer = p_id_buffer
      AND estado_buffer IN ('ENVIADO','PENDIENTE');

    IF NOT FOUND THEN
        RAISE WARNING 'Buffer id=% no encontrado o ya confirmado.', p_id_buffer;
    END IF;
END;
$$;


ALTER PROCEDURE modulo3.sp_confirmar_sincronizacion_buffer(IN p_id_buffer integer) OWNER TO postgres;

--
-- Name: PROCEDURE sp_confirmar_sincronizacion_buffer(IN p_id_buffer integer); Type: COMMENT; Schema: modulo3; Owner: postgres
--

COMMENT ON PROCEDURE modulo3.sp_confirmar_sincronizacion_buffer(IN p_id_buffer integer) IS 'RF-54: Marca un registro de buffer como CONFIRMADO tras ACK del backend. Solo libera el dato tras confirmación explícita (CA-6).';


--
-- Name: sp_corregir_vinculacion(integer, integer, integer, text); Type: PROCEDURE; Schema: modulo3; Owner: postgres
--

CREATE PROCEDURE modulo3.sp_corregir_vinculacion(IN p_id_vinculacion_anterior integer, IN p_id_activo_nuevo integer, IN p_id_usuario integer, IN p_motivo text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_registro RECORD;
    v_new_id   INTEGER;
BEGIN
    SELECT * INTO v_registro
    FROM modulo3.vinculaciones_lecturas
    WHERE id_vinculacion_lectura = p_id_vinculacion_anterior;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Vinculación % no encontrada.', p_id_vinculacion_anterior;
    END IF;

    -- Marcar la anterior como CORREGIDA (fix: era 'SUPERADA', no existe en enum)
    UPDATE modulo3.vinculaciones_lecturas
    SET estado_vinculacion    = 'CORREGIDA',    -- fix: era 'SUPERADA'
        fecha_fin_vinculacion = NOW()
    WHERE id_vinculacion_lectura = p_id_vinculacion_anterior
      AND fecha_fin_vinculacion IS NULL;

    INSERT INTO modulo3.vinculaciones_lecturas (
        id_telemetria, modelo_manejo,
        id_activo_biologico, id_infraestructura,
        fecha_inicio_vinculacion,
        mecanismo_vinculacion,
        estado_vinculacion,
        id_usuario, motivo_correcion,
        id_vinculacion_remplazada,
        fecha_creacion
    )
    VALUES (
        v_registro.id_telemetria, v_registro.modelo_manejo,
        p_id_activo_nuevo, v_registro.id_infraestructura,
        v_registro.fecha_inicio_vinculacion,
        'CORRECCION', 'VINCULADA',
        p_id_usuario, p_motivo,
        p_id_vinculacion_anterior,
        NOW()
    )
    RETURNING id_vinculacion_lectura INTO v_new_id;

    RAISE NOTICE 'Vinculación % corregida → nueva vinculación %.', p_id_vinculacion_anterior, v_new_id;
END;
$$;


ALTER PROCEDURE modulo3.sp_corregir_vinculacion(IN p_id_vinculacion_anterior integer, IN p_id_activo_nuevo integer, IN p_id_usuario integer, IN p_motivo text) OWNER TO postgres;

--
-- Name: PROCEDURE sp_corregir_vinculacion(IN p_id_vinculacion_anterior integer, IN p_id_activo_nuevo integer, IN p_id_usuario integer, IN p_motivo text); Type: COMMENT; Schema: modulo3; Owner: postgres
--

COMMENT ON PROCEDURE modulo3.sp_corregir_vinculacion(IN p_id_vinculacion_anterior integer, IN p_id_activo_nuevo integer, IN p_id_usuario integer, IN p_motivo text) IS 'RF-61-C: Corrección de vinculación. [CORREGIDO: estado CORREGIDA]';


--
-- Name: sp_escalar_alertas_vencidas(); Type: PROCEDURE; Schema: modulo3; Owner: postgres
--

CREATE PROCEDURE modulo3.sp_escalar_alertas_vencidas()
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rec RECORD;
BEGIN
    FOR v_rec IN
        SELECT a.id_alerta, a.severidad, a.fecha_registro
        FROM modulo3.alertas a
        WHERE a.estado_alerta = 'ACTIVA'
          AND (
               (a.severidad = 'CRITICO'  AND NOW() > a.fecha_registro + INTERVAL '5 minutes')
            OR (a.severidad = 'MODERADO' AND NOW() > a.fecha_registro + INTERVAL '30 minutes')
            OR (a.severidad = 'LEVE'     AND NOW() > a.fecha_registro + INTERVAL '2 hours')
          )
    LOOP
        UPDATE modulo3.alertas
        SET estado_alerta = 'VENCIDA'
        WHERE id_alerta   = v_rec.id_alerta;
    END LOOP;
END;
$$;


ALTER PROCEDURE modulo3.sp_escalar_alertas_vencidas() OWNER TO postgres;

--
-- Name: PROCEDURE sp_escalar_alertas_vencidas(); Type: COMMENT; Schema: modulo3; Owner: postgres
--

COMMENT ON PROCEDURE modulo3.sp_escalar_alertas_vencidas() IS 'RF-57 Restricción 12 / CA-12: Marca como VENCIDA las alertas que superaron su SLA de atención (CRITICO=5min, MODERADO=30min, LEVE=2h).';


--
-- Name: sp_evaluar_calidad_dato(integer, integer, numeric, integer, numeric, integer, text, boolean, boolean); Type: PROCEDURE; Schema: modulo3; Owner: postgres
--

CREATE PROCEDURE modulo3.sp_evaluar_calidad_dato(IN p_id_telemetria integer, IN p_n_ventana integer DEFAULT 20, IN p_k_outlier numeric DEFAULT 3.0, IN p_m_congelado integer DEFAULT 5, IN p_umbral_drift numeric DEFAULT 5.0, INOUT p_indice_calidad integer DEFAULT NULL::integer, INOUT p_clasificacion text DEFAULT 'INDETERMINADA'::text, INOUT p_apto_para_ia boolean DEFAULT false, INOUT p_apto_para_nic41 boolean DEFAULT false)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tel              RECORD;
    v_serie            NUMERIC[];
    v_media            NUMERIC;
    v_desv             NUMERIC;
    v_n_real           INTEGER;
    v_congelado        BOOLEAN := FALSE;
    v_congelado_sev    TEXT;
    v_outlier          BOOLEAN := FALSE;
    v_drift            BOOLEAN := FALSE;
    v_drift_pct        NUMERIC;
    v_gap_anomalo      BOOLEAN := FALSE;
    v_descuento        INTEGER := 0;
    v_cal_offset       NUMERIC;
    v_cal_ganancia     NUMERIC;
    v_cal_encontrada   BOOLEAN;
    v_val_calib_esp    NUMERIC;
    v_ultima_ts        TIMESTAMPTZ;
    v_gap_real_min     INTEGER;
    v_frecuencia_esp   INTEGER;
    v_rep_consecutivas INTEGER;
    v_flags            JSONB := '{}';
BEGIN
    SELECT * INTO v_tel FROM modulo3.telemetrias WHERE id_telemetria = p_id_telemetria;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Telemetría % no encontrada.', p_id_telemetria;
    END IF;

    IF v_tel.estado_calidad = 'FUERA_DE_RANGO' THEN
        p_indice_calidad  := 0;
        p_clasificacion   := 'NO_APTO';
        p_apto_para_ia    := FALSE;
        p_apto_para_nic41 := FALSE;
        UPDATE modulo3.telemetrias
        SET metadatos = metadatos || jsonb_build_object(
                'calidad_indice', 0, 'calidad_clase', 'NO_APTO',
                'apto_ia', FALSE, 'apto_nic41', FALSE, 'fuera_de_rango_rf53', TRUE)
        WHERE id_telemetria = p_id_telemetria;
        RETURN;
    END IF;

    SELECT ARRAY(
        SELECT valor_crudo FROM modulo3.telemetrias
        WHERE id_sensor = v_tel.id_sensor AND id_variable = v_tel.id_variable
          AND estado_calidad NOT IN ('ERROR_SENSOR','ERROR_AUTENTICACION')
          AND timestamp_captura < v_tel.timestamp_captura
        ORDER BY timestamp_captura DESC LIMIT p_n_ventana
    ) INTO v_serie;

    v_n_real := array_length(v_serie, 1);

    IF v_n_real < p_m_congelado THEN
        p_indice_calidad  := NULL;
        p_clasificacion   := 'INDETERMINADA';
        p_apto_para_ia    := FALSE;
        p_apto_para_nic41 := FALSE;
        RETURN;
    END IF;

    SELECT AVG(x), STDDEV(x) INTO v_media, v_desv FROM unnest(v_serie) AS x;
    v_desv := COALESCE(v_desv, 0);

    SELECT COUNT(*) INTO v_rep_consecutivas
    FROM (
        SELECT valor_crudo, COUNT(*) AS n
        FROM (SELECT valor_crudo FROM modulo3.telemetrias
              WHERE id_sensor = v_tel.id_sensor AND id_variable = v_tel.id_variable
                AND estado_calidad NOT IN ('ERROR_SENSOR','ERROR_AUTENTICACION')
              ORDER BY timestamp_captura DESC LIMIT p_m_congelado) sub
        GROUP BY valor_crudo HAVING COUNT(*) = p_m_congelado
    ) eq;

    IF v_rep_consecutivas > 0 THEN
        v_congelado := TRUE;
        v_congelado_sev := CASE
            WHEN p_m_congelado >= 20 THEN 'CRITICO'
            WHEN p_m_congelado >= 10 THEN 'MODERADO'
            ELSE 'LEVE' END;
        v_descuento := v_descuento + CASE v_congelado_sev
            WHEN 'LEVE' THEN 15 WHEN 'MODERADO' THEN 35 ELSE 90 END;
        v_flags := v_flags || jsonb_build_object('sensor_congelado',
            jsonb_build_object('activo', TRUE, 'severidad', v_congelado_sev,
                               'M_repeticiones', p_m_congelado));
    END IF;

    IF v_desv > 0 AND ABS(v_tel.valor_crudo - v_media) > p_k_outlier * v_desv THEN
        v_outlier   := TRUE;
        v_descuento := v_descuento + 20;
        v_flags := v_flags || jsonb_build_object('outlier_estadistico',
            jsonb_build_object('activo', TRUE, 'media', ROUND(v_media, 4),
                               'desv', ROUND(v_desv, 4), 'k_utilizado', p_k_outlier,
                               'magnitud', ROUND(ABS(v_tel.valor_crudo - v_media) / NULLIF(v_desv,0), 4)));
    END IF;

    IF v_tel.estado_calidad <> 'ERROR_CALIBRACION' THEN
        SELECT * INTO v_cal_offset, v_cal_ganancia, v_cal_encontrada
        FROM modulo3.fn_obtener_calibracion(v_tel.id_sensor, v_tel.id_dispositivo_iot);
        IF v_cal_encontrada THEN
            v_val_calib_esp := (v_media * v_cal_ganancia) + v_cal_offset;
            IF v_val_calib_esp <> 0 THEN
                v_drift_pct := ABS((v_media - v_val_calib_esp) / v_val_calib_esp * 100);
                IF v_drift_pct > p_umbral_drift THEN
                    v_drift     := TRUE;
                    v_descuento := v_descuento + CASE
                        WHEN v_drift_pct < 10 THEN 10
                        WHEN v_drift_pct < 20 THEN 25 ELSE 40 END;
                    v_flags := v_flags || jsonb_build_object('posible_drift',
                        jsonb_build_object('activo', TRUE,
                                           'magnitud_pct', ROUND(v_drift_pct, 2),
                                           'umbral', p_umbral_drift,
                                           'valor_calibrado_esperado', ROUND(v_val_calib_esp, 4)));
                END IF;
            END IF;
        END IF;
    END IF;

    SELECT MAX(timestamp_captura), MAX(COALESCE(frecuencia_muestreo_min, 10))
    INTO v_ultima_ts, v_frecuencia_esp
    FROM modulo3.telemetrias
    WHERE id_sensor = v_tel.id_sensor AND id_variable = v_tel.id_variable
      AND timestamp_captura < v_tel.timestamp_captura;

    IF v_ultima_ts IS NOT NULL AND v_frecuencia_esp IS NOT NULL THEN
        v_gap_real_min := EXTRACT(EPOCH FROM (v_tel.timestamp_captura - v_ultima_ts))::INTEGER / 60;
        IF v_gap_real_min > v_frecuencia_esp * 2 THEN
            v_gap_anomalo := TRUE;
            v_descuento   := v_descuento + 10;
            v_flags := v_flags || jsonb_build_object('gap_temporal_anomalo',
                jsonb_build_object('activo', TRUE, 'gap_real_min', v_gap_real_min,
                                   'gap_esperado_min', v_frecuencia_esp));
        END IF;
    END IF;

    p_indice_calidad := GREATEST(0, 100 - v_descuento);
    p_clasificacion  := CASE
        WHEN p_indice_calidad >= 80 THEN 'APTO'
        WHEN p_indice_calidad >= 40 THEN 'APTO_CON_RESERVA'
        ELSE 'NO_APTO' END;
    p_apto_para_ia    := p_indice_calidad >= 40;
    p_apto_para_nic41 := p_indice_calidad >= 80;

    UPDATE modulo3.telemetrias
    SET metadatos = metadatos || jsonb_build_object(
            'calidad_indice', p_indice_calidad, 'calidad_clase', p_clasificacion,
            'apto_ia', p_apto_para_ia, 'apto_nic41', p_apto_para_nic41,
            'flags_calidad', v_flags, 'ts_evaluacion', NOW())
    WHERE id_telemetria = p_id_telemetria;

    IF v_congelado AND v_congelado_sev = 'CRITICO' THEN
        PERFORM modulo3.fn_registrar_bitacora(
            p_id_telemetria, v_tel.id_sensor, v_tel.id_dispositivo_iot,
            'DATOS_PROCESADOS',             -- fix: era 'TELEMETRIA_RECIBIDA'
            'ERROR_SENSOR',
            'Sensor congelado crítico detectado por RF-62.',
            v_flags, 'CRITICAL');
    ELSIF v_drift THEN
        PERFORM modulo3.fn_registrar_bitacora(
            p_id_telemetria, v_tel.id_sensor, v_tel.id_dispositivo_iot,
            'DATOS_PROCESADOS',             -- fix: era 'TELEMETRIA_RECIBIDA'
            'LECTURA_VALIDA',
            format('Posible drift detectado: %.2f%%', v_drift_pct),
            v_flags, 'WARNING');
    END IF;
END;
$$;


ALTER PROCEDURE modulo3.sp_evaluar_calidad_dato(IN p_id_telemetria integer, IN p_n_ventana integer, IN p_k_outlier numeric, IN p_m_congelado integer, IN p_umbral_drift numeric, INOUT p_indice_calidad integer, INOUT p_clasificacion text, INOUT p_apto_para_ia boolean, INOUT p_apto_para_nic41 boolean) OWNER TO postgres;

