-- Name: PROCEDURE sp_evaluar_calidad_dato(IN p_id_telemetria integer, IN p_n_ventana integer, IN p_k_outlier numeric, IN p_m_congelado integer, IN p_umbral_drift numeric, INOUT p_indice_calidad integer, INOUT p_clasificacion text, INOUT p_apto_para_ia boolean, INOUT p_apto_para_nic41 boolean); Type: COMMENT; Schema: modulo3; Owner: postgres
--

COMMENT ON PROCEDURE modulo3.sp_evaluar_calidad_dato(IN p_id_telemetria integer, IN p_n_ventana integer, IN p_k_outlier numeric, IN p_m_congelado integer, IN p_umbral_drift numeric, INOUT p_indice_calidad integer, INOUT p_clasificacion text, INOUT p_apto_para_ia boolean, INOUT p_apto_para_nic41 boolean) IS 'RF-62: Evaluación de calidad estadística. [CORREGIDO: enum tipo_evento bitácora]';


--
-- Name: sp_evaluar_estado_dispositivos(integer, integer); Type: PROCEDURE; Schema: modulo3; Owner: postgres
--

CREATE PROCEDURE modulo3.sp_evaluar_estado_dispositivos(IN p_margen_tolerancia_min integer DEFAULT 5, IN p_umbral_inactivo_horas integer DEFAULT 6)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rec            RECORD;
    v_ts_ahora       TIMESTAMPTZ := NOW();
    v_t_sin_contacto INTERVAL;
    v_nuevo_estado   modulo3.enum_estado_dispositivo;
    v_id_alerta      INTEGER;
    v_creada         BOOLEAN;
    v_msg            TEXT;
BEGIN
    FOR v_rec IN
        SELECT
            ed.id_dispositivo_iot,
            ed.estado_actual,
            ed.fecha_ultimo_contacto,
            ed.id_ultimo_heardbeat,
            COALESCE(
                (SELECT MAX(va.frecuencia_muestreo)
                 FROM modulo9.sensores s
                 JOIN modulo9.variables_ambientales va ON va.es_activo = TRUE
                 WHERE s.id_dispositivo_iot = ed.id_dispositivo_iot
                   AND s.es_activo = TRUE),
                10
            ) AS frecuencia_min,
            COALESCE(
                (SELECT hb.estado_local_buffer
                 FROM modulo3.heartbeats hb          -- fix: era modulo3.hearbeats
                 WHERE hb.id_heartbeat = ed.id_ultimo_heardbeat),
                'N'
            ) AS buf_local
        FROM modulo3.estados_dispositivos_iot ed
        WHERE ed.estado_actual NOT IN ('EN_MANTENIMIENTO')
    LOOP
        v_t_sin_contacto := v_ts_ahora - v_rec.fecha_ultimo_contacto;

        IF v_t_sin_contacto <= (v_rec.frecuencia_min || ' minutes')::INTERVAL THEN
            v_nuevo_estado := 'ACTIVO';

        ELSIF v_rec.buf_local = 'A' THEN
            v_nuevo_estado := 'BUFFER_ACTIVO';

        ELSIF v_t_sin_contacto <=
              ((v_rec.frecuencia_min + p_margen_tolerancia_min) || ' minutes')::INTERVAL
        THEN
            v_nuevo_estado := 'SIN_SEÑAL';
            IF v_rec.estado_actual <> 'SIN_SEÑAL' THEN
                CALL modulo3.sp_generar_alerta(
                    'INACTIVIDAD_ANORMAL',          -- fix: era 'TECNICA'
                    'MODERADO', 'BACKEND',
                    NULL, v_rec.id_dispositivo_iot,
                    p_id_alerta       => v_id_alerta,
                    p_creada          => v_creada,
                    p_mensaje         => v_msg,
                    p_metadato_evento => jsonb_build_object(
                        'tipo_alerta_tecnica', 'DISPOSITIVO_SIN_SEÑAL',
                        'minutos_sin_contacto',
                        EXTRACT(EPOCH FROM v_t_sin_contacto)::INTEGER / 60)
                );
            END IF;

        ELSIF v_t_sin_contacto > (p_umbral_inactivo_horas || ' hours')::INTERVAL THEN
            v_nuevo_estado := 'INACTIVO';
            IF v_rec.estado_actual <> 'INACTIVO' THEN
                CALL modulo3.sp_generar_alerta(
                    'INACTIVIDAD_ANORMAL',          -- fix: era 'TECNICA'
                    'CRITICO', 'BACKEND',
                    NULL, v_rec.id_dispositivo_iot,
                    p_id_alerta       => v_id_alerta,
                    p_creada          => v_creada,
                    p_mensaje         => v_msg,
                    p_metadato_evento => jsonb_build_object(
                        'tipo_alerta_tecnica', 'DISPOSITIVO_INACTIVO',
                        'horas_sin_contacto',
                        EXTRACT(EPOCH FROM v_t_sin_contacto)::INTEGER / 3600)
                );
            END IF;

        ELSE
            v_nuevo_estado := 'SIN_SEÑAL';
        END IF;

        IF v_nuevo_estado <> v_rec.estado_actual THEN
            UPDATE modulo3.estados_dispositivos_iot
            SET estado_actual              = v_nuevo_estado,
                tiempo_sin_contacto        = EXTRACT(EPOCH FROM v_t_sin_contacto)::INTEGER / 60,
                fecha_ultima_actualizacion = v_ts_ahora
            WHERE id_dispositivo_iot = v_rec.id_dispositivo_iot;
        END IF;

    END LOOP;
END;
$$;


ALTER PROCEDURE modulo3.sp_evaluar_estado_dispositivos(IN p_margen_tolerancia_min integer, IN p_umbral_inactivo_horas integer) OWNER TO postgres;

