-- Name: PROCEDURE sp_evaluar_estado_dispositivos(IN p_margen_tolerancia_min integer, IN p_umbral_inactivo_horas integer); Type: COMMENT; Schema: modulo3; Owner: postgres
--

COMMENT ON PROCEDURE modulo3.sp_evaluar_estado_dispositivos(IN p_margen_tolerancia_min integer, IN p_umbral_inactivo_horas integer) IS 'RF-60: Evaluación periódica de estado. [CORREGIDO: enum tipo_alerta, tabla heartbeats]';


--
-- Name: sp_exportar_historial_paginado(timestamp with time zone, timestamp with time zone, character varying, modulo3.enum_telemetria_estado_calidad, integer, integer); Type: PROCEDURE; Schema: modulo3; Owner: postgres
--

CREATE PROCEDURE modulo3.sp_exportar_historial_paginado(IN p_fecha_inicio timestamp with time zone, IN p_fecha_fin timestamp with time zone, IN p_tipo_variable character varying, IN p_estado_calidad modulo3.enum_telemetria_estado_calidad, IN p_page integer, IN p_page_size integer, OUT p_cursor refcursor, OUT p_total_registros integer, OUT p_min_val numeric, OUT p_max_val numeric, OUT p_avg_val numeric, OUT p_stddev_val numeric)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_page      INTEGER := COALESCE(p_page, 1);
    v_page_size INTEGER := COALESCE(p_page_size, 100);
    v_offset    INTEGER := (v_page - 1) * v_page_size;
BEGIN
    -- Calcular total y estadísticos con filtros opcionales (NULL se ignora)
    EXECUTE '
        SELECT COUNT(*), MIN(valor_ajustado), MAX(valor_ajustado), AVG(valor_ajustado), STDDEV(valor_ajustado)
        FROM modulo3.telemetrias t
        WHERE ($1 IS NULL OR t.timestamp_captura >= $1)
          AND ($2 IS NULL OR t.timestamp_captura <= $2)
          AND ($3 IS NULL OR t.tipo_variable = $3)
          AND ($4 IS NULL OR t.estado_calidad = $4)
    '
    USING p_fecha_inicio, p_fecha_fin, p_tipo_variable, p_estado_calidad
    INTO p_total_registros, p_min_val, p_max_val, p_avg_val, p_stddev_val;

    -- Abrir cursor paginado
    OPEN p_cursor FOR
        EXECUTE '
            SELECT t.id_telemetria, t.timestamp_captura, t.tipo_variable,
                   t.valor_crudo, t.valor_ajustado, t.estado_calidad, t.origen
            FROM modulo3.telemetrias t
            WHERE ($1 IS NULL OR t.timestamp_captura >= $1)
              AND ($2 IS NULL OR t.timestamp_captura <= $2)
              AND ($3 IS NULL OR t.tipo_variable = $3)
              AND ($4 IS NULL OR t.estado_calidad = $4)
            ORDER BY t.timestamp_captura DESC
            LIMIT $5 OFFSET $6
        '
        USING p_fecha_inicio, p_fecha_fin, p_tipo_variable, p_estado_calidad,
              v_page_size, v_offset;
END;
$_$;


ALTER PROCEDURE modulo3.sp_exportar_historial_paginado(IN p_fecha_inicio timestamp with time zone, IN p_fecha_fin timestamp with time zone, IN p_tipo_variable character varying, IN p_estado_calidad modulo3.enum_telemetria_estado_calidad, IN p_page integer, IN p_page_size integer, OUT p_cursor refcursor, OUT p_total_registros integer, OUT p_min_val numeric, OUT p_max_val numeric, OUT p_avg_val numeric, OUT p_stddev_val numeric) OWNER TO postgres;

--
-- Name: sp_generar_alerta(modulo3.enum_tipo_alerta, modulo3.enum_buffer_nivel_severidad, modulo3.enum_origen_evento_alerta, integer, integer, integer, integer, integer, integer, integer, integer, jsonb, jsonb, text, integer, integer, boolean, text); Type: PROCEDURE; Schema: modulo3; Owner: postgres
--

CREATE PROCEDURE modulo3.sp_generar_alerta(IN p_tipo_alerta modulo3.enum_tipo_alerta, IN p_severidad modulo3.enum_buffer_nivel_severidad, IN p_origen_evento modulo3.enum_origen_evento_alerta, IN p_id_sensor integer DEFAULT NULL::integer, IN p_id_dispositivo integer DEFAULT NULL::integer, IN p_id_activo_biologico integer DEFAULT NULL::integer, IN p_id_infraestructura integer DEFAULT NULL::integer, IN p_id_evento_edge integer DEFAULT NULL::integer, IN p_id_telemetria integer DEFAULT NULL::integer, IN p_id_paquete_inferencia integer DEFAULT NULL::integer, IN p_id_regla_alerta integer DEFAULT NULL::integer, IN p_reglas_activas jsonb DEFAULT '[]'::jsonb, IN p_metadato_evento jsonb DEFAULT '{}'::jsonb, IN p_accion_sugerida text DEFAULT NULL::text, IN p_ventana_dedup_min integer DEFAULT 30, INOUT p_id_alerta integer DEFAULT NULL::integer, INOUT p_creada boolean DEFAULT false, INOUT p_mensaje text DEFAULT 'PENDIENTE'::text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_alerta_existente INTEGER;
BEGIN
    p_creada  := FALSE;
    p_mensaje := 'OK';

    IF p_id_sensor IS NOT NULL THEN
        v_alerta_existente := modulo3.fn_alerta_activa_existe(
                                  p_id_sensor, p_tipo_alerta, p_ventana_dedup_min);
    END IF;

    IF v_alerta_existente IS NOT NULL THEN
        UPDATE modulo3.alertas
        SET metadato_evento = metadato_evento || p_metadato_evento
        WHERE id_alerta = v_alerta_existente
          AND (
              (p_severidad = 'CRITICO'  AND severidad <> 'CRITICO')
           OR (p_severidad = 'MODERADO' AND severidad = 'LEVE')
          );
        p_id_alerta := v_alerta_existente;
        p_mensaje   := 'Alerta existente actualizada (deduplicación).';
        RETURN;
    END IF;

    INSERT INTO modulo3.alertas (
        tipo_alerta, severidad, estado_alerta,
        origen_evento,
        id_evento_edge_computing, id_telemetria,
        id_paquete_inferencia, id_regla_alerta,
        reglas_activas,
        id_sensor, id_dispositivo_ioit,
        id_activo_biologico, id_infraestructura,
        tiene_inferencia_no_disponible,
        conflicto_resolucion,               -- fix: era 'SIN_CONFLICTO'
        fecha_registro,
        fecha_evento,                       -- fix: columna NOT NULL faltaba
        tipo_variable,                      -- fix: columna NOT NULL faltaba
        metadato_evento, accion_sugerida
    )
    VALUES (
        p_tipo_alerta, p_severidad, 'ACTIVA',
        p_origen_evento,
        p_id_evento_edge, p_id_telemetria,
        p_id_paquete_inferencia, p_id_regla_alerta,
        p_reglas_activas,
        p_id_sensor, p_id_dispositivo,
        p_id_activo_biologico, p_id_infraestructura,
        (p_origen_evento <> 'IA'),
        'SEVERIDAD_MAXIMA',                 -- fix: valor válido en enum_conflicto_resolucion
        NOW(),
        NOW(),                              -- fix: fecha_evento
        p_tipo_alerta::TEXT,                -- fix: tipo_variable derivado del tipo de alerta
        p_metadato_evento, p_accion_sugerida
    )
    RETURNING id_alerta INTO p_id_alerta;

    p_creada  := TRUE;
    p_mensaje := format('Alerta %s creada con severidad %s.', p_tipo_alerta, p_severidad);

EXCEPTION WHEN OTHERS THEN
    p_mensaje := 'Error en sp_generar_alerta: ' || SQLERRM;
    RAISE WARNING '%', p_mensaje;
END;
$$;


ALTER PROCEDURE modulo3.sp_generar_alerta(IN p_tipo_alerta modulo3.enum_tipo_alerta, IN p_severidad modulo3.enum_buffer_nivel_severidad, IN p_origen_evento modulo3.enum_origen_evento_alerta, IN p_id_sensor integer, IN p_id_dispositivo integer, IN p_id_activo_biologico integer, IN p_id_infraestructura integer, IN p_id_evento_edge integer, IN p_id_telemetria integer, IN p_id_paquete_inferencia integer, IN p_id_regla_alerta integer, IN p_reglas_activas jsonb, IN p_metadato_evento jsonb, IN p_accion_sugerida text, IN p_ventana_dedup_min integer, INOUT p_id_alerta integer, INOUT p_creada boolean, INOUT p_mensaje text) OWNER TO postgres;

--
-- Name: PROCEDURE sp_generar_alerta(IN p_tipo_alerta modulo3.enum_tipo_alerta, IN p_severidad modulo3.enum_buffer_nivel_severidad, IN p_origen_evento modulo3.enum_origen_evento_alerta, IN p_id_sensor integer, IN p_id_dispositivo integer, IN p_id_activo_biologico integer, IN p_id_infraestructura integer, IN p_id_evento_edge integer, IN p_id_telemetria integer, IN p_id_paquete_inferencia integer, IN p_id_regla_alerta integer, IN p_reglas_activas jsonb, IN p_metadato_evento jsonb, IN p_accion_sugerida text, IN p_ventana_dedup_min integer, INOUT p_id_alerta integer, INOUT p_creada boolean, INOUT p_mensaje text); Type: COMMENT; Schema: modulo3; Owner: postgres
--

COMMENT ON PROCEDURE modulo3.sp_generar_alerta(IN p_tipo_alerta modulo3.enum_tipo_alerta, IN p_severidad modulo3.enum_buffer_nivel_severidad, IN p_origen_evento modulo3.enum_origen_evento_alerta, IN p_id_sensor integer, IN p_id_dispositivo integer, IN p_id_activo_biologico integer, IN p_id_infraestructura integer, IN p_id_evento_edge integer, IN p_id_telemetria integer, IN p_id_paquete_inferencia integer, IN p_id_regla_alerta integer, IN p_reglas_activas jsonb, IN p_metadato_evento jsonb, IN p_accion_sugerida text, IN p_ventana_dedup_min integer, INOUT p_id_alerta integer, INOUT p_creada boolean, INOUT p_mensaje text) IS 'RF-57: Genera alerta con deduplicación. [CORREGIDO: conflicto_resolucion, fecha_evento, tipo_variable]';


--
-- Name: sp_gestionar_estado_alerta(integer, modulo3.enum_estado_alerta, integer, text); Type: PROCEDURE; Schema: modulo3; Owner: postgres
--

CREATE PROCEDURE modulo3.sp_gestionar_estado_alerta(IN p_id_alerta integer, IN p_nuevo_estado modulo3.enum_estado_alerta, IN p_id_usuario integer, IN p_motivo text DEFAULT NULL::text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado_actual modulo3.enum_estado_alerta;
BEGIN
    SELECT estado_alerta INTO v_estado_actual
    FROM modulo3.alertas
    WHERE id_alerta = p_id_alerta
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Alerta % no encontrada.', p_id_alerta;
    END IF;

    -- Validar transiciones permitidas (RF-57 Fase 9 / CA-11)
    IF NOT (
           (v_estado_actual = 'ACTIVA'      AND p_nuevo_estado IN ('EN_ATENCION','DESCARTADA','VENCIDA'))
        OR (v_estado_actual = 'EN_ATENCION' AND p_nuevo_estado IN ('RESUELTA','VENCIDA'))
        OR (v_estado_actual = 'ACTIVA'      AND p_nuevo_estado = 'RESUELTA')  -- shortcut operacional
    ) THEN
        RAISE EXCEPTION 'Transición inválida: % → %', v_estado_actual, p_nuevo_estado;
    END IF;

    UPDATE modulo3.alertas
    SET estado_alerta     = p_nuevo_estado,
        id_usuario_atencion    = CASE WHEN p_nuevo_estado = 'EN_ATENCION'
                                      THEN p_id_usuario ELSE id_usuario_atencion END,
        id_usuario_resolucion  = CASE WHEN p_nuevo_estado IN ('RESUELTA','DESCARTADA')
                                      THEN p_id_usuario ELSE id_usuario_resolucion END,
        motivo_descarte   = CASE WHEN p_nuevo_estado = 'DESCARTADA'
                                 THEN p_motivo ELSE motivo_descarte END,
        diagnostico       = CASE WHEN p_nuevo_estado = 'RESUELTA'
                                 THEN p_motivo ELSE diagnostico END
    WHERE id_alerta = p_id_alerta;

    -- El trigger trg_historial_estado_alerta registra automáticamente el cambio

EXCEPTION WHEN OTHERS THEN
    RAISE;
END;
$$;


ALTER PROCEDURE modulo3.sp_gestionar_estado_alerta(IN p_id_alerta integer, IN p_nuevo_estado modulo3.enum_estado_alerta, IN p_id_usuario integer, IN p_motivo text) OWNER TO postgres;

--
-- Name: PROCEDURE sp_gestionar_estado_alerta(IN p_id_alerta integer, IN p_nuevo_estado modulo3.enum_estado_alerta, IN p_id_usuario integer, IN p_motivo text); Type: COMMENT; Schema: modulo3; Owner: postgres
--

COMMENT ON PROCEDURE modulo3.sp_gestionar_estado_alerta(IN p_id_alerta integer, IN p_nuevo_estado modulo3.enum_estado_alerta, IN p_id_usuario integer, IN p_motivo text) IS 'RF-57 Fase 9: Gestión del ciclo de vida de alertas. Valida transiciones y delega el historial al trigger correspondiente.';


--
-- Name: sp_ingesta_telemetria(integer, integer, integer, numeric, character varying, timestamp with time zone, timestamp with time zone, modulo3.enum_telemetria_origen, modulo3.enum_telemetria_categoria_variable, modulo3.enum_telemetria_tipo_dato, boolean, integer, numeric, numeric, numeric, numeric, numeric, boolean, jsonb, integer, modulo3.enum_telemetria_estado_calidad, text); Type: PROCEDURE; Schema: modulo3; Owner: postgres
--

CREATE PROCEDURE modulo3.sp_ingesta_telemetria(IN p_id_dispositivo integer, IN p_id_sensor integer, IN p_id_variable integer, IN p_valor_crudo numeric, IN p_unidad character varying, IN p_timestamp_captura timestamp with time zone, IN p_timestamp_envio timestamp with time zone, IN p_origen modulo3.enum_telemetria_origen, IN p_categoria_variable modulo3.enum_telemetria_categoria_variable, IN p_tipo_dato modulo3.enum_telemetria_tipo_dato DEFAULT 'CRUDO'::modulo3.enum_telemetria_tipo_dato, IN p_valor_agregado boolean DEFAULT false, IN p_ventana_agregacion integer DEFAULT NULL::integer, IN p_latitud numeric DEFAULT NULL::numeric, IN p_longitud numeric DEFAULT NULL::numeric, IN p_nivel_bateria numeric DEFAULT NULL::numeric, IN p_calidad_rssi numeric DEFAULT NULL::numeric, IN p_calidad_snr numeric DEFAULT NULL::numeric, IN p_estado_conectividad boolean DEFAULT true, IN p_metadatos jsonb DEFAULT '{}'::jsonb, INOUT p_id_telemetria integer DEFAULT NULL::integer, INOUT p_estado_calidad modulo3.enum_telemetria_estado_calidad DEFAULT NULL::modulo3.enum_telemetria_estado_calidad, INOUT p_mensaje text DEFAULT NULL::text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ts_procesamiento   TIMESTAMPTZ := NOW();
    v_valor_ajustado     NUMERIC(10,4);
    v_calibrado          BOOLEAN := FALSE;
    v_offset             NUMERIC;
    v_ganancia           NUMERIC;
    v_cal_encontrada     BOOLEAN;
    v_umbral_min         NUMERIC(8,2);
    v_umbral_max         NUMERIC(8,2);
    v_frecuencia_esp     INTEGER;
    v_unidad_esperada    VARCHAR(10);
    v_latencia_ms        INTEGER;
    v_frecuencia_anomala BOOLEAN := FALSE;
    v_latencia_alta      BOOLEAN := FALSE;
    v_posible_drift      BOOLEAN := FALSE;
    v_dato_buferizado    BOOLEAN;
BEGIN
    p_estado_calidad := 'LECTURA_VALIDA';
    p_mensaje        := 'OK';

    -- Fase 0: latencia
    v_latencia_ms   := EXTRACT(EPOCH FROM (v_ts_procesamiento - p_timestamp_envio))::INTEGER * 1000;
    v_latencia_alta := v_latencia_ms > 2000;

    -- Fase 1: validación estructural
    IF p_id_dispositivo IS NULL OR p_id_sensor IS NULL OR p_id_variable IS NULL
       OR p_valor_crudo IS NULL OR p_unidad IS NULL OR p_timestamp_captura IS NULL
    THEN
        p_estado_calidad := 'ERROR_ESTRUCTURA';
        p_mensaje        := 'Campos obligatorios faltantes en el payload.';
        PERFORM modulo3.fn_registrar_bitacora(
            NULL, p_id_sensor, p_id_dispositivo,
            'ERROR_PROCESAMIENTO',              -- fix: era 'DATO_INVALIDO'
            'ERROR_ESTRUCTURA', p_mensaje,
            jsonb_build_object('dispositivo', p_id_dispositivo, 'sensor', p_id_sensor),
            'CRITICAL');                        -- fix: era 'ERROR'
        RETURN;
    END IF;

    -- Fase 2: autenticación
    IF NOT modulo3.fn_validar_dispositivo(p_id_dispositivo, p_id_sensor) THEN
        p_estado_calidad := 'ERROR_AUTENTICACION';
        p_mensaje        := 'Dispositivo o sensor no registrado / inactivo.';
        PERFORM modulo3.fn_registrar_bitacora(
            NULL, p_id_sensor, p_id_dispositivo,
            'ERROR_PROCESAMIENTO',              -- fix
            'ERROR_AUTENTICACION', p_mensaje,
            jsonb_build_object('dispositivo', p_id_dispositivo, 'sensor', p_id_sensor),
            'CRITICAL');                        -- fix
        RETURN;
    END IF;

    -- Fase 3: coherencia temporal
    IF p_timestamp_captura > v_ts_procesamiento THEN
        p_estado_calidad := 'ERROR_TIEMPO';
        p_mensaje        := 'timestamp_captura futuro respecto al servidor.';
        PERFORM modulo3.fn_registrar_bitacora(
            NULL, p_id_sensor, p_id_dispositivo,
            'ERROR_PROCESAMIENTO',              -- fix
            'ERROR_TIEMPO', p_mensaje,
            jsonb_build_object('ts_captura', p_timestamp_captura, 'ts_servidor', v_ts_procesamiento),
            'WARNING');
        RETURN;
    END IF;

    v_dato_buferizado := (p_origen = 'BUFFER_LOCAL');
    IF v_dato_buferizado
       AND p_timestamp_captura < v_ts_procesamiento - INTERVAL '72 hours'
    THEN
        p_estado_calidad := 'ERROR_TIEMPO';
        p_mensaje        := 'Dato de buffer excede ventana de 72 h permitida.';
        PERFORM modulo3.fn_registrar_bitacora(
            NULL, p_id_sensor, p_id_dispositivo,
            'ERROR_PROCESAMIENTO',              -- fix
            'ERROR_TIEMPO', p_mensaje,
            jsonb_build_object('ts_captura', p_timestamp_captura),
            'WARNING');
        RETURN;
    END IF;

    -- Fase 4: unidad y rango
    SELECT va.unidad, ua.valor_min, ua.valor_max, va.frecuencia_muestreo
    INTO v_unidad_esperada, v_umbral_min, v_umbral_max, v_frecuencia_esp
    FROM modulo9.variables_ambientales va
    LEFT JOIN modulo9.umbrales_ambientales ua
           ON ua.id_variable_ambiental = va.id_variable_ambiental
    WHERE va.id_variable_ambiental = p_id_variable
      AND va.es_activo = TRUE
    LIMIT 1;

    IF v_unidad_esperada IS NOT NULL
       AND LOWER(p_unidad) <> LOWER(v_unidad_esperada)
    THEN
        p_estado_calidad := 'ERROR_UNIDAD';
        p_mensaje        := format('Unidad "%s" no coincide con la esperada "%s".',
                                   p_unidad, v_unidad_esperada);
        PERFORM modulo3.fn_registrar_bitacora(
            NULL, p_id_sensor, p_id_dispositivo,
            'ERROR_PROCESAMIENTO',              -- fix
            'ERROR_UNIDAD', p_mensaje,
            jsonb_build_object('unidad_recibida', p_unidad, 'unidad_esperada', v_unidad_esperada),
            'WARNING');
        RETURN;
    END IF;

    IF v_frecuencia_esp IS NOT NULL THEN
        DECLARE
            v_ultima_lectura TIMESTAMPTZ;
            v_gap_real       INTEGER;
        BEGIN
            SELECT MAX(timestamp_captura) INTO v_ultima_lectura
            FROM modulo3.telemetrias
            WHERE id_sensor = p_id_sensor AND id_variable = p_id_variable;
            IF v_ultima_lectura IS NOT NULL THEN
                v_gap_real := EXTRACT(EPOCH FROM (p_timestamp_captura - v_ultima_lectura))::INTEGER / 60;
                v_frecuencia_anomala := v_gap_real > v_frecuencia_esp * 2
                                     OR v_gap_real < v_frecuencia_esp / 2;
            END IF;
        END;
    END IF;

    -- Fase 5: valor físicamente imposible
    IF v_umbral_min IS NOT NULL AND v_umbral_max IS NOT NULL THEN
        IF p_valor_crudo > v_umbral_max * 5 OR p_valor_crudo < v_umbral_min * 5 * -1 THEN
            p_estado_calidad := 'ERROR_SENSOR';
            p_mensaje        := 'Valor físicamente imposible para la variable.';
            PERFORM modulo3.fn_registrar_bitacora(
                NULL, p_id_sensor, p_id_dispositivo,
                'ERROR_PROCESAMIENTO',          -- fix
                'ERROR_SENSOR', p_mensaje,
                jsonb_build_object('valor', p_valor_crudo,
                                   'umbral_min', v_umbral_min,
                                   'umbral_max', v_umbral_max),
                'CRITICAL');
            RETURN;
        END IF;
    END IF;

    -- Fase 6: duplicados
    IF modulo3.fn_es_duplicado(p_id_sensor, p_id_variable, p_timestamp_captura, p_origen) THEN
        p_estado_calidad := 'ERROR_DUPLICADO';
        p_mensaje        := 'Dato duplicado: ya existe registro con misma clave compuesta.';
        PERFORM modulo3.fn_registrar_bitacora(
            NULL, p_id_sensor, p_id_dispositivo,
            'DATOS_PROCESADOS',                 -- fix: era 'TELEMETRIA_RECIBIDA'
            'ERROR_DUPLICADO',                  -- fix: era 'DUPLICATE_EVENT'
            p_mensaje,
            jsonb_build_object('sensor', p_id_sensor, 'variable', p_id_variable,
                               'ts_captura', p_timestamp_captura, 'origen', p_origen),
            'INFO');
        RETURN;
    END IF;

    -- Fase 7: calibración
    SELECT p_offset, p_ganancia, p_encontrado
    INTO v_offset, v_ganancia, v_cal_encontrada
    FROM modulo3.fn_obtener_calibracion(p_id_sensor, p_id_dispositivo);

    IF v_cal_encontrada THEN
        v_valor_ajustado := (p_valor_crudo * v_ganancia) + v_offset;
        v_calibrado      := TRUE;
    ELSE
        -- fix: valor_ajustado es NOT NULL en DDL → usar valor crudo
        v_valor_ajustado := p_valor_crudo;
        v_calibrado      := FALSE;
        p_estado_calidad := 'ERROR_CALIBRACION';
        p_mensaje        := 'Sin parámetros de calibración. Se persiste valor crudo.';
    END IF;

    -- Fase 5 continuación: FUERA_DE_RANGO
    IF p_estado_calidad IN ('LECTURA_VALIDA', 'ERROR_CALIBRACION')
       AND v_umbral_min IS NOT NULL AND v_umbral_max IS NOT NULL
    THEN
        DECLARE v_valor_eval NUMERIC := COALESCE(v_valor_ajustado, p_valor_crudo);
        BEGIN
            IF v_valor_eval < v_umbral_min OR v_valor_eval > v_umbral_max THEN
                IF p_estado_calidad = 'LECTURA_VALIDA' THEN
                    p_estado_calidad := 'FUERA_DE_RANGO';
                    p_mensaje        := 'Valor fuera del rango operativo configurado.';
                END IF;
            END IF;
        END;
    END IF;

    -- Fase 8: dato agregado sin ventana
    IF p_valor_agregado AND p_ventana_agregacion IS NULL THEN
        p_estado_calidad := 'ERROR_ESTRUCTURA';
        p_mensaje        := 'dato agregado=true pero ventana_agregacion no informada.';
        PERFORM modulo3.fn_registrar_bitacora(
            NULL, p_id_sensor, p_id_dispositivo,
            'ERROR_PROCESAMIENTO',              -- fix
            'ERROR_ESTRUCTURA', p_mensaje,
            jsonb_build_object('valor_agregado', p_valor_agregado),
            'WARNING');
        RETURN;
    END IF;

    -- Fase 9: persistencia
    IF p_estado_calidad NOT IN ('LECTURA_VALIDA', 'FUERA_DE_RANGO', 'ERROR_CALIBRACION') THEN
        RETURN;
    END IF;

    INSERT INTO modulo3.telemetrias (
        id_sensor, id_variable, id_dispositivo_iot,
        valor_crudo, valor_ajustado,
        timestamp_captura, timestamp_envio, timestamp_procesamiento,
        origen, estado_calidad, calibrado,
        latitud, longitud, metadatos,
        categoria_variable, unidad_medida,
        valor_agregado, ventana_agregacion_min,   -- fix: era "ventana de agregacion"
        tipo_dato,
        latencia_alta, frecuencia_anomala,
        posible_drift, dato_buferizado,
        dato_agredado_edge, reloj_desincronizado,
        latencia_procesamiento_ms,                -- fix: era "latencia_procesamiento_ms "
        nivel_bateria_pct, calidad_senal_rssi, calidad_senal_snr,
        frecuencia_muestreo_min, estado_conectividad
    )
    VALUES (
        p_id_sensor, p_id_variable, p_id_dispositivo,
        p_valor_crudo, v_valor_ajustado,          -- fix: ya no es NULL
        p_timestamp_captura, p_timestamp_envio, v_ts_procesamiento,
        p_origen, p_estado_calidad, v_calibrado,
        p_latitud, p_longitud, p_metadatos,
        p_categoria_variable, p_unidad,
        p_valor_agregado, p_ventana_agregacion,
        p_tipo_dato,
        v_latencia_alta, v_frecuencia_anomala,
        v_posible_drift, v_dato_buferizado,
        (p_tipo_dato = 'EVENTO_EDGE'), FALSE,
        v_latencia_ms,
        p_nivel_bateria, p_calidad_rssi, p_calidad_snr,
        v_frecuencia_esp, p_estado_conectividad
    )
    RETURNING id_telemetria INTO p_id_telemetria;

    -- Fase 12: bitácora
    PERFORM modulo3.fn_registrar_bitacora(
        p_id_telemetria, p_id_sensor, p_id_dispositivo,
        'DATOS_PROCESADOS',                         -- fix: era 'TELEMETRIA_RECIBIDA'
        p_estado_calidad::TEXT::modulo3.enum_bitacora_ingest_estado_calidad,
        p_mensaje,
        jsonb_build_object(
            'id_telemetria', p_id_telemetria,
            'valor_crudo', p_valor_crudo,
            'valor_ajustado', v_valor_ajustado,
            'calibrado', v_calibrado,
            'latencia_ms', v_latencia_ms,
            'estado_calidad', p_estado_calidad),
        CASE p_estado_calidad
            WHEN 'LECTURA_VALIDA'    THEN 'INFO'
            WHEN 'FUERA_DE_RANGO'    THEN 'WARNING'
            WHEN 'ERROR_CALIBRACION' THEN 'WARNING'
            ELSE 'CRITICAL'                         -- fix: era 'ERROR'
        END::modulo3.enum_bitacora_ingest_severidad
    );

EXCEPTION WHEN OTHERS THEN
    p_estado_calidad := 'ERROR_ESTRUCTURA';
    p_mensaje        := 'Error inesperado en sp_ingesta_telemetria: ' || SQLERRM;
    ROLLBACK;
END;
$$;


ALTER PROCEDURE modulo3.sp_ingesta_telemetria(IN p_id_dispositivo integer, IN p_id_sensor integer, IN p_id_variable integer, IN p_valor_crudo numeric, IN p_unidad character varying, IN p_timestamp_captura timestamp with time zone, IN p_timestamp_envio timestamp with time zone, IN p_origen modulo3.enum_telemetria_origen, IN p_categoria_variable modulo3.enum_telemetria_categoria_variable, IN p_tipo_dato modulo3.enum_telemetria_tipo_dato, IN p_valor_agregado boolean, IN p_ventana_agregacion integer, IN p_latitud numeric, IN p_longitud numeric, IN p_nivel_bateria numeric, IN p_calidad_rssi numeric, IN p_calidad_snr numeric, IN p_estado_conectividad boolean, IN p_metadatos jsonb, INOUT p_id_telemetria integer, INOUT p_estado_calidad modulo3.enum_telemetria_estado_calidad, INOUT p_mensaje text) OWNER TO postgres;

--
-- Name: PROCEDURE sp_ingesta_telemetria(IN p_id_dispositivo integer, IN p_id_sensor integer, IN p_id_variable integer, IN p_valor_crudo numeric, IN p_unidad character varying, IN p_timestamp_captura timestamp with time zone, IN p_timestamp_envio timestamp with time zone, IN p_origen modulo3.enum_telemetria_origen, IN p_categoria_variable modulo3.enum_telemetria_categoria_variable, IN p_tipo_dato modulo3.enum_telemetria_tipo_dato, IN p_valor_agregado boolean, IN p_ventana_agregacion integer, IN p_latitud numeric, IN p_longitud numeric, IN p_nivel_bateria numeric, IN p_calidad_rssi numeric, IN p_calidad_snr numeric, IN p_estado_conectividad boolean, IN p_metadatos jsonb, INOUT p_id_telemetria integer, INOUT p_estado_calidad modulo3.enum_telemetria_estado_calidad, INOUT p_mensaje text); Type: COMMENT; Schema: modulo3; Owner: postgres
--

COMMENT ON PROCEDURE modulo3.sp_ingesta_telemetria(IN p_id_dispositivo integer, IN p_id_sensor integer, IN p_id_variable integer, IN p_valor_crudo numeric, IN p_unidad character varying, IN p_timestamp_captura timestamp with time zone, IN p_timestamp_envio timestamp with time zone, IN p_origen modulo3.enum_telemetria_origen, IN p_categoria_variable modulo3.enum_telemetria_categoria_variable, IN p_tipo_dato modulo3.enum_telemetria_tipo_dato, IN p_valor_agregado boolean, IN p_ventana_agregacion integer, IN p_latitud numeric, IN p_longitud numeric, IN p_nivel_bateria numeric, IN p_calidad_rssi numeric, IN p_calidad_snr numeric, IN p_estado_conectividad boolean, IN p_metadatos jsonb, INOUT p_id_telemetria integer, INOUT p_estado_calidad modulo3.enum_telemetria_estado_calidad, INOUT p_mensaje text) IS 'RF-53: Ingesta de telemetría IoT — 12 fases. [CORREGIDO: enums, columnas DDL]';


--
-- Name: sp_preparar_paquete_inferencia(integer, integer, integer, character varying, numeric, character varying, modulo3.enum_bitacora_ingest_estado_calidad, modulo3.enum_tipo_evento_edge, modulo3.enum_bitacora_ingest_severidad, modulo3.enum_origen_dato, jsonb, integer, integer, text); Type: PROCEDURE; Schema: modulo3; Owner: postgres
--

CREATE PROCEDURE modulo3.sp_preparar_paquete_inferencia(IN p_id_sensor integer, IN p_id_dispositivo integer, IN p_id_evento_edge integer, IN p_tipo_variable character varying, IN p_valor_numerico numeric, IN p_unidad character varying, IN p_estado_calidad modulo3.enum_bitacora_ingest_estado_calidad, IN p_estado_desviacion modulo3.enum_tipo_evento_edge DEFAULT 'NORMAL'::modulo3.enum_tipo_evento_edge, IN p_severidad modulo3.enum_bitacora_ingest_severidad DEFAULT 'INFO'::modulo3.enum_bitacora_ingest_severidad, IN p_origen modulo3.enum_origen_dato DEFAULT 'TIEMPO_REAL'::modulo3.enum_origen_dato, IN p_contexto_ambiental jsonb DEFAULT NULL::jsonb, IN p_id_version_modelo integer DEFAULT NULL::integer, INOUT p_id_paquete integer DEFAULT NULL::integer, INOUT p_estado text DEFAULT 'PENDIENTE'::text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO modulo3.paquetes_inferencia (      -- fix: era "paquetes_inferencia "
        id_sensor, id_dispositivo_iot, id_evento_edge_computing,
        tipo_variable, valor_numerico, unidad,
        estado_calidad, estado_desviacion,
        severidad, origen,
        contexto_ambiental, contexto_incomplento,
        id_version_modelo,
        fecha_envio, estado_paquete,               -- fix: era estado_paqueta
        intento_envios
    ) VALUES (
        p_id_sensor, p_id_dispositivo, p_id_evento_edge,
        p_tipo_variable, p_valor_numerico, p_unidad,
        p_estado_calidad, p_estado_desviacion,
        p_severidad, p_origen,
        p_contexto_ambiental,
        p_contexto_ambiental IS NULL,
        p_id_version_modelo,
        NOW(), 'PENDIENTE', 0
    )
    RETURNING id_paquetes_inferencia INTO p_id_paquete;  -- fix: era "id_paquetes_inferencia "

    p_estado := 'PAQUETE_CREADO';

EXCEPTION WHEN OTHERS THEN
    p_estado := 'ERROR: ' || SQLERRM;
    RAISE WARNING '[sp_preparar_paquete_inferencia] %', SQLERRM;
END;
$$;


