-- Name: PROCEDURE sp_preparar_paquete_inferencia(IN p_id_sensor integer, IN p_id_dispositivo integer, IN p_id_evento_edge integer, IN p_tipo_variable character varying, IN p_valor_numerico numeric, IN p_unidad character varying, IN p_estado_calidad modulo3.enum_bitacora_ingest_estado_calidad, IN p_estado_desviacion modulo3.enum_tipo_evento_edge, IN p_severidad modulo3.enum_bitacora_ingest_severidad, IN p_origen modulo3.enum_origen_dato, IN p_contexto_ambiental jsonb, IN p_id_version_modelo integer, INOUT p_id_paquete integer, INOUT p_estado text); Type: COMMENT; Schema: modulo3; Owner: postgres
