--
-- Name: sp_procesar_heartbeat(integer, modulo3.enum_tipo_mensaje_iot, numeric, numeric, numeric, character, integer, character varying, jsonb, boolean, integer, text); Type: PROCEDURE; Schema: modulo3; Owner: postgres
--

CREATE PROCEDURE modulo3.sp_procesar_heartbeat(IN p_id_dispositivo integer, IN p_tipo_mensaje modulo3.enum_tipo_mensaje_iot, IN p_nivel_bateria numeric DEFAULT NULL::numeric, IN p_calidad_rssi numeric DEFAULT NULL::numeric, IN p_calidad_snr numeric DEFAULT NULL::numeric, IN p_estado_buffer_local character DEFAULT 'N'::bpchar, IN p_datos_pendientes integer DEFAULT 0, IN p_version_firmware character varying DEFAULT NULL::character varying, IN p_coordenadas jsonb DEFAULT NULL::jsonb, IN p_reloj_sincronizado boolean DEFAULT true, INOUT p_id_heartbeat integer DEFAULT NULL::integer, INOUT p_estado_resultado text DEFAULT 'PENDIENTE'::text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_umbral_bateria_critica NUMERIC := 15.0;
    v_umbral_bateria_baja    NUMERIC := 25.0;
    v_id_alerta_dummy        INTEGER;
    v_creada_dummy           BOOLEAN;
    v_msg_dummy              TEXT;
BEGIN
    INSERT INTO modulo3.heartbeats (                -- fix: era modulo3.hearbeats
        id_dispositivo_iot, tipo_mensaje,
        nivel_bateria_pct, calidad_senal_rssi, calidad_senal_snr,
        estado_local_buffer, datos_pendientes_buffer,
        version_firmware, coordenadas,
        fecha_registro, fecha_recepcion,
        reloj_sincronizado
    ) VALUES (
        p_id_dispositivo, p_tipo_mensaje,
        p_nivel_bateria, p_calidad_rssi, p_calidad_snr,
        p_estado_buffer_local, p_datos_pendientes,
        p_version_firmware, p_coordenadas,
        NOW(), NOW(),
        p_reloj_sincronizado
    )
    RETURNING id_heartbeat INTO p_id_heartbeat;

    INSERT INTO modulo3.estados_dispositivos_iot (
        id_dispositivo_iot, estado_actual,
        fecha_ultimo_contacto, id_ultimo_heardbeat,
        fecha_ultima_actualizacion
    )
    VALUES (p_id_dispositivo, 'ACTIVO', NOW(), p_id_heartbeat, NOW())
    ON CONFLICT (id_dispositivo_iot) DO UPDATE
    SET estado_actual             = 'ACTIVO',
        fecha_ultimo_contacto     = NOW(),
        id_ultimo_heardbeat       = p_id_heartbeat,
        fecha_ultima_actualizacion = NOW();

    -- Batería crítica
    IF p_nivel_bateria IS NOT NULL AND p_nivel_bateria <= v_umbral_bateria_critica THEN
        CALL modulo3.sp_generar_alerta(
            'FALLO_AMBIENTAL',              -- fix: era 'TECNICA'
            'CRITICO', 'BACKEND',
            NULL, p_id_dispositivo,
            p_id_alerta       => v_id_alerta_dummy,
            p_creada          => v_creada_dummy,
            p_mensaje         => v_msg_dummy,
            p_metadato_evento => jsonb_build_object(
                'tipo_alerta_tecnica', 'BATERIA_CRITICA',
                'nivel_bateria', p_nivel_bateria,
                'id_dispositivo', p_id_dispositivo)
        );
    ELSIF p_nivel_bateria IS NOT NULL AND p_nivel_bateria <= v_umbral_bateria_baja THEN
        CALL modulo3.sp_generar_alerta(
            'FALLO_AMBIENTAL',              -- fix: era 'TECNICA'
            'MODERADO', 'BACKEND',
            NULL, p_id_dispositivo,
            p_id_alerta       => v_id_alerta_dummy,
            p_creada          => v_creada_dummy,
            p_mensaje         => v_msg_dummy,
            p_metadato_evento => jsonb_build_object(
                'tipo_alerta_tecnica', 'BATERIA_BAJA',
                'nivel_bateria', p_nivel_bateria)
        );
    END IF;

    -- Reloj desincronizado
    IF NOT p_reloj_sincronizado THEN
        CALL modulo3.sp_generar_alerta(
            'FALLO_AMBIENTAL',              -- fix: era 'TECNICA'
            'LEVE', 'BACKEND',
            NULL, p_id_dispositivo,
            p_id_alerta       => v_id_alerta_dummy,
            p_creada          => v_creada_dummy,
            p_mensaje         => v_msg_dummy,
            p_metadato_evento => jsonb_build_object(
                'tipo_alerta_tecnica', 'DESINCRONIZACION_RELOJ',
                'id_dispositivo', p_id_dispositivo)
        );
    END IF;

    p_estado_resultado := 'HEARTBEAT_PROCESADO';

EXCEPTION WHEN OTHERS THEN
    p_estado_resultado := 'ERROR: ' || SQLERRM;
    RAISE WARNING '[sp_procesar_heartbeat] %', SQLERRM;
END;
$$;


