--
-- Name: sp_registrar_en_buffer(integer, integer, modulo3.enum_telemetria_tipo_dato, json, timestamp with time zone, modulo3.enum_buffer_nivel_severidad, integer, integer, text); Type: PROCEDURE; Schema: modulo3; Owner: postgres
--

CREATE PROCEDURE modulo3.sp_registrar_en_buffer(IN p_id_dispositivo integer, IN p_id_sensor integer, IN p_tipo_dato modulo3.enum_telemetria_tipo_dato, IN p_payload_raw json, IN p_fecha_captura timestamp with time zone, IN p_nivel_severidad modulo3.enum_buffer_nivel_severidad DEFAULT NULL::modulo3.enum_buffer_nivel_severidad, IN p_id_evento_edge integer DEFAULT NULL::integer, INOUT p_id_buffer integer DEFAULT NULL::integer, INOUT p_estado_resultado text DEFAULT NULL::text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_max_seq  BIGINT;
    v_checksum VARCHAR(64);
BEGIN
    SELECT COALESCE(MAX(buffer_sequence_id), 0) + 1
    INTO v_max_seq
    FROM modulo3.buffers
    WHERE id_dispositivo_iot = p_id_dispositivo;   -- fix: era id_dispositivo

    v_checksum := md5(p_payload_raw::TEXT);

    INSERT INTO modulo3.buffers (
        id_dispositivo_iot, id_sensor,             -- fix: era id_dispositivo
        buffer_sequence_id, tipo_dato,
        nivel_severidad, id_evento_edge,
        payload_raw, checksum_dato,
        fecha_captura, fecha_creacion,
        estado_buffer, intentos_envio
    ) VALUES (
        p_id_dispositivo, p_id_sensor,
        v_max_seq, p_tipo_dato,
        p_nivel_severidad, p_id_evento_edge,
        p_payload_raw, v_checksum,
        p_fecha_captura, NOW(),
        'PENDIENTE', 0
    )
    RETURNING id_buffer INTO p_id_buffer;

    p_estado_resultado := 'ALMACENADO';

EXCEPTION WHEN OTHERS THEN
    p_estado_resultado := 'ERROR: ' || SQLERRM;
    RAISE WARNING '[sp_registrar_en_buffer] %', SQLERRM;
END;
$$;


ALTER PROCEDURE modulo3.sp_registrar_en_buffer(IN p_id_dispositivo integer, IN p_id_sensor integer, IN p_tipo_dato modulo3.enum_telemetria_tipo_dato, IN p_payload_raw json, IN p_fecha_captura timestamp with time zone, IN p_nivel_severidad modulo3.enum_buffer_nivel_severidad, IN p_id_evento_edge integer, INOUT p_id_buffer integer, INOUT p_estado_resultado text) OWNER TO postgres;

