-- Name: PROCEDURE sp_registrar_en_buffer(IN p_id_dispositivo integer, IN p_id_sensor integer, IN p_tipo_dato modulo3.enum_telemetria_tipo_dato, IN p_payload_raw json, IN p_fecha_captura timestamp with time zone, IN p_nivel_severidad modulo3.enum_buffer_nivel_severidad, IN p_id_evento_edge integer, INOUT p_id_buffer integer, INOUT p_estado_resultado text); Type: COMMENT; Schema: modulo3; Owner: postgres
--

