--
-- Name: sp_reintentar_buffer(integer, integer); Type: PROCEDURE; Schema: modulo3; Owner: postgres
--

CREATE PROCEDURE modulo3.sp_reintentar_buffer(IN p_id_dispositivo integer, IN p_max_reintentos integer DEFAULT 5)
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE modulo3.buffers
    SET estado_buffer        = 'ERROR',
        error_ultimo_intento = NOW()
    WHERE id_dispositivo_iot = p_id_dispositivo    -- fix: era id_dispositivo
      AND estado_buffer      = 'ENVIADO'
      AND intentos_envio     >= p_max_reintentos;

    UPDATE modulo3.buffers
    SET estado_buffer  = 'PENDIENTE',
        ultimo_intento = NOW(),
        intentos_envio = intentos_envio + 1
    WHERE id_dispositivo_iot = p_id_dispositivo    -- fix: era id_dispositivo
      AND estado_buffer      = 'ENVIADO'
      AND intentos_envio     < p_max_reintentos;
END;
$$;


ALTER PROCEDURE modulo3.sp_reintentar_buffer(IN p_id_dispositivo integer, IN p_max_reintentos integer) OWNER TO postgres;

