COMMENT ON PROCEDURE modulo3.sp_reintentar_buffer(IN p_id_dispositivo integer, IN p_max_reintentos integer) IS 'RF-54: Reintentos de buffer. [CORREGIDO: id_dispositivo_iot]';


--
-- Name: sp_sincronizar_buffer_lote(integer, integer); Type: PROCEDURE; Schema: modulo3; Owner: postgres
--

CREATE PROCEDURE modulo3.sp_sincronizar_buffer_lote(IN p_batch_size integer DEFAULT 100, IN p_max_reintentos integer DEFAULT 5)
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec_buffer          RECORD;
    v_intentos          INTEGER;
    v_duplicado         BOOLEAN;
    vid_telemetria      INTEGER;
    v_estado_calidad    modulo3.enum_telemetria_estado_calidad;
    v_mensaje           TEXT;
BEGIN
    FOR rec_buffer IN
        SELECT b.id_buffer,
               b.id_dispositivo_iot,
               b.id_sensor,
               b.payload_raw,
               b.fecha_captura,
               b.intentos_envio,
               b.ultimo_intento,
               b.tipo_dato,
               b.nivel_severidad
        FROM modulo3.buffers b
        WHERE b.estado_buffer IN ('PENDIENTE'::modulo3.enum_buffers_estado_buffer,
                                  'ERROR'::modulo3.enum_buffers_estado_buffer)
          AND b.intentos_envio < p_max_reintentos
        ORDER BY b.fecha_captura ASC
        LIMIT p_batch_size
        FOR UPDATE OF b SKIP LOCKED
    LOOP
        -- Resolver duplicados con telemetrías
        SELECT EXISTS (
            SELECT 1 FROM modulo3.telemetrias t
            WHERE t.id_sensor = rec_buffer.id_sensor
              AND t.timestamp_captura = rec_buffer.fecha_captura
        ) INTO v_duplicado;

        IF v_duplicado THEN
            UPDATE modulo3.buffers
            SET estado_buffer        = 'CONFIRMADO'::modulo3.enum_buffers_estado_buffer,
                fecha_sincornizacion = NOW()
            WHERE id_buffer = rec_buffer.id_buffer;
            CONTINUE;
        END IF;

        -- Llamada completa a fn_ingesta_telemetria (todos los parámetros)
        SELECT id_telemetria, estado_calidad, mensaje
        INTO vid_telemetria, v_estado_calidad, v_mensaje
        FROM modulo3.fn_ingesta_telemetria(
            p_id_dispositivo      => rec_buffer.id_dispositivo_iot,
            p_id_sensor           => rec_buffer.id_sensor,
            p_id_variable         => (rec_buffer.payload_raw->>'id_variable')::INTEGER,
            p_valor_crudo         => (rec_buffer.payload_raw->>'valor_crudo')::NUMERIC,
            p_unidad              => rec_buffer.payload_raw->>'unidad',
            p_timestamp_captura   => rec_buffer.fecha_captura,
            p_timestamp_envio     => rec_buffer.fecha_captura,
            p_origen              => 'BUFFER_LOCAL'::modulo3.enum_telemetria_origen,
            p_categoria_variable  => 'AMBIENTAL'::modulo3.enum_telemetria_categoria_variable,
            p_tipo_dato           => rec_buffer.tipo_dato,
            p_valor_agregado      => FALSE,
            p_ventana_agregacion  => NULL,
            p_latitud             => NULL,
            p_longitud            => NULL,
            p_nivel_bateria       => NULL,
            p_calidad_rssi        => NULL,
            p_calidad_snr         => NULL,
            p_estado_conectividad => FALSE,          -- buffer local → sin conectividad
            p_metadatos           => COALESCE((rec_buffer.payload_raw->>'metadatos')::JSONB, '{}'::JSONB)
        );

        -- Evaluar resultado
        IF vid_telemetria IS NOT NULL THEN
            UPDATE modulo3.buffers
            SET estado_buffer        = 'CONFIRMADO'::modulo3.enum_buffers_estado_buffer,
                fecha_sincornizacion = NOW(),
                intentos_envio       = rec_buffer.intentos_envio + 1,
                ultimo_intento       = NOW()
            WHERE id_buffer = rec_buffer.id_buffer;
        ELSE
            UPDATE modulo3.buffers
            SET intentos_envio       = rec_buffer.intentos_envio + 1,
                ultimo_intento       = NOW(),
                error_ultimo_intento = NOW(),
                estado_buffer        = CASE
                    WHEN rec_buffer.intentos_envio + 1 >= p_max_reintentos THEN
                        'ERROR'::modulo3.enum_buffers_estado_buffer
                    ELSE
                        'PENDIENTE'::modulo3.enum_buffers_estado_buffer
                END
            WHERE id_buffer = rec_buffer.id_buffer;
        END IF;
    END LOOP;
END;
$$;


ALTER PROCEDURE modulo3.sp_sincronizar_buffer_lote(IN p_batch_size integer, IN p_max_reintentos integer) OWNER TO postgres;

--
-- Name: sp_vincular_activo_historico(integer, integer); Type: PROCEDURE; Schema: modulo3; Owner: postgres
--

CREATE PROCEDURE modulo3.sp_vincular_activo_historico(IN p_id_telemetria integer DEFAULT NULL::integer, IN p_batch_size integer DEFAULT 50)
    LANGUAGE plpgsql
    AS $$
DECLARE
    rec_telemetria    RECORD;
    v_id_activo       INTEGER;
    v_id_infra        INTEGER;
    v_ubicacion_activo RECORD;
BEGIN
    FOR rec_telemetria IN
        SELECT t.id_telemetria,
               t.timestamp_captura,
               t.id_dispositivo_iot,
               t.latitud,
               t.longitud,
               vl.id_vinculacion_lectura,
               vl.id_infraestructura,
               vl.estado_vinculacion
        FROM modulo3.telemetrias t
        LEFT JOIN modulo3.vinculaciones_lecturas vl
               ON t.id_telemetria = vl.id_telemetria
        WHERE (p_id_telemetria IS NULL OR t.id_telemetria = p_id_telemetria)
          AND vl.estado_vinculacion IN ('SIN_VINCULAR'::modulo3.enum_estado_vinculacion,
                                        'AMBIGUA'::modulo3.enum_estado_vinculacion)
        LIMIT p_batch_size
    LOOP
        -- Intentar vincular con activo biológico basado en ubicación espacio-temporal
        -- (acceso a modulo2.ubicaciones_activos, supuesto existente)
        BEGIN
            SELECT ua.id_activo_biologico, ua.id_infraestructura
            INTO v_id_activo, v_id_infra
            FROM modulo2.ubicaciones_activos ua
            WHERE ua.id_infraestructura = rec_telemetria.id_infraestructura
              AND rec_telemetria.timestamp_captura BETWEEN ua.fecha_inicio AND COALESCE(ua.fecha_fin, 'infinity')
            ORDER BY ua.fecha_inicio DESC
            LIMIT 1;
        EXCEPTION WHEN undefined_table THEN
            RAISE NOTICE 'Tabla modulo2.ubicaciones_activos no accesible, omite vinculación';
            CONTINUE;
        END;

        IF v_id_activo IS NOT NULL THEN
            -- Actualizar vinculación existente o crear nueva
            IF rec_telemetria.id_vinculacion_lectura IS NOT NULL THEN
                UPDATE modulo3.vinculaciones_lecturas
                SET id_activo_biologico    = v_id_activo,
                    id_infraestructura     = v_id_infra,
                    mecanismo_vinculacion  = 'AUTOMATICA'::modulo3.enum_mecanismo_vinculacion,
                    estado_vinculacion     = 'VINCULADA'::modulo3.enum_estado_vinculacion
                WHERE id_vinculacion_lectura = rec_telemetria.id_vinculacion_lectura;
            ELSE
                INSERT INTO modulo3.vinculaciones_lecturas (
                    id_telemetria,
                    modelo_manejo,
                    id_activo_biologico,
                    id_infraestructura,
                    fecha_inicio_vinculacion,
                    mecanismo_vinculacion,
                    estado_vinculacion
                ) VALUES (
                    rec_telemetria.id_telemetria,
                    'INDIVIDUAL'::modulo3.enum_modelo_manejo,
                    v_id_activo,
                    v_id_infra,
                    rec_telemetria.timestamp_captura,
                    'AUTOMATICA'::modulo3.enum_mecanismo_vinculacion,
                    'VINCULADA'::modulo3.enum_estado_vinculacion
                );
            END IF;
        ELSE
            -- Marcar como AMBIGUA si no se logra vincular
            IF rec_telemetria.id_vinculacion_lectura IS NOT NULL THEN
                UPDATE modulo3.vinculaciones_lecturas
                SET estado_vinculacion = 'AMBIGUA'::modulo3.enum_estado_vinculacion
                WHERE id_vinculacion_lectura = rec_telemetria.id_vinculacion_lectura;
            ELSE
                INSERT INTO modulo3.vinculaciones_lecturas (
                    id_telemetria,
                    modelo_manejo,
                    id_infraestructura,
                    fecha_inicio_vinculacion,
                    estado_vinculacion
                ) VALUES (
                    rec_telemetria.id_telemetria,
                    'POBLACIONAL'::modulo3.enum_modelo_manejo,
                    rec_telemetria.id_infraestructura,
                    rec_telemetria.timestamp_captura,
                    'AMBIGUA'::modulo3.enum_estado_vinculacion
                );
            END IF;
        END IF;
    END LOOP;
END;
$$;


ALTER PROCEDURE modulo3.sp_vincular_activo_historico(IN p_id_telemetria integer, IN p_batch_size integer) OWNER TO postgres;

--
-- Name: fn_calcular_drift_score(integer, character varying); Type: FUNCTION; Schema: modulo4; Owner: postgres
--

CREATE FUNCTION modulo4.fn_calcular_drift_score(p_id_version_modelo integer, p_periodo_referencia character varying) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_score NUMERIC;
BEGIN
    SELECT MAX(valor_metrica) INTO v_score
    FROM modulo4.metricas_drift
    WHERE id_modelo_version = p_id_version_modelo
      AND supera_umbral_drift = TRUE
      AND periodo_referencia = p_periodo_referencia;

    RETURN COALESCE(v_score, 0.0);
END;
$$;


ALTER FUNCTION modulo4.fn_calcular_drift_score(p_id_version_modelo integer, p_periodo_referencia character varying) OWNER TO postgres;

--
-- Name: fn_calcular_probabilidad_contagio(numeric, numeric, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: modulo4; Owner: postgres
--

CREATE FUNCTION modulo4.fn_calcular_probabilidad_contagio(p_fs numeric, p_fa numeric, p_fd numeric, p_w_fs numeric DEFAULT 0.4, p_w_fa numeric DEFAULT 0.3, p_w_fd numeric DEFAULT 0.3) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    RETURN p_w_fs * p_fs + p_w_fa * p_fa + p_w_fd * p_fd;
END;
$$;


ALTER FUNCTION modulo4.fn_calcular_probabilidad_contagio(p_fs numeric, p_fa numeric, p_fd numeric, p_w_fs numeric, p_w_fa numeric, p_w_fd numeric) OWNER TO postgres;

--
-- Name: fn_contar_registros_etiquetados_disponibles(date, date, modulo4.enum_version_modelo_algoritmo); Type: FUNCTION; Schema: modulo4; Owner: postgres
--

CREATE FUNCTION modulo4.fn_contar_registros_etiquetados_disponibles(p_fecha_inicio date, p_fecha_fin date, p_tipo_modelo modulo4.enum_version_modelo_algoritmo DEFAULT NULL::modulo4.enum_version_modelo_algoritmo) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INT;
BEGIN
    -- Cuenta observaciones clínicas con signos en el rango de fechas.
    SELECT COUNT(*)
    INTO v_count
    FROM modulo4.observaciones_clinicas oc
    WHERE oc.fecha BETWEEN p_fecha_inicio AND p_fecha_fin
      AND EXISTS (
          SELECT 1 FROM modulo4.detalles_signos
          WHERE id_observaciones = oc.id_observacion_clinica
      );

    RETURN v_count;
END;
$$;


ALTER FUNCTION modulo4.fn_contar_registros_etiquetados_disponibles(p_fecha_inicio date, p_fecha_fin date, p_tipo_modelo modulo4.enum_version_modelo_algoritmo) OWNER TO postgres;

--
-- Name: fn_dataset_hash_sha256(integer); Type: FUNCTION; Schema: modulo4; Owner: postgres
--

CREATE FUNCTION modulo4.fn_dataset_hash_sha256(p_id_dataset integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_hash VARCHAR(64);
BEGIN
    SELECT ENCODE(DIGEST(
        nombre ||
        to_char(fecha_inicio_datos, 'YYYY-MM-DD') ||
        to_char(fecha_fin_datos, 'YYYY-MM-DD') ||
        COALESCE(enfermedades_incluidas::TEXT, ''),
        'sha256'
    ), 'hex')
    INTO v_hash
    FROM modulo4.datasets
    WHERE id_dataset = p_id_dataset;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Dataset % no encontrado', p_id_dataset;
    END IF;

    RETURN v_hash;
END;
$$;


ALTER FUNCTION modulo4.fn_dataset_hash_sha256(p_id_dataset integer) OWNER TO postgres;

--
-- Name: fn_detectar_conflicto_retroalimentacion(integer); Type: FUNCTION; Schema: modulo4; Owner: postgres
--

CREATE FUNCTION modulo4.fn_detectar_conflicto_retroalimentacion(p_id_prediccion integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_evaluaciones TEXT[];
BEGIN
    SELECT ARRAY_AGG(DISTINCT datos_nuevos->>'evaluacion')
    INTO v_evaluaciones
    FROM modulo4.auditorias_predicciones
    WHERE id_prediccion = p_id_prediccion
      AND accion = 'VALIDACION_VET'
      AND datos_nuevos->>'evaluacion' IS NOT NULL;

    RETURN v_evaluaciones IS NOT NULL AND array_length(v_evaluaciones, 1) > 1;
END;
$$;


ALTER FUNCTION modulo4.fn_detectar_conflicto_retroalimentacion(p_id_prediccion integer) OWNER TO postgres;

--
-- Name: fn_obtener_historial_predicciones_paginado(integer, timestamp with time zone, timestamp with time zone, integer, text, integer); Type: FUNCTION; Schema: modulo4; Owner: postgres
--

CREATE FUNCTION modulo4.fn_obtener_historial_predicciones_paginado(p_id_activo integer, p_fecha_inicio timestamp with time zone, p_fecha_fin timestamp with time zone, p_id_patologia integer DEFAULT NULL::integer, p_cursor text DEFAULT ''::text, p_page_size integer DEFAULT 20) RETURNS TABLE(id_prediccion integer, probabilidad_pct numeric, clase_predicha modulo4.enum_predicciones_clase, fecha_prediccion timestamp with time zone, patologia integer, next_cursor text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_cursor_fecha TIMESTAMPTZ;
    v_cursor_id    INT;
BEGIN
    IF p_page_size > 50 THEN
        p_page_size := 50;
    END IF;

    IF p_cursor <> '' THEN
        v_cursor_fecha := split_part(p_cursor, ',', 1)::TIMESTAMPTZ;
        v_cursor_id    := split_part(p_cursor, ',', 2)::INT;
    END IF;

    RETURN QUERY
    WITH base AS (
        SELECT
            p.id_prediccion,
            p.probabilidad_pct,
            p.clase_predicha,
            p.fecha_prediccion,
            p.id_patologia AS patologia
        FROM modulo4.predicciones p
        JOIN modulo4.observaciones_clinicas oc
          ON p.id_observacion = oc.id_observacion_clinica
        WHERE oc.id_activo_biologico = p_id_activo
          AND p.fecha_prediccion BETWEEN p_fecha_inicio AND p_fecha_fin
          AND (p_id_patologia IS NULL OR p.id_patologia = p_id_patologia)
          AND (p_cursor = '' 
               OR (p.fecha_prediccion, p.id_prediccion) < (v_cursor_fecha, v_cursor_id))
        ORDER BY p.fecha_prediccion DESC, p.id_prediccion DESC
        LIMIT p_page_size + 1  -- una fila extra para saber si hay siguiente página
    ),
    paged AS (
        SELECT *, row_number() OVER () AS rn
        FROM base
    ),
    with_cursor AS (
        SELECT
            paged.id_prediccion,
            paged.probabilidad_pct,
            paged.clase_predicha,
            paged.fecha_prediccion,
            paged.patologia,
            CASE
                -- Para la última fila visible (rn = page_size) tomamos el cursor de la siguiente si existe
                WHEN paged.rn = p_page_size THEN
                    (SELECT to_char(next_pred.fecha_prediccion, 'YYYY-MM-DD HH24:MI:SS TZ') || ',' || next_pred.id_prediccion
                     FROM paged next_pred WHERE next_pred.rn = p_page_size + 1)
                ELSE ''  -- filas anteriores llevan cursor vacío
            END AS next_cursor
        FROM paged
        WHERE paged.rn <= p_page_size  -- solo devolvemos las filas de la página
    )
    SELECT * FROM with_cursor;
END;
$$;


ALTER FUNCTION modulo4.fn_obtener_historial_predicciones_paginado(p_id_activo integer, p_fecha_inicio timestamp with time zone, p_fecha_fin timestamp with time zone, p_id_patologia integer, p_cursor text, p_page_size integer) OWNER TO postgres;

--
-- Name: fn_obtener_modelo_activo_por_especie(character varying); Type: FUNCTION; Schema: modulo4; Owner: postgres
--

CREATE FUNCTION modulo4.fn_obtener_modelo_activo_por_especie(p_especie character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_algoritmo modulo4.enum_version_modelo_algoritmo;
    v_id INT;
BEGIN
    -- Mapeo simple especie -> algoritmo esperado
    v_algoritmo := CASE p_especie
        WHEN 'pequeña' THEN 'RANDOM_FOREST'::modulo4.enum_version_modelo_algoritmo
        WHEN 'mediana' THEN 'XGBOOST'::modulo4.enum_version_modelo_algoritmo
        WHEN 'grande'  THEN 'RED_BAYESIANA'::modulo4.enum_version_modelo_algoritmo
        ELSE NULL
    END;

    IF v_algoritmo IS NULL THEN
        RAISE EXCEPTION 'Especie no soportada: %', p_especie;
    END IF;

    SELECT id_version_modelo INTO v_id
    FROM modulo4.versiones_modelos
    WHERE algoritmo = v_algoritmo
      AND esta_produccion = TRUE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'No hay modelo activo para especie %', p_especie;
    END IF;

    RETURN v_id;
END;
$$;


ALTER FUNCTION modulo4.fn_obtener_modelo_activo_por_especie(p_especie character varying) OWNER TO postgres;

--
-- Name: fn_prioridad_etiqueta_retroalimentacion(integer[]); Type: FUNCTION; Schema: modulo4; Owner: postgres
--

CREATE FUNCTION modulo4.fn_prioridad_etiqueta_retroalimentacion(p_ids integer[]) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_best_id INT;
    v_best_rank INT := -1;
    rec RECORD;
    v_rank INT;
    v_eval TEXT;
    v_fuente TEXT;
BEGIN
    FOR rec IN
        SELECT id_auditoria_prediccion,
               datos_nuevos->>'evaluacion' AS evaluacion,
               datos_nuevos->>'fuente_diagnostico' AS fuente
        FROM modulo4.auditorias_predicciones
        WHERE id_auditoria_prediccion = ANY(p_ids)
          AND accion = 'VALIDACION_VET'
    LOOP
        v_eval := rec.evaluacion;
        v_fuente := rec.fuente;
        
        -- Prioridad por severidad
        v_rank := CASE v_eval
            WHEN 'INCORRECTO' THEN 300
            WHEN 'PARCIAL'    THEN 200
            WHEN 'CORRECTO'   THEN 100
            ELSE 0
        END;
        
        -- Ajuste por fuente
        v_rank := v_rank + CASE COALESCE(v_fuente, 'fuente_desconocida')
            WHEN 'LABORATORIO'        THEN 50
            WHEN 'HISTORIAL_CLINICO'  THEN 40
            WHEN 'OBSERVACION_DIRECTA' THEN 30
            WHEN 'OTRO'               THEN 20
            ELSE 10
        END;
        
        IF v_rank > v_best_rank THEN
            v_best_rank := v_rank;
            v_best_id := rec.id_auditoria_prediccion;
        END IF;
    END LOOP;

    RETURN v_best_id;
END;
$$;


ALTER FUNCTION modulo4.fn_prioridad_etiqueta_retroalimentacion(p_ids integer[]) OWNER TO postgres;

--
-- Name: fn_supera_umbral_clasificacion(numeric, numeric); Type: FUNCTION; Schema: modulo4; Owner: postgres
--

CREATE FUNCTION modulo4.fn_supera_umbral_clasificacion(p_probabilidad numeric, p_umbral numeric DEFAULT 70.0) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    RETURN p_probabilidad >= p_umbral;
END;
$$;


ALTER FUNCTION modulo4.fn_supera_umbral_clasificacion(p_probabilidad numeric, p_umbral numeric) OWNER TO postgres;

--
-- Name: fn_validar_metricas_modelo(numeric, numeric); Type: FUNCTION; Schema: modulo4; Owner: postgres
--

CREATE FUNCTION modulo4.fn_validar_metricas_modelo(p_f1_score numeric, p_recall numeric) RETURNS modulo4.resultado_validacion
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result modulo4.resultado_validacion;
BEGIN
    IF p_f1_score >= 0.80 AND p_recall >= 0.85 THEN
        v_result.estado := 'APROBADO';
        v_result.campo_fallido := NULL;
    ELSE
        v_result.estado := 'RECHAZADO';
        v_result.campo_fallido := CASE
            WHEN p_f1_score < 0.80 THEN 'f1_score'
            ELSE 'recall'
        END;
    END IF;
    RETURN v_result;
END;
$$;


ALTER FUNCTION modulo4.fn_validar_metricas_modelo(p_f1_score numeric, p_recall numeric) OWNER TO postgres;

--
-- Name: fn_verificar_integridad_artefacto(integer, character varying); Type: FUNCTION; Schema: modulo4; Owner: postgres
--

CREATE FUNCTION modulo4.fn_verificar_integridad_artefacto(p_id_version_modelo integer, p_hash_calculado character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_hash_almacenado VARCHAR(64);
BEGIN
    SELECT hash_artecfacto INTO v_hash_almacenado
    FROM modulo4.versiones_modelos
    WHERE id_version_modelo = p_id_version_modelo;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Modelo % no existe', p_id_version_modelo;
    END IF;

    RETURN p_hash_calculado = v_hash_almacenado;
END;
$$;


ALTER FUNCTION modulo4.fn_verificar_integridad_artefacto(p_id_version_modelo integer, p_hash_calculado character varying) OWNER TO postgres;

--
-- Name: fn_verificar_ventana_retroalimentacion(integer, date); Type: FUNCTION; Schema: modulo4; Owner: postgres
--

CREATE FUNCTION modulo4.fn_verificar_ventana_retroalimentacion(p_id_prediccion integer, p_fecha_actual date DEFAULT CURRENT_DATE) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_fecha_prediccion DATE;
BEGIN
    SELECT fecha_prediccion::DATE INTO v_fecha_prediccion
    FROM modulo4.predicciones
    WHERE id_prediccion = p_id_prediccion;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Predicción % no existe', p_id_prediccion;
    END IF;

    RETURN (p_fecha_actual - v_fecha_prediccion) <= 90;
END;
$$;


ALTER FUNCTION modulo4.fn_verificar_ventana_retroalimentacion(p_id_prediccion integer, p_fecha_actual date) OWNER TO postgres;

--
-- Name: sp_actualizar_estado_alerta(integer, modulo4.enum_alerta_patologia_estado, integer, text, boolean); Type: PROCEDURE; Schema: modulo4; Owner: postgres
--

CREATE PROCEDURE modulo4.sp_actualizar_estado_alerta(IN p_id_alerta_patologica integer, IN p_nuevo_estado modulo4.enum_alerta_patologia_estado, IN p_id_usuario integer, IN p_diagnostico_confirmado text DEFAULT NULL::text, IN p_es_verdadero boolean DEFAULT NULL::boolean)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado_actual modulo4.enum_alerta_patologia_estado;
BEGIN
    SELECT estado_alerta
    INTO   v_estado_actual
    FROM   modulo4.alertas_patologicas
    WHERE  id_alerta_patologica = p_id_alerta_patologica;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Alerta % no encontrada', p_id_alerta_patologica;
    END IF;

    -- No permitir retroceder a PENDIENTE
    IF p_nuevo_estado = 'PENDIENTE' THEN
        RAISE EXCEPTION
            'No se permite regresar al estado PENDIENTE. Estado actual: %',
            v_estado_actual;
    END IF;

    -- Campos mutables según trigger de inmutabilidad
    UPDATE modulo4.alertas_patologicas
    SET
        estado_alerta          = p_nuevo_estado,
        fecha_notificacion     = now(),
        id_usuario             = p_id_usuario,
        diagnostico_confirmado = COALESCE(p_diagnostico_confirmado, diagnostico_confirmado),
        es_verdadero           = COALESCE(p_es_verdadero, es_verdadero)
    WHERE id_alerta_patologica = p_id_alerta_patologica;
END;
$$;


ALTER PROCEDURE modulo4.sp_actualizar_estado_alerta(IN p_id_alerta_patologica integer, IN p_nuevo_estado modulo4.enum_alerta_patologia_estado, IN p_id_usuario integer, IN p_diagnostico_confirmado text, IN p_es_verdadero boolean) OWNER TO postgres;

--
-- Name: sp_aprobar_y_activar_version_modelo(integer, integer); Type: PROCEDURE; Schema: modulo4; Owner: postgres
--

CREATE PROCEDURE modulo4.sp_aprobar_y_activar_version_modelo(IN p_id_version_modelo integer, IN p_id_usuario integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_en_produccion  BOOLEAN;
    v_f1_score       NUMERIC(5,4);
    v_recall_modelo  NUMERIC(5,4);
    v_validacion     modulo4.resultado_validacion;
BEGIN
    SELECT esta_produccion, f1_score, recall_modelo
    INTO   v_en_produccion, v_f1_score, v_recall_modelo
    FROM   modulo4.versiones_modelos
    WHERE  id_version_modelo = p_id_version_modelo;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'Versión de modelo % no encontrada',
            p_id_version_modelo;
    END IF;

    -- Validar que no esté ya en producción
    IF v_en_produccion = true THEN
        RAISE EXCEPTION
            'VERSION_YA_ACTIVA: El modelo % ya está en producción.',
            p_id_version_modelo
        USING ERRCODE = 'P0421';
    END IF;

    -- Validar que las métricas hayan sido evaluadas
    IF v_f1_score IS NULL OR v_recall_modelo IS NULL THEN
        RAISE EXCEPTION
            'METRICAS_PENDIENTES: El modelo % no tiene métricas evaluadas. '
            'Debe pasar primero por sp_registrar_version_modelo.',
            p_id_version_modelo
        USING ERRCODE = 'P0422';
    END IF;

    -- Revalidar métricas mínimas antes de activar
    v_validacion := modulo4.fn_validar_metricas_modelo(v_f1_score, v_recall_modelo);

    IF v_validacion.estado = 'RECHAZADO' THEN
        RAISE EXCEPTION
            'VERSION_RECHAZADA: El modelo % no cumple métricas mínimas para producción. '
            'Campo fallido: %.',
            p_id_version_modelo,
            v_validacion.campo_fallido
        USING ERRCODE = 'P0420';
    END IF;

    -- Activar modelo — el trigger trg_fn_versiones_modelos_unicidad_produccion
    -- desactiva automáticamente el modelo anterior del mismo algoritmo
    UPDATE modulo4.versiones_modelos
    SET
        esta_produccion  = true,
        fecha_despliegue = now()
    WHERE id_version_modelo = p_id_version_modelo;
END;
$$;


ALTER PROCEDURE modulo4.sp_aprobar_y_activar_version_modelo(IN p_id_version_modelo integer, IN p_id_usuario integer) OWNER TO postgres;

--
-- Name: sp_distribuir_modelo_ota(integer, character varying, integer[]); Type: PROCEDURE; Schema: modulo4; Owner: postgres
--

CREATE PROCEDURE modulo4.sp_distribuir_modelo_ota(IN p_id_version_modelo integer, IN p_hash_calculado character varying, IN p_dispositivos integer[])
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_en_produccion     BOOLEAN;
    v_nombre_version    VARCHAR(40);
    v_ruta_artefacto    TEXT;
    v_hash_valido       BOOLEAN;
    v_dispositivo       INTEGER;
    v_total             INTEGER;
    v_exitosos          INTEGER := 0;
    v_fallidos          INTEGER := 0;
BEGIN
    -- Validar que el modelo exista y esté en producción
    SELECT esta_produccion, nombre_version, ruta_artefacto
    INTO   v_en_produccion, v_nombre_version, v_ruta_artefacto
    FROM   modulo4.versiones_modelos
    WHERE  id_version_modelo = p_id_version_modelo;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'MODELO_NO_ENCONTRADO: La versión % no existe.',
            p_id_version_modelo
        USING ERRCODE = 'P0460';
    END IF;

    IF v_en_produccion = false THEN
        RAISE EXCEPTION
            'MODELO_NO_APROBADO: La versión % no está en producción. '
            'Solo se distribuyen modelos activos.',
            p_id_version_modelo
        USING ERRCODE = 'P0461';
    END IF;

    -- Validar dispositivos destino
    v_total := array_length(p_dispositivos, 1);

    IF v_total IS NULL OR v_total = 0 THEN
        RAISE EXCEPTION
            'DISPOSITIVOS_VACIOS: Debe indicar al menos un dispositivo destino.'
        USING ERRCODE = 'P0462';
    END IF;

    -- Verificar integridad del artefacto antes de distribuir
    v_hash_valido := modulo4.fn_verificar_integridad_artefacto(
        p_id_version_modelo,
        p_hash_calculado
    );

    IF NOT v_hash_valido THEN
        RAISE NOTICE
            'HASH_INVALIDO_DETECTADO: El hash proporcionado no coincide '
            'con el artefacto registrado para el modelo %. '
            'Distribución abortada. Se mantiene versión anterior activa.',
            p_id_version_modelo;
        RETURN;
    END IF;

    -- Distribuir a cada dispositivo
    FOREACH v_dispositivo IN ARRAY p_dispositivos
    LOOP
        BEGIN
            -- Simulación de distribución fragmentada por dispositivo
            -- En implementación real aquí iría la integración con el sistema OTA
            RAISE NOTICE
                'MODELO_DISTRIBUIDO_EDGE: Modelo % (%) distribuido a dispositivo %. '
                'Ruta: %.',
                p_id_version_modelo,
                v_nombre_version,
                v_dispositivo,
                v_ruta_artefacto;

            v_exitosos := v_exitosos + 1;

        EXCEPTION WHEN OTHERS THEN
            -- Fallo en dispositivo individual — continúa con los demás
            RAISE NOTICE
                'HASH_INVALIDO_DETECTADO: Fallo al distribuir a dispositivo %. '
                'Error: %. Se mantiene versión anterior activa en ese dispositivo.',
                v_dispositivo,
                SQLERRM;

            v_fallidos := v_fallidos + 1;
        END;
    END LOOP;

    -- Resumen final
    RAISE NOTICE
        'DISTRIBUCION_COMPLETADA: Modelo % → % exitosos, % fallidos de % dispositivos.',
        p_id_version_modelo,
        v_exitosos,
        v_fallidos,
        v_total;
END;
$$;


ALTER PROCEDURE modulo4.sp_distribuir_modelo_ota(IN p_id_version_modelo integer, IN p_hash_calculado character varying, IN p_dispositivos integer[]) OWNER TO postgres;

--
-- Name: sp_ejecutar_inferencia(integer, character varying, integer, integer, jsonb); Type: PROCEDURE; Schema: modulo4; Owner: postgres
--

CREATE PROCEDURE modulo4.sp_ejecutar_inferencia(IN p_id_activo integer, IN p_especie character varying, IN p_id_observacion integer, IN p_id_patologia integer, IN p_features_json jsonb, OUT p_id_prediccion integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_modelo INT;
    v_prob      NUMERIC;
    v_umbral    NUMERIC;
    v_ahora     TIMESTAMPTZ := now();
BEGIN
    -- Obtener modelo activo
    v_id_modelo := modulo4.fn_obtener_modelo_activo_por_especie(p_especie);

    -- Obtener umbral del modelo
    SELECT umbral_clasificacion INTO v_umbral
    FROM modulo4.versiones_modelos
    WHERE id_version_modelo = v_id_modelo;

    -- Simular cálculo de probabilidad (aquí se integraría el verdadero motor de inferencia)
    v_prob := 75.3;  -- ejemplo

    -- Insertar predicción
    INSERT INTO modulo4.predicciones
        (id_observacion, id_patologia, id_version_modelo,
         probabilidad_pct, supera_umbral, umbral_usado, clase_predicha,
         confianza_modelo, features_json, fecha_prediccion, tiempo_proceso_ms)
    VALUES
        (p_id_observacion, p_id_patologia, v_id_modelo,
         v_prob, (v_prob >= v_umbral), v_umbral,
         CASE WHEN v_prob >= v_umbral THEN 'POSITIVO'::modulo4.enum_predicciones_clase
              ELSE 'NEGATIVO'::modulo4.enum_predicciones_clase END,
         0.87, p_features_json, v_ahora, 150)
    RETURNING id_prediccion INTO p_id_prediccion;

    -- Si supera umbral, generar alerta
    IF (v_prob >= v_umbral) THEN
        CALL modulo4.sp_evaluar_umbral_y_generar_alerta(p_id_prediccion);
    END IF;

    COMMIT;
END;
$$;


ALTER PROCEDURE modulo4.sp_ejecutar_inferencia(IN p_id_activo integer, IN p_especie character varying, IN p_id_observacion integer, IN p_id_patologia integer, IN p_features_json jsonb, OUT p_id_prediccion integer) OWNER TO postgres;

--
-- Name: sp_ejecutar_inferencia(integer, character varying, integer, integer, jsonb, integer); Type: PROCEDURE; Schema: modulo4; Owner: postgres
--

CREATE PROCEDURE modulo4.sp_ejecutar_inferencia(IN p_id_activo integer, IN p_especie character varying, IN p_id_observacion integer, IN p_id_patologia integer, IN p_features_json jsonb, INOUT p_id_prediccion integer DEFAULT NULL::integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_modelo INT;
    v_prob      NUMERIC;
    v_umbral    NUMERIC;
    v_ahora     TIMESTAMPTZ := now();
BEGIN
    -- Obtener modelo activo
    v_id_modelo := modulo4.fn_obtener_modelo_activo_por_especie(p_especie);

    -- Obtener umbral del modelo
    SELECT umbral_clasificacion INTO v_umbral
    FROM modulo4.versiones_modelos
    WHERE id_version_modelo = v_id_modelo;

    -- Simular cálculo de probabilidad
    v_prob := 75.3;
    v_umbral := v_umbral * 100;  -- antes del INSERT
    -- Insertar predicción
    INSERT INTO modulo4.predicciones
        (id_observacion, id_patologia, id_version_modelo,
         probabilidad_pct, supera_umbral, umbral_usado, clase_predicha,
         confianza_modelo, features_json, fecha_prediccion, tiempo_proceso_ms)
    VALUES
        (p_id_observacion, p_id_patologia, v_id_modelo,
         v_prob, (v_prob >= v_umbral), v_umbral,
         CASE WHEN v_prob >= v_umbral THEN 'POSITIVO'::modulo4.enum_predicciones_clase
              ELSE 'NEGATIVO'::modulo4.enum_predicciones_clase END,
         0.87, p_features_json, v_ahora, 150)
    RETURNING id_prediccion INTO p_id_prediccion;

    -- Si supera umbral, generar alerta
    IF (v_prob >= v_umbral) THEN
        CALL modulo4.sp_evaluar_umbral_y_generar_alerta(p_id_prediccion);
    END IF;

    COMMIT;
END;
$$;


ALTER PROCEDURE modulo4.sp_ejecutar_inferencia(IN p_id_activo integer, IN p_especie character varying, IN p_id_observacion integer, IN p_id_patologia integer, IN p_features_json jsonb, INOUT p_id_prediccion integer) OWNER TO postgres;

--
-- Name: sp_evaluar_degradacion_modelo(integer, character varying, integer); Type: PROCEDURE; Schema: modulo4; Owner: postgres
--

CREATE PROCEDURE modulo4.sp_evaluar_degradacion_modelo(IN p_id_version_modelo integer, IN p_semestre character varying, IN p_id_usuario integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_f1_score          NUMERIC(5,4);
    v_algoritmo         modulo4.enum_version_modelo_algoritmo;
    v_en_produccion     BOOLEAN;
    v_drift_score       NUMERIC(5,4);
    v_count_verificados INTEGER;
    v_fecha_inicio      DATE := CURRENT_DATE - INTERVAL '30 days';
    v_fecha_fin         DATE := CURRENT_DATE;
    v_id_ciclo          INTEGER;
BEGIN
    -- Obtener datos del modelo
    SELECT esta_produccion, f1_score, algoritmo
    INTO   v_en_produccion, v_f1_score, v_algoritmo
    FROM   modulo4.versiones_modelos
    WHERE  id_version_modelo = p_id_version_modelo;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'MODELO_NO_ENCONTRADO: La versión % no existe.',
            p_id_version_modelo
        USING ERRCODE = 'P0450';
    END IF;

    IF v_en_produccion = false THEN
        RAISE EXCEPTION
            'MODELO_NO_ACTIVO: La versión % no está en producción.',
            p_id_version_modelo
        USING ERRCODE = 'P0451';
    END IF;

    -- Calcular drift score últimos 30 días
    v_drift_score := modulo4.fn_calcular_drift_score(
        p_id_version_modelo,
        p_semestre
    );

    -- Contar registros verificados últimos 30 días
    v_count_verificados := modulo4.fn_contar_registros_etiquetados_disponibles(
        v_fecha_inicio,
        v_fecha_fin
    );

    -- Evaluar degradación
    IF v_f1_score < 0.80 THEN

        IF v_count_verificados < 100 THEN
            -- Insuficientes registros verificados — posponer
            RAISE NOTICE
                'DEGRADACION_DETECTADA_POSPUESTA: Modelo % con f1_score=%. '
                'Solo % registros verificados disponibles (mínimo 100). '
                'Notifique al administrador.',
                p_id_version_modelo,
                v_f1_score,
                v_count_verificados;
            RETURN;
        END IF;

        -- Suficientes registros — iniciar reentrenamiento
        CALL modulo4.sp_iniciar_ciclo_reentrenamiento(
            p_trigger_reentrenamiento  := 'DEGRADACION',
            p_semestre                 := p_semestre,
            p_fecha_inicio_planificada := v_fecha_inicio,
            p_fecha_final_planificada  := v_fecha_fin,
            p_id_modelo_anterior       := p_id_version_modelo,
            p_id_usuario               := p_id_usuario,
            p_notas                    :=
                'Reentrenamiento por degradación. f1_score=' ||
                v_f1_score::TEXT ||
                ' drift_score=' || v_drift_score::TEXT,
            p_id_ciclo_entrenamiento   := v_id_ciclo
        );

        RAISE NOTICE
            'DEGRADACION_DETECTADA: Ciclo de reentrenamiento % iniciado '
            'para modelo % por f1_score=% < 0.80.',
            v_id_ciclo,
            p_id_version_modelo,
            v_f1_score;
    ELSE
        RAISE NOTICE
            'MODELO_ESTABLE: Modelo % con f1_score=% >= 0.80. '
            'No se requiere reentrenamiento.',
            p_id_version_modelo,
            v_f1_score;
    END IF;
END;
$$;


ALTER PROCEDURE modulo4.sp_evaluar_degradacion_modelo(IN p_id_version_modelo integer, IN p_semestre character varying, IN p_id_usuario integer) OWNER TO postgres;

--
-- Name: sp_evaluar_umbral_y_generar_alerta(integer, integer, integer); Type: PROCEDURE; Schema: modulo4; Owner: postgres
--

CREATE PROCEDURE modulo4.sp_evaluar_umbral_y_generar_alerta(IN p_id_prediccion integer, IN p_id_finca integer, IN p_id_notificacion integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_prob         NUMERIC(6,3);
    v_umbral       NUMERIC(5,2);
    v_supera       BOOLEAN;
    v_id_activo    INTEGER;
    v_id_patologia INTEGER;
    v_criticidad   VARCHAR(20);
BEGIN
    -- Obtener datos de la predicción y su observación
    SELECT p.probabilidad_pct,
           p.umbral_usado,
           p.id_patologia,
           oc.id_activo_biologico
    INTO   v_prob, v_umbral, v_id_patologia, v_id_activo
    FROM   modulo4.predicciones p
    JOIN   modulo4.observaciones_clinicas oc
           ON p.id_observacion = oc.id_observacion_clinica
    WHERE  p.id_prediccion = p_id_prediccion;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Predicción % no encontrada', p_id_prediccion;
    END IF;

    -- Evaluar umbral
    v_supera := modulo4.fn_supera_umbral_clasificacion(v_prob, v_umbral);

    IF NOT v_supera THEN
        RETURN;
    END IF;

    -- Derivar criticidad desde la probabilidad
    v_criticidad := CASE
        WHEN v_prob >= 90 THEN 'CRITICA'
        WHEN v_prob >= 80 THEN 'ALTA'
        WHEN v_prob >= 70 THEN 'MEDIA'
        ELSE                   'BAJA'
    END;

    -- Insertar alerta
    INSERT INTO modulo4.alertas_patologicas
        (id_prediccion, id_activo_biologico, id_finca, id_patologia,
         probabilidad_pct, nivel_criticidad, estado_alerta, id_notificacion)
    VALUES
        (p_id_prediccion, v_id_activo, p_id_finca, v_id_patologia,
         v_prob, v_criticidad, 'PENDIENTE', p_id_notificacion);

    -- Auditoría
    INSERT INTO modulo4.auditorias_predicciones
        (id_prediccion, accion, datos_nuevos)
    VALUES
        (p_id_prediccion,
         'ALERTA_ACTIVADA',
         jsonb_build_object(
             'nivel_criticidad', v_criticidad,
             'probabilidad_pct', v_prob
         ));
END;
$$;


ALTER PROCEDURE modulo4.sp_evaluar_umbral_y_generar_alerta(IN p_id_prediccion integer, IN p_id_finca integer, IN p_id_notificacion integer) OWNER TO postgres;

--
-- Name: sp_iniciar_ciclo_reentrenamiento(character varying, character varying, date, date, integer, integer, text); Type: PROCEDURE; Schema: modulo4; Owner: postgres
--

CREATE PROCEDURE modulo4.sp_iniciar_ciclo_reentrenamiento(IN p_trigger_reentrenamiento character varying, IN p_semestre character varying, IN p_fecha_inicio_planificada date, IN p_fecha_final_planificada date, IN p_id_modelo_anterior integer, IN p_id_usuario integer, IN p_notas text, OUT p_id_ciclo_entrenamiento integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tipo_ciclo   modulo4.enum_ciclo_entrenamiento_tipo;
    v_count        INTEGER;
    v_drift_score  NUMERIC(5,4);
BEGIN
    v_tipo_ciclo := CASE p_trigger_reentrenamiento
        WHEN 'PROGRAMADO'  THEN 'SEMESTRAL'::modulo4.enum_ciclo_entrenamiento_tipo
        WHEN 'DEGRADACION' THEN 'DRIFT_DETECTADO'::modulo4.enum_ciclo_entrenamiento_tipo
        WHEN 'MANUAL'      THEN 'MANUAL'::modulo4.enum_ciclo_entrenamiento_tipo
        ELSE NULL
    END;

    IF v_tipo_ciclo IS NULL THEN
        RAISE EXCEPTION
            'TRIGGER_INVALIDO: "%" no es un trigger válido. '
            'Use: PROGRAMADO, MANUAL, DEGRADACION.',
            p_trigger_reentrenamiento
        USING ERRCODE = 'P0440';
    END IF;

    v_count := modulo4.fn_contar_registros_etiquetados_disponibles(
        p_fecha_inicio_planificada,
        p_fecha_final_planificada
    );

    IF v_count < 500 THEN
        RAISE EXCEPTION
            'DATASET_INSUFICIENTE: Se encontraron % registros etiquetados. '
            'Se requieren mínimo 500. Rango: % → %.',
            v_count,
            p_fecha_inicio_planificada,
            p_fecha_final_planificada
        USING ERRCODE = 'P0441';
    END IF;

    IF v_tipo_ciclo = 'DRIFT_DETECTADO' THEN
        v_drift_score := modulo4.fn_calcular_drift_score(
            p_id_modelo_anterior,
            p_semestre
        );
    END IF;

    INSERT INTO modulo4.ciclos_entrenamientos
        (id_modelo_version_anterior, semestre, estado_ciclo,
         fecha_inicio_planificada, fecha_final_planificada,
         inicio_planificada, tipo, drift_score,
         id_usuario_aprobado, notas)
    VALUES
        (p_id_modelo_anterior, p_semestre, 'PLANIFICADO',
         p_fecha_inicio_planificada, p_fecha_final_planificada,
         now(), v_tipo_ciclo, v_drift_score,
         p_id_usuario, p_notas)
    RETURNING id_ciclo_entrenamiento INTO p_id_ciclo_entrenamiento;

    UPDATE modulo4.ciclos_entrenamientos
    SET
        estado_ciclo = 'EN_PROCESO',
        inicio_real  = now()
    WHERE id_ciclo_entrenamiento = p_id_ciclo_entrenamiento;
END;
$$;


ALTER PROCEDURE modulo4.sp_iniciar_ciclo_reentrenamiento(IN p_trigger_reentrenamiento character varying, IN p_semestre character varying, IN p_fecha_inicio_planificada date, IN p_fecha_final_planificada date, IN p_id_modelo_anterior integer, IN p_id_usuario integer, IN p_notas text, OUT p_id_ciclo_entrenamiento integer) OWNER TO postgres;

--
-- Name: sp_registrar_observacion_clinica(integer, integer, timestamp with time zone, numeric, integer, integer, numeric, text, jsonb, character varying); Type: PROCEDURE; Schema: modulo4; Owner: postgres
--

CREATE PROCEDURE modulo4.sp_registrar_observacion_clinica(IN p_id_activo integer, IN p_id_usuario integer, IN p_fecha timestamp with time zone, IN p_temp numeric, IN p_fc integer, IN p_fr integer, IN p_bcs numeric, IN p_nota text, IN p_signos_json jsonb, IN p_fuente character varying DEFAULT 'manual'::character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_obs INT;
    rec JSONB;
BEGIN
    -- Insertar observación
    INSERT INTO modulo4.observaciones_clinicas
        (id_activo_biologico, id_usuario, fecha, temperatura_rectal,
         frecuencia_cardiaca, frecuencia_respiratoria, condicion_corporal,
         observacion, fuente_datos)
    VALUES
        (p_id_activo, p_id_usuario, p_fecha, p_temp,
         p_fc, p_fr, p_bcs, p_nota, p_fuente)
    RETURNING id_observacion_clinica INTO v_id_obs;

    -- Insertar signos
    FOR rec IN SELECT * FROM jsonb_array_elements(p_signos_json)
    LOOP
        INSERT INTO modulo4.detalles_signos
            (id_observaciones, id_signo_clinico, es_presente,
             valor_numerico, intensidad, notas)
        VALUES
            (v_id_obs,
             (rec->>'id_signo')::INT,
             COALESCE((rec->>'es_presente')::BOOLEAN, TRUE),
             (rec->>'valor')::NUMERIC,
             (rec->>'intensidad')::INT2,
             rec->>'notas');
    END LOOP;


    COMMIT;
END;
$$;


ALTER PROCEDURE modulo4.sp_registrar_observacion_clinica(IN p_id_activo integer, IN p_id_usuario integer, IN p_fecha timestamp with time zone, IN p_temp numeric, IN p_fc integer, IN p_fr integer, IN p_bcs numeric, IN p_nota text, IN p_signos_json jsonb, IN p_fuente character varying) OWNER TO postgres;

--
-- Name: sp_registrar_retroalimentacion_clinica(integer, integer, character varying, character varying, text, text); Type: PROCEDURE; Schema: modulo4; Owner: postgres
--

CREATE PROCEDURE modulo4.sp_registrar_retroalimentacion_clinica(IN p_id_prediccion integer, IN p_id_usuario integer, IN p_evaluacion character varying, IN p_fuente character varying, IN p_diagnostico_real text DEFAULT NULL::text, IN p_notas text DEFAULT NULL::text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_dentro_ventana  BOOLEAN;
    v_hay_conflicto   BOOLEAN;
    v_ya_existe       BOOLEAN;
BEGIN
    -- Validar que la predicción exista
    IF NOT EXISTS (
        SELECT 1 FROM modulo4.predicciones
        WHERE id_prediccion = p_id_prediccion
    ) THEN
        RAISE EXCEPTION
            'PREDICCION_NO_ENCONTRADA: La predicción % no existe.',
            p_id_prediccion
        USING ERRCODE = 'P0430';
    END IF;

    -- Validar dominio de evaluacion
    IF p_evaluacion NOT IN ('CORRECTO', 'PARCIAL', 'INCORRECTO', 'SIN_EVENTO') THEN
        RAISE EXCEPTION
            'EVALUACION_INVALIDA: El valor "%" no pertenece al dominio permitido. '
            'Use: CORRECTO, PARCIAL, INCORRECTO, SIN_EVENTO.',
            p_evaluacion
        USING ERRCODE = 'P0431';
    END IF;

    -- Validar que no exista retroalimentación previa del mismo usuario
    SELECT EXISTS (
        SELECT 1 FROM modulo4.auditorias_predicciones
        WHERE id_prediccion = p_id_prediccion
          AND id_usuario    = p_id_usuario
          AND accion        = 'VALIDACION_VET'
    ) INTO v_ya_existe;

    IF v_ya_existe THEN
        RAISE EXCEPTION
            'RETROALIMENTACION_DUPLICADA: El usuario % ya registró retroalimentación '
            'para la predicción %.',
            p_id_usuario,
            p_id_prediccion
        USING ERRCODE = 'P0432';
    END IF;

    -- Validar ventana temporal (90 días)
    v_dentro_ventana := modulo4.fn_verificar_ventana_retroalimentacion(p_id_prediccion);

    IF NOT v_dentro_ventana THEN
        RAISE EXCEPTION
            'VENTANA_EXPIRADA: La predicción % supera los 90 días permitidos '
            'para registrar retroalimentación.',
            p_id_prediccion
        USING ERRCODE = 'P0433';
    END IF;

    -- Insertar retroalimentación
    INSERT INTO modulo4.auditorias_predicciones
        (id_prediccion, accion, id_usuario, datos_nuevos)
    VALUES
        (p_id_prediccion,
         'VALIDACION_VET',
         p_id_usuario,
         jsonb_build_object(
             'evaluacion',       p_evaluacion,
             'fuente_diagnostico', p_fuente,
             'diagnostico_real', p_diagnostico_real,
             'notas',            p_notas
         ));

    -- Detectar conflicto con retroalimentaciones previas
    v_hay_conflicto := modulo4.fn_detectar_conflicto_retroalimentacion(p_id_prediccion);

    IF v_hay_conflicto THEN
        INSERT INTO modulo4.auditorias_predicciones
            (id_prediccion, accion, id_usuario, datos_nuevos)
        VALUES
            (p_id_prediccion,
             'VALIDACION_VET',
             p_id_usuario,
             jsonb_build_object(
                 'evento',       'CONFLICTO_RETROALIMENTACION',
                 'id_prediccion', p_id_prediccion
             ));
    END IF;
END;
$$;


ALTER PROCEDURE modulo4.sp_registrar_retroalimentacion_clinica(IN p_id_prediccion integer, IN p_id_usuario integer, IN p_evaluacion character varying, IN p_fuente character varying, IN p_diagnostico_real text, IN p_notas text) OWNER TO postgres;

--
-- Name: sp_registrar_version_modelo(character varying, modulo4.enum_version_modelo_algoritmo, text, timestamp with time zone, numeric, numeric, numeric, numeric, numeric, numeric, text, character varying, integer, character varying, date, date, integer, integer, integer, json, text, numeric, numeric, boolean, modulo4.enum_datset_semestre); Type: PROCEDURE; Schema: modulo4; Owner: postgres
--

CREATE PROCEDURE modulo4.sp_registrar_version_modelo(IN p_nombre_version character varying, IN p_algoritmo modulo4.enum_version_modelo_algoritmo, IN p_descripcion text, IN p_fecha_entrenamiento timestamp with time zone, IN p_accuracy numeric, IN p_auc_roc numeric, IN p_f1_score numeric, IN p_precision_modelo numeric, IN p_recall_modelo numeric, IN p_umbral_clasificacion numeric, IN p_ruta_artefacto text, IN p_hash_artecfacto character varying, IN p_id_usuario integer, IN p_nombre_dataset character varying, IN p_fecha_inicio_datos date, IN p_fecha_fin_datos date, IN p_total_registros integer, IN p_registros_positivos integer, IN p_registros_negativos integer, IN p_enfermedades_incluidas json, IN p_descripcion_dataset text, IN p_porcentaje_train numeric, IN p_porcentaje_test numeric, IN p_tiene_variables_amb boolean, IN p_semestre_huila modulo4.enum_datset_semestre, OUT p_id_version_modelo integer, OUT p_id_dataset integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_validacion modulo4.resultado_validacion;
BEGIN
    -- Validar métricas mínimas
    v_validacion := modulo4.fn_validar_metricas_modelo(p_f1_score, p_recall_modelo);

    IF v_validacion.estado = 'RECHAZADO' THEN
        RAISE EXCEPTION
            'VERSION_RECHAZADA: Métricas insuficientes. Campo fallido: %. '
            'f1_score=%, recall=%',
            v_validacion.campo_fallido,
            p_f1_score,
            p_recall_modelo
        USING ERRCODE = 'P0420';
    END IF;

    -- Insertar versión del modelo
    INSERT INTO modulo4.versiones_modelos
        (nombre_version, algoritmo, descripcion, fecha_entrenamiento,
         accuracy, auc_roc, f1_score, precision_modelo, recall_modelo,
         umbral_clasificacion, ruta_artefacto, hash_artecfacto,
         esta_produccion, id_usuario)
    VALUES
        (p_nombre_version, p_algoritmo, p_descripcion, p_fecha_entrenamiento,
         p_accuracy, p_auc_roc, p_f1_score, p_precision_modelo, p_recall_modelo,
         p_umbral_clasificacion, p_ruta_artefacto, p_hash_artecfacto,
         false, p_id_usuario)
    RETURNING id_version_modelo INTO p_id_version_modelo;

    -- Insertar dataset asociado
    INSERT INTO modulo4.datasets
        (id_version_modelo, nombre, fecha_inicio_datos, fecha_fin_datos,
         total_resgistros, registros_positivos, registros_negativos,
         enfermedades_incluidas, descripcion, porcentaje_train, porcentaje_test,
         tiene_variables_ambientales, semestre_huila)
    VALUES
        (p_id_version_modelo, p_nombre_dataset, p_fecha_inicio_datos, p_fecha_fin_datos,
         p_total_registros, p_registros_positivos, p_registros_negativos,
         p_enfermedades_incluidas, p_descripcion_dataset, p_porcentaje_train, p_porcentaje_test,
         p_tiene_variables_amb, p_semestre_huila)
    RETURNING id_dataset INTO p_id_dataset;
END;
$$;


ALTER PROCEDURE modulo4.sp_registrar_version_modelo(IN p_nombre_version character varying, IN p_algoritmo modulo4.enum_version_modelo_algoritmo, IN p_descripcion text, IN p_fecha_entrenamiento timestamp with time zone, IN p_accuracy numeric, IN p_auc_roc numeric, IN p_f1_score numeric, IN p_precision_modelo numeric, IN p_recall_modelo numeric, IN p_umbral_clasificacion numeric, IN p_ruta_artefacto text, IN p_hash_artecfacto character varying, IN p_id_usuario integer, IN p_nombre_dataset character varying, IN p_fecha_inicio_datos date, IN p_fecha_fin_datos date, IN p_total_registros integer, IN p_registros_positivos integer, IN p_registros_negativos integer, IN p_enfermedades_incluidas json, IN p_descripcion_dataset text, IN p_porcentaje_train numeric, IN p_porcentaje_test numeric, IN p_tiene_variables_amb boolean, IN p_semestre_huila modulo4.enum_datset_semestre, OUT p_id_version_modelo integer, OUT p_id_dataset integer) OWNER TO postgres;

--
-- Name: trg_fn_alertas_patologicas_inmutabilidad(); Type: FUNCTION; Schema: modulo4; Owner: postgres
--

CREATE FUNCTION modulo4.trg_fn_alertas_patologicas_inmutabilidad() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION
            'IMMUTABLE_ALERT: No se permite eliminar alertas patológicas. '
            'id_alerta_patologica=%. '
            'Requerimiento RF-67 — RF-73.'
            , OLD.id_alerta_patologica
        USING ERRCODE = 'P0403';
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF OLD.id_prediccion       IS DISTINCT FROM NEW.id_prediccion       OR
           OLD.id_activo_biologico IS DISTINCT FROM NEW.id_activo_biologico OR
           OLD.id_finca            IS DISTINCT FROM NEW.id_finca            OR
           OLD.id_patologia        IS DISTINCT FROM NEW.id_patologia        OR
           OLD.probabilidad_pct    IS DISTINCT FROM NEW.probabilidad_pct    OR
           OLD.nivel_criticidad    IS DISTINCT FROM NEW.nivel_criticidad    OR
           OLD.fecha_generacion    IS DISTINCT FROM NEW.fecha_generacion
        THEN
            RAISE EXCEPTION
                'IMMUTABLE_ALERT_FIELDS: Los campos estructurales de la alerta son inmutables. '
                'id_alerta_patologica=%. '
                'Solo se permite actualizar: estado_alerta, fecha_notificacion, '
                'diagnostico_confirmado, es_verdadero, id_usuario. '
                'Requerimiento RF-67 — RF-73.'
                , OLD.id_alerta_patologica
            USING ERRCODE = 'P0403';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo4.trg_fn_alertas_patologicas_inmutabilidad() OWNER TO postgres;

--
