--
-- Name: trg_fn_ciclos_entrenamientos_fechas_coherencia(); Type: FUNCTION; Schema: modulo4; Owner: postgres
--

CREATE FUNCTION modulo4.trg_fn_ciclos_entrenamientos_fechas_coherencia() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.fecha_inicio_planificada >= NEW.fecha_final_planificada THEN
        RAISE EXCEPTION
            'INVALID_DATE_RANGE: La fecha_inicio_planificada debe ser anterior a fecha_final_planificada. '
            'Recibido: inicio=%, fin=%. '
            'Requerimiento RF-71, Entradas — campo fecha_inicio_datos.'
            , NEW.fecha_inicio_planificada
            , NEW.fecha_final_planificada
        USING ERRCODE = 'P0415';
    END IF;

    IF NEW.inicio_real IS NOT NULL AND NEW.inicio_real > now() THEN
        RAISE EXCEPTION
            'INVALID_DATE_FUTURE: El campo inicio_real no puede ser una fecha futura. '
            'Valor recibido: %. '
            'Requerimiento RF-71.'
            , NEW.inicio_real
        USING ERRCODE = 'P0415';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo4.trg_fn_ciclos_entrenamientos_fechas_coherencia() OWNER TO postgres;

--
-- Name: trg_fn_ciclos_entrenamientos_inmutabilidad_completados(); Type: FUNCTION; Schema: modulo4; Owner: postgres
--

CREATE FUNCTION modulo4.trg_fn_ciclos_entrenamientos_inmutabilidad_completados() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.estado_ciclo IN ('COMPLETADO', 'CANCELADO') THEN
        RAISE EXCEPTION
            'IMMUTABLE_CYCLE: El ciclo de entrenamiento id=% en estado "%" no puede modificarse. '
            'Solo se permite modificar ciclos en estado PLANIFICADO o EN_EJECUCION. '
            'Requerimiento RF-71 RNF-11 — RF-73.'
            , OLD.id_ciclo_entrenamiento
            , OLD.estado_ciclo
        USING ERRCODE = 'P0409';
    END IF;

    RETURN NEW;
END;
$$;


