--
-- Name: trg_fn_versiones_modelos_hash_obligatorio(); Type: FUNCTION; Schema: modulo4; Owner: postgres
--

CREATE FUNCTION modulo4.trg_fn_versiones_modelos_hash_obligatorio() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
    IF NEW.hash_artecfacto IS NULL OR trim(NEW.hash_artecfacto) = '' THEN
        RAISE EXCEPTION
            'MISSING_HASH: El hash del artefacto del modelo es obligatorio. '
            'No se permite registrar versiones sin hash_artecfacto. '
            'Requerimiento RF-69, Restricción 8.'
        USING ERRCODE = 'P0406';
    END IF;

    IF length(trim(NEW.hash_artecfacto)) <> 64 THEN
        RAISE EXCEPTION
            'INVALID_HASH_LENGTH: El hash_artecfacto debe tener exactamente 64 caracteres (SHA-256). '
            'Longitud recibida: %. '
            'Requerimiento RF-69, Restricción 8.'
            , length(trim(NEW.hash_artecfacto))
        USING ERRCODE = 'P0406';
    END IF;

    IF trim(NEW.hash_artecfacto) !~ '^[a-fA-F0-9]{64}$' THEN
        RAISE EXCEPTION
            'INVALID_HASH_FORMAT: El hash_artecfacto contiene caracteres no hexadecimales. '
            'Solo se aceptan caracteres [0-9, a-f, A-F]. '
            'Requerimiento RF-69, Restricción 8.'
        USING ERRCODE = 'P0406';
    END IF;

    RETURN NEW;
END;
$_$;


ALTER FUNCTION modulo4.trg_fn_versiones_modelos_hash_obligatorio() OWNER TO postgres;

--
-- Name: trg_fn_versiones_modelos_inmutabilidad(); Type: FUNCTION; Schema: modulo4; Owner: postgres
--

CREATE FUNCTION modulo4.trg_fn_versiones_modelos_inmutabilidad() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION
            'IMMUTABLE_MODEL_VERSION: Las versiones de modelos son inmutables (append-only). '
            'No se permite eliminar id_version_modelo=%. '
            'Requerimiento RF-69, Restricción 7 — CA-8.'
            , OLD.id_version_modelo
        USING ERRCODE = 'P0401';
    END IF;

    IF TG_OP = 'UPDATE' THEN
        -- Se permite modificar únicamente las columnas operativas:
        --   esta_produccion, fecha_despliegue, fecha_retiro
        -- Cualquier otro cambio en los datos del modelo se rechaza.
        IF OLD.id_version_modelo  IS DISTINCT FROM NEW.id_version_modelo  OR
           OLD.nombre_version     IS DISTINCT FROM NEW.nombre_version     OR
           OLD.algoritmo          IS DISTINCT FROM NEW.algoritmo          OR
           OLD.descripcion        IS DISTINCT FROM NEW.descripcion        OR
           OLD.fecha_entrenamiento IS DISTINCT FROM NEW.fecha_entrenamiento OR
           OLD.accuracy           IS DISTINCT FROM NEW.accuracy           OR
           OLD.auc_roc            IS DISTINCT FROM NEW.auc_roc            OR
           OLD.f1_score           IS DISTINCT FROM NEW.f1_score           OR
           OLD.precision_modelo   IS DISTINCT FROM NEW.precision_modelo   OR
           OLD.recall_modelo      IS DISTINCT FROM NEW.recall_modelo      OR
           OLD.umbral_clasificacion IS DISTINCT FROM NEW.umbral_clasificacion OR
           OLD.ruta_artefacto     IS DISTINCT FROM NEW.ruta_artefacto     OR
           OLD.hash_artecfacto    IS DISTINCT FROM NEW.hash_artecfacto    OR
           OLD.id_usuario         IS DISTINCT FROM NEW.id_usuario
        THEN
            RAISE EXCEPTION
                'IMMUTABLE_MODEL_VERSION: Los campos científicos del modelo son inmutables. '
                'Solo se permite modificar: esta_produccion, fecha_despliegue, fecha_retiro. '
                'id_version_modelo=%. '
                'Requerimiento RF-69, Restricción 7 — CA-8.'
                , OLD.id_version_modelo
            USING ERRCODE = 'P0401';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo4.trg_fn_versiones_modelos_inmutabilidad() OWNER TO postgres;

--
-- Name: trg_fn_versiones_modelos_metricas_rango(); Type: FUNCTION; Schema: modulo4; Owner: postgres
--

CREATE FUNCTION modulo4.trg_fn_versiones_modelos_metricas_rango() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.accuracy IS NOT NULL AND (NEW.accuracy < 0.0 OR NEW.accuracy > 1.0) THEN
        RAISE EXCEPTION
            'METRIC_OUT_OF_RANGE: El campo accuracy=% está fuera del rango [0.0 - 1.0]. '
            'Requerimiento RF-69, Entradas — rango obligatorio.'
            , NEW.accuracy
        USING ERRCODE = 'P0414';
    END IF;

    IF NEW.auc_roc IS NOT NULL AND (NEW.auc_roc < 0.0 OR NEW.auc_roc > 1.0) THEN
        RAISE EXCEPTION
            'METRIC_OUT_OF_RANGE: El campo auc_roc=% está fuera del rango [0.0 - 1.0]. '
            'Requerimiento RF-69, Entradas — rango obligatorio.'
            , NEW.auc_roc
        USING ERRCODE = 'P0414';
    END IF;

    IF NEW.f1_score IS NOT NULL AND (NEW.f1_score < 0.0 OR NEW.f1_score > 1.0) THEN
        RAISE EXCEPTION
            'METRIC_OUT_OF_RANGE: El campo f1_score=% está fuera del rango [0.0 - 1.0]. '
            'Requerimiento RF-69, Entradas — rango obligatorio.'
            , NEW.f1_score
        USING ERRCODE = 'P0414';
    END IF;

    IF NEW.precision_modelo IS NOT NULL AND (NEW.precision_modelo < 0.0 OR NEW.precision_modelo > 1.0) THEN
        RAISE EXCEPTION
            'METRIC_OUT_OF_RANGE: El campo precision_modelo=% está fuera del rango [0.0 - 1.0]. '
            'Requerimiento RF-69, Entradas — rango obligatorio.'
            , NEW.precision_modelo
        USING ERRCODE = 'P0414';
    END IF;

    IF NEW.recall_modelo IS NOT NULL AND (NEW.recall_modelo < 0.0 OR NEW.recall_modelo > 1.0) THEN
        RAISE EXCEPTION
            'METRIC_OUT_OF_RANGE: El campo recall_modelo=% está fuera del rango [0.0 - 1.0]. '
            'Requerimiento RF-69, Entradas — rango obligatorio.'
            , NEW.recall_modelo
        USING ERRCODE = 'P0414';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo4.trg_fn_versiones_modelos_metricas_rango() OWNER TO postgres;

--
-- Name: trg_fn_versiones_modelos_unicidad_produccion(); Type: FUNCTION; Schema: modulo4; Owner: postgres
--

CREATE FUNCTION modulo4.trg_fn_versiones_modelos_unicidad_produccion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.esta_produccion = true THEN
        UPDATE modulo4.versiones_modelos
        SET    esta_produccion = false
        WHERE  algoritmo        = NEW.algoritmo
          AND  esta_produccion  = true
          AND  id_version_modelo <> NEW.id_version_modelo;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo4.trg_fn_versiones_modelos_unicidad_produccion() OWNER TO postgres;

--
-- Name: calcular_hash_integridad(); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.calcular_hash_integridad() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Calcula SHA-256 sobre todos los campos en orden alfabético (excluyendo hash_integridad)
  NEW.hash_integridad := encode(
    digest(
      (SELECT string_agg(
        format('%I=%L', key, value), ' & ' ORDER BY key
      ) FROM jsonb_each_text(to_jsonb(NEW) - 'hash_integridad' - 'creado_en' - 'id_registro_suministro')),
      'sha256'
    ), 'hex'
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION modulo5.calcular_hash_integridad() OWNER TO postgres;

--
-- Name: fn_acumular_costo_ciclo(); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.fn_acumular_costo_ciclo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_delta numeric;
  v_costo_original numeric;
BEGIN
  IF NEW.id_gestion_fases IS NULL THEN
    RAISE WARNING 'registro_suministro %: sin id_gestion_fases; no se acumula.', NEW.id_registro_suministro;
    RETURN NEW;
  END IF;

  IF NEW.tipo_operacion = 'CORRECCION' THEN
    SELECT costo_registro INTO v_costo_original
    FROM modulo5.registro_suministro WHERE id_registro_suministro = NEW.id_registro_original;
    v_delta := NEW.costo_registro - COALESCE(v_costo_original, 0);
  ELSE
    v_delta := NEW.costo_registro;
  END IF;

  -- UPDATE primero (no INSERT..ON CONFLICT): el CHECK chk_acumulado_no_negativo se evalúa
  -- contra el VALUES del INSERT antes de resolver el conflicto, así que un delta negativo
  -- de una CORRECCION haría fallar el candidato aunque el acumulado_total_ciclo resultante
  -- fuera positivo. Con UPDATE, el CHECK se evalúa contra el valor final correcto.
  UPDATE modulo5.acumulado_ciclo SET
    acumulado_total_ciclo = acumulado_total_ciclo + v_delta,
    acumulado_por_categoria = jsonb_set(
      COALESCE(acumulado_por_categoria, '{}'::jsonb),
      ARRAY[NEW.tipo_suministro],
      to_jsonb(COALESCE((acumulado_por_categoria ->> NEW.tipo_suministro)::numeric, 0) + v_delta)
    ),
    version_acumulado = version_acumulado + 1,
    fecha_ultima_actualizacion = now()
  WHERE id_gestion_fases = NEW.id_gestion_fases;

  IF NOT FOUND THEN
    -- Solo alcanzable desde un REGISTRO (una CORRECCION siempre referencia un
    -- id_registro_original cuyo REGISTRO ya creó esta fila) => v_delta > 0 aquí,
    -- así que ON CONFLICT DO UPDATE es seguro para la carrera de primer-insert concurrente.
    INSERT INTO modulo5.acumulado_ciclo
      (id_activo_biologico, id_ciclo_productivo, id_gestion_fases, acumulado_total_ciclo,
       acumulado_por_categoria, version_acumulado)
    VALUES
      (NEW.id_activo_biologico, NEW.id_ciclo_productivo, NEW.id_gestion_fases, v_delta,
       jsonb_build_object(NEW.tipo_suministro, v_delta), 0)
    ON CONFLICT (id_gestion_fases) DO UPDATE SET
      acumulado_total_ciclo = modulo5.acumulado_ciclo.acumulado_total_ciclo + v_delta,
      acumulado_por_categoria = jsonb_set(
        COALESCE(modulo5.acumulado_ciclo.acumulado_por_categoria, '{}'::jsonb),
        ARRAY[NEW.tipo_suministro],
        to_jsonb(COALESCE((modulo5.acumulado_ciclo.acumulado_por_categoria ->> NEW.tipo_suministro)::numeric, 0) + v_delta)
      ),
      version_acumulado = modulo5.acumulado_ciclo.version_acumulado + 1,
      fecha_ultima_actualizacion = now();
  END IF;

  RETURN NEW;
END; $$;


ALTER FUNCTION modulo5.fn_acumular_costo_ciclo() OWNER TO postgres;

--
-- Name: fn_calcular_data_quality_score(boolean, boolean, boolean, boolean); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.fn_calcular_data_quality_score(p_peso_ini boolean, p_peso_fin boolean, p_consumo boolean, p_valido boolean) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_presentes INT := 0;
BEGIN
    IF p_peso_ini THEN v_presentes := v_presentes + 1; END IF;
    IF p_peso_fin THEN v_presentes := v_presentes + 1; END IF;
    IF p_consumo  THEN v_presentes := v_presentes + 1; END IF;
    IF p_valido   THEN v_presentes := v_presentes + 1; END IF;

    RETURN ROUND((v_presentes::NUMERIC / 4) * 100, 2);
END;
$$;


ALTER FUNCTION modulo5.fn_calcular_data_quality_score(p_peso_ini boolean, p_peso_fin boolean, p_consumo boolean, p_valido boolean) OWNER TO postgres;

--
-- Name: fn_calcular_ica_periodo(integer, character varying, date, date); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.fn_calcular_ica_periodo(p_activo_id integer, p_periodo character varying, p_inicio date, p_fin date) RETURNS TABLE(ca_valor numeric, clasificacion text, data_quality_score numeric, datos_actualizados_hasta timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_peso_inicial         NUMERIC;
    v_peso_final           NUMERIC;
    v_ganancia_peso        NUMERIC;
    v_consumo_total        NUMERIC;
    v_ca                   NUMERIC;
    v_clasificacion        TEXT;
    v_score                NUMERIC;
    v_tiene_peso_ini       BOOLEAN := FALSE;
    v_tiene_peso_fin       BOOLEAN := FALSE;
    v_tiene_consumo        BOOLEAN := FALSE;
    v_tiene_valido         BOOLEAN := FALSE;
    v_actualizado_hasta    TIMESTAMPTZ;
BEGIN
    -- 1. Validar rango de fechas
    IF p_inicio > p_fin THEN
        RAISE EXCEPTION
            'RANGO_INVALIDO: La fecha de inicio [%] no puede ser posterior '
            'a la fecha de fin [%]. (RF-74)',
            p_inicio, p_fin
        USING ERRCODE = 'P0001';
    END IF;

    -- 2. Validar período
    IF p_periodo NOT IN ('SEMANAL', 'MENSUAL', 'POR_CICLO') THEN
        RAISE EXCEPTION
            'PERIODO_INVALIDO: El período [%] no es válido. '
            'Valores aceptados: SEMANAL, MENSUAL, POR_CICLO. (RF-74)',
            p_periodo
        USING ERRCODE = 'P0001';
    END IF;

    -- 3. Obtener peso inicial — primer registro del período
    SELECT peso_inicial_ciclo
    INTO v_peso_inicial
    FROM modulo5.mediciones_incrementales
    WHERE id_activo_biologico = p_activo_id
      AND fecha_medicion     >= p_inicio
      AND fecha_medicion     <= p_fin
    ORDER BY fecha_medicion ASC, fecha_creacion ASC
    LIMIT 1;

    IF FOUND AND v_peso_inicial IS NOT NULL THEN
        v_tiene_peso_ini := TRUE;
    END IF;

    -- 4. Obtener peso final — último registro del período
    SELECT peso_actual
    INTO v_peso_final
    FROM modulo5.mediciones_incrementales
    WHERE id_activo_biologico = p_activo_id
      AND fecha_medicion     >= p_inicio
      AND fecha_medicion     <= p_fin
    ORDER BY fecha_medicion DESC, fecha_creacion DESC
    LIMIT 1;

    IF FOUND AND v_peso_final IS NOT NULL THEN
        v_tiene_peso_fin := TRUE;
    END IF;

    -- 5. Obtener consumo acumulado de alimentos VALIDADO en el período
    SELECT COALESCE(SUM(cantidad_suministrada), 0)
    INTO v_consumo_total
    FROM modulo5.registros_consumo_alimentos
    WHERE id_activo_biologico = p_activo_id
      AND estado_registro     = 'VALIDADO'
      AND fecha_inicio_periodo >= p_inicio::TIMESTAMPTZ
      AND fecha_inicio_periodo <= p_fin::TIMESTAMPTZ;

    IF v_consumo_total > 0 THEN
        v_tiene_consumo := TRUE;
    END IF;

    -- 6. Verificar que hay registros VALIDADO en el período
    IF v_tiene_peso_ini AND v_tiene_peso_fin AND v_tiene_consumo THEN
        v_tiene_valido := TRUE;
    END IF;

    -- 7. Calcular data quality score
    v_score := modulo5.fn_calcular_data_quality_score(
        v_tiene_peso_ini,
        v_tiene_peso_fin,
        v_tiene_consumo,
        v_tiene_valido
    );

    -- 8. Calcular CA — si no hay datos suficientes retorna fila con score bajo
    IF v_tiene_peso_ini AND v_tiene_peso_fin AND v_tiene_consumo THEN
        v_ganancia_peso := v_peso_final - v_peso_inicial;

        IF v_ganancia_peso > 0 THEN
            v_ca := ROUND(v_consumo_total / v_ganancia_peso, 4);
        ELSE
            v_ca := 0;
        END IF;

        v_clasificacion := modulo5.fn_clasificar_eficiencia_ica(v_ca);
    ELSE
        v_ca            := NULL;
        v_clasificacion := NULL;
    END IF;

    -- 9. Timestamp de última actualización de datos del activo en el período
    SELECT MAX(fecha_creacion)
    INTO v_actualizado_hasta
    FROM modulo5.mediciones_incrementales
    WHERE id_activo_biologico = p_activo_id
      AND fecha_medicion     >= p_inicio
      AND fecha_medicion     <= p_fin;

    -- 10. Retornar resultado
    RETURN QUERY
    SELECT
        v_ca,
        v_clasificacion,
        v_score,
        v_actualizado_hasta;
END;
$$;


ALTER FUNCTION modulo5.fn_calcular_ica_periodo(p_activo_id integer, p_periodo character varying, p_inicio date, p_fin date) OWNER TO postgres;

--
-- Name: fn_clasificar_eficiencia_ica(numeric); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.fn_clasificar_eficiencia_ica(p_ca numeric) RETURNS text
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF p_ca IS NULL OR p_ca < 0 THEN
        RAISE EXCEPTION
            'CA_INVALIDO: El valor de conversión alimenticia no puede ser '
            'nulo ni negativo. Valor recibido: [%]. (RF-74)',
            p_ca
        USING ERRCODE = 'P0001';
    END IF;

    RETURN CASE
        WHEN p_ca > 0    AND p_ca <= 1.5  THEN 'EXCELENTE'
        WHEN p_ca > 1.5  AND p_ca <= 2.5  THEN 'ACEPTABLE'
        WHEN p_ca > 2.5  AND p_ca <= 3.5  THEN 'BAJA'
        ELSE                                    'CRITICA'
    END;
END;
$$;


ALTER FUNCTION modulo5.fn_clasificar_eficiencia_ica(p_ca numeric) OWNER TO postgres;

--
-- Name: fn_consultar_historial_suministros(integer, jsonb, integer, integer); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.fn_consultar_historial_suministros(p_activo_id integer, p_filtro jsonb, p_pagina integer, p_limite integer) RETURNS TABLE(id_historial integer, id_activo_biologico integer, origen modulo5.enum_historial_suministros_activos_origen, fecha_inicio date, fecha_fin date, costo_total_alimento numeric, costo_total_medicamento numeric, costo_total_suministros numeric, num_registros_alimento integer, num_registros_medicamento integer, formato_exportacion modulo5.enum_historial_suministros_activos_formatos_exportacion, fecha_consulta timestamp with time zone, monto_total_filtrado numeric, datos_actualizados_hasta timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_fecha_inicio      DATE;
    v_fecha_fin         DATE;
    v_origen            modulo5.enum_historial_suministros_activos_origen;
    v_offset            INT;
    v_monto_total       NUMERIC;
    v_actualizado_hasta TIMESTAMPTZ;
BEGIN
    -- 1. Validar parámetros de paginación
    IF p_pagina < 1 THEN
        RAISE EXCEPTION
            'PAGINACION_INVALIDA: El número de página debe ser mayor a cero. '
            'Valor recibido: [%]. (RF-81)',
            p_pagina
        USING ERRCODE = 'P0001';
    END IF;

    IF p_limite < 1 OR p_limite > 100 THEN
        RAISE EXCEPTION
            'LIMITE_INVALIDO: El límite de registros debe estar entre 1 y 100. '
            'Valor recibido: [%]. (RF-81)',
            p_limite
        USING ERRCODE = 'P0001';
    END IF;

    -- 2. Extraer filtros del JSONB
    v_fecha_inicio := (p_filtro->>'fecha_inicio')::DATE;
    v_fecha_fin    := (p_filtro->>'fecha_fin')::DATE;

    IF p_filtro->>'origen' IS NOT NULL THEN
        v_origen := (p_filtro->>'origen')::modulo5.enum_historial_suministros_activos_origen;
    END IF;

    -- 3. Validar rango de fechas si ambas están presentes
    IF v_fecha_inicio IS NOT NULL AND v_fecha_fin IS NOT NULL THEN
        IF v_fecha_inicio > v_fecha_fin THEN
            RAISE EXCEPTION
                'RANGO_FECHAS_INVALIDO: La fecha de inicio [%] no puede ser '
                'posterior a la fecha de fin [%]. (RF-81)',
                v_fecha_inicio, v_fecha_fin
            USING ERRCODE = 'P0001';
        END IF;
    END IF;

    -- 4. Calcular monto_total_filtrado sobre TODO el conjunto (no solo la página)
    SELECT COALESCE(SUM(h.costo_total_suministros), 0)
    INTO v_monto_total
    FROM modulo5.historial_suministros_activos h
    WHERE h.id_activo_biologico = p_activo_id
      AND (v_fecha_inicio IS NULL OR h.fecha_inicio >= v_fecha_inicio)
      AND (v_fecha_fin    IS NULL OR h.fecha_fin    <= v_fecha_fin)
      AND (v_origen       IS NULL OR h.origen        = v_origen);

    -- 5. Timestamp de última actualización del conjunto filtrado
    SELECT MAX(h.fecha_consulta)
    INTO v_actualizado_hasta
    FROM modulo5.historial_suministros_activos h
    WHERE h.id_activo_biologico = p_activo_id
      AND (v_fecha_inicio IS NULL OR h.fecha_inicio >= v_fecha_inicio)
      AND (v_fecha_fin    IS NULL OR h.fecha_fin    <= v_fecha_fin)
      AND (v_origen       IS NULL OR h.origen        = v_origen);

    -- 6. Calcular offset
    v_offset := (p_pagina - 1) * p_limite;

    -- 7. Retornar página
    RETURN QUERY
    SELECT
        h.id_historial_suministro_activo,
        h.id_activo_biologico,
        h.origen,
        h.fecha_inicio,
        h.fecha_fin,
        h.costo_total_alimento,
        h.costo_total_medicamento,
        h.costo_total_suministros,
        h.num_registros_alimento,
        h.num_registros_medicamento,
        h.formato_exportacion,
        h.fecha_consulta,
        v_monto_total,
        v_actualizado_hasta
    FROM modulo5.historial_suministros_activos h
    WHERE h.id_activo_biologico = p_activo_id
      AND (v_fecha_inicio IS NULL OR h.fecha_inicio >= v_fecha_inicio)
      AND (v_fecha_fin    IS NULL OR h.fecha_fin    <= v_fecha_fin)
      AND (v_origen       IS NULL OR h.origen        = v_origen)
    ORDER BY h.fecha_consulta DESC
    LIMIT  p_limite
    OFFSET v_offset;
END;
$$;


ALTER FUNCTION modulo5.fn_consultar_historial_suministros(p_activo_id integer, p_filtro jsonb, p_pagina integer, p_limite integer) OWNER TO postgres;

--
-- Name: fn_trg_auditoria_consumo_alimento(); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.fn_trg_auditoria_consumo_alimento() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tipo_op modulo5.enum_auditoria_suministro_tipo_operacion;
    v_datos_ant json := NULL;
    v_datos_nue json := NULL;
BEGIN
    IF TG_OP = 'INSERT' THEN
        v_tipo_op   := 'INSERT';
        v_datos_nue := row_to_json(NEW);
    ELSIF TG_OP = 'UPDATE' THEN
        v_tipo_op   := 'UPDATE';
        v_datos_ant := row_to_json(OLD);
        v_datos_nue := row_to_json(NEW);
    END IF;

    INSERT INTO modulo5.auditorias_suministros (
        entidad_afectada,
        tipo_operacion,
        datos_anteriores,
        datos_nuevos,
        id_usuario,
        ip_origen,
        fecha_evento,
        resultado
    ) VALUES (
        'registros_consumo_alimentos',
        v_tipo_op,
        v_datos_ant,
        v_datos_nue,
        COALESCE(NEW.id_usuario, OLD.id_usuario),
        NULL,   -- IP gestionada por sesión de backend
        NOW(),
        'EXITOSO'
    );

    RETURN NULL;
END;
$$;


ALTER FUNCTION modulo5.fn_trg_auditoria_consumo_alimento() OWNER TO postgres;

