--
-- Name: fn_trg_calcular_costo_total_consumo(); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.fn_trg_calcular_costo_total_consumo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_costo_unitario modulo5.tipos_alimentos.costo_unitario%TYPE;
BEGIN
    -- Validar cantidad positiva como refuerzo de integridad en BD
    IF NEW.cantidad_suministrada <= 0 THEN
        RAISE EXCEPTION
            'CANTIDAD_INVALIDA: La cantidad suministrada debe ser mayor a cero. '
            'Valor recibido: [%]. (RF-75 Restricción 1)',
            NEW.cantidad_suministrada
        USING ERRCODE = 'P0001';
    END IF;

    -- Obtener costo_unitario desde el catálogo como fuente de verdad
    SELECT costo_unitario
    INTO v_costo_unitario
    FROM modulo5.tipos_alimentos
    WHERE id_tipo_elemento = NEW.id_tipo_alimento
      AND estado = 'ACTIVO';

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'TIPO_ALIMENTO_INVALIDO: No se encontró el tipo de alimento con id [%] '
            'en estado ACTIVO. Verifique el catálogo antes de registrar el consumo. '
            '(RF-75 Proceso paso 2)',
            NEW.id_tipo_alimento
        USING ERRCODE = 'P0001';
    END IF;

    -- Calcular y asignar costo_total como fuente de verdad en BD
    NEW.costo_total := NEW.cantidad_suministrada * v_costo_unitario;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo5.fn_trg_calcular_costo_total_consumo() OWNER TO postgres;

--
-- Name: fn_trg_calcular_costo_total_medicamento(); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.fn_trg_calcular_costo_total_medicamento() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Validar cantidad (dosis) positiva
    IF NEW.cantidad <= 0 THEN
        RAISE EXCEPTION
            'CANTIDAD_INVALIDA: La dosis aplicada debe ser mayor a cero. '
            'Valor recibido: [%]. (RF-76 Flujo alterno E4)',
            NEW.cantidad
        USING ERRCODE = 'P0001';
    END IF;

    -- Validar costo unitario positivo
    IF NEW.costo_unitario_medicamento <= 0 THEN
        RAISE EXCEPTION
            'COSTO_INVALIDO: El costo unitario del medicamento debe ser mayor a cero. '
            'Valor recibido: [%]. (RF-76 Entradas — costo_unitario)',
            NEW.costo_unitario_medicamento
        USING ERRCODE = 'P0001';
    END IF;

    -- Calcular y asignar costo_total_medicamento como fuente de verdad en BD
    NEW.costo_total_medicamento := NEW.cantidad * NEW.costo_unitario_medicamento;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo5.fn_trg_calcular_costo_total_medicamento() OWNER TO postgres;

--
-- Name: fn_trg_consumo_alimento_fecha_no_futura(); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.fn_trg_consumo_alimento_fecha_no_futura() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.fecha_inicio_periodo IS NOT NULL AND NEW.fecha_inicio_periodo > NOW() THEN
        RAISE EXCEPTION
            'FECHA_FUTURA_NO_PERMITIDA: La fecha de consumo [%] es posterior a la '
            'fecha actual del sistema [%]. No se permiten registros de consumo con '
            'fechas futuras. (RF-75 Restricción 2)',
            NEW.fecha_inicio_periodo,
            NOW()
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo5.fn_trg_consumo_alimento_fecha_no_futura() OWNER TO postgres;

--
-- Name: fn_trg_consumo_alimento_inmutable_validado(); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.fn_trg_consumo_alimento_inmutable_validado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.estado_registro = 'VALIDADO' AND NEW.estado_registro = 'VALIDADO' THEN
        RAISE EXCEPTION
            'INMUTABILIDAD_VIOLADA: El registro de consumo con id [%] está en estado '
            'VALIDADO y no puede ser modificado. Solo se permite la transición a ANULADO. '
            '(RF-75 Restricción 5)',
            OLD.id_consumo_alimeto
        USING ERRCODE = 'P0001';
    END IF;

    IF OLD.estado_registro = 'VALIDADO' AND NEW.estado_registro = 'ANULADO' THEN
        IF NEW.id_activo_biologico   IS DISTINCT FROM OLD.id_activo_biologico   OR
           NEW.id_tipo_alimento      IS DISTINCT FROM OLD.id_tipo_alimento      OR
           NEW.tipo_alimento         IS DISTINCT FROM OLD.tipo_alimento         OR
           NEW.cantidad_suministrada IS DISTINCT FROM OLD.cantidad_suministrada OR
           NEW.costo_total           IS DISTINCT FROM OLD.costo_total           OR
           NEW.fecha_inicio_periodo  IS DISTINCT FROM OLD.fecha_inicio_periodo  OR
           NEW.fecha_fin_periodo     IS DISTINCT FROM OLD.fecha_fin_periodo
        THEN
            RAISE EXCEPTION
                'INMUTABILIDAD_VIOLADA: Durante la anulación del registro de consumo [%] '
                'no se pueden modificar campos de negocio. Solo se permite cambiar '
                'el estado y los campos propios de la anulación. (RF-75 Restricción 5)',
                OLD.id_consumo_alimeto
            USING ERRCODE = 'P0001';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo5.fn_trg_consumo_alimento_inmutable_validado() OWNER TO postgres;

--
-- Name: fn_trg_consumo_alimento_no_delete(); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.fn_trg_consumo_alimento_no_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION
        'OPERACION_NO_PERMITIDA: Los registros de consumo de alimentos son append-only '
        'y no pueden eliminarse físicamente. El registro con id [%] debe conservarse '
        'en el historial. Para invalidar un registro utilice la operación de anulación. '
        '(RF-75 Restricción 6 / RF-78 Restricción 6)',
        OLD.id_consumo_alimeto
    USING ERRCODE = 'P0001';
END;
$$;


ALTER FUNCTION modulo5.fn_trg_consumo_alimento_no_delete() OWNER TO postgres;

--
-- Name: fn_trg_costos_productivos_no_delete(); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.fn_trg_costos_productivos_no_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION
        'OPERACION_NO_PERMITIDA: Los registros de costos productivos son append-only '
        'bajo política NIC 41 y no pueden eliminarse. El registro con id [%] debe '
        'conservarse como evidencia de inversión del ciclo productivo. Las correcciones '
        'deben realizarse mediante nuevos registros con tipo_operacion = CORRECCION. '
        '(RF-78 Restricción 6)',
        OLD.id_costo_productivo
    USING ERRCODE = 'P0001';
END;
$$;


ALTER FUNCTION modulo5.fn_trg_costos_productivos_no_delete() OWNER TO postgres;

--
-- Name: fn_trg_costos_productivos_no_update(); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.fn_trg_costos_productivos_no_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION
        'OPERACION_NO_PERMITIDA: Los registros de costos productivos son inmutables '
        '(append-only, NIC 41). No se permite modificar el registro con id [%]. '
        'Para realizar una corrección inserte un nuevo registro con '
        'tipo_operacion = CORRECCION referenciando el id del registro original. '
        '(RF-78 Restricción 6)',
        OLD.id_costo_productivo
    USING ERRCODE = 'P0001';
END;
$$;


ALTER FUNCTION modulo5.fn_trg_costos_productivos_no_update() OWNER TO postgres;

--
-- Name: fn_trg_disparar_recalculo_ica_post_consumo(); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.fn_trg_disparar_recalculo_ica_post_consumo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Solo notifica si el registro está VALIDADO
    IF NEW.estado_registro = 'VALIDADO' THEN
        PERFORM pg_notify(
            'ica_recalculo',
            json_build_object(
                'id_activo_biologico', NEW.id_activo_biologico,
                'fecha_evento',        NOW()
            )::TEXT
        );
    END IF;

    RETURN NULL;
END;
$$;


ALTER FUNCTION modulo5.fn_trg_disparar_recalculo_ica_post_consumo() OWNER TO postgres;

--
-- Name: fn_trg_medicamento_fecha_no_futura(); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.fn_trg_medicamento_fecha_no_futura() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.fecha_aplicacion > CURRENT_DATE THEN
        RAISE EXCEPTION
            'FECHA_FUTURA_NO_PERMITIDA: La fecha de aplicación del medicamento [%] '
            'es posterior a la fecha actual del sistema [%]. No se permiten registros '
            'de medicamentos con fechas futuras. (RF-76 Flujo alterno E2)',
            NEW.fecha_aplicacion,
            CURRENT_DATE
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo5.fn_trg_medicamento_fecha_no_futura() OWNER TO postgres;

--
-- Name: fn_trg_medicamento_inmutable_validado(); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.fn_trg_medicamento_inmutable_validado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Bloquear cualquier UPDATE sobre un registro ya ANULADO
    IF OLD.estado_registro = 'ANULADO' THEN
        RAISE EXCEPTION
            'RE_ANULACION_INVALIDA: El registro de medicamento con id [%] ya se '
            'encuentra en estado ANULADO. No es posible anular un registro que ya '
            'fue anulado previamente. (RF-76 Flujo alterno E8)',
            OLD.id_registro_medicamento
        USING ERRCODE = 'P0001';
    END IF;

    -- Si el registro estaba VALIDADO y sigue VALIDADO, bloquear edición
    IF OLD.estado_registro = 'VALIDADO' AND NEW.estado_registro = 'VALIDADO' THEN
        RAISE EXCEPTION
            'INMUTABILIDAD_VIOLADA: El registro de medicamento con id [%] está en '
            'estado VALIDADO y no puede ser modificado. Solo se permite la transición '
            'a ANULADO. (RF-76 Restricción 5)',
            OLD.id_registro_medicamento
        USING ERRCODE = 'P0001';
    END IF;

    -- Durante la transición VALIDADO → ANULADO, proteger campos de negocio
    IF OLD.estado_registro = 'VALIDADO' AND NEW.estado_registro = 'ANULADO' THEN
        IF NEW.id_activo_biologico        IS DISTINCT FROM OLD.id_activo_biologico        OR
           NEW.nombre_medicamento         IS DISTINCT FROM OLD.nombre_medicamento         OR
           NEW.cantidad                   IS DISTINCT FROM OLD.cantidad                   OR
           NEW.fecha_aplicacion           IS DISTINCT FROM OLD.fecha_aplicacion           OR
           NEW.costo_unitario_medicamento IS DISTINCT FROM OLD.costo_unitario_medicamento OR
           NEW.costo_total_medicamento    IS DISTINCT FROM OLD.costo_total_medicamento
        THEN
            RAISE EXCEPTION
                'INMUTABILIDAD_VIOLADA: Durante la anulación del registro de medicamento [%] '
                'no se pueden modificar campos de negocio. Solo se permite cambiar '
                'el estado y los campos propios de la anulación. (RF-76 Restricción 5)',
                OLD.id_registro_medicamento
            USING ERRCODE = 'P0001';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo5.fn_trg_medicamento_inmutable_validado() OWNER TO postgres;

--
-- Name: fn_trg_medicamento_no_delete(); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.fn_trg_medicamento_no_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
