--
-- Name: fn_trg_poblar_registro_suministro_alimento(); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.fn_trg_poblar_registro_suministro_alimento() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_id_ciclo integer; v_id_gestion_fases integer;
BEGIN
  IF NEW.estado_registro <> 'VALIDADO' THEN RETURN NEW; END IF;
  SELECT id_gestion_fases, id_ciclo_productiva INTO v_id_gestion_fases, v_id_ciclo
   FROM modulo2.gestiones_fases
   WHERE id_activo_biologico = NEW.id_activo_biologico
   ORDER BY es_activa DESC, fecha_inicio DESC LIMIT 1;
  IF v_id_ciclo IS NULL THEN
    RAISE WARNING 'registro_suministro: activo % sin ciclo productivo; se omite ledger para consumo %',
      NEW.id_activo_biologico, NEW.id_consumo_alimeto;
    RETURN NEW;
  END IF;
  INSERT INTO modulo5.registro_suministro
    (id_activo_biologico, id_ciclo_productivo, id_gestion_fases, tipo_suministro, cantidad, unidad_medida,
     precio_unitario_resuelto, costo_registro, origen_precio, fecha_aplicacion, observacion, tipo_operacion,
     id_registro_rf75, naturaleza_costo)
  VALUES
    (NEW.id_activo_biologico, v_id_ciclo, v_id_gestion_fases, 'ALIMENTO', NEW.cantidad_suministrada, NEW.tipo_unidad,
     COALESCE(NEW.costo_unitario, 0), COALESCE(NEW.costo_total, 0), 'MANUAL',
     COALESCE(NEW.fecha_consumo, NEW.fecha_registro::date), NEW.observacion, 'REGISTRO',
     NEW.id_registro_rf75, 'MANTENIMIENTO');
  RETURN NEW;
END; $$;


ALTER FUNCTION modulo5.fn_trg_poblar_registro_suministro_alimento() OWNER TO postgres;

