  SELECT id_gestion_fases, id_ciclo_productiva INTO v_id_gestion_fases, v_id_ciclo
   FROM modulo2.gestiones_fases
   WHERE id_activo_biologico = NEW.id_activo_biologico
   ORDER BY es_activa DESC, fecha_inicio DESC LIMIT 1;
  IF v_id_ciclo IS NULL THEN
    RAISE WARNING 'registro_suministro: activo % sin ciclo productivo; se omite ledger para medicamento %',
      NEW.id_activo_biologico, NEW.id_registro_medicamento;
    RETURN NEW;
  END IF;
  INSERT INTO modulo5.registro_suministro
    (id_activo_biologico, id_ciclo_productivo, id_gestion_fases, tipo_suministro, cantidad, unidad_medida,
     precio_unitario_resuelto, costo_registro, origen_precio, fecha_aplicacion, observacion, tipo_operacion,
