--
-- Name: fn_trg_tipo_alimento_debe_estar_activo(); Type: FUNCTION; Schema: modulo5; Owner: postgres
--

CREATE FUNCTION modulo5.fn_trg_tipo_alimento_debe_estar_activo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado modulo5.enum_tipo_alimento_estado;
BEGIN
    SELECT estado
    INTO v_estado
    FROM modulo5.tipos_alimentos
    WHERE id_tipo_elemento = NEW.id_tipo_alimento;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'TIPO_ALIMENTO_NO_ENCONTRADO: El tipo de alimento con id [%] no existe '
            'en el catálogo. Verifique el identificador antes de registrar el consumo. '
            '(RF-75 Proceso paso 2)',
            NEW.id_tipo_alimento
        USING ERRCODE = 'P0001';
    END IF;

    IF v_estado != 'ACTIVO' THEN
        RAISE EXCEPTION
            'TIPO_ALIMENTO_INACTIVO: El tipo de alimento con id [%] se encuentra en '
            'estado [%] y no puede usarse para nuevos registros de consumo. Solo los '
            'tipos de alimento en estado ACTIVO son válidos para nuevos registros. '
            '(RF-75 Proceso paso 2)',
            NEW.id_tipo_alimento,
            v_estado
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo5.fn_trg_tipo_alimento_debe_estar_activo() OWNER TO postgres;

--
-- Name: sp_calcular_ica(integer, integer, integer, numeric, modulo5.enum_medicion_incremental_esquema); Type: PROCEDURE; Schema: modulo5; Owner: postgres
--

CREATE PROCEDURE modulo5.sp_calcular_ica(IN p_id_usuario integer, IN p_id_activo integer, IN p_id_ciclo integer, IN p_peso_actual numeric, IN p_esquema modulo5.enum_medicion_incremental_esquema)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_peso_inicial          NUMERIC;
    v_ganancia_peso         NUMERIC;
    v_consumo_acumulado     NUMERIC;
    v_ica                   NUMERIC;
    v_costo_alimento_acum   NUMERIC;
    v_costo_inversion       NUMERIC;
BEGIN
    -- 1. Obtener peso_inicial_ciclo del primer registro de este activo en este ciclo
    --    Si no hay registros previos, el peso inicial es el peso actual (primera medición)
    SELECT peso_inicial_ciclo
    INTO v_peso_inicial
    FROM modulo5.mediciones_incrementales
    WHERE id_activo_biologico = p_id_activo
      AND id_ciclo_productivo = p_id_ciclo
    ORDER BY fecha_creacion ASC
    LIMIT 1;

    IF NOT FOUND THEN
        v_peso_inicial := p_peso_actual;
    END IF;

    -- 2. Calcular ganancia de peso
    v_ganancia_peso := p_peso_actual - v_peso_inicial;

    -- 3. Consumo acumulado de alimento filtrado por ciclo
    SELECT
        COALESCE(SUM(cantidad_suministrada), 0),
        COALESCE(SUM(costo_total), 0)
    INTO v_consumo_acumulado, v_costo_alimento_acum
    FROM modulo5.registros_consumo_alimentos
    WHERE id_activo_biologico = p_id_activo
      AND estado_registro     = 'VALIDADO';

    -- 4. Calcular ICA — evitar división por cero
    IF v_ganancia_peso > 0 THEN
        v_ica := v_consumo_acumulado / v_ganancia_peso;
    ELSE
        v_ica := 0;
    END IF;

    -- 5. Costo de inversión — medicamentos del activo
    SELECT COALESCE(SUM(costo_total_medicamento), 0)
    INTO v_costo_inversion
    FROM modulo5.registros_medicamentos
    WHERE id_activo_biologico = p_id_activo
      AND estado_registro     = 'VALIDADO';

    -- 6. Insertar medición incremental
    INSERT INTO modulo5.mediciones_incrementales (
        id_activo_biologico,
        id_ciclo_productivo,
        fecha_medicion,
        peso_actual,
        peso_inicial_ciclo,
        ganancia_peso,
        consumo_alimento_acumulado,
        conversion_alimenticia,
        costo_acumalado,
        costo_acumulado_inversion,
        esquema_proceso,
        id_usuario,
        fecha_creacion
    ) VALUES (
        p_id_activo,
        p_id_ciclo,
        CURRENT_DATE,
        p_peso_actual,
        v_peso_inicial,
        v_ganancia_peso,
        v_consumo_acumulado,
        v_ica,
        v_costo_alimento_acum,
        v_costo_inversion,
        p_esquema,
        p_id_usuario,
        CURRENT_TIMESTAMP
    );

    CALL modulo1.sp_registrar_auditoria(
        p_id_usuario,
        NULL,
        3,
        'Modulo 5',
        'ANALITICA',
        'Cálculo de ICA para activo ID: ' || p_id_activo,
        'exitoso',
        'COMPLETADO',
        jsonb_build_object(
            'ica_resultado',   v_ica,
            'ganancia_peso',   v_ganancia_peso,
            'consumo_total',   v_consumo_acumulado
        )
    );
END;
$$;


ALTER PROCEDURE modulo5.sp_calcular_ica(IN p_id_usuario integer, IN p_id_activo integer, IN p_id_ciclo integer, IN p_peso_actual numeric, IN p_esquema modulo5.enum_medicion_incremental_esquema) OWNER TO postgres;

--
-- Name: sp_ejecutar_batch_ica_automatizado(); Type: PROCEDURE; Schema: modulo5; Owner: postgres
--

CREATE PROCEDURE modulo5.sp_ejecutar_batch_ica_automatizado()
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Cursor sobre activos con consumos VALIDADO
    v_activo            RECORD;
    -- Resultados ICA por período
    v_resultado         RECORD;
    -- Control de ventana de 4 horas
    v_inicio_batch      TIMESTAMPTZ := NOW();
    v_limite_ventana    TIMESTAMPTZ := NOW() + INTERVAL '4 hours';
    -- Contadores para log
    v_total_procesados  INT := 0;
    v_total_errores     INT := 0;
    -- Fechas por esquema
    v_inicio_semanal    DATE := CURRENT_DATE - 7;
    v_inicio_mensual    DATE := CURRENT_DATE - 30;
    v_inicio_ciclo      DATE := CURRENT_DATE - 365;
BEGIN
    -- Iterar activos que tienen consumos VALIDADO
    FOR v_activo IN
        SELECT DISTINCT
            rca.id_activo_biologico,
            -- Ciclo más reciente del activo (para POR_CICLO)
            MAX(mi.id_ciclo_productivo) AS id_ciclo
        FROM modulo5.registros_consumo_alimentos rca
        LEFT JOIN modulo5.mediciones_incrementales mi
               ON mi.id_activo_biologico = rca.id_activo_biologico
        WHERE rca.estado_registro = 'VALIDADO'
        GROUP BY rca.id_activo_biologico
    LOOP
        -- Control de ventana — si se supera las 4h se interrumpe
        IF NOW() > v_limite_ventana THEN
            RAISE NOTICE
                'BATCH_INTERRUMPIDO: Se superó la ventana de 4 horas. '
                'Procesados: %, Errores: %. Reactivación manual requerida.',
                v_total_procesados, v_total_errores;
            EXIT;
        END IF;

        -- Calcular ICA SEMANAL
        BEGIN
            SELECT * INTO v_resultado
            FROM modulo5.fn_calcular_ica_periodo(
                v_activo.id_activo_biologico,
                'SEMANAL',
                v_inicio_semanal,
                CURRENT_DATE
            );

            v_total_procesados := v_total_procesados + 1;

        EXCEPTION WHEN OTHERS THEN
            v_total_errores := v_total_errores + 1;
            RAISE NOTICE
                'ERROR_SEMANAL: Activo [%] — %',
                v_activo.id_activo_biologico,
                SQLERRM;
        END;

        -- Calcular ICA MENSUAL
        BEGIN
            SELECT * INTO v_resultado
            FROM modulo5.fn_calcular_ica_periodo(
                v_activo.id_activo_biologico,
                'MENSUAL',
                v_inicio_mensual,
                CURRENT_DATE
            );

            v_total_procesados := v_total_procesados + 1;

        EXCEPTION WHEN OTHERS THEN
            v_total_errores := v_total_errores + 1;
            RAISE NOTICE
                'ERROR_MENSUAL: Activo [%] — %',
                v_activo.id_activo_biologico,
                SQLERRM;
        END;

        -- Calcular ICA POR_CICLO solo si tiene ciclo asociado
        IF v_activo.id_ciclo IS NOT NULL THEN
            BEGIN
                SELECT * INTO v_resultado
                FROM modulo5.fn_calcular_ica_periodo(
                    v_activo.id_activo_biologico,
                    'POR_CICLO',
                    v_inicio_ciclo,
                    CURRENT_DATE
                );

                v_total_procesados := v_total_procesados + 1;

            EXCEPTION WHEN OTHERS THEN
                v_total_errores := v_total_errores + 1;
                RAISE NOTICE
                    'ERROR_POR_CICLO: Activo [%] — %',
                    v_activo.id_activo_biologico,
                    SQLERRM;
            END;
        END IF;

    END LOOP;

    RAISE NOTICE
        'BATCH_COMPLETADO: Inicio [%] — Fin [%] — Procesados: % — Errores: %',
        v_inicio_batch,
        NOW(),
        v_total_procesados,
        v_total_errores;
END;
$$;


ALTER PROCEDURE modulo5.sp_ejecutar_batch_ica_automatizado() OWNER TO postgres;

--
-- Name: sp_registrar_aplicacion_medicamento(integer, integer, integer, character varying, text, character varying, numeric, modulo5.enum_registro_medicamenti_via_aplicacion, numeric, date, character varying, date); Type: PROCEDURE; Schema: modulo5; Owner: postgres
--

CREATE PROCEDURE modulo5.sp_registrar_aplicacion_medicamento(IN p_id_usuario integer, IN p_id_activo integer, IN p_id_veterinario integer, IN p_nombre_medicamento character varying, IN p_descripcion text, IN p_unidad_dosis character varying, IN p_cantidad numeric, IN p_via_aplicacion modulo5.enum_registro_medicamenti_via_aplicacion, IN p_costo_unitario numeric, IN p_fecha_aplicacion date, IN p_lote character varying, IN p_vencimiento_lote date)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Insertar — costo_total_medicamento lo calcula fn_trg_calcular_costo_total_medicamento
    INSERT INTO modulo5.registros_medicamentos (
        id_activo_biologico,
        nombre_medicamento,
        descripcion_clinica,
        unidad_dosis,
        cantidad,
        via_aplicacion,
        costo_unitario_medicamento,
        fecha_aplicacion,
        lote_medicameto,
        fehca_vencimietno_lote,
        id_usuario,
        id_usuario_veterinario
    ) VALUES (
        p_id_activo,
        p_nombre_medicamento,
        p_descripcion,
        p_unidad_dosis,
        p_cantidad,
        p_via_aplicacion,
        p_costo_unitario,
        p_fecha_aplicacion,
        p_lote,
        p_vencimiento_lote,
        p_id_usuario,
        p_id_veterinario
    );

    CALL modulo1.sp_registrar_auditoria(
        p_id_usuario,
        NULL,
        1,
        'Modulo 5',
        'SUMINISTROS',
        'Registro de aplicación de medicamento: ' || p_nombre_medicamento,
        'exitoso',
        'VALIDADO',
        jsonb_build_object(
            'id_activo',     p_id_activo,
            'medicamento',   p_nombre_medicamento,
            'costo_unitario', p_costo_unitario
        )
    );
END;
$$;


ALTER PROCEDURE modulo5.sp_registrar_aplicacion_medicamento(IN p_id_usuario integer, IN p_id_activo integer, IN p_id_veterinario integer, IN p_nombre_medicamento character varying, IN p_descripcion text, IN p_unidad_dosis character varying, IN p_cantidad numeric, IN p_via_aplicacion modulo5.enum_registro_medicamenti_via_aplicacion, IN p_costo_unitario numeric, IN p_fecha_aplicacion date, IN p_lote character varying, IN p_vencimiento_lote date) OWNER TO postgres;

--
-- Name: sp_registrar_consumo_alimento(integer, integer, integer, numeric, timestamp without time zone, timestamp without time zone, character varying); Type: PROCEDURE; Schema: modulo5; Owner: postgres
--

CREATE PROCEDURE modulo5.sp_registrar_consumo_alimento(IN p_id_usuario integer, IN p_id_activo integer, IN p_id_tipo_alimento integer, IN p_cantidad_suministrada numeric, IN p_fecha_inicio timestamp without time zone, IN p_fecha_fin timestamp without time zone, IN p_observacion character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tipo_alimento VARCHAR;
    v_unidad        VARCHAR;
BEGIN
    -- 1. Validar existencia y estado ACTIVO del tipo de alimento
    SELECT nombre, unidad_medida
    INTO v_tipo_alimento, v_unidad
    FROM modulo5.tipos_alimentos
    WHERE id_tipo_elemento = p_id_tipo_alimento
      AND estado = 'ACTIVO';

    IF NOT FOUND THEN
        RAISE EXCEPTION
            'TIPO_ALIMENTO_INVALIDO: El tipo de alimento con id [%] no existe '
            'o no está en estado ACTIVO. (RF-75 Proceso paso 2)',
            p_id_tipo_alimento
        USING ERRCODE = 'P0001';
    END IF;

    -- 2. Insertar — costo_total lo calcula fn_trg_calcular_costo_total_consumo
    INSERT INTO modulo5.registros_consumo_alimentos (
        id_activo_biologico,
        id_tipo_alimento,
        tipo_alimento,
        tipo_unidad,
        cantidad_suministrada,
        observacion,
        fecha_inicio_periodo,
        fecha_fin_periodo,
        id_usuario,
        fecha_registro
    ) VALUES (
        p_id_activo,
        p_id_tipo_alimento,
        v_tipo_alimento,
        v_unidad,
        p_cantidad_suministrada,
        p_observacion,
        p_fecha_inicio,
        p_fecha_fin,
        p_id_usuario,
        CURRENT_TIMESTAMP
    );

    CALL modulo1.sp_registrar_auditoria(
        p_id_usuario,
        NULL,
        1,
        'Modulo 5',
        'SUMINISTROS',
        'Registro de consumo de alimento para activo ID: ' || p_id_activo,
        'exitoso',
        'VALIDADO',
        jsonb_build_object(
            'id_activo',        p_id_activo,
            'id_tipo_alimento', p_id_tipo_alimento,
            'cantidad',         p_cantidad_suministrada
        )
    );
END;
$$;


ALTER PROCEDURE modulo5.sp_registrar_consumo_alimento(IN p_id_usuario integer, IN p_id_activo integer, IN p_id_tipo_alimento integer, IN p_cantidad_suministrada numeric, IN p_fecha_inicio timestamp without time zone, IN p_fecha_fin timestamp without time zone, IN p_observacion character varying) OWNER TO postgres;

--
-- Name: calcular_hash_auditoria(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.calcular_hash_auditoria() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.hash_integridad := encode(digest(
    (SELECT string_agg(key || '=' || value, '&' ORDER BY key) 
     FROM jsonb_each_text(to_jsonb(NEW) - 'hash_integridad')), 
    'sha256'), 'hex');
  RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.calcular_hash_auditoria() OWNER TO postgres;

--
-- Name: fn_normalizar_politica_mantenimiento(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_normalizar_politica_mantenimiento() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Si la naturaleza es MANTENIMIENTO, la política SIEMPRE es GASTO.
    -- Se asigna automáticamente sin requerir que el actor lo informe.
    IF NEW.naturaleza_costo = 'MANTENIMIENTO' THEN
        NEW.politica_capitalizacion := 'GASTO';
    END IF;

    -- Si la naturaleza es VENTA, la política no aplica (debe ser NULL).
    IF NEW.naturaleza_costo = 'VENTA' THEN
        NEW.politica_capitalizacion := NULL;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_normalizar_politica_mantenimiento() OWNER TO postgres;

--
-- Name: FUNCTION fn_normalizar_politica_mantenimiento(); Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON FUNCTION modulo6.fn_normalizar_politica_mantenimiento() IS 'Normaliza politica_capitalizacion antes de INSERT/UPDATE en registros_costos: fuerza GASTO cuando naturaleza_costo = MANTENIMIENTO y NULL cuando es VENTA. Garantiza coherencia con NIC 41 (los costos de mantenimiento son siempre gasto del período; nunca capitalizables). Referencia: RF-90, RF-93.';


--
-- Name: fn_tgr_m06_01_inmutabilidad_reconocimiento(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_01_inmutabilidad_reconocimiento() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION
            '[TGR-M06-01] El reconocimiento inicial id=% no puede eliminarse. '
            'Los reconocimientos son registros permanentes del libro mayor. '
            'Estado actual: %. Requerimiento RF-82, Restricción 2 y RNF-82-03.',
            OLD.id_reconocimiento_inicial, OLD.estado
        USING ERRCODE = 'P0001';
    END IF;

    IF TG_OP = 'UPDATE' AND OLD.estado IN ('CONFIRMADO', 'REVERTIDO') THEN
        RAISE EXCEPTION
            '[TGR-M06-01] El reconocimiento inicial id=% tiene estado % y es inmutable. '
            'No se permiten modificaciones directas sobre reconocimientos confirmados. '
            'Para anular un reconocimiento CONFIRMADO utilice el mecanismo de reversión '
            'auditada (revisiones_reconocimiento). Requerimiento RF-82, Restricción 2.',
            OLD.id_reconocimiento_inicial, OLD.estado
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_01_inmutabilidad_reconocimiento() OWNER TO postgres;

--
-- Name: fn_tgr_m06_02_unicidad_reconocimiento_confirmado(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_02_unicidad_reconocimiento_confirmado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_reconocimiento_existente INTEGER;
BEGIN
    IF TG_OP = 'INSERT'
       OR (TG_OP = 'UPDATE' AND NEW.estado = 'CONFIRMADO' AND OLD.estado != 'CONFIRMADO') THEN

        SELECT id_reconocimiento_inicial
        INTO v_reconocimiento_existente
        FROM modulo6.reconocimientos_iniciales
        WHERE id_activo_biologico = NEW.id_activo_biologico
          AND estado = 'CONFIRMADO'
          AND id_reconocimiento_inicial != COALESCE(NEW.id_reconocimiento_inicial, -1)
        LIMIT 1;

        IF FOUND THEN
            RAISE EXCEPTION
                '[TGR-M06-02] El activo biológico id=% ya posee un reconocimiento inicial '
                'CONFIRMADO (id_reconocimiento=%). No se puede registrar un segundo '
                'reconocimiento vigente. Requerimiento RF-82, Restricción 3 y FA-1.',
                NEW.id_activo_biologico, v_reconocimiento_existente
            USING ERRCODE = 'P0001';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_02_unicidad_reconocimiento_confirmado() OWNER TO postgres;

--
-- Name: fn_tgr_m06_03_inmutabilidad_revisiones(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_03_inmutabilidad_revisiones() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION
            '[TGR-M06-03] La reversión id=% es un registro de auditoría inmutable y no '
            'puede modificarse. Los asientos de reversión coexisten permanentemente con '
            'el reconocimiento original para garantizar trazabilidad NIC 41. '
            'Requerimiento RF-82, Restricciones 2f y 2g.',
            OLD.id_revision_reconocimiento
        USING ERRCODE = 'P0001';
    END IF;

    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION
            '[TGR-M06-03] La reversión id=% no puede eliminarse. Es evidencia contable '
            'auditada que debe coexistir con el reconocimiento original id=% en el historial. '
            'Requerimiento RF-82, Restricciones 2f y 2g.',
            OLD.id_revision_reconocimiento, OLD.id_reconocimiento_revertido
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_03_inmutabilidad_revisiones() OWNER TO postgres;

--
-- Name: fn_tgr_m06_04_consistencia_medicion(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_04_consistencia_medicion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_variacion_calculada NUMERIC(18,4);
    v_suma_componentes    NUMERIC(18,4);
    v_tolerancia          NUMERIC(18,4) := 0.01;
BEGIN
    -- Ecuación 1: variacion_total debe igualar la diferencia de valores razonables
    v_variacion_calculada := NEW.valor_razonable_actual - NEW.valor_razonable_anterior;

    IF ABS(NEW.variacion_total - v_variacion_calculada) > v_tolerancia THEN
        RAISE EXCEPTION
            '[TGR-M06-04] Inconsistencia en medición posterior: variacion_total=% '
            'no coincide con (valor_razonable_actual % - valor_razonable_anterior %) = %. '
            'Diferencia: %. Tolerancia máxima: %. Requerimiento RF-83, RNF-83-05.',
            NEW.variacion_total,
            NEW.valor_razonable_actual,
            NEW.valor_razonable_anterior,
            v_variacion_calculada,
            ABS(NEW.variacion_total - v_variacion_calculada),
            v_tolerancia
        USING ERRCODE = 'P0001';
    END IF;

    -- Ecuación 2: variacion_total debe igualar la suma de los dos componentes
    v_suma_componentes := NEW.ganancia_perdida_transformacion
                        + NEW.ganancia_perdida_precio_mercado;

    IF ABS(NEW.variacion_total - v_suma_componentes) > v_tolerancia THEN
        RAISE EXCEPTION
            '[TGR-M06-04] Inconsistencia en medición posterior: variacion_total=% '
            'no coincide con (ganancia_perdida_transformacion % + '
            'ganancia_perdida_precio_mercado %) = %. '
            'Diferencia: %. Tolerancia máxima: %. Requerimiento RF-83, RNF-83-05.',
            NEW.variacion_total,
            NEW.ganancia_perdida_transformacion,
            NEW.ganancia_perdida_precio_mercado,
            v_suma_componentes,
            ABS(NEW.variacion_total - v_suma_componentes),
            v_tolerancia
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_04_consistencia_medicion() OWNER TO postgres;

--
-- Name: fn_tgr_m06_05_inmutabilidad_medicion(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_05_inmutabilidad_medicion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION
            '[TGR-M06-05] La medición posterior id=% no puede eliminarse. '
            'Es un registro inmutable del libro mayor NIC 41. Estado: %. '
            'Requerimiento RF-83, RNF-83-04.',
            OLD."id_ medicion_posterior", OLD.estado
        USING ERRCODE = 'P0001';
    END IF;

    IF TG_OP = 'UPDATE' AND OLD.estado = 'COMPLETADO' THEN
        RAISE EXCEPTION
            '[TGR-M06-05] La medición posterior id=% tiene estado COMPLETADO y es inmutable. '
            'No se permiten modificaciones directas sobre mediciones confirmadas. '
            'Requerimiento RF-83, RNF-83-04.',
            OLD."id_ medicion_posterior"
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_05_inmutabilidad_medicion() OWNER TO postgres;

--
-- Name: fn_tgr_m06_06_consistencia_calculo_vr(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_06_consistencia_calculo_vr() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_suma_costos     NUMERIC(18,4);
    v_valor_neto_calc NUMERIC(18,4);
    v_tolerancia      NUMERIC(18,4) := 0.01;
BEGIN
    -- Validar que el valor razonable bruto sea positivo
    IF NEW.valor_razonable_bruto <= 0 THEN
        RAISE EXCEPTION
            '[TGR-M06-06] valor_razonable_bruto=% debe ser mayor a cero. '
            'El precio de mercado de referencia no puede ser cero ni negativo. '
            'Requerimiento RF-84, CA-1.',
            NEW.valor_razonable_bruto
        USING ERRCODE = 'P0001';
    END IF;

    -- Validar que ningún componente de costo sea negativo
    IF NEW.costo_transporte < 0 THEN
        RAISE EXCEPTION
            '[TGR-M06-06] costo_transporte=% no puede ser negativo. '
            'Los costos de venta son valores positivos o cero. Requerimiento RF-84.',
            NEW.costo_transporte
        USING ERRCODE = 'P0001';
    END IF;

    IF NEW.costo_comisiones < 0 THEN
        RAISE EXCEPTION
            '[TGR-M06-06] costo_comisiones=% no puede ser negativo. '
            'Requerimiento RF-84.',
            NEW.costo_comisiones
        USING ERRCODE = 'P0001';
    END IF;

    IF NEW.costo_impuestos_transaccion < 0 THEN
        RAISE EXCEPTION
            '[TGR-M06-06] costo_impuestos_transaccion=% no puede ser negativo. '
            'Requerimiento RF-84.',
            NEW.costo_impuestos_transaccion
        USING ERRCODE = 'P0001';
    END IF;

    IF NEW.otros_costos_disposicion < 0 THEN
        RAISE EXCEPTION
            '[TGR-M06-06] otros_costos_disposicion=% no puede ser negativo. '
            'Requerimiento RF-84.',
            NEW.otros_costos_disposicion
        USING ERRCODE = 'P0001';
    END IF;

    -- Validar consistencia aritmética: valor_neto = valor_bruto - suma_costos
    v_suma_costos := NEW.costo_transporte
                   + NEW.costo_comisiones
                   + NEW.costo_impuestos_transaccion
                   + NEW.otros_costos_disposicion;

    v_valor_neto_calc := NEW.valor_razonable_bruto - v_suma_costos;

    IF ABS(NEW.valor_neto - v_valor_neto_calc) > v_tolerancia THEN
        RAISE EXCEPTION
            '[TGR-M06-06] Inconsistencia aritmética: valor_neto=% no coincide con '
            '(valor_razonable_bruto % - suma_costos %) = %. '
            'Diferencia: %. Tolerancia: %. Requerimiento RF-84, CA-1.',
            NEW.valor_neto,
            NEW.valor_razonable_bruto,
            v_suma_costos,
            v_valor_neto_calc,
            ABS(NEW.valor_neto - v_valor_neto_calc),
            v_tolerancia
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_06_consistencia_calculo_vr() OWNER TO postgres;

--
-- Name: fn_tgr_m06_07_inmutabilidad_precios(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_07_inmutabilidad_precios() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION
            '[TGR-M06-07] El precio de mercado id=% no puede modificarse. '
            'El repositorio de precios es append-only e inmutable. '
            'Para corregir un precio erróneo, registre un nuevo precio con '
            'id_precio_coregido=% y la fecha_vigencia correspondiente. '
            'Requerimiento RF-89, Restricciones y FA-6.',
            OLD.id_precio_mercado, OLD.id_precio_mercado
        USING ERRCODE = 'P0001';
    END IF;

    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION
            '[TGR-M06-07] El precio de mercado id=% no puede eliminarse. '
            'El historial de precios es inmutable y permanente. '
            'Los registros históricos sustentan los cálculos de valor razonable auditados. '
            'Requerimiento RF-89, Restricciones y CA-6.',
            OLD.id_precio_mercado
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_07_inmutabilidad_precios() OWNER TO postgres;

--
-- Name: fn_tgr_m06_08_validacion_fechas_precio(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_08_validacion_fechas_precio() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Validar que fecha_vigencia no sea anterior en más de 365 días
    IF NEW.fecha_vigencia < (CURRENT_DATE - INTERVAL '365 days') THEN
        RAISE EXCEPTION
            '[TGR-M06-08] fecha_vigencia=% es anterior en más de 365 días a la fecha '
            'actual (%). No se admiten cargas históricas que podrían afectar cálculos '
            'retroactivos. Requerimiento RF-89, Restricciones.',
            NEW.fecha_vigencia, CURRENT_DATE
        USING ERRCODE = 'P0001';
    END IF;

    -- Validar que fecha_vencimiento sea posterior a fecha_vigencia (si se informa)
    IF NEW.fecha_vencimiento IS NOT NULL
       AND NEW.fecha_vencimiento <= NEW.fecha_vigencia THEN
        RAISE EXCEPTION
            '[TGR-M06-08] fecha_vencimiento=% debe ser posterior a fecha_vigencia=%. '
            'Un precio no puede vencer antes o en la misma fecha de su entrada en vigencia. '
            'Requerimiento RF-89, Restricciones.',
            NEW.fecha_vencimiento, NEW.fecha_vigencia
        USING ERRCODE = 'P0001';
    END IF;

    -- Validar que precio_unitario sea positivo
    IF NEW.precio_unitario <= 0 THEN
        RAISE EXCEPTION
            '[TGR-M06-08] precio_unitario=% debe ser mayor a cero. '
            'No se admiten precios cero ni negativos. Requerimiento RF-89, Restricciones y CA-3.',
            NEW.precio_unitario
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_08_validacion_fechas_precio() OWNER TO postgres;

--
-- Name: fn_tgr_m06_09_periodo_cerrado_bloqueo(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_09_periodo_cerrado_bloqueo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado_periodo modulo6.enum_periodo_contables_estado;
    v_id_periodo     INTEGER;
BEGIN
    IF TG_OP = 'DELETE' THEN
        v_id_periodo := OLD.id_periodo_contable;
    ELSE
        v_id_periodo := NEW.id_periodo_contable;
    END IF;

    SELECT estado
    INTO v_estado_periodo
    FROM modulo6.periodos_contables
    WHERE id_periodo_contable = v_id_periodo;

    IF NOT FOUND THEN
        RAISE EXCEPTION
            '[TGR-M06-09] El período contable id=% no existe. '
            'No se puede registrar información sin un período contable válido.',
            v_id_periodo
        USING ERRCODE = 'P0001';
    END IF;

    IF v_estado_periodo IN ('CERRADO', 'EN_CIERRE') THEN
        RAISE EXCEPTION
            '[TGR-M06-09] El período contable id=% tiene estado % y es inmutable. '
            'No se pueden registrar, modificar ni eliminar registros sobre períodos '
            'CERRADOS o EN_CIERRE. Las correcciones deben realizarse en el período '
            'siguiente con referencia explícita al registro que se corrige. '
            'Tabla afectada: %. Operación: %. Requerimiento RF-87.',
            v_id_periodo, v_estado_periodo, TG_TABLE_NAME, TG_OP
        USING ERRCODE = 'P0001';
    END IF;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_09_periodo_cerrado_bloqueo() OWNER TO postgres;

--
-- Name: fn_tgr_m06_10_inmutabilidad_variaciones(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_10_inmutabilidad_variaciones() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION
            '[TGR-M06-10] La variación de valor razonable id=% es inmutable (append-only). '
            'No se permiten modificaciones directas. Para corregir esta variación, registre '
            'un nuevo asiento correctivo con monto opuesto y id_variacion_corregida=%. '
            'Requiere aprobación del Contador. Requerimiento RF-86, Restricciones y CA-12.',
            OLD.id_variacion_valor_razonable, OLD.id_variacion_valor_razonable
        USING ERRCODE = 'P0001';
    END IF;

    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION
            '[TGR-M06-10] La variación de valor razonable id=% no puede eliminarse. '
            'El modelo append-only garantiza que tanto el registro original como el '
            'correctivo coexistan en el historial contable. '
            'Requerimiento RF-86, Restricciones y CA-12.',
            OLD.id_variacion_valor_razonable
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_10_inmutabilidad_variaciones() OWNER TO postgres;

--
-- Name: fn_tgr_m06_11_consistencia_variacion(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_11_consistencia_variacion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_suma_componentes NUMERIC(18,2);
    v_tolerancia       NUMERIC(18,2) := 0.01;
BEGIN
    -- Validar que monto_variacion no sea cero
    IF NEW.monto_variacion = 0 THEN
        RAISE EXCEPTION
            '[TGR-M06-11] monto_variacion=0 no es válido para un registro de variación. '
            'Si el valor razonable no cambió (variación real = 0), no debe generarse '
            'un registro de variación. Requerimiento RF-86, Restricciones.'
        USING ERRCODE = 'P0001';
    END IF;

    -- Validar que monto_variacion = suma de componentes
    v_suma_componentes := NEW.variacion_transformacion + NEW.variacion_precio_mercado;

    IF ABS(NEW.monto_variacion - v_suma_componentes) > v_tolerancia THEN
        RAISE EXCEPTION
            '[TGR-M06-11] monto_variacion=% no coincide con la suma de componentes: '
            'variacion_transformacion (%) + variacion_precio_mercado (%) = %. '
            'Diferencia: %. Tolerancia: %. Requerimiento RF-86, CA-8.',
            NEW.monto_variacion,
            NEW.variacion_transformacion,
            NEW.variacion_precio_mercado,
            v_suma_componentes,
            ABS(NEW.monto_variacion - v_suma_componentes),
            v_tolerancia
        USING ERRCODE = 'P0001';
    END IF;

    -- Validar que los valores de referencia sean positivos
    IF NEW.valor_razonable_anterior <= 0 THEN
        RAISE EXCEPTION
            '[TGR-M06-11] valor_razonable_anterior=% debe ser positivo. '
            'Requerimiento RF-86, CA-16.',
            NEW.valor_razonable_anterior
        USING ERRCODE = 'P0001';
    END IF;

    IF NEW.valor_razonable_nuevo <= 0 THEN
        RAISE EXCEPTION
            '[TGR-M06-11] valor_razonable_nuevo=% debe ser positivo. '
            'Requerimiento RF-86, CA-16.',
            NEW.valor_razonable_nuevo
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_11_consistencia_variacion() OWNER TO postgres;

--
-- Name: fn_tgr_m06_12_valor_contable_no_negativo(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_12_valor_contable_no_negativo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_valor_calculado NUMERIC(18,4);
    v_tolerancia      NUMERIC(18,4) := 0.01;
BEGIN
    -- Validar que costo_adquisicion sea positivo
    IF NEW.costos_adquisicion <= 0 THEN
        RAISE EXCEPTION
            '[TGR-M06-12] costos_adquisicion=% debe ser mayor a cero. '
            'El costo de adquisición es la base del método de valoración por costo. '
            'Requerimiento RF-88.',
            NEW.costos_adquisicion
        USING ERRCODE = 'P0001';
    END IF;

    -- Validar que depreciacion y deterioro no sean negativos
    IF NEW.depreciacion_acumulada < 0 THEN
        RAISE EXCEPTION
            '[TGR-M06-12] depreciacion_acumulada=% no puede ser negativa. '
            'Requerimiento RF-88.',
            NEW.depreciacion_acumulada
        USING ERRCODE = 'P0001';
    END IF;

    IF NEW.deterioro_acumulado < 0 THEN
        RAISE EXCEPTION
            '[TGR-M06-12] deterioro_acumulado=% no puede ser negativo. '
            'Requerimiento RF-88.',
            NEW.deterioro_acumulado
        USING ERRCODE = 'P0001';
    END IF;

    -- Calcular el valor_contable esperado
    v_valor_calculado := NEW.costos_adquisicion
                       - NEW.depreciacion_acumulada
                       - NEW.deterioro_acumulado;

    -- Si es negativo, ajustar a cero (comportamiento NIC 41 Párr. 30)
    IF v_valor_calculado < 0 THEN
        NEW.valor_contable_por_costo := 0;
    ELSE
        -- Validar consistencia con el valor ingresado
        IF ABS(NEW.valor_contable_por_costo - v_valor_calculado) > v_tolerancia THEN
            RAISE EXCEPTION
                '[TGR-M06-12] valor_contable_por_costo=% no coincide con '
                '(costos_adquisicion % - depreciacion_acumulada % - '
                'deterioro_acumulado %) = %. '
                'Diferencia: %. Tolerancia: %. Requerimiento RF-88, CA-2.',
                NEW.valor_contable_por_costo,
                NEW.costos_adquisicion,
                NEW.depreciacion_acumulada,
                NEW.deterioro_acumulado,
                v_valor_calculado,
                ABS(NEW.valor_contable_por_costo - v_valor_calculado),
                v_tolerancia
            USING ERRCODE = 'P0001';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_12_valor_contable_no_negativo() OWNER TO postgres;

--
-- Name: fn_tgr_m06_13_inmutabilidad_auditoria(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_13_inmutabilidad_auditoria() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION
            '[TGR-M06-13] El registro de auditoría id=% es absolutamente inmutable. '
            'El repositorio de auditorías financieras es append-only por mandato del '
            'Estatuto Tributario Colombiano y la NIC 41. Ningún actor (incluido el '
            'Administrador) puede modificar registros de auditoría. '
            'Requerimiento RF-94, Restricción 1 y RNF-03.',
            OLD.id_auditoria_financiera
        USING ERRCODE = 'P0001';
    END IF;

    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION
            '[TGR-M06-13] El registro de auditoría id=% no puede eliminarse. '
            'La retención mínima es de 10 años desde el cierre del período. '
            'El repositorio de auditorías es inmutable por diseño de BD. '
            'Requerimiento RF-94, Restricción 1, RNF-03 y RNF-07.',
            OLD.id_auditoria_financiera
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_13_inmutabilidad_auditoria() OWNER TO postgres;

--
-- Name: fn_tgr_m06_14_accounting_account_obligatorio(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_14_accounting_account_obligatorio() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_cuenta TEXT;
BEGIN
    -- Validar que el array no esté vacío
    IF NEW.accounting_account IS NULL
       OR array_length(NEW.accounting_account, 1) IS NULL
       OR array_length(NEW.accounting_account, 1) = 0 THEN
        RAISE EXCEPTION
            '[TGR-M06-14] El campo accounting_account es obligatorio y no puede ser un '
            'array vacío en la tabla %. Debe contener al menos una cuenta PUC válida. '
            'Requerimiento RF-90 Restricción 5.2 / RF-COT Restricción 5.2.',
            TG_TABLE_NAME
        USING ERRCODE = 'P0001';
    END IF;

    -- Validar que ningún elemento del array sea nulo o cadena vacía
    FOREACH v_cuenta IN ARRAY NEW.accounting_account LOOP
        IF v_cuenta IS NULL OR trim(v_cuenta) = '' THEN
            RAISE EXCEPTION
                '[TGR-M06-14] El campo accounting_account contiene un valor nulo o vacío '
                'en la tabla %. Todas las cuentas PUC deben tener un valor válido. '
                'Requerimiento RF-90 Restricción 5.2.',
                TG_TABLE_NAME
            USING ERRCODE = 'P0001';
        END IF;
    END LOOP;

    -- Validar que el array no tenga más de 2 elementos (máximo: débito y crédito)
    IF array_length(NEW.accounting_account, 1) > 2 THEN
        RAISE EXCEPTION
            '[TGR-M06-14] El campo accounting_account en la tabla % contiene % elementos. '
            'El máximo permitido es 2 ([débito, crédito]). '
            'Requerimiento RF-90 Restricción 5.2.',
            TG_TABLE_NAME, array_length(NEW.accounting_account, 1)
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_14_accounting_account_obligatorio() OWNER TO postgres;

--
-- Name: fn_tgr_m06_15_costos_restricciones(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_15_costos_restricciones() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Validar monto positivo en INSERT y UPDATE
    IF NEW.monto_costo <= 0 THEN
        RAISE EXCEPTION
            '[TGR-M06-15] monto_costo=% debe ser mayor a cero. '
            'No se admiten costos con valor cero ni negativo. Requerimiento RF-90.',
            NEW.monto_costo
        USING ERRCODE = 'P0001';
    END IF;

    -- Bloquear reclasificación de MANTENIMIENTO en UPDATE
    IF TG_OP = 'UPDATE' THEN
        IF OLD.naturaleza_costo = 'MANTENIMIENTO'
           AND NEW.naturaleza_costo != 'MANTENIMIENTO' THEN
            RAISE EXCEPTION
                '[TGR-M06-15] El costo id=% tiene naturaleza MANTENIMIENTO y no puede '
                'reclasificarse como %. Esta restricción es absoluta e irrevocable. '
                'Requerimiento RF-90, Restricción 5.1.',
                OLD.id_registro_costo, NEW.naturaleza_costo
            USING ERRCODE = 'P0001';
        END IF;

        -- Bloquear reclasificación de VENTA a MANTENIMIENTO
        IF OLD.naturaleza_costo = 'VENTA'
           AND NEW.naturaleza_costo = 'MANTENIMIENTO' THEN
            RAISE EXCEPTION
                '[TGR-M06-15] El costo id=% tiene naturaleza VENTA y no puede '
                'reclasificarse como MANTENIMIENTO. '
                'Requerimiento RF-90, Restricción 5.7.',
                OLD.id_registro_costo
            USING ERRCODE = 'P0001';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_15_costos_restricciones() OWNER TO postgres;

--
-- Name: fn_tgr_m06_16_motivo_revision_minimo(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_16_motivo_revision_minimo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.motivo_revision IS NULL OR trim(NEW.motivo_revision) = '' THEN
        RAISE EXCEPTION
            '[TGR-M06-16] El campo motivo_revision es obligatorio para registrar una '
            'reversión. Debe contener al menos 20 caracteres que justifiquen la operación. '
            'Requerimiento RF-82, Restricción 2c y CA-15.'
        USING ERRCODE = 'P0001';
    END IF;

    IF char_length(trim(NEW.motivo_revision)) < 20 THEN
        RAISE EXCEPTION
            '[TGR-M06-16] El motivo_revision tiene % caracteres (mínimo requerido: 20). '
            'Ingrese una justificación más detallada de la reversión. '
            'Requerimiento RF-82, Restricción 2c y CA-15.',
            char_length(trim(NEW.motivo_revision))
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_16_motivo_revision_minimo() OWNER TO postgres;

--
-- Name: fn_tgr_m06_17_cotizacion_periodo_cerrado(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_17_cotizacion_periodo_cerrado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado_periodo modulo6.enum_periodo_contables_estado;
    v_id_periodo     INTEGER;
BEGIN
    -- Usar siempre el período de origen de la cotización
    v_id_periodo := OLD.id_periodo_contable;

    SELECT estado
    INTO v_estado_periodo
    FROM modulo6.periodos_contables
    WHERE id_periodo_contable = v_id_periodo;

    IF v_estado_periodo = 'CERRADO' THEN
        RAISE EXCEPTION
            '[TGR-M06-17] La cotización id=% pertenece al período contable id=% '
            'que está CERRADO. Las cotizaciones de períodos cerrados son inmutables: '
            'no pueden modificarse ni anularse. Operación: %. '
            'Requerimiento RF-COT, Restricción 5.12.',
            OLD.id_cotizacion, v_id_periodo, TG_OP
        USING ERRCODE = 'P0001';
    END IF;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_17_cotizacion_periodo_cerrado() OWNER TO postgres;

--
-- Name: fn_tgr_m06_18_fecha_vencimiento_cotizacion(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_18_fecha_vencimiento_cotizacion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Validar coherencia de fechas
    IF NEW.fecha_vencimiento IS NOT NULL
       AND NEW.fecha_vencimiento < NEW.fecha_emision THEN
        RAISE EXCEPTION
            '[TGR-M06-18] fecha_vencimiento=% no puede ser anterior a fecha_emision=%. '
            'Una cotización no puede vencer antes de ser emitida. '
            'Requerimiento RF-COT, Restricción 5.7 y CA-13.',
            NEW.fecha_vencimiento, NEW.fecha_emision
        USING ERRCODE = 'P0001';
    END IF;

    -- Validar valor_cotizacion_propuesto positivo
    IF NEW.valor_cotizacion_propuesto <= 0 THEN
        RAISE EXCEPTION
            '[TGR-M06-18] valor_cotizacion_propuesto=% debe ser mayor a cero. '
            'Requerimiento RF-COT, FA-8.',
            NEW.valor_cotizacion_propuesto
        USING ERRCODE = 'P0001';
    END IF;

    -- Eliminada la validación de valor_razonable_referencia

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_18_fecha_vencimiento_cotizacion() OWNER TO postgres;

--
-- Name: fn_tgr_m06_19_campos_inmutables_cotizacion(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_19_campos_inmutables_cotizacion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- fecha_emision es inmutable
    IF NEW.fecha_emision != OLD.fecha_emision THEN
        RAISE EXCEPTION
            '[TGR-M06-19] El campo fecha_emision de la cotización id=% es inmutable '
            'y no puede modificarse. Requerimiento RF-COT, Restricción 5.8.',
            OLD.id_cotizacion
        USING ERRCODE = 'P0001';
    END IF;

    -- id_periodo_contable es inmutable
    IF NEW.id_periodo_contable != OLD.id_periodo_contable THEN
        RAISE EXCEPTION
            '[TGR-M06-19] El campo id_periodo_contable de la cotización id=% es inmutable. '
            'Requerimiento RF-COT, Restricción 5.8.',
            OLD.id_cotizacion
        USING ERRCODE = 'P0001';
    END IF;

    -- activos_cotizados es inmutable
    IF NEW.activos_cotizados != OLD.activos_cotizados THEN
        RAISE EXCEPTION
            '[TGR-M06-19] El campo activos_cotizados de la cotización id=% es inmutable. '
            'Requerimiento RF-COT, Restricción 5.8.',
            OLD.id_cotizacion
        USING ERRCODE = 'P0001';
    END IF;

    -- accounting_account es inmutable
    IF NEW.accounting_account != OLD.accounting_account THEN
        RAISE EXCEPTION
            '[TGR-M06-19] El campo accounting_account de la cotización id=% es inmutable '
            'después del registro inicial. Requerimiento RF-COT, Restricción 5.8.',
            OLD.id_cotizacion
        USING ERRCODE = 'P0001';
    END IF;

    -- line_type es inmutable
    IF NEW.line_type != OLD.line_type THEN
        RAISE EXCEPTION
            '[TGR-M06-19] El campo line_type de la cotización id=% es inmutable. '
            'Requerimiento RF-COT, Restricción 5.8.',
            OLD.id_cotizacion
        USING ERRCODE = 'P0001';
    END IF;

    -- type_code es inmutable
    IF NEW.type_code != OLD.type_code THEN
        RAISE EXCEPTION
            '[TGR-M06-19] El campo type_code de la cotización id=% es inmutable '
            'y siempre debe ser "4". Requerimiento RF-COT, Restricción 5.8.',
            OLD.id_cotizacion
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_19_campos_inmutables_cotizacion() OWNER TO postgres;

--
-- Name: fn_tgr_m06_20_deterioro_positivo(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_20_deterioro_positivo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Validar que el impacto económico sea positivo
    IF NEW.impacto_economico_cop <= 0 THEN
        RAISE EXCEPTION
            '[TGR-M06-20] impacto_economico_cop=% debe ser mayor a cero. '
            'El deterioro representa una pérdida de valor documentada; no puede ser '
            'cero ni negativo. Requerimiento RF-88, Proceso Paso 5c.',
            NEW.impacto_economico_cop
        USING ERRCODE = 'P0001';
    END IF;

    -- Validar que la justificación no esté vacía
    IF NEW.justificacion IS NULL OR trim(NEW.justificacion) = '' THEN
        RAISE EXCEPTION
            '[TGR-M06-20] La justificacion del deterioro es obligatoria. '
            'Debe relacionar el hecho clínico del evento sanitario con su impacto '
            'monetario sobre el valor del activo. Requerimiento RF-88, Paso 5a.'
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_20_deterioro_positivo() OWNER TO postgres;

--
-- Name: fn_tgr_m06_21_inmutabilidad_cierre(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_21_inmutabilidad_cierre() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION
            '[TGR-M06-21] La ejecución de cierre id=% no puede eliminarse. '
            'Es un registro de auditoría permanente del proceso de cierre contable. '
            'Estado actual: %. Requerimiento RF-87, RNF Fiabilidad.',
            OLD.id_cierre, OLD.estado
        USING ERRCODE = 'P0001';
    END IF;

    IF TG_OP = 'UPDATE' AND OLD.estado IN ('COMPLETADO', 'FALLIDO') THEN
        RAISE EXCEPTION
            '[TGR-M06-21] La ejecución de cierre id=% tiene estado % y es inmutable. '
            'Los cierres completados o fallidos no pueden modificarse retroactivamente. '
            'Requerimiento RF-87, Restricciones y RNF Fiabilidad.',
            OLD.id_cierre, OLD.estado
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_21_inmutabilidad_cierre() OWNER TO postgres;

--
-- Name: fn_tgr_m06_22_unicidad_cierre_activo(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_22_unicidad_cierre_activo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_cierre_existente INTEGER;
BEGIN
    IF NEW.estado = 'EN_PROCESO' THEN
        SELECT id_cierre
        INTO v_cierre_existente
        FROM modulo6.ejecuciones_cierre_periodo
        WHERE id_periodo_contable = NEW.id_periodo_contable
          AND estado = 'EN_PROCESO'
          AND id_cierre != COALESCE(NEW.id_cierre, -1)
        LIMIT 1;

        IF FOUND THEN
            RAISE EXCEPTION
                '[TGR-M06-22] El período contable id=% ya tiene una ejecución de '
                'cierre activa (id_cierre=%). No puede iniciarse otro proceso de '
                'cierre simultáneo. Requerimiento RF-87, Restricciones (exclusive lock) y FA-5.',
                NEW.id_periodo_contable, v_cierre_existente
            USING ERRCODE = 'P0001';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_22_unicidad_cierre_activo() OWNER TO postgres;

--
-- Name: fn_tgr_m06_23_inmutabilidad_estado_resultados(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_23_inmutabilidad_estado_resultados() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION
            '[TGR-M06-23] El estado de resultados id=% del período % no puede '
            'eliminarse. Es un documento financiero permanente. '
            'Requerimiento RF-93, Restricción 5.',
            OLD.id_estado, OLD.id_periodo_contable
        USING ERRCODE = 'P0001';
    END IF;

    IF TG_OP = 'UPDATE' AND OLD.estado IN ('GENERADO', 'APROBADO') THEN
        RAISE EXCEPTION
            '[TGR-M06-23] El estado de resultados id=% tiene estado % y es '
            'inmutable en su contenido base. Para versiones alternativas, '
            'genere un nuevo registro independiente. '
            'Requerimiento RF-93, Restricción 5.',
            OLD.id_estado, OLD.estado
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_23_inmutabilidad_estado_resultados() OWNER TO postgres;

--
-- Name: fn_tgr_m06_24_consistencia_resultado_neto(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_24_consistencia_resultado_neto() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_resultado_calculado NUMERIC(18,4);
    v_tolerancia          NUMERIC(18,4) := 0.01;
BEGIN
    v_resultado_calculado :=
          COALESCE(NEW.total_ingresos_transformacion, 0)
        + COALESCE(NEW.total_ingresos_precio_mercado,  0)
        + COALESCE(NEW.total_ingresos_cosecha,         0)
        - COALESCE(NEW.total_gastos_mantenimiento,     0)
        - COALESCE(NEW.total_bajas_deterioro,          0);

    IF ABS(NEW.resultado_neto - v_resultado_calculado) > v_tolerancia THEN
        RAISE EXCEPTION
            '[TGR-M06-24] Inconsistencia en estado de resultados id=%: '
            'resultado_neto=% no coincide con la suma de componentes = %. '
            'Ingresos transformacion: %, precio mercado: %, cosecha: %. '
            'Gastos mantenimiento: %, bajas deterioro: %. '
            'Diferencia: %. Tolerancia: %. Requerimiento RF-93, Restricción 2 y CA-4.',
            NEW.id_estado,
            NEW.resultado_neto,
            v_resultado_calculado,
            COALESCE(NEW.total_ingresos_transformacion, 0),
            COALESCE(NEW.total_ingresos_precio_mercado,  0),
            COALESCE(NEW.total_ingresos_cosecha,         0),
            COALESCE(NEW.total_gastos_mantenimiento,     0),
            COALESCE(NEW.total_bajas_deterioro,          0),
            ABS(NEW.resultado_neto - v_resultado_calculado),
            v_tolerancia
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_24_consistencia_resultado_neto() OWNER TO postgres;

--
-- Name: fn_tgr_m06_25_inmutabilidad_informe_revelacion(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_25_inmutabilidad_informe_revelacion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION
            '[TGR-M06-25] El informe de revelaciones NIC 41 id=% no puede eliminarse. '
            'Es un documento regulatorio permanente. Estado actual: %. '
            'Requerimiento RF-92, Restricción 5.',
            OLD.id_informe, OLD.estado
        USING ERRCODE = 'P0001';
    END IF;

    IF TG_OP = 'UPDATE' AND OLD.estado IN ('APROBADO', 'ARCHIVADO') THEN
        RAISE EXCEPTION
            '[TGR-M06-25] El informe de revelaciones NIC 41 id=% tiene estado % '
            'y es inmutable. Los informes APROBADOS y ARCHIVADOS no pueden editarse. '
            'Para una nueva versión, genere un nuevo BORRADOR independiente. '
            'Requerimiento RF-92, Restricciones 4 y 5.',
            OLD.id_informe, OLD.estado
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_25_inmutabilidad_informe_revelacion() OWNER TO postgres;

--
-- Name: fn_tgr_m06_26_trazabilidad_periodo_cerrado(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_26_trazabilidad_periodo_cerrado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado_periodo modulo6.enum_periodo_contables_estado;
    v_id_variacion   INTEGER;
BEGIN
    IF TG_OP = 'DELETE' THEN
        v_id_variacion := OLD.id_variacion_valor_razonable;
    ELSE
        v_id_variacion := NEW.id_variacion_valor_razonable;
    END IF;

    IF v_id_variacion IS NULL THEN
        IF TG_OP = 'DELETE' THEN
            RETURN OLD;
        END IF;
        RETURN NEW;
    END IF;

    SELECT pc.estado
    INTO v_estado_periodo
    FROM modulo6.variaciones_valor_razonable vvr
    JOIN modulo6.periodos_contables pc
      ON pc.id_periodo_contable = vvr.id_periodo_contable
    WHERE vvr.id_variacion_valor_razonable = v_id_variacion;

    IF FOUND AND v_estado_periodo = 'CERRADO' THEN
        RAISE EXCEPTION
            '[TGR-M06-26] La cadena de trazabilidad id=% está vinculada a la '
            'variación id=% que pertenece a un período contable CERRADO. '
            'Las cadenas de trazabilidad de períodos cerrados son inmutables y '
            'no pueden modificarse ni completarse retroactivamente. '
            'Operación: %. Requerimiento RF-91, Restricción 4.',
            COALESCE(NEW.id_asiento, OLD.id_asiento),
            v_id_variacion, TG_OP
        USING ERRCODE = 'P0001';
    END IF;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_26_trazabilidad_periodo_cerrado() OWNER TO postgres;

--
-- Name: fn_tgr_m06_27_tipo_actor_auditoria(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_tgr_m06_27_tipo_actor_auditoria() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- tipo_actor = USUARIO requiere id_usuario no nulo
    IF NEW.tipo_actor = 'USUARIO' AND NEW.id_usuario IS NULL THEN
        RAISE EXCEPTION
            '[TGR-M06-27] Evento de auditoría inválido: tipo_actor=USUARIO '
            'requiere id_usuario no nulo. El campo id_usuario no puede ser '
            'nulo cuando el actor es un usuario humano. '
            'Requerimiento RF-94, Restricción 6 y CA-4.'
        USING ERRCODE = 'P0001';
    END IF;

    -- tipo_actor = SISTEMA requiere id_usuario nulo
    IF NEW.tipo_actor = 'SISTEMA' AND NEW.id_usuario IS NOT NULL THEN
        RAISE EXCEPTION
            '[TGR-M06-27] Evento de auditoría inválido: tipo_actor=SISTEMA '
            'requiere id_usuario nulo. No puede existir un actor humano '
            'identificado en un evento de proceso automático. '
            'Requerimiento RF-94, Restricción 6 y CA-4.'
        USING ERRCODE = 'P0001';
    END IF;

    -- El hash_integridad no puede ser nulo ni vacío
    IF NEW.hash_integridad IS NULL OR trim(NEW.hash_integridad) = '' THEN
        RAISE EXCEPTION
            '[TGR-M06-27] El campo hash_integridad es obligatorio en todo '
            'registro de auditoría financiera. Garantiza la verificabilidad '
            'del registro ante auditorías externas. '
            'Requerimiento RF-94, Restricción 6 y RNF-04.'
        USING ERRCODE = 'P0001';
    END IF;

    -- El hash_integridad debe tener exactamente 64 caracteres (SHA-256 hex)
    IF char_length(NEW.hash_integridad) != 64 THEN
        RAISE EXCEPTION
            '[TGR-M06-27] El hash_integridad tiene % caracteres; se esperan '
            'exactamente 64 (SHA-256 hexadecimal). '
            'Requerimiento RF-94, Restricción 4 (hash_integridad).',
            char_length(NEW.hash_integridad)
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_tgr_m06_27_tipo_actor_auditoria() OWNER TO postgres;

--
-- Name: fn_validar_periodo_abierto_en_variacion(); Type: FUNCTION; Schema: modulo6; Owner: postgres
--

CREATE FUNCTION modulo6.fn_validar_periodo_abierto_en_variacion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_estado modulo6.enum_periodo_contables_estado;
BEGIN
    SELECT estado
      INTO v_estado
      FROM modulo6.periodos_contables
     WHERE id_periodo_contable = NEW.id_periodo_contable;

    IF v_estado IS NULL THEN
        RAISE EXCEPTION
            'PERIODO_NO_ENCONTRADO: el período contable % no existe.',
            NEW.id_periodo_contable
            USING ERRCODE = 'P0001';
    END IF;

    IF v_estado IN ('CERRADO', 'EN_CIERRE') THEN
        RAISE EXCEPTION
            'PERIODO_CONTABLE_CERRADO: no se puede registrar una variación '
            'de valor razonable en el período % porque su estado es "%". '
            'Solo se permiten variaciones en períodos ABIERTOS (RF-86 FA-2).',
            NEW.id_periodo_contable, v_estado
            USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo6.fn_validar_periodo_abierto_en_variacion() OWNER TO postgres;

--
-- Name: FUNCTION fn_validar_periodo_abierto_en_variacion(); Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON FUNCTION modulo6.fn_validar_periodo_abierto_en_variacion() IS 'Trigger function que impide registrar variaciones de valor razonable cuando el período contable asociado está CERRADO o EN_CIERRE. Implementa la restricción FA-2 de RF-86. Referencia: RF-86, RF-87.';


--
-- Name: fn_tgr_m07_01_auditoria_peticiones_inmutable(); Type: FUNCTION; Schema: modulo7; Owner: postgres
--

CREATE FUNCTION modulo7.fn_tgr_m07_01_auditoria_peticiones_inmutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION
            '[TGR-M07-01] El registro de auditoría evento=% no puede modificarse. '
            'El repositorio de auditoría del módulo M07 es absolutamente inmutable '
            '(append-only). Ningún actor, incluido el Administrador, puede alterar '
            'registros existentes. Operación bloqueada: UPDATE. '
            'Requerimiento RF-102, Restricción 4.4.',
            OLD.evento
        USING ERRCODE = 'P0001';
    END IF;

    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION
            '[TGR-M07-01] El registro de auditoría evento=% no puede eliminarse. '
            'El repositorio de auditoría del módulo M07 es absolutamente inmutable '
            '(append-only). La retención mínima es de 5 años (10 años para eventos AAEF). '
            'Operación bloqueada: DELETE. '
            'Requerimiento RF-102, Restricción 4.4 y Restricción 4.7 (política de retención).',
            OLD.evento
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NULL;
END;
$$;


ALTER FUNCTION modulo7.fn_tgr_m07_01_auditoria_peticiones_inmutable() OWNER TO postgres;

--
-- Name: fn_tgr_m07_02_auditoria_hash_obligatorio(); Type: FUNCTION; Schema: modulo7; Owner: postgres
--

CREATE FUNCTION modulo7.fn_tgr_m07_02_auditoria_hash_obligatorio() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
    IF NEW.evento_sha256 IS NULL OR trim(NEW.evento_sha256) = '' THEN
        RAISE EXCEPTION
            '[TGR-M07-02] El campo evento_sha256 es obligatorio y no puede ser nulo '
            'ni vacío al registrar un evento de auditoría. Todo registro de auditoría '
            'debe incluir su hash SHA-256 de integridad calculado por el backend. '
            'Evento UUID: %. '
            'Requerimiento RF-102, Restricción 4.6 y Restricción 4.7.',
            NEW.evento
        USING ERRCODE = 'P0001';
    END IF;

    IF length(NEW.evento_sha256) <> 64 THEN
        RAISE EXCEPTION
            '[TGR-M07-02] El campo evento_sha256 debe tener exactamente 64 caracteres '
            '(representación hexadecimal de SHA-256). Longitud recibida: %. Evento UUID: %. '
            'Requerimiento RF-102, Restricción 4.6.',
            length(NEW.evento_sha256), NEW.evento
        USING ERRCODE = 'P0001';
    END IF;

    IF NEW.evento_sha256 !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION
            '[TGR-M07-02] El campo evento_sha256 contiene caracteres inválidos. '
            'Solo se admiten dígitos hexadecimales en minúscula (a-f, 0-9). '
            'Evento UUID: %. '
            'Requerimiento RF-102, Restricción 4.6.',
            NEW.evento
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$_$;


ALTER FUNCTION modulo7.fn_tgr_m07_02_auditoria_hash_obligatorio() OWNER TO postgres;

--
-- Name: fn_tgr_m07_03_versiones_contrato_transicion_estado(); Type: FUNCTION; Schema: modulo7; Owner: postgres
--

CREATE FUNCTION modulo7.fn_tgr_m07_03_versiones_contrato_transicion_estado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_orden_anterior INT;
    v_orden_nuevo    INT;
BEGIN
    -- Sin cambio de estado: permitir sin restricción
    IF OLD.estado = NEW.estado THEN
        RETURN NEW;
    END IF;

    -- Mapeo de orden jerárquico según los valores reales del ENUM
    v_orden_anterior := CASE OLD.estado::TEXT
        WHEN 'BORRADOR'    THEN 1
        WHEN 'EN_REVISION' THEN 2
        WHEN 'APROBADO'    THEN 3
        WHEN 'OBSOLETO'    THEN 4
        ELSE 0
    END;

    v_orden_nuevo := CASE NEW.estado::TEXT
        WHEN 'BORRADOR'    THEN 1
        WHEN 'EN_REVISION' THEN 2
        WHEN 'APROBADO'    THEN 3
        WHEN 'OBSOLETO'    THEN 4
        ELSE 0
    END;

    -- Bloquear cualquier intento de modificar un contrato en estado OBSOLETO
    IF OLD.estado::TEXT = 'OBSOLETO' THEN
        RAISE EXCEPTION
            '[TGR-M07-03] El contrato versión=% se encuentra en estado OBSOLETO, '
            'que es irreversible. No se puede reactivar ni cambiar a ningún otro estado. '
            'Estado intentado: %. '
            'Requerimiento RF-98, Restricción 5.1 y FA-13 (REACTIVACION_NO_PERMITIDA).',
            OLD.contrato_version, NEW.estado
        USING ERRCODE = 'P0001';
    END IF;

    -- Bloquear retroceso de estado (orden descendente)
    IF v_orden_nuevo < v_orden_anterior THEN
        RAISE EXCEPTION
            '[TGR-M07-03] Retroceso de estado no permitido para el contrato versión=%. '
            'La secuencia válida es BORRADOR → EN_REVISION → APROBADO → OBSOLETO. '
            'Transición inválida detectada: % → %. '
            'Requerimiento RF-98, Restricción 5.1 y CA-27.',
            OLD.contrato_version, OLD.estado, NEW.estado
        USING ERRCODE = 'P0001';
    END IF;

    -- Bloquear salto de estado (avanzar más de un paso a la vez)
    IF v_orden_nuevo > v_orden_anterior + 1 THEN
        RAISE EXCEPTION
            '[TGR-M07-03] Salto de estado no permitido para el contrato versión=%. '
            'Solo se puede avanzar un estado a la vez en la secuencia '
            'BORRADOR → EN_REVISION → APROBADO → OBSOLETO. '
            'Transición inválida detectada: % → %. '
            'Requerimiento RF-98, Restricción 5.1 y CA-26.',
            OLD.contrato_version, OLD.estado, NEW.estado
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo7.fn_tgr_m07_03_versiones_contrato_transicion_estado() OWNER TO postgres;

--
-- Name: fn_tgr_m07_04_versiones_contrato_limite_activas(); Type: FUNCTION; Schema: modulo7; Owner: postgres
--

CREATE FUNCTION modulo7.fn_tgr_m07_04_versiones_contrato_limite_activas() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INT;
BEGIN
    -- Solo aplica cuando el nuevo estado es APROBADO u OBSOLETO
    IF NEW.estado::TEXT NOT IN ('APROBADO', 'OBSOLETO') THEN
        RETURN NEW;
    END IF;

    -- Si el estado anterior ya era APROBADO u OBSOLETO, la fila ya estaba
    -- contabilizada; no suma al límite
    IF OLD.estado::TEXT IN ('APROBADO', 'OBSOLETO') THEN
        RETURN NEW;
    END IF;

    -- Contar versiones actualmente en APROBADO u OBSOLETO, excluyendo la fila actual
    SELECT count(*)
    INTO v_count
    FROM modulo7.versiones_contrato_aaef
    WHERE estado::TEXT IN ('APROBADO', 'OBSOLETO')
      AND id_version_contrato_aaef <> NEW.id_version_contrato_aaef;

    IF v_count >= 2 THEN
        RAISE EXCEPTION
            '[TGR-M07-04] Límite de versiones simultáneas excedido. Ya existen % '
            'versiones en estado APROBADO u OBSOLETO. El máximo permitido es 2. '
            'Versión bloqueada: %. Deprecar una versión existente (cambiar a OBSOLETO) '
            'antes de aprobar una nueva (error LIMITE_VERSIONES_EXCEDIDO). '
            'Requerimiento RF-98, Restricción 5.3, 5.6 y CA-21.',
            v_count, NEW.contrato_version
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo7.fn_tgr_m07_04_versiones_contrato_limite_activas() OWNER TO postgres;

--
-- Name: fn_tgr_m07_05_versiones_contrato_inmutable_activo(); Type: FUNCTION; Schema: modulo7; Owner: postgres
--

CREATE FUNCTION modulo7.fn_tgr_m07_05_versiones_contrato_inmutable_activo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Solo aplica si el estado actual es APROBADO u OBSOLETO
    IF OLD.estado::TEXT NOT IN ('APROBADO', 'OBSOLETO') THEN
        RETURN NEW;
    END IF;

    -- Detectar intentos de modificar campos estructurales (distinto a la columna estado,
    -- cuya transición es controlada exclusivamente por TGR-M07-03)
    IF NEW.contrato_version <> OLD.contrato_version THEN
        RAISE EXCEPTION
            '[TGR-M07-05] El campo contrato_version del contrato id=% es inmutable '
            'cuando el estado es %. Crear una nueva versión para introducir cambios. '
            'Requerimiento RF-98, Restricción 5.12 y RNF-98.11.',
            OLD.id_version_contrato_aaef, OLD.estado
        USING ERRCODE = 'P0001';
    END IF;

    IF NEW.fecha_comienzo <> OLD.fecha_comienzo THEN
        RAISE EXCEPTION
            '[TGR-M07-05] El campo fecha_comienzo del contrato id=% es inmutable '
            'cuando el estado es %. Crear una nueva versión para introducir cambios. '
            'Requerimiento RF-98, Restricción 5.12 y RNF-98.11.',
            OLD.id_version_contrato_aaef, OLD.estado
        USING ERRCODE = 'P0001';
    END IF;

    IF NEW.descripcion IS DISTINCT FROM OLD.descripcion THEN
        RAISE EXCEPTION
            '[TGR-M07-05] El campo descripcion del contrato id=% es inmutable '
            'cuando el estado es %. Crear una nueva versión para introducir cambios. '
            'Requerimiento RF-98, Restricción 5.12 y RNF-98.11.',
            OLD.id_version_contrato_aaef, OLD.estado
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo7.fn_tgr_m07_05_versiones_contrato_inmutable_activo() OWNER TO postgres;

--
-- Name: fn_tgr_m07_06_cliente_externo_estado_valido(); Type: FUNCTION; Schema: modulo7; Owner: postgres
--

CREATE FUNCTION modulo7.fn_tgr_m07_06_cliente_externo_estado_valido() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Sin cambio de estado: permitir sin restricción
    IF OLD.estado IS NOT DISTINCT FROM NEW.estado THEN
        RETURN NEW;
    END IF;

    -- REVOCADO es irreversible: bloquear cualquier cambio desde ese estado
    IF OLD.estado::TEXT = 'REVOCADO' THEN
        RAISE EXCEPTION
            '[TGR-M07-06] El cliente externo id=% (código=%, nombre=%) se encuentra '
            'en estado REVOCADO, que es permanente e irreversible. No se puede '
            'cambiar a ningún otro estado. Estado intentado: %. '
            'Requerimiento RF-101, Restricción 6 y Proceso Fase 4.',
            OLD.id_cliente_externo, OLD.codigo, OLD.nombre, NEW.estado
        USING ERRCODE = 'P0001';
    END IF;

    -- Desde SUSPENDIDO solo se permite transición a ACTIVO o REVOCADO
    IF OLD.estado::TEXT = 'SUSPENDIDO'
       AND NEW.estado::TEXT NOT IN ('ACTIVO', 'REVOCADO') THEN
        RAISE EXCEPTION
            '[TGR-M07-06] El cliente externo id=% (código=%) tiene estado SUSPENDIDO. '
            'Desde este estado solo se permite transición a ACTIVO (reactivación) '
            'o REVOCADO (revocación definitiva). Estado intentado: %. '
            'Requerimiento RF-101, Restricción 6.',
            OLD.id_cliente_externo, OLD.codigo, NEW.estado
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo7.fn_tgr_m07_06_cliente_externo_estado_valido() OWNER TO postgres;

--
-- Name: fn_tgr_m07_07_identificadores_apis_un_activo(); Type: FUNCTION; Schema: modulo7; Owner: postgres
--

CREATE FUNCTION modulo7.fn_tgr_m07_07_identificadores_apis_un_activo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INT;
BEGIN
    -- Solo aplica cuando el nuevo estado es ACTIVA
    IF NEW.estado::TEXT <> 'ACTIVA' THEN
        RETURN NEW;
    END IF;

    -- En UPDATE: si la fila ya estaba en ACTIVA para sí misma, no hay solapamiento
    IF TG_OP = 'UPDATE' AND OLD.estado::TEXT = 'ACTIVA' THEN
        RETURN NEW;
    END IF;

    -- Verificar que no exista otra API Key en estado ACTIVA para el mismo cliente
    SELECT count(*)
    INTO v_count
    FROM modulo7.identificadores_apis
    WHERE id_cliente_externo = NEW.id_cliente_externo
      AND estado::TEXT = 'ACTIVA'
      AND id_identificador_api <> COALESCE(NEW.id_identificador_api, -1);

    IF v_count > 0 THEN
        RAISE EXCEPTION
            '[TGR-M07-07] Ya existe una API Key en estado ACTIVA para el cliente '
            'externo id=%. No puede coexistir más de una credencial activa simultáneamente. '
            'Invalidar (revocar o expirar) la credencial anterior antes de activar '
            'la nueva, garantizando renovación atómica sin solapamiento. '
            'Requerimiento RF-101, Proceso Fase 2 y CA-5.',
            NEW.id_cliente_externo
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo7.fn_tgr_m07_07_identificadores_apis_un_activo() OWNER TO postgres;

--
-- Name: fn_tgr_m07_08_identificadores_apis_fecha_valida(); Type: FUNCTION; Schema: modulo7; Owner: postgres
--

CREATE FUNCTION modulo7.fn_tgr_m07_08_identificadores_apis_fecha_valida() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Validar que fecha_expiracion esté presente
    IF NEW.fecha_expiracion IS NULL THEN
        RAISE EXCEPTION
            '[TGR-M07-08] El campo fecha_expiracion es obligatorio para toda API Key. '
            'Toda credencial debe tener una fecha de vencimiento definida. '
            'Cliente externo id=%. '
            'Requerimiento RF-101, Restricción 9.',
            NEW.id_cliente_externo
        USING ERRCODE = 'P0001';
    END IF;

    -- Validar que fecha_expiracion sea estrictamente posterior a fecha_emision
    IF NEW.fecha_expiracion <= NEW.fecha_emision THEN
        RAISE EXCEPTION
            '[TGR-M07-08] fecha_expiracion=% debe ser estrictamente posterior a '
            'fecha_emision=%. Una API Key no puede expirar en la misma fecha en que '
            'fue emitida ni antes. Cliente externo id=%. '
            'Requerimiento RF-101, Restricción 9.',
            NEW.fecha_expiracion, NEW.fecha_emision, NEW.id_cliente_externo
        USING ERRCODE = 'P0001';
    END IF;

    -- Validar que fecha_revocacion, si existe, no sea anterior a fecha_emision
    IF NEW.fecha_revocacion IS NOT NULL
       AND NEW.fecha_revocacion < NEW.fecha_emision THEN
        RAISE EXCEPTION
            '[TGR-M07-08] fecha_revocacion=% no puede ser anterior a '
            'fecha_emision=%. Una API Key no puede revocarse antes de haber sido emitida. '
            'Cliente externo id=%. '
            'Requerimiento RF-101, Restricción 9.',
            NEW.fecha_revocacion, NEW.fecha_emision, NEW.id_cliente_externo
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo7.fn_tgr_m07_08_identificadores_apis_fecha_valida() OWNER TO postgres;

--
-- Name: fn_tgr_m07_09_mapeos_anexos_hash_obligatorio(); Type: FUNCTION; Schema: modulo7; Owner: postgres
--

CREATE FUNCTION modulo7.fn_tgr_m07_09_mapeos_anexos_hash_obligatorio() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
    IF NEW.canonical_sha256 IS NULL OR trim(NEW.canonical_sha256) = '' THEN
        RAISE EXCEPTION
            '[TGR-M07-09] El campo canonical_sha256 es obligatorio al registrar un '
            'anexo de mapeo AAEF. El hash SHA-256 del documento canónico formal es el '
            'mecanismo de verificación de integridad del Anexo. Código anexo: %. '
            'Requerimiento RF-AE02, Restricción 5.6 y CA-20.',
            NEW.codigo_anexo
        USING ERRCODE = 'P0001';
    END IF;

    IF length(NEW.canonical_sha256) <> 64 THEN
        RAISE EXCEPTION
            '[TGR-M07-09] El campo canonical_sha256 debe tener exactamente 64 caracteres '
            '(representación hexadecimal de SHA-256). Longitud recibida: %. Código anexo: %. '
            'Requerimiento RF-AE02, Restricción 5.6.',
            length(NEW.canonical_sha256), NEW.codigo_anexo
        USING ERRCODE = 'P0001';
    END IF;

    IF NEW.canonical_sha256 !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION
            '[TGR-M07-09] El campo canonical_sha256 contiene caracteres inválidos. '
            'Solo se admiten dígitos hexadecimales en minúscula (a-f, 0-9). '
            'Código anexo: %. '
            'Requerimiento RF-AE02, Restricción 5.6 y CA-27.',
            NEW.codigo_anexo
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$_$;


ALTER FUNCTION modulo7.fn_tgr_m07_09_mapeos_anexos_hash_obligatorio() OWNER TO postgres;

--
-- Name: fn_tgr_m07_10_mapeos_anexos_orden_aprobaciones(); Type: FUNCTION; Schema: modulo7; Owner: postgres
--

CREATE FUNCTION modulo7.fn_tgr_m07_10_mapeos_anexos_orden_aprobaciones() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Bloquear registro de aprobación de Agrofusión sin aprobación interna previa
    IF NEW.fecha_aprobacion_agrofusion IS NOT NULL
       AND NEW.fecha_aprobacion_interna IS NULL THEN
        RAISE EXCEPTION
            '[TGR-M07-10] No se puede registrar la aprobación de Agrofusión '
            '(fecha_aprobacion_agrofusion=%) sin que exista previamente una aprobación '
            'interna del Equipo Contable/Financiero (fecha_aprobacion_interna IS NULL). '
            'La aprobación interna es precondición obligatoria para el envío externo. '
            'Código anexo: %. '
            'Requerimiento RF-AE02, Restricción 5.9 y CA-31.',
            NEW.fecha_aprobacion_agrofusion, NEW.codigo_anexo
        USING ERRCODE = 'P0001';
    END IF;

    -- Validar coherencia cronológica: aprobación de Agrofusión no puede
    -- ser anterior a la aprobación interna
    IF NEW.fecha_aprobacion_agrofusion IS NOT NULL
       AND NEW.fecha_aprobacion_interna IS NOT NULL
       AND NEW.fecha_aprobacion_agrofusion < NEW.fecha_aprobacion_interna THEN
        RAISE EXCEPTION
            '[TGR-M07-10] La fecha_aprobacion_agrofusion=% no puede ser anterior a '
            'fecha_aprobacion_interna=%. El proceso de aprobación externa siempre '
            'ocurre después del proceso interno. Código anexo: %. '
            'Requerimiento RF-AE02, Restricción 5.9 y CA-31.',
            NEW.fecha_aprobacion_agrofusion,
            NEW.fecha_aprobacion_interna,
            NEW.codigo_anexo
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo7.fn_tgr_m07_10_mapeos_anexos_orden_aprobaciones() OWNER TO postgres;

--
-- Name: fn_tgr_m07_11_metadatos_respuesta_hash_obligatorio(); Type: FUNCTION; Schema: modulo7; Owner: postgres
--

CREATE FUNCTION modulo7.fn_tgr_m07_11_metadatos_respuesta_hash_obligatorio() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
    IF NEW.sha256_sobre IS NULL OR trim(NEW.sha256_sobre) = '' THEN
        RAISE EXCEPTION
            '[TGR-M07-11] El campo sha256_sobre es obligatorio al registrar un envelope '
            'de respuesta AAEF. El hash SHA-256 del contenido canónico es el mecanismo '
            'de verificación de integridad que Agrofusión utiliza para validar el payload. '
            'Solicitud id=%. '
            'Requerimiento RF-97 Fase 9 y RF-AE01 RNF-AE01.5.',
            NEW.id_integracion_solicitud
        USING ERRCODE = 'P0001';
    END IF;

    IF length(NEW.sha256_sobre) <> 64 THEN
        RAISE EXCEPTION
            '[TGR-M07-11] El campo sha256_sobre debe tener exactamente 64 caracteres '
            '(representación hexadecimal de SHA-256). Longitud recibida: %. Solicitud id=%. '
            'Requerimiento RF-97 Fase 9 y RF-AE01 RNF-AE01.5.',
            length(NEW.sha256_sobre), NEW.id_integracion_solicitud
        USING ERRCODE = 'P0001';
    END IF;

    IF NEW.sha256_sobre !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION
            '[TGR-M07-11] El campo sha256_sobre contiene caracteres inválidos. '
            'Solo se admiten dígitos hexadecimales en minúscula (a-f, 0-9). '
            'Solicitud id=%. '
            'Requerimiento RF-97 Fase 9 y RF-AE01 CA-10.',
            NEW.id_integracion_solicitud
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$_$;


ALTER FUNCTION modulo7.fn_tgr_m07_11_metadatos_respuesta_hash_obligatorio() OWNER TO postgres;

--
-- Name: fn_tgr_m07_12_webhook_payload_hash_obligatorio(); Type: FUNCTION; Schema: modulo7; Owner: postgres
--

CREATE FUNCTION modulo7.fn_tgr_m07_12_webhook_payload_hash_obligatorio() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
    IF NEW.payload_sha256 IS NULL OR trim(NEW.payload_sha256) = '' THEN
        RAISE EXCEPTION
            '[TGR-M07-12] El campo payload_sha256 es obligatorio al registrar una '
            'notificación webhook. El hash SHA-256 del payload es evidencia de integridad '
            'necesaria para auditoría y verificación posterior del mensaje enviado. '
            'Solicitud id=%. '
            'Requerimiento RF-99, Restricción de firma obligatoria y RNF-99.8.',
            NEW.id_integracion_solicitudes
        USING ERRCODE = 'P0001';
    END IF;

    IF length(NEW.payload_sha256) <> 64 THEN
        RAISE EXCEPTION
            '[TGR-M07-12] El campo payload_sha256 debe tener exactamente 64 caracteres '
            '(representación hexadecimal de SHA-256). Longitud recibida: %. Solicitud id=%. '
            'Requerimiento RF-99, Restricción de firma HMAC.',
            length(NEW.payload_sha256), NEW.id_integracion_solicitudes
        USING ERRCODE = 'P0001';
    END IF;

    IF NEW.payload_sha256 !~ '^[a-f0-9]{64}$' THEN
        RAISE EXCEPTION
            '[TGR-M07-12] El campo payload_sha256 contiene caracteres inválidos. '
            'Solo se admiten dígitos hexadecimales en minúscula (a-f, 0-9). '
            'Solicitud id=%. '
            'Requerimiento RF-99, Restricción de firma HMAC y RNF-99.14.',
            NEW.id_integracion_solicitudes
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$_$;


ALTER FUNCTION modulo7.fn_tgr_m07_12_webhook_payload_hash_obligatorio() OWNER TO postgres;

--
-- Name: fn_tgr_m07_13_integraciones_fechas_coherentes(); Type: FUNCTION; Schema: modulo7; Owner: postgres
--

CREATE FUNCTION modulo7.fn_tgr_m07_13_integraciones_fechas_coherentes() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Solo validar cuando ambas fechas estén presentes
    IF NEW.fecha_finalizacion IS NULL OR NEW.fecha_comienzoo IS NULL THEN
        RETURN NEW;
    END IF;

    IF NEW.fecha_finalizacion < NEW.fecha_comienzoo THEN
        RAISE EXCEPTION
            '[TGR-M07-13] La fecha_finalizacion=% no puede ser anterior a '
            'fecha_comienzoo=% en la solicitud de integración id=%. '
            'Un registro con duración negativa produciría métricas de rendimiento '
            'erróneas e invalidaría la trazabilidad de la operación. '
            'Requerimiento RF-95 RNF-95.2 y RF-102 Restricción 4.7.',
            NEW.fecha_finalizacion,
            NEW.fecha_comienzoo,
            NEW.id_integracion_solicitud
        USING ERRCODE = 'P0001';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo7.fn_tgr_m07_13_integraciones_fechas_coherentes() OWNER TO postgres;

--
-- Name: fn_trg_m08_01_prevent_dashboard_predeterminado_duplicado(); Type: FUNCTION; Schema: modulo8; Owner: postgres
--

CREATE FUNCTION modulo8.fn_trg_m08_01_prevent_dashboard_predeterminado_duplicado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.es_predeterminado = TRUE THEN
        UPDATE modulo8.dashboards
        SET    es_predeterminado = FALSE
        WHERE  id_usuario        = NEW.id_usuario
          AND  es_predeterminado = TRUE
          AND  id_dashboard IS DISTINCT FROM NEW.id_dashboard;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo8.fn_trg_m08_01_prevent_dashboard_predeterminado_duplicado() OWNER TO postgres;

--
-- Name: FUNCTION fn_trg_m08_01_prevent_dashboard_predeterminado_duplicado(); Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON FUNCTION modulo8.fn_trg_m08_01_prevent_dashboard_predeterminado_duplicado() IS 'Garantiza unicidad del dashboard predeterminado por usuario. Desactiva el anterior cuando se activa uno nuevo para el mismo usuario. Cubre la integridad de datos del campo es_predeterminado en RF-103.';


--
-- Name: fn_trg_m08_02_validate_semaforo_umbrales_consistencia(); Type: FUNCTION; Schema: modulo8; Owner: postgres
--

CREATE FUNCTION modulo8.fn_trg_m08_02_validate_semaforo_umbrales_consistencia() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.umbral_verde_min IS NOT NULL AND NEW.umbral_verde_max IS NOT NULL THEN
        IF NEW.umbral_verde_min > NEW.umbral_verde_max THEN
            RAISE EXCEPTION
                '[TGR-M08-02] SEMAFORO_UMBRAL_INVALIDO: umbral_verde_min (%) no puede ser '
                'mayor que umbral_verde_max (%) para id_configuracion_semaforo=%. '
                'Una configuración con min > max hace imposible la evaluación de KPI. '
                'Requerimiento RF-103, Restricción 5 (lógica de semáforo).',
                NEW.umbral_verde_min, NEW.umbral_verde_max, NEW.id_configuracion_semaforo
            USING ERRCODE = 'check_violation';
        END IF;
    END IF;

    IF NEW.umbral_amarillo_min IS NOT NULL AND NEW.umbral_amarillo_max IS NOT NULL THEN
        IF NEW.umbral_amarillo_min > NEW.umbral_amarillo_max THEN
            RAISE EXCEPTION
                '[TGR-M08-02] SEMAFORO_UMBRAL_INVALIDO: umbral_amarillo_min (%) no puede ser '
                'mayor que umbral_amarillo_max (%) para id_configuracion_semaforo=%. '
                'Una configuración con min > max hace imposible la evaluación de KPI. '
                'Requerimiento RF-103, Restricción 5 (lógica de semáforo).',
                NEW.umbral_amarillo_min, NEW.umbral_amarillo_max, NEW.id_configuracion_semaforo
            USING ERRCODE = 'check_violation';
        END IF;
    END IF;

    IF NEW.umbral_rojo_min IS NOT NULL AND NEW.umbral_rojo_max IS NOT NULL THEN
        IF NEW.umbral_rojo_min > NEW.umbral_rojo_max THEN
            RAISE EXCEPTION
                '[TGR-M08-02] SEMAFORO_UMBRAL_INVALIDO: umbral_rojo_min (%) no puede ser '
                'mayor que umbral_rojo_max (%) para id_configuracion_semaforo=%. '
                'Una configuración con min > max hace imposible la evaluación de KPI. '
                'Requerimiento RF-103, Restricción 5 (lógica de semáforo).',
                NEW.umbral_rojo_min, NEW.umbral_rojo_max, NEW.id_configuracion_semaforo
            USING ERRCODE = 'check_violation';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo8.fn_trg_m08_02_validate_semaforo_umbrales_consistencia() OWNER TO postgres;

--
-- Name: FUNCTION fn_trg_m08_02_validate_semaforo_umbrales_consistencia(); Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON FUNCTION modulo8.fn_trg_m08_02_validate_semaforo_umbrales_consistencia() IS 'Valida consistencia interna de los umbrales de semáforo (min <= max por banda). Evita configuraciones malformadas que generarían evaluaciones de KPI incorrectas. Cubre la integridad de datos requerida por la lógica de semáforo del Productor en RF-103.';


--
-- Name: fn_trg_m08_03_reporte_regulatorio_fecha_expiracion_estado(); Type: FUNCTION; Schema: modulo8; Owner: postgres
--

CREATE FUNCTION modulo8.fn_trg_m08_03_reporte_regulatorio_fecha_expiracion_estado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.estado::TEXT = 'COMPLETADO'
       AND (NEW.ruta_archivo IS NULL OR TRIM(NEW.ruta_archivo) = '')
    THEN
        RAISE EXCEPTION
            '[TGR-M08-03] REPORTE_SIN_RUTA: No se puede marcar el reporte regulatorio '
            '(id=%) como COMPLETADO sin ruta_archivo definida. Un reporte completado sin '
            'ruta de archivo es un estado corrupto que haría fallar cualquier intento de '
            'descarga. Requerimiento RF-104, ciclo de vida del reporte.',
            NEW.id_reporte_regulatorio
        USING ERRCODE = 'check_violation';
    END IF;

    IF TG_OP = 'INSERT' AND NEW.fecha_generacion IS NULL THEN
        NEW.fecha_generacion = NOW();
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo8.fn_trg_m08_03_reporte_regulatorio_fecha_expiracion_estado() OWNER TO postgres;

--
-- Name: FUNCTION fn_trg_m08_03_reporte_regulatorio_fecha_expiracion_estado(); Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON FUNCTION modulo8.fn_trg_m08_03_reporte_regulatorio_fecha_expiracion_estado() IS 'Valida que un reporte regulatorio no pueda transicionar a COMPLETADO sin ruta_archivo. Garantiza integridad del ciclo de vida del reporte definido en RF-104. También asegura que fecha_generacion se asigne en el INSERT si no viene provista.';


--
-- Name: fn_trg_m08_04_reporte_financiero_hash_obligatorio(); Type: FUNCTION; Schema: modulo8; Owner: postgres
--

CREATE FUNCTION modulo8.fn_trg_m08_04_reporte_financiero_hash_obligatorio() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
    IF NEW.ruta_archivo IS NOT NULL AND TRIM(NEW.ruta_archivo) <> '' THEN

        IF NEW.sha256_archivo IS NULL OR TRIM(NEW.sha256_archivo) = '' THEN
            RAISE EXCEPTION
                '[TGR-M08-04] REPORTE_HASH_FALTANTE: El reporte financiero (id=%) tiene '
                'ruta_archivo pero no tiene sha256_archivo. Todo archivo almacenado debe '
                'incluir su hash de integridad para permitir la verificación definida en '
                'RNF-10. Requerimiento RF-104 RNF-10 y Postcondiciones.',
                NEW.id_reporte_financiero
            USING ERRCODE = 'check_violation';
        END IF;

        IF LENGTH(NEW.sha256_archivo) <> 64 THEN
            RAISE EXCEPTION
                '[TGR-M08-04] REPORTE_HASH_INVALIDO: sha256_archivo debe tener exactamente '
                '64 caracteres hexadecimales. Recibido: % caracteres para '
                'id_reporte_financiero=%. Requerimiento RF-104 RNF-10.',
                LENGTH(NEW.sha256_archivo), NEW.id_reporte_financiero
            USING ERRCODE = 'check_violation';
        END IF;

        IF NEW.sha256_archivo !~ '^[a-fA-F0-9]{64}$' THEN
            RAISE EXCEPTION
                '[TGR-M08-04] REPORTE_HASH_FORMATO_INVALIDO: sha256_archivo contiene '
                'caracteres no hexadecimales en id_reporte_financiero=%. '
                'Solo se admiten dígitos hexadecimales (a-f, A-F, 0-9). '
                'Requerimiento RF-104 RNF-10.',
                NEW.id_reporte_financiero
            USING ERRCODE = 'check_violation';
        END IF;

    END IF;

    RETURN NEW;
END;
$_$;


ALTER FUNCTION modulo8.fn_trg_m08_04_reporte_financiero_hash_obligatorio() OWNER TO postgres;

--
-- Name: FUNCTION fn_trg_m08_04_reporte_financiero_hash_obligatorio(); Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON FUNCTION modulo8.fn_trg_m08_04_reporte_financiero_hash_obligatorio() IS 'Garantiza que todo reporte financiero con ruta_archivo tenga su sha256_archivo válido (64 caracteres hexadecimales). Cubre el RNF-10 de RF-104 sobre integridad de archivos. Un registro con ruta_archivo pero sin hash nunca podrá ser verificado antes de la descarga.';


--
-- Name: fn_trg_m08_05_retroalimentacion_append_only(); Type: FUNCTION; Schema: modulo8; Owner: postgres
--

CREATE FUNCTION modulo8.fn_trg_m08_05_retroalimentacion_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION
        '[TGR-M08-05] RETROALIMENTACION_INMUTABLE: Las retroalimentaciones clínicas son '
        'append-only. No se permite modificar el registro id=%. Para corregir, registre '
        'una nueva retroalimentación a través del formulario de RF-72. '
        'Requerimiento RF-106, Restricción 3 (RF-72 es append-only).',
        OLD.id_retroalimentacion_feedback
    USING ERRCODE = 'insufficient_privilege';
END;
