--
-- Name: fn_trg_m08_06_retroalimentacion_conflicto_detector(); Type: FUNCTION; Schema: modulo8; Owner: postgres
--

CREATE FUNCTION modulo8.fn_trg_m08_06_retroalimentacion_conflicto_detector() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_conflicto_detectado BOOLEAN := FALSE;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM   modulo8.retroalimentacion_feedback
        WHERE  id_historial_clinico            = NEW.id_historial_clinico
          AND  estado IS DISTINCT FROM          NEW.estado
          AND  id_retroalimentacion_feedback IS DISTINCT FROM NEW.id_retroalimentacion_feedback
    ) INTO v_conflicto_detectado;

    IF v_conflicto_detectado THEN
        NEW.tiene_conflicto := TRUE;

        UPDATE modulo8.retroalimentacion_feedback
        SET    tiene_conflicto = TRUE
        WHERE  id_historial_clinico = NEW.id_historial_clinico
          AND  estado IS DISTINCT FROM NEW.estado;
    ELSE
        NEW.tiene_conflicto := FALSE;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo8.fn_trg_m08_06_retroalimentacion_conflicto_detector() OWNER TO postgres;

--
-- Name: FUNCTION fn_trg_m08_06_retroalimentacion_conflicto_detector(); Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON FUNCTION modulo8.fn_trg_m08_06_retroalimentacion_conflicto_detector() IS 'Detecta conflictos entre retroalimentaciones del mismo historial clínico con distintos estados. Actualiza tiene_conflicto=TRUE en la nueva fila y en las previas en conflicto. Garantiza consistencia del flag usado en el cálculo de TVCO en RF-106 Restricción 6.';


--
-- Name: fn_trg_m08_07_historial_clinico_fechas_consistencia(); Type: FUNCTION; Schema: modulo8; Owner: postgres
--

CREATE FUNCTION modulo8.fn_trg_m08_07_historial_clinico_fechas_consistencia() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.fecha_inicio > NEW.fecha_fin THEN
        RAISE EXCEPTION
            '[TGR-M08-07] HISTORIAL_FECHAS_INVERTIDAS: fecha_inicio (%) no puede ser '
            'posterior a fecha_fin (%) en id_historial_clinicos=%. Un rango invertido '
            'produciría resultados vacíos e invalidaría la línea de tiempo clínica. '
            'Requerimiento RF-106, Restricción 2.',
            NEW.fecha_inicio, NEW.fecha_fin, NEW.id_historial_clinicos
        USING ERRCODE = 'check_violation';
    END IF;

    IF (NEW.fecha_fin - NEW.fecha_inicio) > 730 THEN
        RAISE EXCEPTION
            '[TGR-M08-07] HISTORIAL_RANGO_EXCEDIDO: El rango entre fecha_inicio (%) y '
            'fecha_fin (%) supera los 24 meses permitidos (% días) en id_historial_clinicos=%. '
            'Para historiales más largos, el Veterinario debe seleccionar un subrango. '
            'Requerimiento RF-106, Restricción 2 (rango máximo de 24 meses).',
            NEW.fecha_inicio, NEW.fecha_fin, (NEW.fecha_fin - NEW.fecha_inicio), NEW.id_historial_clinicos
        USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.procentaje_probabilidad < 0 OR NEW.procentaje_probabilidad > 100 THEN
        RAISE EXCEPTION
            '[TGR-M08-07] HISTORIAL_PROBABILIDAD_INVALIDA: procentaje_probabilidad (%) '
            'debe estar entre 0 y 100 en id_historial_clinicos=%. '
            'Requerimiento RF-106, integridad de datos del historial clínico.',
            NEW.procentaje_probabilidad, NEW.id_historial_clinicos
        USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo8.fn_trg_m08_07_historial_clinico_fechas_consistencia() OWNER TO postgres;

--
-- Name: FUNCTION fn_trg_m08_07_historial_clinico_fechas_consistencia(); Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON FUNCTION modulo8.fn_trg_m08_07_historial_clinico_fechas_consistencia() IS 'Valida coherencia de rango de fechas en historiales clínicos: fecha_inicio <= fecha_fin y rango máximo de 24 meses (730 días). También valida que procentaje_probabilidad esté entre 0 y 100. Cubre Restricción 2 de RF-106.';


--
-- Name: fn_trg_m08_08_accion_critica_log_inmutable(); Type: FUNCTION; Schema: modulo8; Owner: postgres
--

CREATE FUNCTION modulo8.fn_trg_m08_08_accion_critica_log_inmutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION
            '[TGR-M08-08] AUDIT_LOG_INMUTABLE: El registro de auditoría de acción crítica '
            '(id=%) no puede ser modificado. Los logs de auditoría son registros forenses '
            'inmutables. Operación bloqueada: UPDATE. '
            'Requerimiento RF-107 Postcondiciones y RF-104 CA-15.',
            OLD.id_accion_critica_log
        USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION
            '[TGR-M08-08] AUDIT_LOG_INMUTABLE: El registro de auditoría de acción crítica '
            '(id=%) no puede ser eliminado. Los logs de auditoría son registros forenses '
            'inmutables. Operación bloqueada: DELETE. '
            'Requerimiento RF-107 Postcondiciones y RF-104 CA-15.',
            OLD.id_accion_critica_log
        USING ERRCODE = 'insufficient_privilege';
    END IF;

    RETURN OLD;
END;
$$;


ALTER FUNCTION modulo8.fn_trg_m08_08_accion_critica_log_inmutable() OWNER TO postgres;

--
-- Name: FUNCTION fn_trg_m08_08_accion_critica_log_inmutable(); Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON FUNCTION modulo8.fn_trg_m08_08_accion_critica_log_inmutable() IS 'Protege la inmutabilidad de la bitácora de auditoría de acciones críticas. Bloquea UPDATE y DELETE en acciones_critica_log. Solo INSERT permitido. Cubre la trazabilidad forense requerida por RF-107 Postcondiciones y RF-104 CA-15.';


--
-- Name: fn_trg_m08_09_accion_critica_requiere_confirmacion_consistencia(); Type: FUNCTION; Schema: modulo8; Owner: postgres
--

CREATE FUNCTION modulo8.fn_trg_m08_09_accion_critica_requiere_confirmacion_consistencia() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.requiere_confirmacion = TRUE
       AND NEW.resultado_operacion IS NOT NULL
       AND NEW.resultado_operacion::TEXT <> 'EN_CURSO'
       AND NEW.confirmacion IS NULL
    THEN
        RAISE EXCEPTION
            '[TGR-M08-09] ACCION_CRITICA_SIN_CONFIRMACION: La acción crítica tipo=% '
            '(id_operacion=%) requiere confirmacion explícita pero fue registrada sin el '
            'campo confirmacion. Posible bypass del modal de confirmación. '
            'Requerimiento RF-107, Sección 8.1 (fuente de verdad única de requiere_confirmacion).',
            NEW.tipo_accion, NEW.id_operacion
        USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo8.fn_trg_m08_09_accion_critica_requiere_confirmacion_consistencia() OWNER TO postgres;

--
-- Name: FUNCTION fn_trg_m08_09_accion_critica_requiere_confirmacion_consistencia(); Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON FUNCTION modulo8.fn_trg_m08_09_accion_critica_requiere_confirmacion_consistencia() IS 'Valida que toda acción crítica con requiere_confirmacion=TRUE tenga el campo confirmacion definido al registrar resultado final. Detecta bypasses del modal de confirmación en RF-107 Sección 8.1. Solo aplica a operaciones con resultado distinto de EN_CURSO.';


--
-- Name: fn_trg_m08_10_widget_posicion_no_negativa(); Type: FUNCTION; Schema: modulo8; Owner: postgres
--

CREATE FUNCTION modulo8.fn_trg_m08_10_widget_posicion_no_negativa() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.posicion_x < 0 THEN
        RAISE EXCEPTION
            '[TGR-M08-10] WIDGET_POSICION_INVALIDA: posicion_x (%) no puede ser negativa '
            'en id_widget_dashboard=%. Un widget con posición negativa queda fuera de la '
            'pantalla. Requerimiento RF-103, integridad geométrica de widgets.',
            NEW.posicion_x, NEW.id_widget_dashboard
        USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.posicion_y < 0 THEN
        RAISE EXCEPTION
            '[TGR-M08-10] WIDGET_POSICION_INVALIDA: posicion_y (%) no puede ser negativa '
            'en id_widget_dashboard=%. Un widget con posición negativa queda fuera de la '
            'pantalla. Requerimiento RF-103, integridad geométrica de widgets.',
            NEW.posicion_y, NEW.id_widget_dashboard
        USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.ancho < 1 THEN
        RAISE EXCEPTION
            '[TGR-M08-10] WIDGET_DIMENSION_INVALIDA: ancho (%) debe ser al menos 1 unidad '
            'de grid en id_widget_dashboard=%. Un widget con ancho=0 es invisible en el '
            'dashboard. Requerimiento RF-103, integridad geométrica de widgets.',
            NEW.ancho, NEW.id_widget_dashboard
        USING ERRCODE = 'check_violation';
    END IF;

    IF NEW.alto < 1 THEN
        RAISE EXCEPTION
            '[TGR-M08-10] WIDGET_DIMENSION_INVALIDA: alto (%) debe ser al menos 1 unidad '
            'de grid en id_widget_dashboard=%. Un widget con alto=0 es invisible en el '
            'dashboard. Requerimiento RF-103, integridad geométrica de widgets.',
            NEW.alto, NEW.id_widget_dashboard
        USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo8.fn_trg_m08_10_widget_posicion_no_negativa() OWNER TO postgres;

--
-- Name: FUNCTION fn_trg_m08_10_widget_posicion_no_negativa(); Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON FUNCTION modulo8.fn_trg_m08_10_widget_posicion_no_negativa() IS 'Valida integridad geométrica de widgets en el dashboard: posicion_x/y >= 0, ancho/alto >= 1. Previene widgets invisibles o fuera de pantalla. Cubre RF-103 configuración de widgets del dashboard operativo por rol.';


--
-- Name: fn_trg_m08_11_auditoria_reporte_estado_valido(); Type: FUNCTION; Schema: modulo8; Owner: postgres
--

CREATE FUNCTION modulo8.fn_trg_m08_11_auditoria_reporte_estado_valido() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.estado_final IS NOT NULL
       AND NEW.estado_final NOT IN ('GENERADO', 'EN_PROCESO', 'FALLIDO', 'CANCELADO', 'EXPIRADO')
    THEN
        RAISE EXCEPTION
            '[TGR-M08-11] AUDITORIA_ESTADO_INVALIDO: estado_final="%" no es un valor válido. '
            'Valores permitidos: GENERADO, EN_PROCESO, FALLIDO, CANCELADO, EXPIRADO. '
            '(id_auditoria_reporte=%). La columna es VARCHAR sin ENUM; la BD actúa como '
            'guardián del dominio. Requerimiento RF-104, Salida (ciclo de vida del reporte).',
            NEW.estado_final, NEW.id_auditoria_reporte
        USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo8.fn_trg_m08_11_auditoria_reporte_estado_valido() OWNER TO postgres;

--
-- Name: FUNCTION fn_trg_m08_11_auditoria_reporte_estado_valido(); Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON FUNCTION modulo8.fn_trg_m08_11_auditoria_reporte_estado_valido() IS 'Valida que estado_final en auditorias_reportes pertenezca al dominio definido en RF-104: GENERADO, EN_PROCESO, FALLIDO, CANCELADO, EXPIRADO. Cubre la integridad del ciclo de vida de reportes ante el uso de VARCHAR sin ENUM.';


--
-- Name: fn_trg_m08_12_snapshot_kpi_fecha_no_futura(); Type: FUNCTION; Schema: modulo8; Owner: postgres
--

CREATE FUNCTION modulo8.fn_trg_m08_12_snapshot_kpi_fecha_no_futura() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.fecha_calculo > (NOW() + INTERVAL '5 minutes') THEN
        RAISE EXCEPTION
            '[TGR-M08-12] SNAPSHOT_FECHA_FUTURA: fecha_calculo (%) es una fecha futura. '
            'Los snapshots de KPI solo pueden registrarse para el momento actual o pasado. '
            'Tolerancia de 5 minutos para compensar latencias de procesamiento. '
            'id_snapshot_kpi=%. Requerimiento RF-103, integridad temporal de snapshots.',
            NEW.fecha_calculo, NEW.id_snapshot_kpi
        USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo8.fn_trg_m08_12_snapshot_kpi_fecha_no_futura() OWNER TO postgres;

--
-- Name: FUNCTION fn_trg_m08_12_snapshot_kpi_fecha_no_futura(); Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON FUNCTION modulo8.fn_trg_m08_12_snapshot_kpi_fecha_no_futura() IS 'Impide el registro de snapshots de KPI con fecha_calculo en el futuro. Un snapshot representa el estado medido en un momento pasado o presente. Tolerancia de 5 minutos para compensar latencias de procesamiento. Cubre RF-103.';


--
-- Name: sp_desactivar_especie(integer, integer); Type: PROCEDURE; Schema: modulo9; Owner: postgres
--

CREATE PROCEDURE modulo9.sp_desactivar_especie(IN p_id_usuario integer, IN p_id_especie integer)
    LANGUAGE plpgsql
    AS $$
	DECLARE
	    v_es_admin BOOLEAN;
	    v_id_umbral_actual INT;
	BEGIN
	    -- 1. Validar que el usuario sea Administrador
	    SELECT EXISTS (
	        SELECT 1 FROM modulo1.usuarios u
	        JOIN modulo1.roles r ON u.id_rol = r.id_rol
	        WHERE u.id_usuario = p_id_usuario AND r.nombre_rol ILIKE '%Administrador%'
	    ) INTO v_es_admin;

	    IF NOT v_es_admin THEN
	        RAISE EXCEPTION 'Acceso denegado: Solo el rol Administrador puede desactivar especies.';
	    END IF;

	    -- Validar existencia
	    IF NOT EXISTS (SELECT 1 FROM modulo9.especies WHERE id_especie = p_id_especie) THEN
	        RAISE EXCEPTION 'La especie a desactivar no existe.';
	    END IF;

	    -- 2. Validar que no haya procesos críticos activos (Entrenamiento de modelos IA, etc. RF-15)
	    -- Nota: Se simula la validación consultando si hay activos biológicos en estado crítico o activo.
	    IF EXISTS (SELECT 1 FROM modulo2.activos_biologicos WHERE id_especie = p_id_especie AND id_estado = (SELECT id_estado_activo_biologico FROM modulo2.estados_activos_biologicos WHERE nombre ILIKE '%ACTIVO%' LIMIT 1)) THEN
	        RAISE EXCEPTION 'Operación rechazada: No se puede desactivar la especie porque existen activos biológicos vinculados en estado activo.';
	    END IF;

	    UPDATE modulo9.especies
	    SET es_activo = FALSE,
	        fecha_actualizacion = CURRENT_TIMESTAMP
	    WHERE id_especie = p_id_especie;

	    -- 3. Registro en auditoría
	    SELECT id_umbral_ambiental INTO v_id_umbral_actual
	    FROM modulo9.umbrales_ambientales WHERE id_especie = p_id_especie LIMIT 1;

	    INSERT INTO modulo9.gestion_especies (
	        id_usuario, id_especie, fecha_gestion, id_umbral_ambiental
	    ) VALUES (
	        p_id_usuario, p_id_especie, CURRENT_TIMESTAMP, COALESCE(v_id_umbral_actual, 1)
	    );

	EXCEPTION
	    WHEN OTHERS THEN
	        RAISE;
	END;
	$$;


ALTER PROCEDURE modulo9.sp_desactivar_especie(IN p_id_usuario integer, IN p_id_especie integer) OWNER TO postgres;

--
-- Name: sp_editar_especie(integer, integer, character varying, character varying, timestamp without time zone); Type: PROCEDURE; Schema: modulo9; Owner: postgres
--

CREATE PROCEDURE modulo9.sp_editar_especie(IN p_id_usuario integer, IN p_id_especie integer, IN p_nuevo_nombre character varying, IN p_nueva_descripcion character varying, IN p_fecha_verificacion timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
	DECLARE
	    v_tiene_permiso BOOLEAN;
	    v_nombre_actual VARCHAR;
	    v_desc_actual VARCHAR;
	    v_fecha_actual TIMESTAMP;
	BEGIN
	    -- 1. Validar rol Administrador o Ingeniero de Campo (RF-15)
	    SELECT EXISTS (
	        SELECT 1 FROM modulo1.usuarios u
	        JOIN modulo1.roles r ON u.id_rol = r.id_rol
	        WHERE u.id_usuario = p_id_usuario
	        AND (r.nombre_rol ILIKE '%Administrador%' OR r.nombre_rol ILIKE '%Ingeniero de Campo%')
	    ) INTO v_tiene_permiso;

	    IF NOT v_tiene_permiso THEN
	        RAISE EXCEPTION 'Acceso denegado: Solo el Administrador o el Ingeniero de Campo pueden editar especies.';
	    END IF;

	    -- 2. Validar existencia y control de concurrencia
	    SELECT nombre, descripcion, fecha_actualizacion
	    INTO v_nombre_actual, v_desc_actual, v_fecha_actual
	    FROM modulo9.especies
	    WHERE id_especie = p_id_especie;

	    IF v_nombre_actual IS NULL THEN
	        RAISE EXCEPTION 'La especie a editar no existe.';
	    END IF;

	    -- Control de concurrencia optimista (RF-15)
	    IF COALESCE(v_fecha_actual, '1900-01-01'::TIMESTAMP) != COALESCE(p_fecha_verificacion, '1900-01-01'::TIMESTAMP) THEN
	        RAISE EXCEPTION 'Conflicto de concurrencia: El registro ha sido modificado por otro usuario. Por favor, recargue los datos.';
	    END IF;

	    -- 3. Detectar si hay cambios reales
	    IF TRIM(v_nombre_actual) = TRIM(p_nuevo_nombre) AND TRIM(COALESCE(v_desc_actual, '')) = TRIM(COALESCE(p_nueva_descripcion, '')) THEN
	        RETURN; -- No hay cambios, salimos
	    END IF;

	    -- Validar longitud del nombre si se envió
	    IF p_nuevo_nombre IS NOT NULL THEN
	        IF LENGTH(p_nuevo_nombre) < 3 OR LENGTH(p_nuevo_nombre) > 50 THEN
	            RAISE EXCEPTION 'El nombre de la especie debe tener entre 3 y 50 caracteres.';
	        END IF;

	        -- Validar unicidad excluyendo la especie actual
	        IF EXISTS (SELECT 1 FROM modulo9.especies
	                   WHERE LOWER(nombre) = LOWER(p_nuevo_nombre)
	                   AND id_especie != p_id_especie) THEN
	            RAISE EXCEPTION 'La especie % ya se encuentra registrada por otro identificador.', p_nuevo_nombre;
	        END IF;
	    END IF;

	    -- 4. Actualizar especie
	    UPDATE modulo9.especies
	    SET nombre = COALESCE(p_nuevo_nombre, nombre),
	        descripcion = COALESCE(p_nueva_descripcion, descripcion),
	        fecha_actualizacion = CURRENT_TIMESTAMP
	    WHERE id_especie = p_id_especie;

	    -- 5. Registro en auditoría central con OLD/NEW (RF-10)
	    CALL modulo1.sp_registrar_auditoria(
	        p_id_usuario,
	        NULL,
	        2, -- Tipo evento: ACTUALIZACION
	        'Modulo 9',
	        'CATALOGOS',
	        'Actualización de datos de la especie: ' || v_nombre_actual,
	        'exitoso',
	        'ACTIVO',
	        jsonb_build_object(
	            'old_data', jsonb_build_object('nombre', v_nombre_actual, 'descripcion', v_desc_actual),
	            'new_data', jsonb_build_object('nombre', p_nuevo_nombre, 'descripcion', p_nueva_descripcion)
	        )
	    );

	EXCEPTION
	    WHEN OTHERS THEN
	        RAISE;
	END;
	$$;


ALTER PROCEDURE modulo9.sp_editar_especie(IN p_id_usuario integer, IN p_id_especie integer, IN p_nuevo_nombre character varying, IN p_nueva_descripcion character varying, IN p_fecha_verificacion timestamp without time zone) OWNER TO postgres;

--
-- Name: sp_registrar_especie_inactiva(integer, character varying, character varying); Type: PROCEDURE; Schema: modulo9; Owner: postgres
--

CREATE PROCEDURE modulo9.sp_registrar_especie_inactiva(IN p_id_usuario integer, IN p_nombre character varying, IN p_descripcion character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_especie        INT;
    v_id_umbral_defecto INT;
    v_es_admin          BOOLEAN;
BEGIN
    -- Validar rol
    SELECT EXISTS (
        SELECT 1
        FROM modulo1.usuarios u
        JOIN modulo1.roles r ON u.id_rol = r.id_rol
        WHERE u.id_usuario = p_id_usuario
          AND r.nombre_rol ILIKE '%Administrador%'
    ) INTO v_es_admin;

    IF NOT v_es_admin THEN
        RAISE EXCEPTION 'Acceso denegado';
    END IF;

    -- Validaciones
    IF LENGTH(TRIM(p_nombre)) < 3 OR LENGTH(TRIM(p_nombre)) > 50 THEN
        RAISE EXCEPTION 'Nombre inválido';
    END IF;

    IF EXISTS (
        SELECT 1 FROM modulo9.especies
        WHERE LOWER(nombre) = LOWER(TRIM(p_nombre))
    ) THEN
        RAISE EXCEPTION 'La especie ya existe';
    END IF;

    PERFORM set_config('app.usuario_id', p_id_usuario::TEXT, TRUE);

    -- INSERT INACTIVO
    INSERT INTO modulo9.especies (
        nombre,
        descripcion,
        fecha_creacion,
        fecha_actualizacion,
        es_activo
    )
    VALUES (
        TRIM(p_nombre),
        TRIM(p_descripcion),
        CURRENT_TIMESTAMP,
        CURRENT_TIMESTAMP,
        FALSE
    )
    RETURNING id_especie INTO v_id_especie;

    -- Auditoría
    CALL modulo1.sp_registrar_auditoria(
        p_id_usuario,
        NULL,
        1,
        'Modulo 9',
        'CATALOGOS',
        'Registro especie INACTIVA: ' || TRIM(p_nombre),
        'exitoso',
        'INACTIVO',
        jsonb_build_object(
            'id_especie', v_id_especie,
            'estado', 'INACTIVO'
        )
    );

    -- Gestión (igual que el otro)
    SELECT id_umbral_ambiental
    INTO v_id_umbral_defecto
    FROM modulo9.umbrales_ambientales
    LIMIT 1;

    INSERT INTO modulo9.gestion_especies (
        id_usuario,
        id_especie,
        fecha_gestion,
        id_umbral_ambiental
    )
    VALUES (
        p_id_usuario,
        v_id_especie,
        CURRENT_TIMESTAMP,
        v_id_umbral_defecto
    );

END;
$$;


ALTER PROCEDURE modulo9.sp_registrar_especie_inactiva(IN p_id_usuario integer, IN p_nombre character varying, IN p_descripcion character varying) OWNER TO postgres;

--
-- Name: sp_registrar_infraestructura(integer, character varying, character varying, integer, numeric, modulo9.enum_tipo_infraestructura); Type: PROCEDURE; Schema: modulo9; Owner: postgres
--

CREATE PROCEDURE modulo9.sp_registrar_infraestructura(IN p_id_usuario integer, IN p_nombre character varying, IN p_descripcion character varying, IN p_id_finca integer, IN p_superficie numeric, IN p_tipo modulo9.enum_tipo_infraestructura)
    LANGUAGE plpgsql
    AS $$
	DECLARE
	    v_es_admin BOOLEAN;
	BEGIN
	    -- 1. Validar que el usuario sea Administrador (RF-20)
	    SELECT EXISTS (
	        SELECT 1 FROM modulo1.usuarios u
	        JOIN modulo1.roles r ON u.id_rol = r.id_rol
	        WHERE u.id_usuario = p_id_usuario AND r.nombre_rol ILIKE '%Administrador%'
	    ) INTO v_es_admin;

	    IF NOT v_es_admin THEN
	        RAISE EXCEPTION 'Acceso denegado: Solo el rol Administrador puede registrar infraestructuras.';
	    END IF;

	    -- 2. Validar existencia de finca
	    IF NOT EXISTS (SELECT 1 FROM modulo9.fincas WHERE id_finca = p_id_finca) THEN
	        RAISE EXCEPTION 'La finca asociada no existe en el sistema.';
	    END IF;

	    -- 3. Validar unicidad del nombre dentro de la misma finca (RF-20)
	    IF EXISTS (SELECT 1 FROM modulo9.infraestructuras WHERE id_finca = p_id_finca AND LOWER(nombre) = LOWER(p_nombre)) THEN
	        RAISE EXCEPTION 'Conflicto: Ya existe una infraestructura con el nombre % en esta finca.', p_nombre;
	    END IF;

	    -- Validar superficie positiva
	    IF p_superficie <= 0 THEN
	        RAISE EXCEPTION 'La superficie debe ser mayor a cero.';
	    END IF;

	    INSERT INTO modulo9.infraestructuras (
	        nombre, descripcion, id_finca, superficie, es_activo, tipo
	    ) VALUES (
	        TRIM(p_nombre), TRIM(p_descripcion), p_id_finca, p_superficie, TRUE, p_tipo
	    );

	    -- 4. Registro en auditoría general (Usando el procedimiento del Módulo 1 si está disponible)
	    -- En este entorno, insertamos directamente en eventos si es necesario, o llamamos al SP.
	    -- Para este entregable, invocamos el procedimiento de auditoría del Módulo 1.
	    CALL modulo1.sp_registrar_auditoria(
	        p_id_usuario,
	        NULL, -- p_id_sesion (el backend debe proveerlo, aquí simulamos con NULL o un valor por defecto)
	        5,    -- p_id_tipo_evento (Creación de recurso)
	        'Modulo 9',
	        'Infraestructura',
	        'Registro de nueva infraestructura: ' || p_nombre,
	        'exitoso',
	        'activo',
	        jsonb_build_object('finca', p_id_finca, 'tipo', p_tipo)
	    );

	EXCEPTION
	    WHEN OTHERS THEN
	        RAISE;
	END;
	$$;


ALTER PROCEDURE modulo9.sp_registrar_infraestructura(IN p_id_usuario integer, IN p_nombre character varying, IN p_descripcion character varying, IN p_id_finca integer, IN p_superficie numeric, IN p_tipo modulo9.enum_tipo_infraestructura) OWNER TO postgres;

