--
-- Name: trg_fn_calibracion_dispositivo_activo(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_calibracion_dispositivo_activo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_dispositivo_activo BOOLEAN;
    v_serial             VARCHAR(50);
    v_sensor_activo      BOOLEAN;
BEGIN
    -- Verificar dispositivo
    SELECT es_activo, serial
    INTO   v_dispositivo_activo, v_serial
    FROM   modulo9.dispositivos_iot
    WHERE  id_dispositivo_iot = NEW.id_dispositivo_iot;

    IF v_dispositivo_activo IS NULL THEN
        RAISE EXCEPTION
            'DEVICE_NOT_FOUND: El dispositivo IoT con ID % no existe en el sistema.',
            NEW.id_dispositivo_iot
        USING ERRCODE = 'P0131';
    END IF;

    IF v_dispositivo_activo = FALSE THEN
        RAISE EXCEPTION
            'INACTIVE_DEVICE: No se puede registrar una calibración para el '
            'dispositivo "%" porque está inactivo. Active el dispositivo antes de calibrar.',
            v_serial
        USING ERRCODE = 'P0132';
    END IF;

    -- Verificar que el sensor también esté activo
    SELECT es_activo INTO v_sensor_activo
    FROM   modulo9.sensores
    WHERE  id_sensores = NEW.id_sensor;   -- ← CORREGIDO: id_sensores

    IF v_sensor_activo IS NULL THEN
        RAISE EXCEPTION
            'SENSOR_NOT_FOUND: El sensor con ID % no existe en el sistema.',
            NEW.id_sensor
        USING ERRCODE = 'P0133';
    END IF;

    IF v_sensor_activo = FALSE THEN
        RAISE EXCEPTION
            'INACTIVE_SENSOR: No se puede registrar una calibración para el '
            'sensor ID % porque está inactivo. Active el sensor antes de calibrar.',
            NEW.id_sensor
        USING ERRCODE = 'P0133';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_calibracion_dispositivo_activo() OWNER TO postgres;

--
-- Name: trg_fn_ciclos_biologicos_duracion_valida(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_ciclos_biologicos_duracion_valida() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.duracion_dias IS NULL OR NEW.duracion_dias <= 0 THEN
        RAISE EXCEPTION 'INVALID_DURATION: La duración de la etapa debe ser un número entero positivo mayor a 0. Valor recibido: %.',
            NEW.duracion_dias
            USING ERRCODE = 'P0105';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_ciclos_biologicos_duracion_valida() OWNER TO postgres;

--
-- Name: trg_fn_ciclos_biologicos_no_desactivar_en_uso(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_ciclos_biologicos_no_desactivar_en_uso() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ciclos  INTEGER;
    v_activos INTEGER;
BEGIN
    IF OLD.es_activo = TRUE AND NEW.es_activo = FALSE THEN
        -- Verificación 1: ciclos productivos directos
        SELECT COUNT(*) INTO v_ciclos
        FROM modulo9.ciclos_productivos_biologicos
        WHERE id_ciclo_biologico = OLD.id_ciclo_biologico;

        -- Verificación 2: activos biológicos activos cuyas fases activas apunten a ciclos productivos vinculados a esta etapa
        SELECT COUNT(DISTINCT gf.id_activo_biologico) INTO v_activos
        FROM modulo2.gestiones_fases gf
        JOIN modulo9.ciclos_productivos_biologicos cpb ON cpb.id_ciclo_productivo = gf.id_ciclo_productiva
        WHERE cpb.id_ciclo_biologico = OLD.id_ciclo_biologico
          AND gf.es_activa = TRUE;

        IF v_ciclos > 0 OR v_activos > 0 THEN
            RAISE EXCEPTION
                'STAGE_IN_USE: No se puede desactivar la etapa "%" porque tiene '
                '% ciclo(s) productivo(s) y % activo(s) biológico(s) actualmente en esta fase.',
                OLD.nombre, v_ciclos, v_activos
            USING ERRCODE = 'P0106';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_ciclos_biologicos_no_desactivar_en_uso() OWNER TO postgres;

--
-- Name: trg_fn_ciclos_biologicos_nombre_unique_ci(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_ciclos_biologicos_nombre_unique_ci() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_count
    FROM modulo9.ciclos_biologicos
    WHERE LOWER(TRIM(nombre)) = LOWER(TRIM(NEW.nombre))
      AND id_especie          = NEW.id_especie
      AND id_ciclo_biologico <> COALESCE(NEW.id_ciclo_biologico, -1);

    IF v_count > 0 THEN
        RAISE EXCEPTION 'DUPLICATE_STAGE: Ya existe una etapa llamada "%" para esta especie. Los nombres de etapa deben ser únicos por especie (case-insensitive).',
            NEW.nombre
            USING ERRCODE = 'P0104';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_ciclos_biologicos_nombre_unique_ci() OWNER TO postgres;

--
-- Name: trg_fn_configuracion_global_heartbeat_valido(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_configuracion_global_heartbeat_valido() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.frecuencia_muestreo IS NULL OR NEW.frecuencia_muestreo <= 0 THEN
        RAISE EXCEPTION 'INVALID_CONFIG: La frecuencia de muestreo debe ser un entero positivo mayor a 0. Valor recibido: %.',
            NEW.frecuencia_muestreo
            USING ERRCODE = 'P0116';
    END IF;

    IF NEW.heartbeat IS NULL OR NEW.heartbeat <= 0 THEN
        RAISE EXCEPTION 'INVALID_CONFIG: El heartbeat debe ser un entero positivo mayor a 0. Valor recibido: %.',
            NEW.heartbeat
            USING ERRCODE = 'P0116';
    END IF;

    IF NEW.heartbeat < NEW.frecuencia_muestreo THEN
        RAISE EXCEPTION 'INVALID_CONFIG: El heartbeat (%) debe ser mayor o igual a la frecuencia de muestreo (%). No puede esperarse una señal antes del intervalo de envío.',
            NEW.heartbeat, NEW.frecuencia_muestreo
            USING ERRCODE = 'P0117';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_configuracion_global_heartbeat_valido() OWNER TO postgres;

--
-- Name: trg_fn_configuracion_global_unicidad(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_configuracion_global_unicidad() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    IF NEW.es_activo = TRUE THEN
        SELECT COUNT(*) INTO v_count
        FROM modulo9.configuraciones_globales
        WHERE es_activo = TRUE
          AND id_configuracion_global <> COALESCE(NEW.id_configuracion_global, -1);

        IF v_count > 0 THEN
            RAISE EXCEPTION
                'DUPLICATE_GLOBAL_CONFIG: Ya existe una configuración global activa. '
                'Actualice la configuración vigente en lugar de crear una nueva.'
            USING ERRCODE = 'P0115';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_configuracion_global_unicidad() OWNER TO postgres;

--
-- Name: trg_fn_configuracion_remota_sin_pendiente(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_configuracion_remota_sin_pendiente() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_count
    FROM modulo9.configuraciones_remotas
    WHERE id_dispositivo_iot = NEW.id_dispositivo_iot
      AND estado             = 'PENDIENTE';

    IF v_count > 0 THEN
        RAISE EXCEPTION 'PENDING_CONFIG_EXISTS: Ya existe una configuración PENDIENTE para el dispositivo ID %. Espere a que se aplique o cancélela antes de enviar una nueva.',
            NEW.id_dispositivo_iot
            USING ERRCODE = 'P0139';
    END IF;

    RETURN NEW;
END;
$$;


