--
-- Name: trg_fn_configuracion_remota_tiempos_validos(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_configuracion_remota_tiempos_validos() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.frecuencia_captura IS NULL OR NEW.frecuencia_captura <= 0 THEN
        RAISE EXCEPTION 'INVALID_CONFIG: La frecuencia de captura debe ser un entero positivo mayor a 0. Valor recibido: %.',
            NEW.frecuencia_captura
            USING ERRCODE = 'P0137';
    END IF;

    IF NEW.intervalo_transmision IS NULL OR NEW.intervalo_transmision <= 0 THEN
        RAISE EXCEPTION 'INVALID_CONFIG: El intervalo de transmisión debe ser un entero positivo mayor a 0. Valor recibido: %.',
            NEW.intervalo_transmision
            USING ERRCODE = 'P0137';
    END IF;

    IF NEW.intervalo_transmision < NEW.frecuencia_captura THEN
        RAISE EXCEPTION 'INVALID_CONFIG: El intervalo de transmisión (%) no puede ser menor a la frecuencia de captura (%). No se puede transmitir antes de capturar.',
            NEW.intervalo_transmision, NEW.frecuencia_captura
            USING ERRCODE = 'P0138';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_configuracion_remota_tiempos_validos() OWNER TO postgres;

--
-- Name: trg_fn_dispositivo_no_delete_con_historial(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_dispositivo_no_delete_con_historial() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_calibraciones   INTEGER;
    v_configuraciones INTEGER;
    v_sensores        INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_calibraciones
    FROM modulo9.calibraciones
    WHERE id_dispositivo_iot = OLD.id_dispositivo_iot;

    SELECT COUNT(*) INTO v_configuraciones
    FROM modulo9.configuraciones_remotas
    WHERE id_dispositivo_iot = OLD.id_dispositivo_iot;

    SELECT COUNT(*) INTO v_sensores
    FROM modulo9.sensores
    WHERE id_dispositivo_iot = OLD.id_dispositivo_iot;

    IF v_calibraciones > 0 OR v_configuraciones > 0 OR v_sensores > 0 THEN
        RAISE EXCEPTION 'DEVICE_HAS_HISTORY: El dispositivo con serial "%" tiene datos históricos asociados (% calibración(es), % configuración(es), % sensor(es)). Use la desactivación lógica (es_activo = false).',
            OLD.serial, v_calibraciones, v_configuraciones, v_sensores
            USING ERRCODE = 'P0129';
    END IF;

    RAISE EXCEPTION 'NO_PHYSICAL_DELETE: Los dispositivos IoT no pueden eliminarse físicamente. Use la desactivación lógica (es_activo = false). Serial: "%".',
        OLD.serial
        USING ERRCODE = 'P0129';

    RETURN NULL;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_dispositivo_no_delete_con_historial() OWNER TO postgres;

