CREATE FUNCTION modulo9.trg_fn_dispositivo_serial_unique() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_count
    FROM modulo9.dispositivos_iot
    WHERE TRIM(serial) = TRIM(NEW.serial);

    IF v_count > 0 THEN
        RAISE EXCEPTION 'DUPLICATE_SERIAL: El número de serie "%" ya está registrado en el sistema. Cada dispositivo físico debe tener un único registro.',
            NEW.serial
            USING ERRCODE = 'P0128';
    END IF;

    RETURN NEW;
END;
$$;


