--
-- Name: trg_fn_especies_audit(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_especies_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_tipo_operacion       TEXT;
    v_valores_anteriores   JSONB;
    v_valores_nuevos       JSONB;
    v_id_usuario           INT4;
BEGIN

    -- -------------------------------------------------------------------------
    -- Obtener el id_usuario desde la variable de sesión que provee el backend.
    -- El backend debe ejecutar antes de cada operación:
    --   SET LOCAL app.usuario_id = '<id>';
    -- -------------------------------------------------------------------------
    BEGIN
        v_id_usuario := current_setting('app.usuario_id')::INT4;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION
            '[AUDIT-ESPECIES] No se encontró app.usuario_id en la sesión. '
            'El backend debe establecer esta variable antes de operar sobre especies.';
    END;

    -- -------------------------------------------------------------------------
    -- Determinar tipo de operación y construir snapshots
    -- -------------------------------------------------------------------------
    IF TG_OP = 'INSERT' THEN
        v_tipo_operacion     := 'CREATE';
        v_valores_anteriores := NULL;
        v_valores_nuevos     := jsonb_build_object(
            'id_especie',          NEW.id_especie,
            'nombre',              NEW.nombre,
            'descripcion',         NEW.descripcion,
            'es_activo',           NEW.es_activo,
            'fecha_creacion',      NEW.fecha_creacion
        );

    ELSIF TG_OP = 'UPDATE' THEN
        IF OLD.es_activo = TRUE AND NEW.es_activo = FALSE THEN
            v_tipo_operacion := 'DEACTIVATE';
        ELSE
            v_tipo_operacion := 'UPDATE';
        END IF;

        v_valores_anteriores := jsonb_build_object(
            'id_especie',          OLD.id_especie,
            'nombre',              OLD.nombre,
            'descripcion',         OLD.descripcion,
            'es_activo',           OLD.es_activo,
            'fecha_actualizacion', OLD.fecha_actualizacion
        );
        v_valores_nuevos := jsonb_build_object(
            'id_especie',          NEW.id_especie,
            'nombre',              NEW.nombre,
            'descripcion',         NEW.descripcion,
            'es_activo',           NEW.es_activo,
            'fecha_actualizacion', NEW.fecha_actualizacion
        );
    END IF;

    -- -------------------------------------------------------------------------
    -- Insertar registro de auditoría
    -- -------------------------------------------------------------------------
    INSERT INTO modulo9.auditorias_especies (
        id_especie,
        id_usuario,
        tipo_operacion,
        valores_anteriores,
        valores_nuevos,
        fecha_gestion
    )
    VALUES (
        COALESCE(NEW.id_especie, OLD.id_especie),
        v_id_usuario,
        v_tipo_operacion,
        v_valores_anteriores,
        v_valores_nuevos,
        now()
    );

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_especies_audit() OWNER TO postgres;

