--
-- Name: trg_fn_especies_nombre_formato(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_especies_nombre_formato() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_longitud INTEGER;
BEGIN
    NEW.nombre := TRIM(NEW.nombre);
    v_longitud  := LENGTH(NEW.nombre);

    IF v_longitud < 3 OR v_longitud > 50 THEN
        RAISE EXCEPTION 'INVALID_FORMAT: El nombre de la especie debe tener entre 3 y 50 caracteres. Longitud recibida: %.',
            v_longitud
            USING ERRCODE = 'P0102';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_especies_nombre_formato() OWNER TO postgres;

--
-- Name: trg_fn_especies_nombre_unique_ci(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_especies_nombre_unique_ci() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_count
    FROM modulo9.especies
    WHERE LOWER(TRIM(nombre)) = LOWER(TRIM(NEW.nombre))
      AND id_especie          <> COALESCE(NEW.id_especie, -1);

    IF v_count > 0 THEN
        RAISE EXCEPTION 'DUPLICATE_SPECIES: Ya existe una especie con el nombre "%" (validación case-insensitive). Use un nombre diferente.',
            NEW.nombre
            USING ERRCODE = 'P0101';
    END IF;

    -- Normalizar: primer carácter en mayúscula, resto en minúscula
    NEW.nombre := INITCAP(TRIM(NEW.nombre));

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_especies_nombre_unique_ci() OWNER TO postgres;

--
-- Name: trg_fn_finca_coordenadas_validas(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_finca_coordenadas_validas() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_lat NUMERIC;
    v_lng NUMERIC;
BEGIN
    -- Validar tamaño de finca
    IF NEW.tamano_h IS NULL OR NEW.tamano_h <= 0 THEN
        RAISE EXCEPTION 'INVALID_SIZE: El tamaño de la finca debe ser un valor numérico positivo mayor a cero. Valor recibido: %.',
            NEW.tamano_h
            USING ERRCODE = 'P0121';
    END IF;

    -- Extraer y validar coordenadas del JSONB
    IF NEW.ubicacion IS NOT NULL THEN
        v_lat := (NEW.ubicacion->>'latitud')::NUMERIC;
        v_lng := (NEW.ubicacion->>'longitud')::NUMERIC;

        IF v_lat IS NOT NULL AND (v_lat < -90 OR v_lat > 90) THEN
            RAISE EXCEPTION 'INVALID_COORDINATES: La latitud debe estar entre -90 y 90. Valor recibido: %.',
                v_lat
                USING ERRCODE = 'P0122';
        END IF;

        IF v_lng IS NOT NULL AND (v_lng < -180 OR v_lng > 180) THEN
            RAISE EXCEPTION 'INVALID_COORDINATES: La longitud debe estar entre -180 y 180. Valor recibido: %.',
                v_lng
                USING ERRCODE = 'P0122';
        END IF;
    END IF;

    RETURN NEW;

EXCEPTION
    WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'INVALID_JSON_COORDINATES: Las coordenadas en el campo ubicacion no tienen formato numérico válido.'
            USING ERRCODE = 'P0123';
END;
$$;


ALTER FUNCTION modulo9.trg_fn_finca_coordenadas_validas() OWNER TO postgres;

--
-- Name: trg_fn_finca_no_delete_con_dependencias(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_finca_no_delete_con_dependencias() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_infra_count   INTEGER;
    v_iot_count     INTEGER;
    v_activos_count INTEGER;
BEGIN
    -- Verificar infraestructuras directamente asociadas a la finca
    SELECT COUNT(*) INTO v_infra_count
    FROM modulo9.infraestructuras
    WHERE id_finca = OLD.id_finca;

    -- Verificar dispositivos IoT a través de infraestructuras
    SELECT COUNT(*) INTO v_iot_count
    FROM modulo9.dispositivos_iot d
    JOIN modulo9.infraestructuras i ON d.id_infraestructura = i.id_infraestructura
    WHERE i.id_finca = OLD.id_finca;

    -- Verificar activos biológicos a través de infraestructuras (CORREGIDO: modulo2, no modulo9)
    SELECT COUNT(*) INTO v_activos_count
    FROM modulo2.activos_biologicos ab
    JOIN modulo9.infraestructuras i ON ab.id_infraestructura = i.id_infraestructura
    WHERE i.id_finca = OLD.id_finca;

    IF v_infra_count > 0 OR v_iot_count > 0 OR v_activos_count > 0 THEN
        RAISE EXCEPTION
            'FARM_HAS_DEPENDENCIES: La finca "%" no puede eliminarse físicamente. '
            'Tiene % infraestructura(s), % dispositivo(s) IoT y % activo(s) '
            'biológico(s) asociado(s). Use la desactivación lógica (es_activo = false).',
            OLD.nombre, v_infra_count, v_iot_count, v_activos_count
        USING ERRCODE = 'P0124';
    END IF;

    -- Bloqueo general aunque no tenga dependencias (política de no eliminación física)
    RAISE EXCEPTION
        'NO_PHYSICAL_DELETE: Las fincas no pueden eliminarse físicamente del sistema. '
        'Use la desactivación lógica (es_activo = false). Finca: "%".',
        OLD.nombre
    USING ERRCODE = 'P0124';

    RETURN NULL;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_finca_no_delete_con_dependencias() OWNER TO postgres;

--
-- Name: trg_fn_finca_nombre_unique(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_finca_nombre_unique() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_count_global    INTEGER;
    v_count_productor INTEGER;
BEGIN
    NEW.nombre := TRIM(NEW.nombre);

    -- Validar formato: solo letras, espacios, acentos y ñ  (operador !~ correcto)
    IF NEW.nombre !~ '^[A-Za-záéíóúÁÉÍÓÚñÑüÜ\s]+$' THEN
        RAISE EXCEPTION
            'INVALID_FORMAT: El nombre de la finca solo permite letras, espacios '
            'y caracteres del español. No se admiten números ni símbolos. Valor: "%".',
            NEW.nombre
        USING ERRCODE = 'P0118';
    END IF;

    -- Validar unicidad global
    SELECT COUNT(*) INTO v_count_global
    FROM modulo9.fincas
    WHERE LOWER(TRIM(nombre)) = LOWER(NEW.nombre)
      AND id_finca <> COALESCE(NEW.id_finca, -1);

    IF v_count_global > 0 THEN
        RAISE EXCEPTION
            'DUPLICATE_FARM_GLOBAL: Ya existe una finca con el nombre "%" '
            'en el sistema (unicidad global).',
            NEW.nombre
        USING ERRCODE = 'P0119';
    END IF;

    -- Validar unicidad por productor
    IF NEW.id_usuario IS NOT NULL THEN
        SELECT COUNT(*) INTO v_count_productor
        FROM modulo9.fincas
        WHERE LOWER(TRIM(nombre)) = LOWER(NEW.nombre)
          AND id_usuario = NEW.id_usuario
          AND id_finca <> COALESCE(NEW.id_finca, -1);

        IF v_count_productor > 0 THEN
            RAISE EXCEPTION
                'DUPLICATE_FARM_PRODUCER: El productor ya tiene una finca '
                'registrada con el nombre "%".',
                NEW.nombre
            USING ERRCODE = 'P0120';
        END IF;
    END IF;

    RETURN NEW;
END;
$_$;


ALTER FUNCTION modulo9.trg_fn_finca_nombre_unique() OWNER TO postgres;

--
-- Name: trg_fn_identidad_visual_audit(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_identidad_visual_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Solo auditoría en UPDATE (ignora INSERT)
    IF TG_OP = 'UPDATE' THEN
        INSERT INTO modulo9.auditorias_visuales (
            id_usuario,
            fecha_creacion,
            valor_anterior,
            valor_nuevo
        )
        VALUES (
            NEW.id_usuario,
            now(),
            jsonb_build_object(
                'logo_path',        OLD.logo_path,
                'primary_color',    OLD.primary_color,
                'secondary_color',  OLD.secondary_color,
                'org_display_name', OLD.org_display_name,
                'version',          OLD.version
            ),
            jsonb_build_object(
                'logo_path',        NEW.logo_path,
                'primary_color',    NEW.primary_color,
                'secondary_color',  NEW.secondary_color,
                'org_display_name', NEW.org_display_name,
                'version',          NEW.version
            )
        );
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_identidad_visual_audit() OWNER TO postgres;

--
-- Name: trg_fn_identidad_visual_colores_validos(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_identidad_visual_colores_validos() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
    IF NEW.primary_color IS NOT NULL
       AND NEW.primary_color !~ '^#[0-9A-Fa-f]{6}$' THEN
        RAISE EXCEPTION
            'INVALID_COLOR: El color primario "%" no tiene formato hexadecimal '
            'válido (#RRGGBB de 6 dígitos).',
            NEW.primary_color
        USING ERRCODE = 'P0135';
    END IF;

    IF NEW.secondary_color IS NOT NULL
       AND NEW.secondary_color !~ '^#[0-9A-Fa-f]{6}$' THEN
        RAISE EXCEPTION
            'INVALID_COLOR: El color secundario "%" no tiene formato hexadecimal '
            'válido (#RRGGBB de 6 dígitos).',
            NEW.secondary_color
        USING ERRCODE = 'P0135';
    END IF;

    RETURN NEW;
END;
$_$;


ALTER FUNCTION modulo9.trg_fn_identidad_visual_colores_validos() OWNER TO postgres;

--
-- Name: trg_fn_infraestructura_no_desactivar_en_uso(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_infraestructura_no_desactivar_en_uso() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_dispositivos INTEGER;
    v_sensores     INTEGER;
BEGIN
    IF OLD.es_activo = TRUE AND NEW.es_activo = FALSE THEN

        SELECT COUNT(*) INTO v_dispositivos
        FROM modulo9.dispositivos_iot
        WHERE id_infraestructura = OLD.id_infraestructura
          AND es_activo          = TRUE;

        SELECT COUNT(*) INTO v_sensores
        FROM modulo9.sensores_areas_asociadas
        WHERE id_infraestructura = OLD.id_infraestructura
          AND tiene_estado       = TRUE;

        IF v_dispositivos > 0 OR v_sensores > 0 THEN
            RAISE EXCEPTION 'AREA_IN_USE: El área "%" tiene % dispositivo(s) activo(s) y % sensor(es) asociado(s). Desvincule los recursos antes de desactivar la infraestructura.',
                OLD.nombre, v_dispositivos, v_sensores
                USING ERRCODE = 'P0127';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_infraestructura_no_desactivar_en_uso() OWNER TO postgres;

