--
-- Name: trg_fn_niveles_alerta_solapamiento(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_niveles_alerta_solapamiento() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count       INTEGER;
    v_umbral_min  NUMERIC;
    v_umbral_max  NUMERIC;
BEGIN
    -- 1. Coherencia interna del nivel
    IF NEW.limite_inferior >= NEW.limite_superior THEN
        RAISE EXCEPTION
            'INVALID_ALERT_RANGE: El límite inferior (%) debe ser '
            'estrictamente menor al límite superior (%) del nivel de alerta.',
            NEW.limite_inferior, NEW.limite_superior
        USING ERRCODE = 'P0113';
    END IF;

    -- 2. Detectar solapamiento con otros niveles del mismo umbral
    SELECT COUNT(*) INTO v_count
    FROM modulo9.niveles_alerta_ambientales
    WHERE id_umbral_ambiental = NEW.id_umbral_ambiental
      AND id_nivel_alerta_ambiental <> COALESCE(NEW.id_nivel_alerta_ambiental, -1)
      AND (
            NEW.limite_inferior < limite_superior
        AND NEW.limite_superior > limite_inferior
      );

    IF v_count > 0 THEN
        RAISE EXCEPTION
            'OVERLAPPING_ALERT: El rango [%, %] del nuevo nivel de alerta '
            'se solapa con un rango ya existente para este umbral ambiental.',
            NEW.limite_inferior, NEW.limite_superior
        USING ERRCODE = 'P0114';
    END IF;

    -- 3. Validar que el nivel esté contenido dentro del rango del umbral padre
    SELECT valor_min, valor_max
    INTO   v_umbral_min, v_umbral_max
    FROM   modulo9.umbrales_ambientales
    WHERE  id_umbral_ambiental = NEW.id_umbral_ambiental;

    IF v_umbral_min IS NULL THEN
        RAISE EXCEPTION
            'THRESHOLD_NOT_FOUND: No existe un umbral ambiental con ID %.',
            NEW.id_umbral_ambiental
        USING ERRCODE = 'P0115';
    END IF;

    IF NEW.limite_inferior < v_umbral_min OR NEW.limite_superior > v_umbral_max THEN
        RAISE EXCEPTION
            'OUT_OF_THRESHOLD_RANGE: El nivel de alerta [%, %] excede el rango '
            'del umbral ambiental [%, %]. Los niveles deben estar contenidos '
            'dentro del rango general.',
            NEW.limite_inferior, NEW.limite_superior,
            v_umbral_min, v_umbral_max
        USING ERRCODE = 'P0115';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_niveles_alerta_solapamiento() OWNER TO postgres;

--
-- Name: trg_fn_patologias_no_delete(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_patologias_no_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'NO_PHYSICAL_DELETE: Las patologías no pueden eliminarse físicamente. Use la desactivación lógica (es_activo = false). Patología: "%".',
        OLD.nombre
        USING ERRCODE = 'P0108';
    RETURN NULL;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_patologias_no_delete() OWNER TO postgres;

--
-- Name: trg_fn_patologias_nombre_unique_ci(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_patologias_nombre_unique_ci() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_count
    FROM modulo9.patologias
    WHERE LOWER(TRIM(nombre)) = LOWER(TRIM(NEW.nombre))
      AND id_patologia <> COALESCE(NEW.id_patologia, -1);

    IF v_count > 0 THEN
        RAISE EXCEPTION 'DUPLICATE_PATHOLOGY: Ya existe una patología con el nombre "%" en el catálogo global (case-insensitive).',
            NEW.nombre
            USING ERRCODE = 'P0107';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_patologias_nombre_unique_ci() OWNER TO postgres;

--
-- Name: trg_fn_plantilla_inmutable(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_plantilla_inmutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'IMMUTABLE_TEMPLATE: La plantilla "%" (v%) es inmutable y no puede eliminarse. Las plantillas son registros permanentes.',
            OLD.template_name, OLD.version
            USING ERRCODE = 'P0134';
    END IF;

    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION 'IMMUTABLE_TEMPLATE: La plantilla "%" (v%) es inmutable. Para actualizar, genere una nueva versión mediante INSERT.',
            OLD.template_name, OLD.version
            USING ERRCODE = 'P0134';
    END IF;

    RETURN NULL;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_plantilla_inmutable() OWNER TO postgres;

--
-- Name: trg_fn_plantilla_version_incremental(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_plantilla_version_incremental() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_max_version INTEGER;
BEGIN
    SELECT MAX(version) INTO v_max_version
    FROM modulo9.plantillas
    WHERE LOWER(TRIM(template_name)) = LOWER(TRIM(NEW.template_name));

    IF v_max_version IS NULL THEN
        NEW.version := 1;
    ELSE
        NEW.version := v_max_version + 1;
    END IF;

    NEW.fecha_creacion := now();

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_plantilla_version_incremental() OWNER TO postgres;

--
-- Name: trg_fn_sensor_asociacion_infraestructura_fija(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_sensor_asociacion_infraestructura_fija() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_infra_actual INTEGER;
BEGIN
    -- Buscar cualquier infraestructura donde ya haya estado este sensor
    SELECT DISTINCT id_infraestructura
    INTO v_infra_actual
    FROM modulo9.sensores_areas_asociadas
    WHERE id_sensor = NEW.id_sensor
    LIMIT 1;

    -- Si ya existía y es DISTINTA a la nueva → error
    IF v_infra_actual IS NOT NULL AND v_infra_actual <> NEW.id_infraestructura THEN
        RAISE EXCEPTION
            'SENSOR_INFRAESTRUCTURA_FIJA: El sensor ID % ya está vinculado '
            'de por vida a la infraestructura ID %. No puede ser reasignado a '
            'la infraestructura ID %. Los sensores no se reubican en el sistema.',
            NEW.id_sensor, v_infra_actual, NEW.id_infraestructura
            USING ERRCODE = 'P0140';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_sensor_asociacion_infraestructura_fija() OWNER TO postgres;

--
-- Name: trg_fn_sensor_asociacion_unica_activa(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_sensor_asociacion_unica_activa() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count      INTEGER;
    v_nombre_area VARCHAR(50);
BEGIN
    SELECT COUNT(*), MAX(i.nombre)
    INTO v_count, v_nombre_area
    FROM modulo9.sensores_areas_asociadas saa
    JOIN modulo9.infraestructuras i ON i.id_infraestructura = saa.id_infraestructura
    WHERE saa.id_sensor    = NEW.id_sensor
      AND saa.tiene_estado = TRUE;

    IF v_count > 0 THEN
        RAISE EXCEPTION 'SENSOR_ALREADY_ASSIGNED: El sensor ID % ya está activo en el área "%". Finalice la asociación actual antes de reasignarlo.',
            NEW.id_sensor, v_nombre_area
            USING ERRCODE = 'P0130';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_sensor_asociacion_unica_activa() OWNER TO postgres;

--
-- Name: trg_fn_tema_visual_valor_valido(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_tema_visual_valor_valido() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.theme_mode NOT IN (1, 2, 3) THEN
        RAISE EXCEPTION 'INVALID_THEME: El tema visual "%" no es válido. Los valores permitidos son: 1 (Claro), 2 (Oscuro), 3 (Automático/Sistema).',
            NEW.theme_mode
            USING ERRCODE = 'P0136';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_tema_visual_valor_valido() OWNER TO postgres;

--
-- Name: trg_fn_umbral_ambiental_duplicado(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_umbral_ambiental_duplicado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    IF NEW.es_activo = TRUE THEN
        SELECT COUNT(*) INTO v_count
        FROM modulo9.umbrales_ambientales
        WHERE id_especie            = NEW.id_especie
          AND id_variable_ambiental = NEW.id_variable_ambiental
          AND es_activo             = TRUE
          AND id_umbral_ambiental  <> COALESCE(NEW.id_umbral_ambiental, -1);

        IF v_count > 0 THEN
            RAISE EXCEPTION 'DUPLICATE_THRESHOLD: Ya existe un umbral activo para esta combinación de especie y variable ambiental. Edite el umbral existente en lugar de crear uno nuevo.'
                USING ERRCODE = 'P0110';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_umbral_ambiental_duplicado() OWNER TO postgres;

--
-- Name: trg_fn_umbral_ambiental_rango_valido(); Type: FUNCTION; Schema: modulo9; Owner: postgres
--

CREATE FUNCTION modulo9.trg_fn_umbral_ambiental_rango_valido() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_especie_activa BOOLEAN;
BEGIN
    -- Validar rango lógico
    IF NEW.valor_min >= NEW.valor_max THEN
        RAISE EXCEPTION 'INVALID_RANGE: El valor mínimo (%) no puede ser mayor o igual al valor máximo (%) para el umbral ambiental.',
            NEW.valor_min, NEW.valor_max
            USING ERRCODE = 'P0111';
    END IF;

    -- Validar que la especie esté activa
    SELECT es_activo INTO v_especie_activa
    FROM modulo9.especies
    WHERE id_especie = NEW.id_especie;

    IF v_especie_activa IS NULL OR v_especie_activa = FALSE THEN
        RAISE EXCEPTION 'INACTIVE_SPECIES: No se puede configurar un umbral para la especie ID % porque está inactiva o no existe.',
            NEW.id_especie
            USING ERRCODE = 'P0112';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION modulo9.trg_fn_umbral_ambiental_rango_valido() OWNER TO postgres;

