COMMENT ON COLUMN auditoria.logs_dml.rol_bd IS 'Rol activo de PostgreSQL en el momento de la operación. Útil cuando un usuario
asume roles diferentes (SET ROLE) para operaciones privilegiadas.';


--
-- Name: COLUMN logs_dml.esquema_afectado; Type: COMMENT; Schema: auditoria; Owner: postgres
--

COMMENT ON COLUMN auditoria.logs_dml.esquema_afectado IS 'Nombre del esquema donde se encuentra la tabla que fue modificada (ej: modulo1, modulo8).';


--
-- Name: COLUMN logs_dml.tabla_afectada; Type: COMMENT; Schema: auditoria; Owner: postgres
--

COMMENT ON COLUMN auditoria.logs_dml.tabla_afectada IS 'Nombre de la tabla sobre la que se ejecutó la operación DML.';


--
-- Name: COLUMN logs_dml.tipo_operacion; Type: COMMENT; Schema: auditoria; Owner: postgres
--

COMMENT ON COLUMN auditoria.logs_dml.tipo_operacion IS 'Tipo de operación DML ejecutada: INSERT, UPDATE o DELETE.';


--
-- Name: COLUMN logs_dml.datos_anteriores; Type: COMMENT; Schema: auditoria; Owner: postgres
--

COMMENT ON COLUMN auditoria.logs_dml.datos_anteriores IS 'Objeto JSON con los valores de la fila antes de la operación.
