    CONSTRAINT chk_cuentas_intentos_max_cinco CHECK ((intentos_fallidos <= 5)),
    CONSTRAINT chk_cuentas_intentos_no_negativos CHECK ((intentos_fallidos >= 0))
);


ALTER TABLE modulo1.cuentas_usuarios OWNER TO postgres;

--
-- Name: TABLE cuentas_usuarios; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON TABLE modulo1.cuentas_usuarios IS 'Gestiona el estado operativo y de seguridad de la cuenta de acceso de cada usuario.
Separa la información de identidad (tabla usuarios) de la información de cuenta
(intentos, bloqueos, tokens, verificaciones). Cada usuario tiene exactamente
una cuenta asociada (relación 1:1).';


--
