--

COMMENT ON COLUMN modulo1.cuentas_usuarios.tiene_correo_verificado IS 'Indica si el usuario ha verificado su correo electrónico mediante el enlace
de confirmación enviado al registrarse. Por defecto false.';


--
-- Name: COLUMN cuentas_usuarios.fecha_verificacion; Type: COMMENT; Schema: modulo1; Owner: postgres
