--
-- Name: sesiones; Type: TABLE; Schema: modulo1; Owner: postgres
--

CREATE TABLE modulo1.sesiones (
    id_sesion integer NOT NULL,
    id_token integer NOT NULL,
    direccion_ip character varying(45) NOT NULL,
    agente_usuario character varying(255) NOT NULL,
    fecha_inicio timestamp with time zone NOT NULL,
    fecha_finalizacion timestamp with time zone NOT NULL,
    es_activa boolean NOT NULL,
    id_cuenta_usuario integer NOT NULL,
    id_token_refresco integer,
    CONSTRAINT chk_sesiones_estado_coherente CHECK ((es_activa IS NOT NULL)),
    CONSTRAINT chk_sesiones_fechas_coherentes CHECK (((fecha_finalizacion IS NULL) OR (fecha_inicio <= fecha_finalizacion)))
);


ALTER TABLE modulo1.sesiones OWNER TO postgres;

--
-- Name: TABLE sesiones; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON TABLE modulo1.sesiones IS 'Registra las sesiones de acceso al sistema de cada usuario. Permite rastrear
desde qué dispositivo y dirección IP se conectó, la duración de la sesión
y si sigue activa. Es clave para el control de seguridad y auditoría de accesos.';


--
-- Name: COLUMN sesiones.id_sesion; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.sesiones.id_sesion IS 'Identificador único de la sesión. Clave primaria (serial).';


--
-- Name: COLUMN sesiones.id_token; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.sesiones.id_token IS 'FK hacia modulo1.tokens. Token de autenticación asociado a esta sesión. Único por sesión.';


--
-- Name: COLUMN sesiones.direccion_ip; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.sesiones.direccion_ip IS 'Dirección IP del cliente desde la que se inició la sesión.
Soporta IPv4 e IPv6. Máximo 45 caracteres.';


--
-- Name: COLUMN sesiones.agente_usuario; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.sesiones.agente_usuario IS 'Cadena del agente de usuario (navegador o aplicación) del cliente.
Permite identificar el dispositivo y sistema operativo usado. Máximo 255 caracteres.';


--
-- Name: COLUMN sesiones.fecha_inicio; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.sesiones.fecha_inicio IS 'Marca temporal (con zona horaria) del momento en que se inició la sesión.';


--
-- Name: COLUMN sesiones.fecha_finalizacion; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.sesiones.fecha_finalizacion IS 'Marca temporal (con zona horaria) del momento en que la sesión fue cerrada
o expiró. Si la sesión sigue activa, este valor puede ser la expiración esperada.';


--
-- Name: COLUMN sesiones.es_activa; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.sesiones.es_activa IS 'Indica si la sesión está actualmente activa. Se actualiza a false al cerrar sesión
o al expirar el token asociado.';


--
-- Name: COLUMN sesiones.id_cuenta_usuario; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.sesiones.id_cuenta_usuario IS 'FK hacia modulo1.cuentas_usuarios. Cuenta del usuario que inició esta sesión.';


--
-- Name: sesiones_id_sesiones_seq; Type: SEQUENCE; Schema: modulo1; Owner: postgres
--

