--
-- Name: tokens; Type: TABLE; Schema: modulo1; Owner: postgres
--

CREATE TABLE modulo1.tokens (
    id_token integer NOT NULL,
    token_tipo modulo1.enum_token_tipo,
    fecha_expiracion timestamp with time zone,
    fecha_uso timestamp with time zone,
    fecha_creacion timestamp with time zone DEFAULT now() NOT NULL,
    hash_valor character varying(64),
    id_sesion integer
);


ALTER TABLE modulo1.tokens OWNER TO postgres;

--
-- Name: TABLE tokens; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON TABLE modulo1.tokens IS 'Almacena los tokens de uso único generados para operaciones sensibles del sistema:
recuperación de contraseña, verificación de correo, autenticación temporal, etc.
Cada token tiene un tipo, fecha de expiración y registro de si ya fue utilizado.';


--
-- Name: COLUMN tokens.id_token; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.tokens.id_token IS 'Identificador único del token. Clave primaria (serial).';


--
-- Name: COLUMN tokens.token_tipo; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.tokens.token_tipo IS 'Tipo de token según su propósito. ENUM global (enum_token_tipo).
Ej: RECUPERACION_CONTRASENA, VERIFICACION_CORREO, SESION_TEMPORAL.';


--
-- Name: COLUMN tokens.fecha_expiracion; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.tokens.fecha_expiracion IS 'Marca temporal (con zona horaria) en que el token deja de ser válido.
Los tokens no usados antes de esta fecha son inválidos.';


--
-- Name: COLUMN tokens.fecha_uso; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.tokens.fecha_uso IS 'Marca temporal (con zona horaria) del momento en que el token fue consumido/usado.
Si es igual a fecha_creacion o está en el pasado indica que ya fue utilizado.';


--
-- Name: COLUMN tokens.fecha_creacion; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.tokens.fecha_creacion IS 'Marca temporal (con zona horaria) del momento en que se generó el token.';


--
-- Name: tokens_id_token_seq; Type: SEQUENCE; Schema: modulo1; Owner: postgres
--

CREATE SEQUENCE modulo1.tokens_id_token_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo1.tokens_id_token_seq OWNER TO postgres;

--
-- Name: tokens_id_token_seq; Type: SEQUENCE OWNED BY; Schema: modulo1; Owner: postgres
--

ALTER SEQUENCE modulo1.tokens_id_token_seq OWNED BY modulo1.tokens.id_token;


--
-- Name: usuarios; Type: TABLE; Schema: modulo1; Owner: postgres
--

CREATE TABLE modulo1.usuarios (
    id_usuario integer NOT NULL,
    tipo_identificacion character varying(10),
    numero_identificacion character varying(20),
    nombre character varying(80),
    apellidos character varying(80),
    fecha_nacimiento date,
    genero modulo1.enum_usuario_genero,
    correo_electronico character varying(100) NOT NULL,
    contrasena_cifrada character varying(255) NOT NULL,
    telefono character varying(20),
    direccion character varying(150),
    id_rol integer NOT NULL,
    fecha_registro timestamp without time zone DEFAULT now() NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    fecha_actualizacion timestamp with time zone DEFAULT now(),
    CONSTRAINT chk_usuario_apellidos_validos CHECK (((apellidos)::text ~ '^[A-Za-zÁÉÍÓÚáéíóúÑñ ]+$'::text)),
    CONSTRAINT chk_usuario_formato_correo CHECK (((correo_electronico)::text ~* '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$'::text)),
    CONSTRAINT chk_usuario_nombre_validos CHECK (((nombre)::text ~ '^[A-Za-zÁÉÍÓÚáéíóúÑñ ]+$'::text)),
    CONSTRAINT chk_usuario_tipo_identificacion CHECK (((tipo_identificacion)::text = ANY (ARRAY[('CC'::character varying)::text, ('CE'::character varying)::text, ('Pasaporte'::character varying)::text])))
);


ALTER TABLE modulo1.usuarios OWNER TO postgres;

--
-- Name: TABLE usuarios; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON TABLE modulo1.usuarios IS 'Tabla maestra de usuarios del sistema. Almacena la información personal,
de autenticación y de rol de cada persona registrada. Es la entidad central
del módulo 1 y es referenciada por prácticamente todos los demás módulos
del sistema para asociar acciones a un usuario específico.';


--
-- Name: COLUMN usuarios.id_usuario; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.usuarios.id_usuario IS 'Identificador único del usuario. Clave primaria generada automáticamente (serial).
Es la FK más referenciada en todo el sistema.';


--
-- Name: COLUMN usuarios.tipo_identificacion; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.usuarios.tipo_identificacion IS 'Tipo de documento de identidad del usuario (ej: CC, CE, NIT, PA).
Máximo 10 caracteres. Usado junto con numero_identificacion para identificación civil.';


--
-- Name: COLUMN usuarios.numero_identificacion; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.usuarios.numero_identificacion IS 'Número del documento de identidad del usuario. Único en el sistema.
Máximo 20 caracteres. No puede repetirse sin importar el tipo de identificación.';


--
-- Name: COLUMN usuarios.nombre; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.usuarios.nombre IS 'Nombre(s) del usuario. Máximo 80 caracteres.';


--
-- Name: COLUMN usuarios.apellidos; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.usuarios.apellidos IS 'Apellido(s) del usuario. Máximo 80 caracteres.';


--
-- Name: COLUMN usuarios.fecha_nacimiento; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.usuarios.fecha_nacimiento IS 'Fecha de nacimiento del usuario. Usada para validaciones de edad mínima
y para perfiles demográficos.';


--
-- Name: COLUMN usuarios.genero; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.usuarios.genero IS 'Género del usuario. ENUM global del sistema (enum_usuario_genero).';


--
-- Name: COLUMN usuarios.correo_electronico; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.usuarios.correo_electronico IS 'Dirección de correo electrónico del usuario. Única en el sistema.
Es el canal principal de comunicación y recuperación de cuenta. Máximo 100 caracteres.';


--
-- Name: COLUMN usuarios.contrasena_cifrada; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.usuarios.contrasena_cifrada IS 'Hash de la contraseña del usuario. Nunca se almacena la contraseña en texto plano.
Se recomienda bcrypt o argon2. Máximo 255 caracteres.';


--
-- Name: COLUMN usuarios.telefono; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.usuarios.telefono IS 'Número de teléfono de contacto del usuario. Opcional. Máximo 20 caracteres.';


--
-- Name: COLUMN usuarios.direccion; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.usuarios.direccion IS 'Dirección física de residencia o contacto del usuario. Opcional. Máximo 150 caracteres.';


--
-- Name: COLUMN usuarios.id_rol; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.usuarios.id_rol IS 'FK hacia modulo1.roles. Define el rol asignado al usuario, que determina
sus permisos y accesos dentro del sistema.';


--
-- Name: COLUMN usuarios.fecha_registro; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.usuarios.fecha_registro IS 'Marca temporal (con zona horaria) del momento en que el usuario fue creado en el sistema.
Se asigna automáticamente con now().';


--
-- Name: COLUMN usuarios.version; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.usuarios.version IS 'Contador de versión del registro. Se incrementa con cada actualización.
Permite control de concurrencia optimista (optimistic locking).';


--
-- Name: COLUMN usuarios.fecha_actualizacion; Type: COMMENT; Schema: modulo1; Owner: postgres
--

COMMENT ON COLUMN modulo1.usuarios.fecha_actualizacion IS 'Marca temporal (con zona horaria) de la última modificación del registro del usuario.
Debe actualizarse mediante trigger cada vez que el registro cambie.';


--
-- Name: usuarios_admin; Type: VIEW; Schema: modulo1; Owner: postgres
--

CREATE VIEW modulo1.usuarios_admin AS
 SELECT id_usuario,
    tipo_identificacion,
    numero_identificacion,
    nombre,
    apellidos,
    fecha_nacimiento,
    genero,
    correo_electronico,
    contrasena_cifrada,
    telefono,
    direccion,
    id_rol,
    fecha_registro,
    version,
    fecha_actualizacion
   FROM modulo1.usuarios
  WHERE (id_rol = 1);


ALTER VIEW modulo1.usuarios_admin OWNER TO postgres;

--
-- Name: usuarios_id_usuarios_seq; Type: SEQUENCE; Schema: modulo1; Owner: postgres
--

CREATE SEQUENCE modulo1.usuarios_id_usuarios_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo1.usuarios_id_usuarios_seq OWNER TO postgres;

--
-- Name: usuarios_id_usuarios_seq; Type: SEQUENCE OWNED BY; Schema: modulo1; Owner: postgres
--

ALTER SEQUENCE modulo1.usuarios_id_usuarios_seq OWNED BY modulo1.usuarios.id_usuario;


--
-- Name: vw_cuentas_correo_estado; Type: VIEW; Schema: modulo1; Owner: postgres
--

CREATE VIEW modulo1.vw_cuentas_correo_estado AS
 SELECT u.id_usuario,
    u.nombre,
    u.apellidos,
    u.correo_electronico,
    cu.id_cuenta_usuario,
    cu.tiene_correo_verificado,
    cu.fecha_verificacion,
    ec.id_estado_cuenta,
    ec.nombre AS estado_cuenta
   FROM ((modulo1.usuarios u
     JOIN modulo1.cuentas_usuarios cu ON ((cu.id_usuario = u.id_usuario)))
     JOIN modulo1.estados_cuentas ec ON ((ec.id_estado_cuenta = cu.id_estado_cuenta)));


ALTER VIEW modulo1.vw_cuentas_correo_estado OWNER TO postgres;

--
-- Name: vw_eventos_usuario_detalle; Type: VIEW; Schema: modulo1; Owner: postgres
--

CREATE VIEW modulo1.vw_eventos_usuario_detalle AS
 SELECT e.id_evento,
    u.id_usuario,
    u.nombre,
    u.apellidos,
    te.id_tipo_evento,
    te.nombre AS nombre_evento,
    te.accion AS accion_evento,
    e.modulo,
    e.resultado,
    e.estado,
    e.fecha_evento
   FROM ((modulo1.eventos e
     JOIN modulo1.usuarios u ON ((u.id_usuario = e.id_usuario)))
     JOIN modulo1.tipos_eventos te ON ((te.id_tipo_evento = e.tipo_evento)));


ALTER VIEW modulo1.vw_eventos_usuario_detalle OWNER TO postgres;

--
-- Name: vw_eventos_usuario_sesion_activa; Type: VIEW; Schema: modulo1; Owner: postgres
--

CREATE VIEW modulo1.vw_eventos_usuario_sesion_activa AS
 SELECT e.id_evento,
    u.id_usuario,
    u.nombre,
    u.apellidos,
    te.nombre AS nombre_evento,
    e.estado,
    e.modulo,
    s.id_sesion,
    s.direccion_ip,
    e.fecha_evento
   FROM ((((modulo1.eventos e
     JOIN modulo1.usuarios u ON ((u.id_usuario = e.id_usuario)))
     JOIN modulo1.tipos_eventos te ON ((te.id_tipo_evento = e.tipo_evento)))
     JOIN modulo1.cuentas_usuarios cu ON ((cu.id_usuario = u.id_usuario)))
     JOIN LATERAL ( SELECT ses.id_sesion,
            ses.direccion_ip,
            ses.fecha_inicio
           FROM modulo1.sesiones ses
          WHERE ((ses.id_cuenta_usuario = cu.id_cuenta_usuario) AND (ses.es_activa IS TRUE))
          ORDER BY ses.fecha_inicio DESC, ses.id_sesion DESC
         LIMIT 1) s ON (true));


ALTER VIEW modulo1.vw_eventos_usuario_sesion_activa OWNER TO postgres;

--
-- Name: vw_notificaciones_eventos; Type: VIEW; Schema: modulo1; Owner: postgres
--

CREATE VIEW modulo1.vw_notificaciones_eventos AS
 SELECT n.id_notificacion,
    n.id_evento,
    n.mensaje,
    n.fecha_envio,
    n.es_leido,
    u.id_usuario,
    u.nombre,
    u.apellidos,
    e.descripcion AS evento,
    e.modulo,
    e.fecha_evento
   FROM ((modulo1.notificaciones n
     JOIN modulo1.eventos e ON ((e.id_evento = n.id_evento)))
     JOIN modulo1.usuarios u ON ((u.id_usuario = n.id_usuario)));


ALTER VIEW modulo1.vw_notificaciones_eventos OWNER TO postgres;

--
-- Name: vw_permisos_roles; Type: VIEW; Schema: modulo1; Owner: postgres
--

CREATE VIEW modulo1.vw_permisos_roles AS
 SELECT r.id_rol,
    r.nombre_rol,
    p.id_permiso,
    p.nombre AS permiso,
    p.descripcion AS descripcion_permiso,
    a.id_accion,
    a.codigo AS codigo_accion,
    a.descripcion AS accion,
    rec.id_recurso,
    rec.nombre_recurso AS recurso,
    rec.descripcion AS descripcion_recurso,
    p.fecha_creacion AS fecha_asignacion,
    p.fecha_actualizacion,
    p.es_activo
   FROM (((modulo1.roles r
     JOIN modulo1.permisos p ON ((p.id_rol = r.id_rol)))
     JOIN modulo1.acciones a ON ((a.id_accion = p.id_accion)))
     JOIN modulo1.recursos rec ON ((rec.id_recurso = p.id_recurso)));


ALTER VIEW modulo1.vw_permisos_roles OWNER TO postgres;

--
-- Name: vw_resumen_cuentas_usuarios; Type: VIEW; Schema: modulo1; Owner: postgres
--

CREATE VIEW modulo1.vw_resumen_cuentas_usuarios AS
 SELECT u.id_usuario,
    u.nombre,
    u.apellidos,
    u.correo_electronico,
    u.telefono,
    r.id_rol,
    r.nombre_rol AS rol,
    cu.id_cuenta_usuario,
    ec.id_estado_cuenta,
    ec.nombre AS estado_cuenta,
    cu.ultimo_acceso
   FROM (((modulo1.usuarios u
     JOIN modulo1.roles r ON ((r.id_rol = u.id_rol)))
     JOIN modulo1.cuentas_usuarios cu ON ((cu.id_usuario = u.id_usuario)))
     JOIN modulo1.estados_cuentas ec ON ((ec.id_estado_cuenta = cu.id_estado_cuenta)));


ALTER VIEW modulo1.vw_resumen_cuentas_usuarios OWNER TO postgres;

--
-- Name: vw_sesiones_activas_usuario; Type: VIEW; Schema: modulo1; Owner: postgres
--

CREATE VIEW modulo1.vw_sesiones_activas_usuario AS
 SELECT u.id_usuario,
    u.nombre,
    u.apellidos,
    r.id_rol,
    r.nombre_rol,
    cu.id_cuenta_usuario,
    cu.ultimo_acceso,
    ec.nombre AS estado_cuenta,
    s.id_sesion,
    s.es_activa,
    s.direccion_ip,
    s.fecha_inicio
   FROM ((((modulo1.sesiones s
     JOIN modulo1.cuentas_usuarios cu ON ((cu.id_cuenta_usuario = s.id_cuenta_usuario)))
     JOIN modulo1.usuarios u ON ((u.id_usuario = cu.id_usuario)))
     JOIN modulo1.roles r ON ((r.id_rol = u.id_rol)))
     JOIN modulo1.estados_cuentas ec ON ((ec.id_estado_cuenta = cu.id_estado_cuenta)))
  WHERE (s.es_activa IS TRUE);


ALTER VIEW modulo1.vw_sesiones_activas_usuario OWNER TO postgres;

