-- Name: detalles_activos_biologicos_poblacionales; Type: TABLE; Schema: modulo2; Owner: postgres
--

CREATE TABLE modulo2.detalles_activos_biologicos_poblacionales (
    id_detalle_activo_biologico_poblacional integer NOT NULL,
    id_activo_biologico integer NOT NULL,
    cantidad_inicial integer NOT NULL,
    cantidad_actual integer,
    peso_promedio numeric,
    biomasa_total numeric,
    densidad numeric,
    peso_promedio_inicial numeric(10,4),
    CONSTRAINT chk_poblacional_biomasa_coherente CHECK (((cantidad_actual = 0) OR (abs((biomasa_total - ((cantidad_actual)::numeric * peso_promedio))) <= (((cantidad_actual)::numeric * peso_promedio) * 0.05)))),
    CONSTRAINT chk_poblacional_cantidad_actual_coherente CHECK ((cantidad_actual <= cantidad_inicial)),
    CONSTRAINT chk_poblacional_cantidad_actual_no_negativa CHECK ((cantidad_actual >= 0)),
    CONSTRAINT chk_poblacional_cantidad_inicial_positiva CHECK ((cantidad_inicial > 0)),
    CONSTRAINT chk_poblacional_densidad_no_negativa CHECK ((densidad >= (0)::numeric)),
    CONSTRAINT chk_poblacional_peso_promedio_no_negativo CHECK ((peso_promedio >= (0)::numeric))
);


ALTER TABLE modulo2.detalles_activos_biologicos_poblacionales OWNER TO postgres;

