-- Name: eventos_sanitarios; Type: TABLE; Schema: modulo2; Owner: postgres
--

CREATE TABLE modulo2.eventos_sanitarios (
    id_evento integer NOT NULL,
    diagnostico text,
    medicamento character varying,
    dosis numeric(10,2),
    unidad_dosis character varying(5),
    frecuencia integer,
    tipo modulo2.enum_evento_sanitario_tipo NOT NULL,
    duracion integer,
    observaciones text,
    CONSTRAINT check_control CHECK (((tipo <> 'CONTROL_PREVENTIVO'::modulo2.enum_evento_sanitario_tipo) OR (observaciones IS NOT NULL))),
    CONSTRAINT check_diagnostico CHECK (((tipo <> 'DIAGNOSTICO'::modulo2.enum_evento_sanitario_tipo) OR (diagnostico IS NOT NULL))),
    CONSTRAINT check_tratamiento CHECK (((tipo <> 'TRATAMIENTO'::modulo2.enum_evento_sanitario_tipo) OR ((medicamento IS NOT NULL) AND (dosis IS NOT NULL) AND (frecuencia IS NOT NULL) AND (duracion IS NOT NULL)))),
    CONSTRAINT check_vacunacion CHECK (((tipo <> 'VACUNACION'::modulo2.enum_evento_sanitario_tipo) OR ((medicamento IS NOT NULL) AND (dosis IS NOT NULL)))),
    CONSTRAINT chk_sanitario_dosis_positiva CHECK ((dosis > (0)::numeric)),
    CONSTRAINT chk_sanitario_frecuencia_positiva CHECK (((frecuencia IS NULL) OR (frecuencia > 0)))
);


ALTER TABLE modulo2.eventos_sanitarios OWNER TO postgres;

