ALTER VIEW modulo2.vw_rf46_eventos_sanitarios OWNER TO postgres;

--
-- Name: vw_rf46_historial_completo_activo; Type: VIEW; Schema: modulo2; Owner: postgres
--

CREATE VIEW modulo2.vw_rf46_historial_completo_activo AS
 SELECT h.fecha_cambio AS fecha_evento,
    h.id_activo_biologico,
    ab.identificador,
    'ESTADO'::text AS categoria,
    (ea_ant.nombre)::text AS detalle_1,
    (ea_nvo.nombre)::text AS detalle_2,
    h.motivo_cambio AS observacion,
    COALESCE(concat_ws(' '::text, u.nombre, u.apellidos), 'Sin usuario'::text) AS usuario_responsable
   FROM ((((modulo2.historicos_estados_activos h
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = h.id_activo_biologico)))
     JOIN modulo2.estados_activos_biologicos ea_ant ON ((ea_ant.id_estado_activo_biologico = h.id_estado_anterior)))
     JOIN modulo2.estados_activos_biologicos ea_nvo ON ((ea_nvo.id_estado_activo_biologico = h.id_estado_nuevo)))
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = h.id_usuario)))
UNION ALL
 SELECT COALESCE(gf.fecha_finalizacion, gf.fecha_inicio) AS fecha_evento,
    gf.id_activo_biologico,
    ab.identificador,
    'FASE_PRODUCTIVA'::text AS categoria,
    (cp.nombre)::text AS detalle_1,
        CASE
            WHEN gf.es_activa THEN 'Activa'::text
            ELSE 'Finalizada'::text
        END AS detalle_2,
    ((((('duracion_dias='::text || cp.duracion_dias) || ', es_activa='::text) || gf.es_activa) || ', fecha_finalizacion='::text) || COALESCE((gf.fecha_finalizacion)::text, 'NULL'::text)) AS observacion,
    COALESCE(concat_ws(' '::text, u.nombre, u.apellidos), 'Sin usuario'::text) AS usuario_responsable
   FROM (((modulo2.gestiones_fases gf
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = gf.id_activo_biologico)))
     JOIN modulo9.ciclos_productivos cp ON ((cp.id_ciclo_productivo = gf.id_ciclo_productiva)))
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = gf.id_usuario)))
UNION ALL
 SELECT ea.fecha AS fecha_evento,
    ea.id_activo_biologico,
    ab.identificador,
    'SANITARIO'::text AS categoria,
    es.diagnostico AS detalle_1,
    (es.medicamento)::text AS detalle_2,
    ea.descripcion AS observacion,
    COALESCE(concat_ws(' '::text, u.nombre, u.apellidos), 'Sin usuario'::text) AS usuario_responsable
   FROM (((modulo2.eventos_activos ea
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = ea.id_activo_biologico)))
     JOIN modulo2.eventos_sanitarios es ON ((es.id_evento = ea.id_eventos)))
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = ea.id_usuario)))
UNION ALL
 SELECT ea.fecha AS fecha_evento,
    ea.id_activo_biologico,
    ab.identificador,
    'CRECIMIENTO'::text AS categoria,
    (ec.tipo_medicion)::text AS detalle_1,
    ((ec.valor_medicion || ' '::text) || (ec.unidad_medida)::text) AS detalle_2,
    ea.descripcion AS observacion,
    COALESCE(concat_ws(' '::text, u.nombre, u.apellidos), 'Sin usuario'::text) AS usuario_responsable
   FROM (((modulo2.eventos_activos ea
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = ea.id_activo_biologico)))
     JOIN modulo2.eventos_crecimeinto ec ON ((ec.id_evento = ea.id_eventos)))
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = ea.id_usuario)))
UNION ALL
 SELECT ea.fecha AS fecha_evento,
    ea.id_activo_biologico,
    ab.identificador,
    'PRODUCTIVO'::text AS categoria,
    COALESCE(mp.nombre, ((ep.id_metrica_produccion)::text)::character varying) AS detalle_1,
    (ep.cantidad || COALESCE((' '::text || (mp.unidad_medida)::text), ''::text)) AS detalle_2,
    ea.descripcion AS observacion,
    COALESCE(concat_ws(' '::text, u.nombre, u.apellidos), 'Sin usuario'::text) AS usuario_responsable
   FROM ((((modulo2.eventos_activos ea
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = ea.id_activo_biologico)))
     JOIN modulo2.eventos_productivos ep ON ((ep.id_evento = ea.id_eventos)))
     LEFT JOIN modulo9.metricas_produccion mp ON ((mp.id_metrica_produccion = ep.id_metrica_produccion)))
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = ea.id_usuario)))
UNION ALL
 SELECT ea.fecha AS fecha_evento,
    ea.id_activo_biologico,
    ab.identificador,
    'REPRODUCTIVO'::text AS categoria,
    (er.categoria)::text AS detalle_1,
    (er.resultado)::text AS detalle_2,
    ea.descripcion AS observacion,
    COALESCE(concat_ws(' '::text, u.nombre, u.apellidos), 'Sin usuario'::text) AS usuario_responsable
   FROM (((modulo2.eventos_activos ea
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = ea.id_activo_biologico)))
     JOIN modulo2.eventos_reproductivos er ON ((er.id_evento_reproductivo = ea.id_eventos)))
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = ea.id_usuario)))
UNION ALL
 SELECT (lower(iz.rango_fecha))::timestamp with time zone AS fecha_evento,
    iz.id_activo_biologico,
    ab.identificador,
    'INDICADOR'::text AS categoria,
    (iz.tipo)::text AS detalle_1,
    (upper(iz.rango_fecha))::text AS detalle_2,
    (iz.paramtros_calculo)::text AS observacion,
    NULL::text AS usuario_responsable
   FROM (modulo2.indicadores_zootecnicos iz
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = iz.id_activo_biologico)));


ALTER VIEW modulo2.vw_rf46_historial_completo_activo OWNER TO postgres;

--
-- Name: vw_rf47_ficha_integral_activo; Type: VIEW; Schema: modulo2; Owner: postgres
--

CREATE VIEW modulo2.vw_rf47_ficha_integral_activo AS
 SELECT ab.id_activo_biologico,
    ab.identificador AS codigo,
    ab.tipo,
    e.nombre AS especie,
    (ab.fecha_creacion)::date AS fecha_registro,
    (CURRENT_DATE - (ab.fecha_creacion)::date) AS dias_en_sistema,
    est.nombre AS estado_actual,
    i.nombre AS infraestructura_asociada,
    fase_activa.nombre AS fase_productiva_activa,
    di.raza,
    di.sexo,
    (di.fecha_nacimeinto)::date AS fecha_nacimiento,
    COALESCE(ult_peso.valor_medicion, di.peso_inicial, dp.peso_promedio) AS peso_actual,
    COALESCE(ult_peso.unidad_medida, 'kg'::character varying) AS unidad_peso,
    (ult_peso.fecha)::date AS fecha_ultimo_peso,
    dp.cantidad_actual,
    dp.biomasa_total
   FROM (((((((modulo2.activos_biologicos ab
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo2.estados_activos_biologicos est ON ((est.id_estado_activo_biologico = ab.id_estado)))
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)))
     LEFT JOIN modulo2.detalles_activos_individuales di ON ((di.id_activo_biologico = ab.id_activo_biologico)))
     LEFT JOIN modulo2.detalles_activos_biologicos_poblacionales dp ON ((dp.id_activo_biologico = ab.id_activo_biologico)))
     LEFT JOIN LATERAL ( SELECT cp2.nombre
           FROM (modulo2.gestiones_fases gf
             JOIN modulo9.ciclos_productivos cp2 ON ((cp2.id_ciclo_productivo = gf.id_ciclo_productiva)))
          WHERE ((gf.id_activo_biologico = ab.id_activo_biologico) AND (gf.es_activa IS TRUE))
          ORDER BY gf.id_gestion_fases DESC
         LIMIT 1) fase_activa ON (true))
     LEFT JOIN LATERAL ( SELECT ea.fecha,
            ec.valor_medicion,
            ec.unidad_medida
           FROM (modulo2.eventos_activos ea
             JOIN modulo2.eventos_crecimeinto ec ON ((ec.id_evento = ea.id_eventos)))
          WHERE ((ea.id_activo_biologico = ab.id_activo_biologico) AND (lower((ec.tipo_medicion)::text) ~~ '%peso%'::text))
          ORDER BY ea.fecha DESC, ea.id_eventos DESC
         LIMIT 1) ult_peso ON (true));


ALTER VIEW modulo2.vw_rf47_ficha_integral_activo OWNER TO postgres;

--
-- Name: vw_rf47_indicadores_zootecnicos_activo; Type: VIEW; Schema: modulo2; Owner: postgres
--

CREATE VIEW modulo2.vw_rf47_indicadores_zootecnicos_activo AS
 SELECT iz.id_indicador_zootecnico,
    iz.id_activo_biologico,
    ab.identificador AS identificador_activo,
    e.id_especie,
    e.nombre AS especie,
    iz.tipo AS tipo_indicador,
    lower(iz.rango_fecha) AS fecha_inicio,
    upper(iz.rango_fecha) AS fecha_fin,
    iz.rango_fecha,
    iz.paramtros_calculo
   FROM ((modulo2.indicadores_zootecnicos iz
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = iz.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)));


ALTER VIEW modulo2.vw_rf47_indicadores_zootecnicos_activo OWNER TO postgres;

--
-- Name: vw_rf48_infraestructura_actual_activo; Type: VIEW; Schema: modulo2; Owner: postgres
--

CREATE VIEW modulo2.vw_rf48_infraestructura_actual_activo AS
 SELECT ab.id_activo_biologico,
    ab.identificador,
    ab.id_infraestructura,
    i.nombre AS infraestructura_actual
   FROM (modulo2.activos_biologicos ab
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)));


ALTER VIEW modulo2.vw_rf48_infraestructura_actual_activo OWNER TO postgres;

--
-- Name: dispositivos_iot; Type: TABLE; Schema: modulo9; Owner: postgres
--

CREATE TABLE modulo9.dispositivos_iot (
    id_dispositivo_iot integer NOT NULL,
    serial character varying(50) NOT NULL,
    descripcion character varying(100) NOT NULL,
    es_activo boolean NOT NULL,
    fecha_creacion timestamp with time zone NOT NULL,
    id_infraestructura integer NOT NULL
);


ALTER TABLE modulo9.dispositivos_iot OWNER TO postgres;

--
-- Name: TABLE dispositivos_iot; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON TABLE modulo9.dispositivos_iot IS 'Dispositivo IoT físico (gateway, controlador, nodo) instalado en una infraestructura para gestionar la captura y transmisión de datos de sensores.';


--
-- Name: COLUMN dispositivos_iot.id_dispositivo_iot; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON COLUMN modulo9.dispositivos_iot.id_dispositivo_iot IS 'Identificador único del dispositivo IoT en el sistema.';


--
-- Name: COLUMN dispositivos_iot.serial; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON COLUMN modulo9.dispositivos_iot.serial IS 'Número de serie o código MAC del dispositivo IoT físico.';


--
-- Name: COLUMN dispositivos_iot.descripcion; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON COLUMN modulo9.dispositivos_iot.descripcion IS 'Descripción del dispositivo, modelo o notas de instalación.';


--
-- Name: COLUMN dispositivos_iot.es_activo; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON COLUMN modulo9.dispositivos_iot.es_activo IS 'Indica si el dispositivo está activo y comunicándose con la plataforma.';


--
-- Name: COLUMN dispositivos_iot.fecha_creacion; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON COLUMN modulo9.dispositivos_iot.fecha_creacion IS 'Fecha y hora en que el dispositivo fue registrado en el sistema.';


--
-- Name: sensores; Type: TABLE; Schema: modulo9; Owner: postgres
--

CREATE TABLE modulo9.sensores (
    id_sensores integer NOT NULL,
    id_dispositivo_iot integer NOT NULL,
    es_activo boolean NOT NULL,
    nombre character varying(60) NOT NULL,
    categoria modulo3.enum_reglas_alertas_tipo_sensor
);


ALTER TABLE modulo9.sensores OWNER TO postgres;

--
-- Name: TABLE sensores; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON TABLE modulo9.sensores IS 'Sensor físico conectado a un dispositivo IoT, encargado de medir una variable ambiental específica (ej: sonda de temperatura, electrodo de pH).';


--
-- Name: COLUMN sensores.id_sensores; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON COLUMN modulo9.sensores.id_sensores IS 'Identificador único del sensor.';


--
-- Name: COLUMN sensores.id_dispositivo_iot; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON COLUMN modulo9.sensores.id_dispositivo_iot IS 'Dispositivo IoT al que está conectado este sensor.';


--
-- Name: COLUMN sensores.es_activo; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON COLUMN modulo9.sensores.es_activo IS 'Indica si el sensor está operativo y enviando lecturas.';


--
-- Name: COLUMN sensores.nombre; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON COLUMN modulo9.sensores.nombre IS 'Nombre descriptivo del sensor (ej: "Sensor pH estanque 1", "Termómetro zona norte").';


--
-- Name: sensores_areas_asociadas; Type: TABLE; Schema: modulo9; Owner: postgres
--

CREATE TABLE modulo9.sensores_areas_asociadas (
    id_sensores_area_asociada integer NOT NULL,
    id_sensor integer NOT NULL,
    id_dispositivo_iot integer NOT NULL,
    id_infraestructura integer NOT NULL,
    punto_instalacion character varying(100) NOT NULL,
    tiene_estado boolean NOT NULL,
    fecha_asociacion timestamp with time zone NOT NULL,
    fecha_finalizacion timestamp with time zone,
    id_usuario integer NOT NULL
);


ALTER TABLE modulo9.sensores_areas_asociadas OWNER TO postgres;

--
-- Name: TABLE sensores_areas_asociadas; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON TABLE modulo9.sensores_areas_asociadas IS 'Historial de asociaciones de sensores a infraestructuras (áreas de monitoreo). Permite conocer dónde estuvo o está instalado cada sensor a lo largo del tiempo.';


--
-- Name: COLUMN sensores_areas_asociadas.id_sensores_area_asociada; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON COLUMN modulo9.sensores_areas_asociadas.id_sensores_area_asociada IS 'Identificador único de la asociación sensor-área.';


--
-- Name: COLUMN sensores_areas_asociadas.id_sensor; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON COLUMN modulo9.sensores_areas_asociadas.id_sensor IS 'Sensor asociado al área de monitoreo.';


--
-- Name: COLUMN sensores_areas_asociadas.id_dispositivo_iot; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON COLUMN modulo9.sensores_areas_asociadas.id_dispositivo_iot IS 'Dispositivo IoT al que pertenece el sensor en esta asociación.';


--
-- Name: COLUMN sensores_areas_asociadas.id_infraestructura; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON COLUMN modulo9.sensores_areas_asociadas.id_infraestructura IS 'Infraestructura (área) donde está o estuvo instalado el sensor.';


--
-- Name: COLUMN sensores_areas_asociadas.punto_instalacion; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON COLUMN modulo9.sensores_areas_asociadas.punto_instalacion IS 'Descripción del punto exacto de instalación dentro de la infraestructura (ej: "Entrada de agua", "Centro estanque").';


--
-- Name: COLUMN sensores_areas_asociadas.tiene_estado; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON COLUMN modulo9.sensores_areas_asociadas.tiene_estado IS 'Indica si la asociación está actualmente vigente (TRUE) o fue finalizada (FALSE).';


--
-- Name: COLUMN sensores_areas_asociadas.fecha_asociacion; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON COLUMN modulo9.sensores_areas_asociadas.fecha_asociacion IS 'Fecha y hora en que el sensor fue instalado en esta área.';


--
-- Name: COLUMN sensores_areas_asociadas.fecha_finalizacion; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON COLUMN modulo9.sensores_areas_asociadas.fecha_finalizacion IS 'Fecha y hora en que el sensor fue retirado o desasociado del área (NULL si sigue activo).';


--
-- Name: COLUMN sensores_areas_asociadas.id_usuario; Type: COMMENT; Schema: modulo9; Owner: postgres
--

COMMENT ON COLUMN modulo9.sensores_areas_asociadas.id_usuario IS 'Usuario que registró o gestionó la asociación del sensor.';


--
-- Name: vw_rf49_asociaciones_sensores_activos; Type: VIEW; Schema: modulo2; Owner: postgres
--

CREATE VIEW modulo2.vw_rf49_asociaciones_sensores_activos AS
 SELECT aas.id_asociacion_activo_sensor,
    aas.id_sensor,
    s.nombre AS sensor,
    d.serial AS dispositivo_serial,
    i.nombre AS infraestructura_sensor,
    aas.id_usuario,
    aas.fecha_inicio,
    aas.fecha_fin,
    aas.motivo,
    aas.id_activo_biologico,
    ab.identificador,
    aas.tipo
   FROM ((((modulo2.asociaciones_activos_sensores aas
     JOIN modulo9.sensores s ON ((s.id_sensores = aas.id_sensor)))
     JOIN ( SELECT DISTINCT ON (d0.id_dispositivo_iot) d0.id_dispositivo_iot,
            d0.serial,
            d0.descripcion,
            d0.es_activo,
            d0.fecha_creacion,
            COALESCE(saa.id_infraestructura, ab_1.id_infraestructura) AS id_infraestructura
           FROM (((modulo9.dispositivos_iot d0
             LEFT JOIN modulo9.sensores s_1 ON ((s_1.id_dispositivo_iot = d0.id_dispositivo_iot)))
             LEFT JOIN modulo9.sensores_areas_asociadas saa ON (((saa.id_sensor = s_1.id_sensores) AND ((saa.fecha_finalizacion IS NULL) OR (saa.fecha_finalizacion > now())))))
             LEFT JOIN modulo2.activos_biologicos ab_1 ON ((ab_1.id_dispositivo_iot = d0.id_dispositivo_iot)))
          ORDER BY d0.id_dispositivo_iot, saa.fecha_asociacion DESC NULLS LAST, saa.id_sensores_area_asociada DESC NULLS LAST) d ON ((d.id_dispositivo_iot = s.id_dispositivo_iot)))
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = d.id_infraestructura)))
     LEFT JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = aas.id_activo_biologico)));


ALTER VIEW modulo2.vw_rf49_asociaciones_sensores_activos OWNER TO postgres;

--
-- Name: vw_rf51_auditoria_activos_registrados; Type: VIEW; Schema: modulo2; Owner: postgres
--

CREATE VIEW modulo2.vw_rf51_auditoria_activos_registrados AS
 SELECT ab.id_activo_biologico,
    ab.identificador,
    ab.tipo,
    e.nombre AS especie,
    i.nombre AS infraestructura,
    ab.fecha_inicio_ciclo,
    eab.nombre AS estado,
    ab.descripcion,
    ab.origen_financiero,
    ab.costo_adquisicion,
    ab.fecha_creacion,
    ab.id_usuario
   FROM (((modulo2.activos_biologicos ab
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)))
     JOIN modulo2.estados_activos_biologicos eab ON ((eab.id_estado_activo_biologico = ab.id_estado)));


ALTER VIEW modulo2.vw_rf51_auditoria_activos_registrados OWNER TO postgres;

--
-- Name: vw_rf52_auditoria_acceso_modulos_analiticos; Type: VIEW; Schema: modulo2; Owner: postgres
--

CREATE VIEW modulo2.vw_rf52_auditoria_acceso_modulos_analiticos AS
 SELECT ab.id_activo_biologico,
    ab.identificador,
    ab.tipo,
    e.nombre AS especie,
    est.nombre AS estado_actual,
    i.nombre AS infraestructura_actual,
    ab.fecha_creacion,
    count(DISTINCT ea.id_eventos) AS total_eventos,
    count(DISTINCT iz.id_indicador_zootecnico) AS total_indicadores,
    max(ea.fecha) AS fecha_ultimo_evento
   FROM (((((modulo2.activos_biologicos ab
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo2.estados_activos_biologicos est ON ((est.id_estado_activo_biologico = ab.id_estado)))
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)))
     LEFT JOIN modulo2.eventos_activos ea ON ((ea.id_activo_biologico = ab.id_activo_biologico)))
     LEFT JOIN modulo2.indicadores_zootecnicos iz ON ((iz.id_activo_biologico = ab.id_activo_biologico)))
  GROUP BY ab.id_activo_biologico, ab.identificador, ab.tipo, e.nombre, est.nombre, i.nombre, ab.fecha_creacion;


ALTER VIEW modulo2.vw_rf52_auditoria_acceso_modulos_analiticos OWNER TO postgres;

--
-- Name: vw_rf52_auditoria_activos_individuales; Type: VIEW; Schema: modulo2; Owner: postgres
--

CREATE VIEW modulo2.vw_rf52_auditoria_activos_individuales AS
 SELECT ab.id_activo_biologico,
    ab.identificador,
    dai.raza,
    dai.sexo,
    dai.fecha_nacimeinto AS fecha_nacimiento,
    dai.peso_inicial,
    e.nombre AS especie,
    i.nombre AS infraestructura,
    eab.nombre AS estado,
    ab.fecha_creacion,
    ab.descripcion,
    ab.id_usuario
   FROM ((((modulo2.activos_biologicos ab
     JOIN modulo2.detalles_activos_individuales dai ON ((dai.id_activo_biologico = ab.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)))
     JOIN modulo2.estados_activos_biologicos eab ON ((eab.id_estado_activo_biologico = ab.id_estado)))
  WHERE (ab.tipo = 'INDIVIDUAL'::modulo2.enum_activo_biologico_tipo);


ALTER VIEW modulo2.vw_rf52_auditoria_activos_individuales OWNER TO postgres;

--
-- Name: vw_rf52_auditoria_activos_poblacionales; Type: VIEW; Schema: modulo2; Owner: postgres
--

CREATE VIEW modulo2.vw_rf52_auditoria_activos_poblacionales AS
 SELECT ab.id_activo_biologico,
    ab.identificador AS identificador_lote,
    e.nombre AS especie,
    i.nombre AS infraestructura,
    eab.nombre AS estado,
    dp.cantidad_inicial,
    dp.cantidad_actual,
    dp.peso_promedio,
    dp.biomasa_total,
    dp.densidad,
    ab.descripcion,
    ab.fecha_creacion,
    ab.id_usuario
   FROM ((((modulo2.activos_biologicos ab
     JOIN modulo2.detalles_activos_biologicos_poblacionales dp ON ((dp.id_activo_biologico = ab.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)))
     JOIN modulo2.estados_activos_biologicos eab ON ((eab.id_estado_activo_biologico = ab.id_estado)))
  WHERE (ab.tipo = 'POBLACIONAL'::modulo2.enum_activo_biologico_tipo);


ALTER VIEW modulo2.vw_rf52_auditoria_activos_poblacionales OWNER TO postgres;

--
-- Name: vw_rf52_auditoria_cierres_ciclo_productivo; Type: VIEW; Schema: modulo2; Owner: postgres
--

CREATE VIEW modulo2.vw_rf52_auditoria_cierres_ciclo_productivo AS
 SELECT gf.id_gestion_fases,
    gf.id_activo_biologico,
    ab.identificador,
    cp.nombre AS ciclo_productivo,
    gf.fecha_finalizacion,
    h.id_historico_estado_activo,
    ea_ant.nombre AS estado_anterior,
    ea_nvo.nombre AS estado_nuevo,
    h.motivo_cambio,
    h.modulo_origen,
    concat_ws(' '::text, u.nombre, u.apellidos) AS usuario_responsable
   FROM ((((((modulo2.gestiones_fases gf
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = gf.id_activo_biologico)))
     JOIN modulo9.ciclos_productivos cp ON ((cp.id_ciclo_productivo = gf.id_ciclo_productiva)))
     LEFT JOIN modulo2.historicos_estados_activos h ON (((h.id_activo_biologico = gf.id_activo_biologico) AND (((h.modulo_origen)::text = 'RF-38'::text) OR ((gf.fecha_finalizacion IS NOT NULL) AND (h.fecha_cambio >= (gf.fecha_finalizacion - '00:05:00'::interval)) AND (h.fecha_cambio <= (gf.fecha_finalizacion + '00:05:00'::interval)))))))
     LEFT JOIN modulo2.estados_activos_biologicos ea_ant ON ((ea_ant.id_estado_activo_biologico = h.id_estado_anterior)))
     LEFT JOIN modulo2.estados_activos_biologicos ea_nvo ON ((ea_nvo.id_estado_activo_biologico = h.id_estado_nuevo)))
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = COALESCE(h.id_usuario, gf.id_usuario))))
  WHERE (gf.fecha_finalizacion IS NOT NULL);


ALTER VIEW modulo2.vw_rf52_auditoria_cierres_ciclo_productivo OWNER TO postgres;

--
-- Name: vw_rf52_auditoria_fases_ciclo_productivo; Type: VIEW; Schema: modulo2; Owner: postgres
--

CREATE VIEW modulo2.vw_rf52_auditoria_fases_ciclo_productivo AS
 SELECT gf.id_gestion_fases,
    gf.id_activo_biologico,
    ab.identificador AS identificador_activo,
    e.nombre AS especie,
    cp.id_ciclo_productivo,
    cp.nombre AS ciclo_productivo,
    gf.fecha_inicio,
    gf.fecha_finalizacion,
    gf.es_activa,
    gf.id_usuario,
    concat_ws(' '::text, u.nombre, u.apellidos) AS usuario_responsable
   FROM ((((modulo2.gestiones_fases gf
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = gf.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo9.ciclos_productivos cp ON ((cp.id_ciclo_productivo = gf.id_ciclo_productiva)))
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = gf.id_usuario)));


ALTER VIEW modulo2.vw_rf52_auditoria_fases_ciclo_productivo OWNER TO postgres;

--
-- Name: vw_rf52_auditoria_transferencias_internas; Type: VIEW; Schema: modulo2; Owner: postgres
--

CREATE VIEW modulo2.vw_rf52_auditoria_transferencias_internas AS
 SELECT m.id_movimiento,
    m.id_activo_biologico,
    ab.identificador,
    m.id_usuario,
    concat_ws(' '::text, u.nombre, u.apellidos) AS usuario_responsable,
    m.fecha_transferencia,
    m.tipo,
    m.id_infraestructura_origen,
    io.nombre AS infraestructura_origen,
    m.id_infraestructura_destino,
    ides.nombre AS infraestructura_destino,
    m.fecha_registro
   FROM ((((modulo2.movimientos m
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = m.id_activo_biologico)))
     JOIN modulo1.usuarios u ON ((u.id_usuario = m.id_usuario)))
     JOIN modulo9.infraestructuras io ON ((io.id_infraestructura = m.id_infraestructura_origen)))
     JOIN modulo9.infraestructuras ides ON ((ides.id_infraestructura = m.id_infraestructura_destino)));


