CREATE VIEW modulo3.vw_m03_03_bitacora_estado_sensor_con_lecturas AS
 SELECT l.id_lectura_sensor,
    l.id_sensor,
    l.nombre_sensor,
        CASE
            WHEN l.sensor_activo THEN 'ACTIVO'::text
            ELSE 'INACTIVO'::text
        END AS estado_sensor,
    eas.estado_semaforo AS estado_semaforo_sensor,
    (eas.estado_calidad)::text AS estado_calidad_actual_sensor,
    (eas.estado_desviacion)::text AS estado_desviacion_actual_sensor,
    l.dispositivo_nombre,
    l.infraestructura,
    l.finca,
    l.valor,
    l.unidad_medida,
    l.estado_lectura,
    l.origen_procesamiento AS mecanismo,
    l.fecha_captura,
    l.fecha_recepcion
   FROM (modulo3.vw_m03_lectura_contextualizada l
     LEFT JOIN modulo3.estados_actuales_sensores eas ON (((eas.id_estado_actual_sensor = l.id_sensor) AND (eas.id_dispositivo_iot = l.id_dispositivo_iot))));


