--
-- Name: vw_m03_alerta_contextualizada; Type: VIEW; Schema: modulo3; Owner: postgres
--

CREATE VIEW modulo3.vw_m03_alerta_contextualizada AS
 SELECT a.id_alerta AS id_alerta_telemetria,
    a.id_alerta,
    COALESCE(ra.nombre, ((a.tipo_alerta)::text)::character varying) AS nombre_alerta,
    (a.tipo_alerta)::text AS tipo_alerta,
    a.tipo_variable,
    (a.estado_alerta)::text AS estado_alerta,
    (a.severidad)::text AS nivel_criticidad,
    (a.origen_evento)::text AS origen_evento,
    COALESCE(tctx.valor, ee.valor_evaluado, pi.valor_numerico) AS valor_detectado,
        CASE
            WHEN ((a.origen_evento)::text = 'EDGE'::text) THEN 'EDGE'::text
            WHEN ((a.origen_evento)::text = 'IA'::text) THEN 'IA'::text
            WHEN ((a.origen_evento)::text = 'BACKEND'::text) THEN 'BACKEND'::text
            WHEN (a.id_evento_edge_computing IS NOT NULL) THEN 'EDGE'::text
            WHEN (a.id_paquete_inferencia IS NOT NULL) THEN 'IA'::text
            ELSE 'BACKEND'::text
        END AS como_se_genera,
    COALESCE(a.fecha_evento, ee.fecha_captura, tctx.timestamp_captura, pi.fecha_envio, a.fecha_registro) AS fecha_alerta,
    COALESCE(a.fecha_evento, ee.fecha_captura, tctx.timestamp_captura, pi.fecha_envio, a.fecha_registro) AS fecha_evento,
    a.fecha_generacion,
    a.fecha_notificacion,
    a.fecha_atencion,
    a.fecha_resolucion,
    a.fecha_vencimiento,
    a.id_regla_alerta,
    ra.nombre AS nombre_regla,
    ra.es_regla_compuesta,
    a.id_evento_edge_computing,
    (ee.tipo_evento)::text AS tipo_evento_edge,
    (ee.severidad)::text AS severidad_edge,
    a.id_telemetria,
    a.id_paquete_inferencia,
    (pi.estado_paquete)::text AS estado_paquete_inferencia,
    pi.intento_envios AS intentos_inferencia,
    COALESCE(a.id_sensor, tctx.id_sensor, ee.id_sensor, pi.id_sensor) AS id_sensor,
    COALESCE(tctx.nombre_sensor, s.nombre) AS nombre_sensor,
    COALESCE(a.id_dispositivo_ioit, tctx.id_dispositivo_iot, ee.id_dispositivo_iot, pi.id_dispositivo_iot) AS id_dispositivo_iot,
    COALESCE(tctx.dispositivo_nombre, d.descripcion) AS dispositivo_nombre,
    COALESCE(tctx.dispositivo_serial, d.serial) AS dispositivo_serial,
    COALESCE(a.id_infraestructura, tctx.id_infraestructura, saa.id_infraestructura, ab.id_infraestructura) AS id_infraestructura,
    i.nombre AS infraestructura,
    i.id_finca,
    f.nombre AS finca,
    COALESCE(a.id_activo_biologico, tctx.id_activo_biologico) AS id_activo_biologico,
    ab.identificador AS identificador_activo,
    (a.conflicto_resolucion)::text AS conflicto_resolucion,
    NULL::text AS severidad_edge_original,
    NULL::text AS severidad_ia,
    NULL::text AS tipo_edge_original,
    NULL::text AS tipo_ia_original,
    a.diagnostico,
    a.motivo_descarte,
    a.accion_sugerida,
    a.metadato_evento,
        CASE (a.estado_alerta)::text
            WHEN 'RESUELTA'::text THEN 'EXITOSO'::text
            WHEN 'DESCARTADA'::text THEN 'RECHAZADO'::text
            WHEN 'VENCIDA'::text THEN 'FALLIDO'::text
            WHEN 'EN_ATENCION'::text THEN 'PARCIAL'::text
            ELSE 'ADVERTENCIA'::text
        END AS resultado_evento,
    (a.tipo_alerta)::text AS nivel_alerta_raw
   FROM ((((((((((modulo3.alertas a
     LEFT JOIN modulo3.vw_m03_telemetria_contextualizada tctx ON ((tctx.id_telemetria = a.id_telemetria)))
     LEFT JOIN modulo3.eventos_edge_computing ee ON ((ee.id_evento_edge_computing = a.id_evento_edge_computing)))
     LEFT JOIN modulo3.paquetes_inferencia pi ON ((pi.id_paquetes_inferencia = a.id_paquete_inferencia)))
     LEFT JOIN modulo3.reglas_alertas ra ON ((ra.id_regla_alertas = a.id_regla_alerta)))
     LEFT JOIN modulo9.sensores s ON ((s.id_sensores = COALESCE(a.id_sensor, tctx.id_sensor, ee.id_sensor, pi.id_sensor))))
     LEFT JOIN modulo9.dispositivos_iot d ON ((d.id_dispositivo_iot = COALESCE(a.id_dispositivo_ioit, tctx.id_dispositivo_iot, ee.id_dispositivo_iot, pi.id_dispositivo_iot))))
     LEFT JOIN LATERAL ( SELECT x.id_infraestructura
           FROM modulo9.sensores_areas_asociadas x
          WHERE ((x.id_sensor = COALESCE(a.id_sensor, tctx.id_sensor, ee.id_sensor, pi.id_sensor)) AND (x.fecha_asociacion <= COALESCE(a.fecha_evento, ee.fecha_captura, tctx.timestamp_captura, pi.fecha_envio, a.fecha_registro)) AND ((x.fecha_finalizacion IS NULL) OR (x.fecha_finalizacion > COALESCE(a.fecha_evento, ee.fecha_captura, tctx.timestamp_captura, pi.fecha_envio, a.fecha_registro))))
          ORDER BY x.fecha_asociacion DESC, x.id_sensores_area_asociada DESC
         LIMIT 1) saa ON (true))
     LEFT JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = COALESCE(a.id_activo_biologico, tctx.id_activo_biologico))))
     LEFT JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = COALESCE(a.id_infraestructura, tctx.id_infraestructura, saa.id_infraestructura, ab.id_infraestructura))))
     LEFT JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)));


ALTER VIEW modulo3.vw_m03_alerta_contextualizada OWNER TO postgres;

