-- Name: vw_m03_pipeline_inferencia; Type: VIEW; Schema: modulo3; Owner: postgres
--

CREATE VIEW modulo3.vw_m03_pipeline_inferencia AS
 SELECT pi.id_paquetes_inferencia,
    pi.id_dispositivo_iot,
    d.dispositivo_nombre,
    d.dispositivo_serial,
    d.infraestructura,
    d.finca,
    pi.contexto_ambiental AS contexto,
    pi.contexto_incomplento AS contexto_incompleto,
    pi.tipo_variable,
    pi.valor_numerico AS valor,
    count(*) OVER (PARTITION BY pi.id_dispositivo_iot, pi.tipo_variable) AS registros,
    (pi.severidad)::text AS severidad,
    (pi.origen)::text AS origen,
    (pi.estado_calidad)::text AS estado_calidad,
    pi.intento_envios AS reintentos,
    (pi.estado_paquete)::text AS estado_paquete,
    pi.fecha_envio
   FROM (modulo3.paquetes_inferencia pi
     LEFT JOIN modulo3.vw_m03_dispositivo_operacional d ON ((d.id_dispositivo_iot = pi.id_dispositivo_iot)));


ALTER VIEW modulo3.vw_m03_pipeline_inferencia OWNER TO postgres;

--
-- Name: vw_m03_procesamiento_edge; Type: VIEW; Schema: modulo3; Owner: postgres
--

CREATE VIEW modulo3.vw_m03_procesamiento_edge AS
 WITH base AS (
         SELECT vw_m03_telemetria_contextualizada.id_telemetria,
            vw_m03_telemetria_contextualizada.id_sensor,
            vw_m03_telemetria_contextualizada.nombre_sensor,
            vw_m03_telemetria_contextualizada.id_variable,
            vw_m03_telemetria_contextualizada.variable_ambiental AS variable,
            vw_m03_telemetria_contextualizada.categoria_variable AS categoria,
            vw_m03_telemetria_contextualizada.valor,
            vw_m03_telemetria_contextualizada.unidad_medida,
            vw_m03_telemetria_contextualizada.valor_fisico_min AS minimo,
            vw_m03_telemetria_contextualizada.valor_fisico_max AS maximo,
            vw_m03_telemetria_contextualizada.ventana_agregacion_min AS ventana,
            vw_m03_telemetria_contextualizada.estado_calidad AS estado,
                CASE
                    WHEN ((vw_m03_telemetria_contextualizada.valor_fisico_min IS NULL) OR (vw_m03_telemetria_contextualizada.valor_fisico_max IS NULL)) THEN NULL::numeric
                    WHEN ((vw_m03_telemetria_contextualizada.valor < vw_m03_telemetria_contextualizada.valor_fisico_min) AND (NULLIF(abs(vw_m03_telemetria_contextualizada.valor_fisico_min), (0)::numeric) IS NOT NULL)) THEN round((((vw_m03_telemetria_contextualizada.valor_fisico_min - vw_m03_telemetria_contextualizada.valor) / NULLIF(abs(vw_m03_telemetria_contextualizada.valor_fisico_min), (0)::numeric)) * (100)::numeric), 2)
                    WHEN ((vw_m03_telemetria_contextualizada.valor > vw_m03_telemetria_contextualizada.valor_fisico_max) AND (NULLIF(abs(vw_m03_telemetria_contextualizada.valor_fisico_max), (0)::numeric) IS NOT NULL)) THEN round((((vw_m03_telemetria_contextualizada.valor - vw_m03_telemetria_contextualizada.valor_fisico_max) / NULLIF(abs(vw_m03_telemetria_contextualizada.valor_fisico_max), (0)::numeric)) * (100)::numeric), 2)
                    WHEN ((vw_m03_telemetria_contextualizada.valor < vw_m03_telemetria_contextualizada.valor_fisico_min) OR (vw_m03_telemetria_contextualizada.valor > vw_m03_telemetria_contextualizada.valor_fisico_max)) THEN NULL::numeric
                    ELSE (0)::numeric
                END AS desviacion_pct
           FROM modulo3.vw_m03_telemetria_contextualizada
        )
 SELECT id_telemetria,
    id_sensor,
    nombre_sensor,
    id_variable,
    variable,
    valor,
    unidad_medida,
    minimo,
    maximo,
    desviacion_pct AS nivel_desviacion_pct,
        CASE
            WHEN ((minimo IS NULL) OR (maximo IS NULL)) THEN 'SIN_RANGO'::text
            WHEN (desviacion_pct IS NULL) THEN 'ERROR_CONFIGURACION'::text
            WHEN (desviacion_pct = (0)::numeric) THEN 'NORMAL'::text
            WHEN (desviacion_pct <= (10)::numeric) THEN 'LEVE'::text
            WHEN (desviacion_pct <= (25)::numeric) THEN 'MODERADO'::text
            ELSE 'CRITICO'::text
        END AS nivel_desviacion,
    categoria,
    ventana,
    estado AS estado_calidad,
        CASE
            WHEN ((minimo IS NULL) OR (maximo IS NULL)) THEN 'SIN_RANGO'::text
            WHEN (desviacion_pct = (0)::numeric) THEN 'NORMAL'::text
            ELSE 'DESVIACION_SIMPLE'::text
        END AS estado_desviacion
   FROM base;


