--
-- Name: configuraciones_motor_ia; Type: TABLE; Schema: modulo4; Owner: postgres
--

CREATE TABLE modulo4.configuraciones_motor_ia (
    id_configuracion_motor integer NOT NULL,
    tipo_modelo modulo4.enum_tipo_modelo NOT NULL,
    umbral_riesgo_alto numeric(4,3) DEFAULT 0.700 NOT NULL,
    umbral_alerta_critica numeric(4,3) DEFAULT 0.700 NOT NULL,
    ventana_temporal_min integer DEFAULT 10 NOT NULL,
    id_version_modelo_activa integer,
    modo_ejecucion modulo4.enum_modo_ejecucion DEFAULT 'SERVIDOR'::modulo4.enum_modo_ejecucion NOT NULL,
    config_version integer DEFAULT 1 NOT NULL,
    w_factor_sanitario numeric(4,3) DEFAULT 0.500 NOT NULL,
    w_factor_ambiental numeric(4,3) DEFAULT 0.300 NOT NULL,
    w_factor_densidad numeric(4,3) DEFAULT 0.200 NOT NULL,
    temp_min_config numeric(6,2),
    temp_max_config numeric(6,2),
    hr_min_config numeric(6,2),
    hr_max_config numeric(6,2),
    densidad_maxima_config numeric(10,4),
    es_activa boolean DEFAULT true NOT NULL,
    id_usuario_responsable integer NOT NULL,
    fecha_creacion timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_pesos_contagio CHECK ((abs((((w_factor_sanitario + w_factor_ambiental) + w_factor_densidad) - 1.000)) < 0.001)),
    CONSTRAINT chk_umbral_critica_gte CHECK ((umbral_alerta_critica >= umbral_riesgo_alto)),
    CONSTRAINT chk_umbral_critica_rango CHECK (((umbral_alerta_critica >= 0.50) AND (umbral_alerta_critica <= 0.95))),
    CONSTRAINT chk_umbral_riesgo_rango CHECK (((umbral_riesgo_alto >= 0.50) AND (umbral_riesgo_alto <= 0.95))),
    CONSTRAINT chk_ventana_rango CHECK (((ventana_temporal_min >= 5) AND (ventana_temporal_min <= 15)))
);


