    hash_modelo_sha256 character varying(64) NOT NULL,
    resultado_validacion_hash boolean,
    id_version_modelo_anterior integer,
    rollback_ejecutado boolean DEFAULT false NOT NULL,
    intentos_descarga integer DEFAULT 0 NOT NULL,
    max_reintentos integer DEFAULT 3 NOT NULL,
    tamano_modelo_bytes bigint,
    tamano_descargado_bytes bigint,
    duracion_proceso_ms integer,
