--
-- Name: eventos_auditoria_m04; Type: TABLE; Schema: modulo4; Owner: postgres
--

CREATE TABLE modulo4.eventos_auditoria_m04 (
    id_evento uuid DEFAULT gen_random_uuid() NOT NULL,
    tipo_evento modulo4.enum_tipo_evento_auditoria_m04 NOT NULL,
    modulo character varying(10) DEFAULT 'MODULO4'::character varying NOT NULL,
    fecha_evento timestamp with time zone DEFAULT now() NOT NULL,
    tipo_actor modulo4.enum_tipo_actor_auditoria NOT NULL,
    id_usuario integer,
    id_sistema character varying(100),
    id_referencia character varying(100),
    entidad_referencia character varying(50),
    correlacion_id uuid DEFAULT gen_random_uuid() NOT NULL,
    payload_evento jsonb NOT NULL,
    es_payload_truncado boolean DEFAULT false NOT NULL,
    resultado_operacion modulo4.enum_resultado_operacion_auditoria,
    severidad_evento modulo4.enum_severidad_evento_auditoria DEFAULT 'INFO'::modulo4.enum_severidad_evento_auditoria NOT NULL,
    codigo_error character varying(50),
    descripcion_error text,
    origen_dato character varying(20),
    version_modelo character varying(40),
    latencia_ms integer,
    hash_evento character varying(64),
    origen_registro character varying(20) DEFAULT 'DIRECTO'::character varying NOT NULL,
    CONSTRAINT chk_eam_actor_exclusivo CHECK ((((tipo_actor = 'USUARIO'::modulo4.enum_tipo_actor_auditoria) AND (id_usuario IS NOT NULL) AND (id_sistema IS NULL)) OR ((tipo_actor = ANY (ARRAY['SISTEMA'::modulo4.enum_tipo_actor_auditoria, 'DISPOSITIVO_EDGE'::modulo4.enum_tipo_actor_auditoria])) AND (id_sistema IS NOT NULL) AND (id_usuario IS NULL))))
);


ALTER TABLE modulo4.eventos_auditoria_m04 OWNER TO postgres;

--
-- Name: TABLE eventos_auditoria_m04; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON TABLE modulo4.eventos_auditoria_m04 IS 'RF-73: Registro inmutable append-only de todos los eventos del módulo M04 (RF-64 a RF-72). Estructura base RF-10. Persistencia ≤2s. Payload máx. 64KB (truncado + payload_truncado=true si excede). hash_evento garantiza integridad. correlacion_id habilita trazabilidad end-to-end: RF-56→RF-66→RF-57→RF-72. origen_registro=FALLBACK para eventos sincronizados desde contingencia local.';


--
-- Name: COLUMN eventos_auditoria_m04.correlacion_id; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON COLUMN modulo4.eventos_auditoria_m04.correlacion_id IS 'RF-73: UUID que agrupa eventos del mismo flujo. Ejemplo: un paquete→inferencia→alerta→retroalimentación comparten el mismo correlacion_id.';


--
-- Name: COLUMN eventos_auditoria_m04.es_payload_truncado; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON COLUMN modulo4.eventos_auditoria_m04.es_payload_truncado IS 'RF-73: true si el payload_evento original superó 64KB y fue truncado. El contenido completo debe consultarse en el módulo fuente mediante id_referencia.';


--
-- Name: COLUMN eventos_auditoria_m04.hash_evento; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON COLUMN modulo4.eventos_auditoria_m04.hash_evento IS 'RF-73: SHA-256 del contenido del evento para verificar que no fue alterado post-persistencia. Garantiza integridad de registros.';


--
-- Name: COLUMN eventos_auditoria_m04.origen_registro; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON COLUMN modulo4.eventos_auditoria_m04.origen_registro IS 'RF-73: DIRECTO = persistido directamente al repositorio. FALLBACK = provino del mecanismo de contingencia local (log/buffer) al recuperarse el repositorio.';


