    fecha_evento timestamp with time zone DEFAULT now() NOT NULL,
    id_resultado_inferencia uuid NOT NULL,
    payload jsonb NOT NULL,
    CONSTRAINT chk_tipo_evento_historial CHECK (((tipo_evento)::text = ANY (ARRAY[('INFERENCIA'::character varying)::text, ('ALERTA'::character varying)::text, ('RETROALIMENTACION'::character varying)::text])))
);


ALTER TABLE modulo4.historial_diagnostico_eventos OWNER TO postgres;

--
-- Name: TABLE historial_diagnostico_eventos; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON TABLE modulo4.historial_diagnostico_eventos IS 'RF-67: Historial append-only de eventos diagnósticos por activo biológico. Tipos: INFERENCIA (RF-66), ALERTA (RF-57), RETROALIMENTACION (RF-72). Correlación obligatoria por id_resultado_inferencia (no por timestamp). Orden: timestamp DESC, id_evento DESC (determinístico). Paginación cursor-based (50 reg./pág.).';


--
-- Name: COLUMN historial_diagnostico_eventos.id_resultado_inferencia; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON COLUMN modulo4.historial_diagnostico_eventos.id_resultado_inferencia IS 'RF-67: Clave de correlación obligatoria entre inferencias, alertas y retroalimentación. No se permite correlación solo por timestamp.';


--
-- Name: historial_estados_modelos; Type: TABLE; Schema: modulo4; Owner: postgres
--

CREATE TABLE modulo4.historial_estados_modelos (
    id_historial_estado_modelo integer NOT NULL,
    id_version_modelo integer NOT NULL,
