    fecha_transicion timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE modulo4.historial_estados_modelos OWNER TO postgres;

--
-- Name: TABLE historial_estados_modelos; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON TABLE modulo4.historial_estados_modelos IS 'RF-69: Historial inmutable append-only de todas las transiciones de estado. Transiciones válidas: EN_VALIDACION→APROBADO/RECHAZADO (auto); APROBADO→ACTIVO (manual); ACTIVO→DEPRECADO (auto). Ninguna transición fuera de este flujo. Correlacion_id agrupa activación+deprecación atómica.';


--
-- Name: COLUMN historial_estados_modelos.correlacion_id; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON COLUMN modulo4.historial_estados_modelos.correlacion_id IS 'RF-69: UUID compartido entre la transición ACTIVO de la nueva versión y la DEPRECADO de la anterior, garantizando atomicidad en auditoría (E5 de RF-69).';


--
