--
-- Name: resultados_inferencia; Type: TABLE; Schema: modulo4; Owner: postgres
--

CREATE TABLE modulo4.resultados_inferencia (
    id_resultado_inferencia uuid DEFAULT gen_random_uuid() NOT NULL,
    id_paquete_inferencia integer,
    id_activo_biologico integer NOT NULL,
    id_especie integer NOT NULL,
    fase_productiva character varying(50),
    tipo_modelo modulo4.enum_tipo_modelo NOT NULL,
    id_version_modelo integer NOT NULL,
    nivel_riesgo smallint NOT NULL,
    probabilidad_riesgo jsonb NOT NULL,
    id_patologia integer,
    probabilidad_enfermedad jsonb NOT NULL,
    confianza_global numeric(5,4) NOT NULL,
    contexto_incompleto boolean DEFAULT false NOT NULL,
    latencia_excedida boolean DEFAULT false NOT NULL,
    modo_ejecucion modulo4.enum_modo_ejecucion NOT NULL,
    latencia_ms integer,
    fecha_inicio_ventana timestamp with time zone,
    fecha_fin_ventana timestamp with time zone,
    fecha_inferencia timestamp with time zone DEFAULT now() NOT NULL,
    tiene_alerta_generada boolean DEFAULT false NOT NULL,
    id_alerta_generada integer,
    CONSTRAINT resultados_inferencia_confianza_global_check CHECK (((confianza_global >= 0.0) AND (confianza_global <= 1.0))),
    CONSTRAINT resultados_inferencia_nivel_riesgo_check CHECK (((nivel_riesgo >= 0) AND (nivel_riesgo <= 3)))
);


ALTER TABLE modulo4.resultados_inferencia OWNER TO postgres;

--
-- Name: TABLE resultados_inferencia; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON TABLE modulo4.resultados_inferencia IS 'RF-66: Resultado inmutable del motor de inferencia en tiempo real. nivel_riesgo: 0=Normal, 1=Bajo, 2=Medio, 3=Alto. Si P(riesgo_alto) ≥ umbral_riesgo_alto se prioriza clase 3 (argmax). confianza_global se reduce 20% si contexto_incompleto=true. Latencia P95 ≤ 2s.';


--
-- Name: COLUMN resultados_inferencia.nivel_riesgo; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON COLUMN modulo4.resultados_inferencia.nivel_riesgo IS 'RF-66: Clasificación discreta. Si P(riesgo_alto) ≥ umbral_alerta_critica → alerta RF-57 tipo PREDICCION_PATOLOGIA con severidad CRITICO.';


--
-- Name: COLUMN resultados_inferencia.id_patologia; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON COLUMN modulo4.resultados_inferencia.id_patologia IS 'RF-66: ID de patología en RF-64 con mayor probabilidad (argmax sobre probabilidades de clase de enfermedad).';


--
-- Name: resultados_riesgo_contagio; Type: TABLE; Schema: modulo4; Owner: postgres
--

CREATE TABLE modulo4.resultados_riesgo_contagio (
    id_resultado_contagio integer NOT NULL,
    id_activo_biologico integer NOT NULL,
    id_configuracion_motor integer NOT NULL,
    factor_sanitario_fs numeric(6,4) NOT NULL,
    factor_ambiental_fa numeric(6,4),
    factor_densidad_fd numeric(6,4),
    w_fs_aplicado numeric(4,3) NOT NULL,
    w_fa_aplicado numeric(4,3) NOT NULL,
    w_fd_aplicado numeric(4,3) NOT NULL,
    probabilidad_contagio numeric(6,4) NOT NULL,
    nivel_riesgo_contagio smallint NOT NULL,
    confianza_baja boolean DEFAULT false NOT NULL,
    data_quality_score numeric(4,3),
    factores_ausentes jsonb,
    modo_ejecucion_calculo character varying(20) DEFAULT 'NORMAL'::character varying,
    n_enfermos_detectados integer,
    total_activos_lote integer,
    porcentaje_sensores_activos numeric(5,2),
    variables_ambientales_snap jsonb,
    fecha_calculo timestamp with time zone DEFAULT now() NOT NULL,
    id_alerta_generada integer,
    CONSTRAINT resultados_riesgo_contagio_data_quality_score_check CHECK (((data_quality_score >= 0.0) AND (data_quality_score <= 1.0))),
    CONSTRAINT resultados_riesgo_contagio_nivel_riesgo_contagio_check CHECK (((nivel_riesgo_contagio >= 0) AND (nivel_riesgo_contagio <= 2))),
    CONSTRAINT resultados_riesgo_contagio_probabilidad_contagio_check CHECK (((probabilidad_contagio >= 0.0) AND (probabilidad_contagio <= 1.0)))
);


ALTER TABLE modulo4.resultados_riesgo_contagio OWNER TO postgres;

--
-- Name: TABLE resultados_riesgo_contagio; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON TABLE modulo4.resultados_riesgo_contagio IS 'RF-68: Resultados del modelo P_contagio = W_fs*Fs + W_fa*Fa + W_fd*Fd. nivel_riesgo: 0=Bajo, 1=Medio, 2=Alto. Reglas: Fs>0.5 → mínimo MEDIO; Fs>0.7 → ALTO obligatorio. Si confianza_baja=true no se generan alertas críticas. data_quality_score<0.6 → modo degradado.';


--
-- Name: COLUMN resultados_riesgo_contagio.w_fs_aplicado; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON COLUMN modulo4.resultados_riesgo_contagio.w_fs_aplicado IS 'RF-68: Snapshot del peso W_fs usado en este cálculo (obtenido de configuraciones_motor_ia). Permite reproducibilidad del resultado.';


--
-- Name: COLUMN resultados_riesgo_contagio.data_quality_score; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON COLUMN modulo4.resultados_riesgo_contagio.data_quality_score IS 'RF-68: Score [0.0, 1.0] de calidad de datos. Depende de % activos con datos válidos, % sensores activos y frescura de timestamps. Si <0.6 → confianza_baja=true.';


--
-- Name: resultados_riesgo_contagio_id_resultado_contagio_seq; Type: SEQUENCE; Schema: modulo4; Owner: postgres
--

CREATE SEQUENCE modulo4.resultados_riesgo_contagio_id_resultado_contagio_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo4.resultados_riesgo_contagio_id_resultado_contagio_seq OWNER TO postgres;

--
-- Name: resultados_riesgo_contagio_id_resultado_contagio_seq; Type: SEQUENCE OWNED BY; Schema: modulo4; Owner: postgres
--

ALTER SEQUENCE modulo4.resultados_riesgo_contagio_id_resultado_contagio_seq OWNED BY modulo4.resultados_riesgo_contagio.id_resultado_contagio;


--
-- Name: retroalimentaciones_clinicas; Type: TABLE; Schema: modulo4; Owner: postgres
--

CREATE TABLE modulo4.retroalimentaciones_clinicas (
    id_retroalimentacion uuid DEFAULT gen_random_uuid() NOT NULL,
    id_resultado_inferencia uuid NOT NULL,
    id_activo_biologico integer NOT NULL,
    estado_retroalimentacion modulo4.enum_estado_retroalimentacion NOT NULL,
    diagnosticos_reales integer[],
    fuente_diagnostico modulo4.enum_fuente_diagnostico,
    es_fuente_desconocida boolean DEFAULT false NOT NULL,
    es_conflicto_retroalimentacion boolean DEFAULT false NOT NULL,
    observaciones_clinicas text,
    id_usuario_veterinario integer NOT NULL,
    fecha_retroalimentacion timestamp with time zone DEFAULT now() NOT NULL,
    estado_registro character varying(10) DEFAULT 'ACTIVO'::character varying NOT NULL,
    CONSTRAINT chk_diagnostico_obligatorio CHECK (((estado_retroalimentacion = ANY (ARRAY['CORRECTO'::modulo4.enum_estado_retroalimentacion, 'SIN_EVENTO'::modulo4.enum_estado_retroalimentacion])) OR (diagnosticos_reales IS NOT NULL))),
    CONSTRAINT chk_max_3_diagnosticos CHECK (((array_length(diagnosticos_reales, 1) IS NULL) OR (array_length(diagnosticos_reales, 1) <= 3))),
    CONSTRAINT chk_obs_max_500 CHECK ((char_length(observaciones_clinicas) <= 500))
);


ALTER TABLE modulo4.retroalimentaciones_clinicas OWNER TO postgres;

--
-- Name: TABLE retroalimentaciones_clinicas; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON TABLE modulo4.retroalimentaciones_clinicas IS 'RF-72: Retroalimentación clínica append-only del veterinario. Una por usuario por id_resultado_inferencia (UNIQUE). Hasta 3 diagnósticos para comorbilidades (primer elemento = patología principal para RF-71). Ventana de registro: 90 días por defecto (configurable 7-365 días en parametros_mlops). Si estado=PARCIAL/INCORRECTO sin fuente_diagnostico → fuente_desconocida=true.';


--
-- Name: COLUMN retroalimentaciones_clinicas.diagnosticos_reales; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON COLUMN modulo4.retroalimentaciones_clinicas.diagnosticos_reales IS 'RF-72: Array de IDs de patologías RF-64. Obligatorio si PARCIAL/INCORRECTO. RF-71 usa [0] como etiqueta primaria y [1],[2] como contexto de comorbilidad. Regla de prioridad para conflictos: LABORATORIO > HISTORIAL_CLINICO > OBSERVACION_DIRECTA > OTRO.';


--
-- Name: COLUMN retroalimentaciones_clinicas.es_conflicto_retroalimentacion; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON COLUMN modulo4.retroalimentaciones_clinicas.es_conflicto_retroalimentacion IS 'RF-72: true cuando el sistema detecta retroalimentaciones contradictorias sobre el mismo resultado entre diferentes veterinarios. Dispara evento CONFLICTO_RETROALIMENTACION en RF-73.';


