--
-- Name: COLUMN signos_clinicos.id_signo_clinico; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON COLUMN modulo4.signos_clinicos.id_signo_clinico IS 'ID único del signo clínico.';


