--
-- Name: COLUMN signos_clinicos.descripcion; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON COLUMN modulo4.signos_clinicos.descripcion IS 'Descripción médica del signo.';


--
-- Name: COLUMN signos_clinicos.escala_medicion; Type: COMMENT; Schema: modulo4; Owner: postgres
--

COMMENT ON COLUMN modulo4.signos_clinicos.escala_medicion IS 'Tipo de medición del signo (cualitativo/cuanti).';


--
