    descripcion text,
    fecha_entrenamiento timestamp with time zone,
    fecha_despliegue timestamp with time zone,
    fecha_retiro timestamp with time zone,
    accuracy numeric(5,4),
    auc_roc numeric(5,4),
    f1_score numeric(5,4),
    precision_modelo numeric(5,4),
    recall_modelo numeric(5,4),
    umbral_clasificacion numeric(5,4) DEFAULT 70.00 NOT NULL,
    ruta_artefacto text,
    hash_artecfacto character varying(64),
    esta_produccion boolean DEFAULT false NOT NULL,
    id_usuario integer,
    tipo_modelo modulo4.enum_tipo_modelo,
    estado_version modulo4.enum_estado_version_modelo DEFAULT 'EN_VALIDACION'::modulo4.enum_estado_version_modelo NOT NULL,
    hash_artefacto_sha256 character varying(64),
    dataset_entrenamiento_hash character varying(64),
    id_proceso_rf71 uuid,
    notas_validacion text,
    compatibilidad_variables jsonb,
    version_referencia integer,
    formato_artefacto modulo4.enum_formato_artefacto,
