    matriz_confusion jsonb,
    tamanio_artefacto_bytes bigint,
    detalle_validacion text,
    fecha_registro timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_auc CHECK (((auc_roc >= (0)::numeric) AND (auc_roc <= (1)::numeric))),
    CONSTRAINT chk_umbral_version CHECK (((umbral_clasificacion >= (0)::numeric) AND (umbral_clasificacion <= (100)::numeric)))
);


