--
-- Name: vw_catalogo_patologias; Type: VIEW; Schema: modulo4; Owner: postgres
--

CREATE VIEW modulo4.vw_catalogo_patologias AS
 SELECT p.id_patologia,
    p.nombre AS nombre_patologia,
    p.nombre_tecnico,
    e.id_especie,
    COALESCE(e.nombre, 'Sin especie asociada'::character varying) AS especie,
    COALESCE(vars.variables_sensoricas_asociadas, 'Sin variables asociadas'::text) AS variables_sensoricas_asociadas,
    p.categoria AS tipo_patologia,
        CASE
            WHEN (p.es_activo IS TRUE) THEN 'ACTIVA'::text
            ELSE 'INACTIVA'::text
        END AS estado,
    p.codigo_cie,
    p.descripcion
   FROM (((modulo9.patologias p
     LEFT JOIN modulo9.especies_patologias ep ON ((ep.id_patologia = p.id_patologia)))
     LEFT JOIN modulo9.especies e ON ((e.id_especie = ep.id_especie)))
     LEFT JOIN LATERAL ( SELECT string_agg(DISTINCT (va.nombre)::text, ', '::text ORDER BY (va.nombre)::text) AS variables_sensoricas_asociadas
           FROM (modulo9.umbrales_ambientales ua
             JOIN modulo9.variables_ambientales va ON ((va.id_variable_ambiental = ua.id_variable_ambiental)))
          WHERE ((ua.id_especie = e.id_especie) AND (ua.es_activo IS TRUE) AND (va.es_activo IS TRUE))) vars ON (true));


ALTER VIEW modulo4.vw_catalogo_patologias OWNER TO postgres;

--
-- Name: vw_configuracion_motor; Type: VIEW; Schema: modulo4; Owner: postgres
--

CREATE VIEW modulo4.vw_configuracion_motor AS
 WITH versiones_por_patologia AS (
         SELECT DISTINCT pred.id_patologia,
            pred.id_version_modelo
           FROM modulo4.predicciones pred
        )
 SELECT ps.id_patologia_signo,
    pat.id_patologia,
    pat.nombre AS patologia,
    COALESCE(e.nombre, 'Sin especie asociada'::character varying) AS especie,
    ps.peso_relativo AS peso_umbral,
    ps.sensibilidad AS sensibilidad_umbral,
    vm.id_version_modelo,
    vm.nombre_version AS version_modelo,
    vm.algoritmo AS tipo_modelo,
        CASE
            WHEN (vm.id_version_modelo IS NULL) THEN 'SIN_VERSION_ASOCIADA'::text
            WHEN (vm.esta_produccion IS TRUE) THEN 'PRODUCCION'::text
            WHEN (vm.fecha_retiro IS NOT NULL) THEN 'RETIRADO'::text
            WHEN (vm.fecha_despliegue IS NOT NULL) THEN 'DESPLEGADO_NO_PRODUCCION'::text
            ELSE 'ENTRENAMIENTO'::text
        END AS modo_ejecucion
   FROM (((((modulo4.patologias_signos ps
     JOIN modulo9.patologias pat ON ((pat.id_patologia = ps.id_patologia)))
     LEFT JOIN modulo9.especies_patologias ep ON ((ep.id_patologia = pat.id_patologia)))
     LEFT JOIN modulo9.especies e ON ((e.id_especie = ep.id_especie)))
     LEFT JOIN versiones_por_patologia vp ON ((vp.id_patologia = pat.id_patologia)))
     LEFT JOIN modulo4.versiones_modelos vm ON ((vm.id_version_modelo = vp.id_version_modelo)));


ALTER VIEW modulo4.vw_configuracion_motor OWNER TO postgres;

--
-- Name: vw_m04_caracteristicas_version_modelo; Type: VIEW; Schema: modulo4; Owner: postgres
--

CREATE VIEW modulo4.vw_m04_caracteristicas_version_modelo AS
 SELECT vm.id_version_modelo,
    vm.nombre_version AS version_modelo,
    vm.algoritmo AS tipo_modelo,
    vm.descripcion,
    vm.umbral_clasificacion AS umbral_modelo,
    vm.accuracy,
    vm.auc_roc,
    vm.f1_score,
    vm.precision_modelo,
    vm.recall_modelo AS sensibilidad,
    vm.ruta_artefacto,
    vm.hash_artecfacto,
    vm.esta_produccion,
    COALESCE(ds.total_datasets, (0)::bigint) AS total_datasets,
    COALESCE(ds.datasets, '[]'::jsonb) AS datasets,
    COALESCE(md.total_metricas_drift, (0)::bigint) AS total_metricas_drift,
    COALESCE(md.tiene_drift_alertado, false) AS tiene_drift_alertado,
    COALESCE(md.metricas_drift, '[]'::jsonb) AS metricas_drift
   FROM ((modulo4.versiones_modelos vm
     LEFT JOIN LATERAL ( SELECT count(*) AS total_datasets,
            jsonb_agg(jsonb_build_object('id_dataset', d.id_dataset, 'nombre', d.nombre, 'fecha_inicio_datos', d.fecha_inicio_datos, 'fecha_fin_datos', d.fecha_fin_datos, 'total_registros', d.total_resgistros, 'registros_positivos', d.registros_positivos, 'registros_negativos', d.registros_negativos, 'porcentaje_train', d.porcentaje_train, 'porcentaje_test', d.porcentaje_test, 'tiene_variables_ambientales', d.tiene_variables_ambientales, 'semestre_huila', d.semestre_huila, 'enfermedades_incluidas', d.enfermedades_incluidas) ORDER BY d.fecha_inicio_datos, d.id_dataset) AS datasets
           FROM modulo4.datasets d
          WHERE (d.id_version_modelo = vm.id_version_modelo)) ds ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS total_metricas_drift,
            bool_or(m.supera_umbral_drift) AS tiene_drift_alertado,
            jsonb_agg(jsonb_build_object('id_metrica_drift', m.id_metrica_drift, 'fecha_calculo', m.fecha_calculo, 'tipo_metrica', m.tipo_metrica, 'feature_evaluado', m.feature_evaluado, 'valor_metrica', m.valor_metrica, 'umbral_alerta_drift', m.umbral_alerta_drift, 'supera_umbral_drift', m.supera_umbral_drift, 'periodo_referencia', m.periodo_referencia, 'periodo_actual', m.periodo_actual, 'accion_tomada', m.accion_tomada) ORDER BY m.fecha_calculo DESC, m.id_metrica_drift DESC) AS metricas_drift
           FROM modulo4.metricas_drift m
          WHERE (m.id_modelo_version = vm.id_version_modelo)) md ON (true));


ALTER VIEW modulo4.vw_m04_caracteristicas_version_modelo OWNER TO postgres;

--
-- Name: vw_m04_distribucion_modelos; Type: VIEW; Schema: modulo4; Owner: postgres
--

CREATE VIEW modulo4.vw_m04_distribucion_modelos AS
 SELECT vm.id_version_modelo,
    vm.algoritmo AS tipo_modelo,
    vm.nombre_version AS version_modelo,
        CASE
            WHEN (vm.esta_produccion IS TRUE) THEN 'PRODUCCION'::text
            WHEN (vm.fecha_retiro IS NOT NULL) THEN 'RETIRADO'::text
            WHEN (vm.fecha_despliegue IS NOT NULL) THEN 'DESPLEGADO_NO_PRODUCCION'::text
            ELSE 'ENTRENAMIENTO'::text
        END AS estado_modelo,
    COALESCE(vm.fecha_despliegue, vm.fecha_entrenamiento) AS inicio,
    COALESCE(dispositivos.cantidad_dispositivos, (0)::bigint) AS cantidad_dispositivos,
    COALESCE(dispositivos.dispositivos_modelo, 'Sin dispositivo asociado'::text) AS dispositivos_modelo,
    COALESCE(dispositivos.infraestructura, 'Sin infraestructura asociada'::text) AS infraestructura,
    COALESCE(dispositivos.finca, 'Sin finca asociada'::text) AS finca
   FROM (modulo4.versiones_modelos vm
     LEFT JOIN LATERAL ( SELECT count(DISTINCT d.id_dispositivo_iot) AS cantidad_dispositivos,
            string_agg(DISTINCT concat(d.serial, ' - ', d.descripcion), ', '::text ORDER BY (concat(d.serial, ' - ', d.descripcion))) FILTER (WHERE (d.id_dispositivo_iot IS NOT NULL)) AS dispositivos_modelo,
            string_agg(DISTINCT (i.nombre)::text, ', '::text ORDER BY (i.nombre)::text) AS infraestructura,
            string_agg(DISTINCT (f.nombre)::text, ', '::text ORDER BY (f.nombre)::text) AS finca
           FROM (((((modulo4.predicciones pred
             JOIN modulo4.observaciones_clinicas oc ON ((oc.id_observacion_clinica = pred.id_observacion)))
             JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = oc.id_activo_biologico)))
             JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)))
             JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)))
             LEFT JOIN modulo9.dispositivos_iot d ON ((d.id_dispositivo_iot = ab.id_dispositivo_iot)))
          WHERE (pred.id_version_modelo = vm.id_version_modelo)) dispositivos ON (true));


ALTER VIEW modulo4.vw_m04_distribucion_modelos OWNER TO postgres;

--
-- Name: vw_m04_eventos_auditoria_modelos; Type: VIEW; Schema: modulo4; Owner: postgres
--

CREATE VIEW modulo4.vw_m04_eventos_auditoria_modelos AS
 WITH eventos_predicciones AS (
         SELECT ('AUDITORIA_PREDICCION-'::text || ap.id_auditoria_prediccion) AS id_evento,
            (ap.fecha_accion)::timestamp without time zone AS fecha_evento,
            (ap.accion)::text AS tipo_evento,
                CASE
                    WHEN ((ap.accion)::text = 'ALERTA_ACTIVADA'::text) THEN 'CRITICAL'::text
                    WHEN ((ap.accion)::text = 'UPDATE'::text) THEN 'WARNING'::text
                    ELSE 'INFO'::text
                END AS severidad,
            COALESCE(ap.servicio_origen, 'modulo4.auditorias_predicciones'::character varying) AS origen,
            'EXITOSO'::text AS resultado,
            'modulo4.auditorias_predicciones'::text AS tabla_auditoria,
            ap.id_auditoria_prediccion AS id_registro_auditoria,
            ap.id_prediccion,
            pred.id_version_modelo,
            (vm.algoritmo)::text AS modelo,
            vm.nombre_version AS version_modelo,
            pat.nombre AS patologia,
            ap.id_usuario,
            concat_ws(' '::text, u.nombre, u.apellidos) AS usuario_responsable,
            ap.datos_anteriores,
            ap.datos_nuevos
           FROM ((((modulo4.auditorias_predicciones ap
             JOIN modulo4.predicciones pred ON ((pred.id_prediccion = ap.id_prediccion)))
             JOIN modulo4.versiones_modelos vm ON ((vm.id_version_modelo = pred.id_version_modelo)))
             JOIN modulo9.patologias pat ON ((pat.id_patologia = pred.id_patologia)))
             LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = ap.id_usuario)))
        ), logs_base AS (
         SELECT ld.id_log,
            ld.fecha_evento,
            ld.usuario_bd,
            ld.rol_bd,
            ld.esquema_afectado,
            ld.tabla_afectada,
            ld.tipo_operacion,
            ld.datos_anteriores,
            ld.datos_nuevos,
            ld.ip_cliente,
            ld.aplicacion,
            ld.query_sql,
            COALESCE((ld.datos_nuevos ->> 'id_prediccion'::text), (ld.datos_anteriores ->> 'id_prediccion'::text)) AS id_prediccion_txt,
            COALESCE((ld.datos_nuevos ->> 'id_version_modelo'::text), (ld.datos_anteriores ->> 'id_version_modelo'::text)) AS id_version_modelo_txt,
            COALESCE((ld.datos_nuevos ->> 'id_usuario'::text), (ld.datos_anteriores ->> 'id_usuario'::text)) AS id_usuario_txt
           FROM auditoria.logs_dml ld
          WHERE ((ld.esquema_afectado = 'modulo4'::text) AND (ld.tabla_afectada = ANY (ARRAY['predicciones'::text, 'versiones_modelos'::text, 'auditorias_predicciones'::text, 'alertas_patologicas'::text, 'metricas_drift'::text, 'datasets'::text])))
        ), eventos_dml AS (
         SELECT ('LOG_DML-'::text || lb.id_log) AS id_evento,
            lb.fecha_evento,
            lb.tipo_operacion AS tipo_evento,
                CASE
                    WHEN (lb.tipo_operacion = 'DELETE'::text) THEN 'CRITICAL'::text
                    WHEN (lb.tipo_operacion = 'UPDATE'::text) THEN 'WARNING'::text
                    ELSE 'INFO'::text
                END AS severidad,
            COALESCE(lb.aplicacion, lb.ip_cliente, lb.usuario_bd, 'auditoria.logs_dml'::text) AS origen,
            'EXITOSO'::text AS resultado,
            'auditoria.logs_dml'::text AS tabla_auditoria,
            lb.id_log AS id_registro_auditoria,
            pred.id_prediccion,
            vm.id_version_modelo,
            (vm.algoritmo)::text AS modelo,
            vm.nombre_version AS version_modelo,
            pat.nombre AS patologia,
                CASE
                    WHEN (lb.id_usuario_txt ~ '^[0-9]+$'::text) THEN (lb.id_usuario_txt)::integer
                    ELSE NULL::integer
                END AS id_usuario,
            concat_ws(' '::text, u.nombre, u.apellidos) AS usuario_responsable,
            lb.datos_anteriores,
            lb.datos_nuevos
           FROM ((((logs_base lb
             LEFT JOIN modulo4.predicciones pred ON ((pred.id_prediccion =
                CASE
                    WHEN (lb.id_prediccion_txt ~ '^[0-9]+$'::text) THEN (lb.id_prediccion_txt)::integer
                    ELSE NULL::integer
                END)))
             LEFT JOIN modulo4.versiones_modelos vm ON ((vm.id_version_modelo = COALESCE(pred.id_version_modelo,
                CASE
                    WHEN (lb.id_version_modelo_txt ~ '^[0-9]+$'::text) THEN (lb.id_version_modelo_txt)::integer
                    ELSE NULL::integer
                END))))
             LEFT JOIN modulo9.patologias pat ON ((pat.id_patologia = pred.id_patologia)))
             LEFT JOIN modulo1.usuarios u ON ((u.id_usuario =
                CASE
                    WHEN (lb.id_usuario_txt ~ '^[0-9]+$'::text) THEN (lb.id_usuario_txt)::integer
                    ELSE NULL::integer
                END)))
        ), eventos_base AS (
         SELECT eventos_predicciones.id_evento,
            eventos_predicciones.fecha_evento,
            eventos_predicciones.tipo_evento,
            eventos_predicciones.severidad,
            eventos_predicciones.origen,
            eventos_predicciones.resultado,
            eventos_predicciones.tabla_auditoria,
            eventos_predicciones.id_registro_auditoria,
            eventos_predicciones.id_prediccion,
            eventos_predicciones.id_version_modelo,
            eventos_predicciones.modelo,
            eventos_predicciones.version_modelo,
            eventos_predicciones.patologia,
            eventos_predicciones.id_usuario,
            eventos_predicciones.usuario_responsable,
            eventos_predicciones.datos_anteriores,
            eventos_predicciones.datos_nuevos
           FROM eventos_predicciones
        UNION ALL
         SELECT eventos_dml.id_evento,
            eventos_dml.fecha_evento,
            eventos_dml.tipo_evento,
            eventos_dml.severidad,
            eventos_dml.origen,
            eventos_dml.resultado,
            eventos_dml.tabla_auditoria,
            eventos_dml.id_registro_auditoria,
            eventos_dml.id_prediccion,
            eventos_dml.id_version_modelo,
            eventos_dml.modelo,
            eventos_dml.version_modelo,
            eventos_dml.patologia,
            eventos_dml.id_usuario,
            eventos_dml.usuario_responsable,
            eventos_dml.datos_anteriores,
            eventos_dml.datos_nuevos
           FROM eventos_dml
        )
 SELECT id_evento,
    fecha_evento,
    date_trunc('day'::text, fecha_evento) AS fecha_inicio_rango,
    ((date_trunc('day'::text, fecha_evento) + '1 day'::interval) - '00:00:00.000001'::interval) AS fecha_fin_rango,
    tipo_evento,
    severidad,
    origen,
    resultado,
    tabla_auditoria,
    id_registro_auditoria,
    id_prediccion,
    id_version_modelo,
    modelo,
    version_modelo,
    patologia,
    id_usuario,
    usuario_responsable,
    datos_anteriores,
    datos_nuevos
   FROM eventos_base;


ALTER VIEW modulo4.vw_m04_eventos_auditoria_modelos OWNER TO postgres;

--
-- Name: vw_m04_gestion_modelos_ia; Type: VIEW; Schema: modulo4; Owner: postgres
--

CREATE VIEW modulo4.vw_m04_gestion_modelos_ia AS
 SELECT vm.id_version_modelo,
    vm.nombre_version AS version_modelo,
    vm.algoritmo AS tipo_modelo,
        CASE
            WHEN (vm.esta_produccion IS TRUE) THEN 'PRODUCCION'::text
            WHEN (vm.fecha_retiro IS NOT NULL) THEN 'RETIRADO'::text
            WHEN (vm.fecha_despliegue IS NOT NULL) THEN 'DESPLEGADO_NO_PRODUCCION'::text
            ELSE 'ENTRENAMIENTO'::text
        END AS estado_modelo,
    vm.f1_score,
    vm.recall_modelo AS sensibilidad,
    vm.precision_modelo,
    vm.accuracy,
    vm.auc_roc,
    vm.fecha_entrenamiento,
    vm.fecha_despliegue,
    vm.fecha_retiro,
    u.id_usuario AS id_usuario_responsable,
    concat_ws(' '::text, u.nombre, u.apellidos) AS usuario_responsable
   FROM (modulo4.versiones_modelos vm
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = vm.id_usuario)));


ALTER VIEW modulo4.vw_m04_gestion_modelos_ia OWNER TO postgres;

--
-- Name: vw_m04_historial_diagnostico; Type: VIEW; Schema: modulo4; Owner: postgres
--

CREATE VIEW modulo4.vw_m04_historial_diagnostico AS
 SELECT oc.id_observacion_clinica,
    ab.id_activo_biologico,
    ab.identificador AS activo_biologico,
    ab.tipo AS tipo_activo,
    e.id_especie,
    e.nombre AS especie,
    oc.fecha,
    jsonb_build_object('temperatura_rectal', oc.temperatura_rectal, 'frecuencia_cardiaca', oc.frecuencia_cardiaca, 'frecuencia_respiratoria', oc.frecuencia_respiratoria, 'condicion_corporal', oc.condicion_corporal, 'fuente_datos', oc.fuente_datos, 'observacion', oc.observacion, 'validada_por_veterinario', COALESCE(bool_or(((ap.accion)::text = 'VALIDACION_VET'::text)), false)) AS condiciones,
    COALESCE(string_agg(DISTINCT (pat.nombre)::text, ', '::text ORDER BY (pat.nombre)::text), 'Sin prediccion asociada'::text) AS patologia,
    count(DISTINCT pred.id_prediccion) AS total_predicciones_asociadas,
    u.id_usuario,
    concat_ws(' '::text, u.nombre, u.apellidos) AS usuario_responsable
   FROM ((((((modulo4.observaciones_clinicas oc
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = oc.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     LEFT JOIN modulo4.predicciones pred ON ((pred.id_observacion = oc.id_observacion_clinica)))
     LEFT JOIN modulo9.patologias pat ON ((pat.id_patologia = pred.id_patologia)))
     LEFT JOIN modulo4.auditorias_predicciones ap ON ((ap.id_prediccion = pred.id_prediccion)))
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = oc.id_usuario)))
  GROUP BY oc.id_observacion_clinica, ab.id_activo_biologico, ab.identificador, ab.tipo, e.id_especie, e.nombre, oc.fecha, oc.temperatura_rectal, oc.frecuencia_cardiaca, oc.frecuencia_respiratoria, oc.condicion_corporal, oc.fuente_datos, oc.observacion, u.id_usuario, u.nombre, u.apellidos;


ALTER VIEW modulo4.vw_m04_historial_diagnostico OWNER TO postgres;

--
-- Name: vw_m04_monitoreo_inferencia; Type: VIEW; Schema: modulo4; Owner: postgres
--

CREATE VIEW modulo4.vw_m04_monitoreo_inferencia AS
 SELECT pred.id_prediccion,
    ab.id_activo_biologico,
    f.nombre AS finca,
    ab.identificador AS activo_biologico,
    ab.tipo AS tipo_activo,
    e.id_especie,
    e.nombre AS especie,
    pat.id_patologia,
    pat.nombre AS patologia,
    vm.id_version_modelo,
    vm.nombre_version AS version_modelo,
    vm.algoritmo AS tipo_modelo,
    pred.probabilidad_pct,
    pred.umbral_usado,
    pred.supera_umbral,
    COALESCE(alerta.nivel_criticidad, (
        CASE
            WHEN (pred.probabilidad_pct >= (90)::numeric) THEN 'CRITICO'::text
            WHEN (pred.supera_umbral IS TRUE) THEN 'ALTO'::text
            WHEN (pred.probabilidad_pct >= (pred.umbral_usado * 0.75)) THEN 'MEDIO'::text
            ELSE 'BAJO'::text
        END)::character varying) AS nivel_riesgo,
    pred.confianza_modelo AS confianza,
    pred.tiempo_proceso_ms,
    pred.features_json,
    pred.fecha_prediccion,
    oc.id_observacion_clinica,
    oc.fecha AS fecha_observacion_clinica
   FROM ((((((((modulo4.predicciones pred
     JOIN modulo4.observaciones_clinicas oc ON ((oc.id_observacion_clinica = pred.id_observacion)))
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = oc.id_activo_biologico)))
     LEFT JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)))
     LEFT JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo9.patologias pat ON ((pat.id_patologia = pred.id_patologia)))
     JOIN modulo4.versiones_modelos vm ON ((vm.id_version_modelo = pred.id_version_modelo)))
     LEFT JOIN modulo4.alertas_patologicas alerta ON ((alerta.id_prediccion = pred.id_prediccion)));


ALTER VIEW modulo4.vw_m04_monitoreo_inferencia OWNER TO postgres;

