    fecha_registro timestamp with time zone DEFAULT now(),
    id_usuario integer,
    estado_registro character varying(20) DEFAULT 'VALIDADO'::character varying NOT NULL,
    fecha_consumo date,
    hora_suministro time without time zone,
    costo_unitario numeric(14,4),
    consumo_por_individuo_kg numeric(10,4),
    justificacion_anulacion character varying(255),
    fecha_hora_anulacion timestamp with time zone,
    id_registro_rf75 uuid DEFAULT gen_random_uuid(),
    CONSTRAINT chk_consumo_anulacion CHECK ((((estado_registro)::text = 'VALIDADO'::text) OR (((estado_registro)::text = 'ANULADO'::text) AND (justificacion_anulacion IS NOT NULL) AND (char_length((justificacion_anulacion)::text) >= 20))))
);


