--
-- Name: vw_m05_aplicacion_medicamentos; Type: VIEW; Schema: modulo5; Owner: postgres
--

CREATE VIEW modulo5.vw_m05_aplicacion_medicamentos AS
 SELECT rm.id_registro_medicamento,
    rm.id_registro_rf76,
    ab.id_activo_biologico,
    ab.identificador AS identificador_activo,
    ab.tipo AS tipo_activo,
    e.nombre AS especie,
    f.nombre AS finca,
    i.nombre AS infraestructura,
    cp.nombre AS ciclo_productivo,
    dabp.cantidad_actual AS individuos_en_lote,
    rm.nombre_medicamento,
    rm.descripcion_clinica,
    rm.unidad_dosis,
    rm.cantidad AS cantidad_dosis,
    rm.dosis_por_individuo,
    rm.via_aplicacion,
    rm.lote_medicameto AS lote_medicamento,
    rm.fehca_vencimietno_lote AS fecha_vencimiento_lote,
    rm.motivo_aplicacion,
    rm.costo_unitario_medicamento,
    rm.costo_total_medicamento,
    rm.periodo_retiro_dias,
    rm.fecha_fin_retiro AS retiro_hasta,
        CASE
            WHEN (rm.fecha_fin_retiro IS NULL) THEN 'SIN_RETIRO'::text
            WHEN (rm.fecha_fin_retiro > CURRENT_DATE) THEN 'EN_RETIRO'::text
            ELSE 'RETIRO_CUMPLIDO'::text
        END AS estado_retiro,
    rm.fecha_aplicacion,
    rm.hora_aplicacion,
    rm.fecha_registro,
    rm.estado_registro,
    rm.justificacion_anulacion,
    rm.fecha_hora_anulacion,
    rm.id_evento_sanitario,
    (((u_reg.nombre)::text || ' '::text) || (u_reg.apellidos)::text) AS registrado_por,
    (((u_vet.nombre)::text || ' '::text) || (u_vet.apellidos)::text) AS veterinario
   FROM (((((((((modulo5.registros_medicamentos rm
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = rm.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)))
     JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)))
     LEFT JOIN modulo1.usuarios u_reg ON ((u_reg.id_usuario = rm.id_usuario)))
     LEFT JOIN modulo1.usuarios u_vet ON ((u_vet.id_usuario = rm.id_usuario_veterinario)))
     LEFT JOIN modulo2.gestiones_fases gf ON (((gf.id_activo_biologico = ab.id_activo_biologico) AND (gf.es_activa = true))))
     LEFT JOIN modulo9.ciclos_productivos cp ON ((cp.id_ciclo_productivo = gf.id_ciclo_productiva)))
     LEFT JOIN modulo2.detalles_activos_biologicos_poblacionales dabp ON ((dabp.id_activo_biologico = ab.id_activo_biologico)));


ALTER VIEW modulo5.vw_m05_aplicacion_medicamentos OWNER TO postgres;

--
-- Name: VIEW vw_m05_aplicacion_medicamentos; Type: COMMENT; Schema: modulo5; Owner: postgres
--

COMMENT ON VIEW modulo5.vw_m05_aplicacion_medicamentos IS 'RF-76. Lista de registros de aplicación de medicamentos. Columnas del mockup: Activo, Especie/Finca, Medicamento, Fecha y hora, Dosis, Vía, Retiro hasta, Costo total, Estado, Veterinario. Calcula estado_retiro para el semáforo de período de retiro.';


--
-- Name: vw_m05_costos_produccion; Type: VIEW; Schema: modulo5; Owner: postgres
--

CREATE VIEW modulo5.vw_m05_costos_produccion AS
 SELECT rs.id_registro_suministro,
    ab.id_activo_biologico,
    ab.identificador AS identificador_activo,
    e.nombre AS especie,
    f.nombre AS finca,
    cp.id_ciclo_productivo,
    cp.nombre AS ciclo_productivo,
    ac.acumulado_total_ciclo,
    ac.acumulado_por_categoria,
    ac.version_acumulado,
    ac.fecha_ultima_actualizacion AS acumulado_actualizado_en,
    ac.estado AS estado_acumulado,
    rs.naturaleza_costo,
    rs.unidad_medida,
    rs.cantidad,
    rs.precio_unitario_resuelto AS precio_unitario,
    rs.costo_registro AS costo,
    rs.origen_precio,
    rs.fecha_aplicacion,
    rs.fecha_registro,
    rs.tipo_operacion,
    rs.observacion,
    rs.motivo_correccion,
    rs.id_registro_original,
    NULL::text AS registrado_por
   FROM ((((((modulo5.registro_suministro rs
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = rs.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)))
     JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)))
     JOIN modulo9.ciclos_productivos cp ON ((cp.id_ciclo_productivo = rs.id_ciclo_productivo)))
     LEFT JOIN modulo5.acumulado_ciclo ac ON ((ac.id_gestion_fases = rs.id_gestion_fases)));


ALTER VIEW modulo5.vw_m05_costos_produccion OWNER TO postgres;

--
-- Name: VIEW vw_m05_costos_produccion; Type: COMMENT; Schema: modulo5; Owner: postgres
--

COMMENT ON VIEW modulo5.vw_m05_costos_produccion IS 'RF-78. Costos de producción por ciclo productivo. Combina el acumulado del ciclo con el detalle de cada registro de suministro.';


--
-- Name: vw_m05_eficiencia_alimenticia; Type: VIEW; Schema: modulo5; Owner: postgres
--

CREATE VIEW modulo5.vw_m05_eficiencia_alimenticia AS
 SELECT ab.id_activo_biologico,
    ab.identificador AS identificador_activo,
    e.nombre AS especie,
    f.nombre AS finca,
    i.nombre AS infraestructura,
    ica.id_resultado_ica,
    ica.periodo_evaluacion,
    ica.fecha_inicio_periodo,
    ica.fecha_fin_periodo,
    ica.alimento_consumido_total_kg,
    ica.ganancia_peso_kg,
    ica.ca_calculado AS indice_conversion_alimenticia,
    ica.clasificacion_ca AS clasificacion_ica,
    ica.data_quality_score,
    ica.causa_no_calculo,
    ica.tipo_calculo,
    ica.fecha_calculo AS fecha_ultimo_calculo,
        CASE
            WHEN (ica.data_quality_score IS NULL) THEN 'SIN_DATOS'::text
            WHEN (ica.data_quality_score >= 80) THEN 'BUENA'::text
            WHEN (ica.data_quality_score >= 50) THEN 'REGULAR'::text
            ELSE 'CRITICA'::text
        END AS calidad_datos_semaforo,
        CASE
            WHEN (ica.clasificacion_ca IS NULL) THEN 'SIN_DATOS'::text
            WHEN ((ica.clasificacion_ca)::text = ANY (ARRAY['CRITICA'::text, 'MUY_BAJA'::text])) THEN 'CRITICA'::text
            WHEN ((ica.clasificacion_ca)::text = 'BAJA'::text) THEN 'BAJA'::text
            ELSE 'NORMAL'::text
        END AS nivel_eficiencia,
    (((u.nombre)::text || ' '::text) || (u.apellidos)::text) AS registrado_por,
    ica.creado_en AS fecha_registro
   FROM (((((modulo2.activos_biologicos ab
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)))
     JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)))
     LEFT JOIN modulo5.resultado_ica ica ON (((ica.id_activo_biologico = ab.id_activo_biologico) AND (ica.fecha_calculo = ( SELECT max(ica2.fecha_calculo) AS max
           FROM modulo5.resultado_ica ica2
          WHERE (ica2.id_activo_biologico = ab.id_activo_biologico))))))
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = ica.id_usuario)))
  WHERE (ab.id_estado IN ( SELECT estados_activos_biologicos.id_estado_activo_biologico
           FROM modulo2.estados_activos_biologicos
          WHERE ((estados_activos_biologicos.nombre)::text <> ALL (ARRAY[('BAJA'::character varying)::text, ('VENDIDO'::character varying)::text]))));


ALTER VIEW modulo5.vw_m05_eficiencia_alimenticia OWNER TO postgres;

--
-- Name: VIEW vw_m05_eficiencia_alimenticia; Type: COMMENT; Schema: modulo5; Owner: postgres
--

COMMENT ON VIEW modulo5.vw_m05_eficiencia_alimenticia IS 'RF-74. Eficiencia alimenticia por activo biológico activo. Expone el ICA más reciente, su clasificación y la calidad del dato para alimentar los KPIs (total, crítica, baja, sin datos) y la tabla principal del mockup.';


--
-- Name: vw_m05_historial_ica; Type: VIEW; Schema: modulo5; Owner: postgres
--

CREATE VIEW modulo5.vw_m05_historial_ica AS
 SELECT ica.id_resultado_ica,
    ab.id_activo_biologico,
    ab.identificador AS identificador_activo,
    e.nombre AS especie,
    ica.periodo_evaluacion,
    ica.fecha_inicio_periodo,
    ica.fecha_fin_periodo,
    ica.ca_calculado AS indice_conversion_alimenticia,
    ica.clasificacion_ca AS clasificacion_ica,
    ica.alimento_consumido_total_kg,
    ica.ganancia_peso_kg,
    ica.tipo_calculo AS origen_calculo,
    ica.fecha_calculo,
    ica.data_quality_score
   FROM ((modulo5.resultado_ica ica
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = ica.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
  ORDER BY ica.id_activo_biologico, ica.fecha_calculo DESC;


ALTER VIEW modulo5.vw_m05_historial_ica OWNER TO postgres;

--
-- Name: VIEW vw_m05_historial_ica; Type: COMMENT; Schema: modulo5; Owner: postgres
--

COMMENT ON VIEW modulo5.vw_m05_historial_ica IS 'RF-74 (panel historial). Serie temporal de cálculos de ICA por activo. Columnas del mockup: Fecha del cálculo, Período evaluado, Índice de conversión, Clasificación, Alimento total (kg), Ganancia de peso (kg), Origen.';


--
-- Name: vw_m05_historial_suministros; Type: VIEW; Schema: modulo5; Owner: postgres
--

CREATE VIEW modulo5.vw_m05_historial_suministros AS
 SELECT hsa.id_historial_suministro_activo,
    ab.id_activo_biologico,
    ab.identificador AS identificador_activo,
    e.nombre AS especie,
    f.nombre AS finca,
    cp.id_ciclo_productivo,
    cp.nombre AS ciclo_productivo,
    hsa.origen AS tipo_suministro_origen,
    hsa.fecha_inicio,
    hsa.fecha_fin,
    hsa.num_registros_alimento,
    hsa.num_registros_medicamento,
    (hsa.num_registros_alimento + hsa.num_registros_medicamento) AS total_registros,
    hsa.costo_total_alimento,
    hsa.costo_total_medicamento,
    hsa.costo_total_suministros,
    hsa.formato_exportacion,
    hsa.fecha_consulta
   FROM ((((((modulo5.historial_suministros_activos hsa
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = hsa.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)))
     JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)))
     LEFT JOIN modulo9.ciclos_productivos cp ON ((cp.id_ciclo_productivo = hsa.id_ciclo_productivos)))
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = hsa.id_usuario)));


ALTER VIEW modulo5.vw_m05_historial_suministros OWNER TO postgres;

--
-- Name: VIEW vw_m05_historial_suministros; Type: COMMENT; Schema: modulo5; Owner: postgres
--

COMMENT ON VIEW modulo5.vw_m05_historial_suministros IS 'RF-81 (panel de resumen). Historial consolidado de suministros por activo. Alimenta los totales del panel summary: total registros, monto total, especie. Se complementa con vw_m05_historial_suministros_detalle para la tabla paginada.';


--
-- Name: vw_m05_historial_suministros_detalle; Type: VIEW; Schema: modulo5; Owner: postgres
--

CREATE VIEW modulo5.vw_m05_historial_suministros_detalle AS
 SELECT rs.id_registro_suministro,
    ab.id_activo_biologico,
    ab.identificador AS identificador_activo,
    e.nombre AS especie,
    f.nombre AS finca,
    cp.id_ciclo_productivo,
    cp.nombre AS ciclo_productivo,
    'ALIMENTO'::text AS tipo_suministro,
    ta.nombre AS detalle,
    rs.fecha_aplicacion,
    rs.cantidad,
    rs.unidad_medida,
    rs.precio_unitario_resuelto AS precio_unitario,
    rs.costo_registro AS costo_total,
    rs.origen_precio,
    rs.tipo_operacion,
    rs.observacion,
    rs.fecha_registro,
    rs.id_registro_rf75 AS id_rf_origen
   FROM ((((((modulo5.registro_suministro rs
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = rs.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)))
     JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)))
     JOIN modulo9.ciclos_productivos cp ON ((cp.id_ciclo_productivo = rs.id_ciclo_productivo)))
     LEFT JOIN modulo5.tipos_alimentos ta ON (((ta.id_tipo_elemento)::text = (rs.id_idempotencia)::text)))
  WHERE (rs.id_registro_rf75 IS NOT NULL)
UNION ALL
 SELECT rs.id_registro_suministro,
    ab.id_activo_biologico,
    ab.identificador AS identificador_activo,
    e.nombre AS especie,
    f.nombre AS finca,
    cp.id_ciclo_productivo,
    cp.nombre AS ciclo_productivo,
    'MEDICAMENTO'::text AS tipo_suministro,
    rm.nombre_medicamento AS detalle,
    rs.fecha_aplicacion,
    rs.cantidad,
    rs.unidad_medida,
    rs.precio_unitario_resuelto AS precio_unitario,
    rs.costo_registro AS costo_total,
    rs.origen_precio,
    rs.tipo_operacion,
    rs.observacion,
    rs.fecha_registro,
    rs.id_registro_rf76 AS id_rf_origen
   FROM ((((((modulo5.registro_suministro rs
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = rs.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)))
     JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)))
     JOIN modulo9.ciclos_productivos cp ON ((cp.id_ciclo_productivo = rs.id_ciclo_productivo)))
     LEFT JOIN modulo5.registros_medicamentos rm ON ((rm.id_registro_rf76 = rs.id_registro_rf76)))
  WHERE (rs.id_registro_rf76 IS NOT NULL);


ALTER VIEW modulo5.vw_m05_historial_suministros_detalle OWNER TO postgres;

--
-- Name: VIEW vw_m05_historial_suministros_detalle; Type: COMMENT; Schema: modulo5; Owner: postgres
--

COMMENT ON VIEW modulo5.vw_m05_historial_suministros_detalle IS 'RF-81 (tabla paginada). Detalle de todos los registros de suministro (alimentos y medicamentos) unificados. Columnas del mockup: Fecha, Ciclo, Tipo, Detalle, Origen del precio. Soporta los filtros: activo, ciclo, tipo de suministro, origen de precio, rango de fechas, costo mín/máx.';


--
-- Name: vw_m05_provision_incrementales; Type: VIEW; Schema: modulo5; Owner: postgres
--

CREATE VIEW modulo5.vw_m05_provision_incrementales AS
 SELECT aus.id_auditoria_suministro,
    ab.id_activo_biologico,
    ab.identificador AS identificador_activo,
    e.nombre AS especie,
    cp.id_ciclo_productivo,
    cp.nombre AS ciclo_productivo,
    aus.tipo_operacion AS tipo_evento,
    aus.costo_afectado AS costo_registro,
    aus.resultado AS estado_entrega,
    aus.numero_reintentos AS reintentos,
    aus.fecha_intentos AS timestamp_ultimo_intento,
    aus.hash_integridad,
    aus.registro_incompleto,
    aus.detalle_causa,
    aus.clasificacion_registro,
    aus.fecha_evento AS fecha_hora,
    ac.acumulado_total_ciclo AS acumulado_ciclo
   FROM ((((modulo5.auditorias_suministros aus
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = aus.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     LEFT JOIN modulo9.ciclos_productivos cp ON ((cp.id_ciclo_productivo = aus.id_ciclo_productivo)))
     LEFT JOIN modulo5.acumulado_ciclo ac ON ((ac.id_gestion_fases = aus.id_gestion_fases)))
  WHERE (aus.id_activo_biologico IS NOT NULL);


ALTER VIEW modulo5.vw_m05_provision_incrementales OWNER TO postgres;

--
-- Name: VIEW vw_m05_provision_incrementales; Type: COMMENT; Schema: modulo5; Owner: postgres
--

COMMENT ON VIEW modulo5.vw_m05_provision_incrementales IS 'RF-79 (tabla Outbox incremental). Eventos de auditoría de suministros pendientes de entrega al módulo financiero. Columnas del mockup: Fecha y hora, Activo, Ciclo, Categoría, Costo del registro, Acumulado del ciclo, Estado entrega, Reintentos.';


--
-- Name: vw_m05_provision_nic41; Type: VIEW; Schema: modulo5; Owner: postgres
--

CREATE VIEW modulo5.vw_m05_provision_nic41 AS
 SELECT pn.id_provision,
    ab.id_activo_biologico,
    ab.identificador AS identificador_activo,
    e.nombre AS especie,
    f.nombre AS finca,
    cp.id_ciclo_productivo,
    cp.nombre AS ciclo_productivo,
    pn.modalidad,
    pn.monto_provision,
    pn.desglose_categoria,
    pn.version_reporte,
    pn.estado,
    pn.hash_integridad,
    pn.es_reporte_potencialmente_incompleto,
    pn.motivo_correccion,
    pn.fecha_generacion,
    pn.fecha_entrega_m06,
        CASE
            WHEN (pn.hash_integridad IS NULL) THEN 'SIN_HASH'::text
            WHEN pn.es_reporte_potencialmente_incompleto THEN 'INCOMPLETO'::text
            ELSE 'VERIFICADO'::text
        END AS estado_integridad
   FROM (((((modulo5.provision_nic41 pn
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = pn.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)))
     JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)))
     LEFT JOIN modulo9.ciclos_productivos cp ON ((cp.id_ciclo_productivo = pn.id_ciclo_productivo)));


ALTER VIEW modulo5.vw_m05_provision_nic41 OWNER TO postgres;

--
-- Name: VIEW vw_m05_provision_nic41; Type: COMMENT; Schema: modulo5; Owner: postgres
--

COMMENT ON VIEW modulo5.vw_m05_provision_nic41 IS 'RF-79 (tabla de reportes). Provisiones de costos NIC 41 generadas. Columnas del mockup: Fecha de generación, Activo biológico, Ciclo productivo, Monto total, Versión, Estado, Integridad.';


--
-- Name: vw_m05_registro_alimentacion; Type: VIEW; Schema: modulo5; Owner: postgres
--

CREATE VIEW modulo5.vw_m05_registro_alimentacion AS
 SELECT rca.id_consumo_alimeto,
    rca.id_registro_rf75,
    ab.id_activo_biologico,
    ab.identificador AS identificador_activo,
    ab.tipo AS tipo_activo,
    e.nombre AS especie,
    f.nombre AS finca,
    i.nombre AS infraestructura,
    cp.id_ciclo_productivo,
    cp.nombre AS ciclo_productivo,
    dabp.cantidad_actual AS individuos_en_lote,
    ta.id_tipo_elemento AS id_tipo_alimento,
    ta.nombre AS tipo_alimento,
    rca.tipo_unidad AS unidad_medida,
    rca.cantidad_suministrada,
    rca.costo_unitario,
    rca.costo_total,
    rca.consumo_por_individuo_kg,
    rca.observacion,
    COALESCE((rca.fecha_consumo)::timestamp with time zone, rca.fecha_registro) AS fecha_hora_suministro,
    rca.fecha_inicio_periodo,
    rca.fecha_fin_periodo,
    rca.fecha_registro,
    rca.estado_registro,
    rca.justificacion_anulacion,
    rca.fecha_hora_anulacion,
    (((u.nombre)::text || ' '::text) || (u.apellidos)::text) AS registrado_por,
    u.id_usuario
   FROM (((((((((modulo5.registros_consumo_alimentos rca
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = rca.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)))
     JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)))
     JOIN modulo5.tipos_alimentos ta ON ((ta.id_tipo_elemento = rca.id_tipo_alimento)))
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = rca.id_usuario)))
     LEFT JOIN modulo2.gestiones_fases gf ON (((gf.id_activo_biologico = ab.id_activo_biologico) AND (gf.es_activa = true))))
     LEFT JOIN modulo9.ciclos_productivos cp ON ((cp.id_ciclo_productivo = gf.id_ciclo_productiva)))
     LEFT JOIN modulo2.detalles_activos_biologicos_poblacionales dabp ON ((dabp.id_activo_biologico = ab.id_activo_biologico)));


ALTER VIEW modulo5.vw_m05_registro_alimentacion OWNER TO postgres;

--
-- Name: VIEW vw_m05_registro_alimentacion; Type: COMMENT; Schema: modulo5; Owner: postgres
--

COMMENT ON VIEW modulo5.vw_m05_registro_alimentacion IS 'RF-75. Lista de registros de consumo de alimentos. Columnas del mockup: Activo, Especie/Finca, Tipo de alimento, Fecha y hora, Cantidad (kg), Costo total, Estado, Registrado por. Incluye datos de contexto del activo para el panel de previsualización del formulario de registro.';


--
-- Name: vw_m05_reporte_gastos; Type: VIEW; Schema: modulo5; Owner: postgres
--

CREATE VIEW modulo5.vw_m05_reporte_gastos AS
 SELECT rga.id_reporte_gasto_acumulado,
    ab.id_activo_biologico,
    ab.identificador AS identificador_activo,
    e.nombre AS especie,
    f.nombre AS finca,
    i.nombre AS infraestructura,
    cp.id_ciclo_productivo,
    cp.nombre AS ciclo_productivo,
    rga.fecha_incio_reporte AS fecha_inicio,
    rga.fecha_fin_report AS fecha_fin,
    rga.categoria,
    rga.total_costo_alimento,
    rga.total_costo_medicamento,
    rga.total_costo_directo,
    (rga.total_costo_alimento + rga.total_costo_medicamento) AS total_suministros,
        CASE
            WHEN (COALESCE((dabp.cantidad_actual)::numeric, dai.peso_inicial, (1)::numeric) > (0)::numeric) THEN round((rga.total_costo_directo / COALESCE((dabp.cantidad_actual)::numeric, (1)::numeric)), 4)
            ELSE NULL::numeric
        END AS costo_por_individuo,
    COALESCE(dabp.cantidad_actual, 1) AS individuos_referencia,
    rga.fecha_generacion,
    (((u.nombre)::text || ' '::text) || (u.apellidos)::text) AS generado_por
   FROM ((((((((((modulo5.reporte_gastos_acumulados rga
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = rga.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)))
     JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)))
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = rga.id_usuario)))
     LEFT JOIN modulo9.infraestructuras i2 ON ((i2.id_infraestructura = rga.id_infraestructura)))
     LEFT JOIN modulo2.gestiones_fases gf ON (((gf.id_activo_biologico = ab.id_activo_biologico) AND (gf.es_activa = true))))
     LEFT JOIN modulo9.ciclos_productivos cp ON ((cp.id_ciclo_productivo = gf.id_ciclo_productiva)))
     LEFT JOIN modulo2.detalles_activos_biologicos_poblacionales dabp ON ((dabp.id_activo_biologico = ab.id_activo_biologico)))
     LEFT JOIN modulo2.detalles_activos_individuales dai ON ((dai.id_activo_biologico = ab.id_activo_biologico)));


ALTER VIEW modulo5.vw_m05_reporte_gastos OWNER TO postgres;

--
-- Name: VIEW vw_m05_reporte_gastos; Type: COMMENT; Schema: modulo5; Owner: postgres
--

COMMENT ON VIEW modulo5.vw_m05_reporte_gastos IS 'RF-77. Reporte de gastos acumulados por activo y período. Alimenta los KPIs: Gasto total acumulado, Alimentación, Medicación, Gasto por individuo. Incluye desglose por categoría.';


--
-- Name: vw_m05_reporte_gastos_detalle; Type: VIEW; Schema: modulo5; Owner: postgres
--

CREATE VIEW modulo5.vw_m05_reporte_gastos_detalle AS
 SELECT 'ALIMENTO'::text AS categoria,
    (rca.id_consumo_alimeto)::text AS id_origen,
    ab.id_activo_biologico,
    ab.identificador AS identificador_activo,
    (COALESCE((rca.fecha_consumo)::timestamp with time zone, rca.fecha_registro))::timestamp without time zone AS fecha,
    ta.nombre AS descripcion,
    rca.costo_total AS monto_cop,
    (rca.estado_registro)::text AS estado,
    e.nombre AS especie,
    f.nombre AS finca
   FROM (((((modulo5.registros_consumo_alimentos rca
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = rca.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)))
     JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)))
     JOIN modulo5.tipos_alimentos ta ON ((ta.id_tipo_elemento = rca.id_tipo_alimento)))
UNION ALL
 SELECT 'MEDICAMENTO'::text AS categoria,
    (rm.id_registro_medicamento)::text AS id_origen,
    ab.id_activo_biologico,
    ab.identificador AS identificador_activo,
    ((rm.fecha_registro + (rm.hora_aplicacion)::interval))::timestamp without time zone AS fecha,
    rm.nombre_medicamento AS descripcion,
    rm.costo_total_medicamento AS monto_cop,
    (rm.estado_registro)::text AS estado,
    e.nombre AS especie,
    f.nombre AS finca
   FROM ((((modulo5.registros_medicamentos rm
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = rm.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)))
     JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)));


ALTER VIEW modulo5.vw_m05_reporte_gastos_detalle OWNER TO postgres;

--
-- Name: VIEW vw_m05_reporte_gastos_detalle; Type: COMMENT; Schema: modulo5; Owner: postgres
--

COMMENT ON VIEW modulo5.vw_m05_reporte_gastos_detalle IS 'RF-77 (tabla de detalle). Unión de alimentos y medicamentos en una sola serie de transacciones. Columnas del mockup: Fecha, Categoría, Descripción, Monto (COP), Estado.';


--
-- Name: vw_m05_trazabilidad_costos; Type: VIEW; Schema: modulo5; Owner: postgres
--

CREATE VIEW modulo5.vw_m05_trazabilidad_costos AS
 SELECT aus.id_auditoria_suministro,
    ab.id_activo_biologico,
    ab.identificador AS identificador_activo,
    e.nombre AS especie,
    f.nombre AS finca,
    cp.id_ciclo_productivo,
    cp.nombre AS ciclo_productivo,
    aus.fecha_evento AS fecha_operacion,
    aus.tipo_operacion AS tipo_evento,
    aus.resultado,
    aus.clasificacion_registro AS clasificacion,
    aus.retencion_aplicable AS retencion,
    aus.costo_afectado AS monto_afectado,
    aus.hash_integridad,
    aus.registro_incompleto,
    aus.detalle_causa,
    aus.numero_reintentos,
    aus.fecha_intentos,
    aus.datos_anteriores,
    aus.datos_nuevos,
    (((u.nombre)::text || ' '::text) || (u.apellidos)::text) AS usuario,
    aus.ip_origen,
    aus.id_sesion
   FROM ((((((modulo5.auditorias_suministros aus
     LEFT JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = aus.id_activo_biologico)))
     LEFT JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     LEFT JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = ab.id_infraestructura)))
     LEFT JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)))
     LEFT JOIN modulo9.ciclos_productivos cp ON ((cp.id_ciclo_productivo = aus.id_ciclo_productivo)))
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = aus.id_usuario)));


ALTER VIEW modulo5.vw_m05_trazabilidad_costos OWNER TO postgres;

--
-- Name: VIEW vw_m05_trazabilidad_costos; Type: COMMENT; Schema: modulo5; Owner: postgres
--

COMMENT ON VIEW modulo5.vw_m05_trazabilidad_costos IS 'RF-80. Log completo de auditoría de suministros. Columnas del mockup: Fecha de operación, Tipo de evento, Resultado, Clasificación, Activo biológico, Ciclo, Monto afectado. Incluye datos para el panel de detalle (datos_anteriores/datos_nuevos, reintentos, hash de integridad).';


--
-- Name: auditorias_financieras; Type: TABLE; Schema: modulo6; Owner: postgres
--

CREATE TABLE modulo6.auditorias_financieras (
    id_auditoria_financiera integer NOT NULL,
    tipo modulo6.enum_auditorias_financieras_severidad NOT NULL,
    id_activo_biologico integer NOT NULL,
    modulo_origen character varying(10) DEFAULT 'modulo6'::character varying NOT NULL,
    id_periodo_contable integer,
    monto_afectado numeric(18,4),
    metodo_valoracion_anterior modulo6.enum_auditoria_financiera_metodo_valoracion,
    metodo_valoracion_nuevo modulo6.enum_auditoria_financiera_metodo_valoracion,
    datos_nuevos jsonb,
    datos_anteriores jsonb,
    severidad modulo6.enum_auditorias_financieras_severidad DEFAULT 'INFO'::modulo6.enum_auditorias_financieras_severidad NOT NULL,
    id_usuario integer,
    ip_origen inet,
    fecha_registro timestamp with time zone DEFAULT now() NOT NULL,
    tipo_actor modulo6.enum_actor_auditoria NOT NULL,
    hash_integridad character varying(64) NOT NULL,
    origen_registro character varying(20) DEFAULT 'REPOSITORIO'::character varying NOT NULL,
    CONSTRAINT chk_auditoria_financiera_fecha_no_futura CHECK ((fecha_registro <= now()))
);


ALTER TABLE modulo6.auditorias_financieras OWNER TO postgres;

--
-- Name: TABLE auditorias_financieras; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TABLE modulo6.auditorias_financieras IS 'Repositorio append-only e inmutable de eventos financieros del módulo M06. Registra automáticamente todas las operaciones de RF-82 a RF-93 y RF-COT con trazabilidad completa. Comparte el repositorio centralizado con RF-52 (M02), RF-63 (M03) y RF-73 (M04), diferenciándose por el campo modulo_origen. Retención mínima: 10 años. Los registros son generados por el sistema; ningún actor humano puede crearlos, modificarlos ni eliminarlos. Referencia: RF-94.';


--
-- Name: COLUMN auditorias_financieras.id_auditoria_financiera; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.auditorias_financieras.id_auditoria_financiera IS 'PK serial. Identificador único del evento de auditoría. Inmutable desde su creación. Utilizado por auditores externos (acceso de solo lectura vía M08) y por RF-91 para verificar la cadena de trazabilidad completa desde datos IoT hasta asientos contables.';


--
-- Name: COLUMN auditorias_financieras.tipo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.auditorias_financieras.tipo IS 'Tipo de evento financiero registrado. Catálogo completo: RECONOCIMIENTO_INICIAL, MEDICION_POSTERIOR, VARIACION_VALOR_RAZONABLE, CIERRE_PERIODO_INICIADO, CIERRE_PERIODO_COMPLETADO, CIERRE_PERIODO_FALLIDO, ACTIVO_MARCADO_SIN_MERCADO, METODO_VALORACION_CAMBIADO, RECONOCIMIENTO_REVERTIDO, REVERSION_BLOQUEADA, COTIZACION_REGISTRADA, COTIZACION_MODIFICADA, COTIZACION_ANULADA, COTIZACION_VENCIDA, COSTO_REGISTRADO, INFORME_REVELACIONES_APROBADO, ESTADO_RESULTADOS_GENERADO, PRECIO_REGISTRADO. [Nota: el campo usa el enum de severidad; debería ser un enum de tipo_evento separado — revisar en próxima migración.]';


--
-- Name: COLUMN auditorias_financieras.id_activo_biologico; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.auditorias_financieras.id_activo_biologico IS 'FK → modulo2.activos_biologicos. Activo biológico afectado por el evento registrado. Obligatorio para eventos que involucran un activo específico (reconocimientos, valoraciones, mediciones). Puede ser nulo en eventos de cierre de período masivo o configuración de parámetros.';


--
-- Name: COLUMN auditorias_financieras.modulo_origen; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.auditorias_financieras.modulo_origen IS 'Identificador del módulo que generó el evento. DEFAULT "modulo6". Permite correlacionar eventos de este módulo con eventos de RF-52 (M02), RF-63 (M03) y RF-73 (M04) en el repositorio centralizado de auditoría para construir la cadena de trazabilidad de RF-91.';


--
-- Name: COLUMN auditorias_financieras.id_periodo_contable; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.auditorias_financieras.id_periodo_contable IS 'FK → modulo6.periodos_contables. Período contable al que pertenece el evento auditado. Nulo para eventos que no están vinculados a un período específico (configuración de parámetros, registro de precios). [Nota: el nombre tiene un espacio al final; corregir en próxima migración.]';


--
-- Name: COLUMN auditorias_financieras.monto_afectado; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.auditorias_financieras.monto_afectado IS 'Monto monetario en COP (DECIMAL 18,4) impactado por el evento auditado. Nulo para eventos sin impacto monetario directo (marcaciones, configuraciones). Permite a auditores cuantificar el impacto de cada operación sin acceder a las tablas operativas.';


--
-- Name: COLUMN auditorias_financieras.metodo_valoracion_anterior; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.auditorias_financieras.metodo_valoracion_anterior IS 'Método de valoración del activo antes del evento, cuando el tipo registra un cambio de método (METODO_VALORACION_CAMBIADO). VALOR_RAZONABLE o VALORACION_POR_COSTO. Nulo para eventos que no implican cambio de método.';


--
-- Name: COLUMN auditorias_financieras.metodo_valoracion_nuevo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.auditorias_financieras.metodo_valoracion_nuevo IS 'Método de valoración del activo después del evento. VALOR_RAZONABLE o VALORACION_POR_COSTO. Junto con metodo_valoracion_anterior documenta completamente la transición de método, requerida para auditabilidad NIC 41 y trazabilidad de RF-91.';


--
-- Name: COLUMN auditorias_financieras.datos_nuevos; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.auditorias_financieras.datos_nuevos IS 'Snapshot en JSONB del estado del registro afectado después del evento. Permite a auditores reconstruir el estado exacto del sistema en cualquier momento histórico sin depender de las tablas operativas. Tamaño máximo: 64 KB (registros mayores se truncan con indicador payload_truncado).';


--
-- Name: COLUMN auditorias_financieras.datos_anteriores; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.auditorias_financieras.datos_anteriores IS 'Snapshot en JSONB del estado del registro afectado antes del evento. Nulo en eventos de creación (no existe estado anterior). Junto con datos_nuevos permite reconstruir la diferencia exacta entre el estado pre y post evento para auditorías de cambio.';


--
-- Name: COLUMN auditorias_financieras.severidad; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.auditorias_financieras.severidad IS 'Nivel de criticidad del evento. INFO: operación normal exitosa. WARNING: evento excepcional que requiere atención del Contador (valoración estimada, reversión bloqueada, precio próximo a vencer). ERROR: fallo técnico que requiere intervención. CRITICAL: fallo en cadena que compromete la integridad contable. Permite al Administrador filtrar eventos relevantes en el dashboard de M08. Default: INFO.';


--
-- Name: COLUMN auditorias_financieras.id_usuario; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.auditorias_financieras.id_usuario IS 'FK → modulo1.usuarios. Actor humano que originó el evento auditado. Nulo cuando el evento fue generado automáticamente por un proceso del sistema (cierre RF-87, medición automática RF-83). Exclusivo con el concepto de proceso del sistema para identificar la fuente exacta.';


--
-- Name: COLUMN auditorias_financieras.ip_origen; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.auditorias_financieras.ip_origen IS 'Dirección IP del cliente desde la cual el usuario ejecutó la operación. Tipo inet de PostgreSQL para soportar IPv4 e IPv6. Nulo para eventos generados por procesos internos del sistema sin interacción humana directa.';


--
-- Name: COLUMN auditorias_financieras.fecha_registro; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.auditorias_financieras.fecha_registro IS 'Timestamp de inserción del evento en el repositorio de auditoría. DEFAULT now(). Absolutamente inmutable. Sincronizado con el reloj NTP del sistema para garantizar coherencia cronológica con eventos de RF-52 (M02) y RF-73 (M04) en la cadena de trazabilidad de RF-91. Retención mínima: 10 años desde el cierre del período al que pertenece el evento.';


--
-- Name: auditorias_financieras_id_auditoria_financiera_seq; Type: SEQUENCE; Schema: modulo6; Owner: postgres
--

CREATE SEQUENCE modulo6.auditorias_financieras_id_auditoria_financiera_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo6.auditorias_financieras_id_auditoria_financiera_seq OWNER TO postgres;

--
-- Name: auditorias_financieras_id_auditoria_financiera_seq; Type: SEQUENCE OWNED BY; Schema: modulo6; Owner: postgres
--

ALTER SEQUENCE modulo6.auditorias_financieras_id_auditoria_financiera_seq OWNED BY modulo6.auditorias_financieras.id_auditoria_financiera;


