    id_precio_mercado integer,
    estado_verificacion modulo6.enum_estado_verificacion DEFAULT 'PENDIENTE'::modulo6.enum_estado_verificacion,
    nivel_fallo integer,
    fecha_verificacion timestamp with time zone,
    verificado_por integer,
    justificacion_verificacion text
);


ALTER TABLE modulo6.cadenas_trazabilidad_contable OWNER TO postgres;

--
-- Name: cadenas_trazabilidad_contable_id_asiento_seq; Type: SEQUENCE; Schema: modulo6; Owner: postgres
--

CREATE SEQUENCE modulo6.cadenas_trazabilidad_contable_id_asiento_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo6.cadenas_trazabilidad_contable_id_asiento_seq OWNER TO postgres;

--
-- Name: cadenas_trazabilidad_contable_id_asiento_seq; Type: SEQUENCE OWNED BY; Schema: modulo6; Owner: postgres
--

ALTER SEQUENCE modulo6.cadenas_trazabilidad_contable_id_asiento_seq OWNED BY modulo6.cadenas_trazabilidad_contable.id_asiento;


--
-- Name: calculos_valor_razonable; Type: TABLE; Schema: modulo6; Owner: postgres
--

CREATE TABLE modulo6.calculos_valor_razonable (
    id_calculo_valor_razonable integer NOT NULL,
    id_activo_biologico integer NOT NULL,
    id_precio_mercado integer NOT NULL,
    id_parametro_costo_venta integer,
    valor_razonable_bruto numeric(18,4) NOT NULL,
    costo_transporte numeric(18,4) DEFAULT 0 NOT NULL,
    costo_comisiones numeric(18,4) DEFAULT 0 NOT NULL,
    costo_impuestos_transaccion numeric(18,4) DEFAULT 0 NOT NULL,
    otros_costos_disposicion numeric(18,4) DEFAULT 0 NOT NULL,
    valor_neto numeric(18,4) NOT NULL,
    metodo_costo modulo6.enum_calculos_valor_razonable_metodo_costo NOT NULL,
    justificacion text,
    estado modulo6.enum_calculos_valor_razonable_estado DEFAULT 'CALCULADO'::modulo6.enum_calculos_valor_razonable_estado NOT NULL,
    id_usuario integer NOT NULL,
    fecha_calculo timestamp with time zone DEFAULT now() NOT NULL,
    id_periodo_contable integer NOT NULL,
    CONSTRAINT chk_calculo_bruto_positivo CHECK ((valor_razonable_bruto > (0)::numeric)),
    CONSTRAINT chk_calculo_costos_no_negativos CHECK (((costo_transporte >= (0)::numeric) AND (costo_comisiones >= (0)::numeric) AND (costo_impuestos_transaccion >= (0)::numeric) AND (otros_costos_disposicion >= (0)::numeric))),
    CONSTRAINT chk_calculo_fecha_no_futura CHECK ((fecha_calculo <= now())),
    CONSTRAINT chk_calculo_valor_neto_coherente CHECK ((abs((valor_neto - ((((valor_razonable_bruto - costo_transporte) - costo_comisiones) - costo_impuestos_transaccion) - otros_costos_disposicion))) <= 1.0)),
    CONSTRAINT chk_manual_requiere_justificacion CHECK (((metodo_costo = 'PARAMETRIZADO'::modulo6.enum_calculos_valor_razonable_metodo_costo) OR (justificacion IS NOT NULL)))
);


ALTER TABLE modulo6.calculos_valor_razonable OWNER TO postgres;

--
-- Name: TABLE calculos_valor_razonable; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TABLE modulo6.calculos_valor_razonable IS 'Registra cada ejecución del cálculo de valor razonable menos costos de venta conforme al Párr. 12 NIC 41. Es la única fuente de valor razonable del módulo; ningún otro RF debe tomar precios de RF-89 directamente y usarlos como valor del activo. Consumido por mediciones_posteriores, reconocimientos_iniciales y reconocimientos_productos_agricolas. Referencia: RF-84.';


--
-- Name: COLUMN calculos_valor_razonable.id_calculo_valor_razonable; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.calculos_valor_razonable.id_calculo_valor_razonable IS 'PK serial. Identificador único del cálculo. Referenciado por mediciones_posteriores (calculo_actual y calculo_anterior) para computar la variación entre dos puntos en el tiempo, y por reconocimientos_productos_agricolas para documentar el valor de la cosecha.';


--
-- Name: COLUMN calculos_valor_razonable.id_activo_biologico; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.calculos_valor_razonable.id_activo_biologico IS 'FK → modulo2.activos_biologicos. Activo sobre el cual se calcula el valor razonable neto. El sistema garantiza que el activo tenga reconocimiento inicial confirmado en reconocimientos_iniciales antes de ejecutar este cálculo.';


--
-- Name: COLUMN calculos_valor_razonable.id_precio_mercado; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.calculos_valor_razonable.id_precio_mercado IS 'FK → modulo6.precios_mercado. Precio de referencia aplicado en este cálculo. Debe estar en estado ACTIVO y vigente a la fecha del cálculo. En cierres de período (RF-87) corresponde al precio "congelado" al inicio del proceso para garantizar coherencia interna.';


--
-- Name: COLUMN calculos_valor_razonable.id_parametro_costo_venta; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.calculos_valor_razonable.id_parametro_costo_venta IS 'FK → modulo6.parametros_costos_venta. Parámetro de costos de venta de M09 aplicado automáticamente en este cálculo. Nulo cuando los costos fueron ingresados manualmente por el Contador (metodo_costo = MANUAL); en ese caso la justificacion es obligatoria.';


--
-- Name: COLUMN calculos_valor_razonable.valor_razonable_bruto; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.calculos_valor_razonable.valor_razonable_bruto IS 'Precio de mercado de referencia sin deducción de costos, expresado en COP (DECIMAL 18,4). Obtenido directamente desde el id_precio_mercado vigente. Es la base del cálculo; no es el valor que se contabiliza.';


--
-- Name: COLUMN calculos_valor_razonable.costo_transporte; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.calculos_valor_razonable.costo_transporte IS 'Costo de transporte del activo al punto de venta en COP. Puede provenir de parametros_costos_venta (PARAMETRIZADO) o ser ingresado manualmente por el Contador (MANUAL). Clasificado como tipo_costo = VENTA; nunca se deduce del valor razonable un costo de MANTENIMIENTO. DEFAULT 0.';


--
-- Name: COLUMN calculos_valor_razonable.costo_comisiones; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.calculos_valor_razonable.costo_comisiones IS 'Comisiones de intermediación estimadas para la transacción de venta en COP. Deducibles del valor razonable bruto. El Contador puede sobrescribir el valor parametrizado con justificacion obligatoria registrada en auditorias_financieras. DEFAULT 0.';


--
-- Name: COLUMN calculos_valor_razonable.costo_impuestos_transaccion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.calculos_valor_razonable.costo_impuestos_transaccion IS 'Impuestos directamente atribuibles a la transacción de venta (no impuesto sobre la renta) en COP. Deducible del valor razonable bruto conforme a NIC 41. DEFAULT 0.';


--
-- Name: COLUMN calculos_valor_razonable.otros_costos_disposicion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.calculos_valor_razonable.otros_costos_disposicion IS 'Otros costos directos de disposición no contemplados en las tres categorías anteriores, en COP. Siempre ingresado manualmente por el Contador con justificacion obligatoria. Clasificado como tipo_costo = VENTA. DEFAULT 0.';


--
-- Name: COLUMN calculos_valor_razonable.valor_neto; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.calculos_valor_razonable.valor_neto IS 'Resultado del cálculo: valor_razonable_bruto − (costo_transporte + costo_comisiones + costo_impuestos_transaccion + otros_costos_disposicion). Expresado en COP DECIMAL(18,4). Este es el valor que se contabiliza en el balance conforme a NIC 41. Si es ≤ 0, estado pasa a REVISION_REQUERIDA y se alerta al Contador.';


--
-- Name: COLUMN calculos_valor_razonable.metodo_costo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.calculos_valor_razonable.metodo_costo IS 'Indica si los costos de venta fueron tomados de parametros_costos_venta (PARAMETRIZADO), ingresados manualmente (MANUAL) o aplicados de forma mixta (MIXTO: algunos parametrizados y otros manuales). El sistema registra el método por componente para auditabilidad completa.';


--
-- Name: COLUMN calculos_valor_razonable.justificacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.calculos_valor_razonable.justificacion IS 'Descripción obligatoria cuando el Contador sobrescribe costos parametrizados o cuando todos los costos son MANUAL. Registrada en auditorias_financieras con identificación del usuario y fecha. Nula cuando todos los costos provienen de parametros_costos_venta sin modificación.';


--
-- Name: COLUMN calculos_valor_razonable.estado; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.calculos_valor_razonable.estado IS 'Estado del cálculo. CALCULADO: valor_neto > 0, disponible para uso en mediciones_posteriores y reconocimientos. REVISION_REQUERIDA: valor_neto ≤ 0; bloqueado hasta que el Contador valide explícitamente con justificación documentada. Default: CALCULADO.';


--
-- Name: COLUMN calculos_valor_razonable.id_usuario; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.calculos_valor_razonable.id_usuario IS 'FK → modulo1.usuarios. Contador responsable del cálculo. En cálculos automáticos (cierre RF-87) puede corresponder al proceso del sistema identificado por su id de servicio.';


--
-- Name: COLUMN calculos_valor_razonable.fecha_calculo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.calculos_valor_razonable.fecha_calculo IS 'Timestamp de ejecución del cálculo. DEFAULT now(). Debe coincidir con la fecha del evento que lo desencadenó (medición por evento) o con el inicio del cierre (medición masiva RF-87).';


--
-- Name: COLUMN calculos_valor_razonable.id_periodo_contable; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.calculos_valor_razonable.id_periodo_contable IS 'FK → modulo6.periodos_contables. Período contable ABIERTO al que pertenece este cálculo. No se realizan cálculos en períodos EN_CIERRE o CERRADOS (excepto durante el proceso de cierre masivo de RF-87).';


--
-- Name: calculos_valor_razonable_id_calculo_valor_razonable_seq; Type: SEQUENCE; Schema: modulo6; Owner: postgres
--

CREATE SEQUENCE modulo6.calculos_valor_razonable_id_calculo_valor_razonable_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo6.calculos_valor_razonable_id_calculo_valor_razonable_seq OWNER TO postgres;

--
-- Name: calculos_valor_razonable_id_calculo_valor_razonable_seq; Type: SEQUENCE OWNED BY; Schema: modulo6; Owner: postgres
--

ALTER SEQUENCE modulo6.calculos_valor_razonable_id_calculo_valor_razonable_seq OWNED BY modulo6.calculos_valor_razonable.id_calculo_valor_razonable;


--
-- Name: cotizaciones; Type: TABLE; Schema: modulo6; Owner: postgres
--

CREATE TABLE modulo6.cotizaciones (
    id_cotizacion integer NOT NULL,
    fecha_emision date NOT NULL,
    id_periodo_contable integer NOT NULL,
    activos_cotizados integer[] NOT NULL,
    valor_cotizacion_propuesto numeric(18,4) NOT NULL,
    condiciones text,
    estado modulo6.enum_cotizaciones_estado_cotizacion,
    fecha_vencimiento date,
    accounting_account character varying(20)[] NOT NULL,
    line_type character varying(60) NOT NULL,
    type_code "char" DEFAULT '4'::"char" NOT NULL,
    motivo_anulacion text,
    id_usuario integer,
    fecha_registro timestamp with time zone DEFAULT now() NOT NULL,
    id_fuente_rf86 uuid,
    estado_envelope modulo6.enum_estado_envelope DEFAULT 'ACTIVE'::modulo6.enum_estado_envelope,
    cuentas_orden_puc character varying(20)[],
    motivo_anulacion_envelope text,
    id_variacion_valor_razonable integer,
    CONSTRAINT chk_anulacion_requiere_motivo CHECK (((estado <> 'ANULADA'::modulo6.enum_cotizaciones_estado_cotizacion) OR (motivo_anulacion IS NOT NULL))),
    CONSTRAINT chk_cotizacion_emision_no_futura CHECK ((fecha_emision <= CURRENT_DATE)),
    CONSTRAINT chk_cotizaciones_motivo_anulacion_min_length CHECK (((motivo_anulacion IS NULL) OR (char_length(motivo_anulacion) >= 20))),
    CONSTRAINT chk_vencimiento_posterior_emision CHECK (((fecha_vencimiento IS NULL) OR (fecha_vencimiento >= fecha_emision)))
);


ALTER TABLE modulo6.cotizaciones OWNER TO postgres;

--
-- Name: TABLE cotizaciones; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TABLE modulo6.cotizaciones IS 'Gestiona las cotizaciones formales de venta de activos biológicos. Una cotización es un hecho económico del período de emisión; no genera transferencia de propiedad ni modifica el valor razonable del activo. Produce documentos AAEF tipo 04 Uso B (prefijo COT-) en el envelope del período cerrado, diferenciados de tipo 04 Uso A (Nota Débito de RF-86). Referencia: RF-COT.';


--
-- Name: COLUMN cotizaciones.id_cotizacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.cotizaciones.id_cotizacion IS 'PK serial. Identificador único de la cotización. Forma parte del DocumentId AAEF con la convención: COT-{id_cotizacion}-{fecha_emision_YYYYMMDD}. Inmutable desde la creación; el Mapper de RF-96 lo usa para construir el documento tipo 04 Uso B.';


--
-- Name: COLUMN cotizaciones.fecha_emision; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.cotizaciones.fecha_emision IS 'Fecha de emisión de la cotización. Debe estar dentro del período contable ABIERTO activo (id_periodo_contable). Junto con id_cotizacion forma el DocumentId determinístico del documento AAEF.';


--
-- Name: COLUMN cotizaciones.id_periodo_contable; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.cotizaciones.id_periodo_contable IS 'FK → modulo6.periodos_contables. Período contable al que pertenece la cotización. Debe estar ABIERTO al registrar. La cotización aparece en el envelope AAEF de este período cuando esté CERRADO, siempre que su estado sea COTIZADO al momento del cierre (no VENCIDA ni ANULADA).';


--
-- Name: COLUMN cotizaciones.activos_cotizados; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.cotizaciones.activos_cotizados IS 'Array de id_activo_biologico (integers) de los activos incluidos en la cotización. Todos deben existir con reconocimiento inicial CONFIRMADO y estado ACTIVO en M02. Los activos cotizados no se bloquean ni modifican; permanecen ACTIVOS y siguen siendo valorados por RF-86.';


--
-- Name: COLUMN cotizaciones.valor_cotizacion_propuesto; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.cotizaciones.valor_cotizacion_propuesto IS 'Valor de venta propuesto por el Contador o Administrador en COP (DECIMAL 18,4). Puede diferir del valor razonable de referencia. Mayor a cero (validar con CHECK). Modificable antes del cierre del período. [Nota: el nombre tiene un espacio al final; corregir en próxima migración.]';


--
-- Name: COLUMN cotizaciones.condiciones; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.cotizaciones.condiciones IS 'Texto libre con las condiciones comerciales de la cotización: plazo de pago, forma de pago, observaciones especiales, vigencia. Modificable antes del cierre del período con registro en auditorias_financieras. Nulo si no aplican condiciones especiales.';


--
-- Name: COLUMN cotizaciones.estado; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.cotizaciones.estado IS 'Estado del ciclo de vida de la cotización. COTIZADO: activa y vigente; aparece en el envelope AAEF si el período se cierra mientras está en este estado. VENCIDA: superó fecha_vencimiento sin concretarse; no aparece en el envelope si ya estaba VENCIDA al cierre. ANULADA: cancelada por el Contador antes del cierre con motivo_anulacion; nunca aparece en el envelope. CONVERTIDA_EN_VENTA: referencial para proceso de venta consumada (flujo diferido).';


--
-- Name: COLUMN cotizaciones.fecha_vencimiento; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.cotizaciones.fecha_vencimiento IS 'Fecha hasta la cual la cotización es válida. Opcional (nullable). No puede ser anterior a fecha_emision. Si no se informa, la cotización no vence automáticamente (vigencia indefinida hasta anulación manual). Si se informa y vence antes del cierre del período, el estado cambia automáticamente a VENCIDA y se excluye del envelope AAEF.';


--
-- Name: COLUMN cotizaciones.accounting_account; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.cotizaciones.accounting_account IS 'Array posicional de cuentas PUC de orden (cuentas que no afectan el balance porque la venta no está perfeccionada). 1 o 2 elementos: [cuenta_orden_deudora] o [deudora, acreedora]. Obligatorio (CHECK array_length > 0). No modificable después del registro. Configuradas en M09 por especie.';


--
-- Name: COLUMN cotizaciones.line_type; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.cotizaciones.line_type IS 'Tipo de línea del catálogo M09 específico para cotizaciones. Valores probables: COTIZACION_ACTIVO_BIOLOGICO, CONDICIONES_PAGO. Obligatorio y validado contra catálogo activo. No modificable después del registro. Transferido íntegramente por RF-96 al documento AAEF.';


--
-- Name: COLUMN cotizaciones.type_code; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.cotizaciones.type_code IS 'Código de tipo de documento AAEF. Siempre "4" (tipo 04 Uso B: Cotización de Venta de Activo Biológico). Generado automáticamente; no editable. Diferencia este documento del tipo 04 Uso A (Nota Débito de RF-86) por el prefijo COT- en el DocumentId. DEFAULT "4".';


--
-- Name: COLUMN cotizaciones.motivo_anulacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.cotizaciones.motivo_anulacion IS 'Texto obligatorio cuando el Contador o Administrador anula la cotización (estado → ANULADA). Describe la razón de la cancelación. Inmutable una vez registrada la anulación. La anulación es irrevocable; no puede revertirse a COTIZADO.';


--
-- Name: COLUMN cotizaciones.id_usuario; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.cotizaciones.id_usuario IS 'FK → modulo1.usuarios. Contador o Administrador que registró, modificó o anuló la cotización. El Productor/Usuario solo puede consultar; los intentos de escritura reciben HTTP 403 registrado en auditorias_financieras.';


--
-- Name: COLUMN cotizaciones.fecha_registro; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.cotizaciones.fecha_registro IS 'Timestamp de creación del registro. DEFAULT now(). Inmutable. Registrado en auditorias_financieras con tipo_evento = COTIZACION_REGISTRADA.';


--
-- Name: COLUMN cotizaciones.id_variacion_valor_razonable; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.cotizaciones.id_variacion_valor_razonable IS 'FK → modulo6.variaciones_valor_razonable. Referencia a la variación de valor razonable (RF-86) cuyo valor_razonable_nuevo fue usado como valor_razonable_referencia en el momento de emisión de la cotización. Materializa la trazabilidad exigida por RF-91: cotización → variación → medición → cálculo → precio de mercado. Nullable para compatibilidad con cotizaciones previas a esta migración y para escenarios donde el valor razonable de referencia provino de una fuente estimada sin variación registrada. Referencia: RF-COT, RF-86, RF-91.';


--
-- Name: CONSTRAINT chk_cotizaciones_motivo_anulacion_min_length ON cotizaciones; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON CONSTRAINT chk_cotizaciones_motivo_anulacion_min_length ON modulo6.cotizaciones IS 'Garantiza que cuando se registra un motivo de anulación, este contenga al menos 20 caracteres para asegurar una justificación significativa y auditable (NULL es válido mientras la cotización no esté ANULADA; la obligatoriedad de presencia se valida en capa de negocio al cambiar estado → ANULADA). Alinea el estándar con revisiones_reconocimiento. Referencia: RF-COT.';


--
-- Name: cotizaciones_id_cotizacion_seq; Type: SEQUENCE; Schema: modulo6; Owner: postgres
--

CREATE SEQUENCE modulo6.cotizaciones_id_cotizacion_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo6.cotizaciones_id_cotizacion_seq OWNER TO postgres;

--
-- Name: cotizaciones_id_cotizacion_seq; Type: SEQUENCE OWNED BY; Schema: modulo6; Owner: postgres
--

ALTER SEQUENCE modulo6.cotizaciones_id_cotizacion_seq OWNED BY modulo6.cotizaciones.id_cotizacion;


--
-- Name: deterorios_activos; Type: TABLE; Schema: modulo6; Owner: postgres
--

CREATE TABLE modulo6.deterorios_activos (
    id_deterorio_activo integer NOT NULL,
    id_valoracio_costo integer NOT NULL,
    id_evento_sanitario integer NOT NULL,
    impacto_economico_cop numeric(18,4) NOT NULL,
    justificacion text NOT NULL,
    id_usuario integer NOT NULL,
    fecha_registro timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_deterioro_fecha_no_futura CHECK ((fecha_registro <= now())),
    CONSTRAINT chk_deterioro_impacto_positivo CHECK ((impacto_economico_cop > (0)::numeric)),
    CONSTRAINT chk_deterioro_justificacion_minima CHECK ((char_length(TRIM(BOTH FROM justificacion)) >= 30))
);


ALTER TABLE modulo6.deterorios_activos OWNER TO postgres;

--
-- Name: TABLE deterorios_activos; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TABLE modulo6.deterorios_activos IS 'Registra los impactos económicos cuantificados por el Contador para cada evento sanitario de M02 que afecta el valor de un activo bajo método de costo (RF-88). Los eventos sanitarios son hechos clínicos de M02; la cuantificación monetaria es responsabilidad exclusiva de M06. El deterioro_acumulado en valoraciones_por_costos es la sumatoria de estos registros. [Nota: "deterorio" → corregir typo a "deterioro" en próxima migración.] Referencia: RF-88.';


--
-- Name: COLUMN deterorios_activos.id_deterorio_activo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.deterorios_activos.id_deterorio_activo IS 'PK serial. Identificador único del impacto de deterioro. Cada registro representa un evento sanitario específico con su cuantificación monetaria aprobada por el Contador. [Typo: "deterorio" → "deterioro"].';


--
-- Name: COLUMN deterorios_activos.id_valoracio_costo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.deterorios_activos.id_valoracio_costo IS 'FK → modulo6.valoraciones_por_costos. Valoración por costo activa del activo al que se asocia este deterioro. Garantiza que el impacto económico se suma al deterioro_acumulado de la valoración correcta. [Typo: "valoracio" → "valoracion_costo"].';


--
-- Name: COLUMN deterorios_activos.id_evento_sanitario; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.deterorios_activos.id_evento_sanitario IS 'FK → modulo2.eventos_sanitarios. Evento sanitario (enfermedad, tratamiento, diagnóstico) registrado en M02 que justifica este impacto económico. Vínculo obligatorio: no se puede registrar deterioro sin un evento sanitario documentado en M02. RF-41 aporta el hecho clínico; M06 aporta su cuantificación monetaria.';


--
-- Name: COLUMN deterorios_activos.impacto_economico_cop; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.deterorios_activos.impacto_economico_cop IS 'Valor monetario del deterioro en COP (DECIMAL 18,4). Debe ser mayor a 0 (validar con CHECK impacto_economico_cop > 0). Ingresado manualmente por el Contador con justificación contable. No proviene de RF-41 ni de ningún cálculo automático.';


--
-- Name: COLUMN deterorios_activos.justificacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.deterorios_activos.justificacion IS 'Descripción contable obligatoria que explica cómo se cuantificó el impacto económico del evento sanitario. Debe relacionar el hecho clínico de M02 con su efecto monetario sobre el valor del activo. Visible en auditorías externas NIC 41 y revelaciones RF-92.';


--
-- Name: COLUMN deterorios_activos.id_usuario; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.deterorios_activos.id_usuario IS 'FK → modulo1.usuarios. Contador que registró el impacto económico de deterioro. Operación exclusiva del rol Contador, verificado en M01. Registrado en auditorias_financieras.';


--
-- Name: COLUMN deterorios_activos.fecha_registro; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.deterorios_activos.fecha_registro IS 'Timestamp de registro del impacto económico. DEFAULT now(). Inmutable. El sistema verifica que la fecha sea igual o anterior al período de cierre vigente para incluir el deterioro en el cálculo del período correcto.';


--
-- Name: deterorios_activos_id_deterorio_activo_seq; Type: SEQUENCE; Schema: modulo6; Owner: postgres
--

CREATE SEQUENCE modulo6.deterorios_activos_id_deterorio_activo_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo6.deterorios_activos_id_deterorio_activo_seq OWNER TO postgres;

--
-- Name: deterorios_activos_id_deterorio_activo_seq; Type: SEQUENCE OWNED BY; Schema: modulo6; Owner: postgres
--

ALTER SEQUENCE modulo6.deterorios_activos_id_deterorio_activo_seq OWNED BY modulo6.deterorios_activos.id_deterorio_activo;


