--
-- Name: mediciones_posteriores; Type: TABLE; Schema: modulo6; Owner: postgres
--

CREATE TABLE modulo6.mediciones_posteriores (
    "id_ medicion_posterior" integer NOT NULL,
    id_activo_biologico integer NOT NULL,
    id_evento integer,
    id_calculo_actual integer NOT NULL,
    id_calculo_anterior integer NOT NULL,
    origen_medicion modulo6.enum_mediciones_posteriores_origen_medicion NOT NULL,
    valor_razonable_anterior numeric(18,4) NOT NULL,
    valor_razonable_actual numeric(18,4) NOT NULL,
    ganancia_perdida_transformacion numeric(18,4) NOT NULL,
    ganancia_perdida_precio_mercado numeric(18,4) NOT NULL,
    variacion_total numeric(18,4) NOT NULL,
    tiene_valor_estimado boolean DEFAULT false NOT NULL,
    estado modulo6.enum_mediciones_posteriores_estado DEFAULT 'COMPLETADO'::modulo6.enum_mediciones_posteriores_estado NOT NULL,
    id_periodo_contable integer NOT NULL,
    fecha_medicion timestamp with time zone DEFAULT now() NOT NULL,
    supuestos_aplicados jsonb,
    id_asiento_contable integer,
    tipo_origen character varying(30),
    CONSTRAINT chk_medicion_fecha_no_futura CHECK ((fecha_medicion <= now())),
    CONSTRAINT chk_medicion_valores_positivos CHECK (((valor_razonable_anterior > (0)::numeric) AND (valor_razonable_actual > (0)::numeric))),
    CONSTRAINT chk_variacion_total_coherente CHECK ((abs((variacion_total - (valor_razonable_actual - valor_razonable_anterior))) < 0.01))
);


ALTER TABLE modulo6.mediciones_posteriores OWNER TO postgres;

--
-- Name: TABLE mediciones_posteriores; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TABLE modulo6.mediciones_posteriores IS 'Registra periódicamente la variación del valor razonable de cada activo biológico, descomponiéndola en dos componentes diferenciados según NIC 41 Párr. 12: transformación biológica (cambio físico del activo) y variación de precio de mercado (cambio externo). No recalcula el valor razonable; consume valores de calculos_valor_razonable. Referencia: RF-83.';


--
-- Name: COLUMN mediciones_posteriores."id_ medicion_posterior"; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.mediciones_posteriores."id_ medicion_posterior" IS 'PK serial. Identificador único de la medición posterior. [Nota: el nombre tiene un espacio; corregir a "id_medicion_posterior" en próxima migración.] Referenciado por variaciones_valor_razonable para vincular cada asiento contable a la medición que lo originó.';


--
-- Name: COLUMN mediciones_posteriores.id_activo_biologico; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.mediciones_posteriores.id_activo_biologico IS 'FK → modulo2.activos_biologicos. Activo biológico sobre el que se ejecuta la medición. El activo debe tener reconocimiento inicial CONFIRMADO en reconocimientos_iniciales y estado ACTIVO en M02.';


--
-- Name: COLUMN mediciones_posteriores.id_evento; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.mediciones_posteriores.id_evento IS 'FK → modulo2.eventos_activos. Evento biológico que desencadenó esta medición (RF-40: crecimiento, RF-42: reproducción, RF-43: producción, RF-44: deterioro de estado, RF-45: baja). Nulo cuando la medición se origina por cierre de período (origen_medicion = CIERRE_PERIODO).';


--
-- Name: COLUMN mediciones_posteriores.id_calculo_actual; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.mediciones_posteriores.id_calculo_actual IS 'FK → modulo6.calculos_valor_razonable. Cálculo de valor razonable neto después del evento biológico actual. Consumido desde RF-84; RF-83 no recalcula el valor directamente. Junto con id_calculo_anterior determina la variación total del período.';


--
-- Name: COLUMN mediciones_posteriores.id_calculo_anterior; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.mediciones_posteriores.id_calculo_anterior IS 'FK → modulo6.calculos_valor_razonable. Cálculo de valor razonable neto de la medición inmediatamente anterior para este activo. Es el punto de referencia para calcular la variación. En la primera medición del activo corresponde al cálculo del reconocimiento inicial (RF-82).';


--
-- Name: COLUMN mediciones_posteriores.origen_medicion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.mediciones_posteriores.origen_medicion IS 'Fuente que desencadenó la medición. EVENTO_BIOLOGICO: triggereada por un evento de M02 (RF-40, RF-42, RF-43, RF-44, RF-45). CIERRE_PERIODO: triggereada por el proceso masivo de RF-87; en este caso toda la variación se considera efecto precio (no hay cambio físico del activo en el cierre).';


--
-- Name: COLUMN mediciones_posteriores.valor_razonable_anterior; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.mediciones_posteriores.valor_razonable_anterior IS 'Valor razonable neto del activo antes del evento actual, en COP DECIMAL(18,4). Tomado del id_calculo_anterior. Punto de partida para calcular los dos componentes de variación y validar la ecuación de consistencia.';


--
-- Name: COLUMN mediciones_posteriores.valor_razonable_actual; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.mediciones_posteriores.valor_razonable_actual IS 'Valor razonable neto del activo después del evento actual, en COP DECIMAL(18,4). Tomado del id_calculo_actual. El sistema actualiza este valor en el campo correspondiente del activo en M02 tras confirmar la medición.';


--
-- Name: COLUMN mediciones_posteriores.ganancia_perdida_transformacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.mediciones_posteriores.ganancia_perdida_transformacion IS 'Componente de variación atribuible exclusivamente al cambio físico del activo (crecimiento, procreación, producción o degeneración). Calculado como: valor_razonable_actual − valor_razonable_pre_evento_ajustado_por_precio. Positivo = ganancia; negativo = pérdida.';


--
-- Name: COLUMN mediciones_posteriores.ganancia_perdida_precio_mercado; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.mediciones_posteriores.ganancia_perdida_precio_mercado IS 'Componente de variación atribuible exclusivamente al cambio en el precio de mercado de referencia, sin que el activo haya cambiado físicamente. Calculado como: valor_razonable_pre_evento_ajustado_por_precio − valor_razonable_anterior. Positivo = ganancia; negativo = pérdida.';


--
-- Name: COLUMN mediciones_posteriores.variacion_total; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.mediciones_posteriores.variacion_total IS 'Variación total del valor razonable: ganancia_perdida_transformacion + ganancia_perdida_precio_mercado = valor_razonable_actual − valor_razonable_anterior. El sistema valida esta ecuación de consistencia antes de confirmar el registro (RF-83 RNF-05).';


--
-- Name: COLUMN mediciones_posteriores.tiene_valor_estimado; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.mediciones_posteriores.tiene_valor_estimado IS 'true cuando no existe precio de mercado vigente en RF-89 y el sistema aplicó la jerarquía de estimación: (1) último precio disponible histórico, (2) valoración por costo. Genera alerta MEDICION_PENDIENTE al Contador para revisión. DEFAULT false.';


--
-- Name: COLUMN mediciones_posteriores.estado; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.mediciones_posteriores.estado IS 'Estado de la medición. COMPLETADO: ambos componentes calculados y consistentes; disponible para RF-86. MEDICION_PENDIENTE: sin precio de mercado disponible, esperando resolución del Contador. ERROR: fallo en cadena RF-83 → RF-84; activo bloqueado para ese evento. Default: COMPLETADO.';


--
-- Name: COLUMN mediciones_posteriores.id_periodo_contable; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.mediciones_posteriores.id_periodo_contable IS 'FK → modulo6.periodos_contables. Período contable ABIERTO al que pertenece esta medición. No se ejecutan mediciones en períodos CERRADOS o EN_CIERRE (excepto en el proceso de cierre masivo RF-87).';


--
-- Name: COLUMN mediciones_posteriores.fecha_medicion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.mediciones_posteriores.fecha_medicion IS 'Timestamp de ejecución de la medición. DEFAULT now(). Debe coincidir con la fecha del evento biológico (medición por evento) o con la fecha de inicio del cierre (medición por cierre RF-87).';


--
-- Name: mediciones_posteriores_id_ medicion_posterior_seq; Type: SEQUENCE; Schema: modulo6; Owner: postgres
--

CREATE SEQUENCE modulo6."mediciones_posteriores_id_ medicion_posterior_seq"
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo6."mediciones_posteriores_id_ medicion_posterior_seq" OWNER TO postgres;

--
-- Name: mediciones_posteriores_id_ medicion_posterior_seq; Type: SEQUENCE OWNED BY; Schema: modulo6; Owner: postgres
--

ALTER SEQUENCE modulo6."mediciones_posteriores_id_ medicion_posterior_seq" OWNED BY modulo6.mediciones_posteriores."id_ medicion_posterior";


--
-- Name: parametros_costos_venta; Type: TABLE; Schema: modulo6; Owner: postgres
--

CREATE TABLE modulo6.parametros_costos_venta (
    id_parametro_costo_venta integer NOT NULL,
    id_especie integer NOT NULL,
    region character varying(100) NOT NULL,
    pct_transporte numeric(5,4) DEFAULT 0 NOT NULL,
    pct_comisiones numeric(5,4) DEFAULT 0 NOT NULL,
    pct_impuestos numeric(5,4) DEFAULT 0 NOT NULL,
    es_activo boolean DEFAULT true NOT NULL,
    id_usuario integer NOT NULL,
    fecha_creacion timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_param_pct_comisiones_rango CHECK (((pct_comisiones >= (0)::numeric) AND (pct_comisiones <= (1)::numeric))),
    CONSTRAINT chk_param_pct_impuestos_rango CHECK (((pct_impuestos >= (0)::numeric) AND (pct_impuestos <= (1)::numeric))),
    CONSTRAINT chk_param_pct_transporte_rango CHECK (((pct_transporte >= (0)::numeric) AND (pct_transporte <= (1)::numeric))),
    CONSTRAINT chk_param_region_no_vacia CHECK ((char_length(TRIM(BOTH FROM region)) > 0))
);


ALTER TABLE modulo6.parametros_costos_venta OWNER TO postgres;

--
-- Name: TABLE parametros_costos_venta; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TABLE modulo6.parametros_costos_venta IS 'Almacena los parámetros de costos de venta configurados en M09 por especie y región geográfica. Son consumidos automáticamente por calculos_valor_razonable (RF-84) para deducir el valor razonable bruto y obtener el valor neto según Párr. 12 NIC 41. El Contador puede sobrescribir estos valores para transacciones específicas con justificación obligatoria. Referencia: RF-84, RF-90.';


--
-- Name: COLUMN parametros_costos_venta.id_parametro_costo_venta; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.parametros_costos_venta.id_parametro_costo_venta IS 'PK serial. Identificador único del parámetro. [Nota: el nombre tiene un espacio al final; corregir en próxima migración.] Referenciado por calculos_valor_razonable.id_parametro_costo_venta para documentar qué parámetros se aplicaron en cada cálculo.';


--
-- Name: COLUMN parametros_costos_venta.id_especie; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.parametros_costos_venta.id_especie IS 'FK → modulo9.especies. Especie para la cual aplican estos parámetros. Junto con region forma la clave de unicidad (uq_param_especie_region), garantizando que solo exista un set de parámetros activo por especie y región.';


--
-- Name: COLUMN parametros_costos_venta.region; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.parametros_costos_venta.region IS 'Región geográfica del departamento o municipio a la que aplican los costos. Junto con id_especie define el contexto de mercado específico. Ejemplos: "Huila", "Neiva", "Pitalito". Relevante para el contexto UPRA colombiano.';


--
-- Name: COLUMN parametros_costos_venta.pct_transporte; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.parametros_costos_venta.pct_transporte IS 'Porcentaje del precio bruto que corresponde al costo de transporte del activo al punto de venta. DECIMAL(5,4) para precisión de hasta 99.9999%. Aplicado automáticamente en RF-84 como deducción del valor razonable. DEFAULT 0.';


--
-- Name: COLUMN parametros_costos_venta.pct_comisiones; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.parametros_costos_venta.pct_comisiones IS 'Porcentaje del precio bruto que corresponde a comisiones de intermediación en la transacción de venta. Deducido del valor razonable en RF-84. El Contador puede sobrescribirlo para una transacción específica con justificación registrada en auditorias_financieras. DEFAULT 0.';


--
-- Name: COLUMN parametros_costos_venta.pct_impuestos; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.parametros_costos_venta.pct_impuestos IS 'Porcentaje correspondiente a impuestos directamente atribuibles a la transacción de venta (excluye impuesto sobre la renta). Deducido del valor razonable en RF-84. Configurado por el Administrador en M09. DEFAULT 0.';


--
-- Name: COLUMN parametros_costos_venta.es_activo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.parametros_costos_venta.es_activo IS 'Indica si el parámetro está vigente y disponible para nuevos cálculos. false: desactivado por el Administrador en M09. Los registros desactivados persisten en la tabla para trazabilidad de cálculos históricos. DEFAULT true.';


--
-- Name: COLUMN parametros_costos_venta.id_usuario; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.parametros_costos_venta.id_usuario IS 'FK → modulo1.usuarios. Administrador del sistema que configuró o modificó estos parámetros en M09. Los cambios aplican prospectivamente y no recalculan valores históricos ya confirmados.';


--
-- Name: COLUMN parametros_costos_venta.fecha_creacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.parametros_costos_venta.fecha_creacion IS 'Timestamp de creación del parámetro. DEFAULT now(). Permite auditar cuándo se configuró cada set de parámetros y qué valores existían en períodos anteriores.';


--
-- Name: parametros_costos_venta_id_parametro_costo_venta _seq; Type: SEQUENCE; Schema: modulo6; Owner: postgres
--

CREATE SEQUENCE modulo6."parametros_costos_venta_id_parametro_costo_venta _seq"
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo6."parametros_costos_venta_id_parametro_costo_venta _seq" OWNER TO postgres;

--
-- Name: parametros_costos_venta_id_parametro_costo_venta _seq; Type: SEQUENCE OWNED BY; Schema: modulo6; Owner: postgres
--

ALTER SEQUENCE modulo6."parametros_costos_venta_id_parametro_costo_venta _seq" OWNED BY modulo6.parametros_costos_venta.id_parametro_costo_venta;


--
-- Name: periodos_contables; Type: TABLE; Schema: modulo6; Owner: postgres
--

CREATE TABLE modulo6.periodos_contables (
    id_periodo_contable integer NOT NULL,
    tipo_cierre modulo6.enum_periodos_contables_tipo_cierre NOT NULL,
    fecha_inicio date NOT NULL,
    fecha_fin date NOT NULL,
    estado modulo6.enum_periodo_contables_estado DEFAULT 'ABIERTO'::modulo6.enum_periodo_contables_estado NOT NULL,
    fecha_cierre timestamp with time zone,
    id_usuario integer NOT NULL,
    fecha_creacion timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_periodo_fechas CHECK ((fecha_fin > fecha_inicio)),
    CONSTRAINT chk_periodo_inicio_no_futuro CHECK ((fecha_inicio <= CURRENT_DATE))
);


ALTER TABLE modulo6.periodos_contables OWNER TO postgres;

--
-- Name: TABLE periodos_contables; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TABLE modulo6.periodos_contables IS 'Define los intervalos contables (mensual, trimestral o anual) que agrupan todos los registros financieros del módulo NIC 41. Controla el ciclo de vida del período: ABIERTO → EN_CIERRE → CERRADO. Un período CERRADO es inmutable; las correcciones se realizan en el período siguiente. Referencia: RF-87.';


--
-- Name: COLUMN periodos_contables.id_periodo_contable; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.periodos_contables.id_periodo_contable IS 'PK serial. Identificador único del período contable. Referenciado por la mayoría de tablas del módulo como llave foránea para garantizar que cada registro financiero pertenezca a un período específico.';


--
-- Name: COLUMN periodos_contables.tipo_cierre; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.periodos_contables.tipo_cierre IS 'Frecuencia del período según configuración de M09. Valores: MENSUAL (1 mes calendario), TRIMESTRAL (3 meses), ANUAL (año fiscal). Determina el alcance temporal de la revaluación masiva de RF-87.';


--
-- Name: COLUMN periodos_contables.fecha_inicio; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.periodos_contables.fecha_inicio IS 'Fecha de inicio del período contable. Junto con fecha_fin forma el rango único del período. No puede solaparse con otro período existente (constraint uq_periodo_rango).';


--
-- Name: COLUMN periodos_contables.fecha_fin; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.periodos_contables.fecha_fin IS 'Fecha de cierre del período contable. Delimita hasta qué fecha se aceptan registros de variaciones, costos y mediciones en este período.';


--
-- Name: COLUMN periodos_contables.estado; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.periodos_contables.estado IS 'Estado del ciclo de vida del período. ABIERTO: acepta nuevos registros. EN_CIERRE: el proceso RF-87 está en ejecución; bloquea nuevas escrituras. CERRADO: inmutable, apto para exportación a M07. Default: ABIERTO.';


--
-- Name: COLUMN periodos_contables.fecha_cierre; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.periodos_contables.fecha_cierre IS 'Timestamp exacto en que el Contador completó el proceso de cierre (RF-87 paso 9). Nulo mientras el período esté ABIERTO o EN_CIERRE. Registrado junto con el hash SHA-256 del estado final.';


--
-- Name: COLUMN periodos_contables.id_usuario; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.periodos_contables.id_usuario IS 'FK → modulo1.usuarios. Identificador del Contador autenticado en M01 que creó o ejecutó el cierre del período. Solo el rol Contador tiene permisos de cierre.';


--
-- Name: COLUMN periodos_contables.fecha_creacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.periodos_contables.fecha_creacion IS 'Timestamp de inserción del registro. Generado automáticamente por el sistema (DEFAULT now()). Inmutable una vez creado.';


--
-- Name: periodos_contables_id_periodo_contable_seq; Type: SEQUENCE; Schema: modulo6; Owner: postgres
--

CREATE SEQUENCE modulo6.periodos_contables_id_periodo_contable_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo6.periodos_contables_id_periodo_contable_seq OWNER TO postgres;

--
-- Name: periodos_contables_id_periodo_contable_seq; Type: SEQUENCE OWNED BY; Schema: modulo6; Owner: postgres
--

ALTER SEQUENCE modulo6.periodos_contables_id_periodo_contable_seq OWNED BY modulo6.periodos_contables.id_periodo_contable;


--
-- Name: precios_mercado; Type: TABLE; Schema: modulo6; Owner: postgres
--

CREATE TABLE modulo6.precios_mercado (
    id_precio_mercado integer NOT NULL,
    id_especie integer NOT NULL,
    categoria modulo6.enum_precio_mercado_categoria[] NOT NULL,
    precio_unitario numeric(10,2) NOT NULL,
    unidad_medida character varying(20) NOT NULL,
    fecha_vencimiento date,
    fecha_vigencia date NOT NULL,
    fuente modulo6.enum_precio_mercado_fuente NOT NULL,
    estado modulo6.enum_precio_mercado_estado DEFAULT 'PROGRAMADO'::modulo6.enum_precio_mercado_estado NOT NULL,
    evidencia character varying(500) NOT NULL,
    justificacion character varying(500),
    origen_registro modulo6.enum_precios_mercado_origen_precio DEFAULT 'MANUAL'::modulo6.enum_precios_mercado_origen_precio NOT NULL,
    id_usuario integer NOT NULL,
    id_precio_coregido integer,
    fecha_registro timestamp with time zone DEFAULT now() NOT NULL,
    version_precio integer DEFAULT 1 NOT NULL,
    region character varying(50),
    hash_evidencia character varying(64),
    CONSTRAINT chk_estimada_requiere_justificacion CHECK (((fuente <> 'ESTIMADA'::modulo6.enum_precio_mercado_fuente) OR (justificacion IS NOT NULL))),
    CONSTRAINT chk_precio_evidencia_no_vacia CHECK ((char_length(TRIM(BOTH FROM evidencia)) > 0)),
    CONSTRAINT chk_precio_unidad_no_vacia CHECK ((char_length(TRIM(BOTH FROM unidad_medida)) > 0)),
    CONSTRAINT chk_precio_unitario_positivo CHECK ((precio_unitario > (0)::numeric)),
    CONSTRAINT chk_precio_vencimiento CHECK (((fecha_vencimiento IS NULL) OR (fecha_vencimiento > fecha_vigencia))),
    CONSTRAINT chk_vigencia_no_retroactiva CHECK ((fecha_vigencia >= (CURRENT_DATE - '365 days'::interval)))
);


ALTER TABLE modulo6.precios_mercado OWNER TO postgres;

--
-- Name: TABLE precios_mercado; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TABLE modulo6.precios_mercado IS 'Repositorio centralizado e inmutable (append-only) de precios de referencia para la valoración de activos biológicos y productos agrícolas bajo NIC 41 Párr. 17. Soporta tres fuentes priorizadas: MERCADO_ACTIVO > UPRA > ESTIMADA. Ningún precio puede editarse; las correcciones se registran como nuevas entradas. Referencia: RF-89.';


--
-- Name: COLUMN precios_mercado.id_precio_mercado; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.precios_mercado.id_precio_mercado IS 'PK serial. Identificador único del registro de precio. Referenciado por calculos_valor_razonable y reconocimientos_iniciales para trazabilidad del precio aplicado en cada cálculo (RF-91).';


--
-- Name: COLUMN precios_mercado.id_especie; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.precios_mercado.id_especie IS 'FK → modulo9.especies. Especie del activo biológico para la cual aplica este precio. Junto con cagetoria, fuente y fecha_vigencia forma la clave de unicidad (uq_precio_especie_cat_fuente_vigencia).';


--
-- Name: COLUMN precios_mercado.categoria; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.precios_mercado.categoria IS 'Array de categorías de precio según configuración de M09. Ejemplos: "Peso vivo (/kg)", "Por cabeza (/unidad)", "Leche (/litro)". Determina la unidad de medida en que se expresa el precio. [Nota: el nombre correcto sería "categoria"; revisar en próxima migración.]';


--
-- Name: COLUMN precios_mercado.precio_unitario; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.precios_mercado.precio_unitario IS 'Valor monetario del precio por unidad de medida en COP. No puede ser cero ni negativo (validar con CHECK precio_unitario > 0). Si supera ±50% respecto al precio vigente anterior de la misma fuente/especie/categoría, el sistema exige confirmación explícita del Contador.';


--
-- Name: COLUMN precios_mercado.unidad_medida; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.precios_mercado.unidad_medida IS 'Unidad de medida asociada al precio_unitario: kg, unidad, litro, canal, etc. Debe coincidir con la configuración de M09 para la especie y categoría indicadas.';


--
-- Name: COLUMN precios_mercado.fecha_vencimiento; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.precios_mercado.fecha_vencimiento IS 'Fecha hasta la cual el precio es válido. Opcional (nullable). Si se informa, debe ser posterior a fecha_vigencia. Al vencerse sin reemplazo, los activos de esa especie/categoría pasan a SIN_PRECIO_VIGENTE y se alerta al Contador para aplicar RF-88.';


--
-- Name: COLUMN precios_mercado.fecha_vigencia; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.precios_mercado.fecha_vigencia IS 'Fecha a partir de la cual el precio es válido para cálculos. Si es igual o anterior a now(), el precio queda en estado ACTIVO inmediatamente. Si es futura, queda en PROGRAMADO y el sistema lo activa automáticamente al llegar esa fecha.';


--
-- Name: COLUMN precios_mercado.fuente; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.precios_mercado.fuente IS 'Origen del precio según jerarquía NIC 41. MERCADO_ACTIVO: subasta, feria o bolsa (máxima prioridad). UPRA: precio referencial publicado por la Unidad de Planificación Rural Agropecuaria. ESTIMADA: cálculo del Contador con comparables; requiere justificacion obligatoria.';


--
-- Name: COLUMN precios_mercado.estado; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.precios_mercado.estado IS 'Estado operativo del precio dentro del repositorio. ACTIVO: vigente y disponible para cálculos. PROGRAMADO: fecha_vigencia futura, no disponible aún. VENCIDO: superó fecha_vencimiento sin reemplazo. SUPERADO: reemplazado por un precio más reciente de la misma fuente/especie/categoría. PENDIENTE_CONFIRMACION: recibido por API de M07, pendiente de aprobación del Contador. Default: PROGRAMADO.';


--
-- Name: COLUMN precios_mercado.evidencia; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.precios_mercado.evidencia IS 'Referencia documental obligatoria que sustenta el precio: URL del boletín UPRA, número de acta de feria, número de resolución, etc. Sin este campo el registro es inválido. Garantiza auditabilidad ante revisiones externas NIC 41.';


--
-- Name: COLUMN precios_mercado.justificacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.precios_mercado.justificacion IS 'Descripción obligatoria únicamente cuando fuente = ESTIMADA. Debe explicar: (1) razón de indisponibilidad de MERCADO_ACTIVO, (2) razón de indisponibilidad de UPRA, (3) comparables utilizados. Nulo para las otras dos fuentes.';


--
-- Name: COLUMN precios_mercado.origen_registro; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.precios_mercado.origen_registro IS 'Indica cómo fue registrado el precio. MANUAL: ingresado directamente por el Contador desde la interfaz de M06. API_M07: recibido automáticamente desde la integración con M07; requiere aprobación del Contador antes de quedar ACTIVO.';


--
-- Name: COLUMN precios_mercado.id_usuario; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.precios_mercado.id_usuario IS 'FK → modulo1.usuarios. Contador que registró o aprobó el precio. Solo el rol Contador tiene permisos de escritura en este repositorio, verificado contra M01.';


--
-- Name: COLUMN precios_mercado.id_precio_coregido; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.precios_mercado.id_precio_coregido IS 'FK self → precios_mercado. Referencia al id_precio_mercado del registro que este precio corrige. Permite reconstruir la cadena de correcciones históricas sin modificar registros anteriores (política append-only). Nulo si es un registro original. [Nota: "coregido" → corregir typo a "corregido" en próxima migración.]';


--
-- Name: COLUMN precios_mercado.fecha_registro; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.precios_mercado.fecha_registro IS 'Timestamp de inserción del registro en el repositorio. DEFAULT now(). Inmutable. Junto con id_precio_mercado permite ordenar cronológicamente el historial de precios por especie.';


--
-- Name: precios_mercado_id_precio_mercado_seq; Type: SEQUENCE; Schema: modulo6; Owner: postgres
--

CREATE SEQUENCE modulo6.precios_mercado_id_precio_mercado_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo6.precios_mercado_id_precio_mercado_seq OWNER TO postgres;

--
-- Name: precios_mercado_id_precio_mercado_seq; Type: SEQUENCE OWNED BY; Schema: modulo6; Owner: postgres
--

ALTER SEQUENCE modulo6.precios_mercado_id_precio_mercado_seq OWNED BY modulo6.precios_mercado.id_precio_mercado;


--
-- Name: reconocimientos_iniciales; Type: TABLE; Schema: modulo6; Owner: postgres
--

CREATE TABLE modulo6.reconocimientos_iniciales (
    id_reconocimiento_inicial integer NOT NULL,
    id_activo_biologico integer NOT NULL,
    fecha_reconocimiento timestamp with time zone DEFAULT now(),
    clasificacion modulo6.enum_reconocimientos_iniciales_clasificacion NOT NULL,
    indicador_valoracion modulo6.enum_reconocimientos_iniciales_indicador_valoracion NOT NULL,
    id_precio_mercado integer NOT NULL,
    valor_razonable_neto_inicial numeric(18,4) NOT NULL,
    costos_venta_estimados numeric(18,4) DEFAULT 0 NOT NULL,
    estado modulo6.enum_reconocimientos_iniciales_estado_reconocimiento DEFAULT 'PENDIENTE_CONFIRMACION'::modulo6.enum_reconocimientos_iniciales_estado_reconocimiento NOT NULL,
    cuenta_debito character varying(20) NOT NULL,
    cuenta_credito character varying(20) NOT NULL,
    id_usuario integer NOT NULL,
    id_periodo_contable integer NOT NULL,
    fecha_creacion timestamp with time zone DEFAULT now() NOT NULL,
    justificacion_reversion text,
    metodo_valoracion character varying(20),
    CONSTRAINT chk_reconoc_costos_venta_no_negativos CHECK ((costos_venta_estimados >= (0)::numeric)),
    CONSTRAINT chk_reconoc_cuentas_no_vacias CHECK (((char_length(TRIM(BOTH FROM cuenta_debito)) > 0) AND (char_length(TRIM(BOTH FROM cuenta_credito)) > 0))),
    CONSTRAINT chk_reconoc_fecha_no_futura CHECK (((fecha_reconocimiento IS NULL) OR (fecha_reconocimiento <= now()))),
    CONSTRAINT chk_reconoc_valor_positivo CHECK ((valor_razonable_neto_inicial > (0)::numeric))
);


ALTER TABLE modulo6.reconocimientos_iniciales OWNER TO postgres;

--
-- Name: TABLE reconocimientos_iniciales; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TABLE modulo6.reconocimientos_iniciales IS 'Registra el primer asiento contable del activo biológico en el módulo financiero, conforme al Párrafo 10 de la NIC 41. Una vez CONFIRMADO es inmutable; solo puede anularse mediante una reversión auditada en revisiones_reconocimiento. Solo puede existir un reconocimiento vigente por activo (constraint uq sobre id_actvo_biologico). Referencia: RF-82.';


--
-- Name: COLUMN reconocimientos_iniciales.id_reconocimiento_inicial; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_iniciales.id_reconocimiento_inicial IS 'PK serial. Identificador único del reconocimiento inicial. Referenciado por revisiones_reconocimiento (para reversiones) y por mediciones_posteriores como punto de partida del valor base del activo.';


--
-- Name: COLUMN reconocimientos_iniciales.id_activo_biologico; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_iniciales.id_activo_biologico IS 'FK → modulo2.activos_biologicos. Activo biológico que se reconoce contablemente. Tiene constraint UNIQUE: no puede existir más de un reconocimiento inicial vigente por activo. [Nota: "actvo" → corregir typo a "activo_biologico" en próxima migración.]';


--
-- Name: COLUMN reconocimientos_iniciales.fecha_reconocimiento; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_iniciales.fecha_reconocimiento IS 'Timestamp del reconocimiento inicial. Debe coincidir con la fecha de ingreso del activo en RF-33. No se admiten valores retroactivos. Referenciado por la cadena de trazabilidad de RF-91. [Nota: el nombre tiene un espacio al final; corregir en próxima migración.]';


--
-- Name: COLUMN reconocimientos_iniciales.clasificacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_iniciales.clasificacion IS 'Propósito del activo según NIC 41 y M09. PRODUCCION: genera outputs periódicos sin que el activo se consuma (vacas lecheras, gallinas). CONSUMO: el activo en sí se cosecha o sacrifica al finalizar el ciclo (bovinos de carne, peces). Determina el comportamiento contable en reconocimientos_productos_agricolas.';


--
-- Name: COLUMN reconocimientos_iniciales.indicador_valoracion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_iniciales.indicador_valoracion IS 'Método de valoración aplicado en el reconocimiento inicial. VALOR_RAZONABLE: precio de mercado de RF-89 disponible; se usa RF-84. VALORACION_POR_COSTO: sin precio de mercado activo; se delega el cálculo a RF-88 (Párr. 30 NIC 41). Genera alerta ADVERTENCIA al Contador cuando es VALORACION_POR_COSTO.';


--
-- Name: COLUMN reconocimientos_iniciales.id_precio_mercado; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_iniciales.id_precio_mercado IS 'FK → modulo6.precios_mercado. Precio de referencia vigente a la fecha del reconocimiento utilizado para calcular el valor razonable bruto. Garantiza trazabilidad desde el asiento contable hasta el precio de mercado (Nivel 4 → Nivel 3 en RF-91). Obligatorio incluso en VALORACION_POR_COSTO para documentar la ausencia de precio.';


--
-- Name: COLUMN reconocimientos_iniciales.valor_razonable_neto_inicial; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_iniciales.valor_razonable_neto_inicial IS 'Valor razonable menos costos de venta calculado por RF-84 en la fecha del reconocimiento, expresado en COP con precisión DECIMAL(18,4). Establece el valor base para todas las mediciones posteriores requeridas por RF-83. En VALORACION_POR_COSTO corresponde al costo_adquisicion calculado por RF-88.';


--
-- Name: COLUMN reconocimientos_iniciales.costos_venta_estimados; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_iniciales.costos_venta_estimados IS 'Costos estimados en el punto de venta (transporte, comisiones, impuestos de transacción) deducidos del precio bruto para obtener el valor razonable neto, según Párr. 12 NIC 41. Obtenidos automáticamente desde M09 o ingresados manualmente por el Contador. DEFAULT 0: si son cero, valor_razonable_neto = precio_bruto.';


--
-- Name: COLUMN reconocimientos_iniciales.estado; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_iniciales.estado IS 'Estado del reconocimiento en su ciclo de vida. PENDIENTE_CONFIRMACION: propuesta generada automáticamente por el sistema, esperando validación del Contador. CONFIRMADO: aprobado y registrado de forma definitiva; inmutable. REVERTIDO: anulado contablemente mediante una entrada en revisiones_reconocimiento (el registro original persiste para trazabilidad). Default: PENDIENTE_CONFIRMACION.';


--
-- Name: COLUMN reconocimientos_iniciales.cuenta_debito; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_iniciales.cuenta_debito IS 'Cuenta contable debitada en el asiento inicial según el Plan Único de Cuentas (PUC colombiano) y el catálogo parametrizado de M07. Generalmente la cuenta del Activo Biológico (120505). Determinada automáticamente por el sistema según origen_financiero_activo del evento RF-33.';


--
-- Name: COLUMN reconocimientos_iniciales.cuenta_credito; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_iniciales.cuenta_credito IS 'Cuenta contable acreditada en el asiento inicial, determinada por origen_financiero_activo: COMPRA → Cuentas por Pagar/Efectivo; NACIMIENTO → Ingreso por transformación biológica; DONACION → Ingreso por donación; TRANSFERENCIA_INTERNA → Cuenta de traslado interno.';


--
-- Name: COLUMN reconocimientos_iniciales.id_usuario; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_iniciales.id_usuario IS 'FK → modulo1.usuarios. Contador autenticado en M01 que confirmó el reconocimiento inicial. Solo el rol Contador puede confirmar; cualquier otro intento es rechazado y registrado en auditorias_financieras.';


--
-- Name: COLUMN reconocimientos_iniciales.id_periodo_contable; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_iniciales.id_periodo_contable IS 'FK → modulo6.periodos_contables. Período contable ABIERTO al que pertenece este reconocimiento. El período debe estar en estado ABIERTO; no se admiten reconocimientos en períodos EN_CIERRE o CERRADOS.';


--
-- Name: COLUMN reconocimientos_iniciales.fecha_creacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_iniciales.fecha_creacion IS 'Timestamp de inserción del registro en la base de datos. DEFAULT now(). Inmutable. Diferente de "fecha_reconocimiento", que es la fecha contable del evento.';


--
-- Name: reconocimientos_iniciales_id_reconocimiento_inicial_seq; Type: SEQUENCE; Schema: modulo6; Owner: postgres
--

CREATE SEQUENCE modulo6.reconocimientos_iniciales_id_reconocimiento_inicial_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo6.reconocimientos_iniciales_id_reconocimiento_inicial_seq OWNER TO postgres;

--
-- Name: reconocimientos_iniciales_id_reconocimiento_inicial_seq; Type: SEQUENCE OWNED BY; Schema: modulo6; Owner: postgres
--

ALTER SEQUENCE modulo6.reconocimientos_iniciales_id_reconocimiento_inicial_seq OWNED BY modulo6.reconocimientos_iniciales.id_reconocimiento_inicial;


--
-- Name: reconocimientos_productos_agricolas; Type: TABLE; Schema: modulo6; Owner: postgres
--

CREATE TABLE modulo6.reconocimientos_productos_agricolas (
    id_reconocimiento_prodcutos_agricola integer NOT NULL,
    id_evento_productivo integer NOT NULL,
    id_activo_biologico integer NOT NULL,
    producto_agricola character varying(100) NOT NULL,
    cantidad_cosechada numeric(18,4) NOT NULL,
    unidad_medida character varying(20) NOT NULL,
    precio_mercado_producto numeric(18,4) NOT NULL,
    costo_venta_producto numeric(18,4) NOT NULL,
    valor_producto numeric(18,4) NOT NULL,
    proporcion_cosechada numeric(8,6),
    valor_reduccion_activo numeric(18,4),
    id_calculo_valor_razonable integer NOT NULL,
    cuenta_debito character varying(20) NOT NULL,
    cuenta_credito character varying(20) NOT NULL,
    id_periodo_contable integer NOT NULL,
    id_parametro_m09 integer,
    justificacion text,
    fecha_cosecha date NOT NULL,
    fecha_registro timestamp with time zone DEFAULT now() NOT NULL,
    id_usuario integer NOT NULL,
    tipo modulo6.enum_reconocimientos_productos_agricolas_tipo_producto,
    CONSTRAINT chk_prod_agricola_cantidad_positiva CHECK ((cantidad_cosechada > (0)::numeric)),
    CONSTRAINT chk_prod_agricola_cosecha_no_futura CHECK ((fecha_cosecha <= CURRENT_DATE)),
    CONSTRAINT chk_prod_agricola_nombre_no_vacio CHECK ((char_length(TRIM(BOTH FROM producto_agricola)) > 0)),
    CONSTRAINT chk_prod_agricola_precio_positivo CHECK ((precio_mercado_producto > (0)::numeric)),
    CONSTRAINT chk_prod_agricola_proporcion_rango CHECK (((proporcion_cosechada IS NULL) OR ((proporcion_cosechada > (0)::numeric) AND (proporcion_cosechada <= (1)::numeric)))),
    CONSTRAINT chk_prod_agricola_unidad_no_vacia CHECK ((char_length(TRIM(BOTH FROM unidad_medida)) > 0)),
    CONSTRAINT chk_prod_agricola_valor_coherente CHECK ((abs((valor_producto - ((precio_mercado_producto - costo_venta_producto) * cantidad_cosechada))) <= 1.0))
);


ALTER TABLE modulo6.reconocimientos_productos_agricolas OWNER TO postgres;

--
-- Name: TABLE reconocimientos_productos_agricolas; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TABLE modulo6.reconocimientos_productos_agricolas IS 'Registra el reconocimiento contable de los productos agrícolas separados del activo biológico (leche, huevos, lana, biomasa piscícola, etc.) al valor razonable menos costos de venta en el punto de cosecha, conforme al Párr. 13 NIC 41. El valor reconocido se convierte en el costo de inventario bajo NIC 2. Un evento productivo (RF-43) solo puede generar un reconocimiento (constraint UNIQUE). Referencia: RF-85.';


--
-- Name: COLUMN reconocimientos_productos_agricolas.id_reconocimiento_prodcutos_agricola; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.id_reconocimiento_prodcutos_agricola IS 'PK serial. Identificador único del reconocimiento del producto agrícola. [Typo: "prodcutos" → "productos".] Referenciado en el módulo de inventarios como el costo NIC 2 del producto cosechado y en auditorias_financieras para trazabilidad.';


--
-- Name: COLUMN reconocimientos_productos_agricolas.id_evento_productivo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.id_evento_productivo IS 'FK → modulo2.eventos_productivos. Evento productivo de RF-43 que desencadenó este reconocimiento. Tiene constraint UNIQUE: cada evento productivo genera exactamente un reconocimiento; no se admiten duplicados. El evento debe contener: tipo_producto, cantidad_cosechada, unidad_medida y fecha_cosecha.';


--
-- Name: COLUMN reconocimientos_productos_agricolas.id_activo_biologico; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.id_activo_biologico IS 'FK → modulo2.activos_biologicos. Activo biológico que generó el producto. Debe estar en estado ACTIVO en M02. Para PRODUCTO_DE_CONSUMO, el valor del activo se reduce proporcionalmente tras el reconocimiento.';


--
-- Name: COLUMN reconocimientos_productos_agricolas.producto_agricola; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.producto_agricola IS 'Nombre o código del producto cosechado. Ejemplos: "Leche", "Huevo", "Lana", "Miel", "Bovino de carne", "Biomasa piscícola". Usado en el catálogo de inventarios bajo NIC 2 para identificar el producto reconocido.';


--
-- Name: COLUMN reconocimientos_productos_agricolas.cantidad_cosechada; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.cantidad_cosechada IS 'Cantidad del producto cosechado expresada en la unidad_medida correspondiente (DECIMAL 18,4). Para PRODUCTO_DE_CONSUMO, junto con la cantidad total del activo en M02, determina la proporcion_cosechada y el valor_reduccion_activo.';


--
-- Name: COLUMN reconocimientos_productos_agricolas.unidad_medida; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.unidad_medida IS 'Unidad de medida de la cosecha: KG, LT, UNIDAD, M2, según la especie y el producto. Debe ser compatible con la unidad base del activo biológico o existir una regla de conversión en M09; sin ella el reconocimiento es bloqueado (RF-85 restricción 6).';


--
-- Name: COLUMN reconocimientos_productos_agricolas.precio_mercado_producto; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.precio_mercado_producto IS 'Precio de mercado de referencia vigente en RF-89 para el producto agrícola a la fecha de cosecha (DECIMAL 18,4). Es la base para calcular el valor_razonable_bruto del producto antes de deducir costos de venta.';


--
-- Name: COLUMN reconocimientos_productos_agricolas.costo_venta_producto; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.costo_venta_producto IS 'Costos de venta deducidos del precio bruto del producto para obtener el valor_producto conforme a NIC 41. Calculados por RF-84. Obtenidos de M09 (parametrizados) o ingresados manualmente por el Contador con justificacion obligatoria.';


--
-- Name: COLUMN reconocimientos_productos_agricolas.valor_producto; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.valor_producto IS 'Valor razonable menos costos de venta del producto agrícola en el punto de cosecha (DECIMAL 18,4). Este valor se transfiere íntegramente como costo de inventario bajo NIC 2 al módulo de inventarios. Inmutable una vez confirmado.';


--
-- Name: COLUMN reconocimientos_productos_agricolas.proporcion_cosechada; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.proporcion_cosechada IS 'Para PRODUCTO_DE_CONSUMO: cociente cantidad_cosechada / cantidad_total_activo (DECIMAL 8,6). Determina qué fracción del valor del activo biológico se reduce. Nulo para PRODUCTO_PERIODICO (el activo no se reduce en cosechas periódicas como leche o huevos).';


--
-- Name: COLUMN reconocimientos_productos_agricolas.valor_reduccion_activo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.valor_reduccion_activo IS 'Para PRODUCTO_DE_CONSUMO: monto en COP que se descuenta del valor contable del activo biológico en M02 y M06 (valor_activo_actual × proporcion_cosechada). Si proporcion_cosechada = 1 (cosecha total), el activo inicia proceso de baja en RF-45. Nulo para PRODUCTO_PERIODICO.';


--
-- Name: COLUMN reconocimientos_productos_agricolas.id_calculo_valor_razonable; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.id_calculo_valor_razonable IS 'FK → modulo6.calculos_valor_razonable. Cálculo de RF-84 que determinó el valor_producto. Garantiza que el costo NIC 2 esté sustentado en un cálculo formal de valor razonable con precio documentado en precios_mercado.';


--
-- Name: COLUMN reconocimientos_productos_agricolas.cuenta_debito; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.cuenta_debito IS 'Cuenta contable de Inventario de Productos Agrícolas (NIC 2) debitada en el asiento de reconocimiento. Definida en el catálogo contable de M07 según tipo de producto y especie.';


--
-- Name: COLUMN reconocimientos_productos_agricolas.cuenta_credito; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.cuenta_credito IS 'Cuenta contable acreditada. Para PRODUCTO_DE_CONSUMO: cuenta del Activo Biológico (reducción proporcional). Para PRODUCTO_PERIODICO: cuenta de Ganancia por medición a valor razonable (resultado del período NIC 41), no como ingreso operativo.';


--
-- Name: COLUMN reconocimientos_productos_agricolas.id_periodo_contable; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.id_periodo_contable IS 'FK → modulo6.periodos_contables. Período contable al que pertenece este reconocimiento. Debe generarse en el mismo período en que ocurrió el evento RF-43 (restricción 5 de RF-85).';


--
-- Name: COLUMN reconocimientos_productos_agricolas.id_parametro_m09; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.id_parametro_m09 IS 'FK → modulo6.parametros_costos_venta. Referencia a los parámetros de M09 utilizados en el cálculo de costos de venta del producto. Nulo cuando los costos fueron ingresados manualmente por el Contador.';


--
-- Name: COLUMN reconocimientos_productos_agricolas.justificacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.justificacion IS 'Descripción obligatoria cuando el Contador define manualmente los costos de venta del producto. Registrada en auditorias_financieras con identificación del usuario y fecha. Nula cuando los costos provienen de parámetros de M09.';


--
-- Name: COLUMN reconocimientos_productos_agricolas.fecha_cosecha; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.fecha_cosecha IS 'Fecha de separación del producto del activo biológico. Debe coincidir con la fecha del evento RF-43. Determina qué precio de RF-89 es vigente para el cálculo.';


--
-- Name: COLUMN reconocimientos_productos_agricolas.fecha_registro; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.fecha_registro IS 'Timestamp de inserción en la base de datos. DEFAULT now(). Diferente de fecha_cosecha, que es la fecha contable del evento de producción.';


--
-- Name: COLUMN reconocimientos_productos_agricolas.id_usuario; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.id_usuario IS 'FK → modulo1.usuarios. Contador que confirmó el reconocimiento del producto. El sistema ejecuta el proceso automáticamente al recibir el evento de RF-43, pero requiere confirmación del Contador para el registro definitivo.';


--
-- Name: COLUMN reconocimientos_productos_agricolas.tipo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.reconocimientos_productos_agricolas.tipo IS 'Clasificación del producto cosechado. PRODUCTO_DE_CONSUMO: la cosecha reduce el valor del activo (bovinos de carne, peces). PRODUCTO_PERIODICO: la cosecha no reduce el activo; se reconoce solo el ingreso (leche, huevos, lana). Determina el comportamiento contable del asiento generado.';


--
-- Name: reconocimientos_productos_agr_id_reconocimiento_prodcutos_a_seq; Type: SEQUENCE; Schema: modulo6; Owner: postgres
--

CREATE SEQUENCE modulo6.reconocimientos_productos_agr_id_reconocimiento_prodcutos_a_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo6.reconocimientos_productos_agr_id_reconocimiento_prodcutos_a_seq OWNER TO postgres;

--
-- Name: reconocimientos_productos_agr_id_reconocimiento_prodcutos_a_seq; Type: SEQUENCE OWNED BY; Schema: modulo6; Owner: postgres
--

ALTER SEQUENCE modulo6.reconocimientos_productos_agr_id_reconocimiento_prodcutos_a_seq OWNED BY modulo6.reconocimientos_productos_agricolas.id_reconocimiento_prodcutos_agricola;


--
-- Name: registros_costos; Type: TABLE; Schema: modulo6; Owner: postgres
--

CREATE TABLE modulo6.registros_costos (
    id_registro_costo integer NOT NULL,
    naturaleza_costo modulo6.enum_registros_costos_naturaleza_costo NOT NULL,
    subtipo_costo modulo6.enum_registros_costos_subtipo_costo NOT NULL,
    id_activo_biologico integer NOT NULL,
    monto_costo numeric(18,4) NOT NULL,
    accounting_account character varying(20)[] NOT NULL,
    line_type character varying(60) NOT NULL,
    type_code "char"[],
    exportable_aaef boolean DEFAULT false NOT NULL,
    politica_capitalizacion modulo6.enum_registros_costos_politica_capitalizacion,
    estado modulo6.enum_registros_costos_estado_costo,
    justificacion text,
    id_periodo_contable integer NOT NULL,
    id_usuario integer NOT NULL,
    fecha_registro timestamp with time zone DEFAULT now() NOT NULL,
    politica_capitalizacion_aplicada character varying(20),
    CONSTRAINT chk_accounting_account_no_vacio CHECK (((accounting_account IS NOT NULL) AND ((array_length(accounting_account, 1) >= 1) AND (array_length(accounting_account, 1) <= 2)))),
    CONSTRAINT chk_costo_fecha_no_futura CHECK ((fecha_registro <= now())),
    CONSTRAINT chk_exportable_type_code CHECK ((((exportable_aaef = true) AND (type_code = '{2}'::"char"[])) OR ((exportable_aaef = false) AND (type_code IS NULL)))),
    CONSTRAINT chk_mantenimiento_politica_gasto CHECK ((((naturaleza_costo <> 'MANTENIMIENTO'::modulo6.enum_registros_costos_naturaleza_costo) OR (politica_capitalizacion = 'GASTO'::modulo6.enum_registros_costos_politica_capitalizacion)) AND ((naturaleza_costo <> 'VENTA'::modulo6.enum_registros_costos_naturaleza_costo) OR (politica_capitalizacion IS NULL))))
);


ALTER TABLE modulo6.registros_costos OWNER TO postgres;

--
-- Name: TABLE registros_costos; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TABLE modulo6.registros_costos IS 'Centraliza todos los desembolsos económicos del ciclo de vida del activo biológico con tres categorías de tratamiento contable diferenciado bajo NIC 41: MANTENIMIENTO (gasto del período en RF-93), INVERSION (capitalizable o gasto según política M09) y VENTA (deducible del valor razonable en RF-84). Los registros MANTENIMIENTO e INVERSION son exportables a M07 como documentos AAEF tipo 02. Referencia: RF-90.';


--
-- Name: COLUMN registros_costos.id_registro_costo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.registros_costos.id_registro_costo IS 'PK serial. Identificador único del registro de costo. Referenciado por auditorias_financieras (tipo COSTO_REGISTRADO) y consumido en modo read-only por el Mapper de Costos de RF-96 para generar documentos AAEF tipo 02 hacia M07.';


--
-- Name: COLUMN registros_costos.naturaleza_costo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.registros_costos.naturaleza_costo IS 'Clasificación principal del costo con impacto directo en el tratamiento contable NIC 41. MANTENIMIENTO: siempre gasto del período (nunca capitalizable ni deducible del valor razonable). INVERSION: capitalizable o gasto según política M09 para la especie. VENTA: deducible del valor razonable en RF-84; no genera documento AAEF.';


--
-- Name: COLUMN registros_costos.subtipo_costo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.registros_costos.subtipo_costo IS 'Subcategoría del costo que determina automáticamente la naturaleza_costo. ALIMENTO, MEDICAMENTO, MANO_OBRA, VETERINARIO → MANTENIMIENTO. TRANSPORTE, COMISION, IMPUESTO_TRANSACCION, SACRIFICIO → VENTA. INVERSION_DIRECTA → según política M09 (requiere confirmación del Contador). OTRO → queda en PENDIENTE_CLASIFICACION hasta que el Contador declare la naturaleza.';


--
-- Name: COLUMN registros_costos.id_activo_biologico; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.registros_costos.id_activo_biologico IS 'FK → modulo2.activos_biologicos. Activo o lote al que se asocia el costo. Cuando el costo aplica a un lote sin activo individual (id_activo_biologico = null), se usa un identificador de lote referenciado en la capa de negocio. El sistema aplica reglas de distribución de M09 si están configuradas.';


--
-- Name: COLUMN registros_costos.monto_costo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.registros_costos.monto_costo IS 'Valor monetario del costo en COP (DECIMAL 18,4). Debe ser mayor a cero (validar con CHECK monto_costo > 0). Acumulado en el consolidado del período por naturaleza_costo y subtipo_costo para RF-87 (cierre), RF-92 (revelaciones) y RF-93 (estado de resultados).';


--
-- Name: COLUMN registros_costos.accounting_account; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.registros_costos.accounting_account IS 'Array posicional de cuentas PUC (Plan Único de Cuentas colombiano). 1 elemento: [cuenta_única]. 2 elementos: [cuenta_débito, cuenta_crédito]. Obligatorio para TODAS las naturalezas (incluyendo VENTA para trazabilidad interna). Validado contra el catálogo de M09. Consumido por RF-96 para generar el documento AAEF.';


--
-- Name: COLUMN registros_costos.line_type; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.registros_costos.line_type IS 'Tipo de línea contable según catálogo activo de M09. Valores configurables: COMPRA_INSUMOS, ALIMENTACION, SANIDAD_ANIMAL, TRANSPORTE_ACTIVO, SERVICIO_VETERINARIO, INVERSION_DIRECTA. Obligatorio para todas las categorías. Un valor fuera del catálogo genera rechazo LINETYPE_INVALIDO. Consumido íntegramente por RF-96 sin modificación.';


--
-- Name: COLUMN registros_costos.type_code; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.registros_costos.type_code IS 'Código de tipo de documento AAEF. Siempre "02" para registros exportables (MANTENIMIENTO e INVERSION). NULL para naturaleza VENTA (no genera documento AAEF en M07). Consumido por el Mapper de RF-96 para clasificar el documento en el envelope AAEF.';


--
-- Name: COLUMN registros_costos.exportable_aaef; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.registros_costos.exportable_aaef IS 'Indica si este registro debe ser incluido en el envelope AAEF exportado a M07. true: MANTENIMIENTO e INVERSION. false: VENTA (solo se usa internamente en RF-84 como deducción del valor razonable). El Mapper de RF-96 filtra por exportable_aaef = true antes de procesar. DEFAULT false.';


--
-- Name: COLUMN registros_costos.politica_capitalizacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.registros_costos.politica_capitalizacion IS 'Solo aplica para naturaleza INVERSION. CAPITALIZAR: el monto incrementa el costo histórico del activo en cuenta 120505; el Contador debe confirmar con justificación en auditorias_financieras. GASTO: se dirige a RF-93 como gasto del período. Determinado por la política configurada en M09 para la especie. Nulo para MANTENIMIENTO y VENTA.';


--
-- Name: COLUMN registros_costos.estado; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.registros_costos.estado IS 'Estado de clasificación del registro. CLASIFICADO: naturaleza_costo definida, listo para procesamiento. PENDIENTE_CLASIFICACION: subtipo_costo = OTRO sin naturaleza declarada por el Contador. El período contable no puede cerrarse en RF-87 mientras existan registros en este estado (RF-90 restricción 5.8).';


--
-- Name: COLUMN registros_costos.justificacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.registros_costos.justificacion IS 'Descripción obligatoria cuando: (1) el Contador registra manualmente una INVERSION_DIRECTA, (2) subtipo_costo = OTRO, o (3) el Contador sobrescribe costos parametrizados. Registrada en auditorias_financieras para auditabilidad completa.';


--
-- Name: COLUMN registros_costos.id_periodo_contable; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.registros_costos.id_periodo_contable IS 'FK → modulo6.periodos_contables. Período contable ABIERTO al que pertenece el registro. El sistema rechaza registros sobre períodos EN_CIERRE o CERRADOS con error PERIODO_CONTABLE_CERRADO (HTTP 422).';


--
-- Name: COLUMN registros_costos.id_usuario; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.registros_costos.id_usuario IS 'FK → modulo1.usuarios. Actor que registró el costo. Para costos de MANTENIMIENTO: puede ser el sistema M05 automáticamente. Para INVERSION_DIRECTA: solo el Contador o el Administrador (M05 no puede entregar inversiones directas).';


--
-- Name: COLUMN registros_costos.fecha_registro; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.registros_costos.fecha_registro IS 'Timestamp de inserción del registro. DEFAULT now(). Inmutable una vez persistido. El período no puede contener registros con fecha_registro posterior a su fecha_fin.';


--
-- Name: CONSTRAINT chk_mantenimiento_politica_gasto ON registros_costos; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON CONSTRAINT chk_mantenimiento_politica_gasto ON modulo6.registros_costos IS 'Garantiza que: (1) naturaleza MANTENIMIENTO implica politica_capitalizacion = GASTO; (2) naturaleza VENTA implica politica_capitalizacion IS NULL. Complementa al trigger trg_normalizar_politica_mantenimiento como capa de seguridad declarativa. Referencia: RF-90 restricción 5.6, NIC 41.';


--
-- Name: registros_costos_id_registro_costo_seq; Type: SEQUENCE; Schema: modulo6; Owner: postgres
--

CREATE SEQUENCE modulo6.registros_costos_id_registro_costo_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo6.registros_costos_id_registro_costo_seq OWNER TO postgres;

--
-- Name: registros_costos_id_registro_costo_seq; Type: SEQUENCE OWNED BY; Schema: modulo6; Owner: postgres
--

ALTER SEQUENCE modulo6.registros_costos_id_registro_costo_seq OWNED BY modulo6.registros_costos.id_registro_costo;


--
-- Name: revisiones_reconocimiento; Type: TABLE; Schema: modulo6; Owner: postgres
--

CREATE TABLE modulo6.revisiones_reconocimiento (
    id_revision_reconocimiento integer NOT NULL,
    id_reconocimiento_revertido integer NOT NULL,
    motivo_revision text NOT NULL,
    monto_revision numeric(18,4) NOT NULL,
    cuenta_debito character varying(20) NOT NULL,
    cuenta_credito character varying(20) NOT NULL,
    id_usuario integer NOT NULL,
    fecha_revision timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_revision_cuentas_no_vacias CHECK (((char_length(TRIM(BOTH FROM cuenta_debito)) > 0) AND (char_length(TRIM(BOTH FROM cuenta_credito)) > 0))),
    CONSTRAINT chk_revision_monto_positivo CHECK ((monto_revision > (0)::numeric)),
    CONSTRAINT chk_revision_motivo_minimo CHECK ((char_length(TRIM(BOTH FROM motivo_revision)) >= 20))
);


ALTER TABLE modulo6.revisiones_reconocimiento OWNER TO postgres;

--
-- Name: TABLE revisiones_reconocimiento; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TABLE modulo6.revisiones_reconocimiento IS 'Registra los asientos de reversión de reconocimientos iniciales conforme al mecanismo de reversión auditada de RF-82. El registro original en reconocimientos_iniciales nunca se elimina; ambos coexisten para trazabilidad. Solo puede existir una reversión por reconocimiento (constraint UNIQUE sobre id_reconocimiento_revertido). Condición: el activo no debe tener mediciones (RF-83), variaciones (RF-86) ni cierres (RF-87) dependientes.';


--
-- Name: COLUMN revisiones_reconocimiento.id_revision_reconocimiento; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.revisiones_reconocimiento.id_revision_reconocimiento IS 'PK serial. Identificador único del asiento de reversión. Referenciado en auditorias_financieras con tipo_evento = RECONOCIMIENTO_REVERTIDO para garantizar trazabilidad completa de la operación.';


--
-- Name: COLUMN revisiones_reconocimiento.id_reconocimiento_revertido; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.revisiones_reconocimiento.id_reconocimiento_revertido IS 'FK → modulo6.reconocimientos_iniciales. Identificador del reconocimiento inicial que se revierte. Tiene constraint UNIQUE: no se puede emitir más de una reversión por reconocimiento. El reconocimiento original pasa a estado REVERTIDO pero persiste en el historial.';


--
-- Name: COLUMN revisiones_reconocimiento.motivo_revision; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.revisiones_reconocimiento.motivo_revision IS 'Justificación obligatoria de la reversión, ingresada manualmente por el Contador. Mínimo 20 caracteres (validar con CHECK char_length(motivo_revision) >= 20). Inmutable una vez confirmada la reversión. Visible en auditorías externas NIC 41.';


--
-- Name: COLUMN revisiones_reconocimiento.monto_revision; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.revisiones_reconocimiento.monto_revision IS 'Monto del asiento espejo de reversión en COP (DECIMAL 18,4). Debe ser exactamente igual al valor_razonable_neto_inicial del reconocimiento original. El sistema calcula este valor automáticamente; el Contador no lo ingresa manualmente.';


--
-- Name: COLUMN revisiones_reconocimiento.cuenta_debito; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.revisiones_reconocimiento.cuenta_debito IS 'Cuenta contable debitada en el asiento de reversión. Corresponde a la cuenta de contrapartida original del reconocimiento: Cuentas por Pagar, Ingreso por transformación, Ingreso por donación o Cuenta de traslado interno, según el origen_financiero_activo del activo.';


--
-- Name: COLUMN revisiones_reconocimiento.cuenta_credito; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.revisiones_reconocimiento.cuenta_credito IS 'Cuenta contable acreditada en el asiento de reversión. Corresponde a la cuenta del Activo Biológico (120505), invirtiendo el débito original para anular contablemente el reconocimiento sin eliminarlo del historial.';


--
-- Name: COLUMN revisiones_reconocimiento.id_usuario; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.revisiones_reconocimiento.id_usuario IS 'FK → modulo1.usuarios. Contador autenticado en M01 que solicitó y confirmó la reversión. Ningún otro rol tiene acceso a esta operación. Registrado junto con fecha_revision en auditorias_financieras.';


--
-- Name: COLUMN revisiones_reconocimiento.fecha_revision; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.revisiones_reconocimiento.fecha_revision IS 'Timestamp en que se ejecutó y confirmó la reversión. DEFAULT now(). Inmutable. Después de esta fecha el activo biológico regresa a estado PENDIENTE_RECONOCIMIENTO en M02 para recibir un nuevo reconocimiento corregido.';


--
-- Name: revisiones_reconocimiento_id_revision_reconocimiento_seq; Type: SEQUENCE; Schema: modulo6; Owner: postgres
--

CREATE SEQUENCE modulo6.revisiones_reconocimiento_id_revision_reconocimiento_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo6.revisiones_reconocimiento_id_revision_reconocimiento_seq OWNER TO postgres;

--
-- Name: revisiones_reconocimiento_id_revision_reconocimiento_seq; Type: SEQUENCE OWNED BY; Schema: modulo6; Owner: postgres
--

ALTER SEQUENCE modulo6.revisiones_reconocimiento_id_revision_reconocimiento_seq OWNED BY modulo6.revisiones_reconocimiento.id_revision_reconocimiento;


--
-- Name: v_ultimo_calculo_por_activo; Type: VIEW; Schema: modulo6; Owner: postgres
--

CREATE VIEW modulo6.v_ultimo_calculo_por_activo AS
 SELECT DISTINCT ON (cvr.id_activo_biologico) cvr.id_calculo_valor_razonable,
    cvr.id_activo_biologico,
    ab.identificador,
    e.nombre AS especie,
    cvr.valor_razonable_bruto,
    cvr.valor_neto,
    cvr.metodo_costo,
    cvr.estado,
    pm.fuente AS fuente_precio,
    pm.precio_unitario,
    cvr.fecha_calculo,
    cvr.id_periodo_contable,
    pc.estado AS estado_periodo
   FROM ((((modulo6.calculos_valor_razonable cvr
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = cvr.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo6.precios_mercado pm ON ((pm.id_precio_mercado = cvr.id_precio_mercado)))
     JOIN modulo6.periodos_contables pc ON ((pc.id_periodo_contable = cvr.id_periodo_contable)))
  WHERE ((pc.estado = 'ABIERTO'::modulo6.enum_periodo_contables_estado) AND (cvr.estado = 'REVISION_REQUERIDA'::modulo6.enum_calculos_valor_razonable_estado))
  ORDER BY cvr.id_activo_biologico, cvr.fecha_calculo DESC;


ALTER VIEW modulo6.v_ultimo_calculo_por_activo OWNER TO postgres;

--
-- Name: valoraciones_por_costos; Type: TABLE; Schema: modulo6; Owner: postgres
--

CREATE TABLE modulo6.valoraciones_por_costos (
    id_valoracion_por_costo integer NOT NULL,
    id_activo_biologico integer NOT NULL,
    escenario_activacion modulo6.enum_valoraciones_por_costos_escenario NOT NULL,
    costos_adquisicion numeric(18,4) NOT NULL,
    tasa_depreciacion numeric(5,4) NOT NULL,
    fecha_adquisicion date NOT NULL,
    depreciacion_acumulada numeric(18,4) NOT NULL,
    deterioro_acumulado numeric(18,4) NOT NULL,
    valor_contable_por_costo numeric(18,4) NOT NULL,
    razon_sin_mercado character varying(500) NOT NULL,
    id_usuario integer NOT NULL,
    fecha_marcacion timestamp with time zone DEFAULT now() NOT NULL,
    es_activa boolean DEFAULT true NOT NULL,
    id_rf89_rechazo uuid,
    id_precio_rechazado integer,
    justificacion text,
    CONSTRAINT chk_valcosto_acumulados_no_negativos CHECK (((depreciacion_acumulada >= (0)::numeric) AND (deterioro_acumulado >= (0)::numeric))),
    CONSTRAINT chk_valcosto_adquisicion_no_futura CHECK ((fecha_adquisicion <= CURRENT_DATE)),
    CONSTRAINT chk_valcosto_adquisicion_positivo CHECK ((costos_adquisicion > (0)::numeric)),
    CONSTRAINT chk_valcosto_formula_coherente CHECK ((abs((valor_contable_por_costo - GREATEST((0)::numeric, ((costos_adquisicion - depreciacion_acumulada) - deterioro_acumulado)))) <= 1.0)),
    CONSTRAINT chk_valcosto_razon_no_vacia CHECK ((char_length(TRIM(BOTH FROM razon_sin_mercado)) >= 30)),
    CONSTRAINT chk_valcosto_tasa_depreciacion_rango CHECK (((tasa_depreciacion > (0)::numeric) AND (tasa_depreciacion <= (1)::numeric))),
    CONSTRAINT chk_valcosto_valor_contable_no_negativo CHECK ((valor_contable_por_costo >= (0)::numeric))
);


ALTER TABLE modulo6.valoraciones_por_costos OWNER TO postgres;

--
-- Name: TABLE valoraciones_por_costos; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TABLE modulo6.valoraciones_por_costos IS 'Implementa el mecanismo de valoración alternativa del Párrafo 30 NIC 41 para activos sin precio de mercado activo. Aplica la fórmula: costo_adquisicion − depreciacion_acumulada − deterioro_acumulado. Cada activo puede tener solo una valoración activa (constraint UNIQUE sobre id_activo_biologico, es_activa = true). Referencia: RF-88.';


--
-- Name: COLUMN valoraciones_por_costos.id_valoracion_por_costo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.valoraciones_por_costos.id_valoracion_por_costo IS 'PK serial. Identificador único de la valoración alternativa. Referenciado por deterorios_activos para vincular cada impacto económico de deterioro a su valoración correspondiente.';


--
-- Name: COLUMN valoraciones_por_costos.id_activo_biologico; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.valoraciones_por_costos.id_activo_biologico IS 'FK → modulo2.activos_biologicos. Activo marcado como SIN_MERCADO_ACTIVO por el Contador. El activo debe estar en estado ACTIVO o EN_TRATAMIENTO en M02; no aplica a activos dados de baja. El constraint UNIQUE garantiza una sola valoración activa por activo.';


--
-- Name: COLUMN valoraciones_por_costos.escenario_activacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.valoraciones_por_costos.escenario_activacion IS 'Contexto de activación de RF-88. INICIAL_RF82: invocado como calculador delegado durante el reconocimiento inicial (RF-82) cuando no hay precio en RF-89; RF-88 devuelve el valor a RF-82 y no persiste independientemente. AUTONOMO_CONTADOR: activado directamente por el Contador para un activo ya reconocido que perdió precio de mercado.';


--
-- Name: COLUMN valoraciones_por_costos.costos_adquisicion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.valoraciones_por_costos.costos_adquisicion IS 'Valor base del cálculo en COP (DECIMAL 18,4). Leído del reconocimiento inicial de RF-82, que a su vez lo tomó del registro RF-33. RF-88 no consulta RF-33 directamente para garantizar que el valor esté respaldado con soporte documental validado. Nulo en origen NACIMIENTO (bloquea la marcación).';


--
-- Name: COLUMN valoraciones_por_costos.tasa_depreciacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.valoraciones_por_costos.tasa_depreciacion IS 'Tasa de depreciación anual calculada como 1 / vida_util_estimada (configurada en M09 para la especie). DECIMAL(5,4). El Contador no ingresa este valor directamente; configura la vida útil en M09 y el sistema deriva la tasa. Los cambios en M09 aplican prospectivamente.';


--
-- Name: COLUMN valoraciones_por_costos.fecha_adquisicion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.valoraciones_por_costos.fecha_adquisicion IS 'Fecha de ingreso del activo al sistema (tomada de RF-33). Usada para calcular periodos_transcurridos en la fórmula de depreciación por línea recta: depreciacion = costos_adquisicion × tasa_depreciacion × periodos_transcurridos.';


--
-- Name: COLUMN valoraciones_por_costos.depreciacion_acumulada; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.valoraciones_por_costos.depreciacion_acumulada IS 'Sumatoria de la depreciación registrada hasta el período vigente, calculada automáticamente por el sistema en cada cierre de período (RF-87 paso 4.1). En INICIAL_RF82 es 0 (primer período). El Contador no puede modificar este valor directamente.';


--
-- Name: COLUMN valoraciones_por_costos.deterioro_acumulado; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.valoraciones_por_costos.deterioro_acumulado IS 'Sumatoria de los impactos económicos en COP registrados por el Contador en deterorios_activos, cada uno vinculado a un evento sanitario de modulo2.eventos_sanitarios. Si no hay impactos registrados = 0. El sistema no infiere deterioro a partir de datos clínicos sin cuantificación explícita.';


--
-- Name: COLUMN valoraciones_por_costos.valor_contable_por_costo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.valoraciones_por_costos.valor_contable_por_costo IS 'Valor contable resultante: costos_adquisicion − depreciacion_acumulada − deterioro_acumulado, en COP DECIMAL(18,4). No puede ser negativo (el sistema lo fija en 0 si la suma de deducciones supera el costo). Este es el valor registrado en el balance mientras el activo esté SIN_MERCADO_ACTIVO.';


--
-- Name: COLUMN valoraciones_por_costos.razon_sin_mercado; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.valoraciones_por_costos.razon_sin_mercado IS 'Descripción textual obligatoria (mín. 1 char, máx. 500) que justifica la ausencia de precio de mercado confiable. Usada en la sección Párr. 54 del informe de revelaciones NIC 41 (RF-92). Campo inmutable una vez confirmada la marcación.';


--
-- Name: COLUMN valoraciones_por_costos.id_usuario; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.valoraciones_por_costos.id_usuario IS 'FK → modulo1.usuarios. Contador que ejecutó la marcación SIN_MERCADO_ACTIVO o el cambio de método. Acción exclusiva del rol Contador; cualquier otro intento genera error HTTP 403 registrado en auditorias_financieras.';


--
-- Name: COLUMN valoraciones_por_costos.fecha_marcacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.valoraciones_por_costos.fecha_marcacion IS 'Timestamp de cuando el Contador activó la valoración por costo. DEFAULT now(). Inmutable. Registrado en auditorias_financieras con tipo_evento = ACTIVO_MARCADO_SIN_MERCADO.';


--
-- Name: COLUMN valoraciones_por_costos.es_activa; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.valoraciones_por_costos.es_activa IS 'Indica si esta valoración está vigente. true: el activo está bajo método de costo; RF-83 no ejecuta mediciones de valor razonable sobre él. false: el Contador cambió el método a VALOR_RAZONABLE al restaurarse un precio en RF-89; la diferencia se registra como variación en variaciones_valor_razonable. DEFAULT true.';


--
-- Name: COLUMN valoraciones_por_costos.justificacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.valoraciones_por_costos.justificacion IS 'Justificación contable complementaria que el Contador puede añadir al activar la valoración por costo alternativa (Párr. 30 NIC 41). Detalla los supuestos de valoración, comparable con razon_sin_mercado pero orientado al tratamiento contable (método de depreciación aplicado, vida útil estimada, fuentes de referencia del costo de adquisición). Nullable: su obligatoriedad se evalúa en capa de negocio según escenario_activacion (obligatorio en AUTONOMO_CONTADOR por buenas prácticas NIC 41). Inmutable una vez confirmada la marcación. Visible en revelaciones RF-92 Párr. 54 e informes de auditoría externa.';


--
-- Name: v_activos_valorados_resumen_nic41; Type: VIEW; Schema: modulo6; Owner: postgres
--

CREATE VIEW modulo6.v_activos_valorados_resumen_nic41 AS
 SELECT ab.id_activo_biologico,
    ab.identificador,
    e.nombre AS especie,
    ab.tipo AS tipo_activo,
    inf.nombre AS infraestructura,
    f.nombre AS finca,
    ri.clasificacion,
        CASE
            WHEN (vpc.id_valoracion_por_costo IS NOT NULL) THEN 'COSTO'::text
            ELSE 'VALOR_RAZONABLE'::text
        END AS metodo_valoracion_vigente,
    COALESCE(uc.valor_neto, vpc.valor_contable_por_costo) AS valor_vigente,
    uc.valor_neto AS ultimo_vr_neto,
    uc.fuente_precio,
    vpc.valor_contable_por_costo,
    vpc.escenario_activacion,
    vpc.razon_sin_mercado,
    ri.estado AS estado_reconocimiento,
    ri.fecha_reconocimiento,
    ri.valor_razonable_neto_inicial
   FROM ((((((modulo2.activos_biologicos ab
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo9.infraestructuras inf ON ((inf.id_infraestructura = ab.id_infraestructura)))
     JOIN modulo9.fincas f ON ((f.id_finca = inf.id_finca)))
     LEFT JOIN modulo6.reconocimientos_iniciales ri ON ((ri.id_activo_biologico = ab.id_activo_biologico)))
     LEFT JOIN modulo6.v_ultimo_calculo_por_activo uc ON ((uc.id_activo_biologico = ab.id_activo_biologico)))
     LEFT JOIN modulo6.valoraciones_por_costos vpc ON (((vpc.id_activo_biologico = ab.id_activo_biologico) AND (vpc.es_activa = true))));


ALTER VIEW modulo6.v_activos_valorados_resumen_nic41 OWNER TO postgres;

--
-- Name: variaciones_valor_razonable; Type: TABLE; Schema: modulo6; Owner: postgres
--

CREATE TABLE modulo6.variaciones_valor_razonable (
    id_variacion_valor_razonable integer NOT NULL,
    id_activo_biologico integer NOT NULL,
    tipo modulo6.enum_variaciones_valor_razonable_tipo NOT NULL,
    monto_variacion numeric(18,2) NOT NULL,
    variacion_transformacion numeric(18,2) NOT NULL,
    variacion_precio_mercado numeric(18,2) NOT NULL,
    valor_razonable_anterior numeric(18,2) NOT NULL,
    valor_razonable_nuevo numeric(18,2) NOT NULL,
    id_evento integer NOT NULL,
    id_medicion_posterior integer,
    id_periodo_contable integer NOT NULL,
    estado_trazabilidad modulo6.enum_variaciones_valor_razonable_estado_trazabilidad DEFAULT 'VERIFICACION_PENDIENTE'::modulo6.enum_variaciones_valor_razonable_estado_trazabilidad NOT NULL,
    tiene_estimacion boolean DEFAULT false NOT NULL,
    id_usuario integer NOT NULL,
    fecha_registro timestamp with time zone DEFAULT now() NOT NULL,
    id_variacion_corregida integer,
    tipo_variacion character varying(30),
    CONSTRAINT chk_monto_coherente CHECK ((abs((monto_variacion - (variacion_transformacion + variacion_precio_mercado))) < 0.01)),
    CONSTRAINT chk_variacion_fecha_no_futura CHECK ((fecha_registro <= now())),
    CONSTRAINT chk_variacion_vr_positivos CHECK (((valor_razonable_anterior > (0)::numeric) AND (valor_razonable_nuevo > (0)::numeric)))
);


ALTER TABLE modulo6.variaciones_valor_razonable OWNER TO postgres;

--
-- Name: TABLE variaciones_valor_razonable; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TABLE modulo6.variaciones_valor_razonable IS 'Registra en modo append-only cada ganancia o pérdida generada por variación del valor razonable de activos biológicos conforme al Párr. 26 NIC 41. Distingue cuatro tipos: GANANCIA/PERDIDA_TRANSFORMACION_BIOLOGICA y GANANCIA/PERDIDA_PRECIO_MERCADO. Los registros son inmutables; las correcciones se realizan como nuevas entradas con id_variacion_corregida. [Nota: el nombre de la tabla tiene un espacio al final; corregir en próxima migración.] Referencia: RF-86.';


--
-- Name: COLUMN variaciones_valor_razonable.id_variacion_valor_razonable; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.variaciones_valor_razonable.id_variacion_valor_razonable IS 'PK serial. Identificador único del registro de variación. Referenciado por trazabilidades_contables (RF-91) para verificar la cadena IoT → evento → valoración → asiento, y por cotizaciones para asociar el valor razonable de referencia.';


--
-- Name: COLUMN variaciones_valor_razonable.id_activo_biologico; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.variaciones_valor_razonable.id_activo_biologico IS 'FK → modulo2.activos_biologicos. Activo biológico cuyo valor razonable varió. Debe existir en estado ACTIVO o EN_TRATAMIENTO en M02. No se registran variaciones de activos en estado BAJA (excepto mediante el evento RF-45 de baja).';


--
-- Name: COLUMN variaciones_valor_razonable.tipo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.variaciones_valor_razonable.tipo IS 'Clasificación de la variación según NIC 41 Párr. 26. GANANCIA_TRANSFORMACION_BIOLOGICA: aumento por crecimiento/procreación/mejora. PERDIDA_TRANSFORMACION_BIOLOGICA: disminución por degeneración/enfermedad/baja. GANANCIA_PRECIO_MERCADO: aumento del precio sin cambio físico. PERDIDA_PRECIO_MERCADO: disminución del precio sin cambio físico.';


--
-- Name: COLUMN variaciones_valor_razonable.monto_variacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.variaciones_valor_razonable.monto_variacion IS 'Monto monetario total de la variación en COP DECIMAL(18,2). Positivo para ganancias, negativo para pérdidas. Debe ser distinto de cero; si es cero por valores válidos, no se genera registro. Calculado y entregado por RF-83; RF-86 no lo recalcula.';


--
-- Name: COLUMN variaciones_valor_razonable.variacion_transformacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.variaciones_valor_razonable.variacion_transformacion IS 'Componente de la variación atribuible al cambio físico del activo biológico. Calculado y entregado por RF-83. Positivo = ganancia por transformación; negativo = pérdida. RF-86 persiste este valor exactamente como lo recibe sin modificación.';


--
-- Name: COLUMN variaciones_valor_razonable.variacion_precio_mercado; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.variaciones_valor_razonable.variacion_precio_mercado IS 'Componente de la variación atribuible al cambio en el precio de referencia de mercado. Calculado y entregado por RF-83. Positivo = ganancia por precio; negativo = pérdida. La suma variacion_transformacion + variacion_precio_mercado debe ser igual a monto_variacion.';


--
-- Name: COLUMN variaciones_valor_razonable.valor_razonable_anterior; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.variaciones_valor_razonable.valor_razonable_anterior IS 'Valor razonable neto (menos costos de venta) del activo inmediatamente antes del evento de valoración, en COP DECIMAL(18,2). Proviene del último registro de calculos_valor_razonable. Obligatorio para trazabilidad y para el cálculo de revelaciones Párr. 50 (rollforward) en RF-92.';


--
-- Name: COLUMN variaciones_valor_razonable.valor_razonable_nuevo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.variaciones_valor_razonable.valor_razonable_nuevo IS 'Valor razonable neto del activo después de aplicar la variación, en COP DECIMAL(18,2). Calculado por RF-83 y RF-84. Debe ser un número positivo mayor a cero; si es nulo o negativo, RF-86 suspende el proceso (FA-3: RF_84_DATOS_INVALIDOS).';


--
-- Name: COLUMN variaciones_valor_razonable.id_evento; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.variaciones_valor_razonable.id_evento IS 'FK → modulo2.eventos_activos. Evento biológico o económico que originó la variación. Para transformación biológica: UUID de RF-40/RF-42/RF-43/RF-44/RF-45. Para variación de precio: puede referenciar el id del precio en precios_mercado. Campo obligatorio; sin id_evento válido el registro es rechazado (CA-6 RF-86).';


--
-- Name: COLUMN variaciones_valor_razonable.id_medicion_posterior; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.variaciones_valor_razonable.id_medicion_posterior IS 'FK → modulo6.mediciones_posteriores. Medición que calculó y descompuso los valores que este registro persiste. Nulo en casos excepcionales de registro directo. RF-86 verifica que la medicion_posterior referenciada tenga estado COMPLETADO antes de persistir.';


--
-- Name: COLUMN variaciones_valor_razonable.id_periodo_contable; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.variaciones_valor_razonable.id_periodo_contable IS 'FK → modulo6.periodos_contables. Período contable ABIERTO al que pertenece esta variación. El sistema rechaza variaciones sobre períodos EN_CIERRE o CERRADOS (FA-2 RF-86). Usado por RF-93 para consolidar el estado de resultados del período.';


--
-- Name: COLUMN variaciones_valor_razonable.estado_trazabilidad; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.variaciones_valor_razonable.estado_trazabilidad IS 'Estado de la cadena de custodia verificada por RF-91. VERIFICACION_PENDIENTE: generado por RF-86, pendiente de verificación por RF-91. VERIFICADO: cadena completa (IoT → evento → valoración → asiento); elegible para cierre y exportación a M07. PENDIENTE_TRAZABILIDAD: cadena incompleta; bloqueado para cierre. Default: VERIFICACION_PENDIENTE.';


--
-- Name: COLUMN variaciones_valor_razonable.tiene_estimacion; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.variaciones_valor_razonable.tiene_estimacion IS 'true cuando el valor razonable utilizado proviene de un precio estimado aprobado por el Contador (fuente = ESTIMADA en precios_mercado). El registro se persiste normalmente pero queda trazable en informes RF-92 y estados de resultados RF-93. DEFAULT false.';


--
-- Name: COLUMN variaciones_valor_razonable.id_usuario; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.variaciones_valor_razonable.id_usuario IS 'FK → modulo1.usuarios. Actor que origina el registro. Usuario (Contador) cuando es manual; id del proceso del sistema (RF-83, RF-84 o RF-87) cuando es automático. Campo obligatorio en ambos casos para auditabilidad.';


--
-- Name: COLUMN variaciones_valor_razonable.fecha_registro; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.variaciones_valor_razonable.fecha_registro IS 'Timestamp de creación del registro. DEFAULT now(). Inmutable desde su creación. Registrado en auditorias_financieras (tipo VARIACION_VALOR_RAZONABLE) como parte de la transacción atómica de RF-86.';


--
-- Name: COLUMN variaciones_valor_razonable.id_variacion_corregida; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON COLUMN modulo6.variaciones_valor_razonable.id_variacion_corregida IS 'FK self → variaciones_valor_razonable. Referencia al id de la variación que este registro corrige. Solo se usa en registros correctivos: el registro original y el correctivo coexisten en el historial; ninguno se elimina. Nulo en registros originales. Requiere aprobación explícita del Contador.';


--
-- Name: v_asientos_contables_periodo; Type: VIEW; Schema: modulo6; Owner: postgres
--

CREATE VIEW modulo6.v_asientos_contables_periodo AS
 SELECT ctc.id_asiento,
    ctc.estado_verificacion,
    ctc.fecha_verificacion,
    ctc.nivel_fallo,
    mp."id_ medicion_posterior" AS id_medicion_posterior,
    mp.id_activo_biologico,
    ab.identificador,
    e.nombre AS especie,
    mp.valor_razonable_anterior,
    mp.valor_razonable_actual,
    mp.variacion_total,
    mp.ganancia_perdida_transformacion,
    mp.ganancia_perdida_precio_mercado,
    mp.origen_medicion,
    mp.id_asiento_contable,
    mp.id_periodo_contable,
    pc.fecha_inicio AS periodo_inicio,
    pc.fecha_fin AS periodo_fin,
    pc.estado AS estado_periodo,
    mp.fecha_medicion
   FROM (((((modulo6.cadenas_trazabilidad_contable ctc
     JOIN modulo6.variaciones_valor_razonable vvr ON ((vvr.id_variacion_valor_razonable = ctc.id_variacion_valor_razonable)))
     JOIN modulo6.mediciones_posteriores mp ON ((mp."id_ medicion_posterior" = vvr.id_medicion_posterior)))
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = mp.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo6.periodos_contables pc ON ((pc.id_periodo_contable = mp.id_periodo_contable)))
  WHERE (mp."id_ medicion_posterior" IS NOT NULL);


ALTER VIEW modulo6.v_asientos_contables_periodo OWNER TO postgres;

--
-- Name: v_auditoria_financiera_log; Type: VIEW; Schema: modulo6; Owner: postgres
--

CREATE VIEW modulo6.v_auditoria_financiera_log AS
 SELECT af.id_auditoria_financiera,
    af.tipo,
    af.severidad,
    af.id_usuario,
    af.modulo_origen,
    af.id_activo_biologico,
    ab.identificador,
    e.nombre AS especie,
    af.id_periodo_contable,
    pc.fecha_inicio AS periodo_inicio,
    pc.fecha_fin AS periodo_fin,
    af.monto_afectado,
    af.metodo_valoracion_anterior,
    af.metodo_valoracion_nuevo,
    af.datos_anteriores,
    af.datos_nuevos,
    af.ip_origen,
    af.hash_integridad,
    af.origen_registro,
    af.fecha_registro,
    (((u.nombre)::text || ' '::text) || (u.apellidos)::text) AS ejecutado_por
   FROM ((((modulo6.auditorias_financieras af
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = af.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     LEFT JOIN modulo6.periodos_contables pc ON ((pc.id_periodo_contable = af.id_periodo_contable)))
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = af.id_usuario)))
  ORDER BY af.fecha_registro DESC;


ALTER VIEW modulo6.v_auditoria_financiera_log OWNER TO postgres;

--
-- Name: v_cadenas_trazabilidad_detalle; Type: VIEW; Schema: modulo6; Owner: postgres
--

CREATE VIEW modulo6.v_cadenas_trazabilidad_detalle AS
 SELECT ctc.id_asiento,
    ctc.id_variacion_valor_razonable,
    ctc.id_evento,
    ctc.id_telemetria,
    ctc.id_precio_mercado,
    ctc.estado_verificacion,
    ctc.nivel_fallo,
    ctc.fecha_verificacion,
    ctc.justificacion_verificacion,
    vvr.id_activo_biologico,
    ab.identificador AS activo,
    e.nombre AS especie,
    vvr.tipo AS tipo_variacion,
    vvr.monto_variacion,
    vvr.variacion_transformacion,
    vvr.variacion_precio_mercado,
    vvr.estado_trazabilidad,
    cvr.valor_neto AS vr_neto,
    cvr.metodo_costo,
    pm.precio_unitario,
    pm.fuente AS fuente_precio,
    tel.valor_ajustado AS valor_telemetria,
    tel.timestamp_captura,
    (((u.nombre)::text || ' '::text) || (u.apellidos)::text) AS verificado_por_nombre,
    ctc.verificado_por
   FROM (((((((modulo6.cadenas_trazabilidad_contable ctc
     LEFT JOIN modulo6.variaciones_valor_razonable vvr ON ((vvr.id_variacion_valor_razonable = ctc.id_variacion_valor_razonable)))
     LEFT JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = vvr.id_activo_biologico)))
     LEFT JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     LEFT JOIN modulo6.calculos_valor_razonable cvr ON ((cvr.id_calculo_valor_razonable = ctc.id_variacion_valor_razonable)))
     LEFT JOIN modulo6.precios_mercado pm ON ((pm.id_precio_mercado = ctc.id_precio_mercado)))
     LEFT JOIN modulo3.telemetrias tel ON ((tel.id_telemetria = ctc.id_telemetria)))
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = ctc.verificado_por)));


ALTER VIEW modulo6.v_cadenas_trazabilidad_detalle OWNER TO postgres;

--
-- Name: v_calculos_valor_razonable_detalle; Type: VIEW; Schema: modulo6; Owner: postgres
--

CREATE VIEW modulo6.v_calculos_valor_razonable_detalle AS
 SELECT cvr.id_calculo_valor_razonable,
    cvr.id_activo_biologico,
    ab.identificador,
    e.nombre AS especie,
    inf.nombre AS infraestructura,
    f.nombre AS finca,
    cvr.id_precio_mercado,
    pm.precio_unitario,
    pm.fuente AS fuente_precio,
    pm.estado AS estado_precio,
    cvr.valor_razonable_bruto,
    cvr.costo_transporte,
    cvr.costo_comisiones,
    cvr.costo_impuestos_transaccion,
    cvr.otros_costos_disposicion,
    (((cvr.costo_transporte + cvr.costo_comisiones) + cvr.costo_impuestos_transaccion) + cvr.otros_costos_disposicion) AS total_costos_deducidos,
    cvr.valor_neto,
    cvr.metodo_costo,
    cvr.justificacion,
    cvr.estado,
    cvr.id_periodo_contable,
    pc.fecha_inicio AS periodo_inicio,
    pc.fecha_fin AS periodo_fin,
    pc.estado AS estado_periodo,
    cvr.fecha_calculo,
    (((u.nombre)::text || ' '::text) || (u.apellidos)::text) AS calculado_por,
    cvr.id_usuario,
    pcv.id_parametro_costo_venta,
    pcv.region AS region_parametro,
    pcv.pct_transporte,
    pcv.pct_comisiones,
    pcv.pct_impuestos
   FROM ((((((((modulo6.calculos_valor_razonable cvr
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = cvr.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo9.infraestructuras inf ON ((inf.id_infraestructura = ab.id_infraestructura)))
     JOIN modulo9.fincas f ON ((f.id_finca = inf.id_finca)))
     JOIN modulo6.precios_mercado pm ON ((pm.id_precio_mercado = cvr.id_precio_mercado)))
     JOIN modulo6.periodos_contables pc ON ((pc.id_periodo_contable = cvr.id_periodo_contable)))
     JOIN modulo1.usuarios u ON ((u.id_usuario = cvr.id_usuario)))
     LEFT JOIN modulo6.parametros_costos_venta pcv ON ((pcv.id_parametro_costo_venta = cvr.id_parametro_costo_venta)));


ALTER VIEW modulo6.v_calculos_valor_razonable_detalle OWNER TO postgres;

--
-- Name: v_costos_acumulados_por_activo; Type: VIEW; Schema: modulo6; Owner: postgres
--

CREATE VIEW modulo6.v_costos_acumulados_por_activo AS
 SELECT rc.id_activo_biologico,
    ab.identificador,
    e.nombre AS especie,
    rc.id_periodo_contable,
    pc.fecha_inicio AS periodo_inicio,
    pc.fecha_fin AS periodo_fin,
    rc.naturaleza_costo,
    rc.subtipo_costo,
    count(*) AS num_registros,
    sum(rc.monto_costo) AS total_costo,
    min(rc.fecha_registro) AS primera_fecha,
    max(rc.fecha_registro) AS ultima_fecha
   FROM (((modulo6.registros_costos rc
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = rc.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo6.periodos_contables pc ON ((pc.id_periodo_contable = rc.id_periodo_contable)))
  GROUP BY rc.id_activo_biologico, ab.identificador, e.nombre, rc.id_periodo_contable, pc.fecha_inicio, pc.fecha_fin, rc.naturaleza_costo, rc.subtipo_costo;


ALTER VIEW modulo6.v_costos_acumulados_por_activo OWNER TO postgres;

--
-- Name: v_cotizaciones_periodo; Type: VIEW; Schema: modulo6; Owner: postgres
--

CREATE VIEW modulo6.v_cotizaciones_periodo AS
 SELECT cot.id_cotizacion,
    cot.fecha_emision,
    cot.id_periodo_contable,
    pc.fecha_inicio AS periodo_inicio,
    pc.fecha_fin AS periodo_fin,
    pc.estado AS estado_periodo,
    cot.activos_cotizados,
    cot.valor_cotizacion_propuesto,
    cot.condiciones,
    cot.estado,
    cot.estado_envelope,
    cot.fecha_vencimiento,
    cot.accounting_account,
    cot.line_type,
    cot.type_code,
    cot.cuentas_orden_puc,
    cot.motivo_anulacion,
    cot.motivo_anulacion_envelope,
    cot.id_fuente_rf86,
    cot.fecha_registro,
    (((u.nombre)::text || ' '::text) || (u.apellidos)::text) AS registrado_por,
    cot.id_usuario
   FROM ((modulo6.cotizaciones cot
     JOIN modulo6.periodos_contables pc ON ((pc.id_periodo_contable = cot.id_periodo_contable)))
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = cot.id_usuario)));


ALTER VIEW modulo6.v_cotizaciones_periodo OWNER TO postgres;

--
-- Name: v_deterioros_por_activo; Type: VIEW; Schema: modulo6; Owner: postgres
--

CREATE VIEW modulo6.v_deterioros_por_activo AS
 SELECT da.id_deterorio_activo,
    da.id_valoracio_costo AS id_valoracion_costo,
    vpc.id_activo_biologico,
    ab.identificador,
    e.nombre AS especie,
    da.id_evento_sanitario,
    es_ev.diagnostico,
    es_ev.medicamento,
    da.impacto_economico_cop,
    da.justificacion,
    da.fecha_registro,
    (((u.nombre)::text || ' '::text) || (u.apellidos)::text) AS registrado_por,
    sum(da.impacto_economico_cop) OVER (PARTITION BY vpc.id_activo_biologico) AS deterioro_total_activo
   FROM (((((modulo6.deterorios_activos da
     JOIN modulo6.valoraciones_por_costos vpc ON ((vpc.id_valoracion_por_costo = da.id_valoracio_costo)))
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = vpc.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo2.eventos_sanitarios es_ev ON ((es_ev.id_evento = da.id_evento_sanitario)))
     JOIN modulo1.usuarios u ON ((u.id_usuario = da.id_usuario)));


ALTER VIEW modulo6.v_deterioros_por_activo OWNER TO postgres;

--
-- Name: v_estado_cierre_periodo; Type: VIEW; Schema: modulo6; Owner: postgres
--

CREATE VIEW modulo6.v_estado_cierre_periodo AS
 SELECT ecp.id_cierre,
    ecp.hash_saga,
    ecp.id_periodo_contable,
    pc.fecha_inicio AS periodo_inicio,
    pc.fecha_fin AS periodo_fin,
    pc.estado AS estado_periodo,
    pc.tipo_cierre,
    ecp.estado,
    ecp.paso_actual,
    ecp.activos_procesados,
    ecp.activos_pendientes,
    ecp.activos_excluidos,
    ecp.tiempo_ejecucion_ms,
    ecp.error_detalle,
    ecp.fecha_inicio AS fecha_inicio_cierre,
    ecp.fecha_fin AS fecha_fin_cierre,
    ecp.intento_reintento,
    (((u.nombre)::text || ' '::text) || (u.apellidos)::text) AS ejecutado_por,
    ecp.id_usuario_ejecutor,
        CASE
            WHEN (ecp.fecha_fin IS NOT NULL) THEN (EXTRACT(epoch FROM (ecp.fecha_fin - ecp.fecha_inicio)))::integer
            ELSE NULL::integer
        END AS duracion_seg
   FROM ((modulo6.ejecuciones_cierre_periodo ecp
     JOIN modulo6.periodos_contables pc ON ((pc.id_periodo_contable = ecp.id_periodo_contable)))
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = ecp.id_usuario_ejecutor)));


ALTER VIEW modulo6.v_estado_cierre_periodo OWNER TO postgres;

--
-- Name: v_estado_resultados_periodo; Type: VIEW; Schema: modulo6; Owner: postgres
--

CREATE VIEW modulo6.v_estado_resultados_periodo AS
 SELECT erp.id_estado,
    erp.id_periodo_contable,
    pc.fecha_inicio AS periodo_inicio,
    pc.fecha_fin AS periodo_fin,
    pc.tipo_cierre,
    pc.estado AS estado_periodo,
    erp.total_ingresos_transformacion,
    erp.total_ingresos_precio_mercado,
    erp.total_ingresos_cosecha,
    ((erp.total_ingresos_transformacion + erp.total_ingresos_precio_mercado) + erp.total_ingresos_cosecha) AS total_ingresos,
    erp.total_gastos_mantenimiento,
    erp.total_bajas_deterioro,
    (erp.total_gastos_mantenimiento + erp.total_bajas_deterioro) AS total_gastos,
    erp.resultado_neto,
    erp.estado,
    erp.hash_consistencia,
    erp.fecha_generacion
   FROM (modulo6.estados_resultados_periodo erp
     JOIN modulo6.periodos_contables pc ON ((pc.id_periodo_contable = erp.id_periodo_contable)));


ALTER VIEW modulo6.v_estado_resultados_periodo OWNER TO postgres;

--
-- Name: v_historial_mediciones_por_activo; Type: VIEW; Schema: modulo6; Owner: postgres
--

CREATE VIEW modulo6.v_historial_mediciones_por_activo AS
 SELECT mp."id_ medicion_posterior" AS id_medicion_posterior,
    mp.id_activo_biologico,
    mp.valor_razonable_anterior,
    mp.valor_razonable_actual,
    mp.ganancia_perdida_transformacion,
    mp.ganancia_perdida_precio_mercado,
    mp.variacion_total,
    mp.tiene_valor_estimado,
    mp.origen_medicion,
    mp.estado,
    mp.id_periodo_contable,
    pc.fecha_inicio AS periodo_inicio,
    pc.fecha_fin AS periodo_fin,
    mp.fecha_medicion,
    cvr.valor_neto,
    cvr.metodo_costo,
    pm.fuente AS fuente_precio,
    pm.precio_unitario,
    pm.region,
        CASE
            WHEN (mp.valor_razonable_anterior <> (0)::numeric) THEN round(((mp.variacion_total / mp.valor_razonable_anterior) * (100)::numeric), 2)
            ELSE NULL::numeric
        END AS variacion_pct
   FROM (((modulo6.mediciones_posteriores mp
     JOIN modulo6.periodos_contables pc ON ((pc.id_periodo_contable = mp.id_periodo_contable)))
     JOIN modulo6.calculos_valor_razonable cvr ON ((cvr.id_calculo_valor_razonable = mp.id_calculo_actual)))
     JOIN modulo6.precios_mercado pm ON ((pm.id_precio_mercado = cvr.id_precio_mercado)))
  ORDER BY mp.id_activo_biologico, mp.fecha_medicion DESC;


ALTER VIEW modulo6.v_historial_mediciones_por_activo OWNER TO postgres;

--
-- Name: v_ingresos_cosecha_detalle; Type: VIEW; Schema: modulo6; Owner: postgres
--

CREATE VIEW modulo6.v_ingresos_cosecha_detalle AS
 SELECT rpa.id_reconocimiento_prodcutos_agricola AS id_reconocimiento_producto_agricola,
    rpa.id_activo_biologico,
    ab.identificador,
    e.nombre AS especie,
    rpa.producto_agricola,
    rpa.tipo AS tipo_producto,
    rpa.cantidad_cosechada,
    rpa.unidad_medida,
    rpa.precio_mercado_producto,
    rpa.costo_venta_producto,
    rpa.valor_producto,
    rpa.proporcion_cosechada,
    rpa.valor_reduccion_activo,
    rpa.fecha_cosecha,
    rpa.id_periodo_contable,
    pc.fecha_inicio AS periodo_inicio,
    pc.fecha_fin AS periodo_fin
   FROM (((modulo6.reconocimientos_productos_agricolas rpa
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = rpa.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo6.periodos_contables pc ON ((pc.id_periodo_contable = rpa.id_periodo_contable)));


