     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo2.eventos_activos ea ON ((ea.id_eventos = vvr.id_evento)))
     JOIN modulo6.periodos_contables pc ON ((pc.id_periodo_contable = vvr.id_periodo_contable)))
  WHERE (vvr.variacion_transformacion <> (0)::numeric);


