--

CREATE VIEW modulo6.v_mediciones_posteriores_periodo AS
 SELECT mp."id_ medicion_posterior" AS id_medicion_posterior,
    mp.id_activo_biologico,
    ab.identificador,
    e.nombre AS especie,
    ab.tipo AS tipo_activo,
    inf.nombre AS infraestructura,
    f.nombre AS finca,
    mp.origen_medicion,
    mp.tipo_origen,
    mp.valor_razonable_anterior,
    mp.valor_razonable_actual,
    mp.ganancia_perdida_transformacion,
    mp.ganancia_perdida_precio_mercado,
    mp.variacion_total,
    mp.tiene_valor_estimado,
    mp.estado,
    mp.id_periodo_contable,
    pc.fecha_inicio AS periodo_inicio,
    pc.fecha_fin AS periodo_fin,
    pc.estado AS estado_periodo,
    mp.fecha_medicion,
    mp.supuestos_aplicados,
    mp.id_asiento_contable,
    cvr_act.valor_neto AS vr_neto_actual,
    cvr_act.metodo_costo AS metodo_costo_actual,
    pm_act.fuente AS fuente_precio_actual,
    pm_act.precio_unitario AS precio_actual,
    cvr_ant.valor_neto AS vr_neto_anterior_calc,
    pm_ant.fuente AS fuente_precio_anterior,
    pm_ant.precio_unitario AS precio_anterior,
    ea.descripcion AS descripcion_evento,
    ea.fecha AS fecha_evento
   FROM ((((((((((modulo6.mediciones_posteriores mp
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = mp.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     JOIN modulo9.infraestructuras inf ON ((inf.id_infraestructura = ab.id_infraestructura)))
     JOIN modulo9.fincas f ON ((f.id_finca = inf.id_finca)))
     JOIN modulo6.periodos_contables pc ON ((pc.id_periodo_contable = mp.id_periodo_contable)))
     JOIN modulo6.calculos_valor_razonable cvr_act ON ((cvr_act.id_calculo_valor_razonable = mp.id_calculo_actual)))
     JOIN modulo6.calculos_valor_razonable cvr_ant ON ((cvr_ant.id_calculo_valor_razonable = mp.id_calculo_anterior)))
     JOIN modulo6.precios_mercado pm_act ON ((pm_act.id_precio_mercado = cvr_act.id_precio_mercado)))
     JOIN modulo6.precios_mercado pm_ant ON ((pm_ant.id_precio_mercado = cvr_ant.id_precio_mercado)))
     LEFT JOIN modulo2.eventos_activos ea ON ((ea.id_eventos = mp.id_evento)));


