--
-- Name: v_rollforward_activos_biologicos; Type: VIEW; Schema: modulo6; Owner: postgres
--

CREATE VIEW modulo6.v_rollforward_activos_biologicos AS
 WITH periodo_activo AS (
         SELECT periodos_contables.id_periodo_contable,
            periodos_contables.fecha_inicio,
            periodos_contables.fecha_fin
           FROM modulo6.periodos_contables
          WHERE (periodos_contables.estado = 'ABIERTO'::modulo6.enum_periodo_contables_estado)
         LIMIT 1
        ), saldo_inicial AS (
         SELECT mp.id_activo_biologico,
            mp.valor_razonable_anterior AS saldo_inicial
           FROM (modulo6.mediciones_posteriores mp
             JOIN periodo_activo pa_1 ON ((pa_1.id_periodo_contable = mp.id_periodo_contable)))
          WHERE (mp."id_ medicion_posterior" IN ( SELECT min(mediciones_posteriores."id_ medicion_posterior") AS min
                   FROM modulo6.mediciones_posteriores
                  WHERE (mediciones_posteriores.id_periodo_contable = ( SELECT periodo_activo.id_periodo_contable
                           FROM periodo_activo))
                  GROUP BY mediciones_posteriores.id_activo_biologico))
        ), saldo_final AS (
         SELECT v_ultimo_calculo_por_activo.id_activo_biologico,
            v_ultimo_calculo_por_activo.valor_neto AS saldo_final
           FROM modulo6.v_ultimo_calculo_por_activo
        ), ajuste_transformacion AS (
         SELECT mp.id_activo_biologico,
            sum(mp.ganancia_perdida_transformacion) AS total_transformacion
           FROM (modulo6.mediciones_posteriores mp
             JOIN periodo_activo pa_1 ON ((pa_1.id_periodo_contable = mp.id_periodo_contable)))
          GROUP BY mp.id_activo_biologico
        ), ajuste_precio AS (
         SELECT mp.id_activo_biologico,
            sum(mp.ganancia_perdida_precio_mercado) AS total_precio
           FROM (modulo6.mediciones_posteriores mp
             JOIN periodo_activo pa_1 ON ((pa_1.id_periodo_contable = mp.id_periodo_contable)))
          GROUP BY mp.id_activo_biologico
        ), cosechas AS (
         SELECT rpa.id_activo_biologico,
            sum(rpa.valor_reduccion_activo) AS total_cosechas
           FROM (modulo6.reconocimientos_productos_agricolas rpa
             JOIN periodo_activo pa_1 ON ((pa_1.id_periodo_contable = rpa.id_periodo_contable)))
          GROUP BY rpa.id_activo_biologico
        ), bajas AS (
         SELECT ab_1.id_activo_biologico,
            sum(rc.monto_costo) AS total_bajas_deterioro
           FROM ((modulo6.registros_costos rc
             JOIN modulo2.activos_biologicos ab_1 ON ((ab_1.id_activo_biologico = rc.id_activo_biologico)))
             JOIN periodo_activo pa_1 ON ((pa_1.id_periodo_contable = rc.id_periodo_contable)))
          WHERE (rc.naturaleza_costo = ANY (ARRAY['MANTENIMIENTO'::modulo6.enum_registros_costos_naturaleza_costo, 'INVERSION'::modulo6.enum_registros_costos_naturaleza_costo, 'VENTA'::modulo6.enum_registros_costos_naturaleza_costo]))
          GROUP BY ab_1.id_activo_biologico
        )
 SELECT ab.id_activo_biologico,
    ab.identificador,
    e.nombre AS especie,
    pa.id_periodo_contable,
    pa.fecha_inicio,
    pa.fecha_fin,
    COALESCE(si.saldo_inicial, (0)::numeric) AS saldo_inicial,
    COALESCE(at2.total_transformacion, (0)::numeric) AS ajuste_transformacion,
    COALESCE(ap.total_precio, (0)::numeric) AS ajuste_precio_mercado,
    (COALESCE(co.total_cosechas, (0)::numeric) * ('-1'::integer)::numeric) AS reduccion_por_cosechas,
    (COALESCE(ba.total_bajas_deterioro, (0)::numeric) * ('-1'::integer)::numeric) AS bajas_deterioro,
    COALESCE(sf.saldo_final, (0)::numeric) AS saldo_final
   FROM ((((((((modulo2.activos_biologicos ab
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
     CROSS JOIN periodo_activo pa)
     LEFT JOIN saldo_inicial si ON ((si.id_activo_biologico = ab.id_activo_biologico)))
     LEFT JOIN saldo_final sf ON ((sf.id_activo_biologico = ab.id_activo_biologico)))
     LEFT JOIN ajuste_transformacion at2 ON ((at2.id_activo_biologico = ab.id_activo_biologico)))
     LEFT JOIN ajuste_precio ap ON ((ap.id_activo_biologico = ab.id_activo_biologico)))
     LEFT JOIN cosechas co ON ((co.id_activo_biologico = ab.id_activo_biologico)))
     LEFT JOIN bajas ba ON ((ba.id_activo_biologico = ab.id_activo_biologico)));


ALTER VIEW modulo6.v_rollforward_activos_biologicos OWNER TO postgres;

