    pm_rej.fuente AS fuente_precio_rechazado,
    pm_rej.justificacion AS justificacion_rechazo,
    (((u.nombre)::text || ' '::text) || (u.apellidos)::text) AS marcado_por,
    vpc.id_usuario
   FROM ((((((modulo6.valoraciones_por_costos vpc
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = vpc.id_activo_biologico)))
