   FROM ((((((((modulo6.variaciones_valor_razonable vvr
     JOIN modulo2.activos_biologicos ab ON ((ab.id_activo_biologico = vvr.id_activo_biologico)))
     JOIN modulo9.especies e ON ((e.id_especie = ab.id_especie)))
