CREATE VIEW modulo6.vw_06_01precio_mercado_activo_por_activo AS
 SELECT act.id_activo_biologico,
    pm.id_especie,
    pm.estado,
    pm.fecha_vigencia,
    pm.fuente
   FROM ((modulo2.activos_biologicos act
     JOIN modulo9.especies e ON ((act.id_especie = e.id_especie)))
     JOIN modulo6.precios_mercado pm ON ((e.id_especie = pm.id_especie)))
  WHERE ((pm.estado = 'ACTIVO'::modulo6.enum_precio_mercado_estado) AND (pm.fecha_vigencia <= CURRENT_DATE));


