    pm.estado,
    pm.fecha_vigencia,
    pm.hash_evidencia,
    act.id_activo_biologico
   FROM ((modulo6.precios_mercado pm
     JOIN modulo9.especies e ON ((pm.id_especie = e.id_especie)))
     JOIN modulo2.activos_biologicos act ON ((act.id_especie = e.id_especie)));


ALTER VIEW modulo6.vw_06_02precios_mercado_vigentes OWNER TO postgres;

--
-- Name: vw_06_03parametros_costos_venta_activos; Type: VIEW; Schema: modulo6; Owner: postgres
--

CREATE VIEW modulo6.vw_06_03parametros_costos_venta_activos AS
 SELECT pcv.id_parametro_costo_venta,
    pcv.id_especie,
    pcv.es_activo
   FROM (modulo6.parametros_costos_venta pcv
     JOIN modulo9.especies e ON ((pcv.id_especie = e.id_especie)))
  WHERE (pcv.es_activo = true);


ALTER VIEW modulo6.vw_06_03parametros_costos_venta_activos OWNER TO postgres;

--
-- Name: vw_06_04reconocimientos_iniciales_detalle; Type: VIEW; Schema: modulo6; Owner: postgres
--

CREATE VIEW modulo6.vw_06_04reconocimientos_iniciales_detalle AS
 SELECT ri.id_reconocimiento_inicial,
    ri.estado,
    ri.cuenta_debito,
    ri.cuenta_credito,
    ri.valor_razonable_neto_inicial,
    ri.id_activo_biologico,
    ri.id_periodo_contable,
    ri.id_usuario,
    act.id_especie,
    act.id_infraestructura,
    inf.id_finca
   FROM ((modulo6.reconocimientos_iniciales ri
     JOIN modulo2.activos_biologicos act ON ((ri.id_activo_biologico = act.id_activo_biologico)))
     JOIN modulo9.infraestructuras inf ON ((act.id_infraestructura = inf.id_infraestructura)));


ALTER VIEW modulo6.vw_06_04reconocimientos_iniciales_detalle OWNER TO postgres;

--
-- Name: vw_06_05_activos_sin_reconocimiento; Type: VIEW; Schema: modulo6; Owner: postgres
--

CREATE VIEW modulo6.vw_06_05_activos_sin_reconocimiento AS
 SELECT act.id_activo_biologico,
    act.id_especie,
    act.id_infraestructura,
    ri.id_reconocimiento_inicial,
    ri.estado
   FROM (modulo2.activos_biologicos act
     LEFT JOIN modulo6.reconocimientos_iniciales ri ON ((ri.id_activo_biologico = act.id_activo_biologico)))
  WHERE (ri.id_activo_biologico IS NULL);


ALTER VIEW modulo6.vw_06_05_activos_sin_reconocimiento OWNER TO postgres;

