CREATE TABLE modulo7.auditoria_peticiones (
    id_auditoria integer NOT NULL,
    evento uuid NOT NULL,
    id_intgracion_solucitud integer NOT NULL,
    id_usuario integer NOT NULL,
    id_auditorias_financieras integer NOT NULL,
    tipo character varying(80) NOT NULL,
    fecha timestamp with time zone NOT NULL,
    datos jsonb NOT NULL,
    evento_sha256 character varying(64) NOT NULL,
    es_inmuntable boolean DEFAULT true NOT NULL,
    CONSTRAINT chk_auditoria_datos_no_vacio CHECK ((datos <> '{}'::jsonb)),
    CONSTRAINT chk_auditoria_fecha_no_futura CHECK ((fecha <= now())),
    CONSTRAINT chk_auditoria_inmutable CHECK ((es_inmuntable = true)),
    CONSTRAINT chk_auditoria_sha256_formato CHECK (((evento_sha256)::text ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT chk_auditoria_tipo_no_vacio CHECK ((char_length(TRIM(BOTH FROM tipo)) > 0))
);


