--

CREATE TABLE modulo7.identificadores_apis (
    id_identificador_api integer NOT NULL,
    id_cliente_externo integer NOT NULL,
    api_llave_encriptada character varying(64) NOT NULL,
    certificado_serial character varying(120),
    fecha_emision timestamp with time zone NOT NULL,
    fecha_expiracion timestamp with time zone NOT NULL,
    fecha_revocacion timestamp with time zone,
    estado modulo7.enum_identificadores_apis_estado NOT NULL,
    fecha_creacion timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_api_key_emision_no_futura CHECK ((fecha_emision <= now())),
    CONSTRAINT chk_api_key_fechas_coherentes CHECK ((fecha_expiracion > fecha_emision)),
    CONSTRAINT chk_api_key_llave_no_vacia CHECK ((char_length(TRIM(BOTH FROM api_llave_encriptada)) > 0)),
    CONSTRAINT chk_api_key_revocacion_posterior CHECK (((fecha_revocacion IS NULL) OR (fecha_revocacion >= fecha_emision))),
    CONSTRAINT chk_api_key_revocada_tiene_fecha CHECK (((estado <> 'REVOCADA'::modulo7.enum_identificadores_apis_estado) OR (fecha_revocacion IS NOT NULL)))
);


ALTER TABLE modulo7.identificadores_apis OWNER TO postgres;

