CREATE TABLE modulo7.integraciones_solicitudes (
    id_integracion_solicitud integer NOT NULL,
    id_cliente_externo integer NOT NULL,
    id_usuario integer,
    id_periodo_contable integer,
    id_version_contrato integer,
    estado modulo7.enum_integraciones_solicitudes_estado NOT NULL,
    fecha_comienzoo timestamp with time zone NOT NULL,
    fecha_finalizacion timestamp with time zone NOT NULL,
    duracion_ms integer,
    correlacion_id uuid,
    id_error integer,
    CONSTRAINT chk_solicitud_duracion_no_negativa CHECK (((duracion_ms IS NULL) OR (duracion_ms >= 0))),
    CONSTRAINT chk_solicitud_error_coherente CHECK (((estado = 'SUCCESS'::modulo7.enum_integraciones_solicitudes_estado) OR (id_error IS NOT NULL) OR (estado = 'TIMEOUT'::modulo7.enum_integraciones_solicitudes_estado))),
    CONSTRAINT chk_solicitud_fecha_no_futura CHECK ((fecha_comienzoo <= now())),
    CONSTRAINT chk_solicitud_fechas_coherentes CHECK ((fecha_finalizacion >= fecha_comienzoo))
);


