--
-- Name: mapeos_anexos_aaef; Type: TABLE; Schema: modulo7; Owner: postgres
--

CREATE TABLE modulo7.mapeos_anexos_aaef (
    id_mapeo_anexo_aaef integer NOT NULL,
    id_version_contrato_aaef integer NOT NULL,
    codigo_anexo character varying(40) NOT NULL,
    version_anexo character varying(40) NOT NULL,
    estado modulo7.enum_mapeos_anexos_aaef_estado NOT NULL,
    direccion_pdf text NOT NULL,
    canonical_sha256 character varying(64) NOT NULL,
    fecha_aprobacion_interna timestamp with time zone,
    fecha_aprobacion_agrofusion timestamp with time zone,
    fecha_creacion timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_mapeo_aprobacion_orden CHECK (((fecha_aprobacion_agrofusion IS NULL) OR (fecha_aprobacion_interna IS NULL) OR (fecha_aprobacion_agrofusion >= fecha_aprobacion_interna))),
    CONSTRAINT chk_mapeo_aprobado_tiene_fechas CHECK (((estado <> 'APROBADO'::modulo7.enum_mapeos_anexos_aaef_estado) OR ((fecha_aprobacion_interna IS NOT NULL) AND (fecha_aprobacion_agrofusion IS NOT NULL)))),
    CONSTRAINT chk_mapeo_direccion_no_vacia CHECK ((char_length(TRIM(BOTH FROM direccion_pdf)) > 0)),
    CONSTRAINT chk_mapeo_sha256_formato CHECK (((canonical_sha256)::text ~ '^[a-f0-9]{64}$'::text))
);


ALTER TABLE modulo7.mapeos_anexos_aaef OWNER TO postgres;

