    fecha_creacion timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_metadato_jsonb_no_vacios CHECK (((metadatos <> '{}'::jsonb) AND (facturas <> '[]'::jsonb) AND (resumen <> '{}'::jsonb))),
    CONSTRAINT chk_metadato_sha256_formato CHECK (((sha256_sobre)::text ~ '^[a-f0-9]{64}$'::text))
);


