--

CREATE TABLE modulo7.notificaciones_weebhook (
    id_notificacion_weebhook integer NOT NULL,
    tipo_evento modulo7.enum_notificaciones_weebhook_estado_notificacion NOT NULL,
    url_destino text NOT NULL,
    payload_sha256 character varying(64) NOT NULL,
    codigo_respuesta integer,
    estado_notifiacion modulo7.enum_notificaciones_weebhook_tipo NOT NULL,
    fecha_envio timestamp with time zone NOT NULL,
    fecha_recepcion timestamp with time zone,
    id_integracion_solicitudes integer NOT NULL,
    CONSTRAINT chk_webhook_codigo_http_valido CHECK (((codigo_respuesta IS NULL) OR ((codigo_respuesta >= 100) AND (codigo_respuesta <= 599)))),
    CONSTRAINT chk_webhook_envio_no_futuro CHECK ((fecha_envio <= now())),
    CONSTRAINT chk_webhook_fechas_coherentes CHECK (((fecha_recepcion IS NULL) OR (fecha_recepcion >= fecha_envio))),
    CONSTRAINT chk_webhook_sha256_formato CHECK (((payload_sha256)::text ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT chk_webhook_url_no_vacia CHECK ((char_length(TRIM(BOTH FROM url_destino)) > 0))
);


ALTER TABLE modulo7.notificaciones_weebhook OWNER TO postgres;

