    orden_ejecucion smallint NOT NULL,
    fecha_comienzo timestamp with time zone NOT NULL,
    duration_ms integer,
    mensaje_error text,
    CONSTRAINT chk_mapeador_duracion_no_negativa CHECK (((duration_ms IS NULL) OR (duration_ms >= 0))),
    CONSTRAINT chk_mapeador_failed_tiene_mensaje CHECK (((estado <> 'FAILED'::modulo7.enum_registros_ejecucion_mapeador_estado) OR (mensaje_error IS NOT NULL))),
    CONSTRAINT chk_mapeador_orden_positivo CHECK ((orden_ejecucion >= 1))
);


