CREATE TABLE modulo7.reglas_mapeo_aaef (
    id_regla_mapeo_aaef integer NOT NULL,
    id_mapeo_anexo integer NOT NULL,
    id_tipo_documento integer NOT NULL,
    entidad_origen character varying(120) NOT NULL,
    campo_origen character varying(120) NOT NULL,
    campo_destino character varying(120) NOT NULL,
    regla_transformacion text,
    es_requerida boolean DEFAULT false NOT NULL,
    fecha_creacion timestamp with time zone DEFAULT now() NOT NULL,
