--
-- Name: v_pipeline_solicitud; Type: VIEW; Schema: modulo7; Owner: postgres
--

CREATE VIEW modulo7.v_pipeline_solicitud AS
 SELECT ins.id_integracion_solicitud,
    ins.correlacion_id,
    ins.estado AS estado_solicitud,
    ins.fecha_comienzoo AS inicio,
    ins.fecha_finalizacion AS fin,
    ins.duracion_ms,
    ce.id_cliente_externo,
    ce.nombre AS cliente,
    ce.codigo AS cliente_codigo,
    vc.contrato_version,
    vc.estado AS estado_contrato,
    COALESCE(json_agg(json_build_object('orden', rem.orden_ejecucion, 'nombre', rem.nombre, 'estado', rem.estado, 'duracion_ms', rem.duration_ms, 'error', rem.mensaje_error) ORDER BY rem.orden_ejecucion) FILTER (WHERE (rem.id_registro_ejecucion_mapeador IS NOT NULL)), '[]'::json) AS pasos_mapeador,
    count(dg.id_documentos_generados_aaef) AS documentos_generados,
    nw.estado_notifiacion AS webhook_estado,
    nw.codigo_respuesta AS webhook_codigo_http,
    nw.fecha_envio AS webhook_enviado_en,
    nw.fecha_recepcion AS webhook_confirmado_en,
    ce_err.codigo AS error_codigo,
    ce_err.mensaje AS error_mensaje,
    ce_err.estado_http AS error_http
   FROM ((((((modulo7.integraciones_solicitudes ins
     JOIN modulo7.clientes_externos ce ON ((ce.id_cliente_externo = ins.id_cliente_externo)))
     LEFT JOIN modulo7.versiones_contrato_aaef vc ON ((vc.id_version_contrato_aaef = ins.id_version_contrato)))
     LEFT JOIN modulo7.registros_ejecucion_mapeador rem ON ((rem.id_integracion_solicitud = ins.id_integracion_solicitud)))
     LEFT JOIN modulo7.documentos_generados_aaef dg ON ((dg.id_integracion_solicitud = ins.id_integracion_solicitud)))
     LEFT JOIN LATERAL ( SELECT nwi.id_notificacion_weebhook,
            nwi.tipo_evento,
            nwi.url_destino,
            nwi.payload_sha256,
            nwi.codigo_respuesta,
            nwi.estado_notifiacion,
            nwi.fecha_envio,
            nwi.fecha_recepcion,
            nwi.id_integracion_solicitudes
           FROM modulo7.notificaciones_weebhook nwi
          WHERE (nwi.id_integracion_solicitudes = ins.id_integracion_solicitud)
          ORDER BY nwi.fecha_envio DESC
         LIMIT 1) nw ON (true))
     LEFT JOIN modulo7.catalogo_errores_de_integracion ce_err ON ((ce_err.id_catalogo_error = ins.id_error)))
  GROUP BY ins.id_integracion_solicitud, ins.correlacion_id, ins.estado, ins.fecha_comienzoo, ins.fecha_finalizacion, ins.duracion_ms, ce.id_cliente_externo, ce.nombre, ce.codigo, vc.contrato_version, vc.estado, nw.estado_notifiacion, nw.codigo_respuesta, nw.fecha_envio, nw.fecha_recepcion, ce_err.codigo, ce_err.mensaje, ce_err.estado_http;


ALTER VIEW modulo7.v_pipeline_solicitud OWNER TO postgres;

--
-- Name: VIEW v_pipeline_solicitud; Type: COMMENT; Schema: modulo7; Owner: postgres
--

COMMENT ON VIEW modulo7.v_pipeline_solicitud IS 'Vista transversal: traza el ciclo de vida completo de una solicitud de integración — cliente → mapeador (pasos) → documentos generados → webhook. Alimenta los modales de detalle en RF-99 (Detalle de entrega) y RF-102 (Detalle del evento). Usa LATERAL para traer solo el último webhook.';


--
-- Name: v_rf101_clientes_externos; Type: VIEW; Schema: modulo7; Owner: postgres
--

CREATE VIEW modulo7.v_rf101_clientes_externos AS
 SELECT ce.id_cliente_externo,
    ce.codigo,
    ce.nombre AS sistema,
    ce.tipo,
    ce.estado,
    ce.ip_permitida,
    ce.fecha_creacion,
    api.id_identificador_api,
    api.fecha_expiracion AS clave_vence,
    api.fecha_revocacion AS clave_revocada_en,
    api.estado AS estado_clave,
    ((api.fecha_expiracion)::date - CURRENT_DATE) AS dias_para_vencer,
    ( SELECT count(*) AS count
           FROM modulo7.permisos_clientes pc
          WHERE (pc.id_clienete_externo = ce.id_cliente_externo)) AS total_permisos,
    ( SELECT count(*) AS count
           FROM (modulo7.notificaciones_weebhook nw
             JOIN modulo7.integraciones_solicitudes ins ON ((ins.id_integracion_solicitud = nw.id_integracion_solicitudes)))
          WHERE (ins.id_cliente_externo = ce.id_cliente_externo)) AS total_webhooks,
    ( SELECT max(ins.fecha_comienzoo) AS max
           FROM modulo7.integraciones_solicitudes ins
          WHERE (ins.id_cliente_externo = ce.id_cliente_externo)) AS ultima_actividad,
    ( SELECT max(ins.fecha_comienzoo) AS max
           FROM modulo7.integraciones_solicitudes ins
          WHERE ((ins.id_cliente_externo = ce.id_cliente_externo) AND (ins.estado = 'SUCCESS'::modulo7.enum_integraciones_solicitudes_estado))) AS ultima_solicitud_exitosa
   FROM (modulo7.clientes_externos ce
     LEFT JOIN LATERAL ( SELECT ia.id_identificador_api,
            ia.id_cliente_externo,
            ia.api_llave_encriptada,
            ia.certificado_serial,
            ia.fecha_emision,
            ia.fecha_expiracion,
            ia.fecha_revocacion,
            ia.estado,
            ia.fecha_creacion
           FROM modulo7.identificadores_apis ia
          WHERE ((ia.id_cliente_externo = ce.id_cliente_externo) AND (ia.fecha_revocacion IS NULL))
          ORDER BY ia.fecha_creacion DESC
         LIMIT 1) api ON (true));


ALTER VIEW modulo7.v_rf101_clientes_externos OWNER TO postgres;

--
-- Name: VIEW v_rf101_clientes_externos; Type: COMMENT; Schema: modulo7; Owner: postgres
--

COMMENT ON VIEW modulo7.v_rf101_clientes_externos IS 'RF-101: Directorio de clientes externos con su credencial API vigente, conteo de webhooks y timestamp de última actividad. Usa LATERAL para obtener solo la clave activa más reciente.';


--
-- Name: v_rf101_historial_cliente; Type: VIEW; Schema: modulo7; Owner: postgres
--

CREATE VIEW modulo7.v_rf101_historial_cliente AS
 SELECT ap.id_auditoria,
    ap.id_intgracion_solucitud AS id_integracion_solicitud,
    ins.id_cliente_externo,
    ce.nombre AS cliente_nombre,
    ap.tipo AS evento,
    ap.fecha,
    (ap.datos ->> 'ip_origen'::text) AS ip,
    (ap.datos ->> 'motivo'::text) AS motivo,
    ap.evento_sha256,
    ap.es_inmuntable
   FROM ((modulo7.auditoria_peticiones ap
     JOIN modulo7.integraciones_solicitudes ins ON ((ins.id_integracion_solicitud = ap.id_intgracion_solucitud)))
     JOIN modulo7.clientes_externos ce ON ((ce.id_cliente_externo = ins.id_cliente_externo)))
  ORDER BY ap.fecha DESC;


ALTER VIEW modulo7.v_rf101_historial_cliente OWNER TO postgres;

--
-- Name: VIEW v_rf101_historial_cliente; Type: COMMENT; Schema: modulo7; Owner: postgres
--

COMMENT ON VIEW modulo7.v_rf101_historial_cliente IS 'RF-101: Historial de operaciones por cliente (panel lateral de auditoría). Proyecta ip_origen y motivo desde la columna JSONB datos.';


--
-- Name: v_rf102_auditoria_integracion; Type: VIEW; Schema: modulo7; Owner: postgres
--

CREATE VIEW modulo7.v_rf102_auditoria_integracion AS
 SELECT ap.id_auditoria,
    ap.evento AS evento_uuid,
    ap.fecha AS timestamp_evento,
    ap.tipo AS tipo_evento_label,
    ap.es_inmuntable,
    ((ap.evento_sha256 IS NOT NULL) AND (ap.es_inmuntable = true)) AS es_integro,
    ap.evento_sha256,
    ins.id_cliente_externo,
    ce.nombre AS sistema_externo,
    ce.tipo AS tipo_sistema,
    (((u.nombre)::text || ' '::text) || (u.apellidos)::text) AS actor_usuario,
    COALESCE(ce.nombre, ((((u.nombre)::text || ' '::text) || (u.apellidos)::text))::character varying, '—'::character varying) AS actor,
    (ap.datos ->> 'ip_origen'::text) AS ip_origen,
    ins.id_integracion_solicitud,
    ins.estado AS estado_solicitud,
    ins.correlacion_id,
    ce_err.estado_http AS codigo_http,
    ce_err.mensaje AS mensaje_error,
    ce_err.codigo AS codigo_error_enum,
        CASE
            WHEN (ce_err.estado_http >= 500) THEN 'CRITICO'::text
            WHEN (ce_err.estado_http >= 400) THEN 'ADVERTENCIA'::text
            WHEN (ins.estado = 'SUCCESS'::modulo7.enum_integraciones_solicitudes_estado) THEN 'INFORMATIVO'::text
            ELSE 'INFORMATIVO'::text
        END AS severidad,
        CASE
            WHEN (((ap.tipo)::text ~~* '%EXPORTACION%'::text) OR ((ap.tipo)::text ~~* '%AEEF%'::text)) THEN 'EXPORTACION_AEEF'::text
            WHEN (((ap.tipo)::text ~~* '%AUTENTICACION%'::text) OR ((ap.tipo)::text ~~* '%ACCESO%'::text)) THEN 'AUTENTICACION'::text
            WHEN (((ap.tipo)::text ~~* '%ERROR%'::text) OR (ce_err.id_catalogo_error IS NOT NULL)) THEN 'ERROR'::text
            ELSE 'OPERACION'::text
        END AS categoria,
    af.id_auditoria_financiera,
    af.tipo AS tipo_auditoria_financiera,
    af.severidad AS severidad_auditoria_financiera,
    ins.id_periodo_contable
   FROM (((((modulo7.auditoria_peticiones ap
     JOIN modulo7.integraciones_solicitudes ins ON ((ins.id_integracion_solicitud = ap.id_intgracion_solucitud)))
     JOIN modulo7.clientes_externos ce ON ((ce.id_cliente_externo = ins.id_cliente_externo)))
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = ap.id_usuario)))
     LEFT JOIN modulo7.catalogo_errores_de_integracion ce_err ON ((ce_err.id_catalogo_error = ins.id_error)))
     LEFT JOIN modulo6.auditorias_financieras af ON ((af.id_auditoria_financiera = ap.id_auditorias_financieras)));


ALTER VIEW modulo7.v_rf102_auditoria_integracion OWNER TO postgres;

--
-- Name: VIEW v_rf102_auditoria_integracion; Type: COMMENT; Schema: modulo7; Owner: postgres
--

COMMENT ON VIEW modulo7.v_rf102_auditoria_integracion IS 'RF-102: Historial de auditoría de integración completo. Combina auditoria_peticiones + solicitudes + cliente + usuario + error + auditoría financiera. Severidad y Categoría son campos derivados que alimentan los badges de la UI. es_integro valida que el registro tenga sha256 y no haya sido mutado (es_inmuntable = true).';


--
-- Name: v_rf102_stats_auditoria; Type: VIEW; Schema: modulo7; Owner: postgres
--

CREATE VIEW modulo7.v_rf102_stats_auditoria AS
 SELECT count(*) FILTER (WHERE ((ap.fecha)::date = CURRENT_DATE)) AS eventos_hoy,
    count(*) FILTER (WHERE (((ap.fecha)::date = CURRENT_DATE) AND (ins.estado = 'SUCCESS'::modulo7.enum_integraciones_solicitudes_estado) AND (((ap.tipo)::text ~~* '%AEEF%'::text) OR ((ap.tipo)::text ~~* '%EXPORTACION%'::text)))) AS consultas_aeef_exitosas,
    count(*) FILTER (WHERE (((ap.fecha)::date = CURRENT_DATE) AND ((ce_err.estado_http >= 500) OR (ins.estado = 'FAILED'::modulo7.enum_integraciones_solicitudes_estado)))) AS alertas_criticas,
    count(*) FILTER (WHERE ((ap.evento_sha256 IS NULL) OR (ap.es_inmuntable = false))) AS integridad_comprometida
   FROM ((modulo7.auditoria_peticiones ap
     JOIN modulo7.integraciones_solicitudes ins ON ((ins.id_integracion_solicitud = ap.id_intgracion_solucitud)))
     LEFT JOIN modulo7.catalogo_errores_de_integracion ce_err ON ((ce_err.id_catalogo_error = ins.id_error)));


ALTER VIEW modulo7.v_rf102_stats_auditoria OWNER TO postgres;

--
-- Name: VIEW v_rf102_stats_auditoria; Type: COMMENT; Schema: modulo7; Owner: postgres
--

COMMENT ON VIEW modulo7.v_rf102_stats_auditoria IS 'RF-102: Contadores para las 4 stat-cards del encabezado de auditoría.';


--
-- Name: v_rf98_contratos_integracion; Type: VIEW; Schema: modulo7; Owner: postgres
--

CREATE VIEW modulo7.v_rf98_contratos_integracion AS
 SELECT vc.id_version_contrato_aaef,
    vc.contrato_version AS version,
    vc.estado,
    vc.fecha_comienzo AS vigente_desde,
    vc.descripcion,
    vc.fecha_creacion,
    ma.id_mapeo_anexo_aaef,
    ma.codigo_anexo AS transformador,
    ma.version_anexo AS version_transformador,
    ma.estado AS estado_transformador,
    (ma.estado = 'APROBADO'::modulo7.enum_mapeos_anexos_aaef_estado) AS transformador_disponible,
    ma.fecha_aprobacion_agrofusion AS fecha_aprobacion_transformador,
        CASE
            WHEN ((vc.contrato_version)::text ~~ '%.0'::text) THEN 'MAYOR'::text
            WHEN (((vc.contrato_version)::text ~~ '%.%'::text) AND ((split_part((vc.contrato_version)::text, '.'::text, 2))::integer > 0)) THEN 'MENOR'::text
            ELSE 'INICIAL'::text
        END AS tipo_cambio,
    count(rm.id_regla_mapeo_aaef) AS total_reglas_mapeo,
    count(rm.id_regla_mapeo_aaef) FILTER (WHERE rm.es_requerida) AS reglas_requeridas
   FROM ((modulo7.versiones_contrato_aaef vc
     LEFT JOIN modulo7.mapeos_anexos_aaef ma ON ((ma.id_version_contrato_aaef = vc.id_version_contrato_aaef)))
     LEFT JOIN modulo7.reglas_mapeo_aaef rm ON ((rm.id_mapeo_anexo = ma.id_mapeo_anexo_aaef)))
  GROUP BY vc.id_version_contrato_aaef, vc.contrato_version, vc.estado, vc.fecha_comienzo, vc.descripcion, vc.fecha_creacion, ma.id_mapeo_anexo_aaef, ma.codigo_anexo, ma.version_anexo, ma.estado, ma.fecha_aprobacion_agrofusion;


ALTER VIEW modulo7.v_rf98_contratos_integracion OWNER TO postgres;

--
-- Name: VIEW v_rf98_contratos_integracion; Type: COMMENT; Schema: modulo7; Owner: postgres
--

COMMENT ON VIEW modulo7.v_rf98_contratos_integracion IS 'RF-98: Listado de versiones del contrato AAEF con su transformador (mapeo) activo y métricas de completitud de reglas. Alimenta la tabla principal y el modal de detalle.';


--
-- Name: v_rf98_stats_contratos; Type: VIEW; Schema: modulo7; Owner: postgres
--

CREATE VIEW modulo7.v_rf98_stats_contratos AS
 SELECT count(*) FILTER (WHERE (estado = 'APROBADO'::modulo7.enum_versiones_contrato_aaef_estado)) AS versiones_vigentes,
    count(*) FILTER (WHERE (estado = 'EN_REVISION'::modulo7.enum_versiones_contrato_aaef_estado)) AS en_periodo_gracia,
    count(*) FILTER (WHERE (estado = ANY (ARRAY['BORRADOR'::modulo7.enum_versiones_contrato_aaef_estado, 'OBSOLETO'::modulo7.enum_versiones_contrato_aaef_estado]))) AS archivadas,
    count(*) AS total
   FROM modulo7.versiones_contrato_aaef;


ALTER VIEW modulo7.v_rf98_stats_contratos OWNER TO postgres;

--
-- Name: VIEW v_rf98_stats_contratos; Type: COMMENT; Schema: modulo7; Owner: postgres
--

COMMENT ON VIEW modulo7.v_rf98_stats_contratos IS 'RF-98: Contadores para las stat-cards del encabezado de la pantalla.';


--
-- Name: v_rf99_stats_webhooks; Type: VIEW; Schema: modulo7; Owner: postgres
--

CREATE VIEW modulo7.v_rf99_stats_webhooks AS
 SELECT count(*) FILTER (WHERE ((fecha_envio)::date = CURRENT_DATE)) AS enviados_hoy,
    count(*) FILTER (WHERE ((estado_notifiacion = 'PERIODO_CERRADO'::modulo7.enum_notificaciones_weebhook_tipo) AND ((fecha_envio)::date = CURRENT_DATE))) AS confirmados_hoy,
    count(*) FILTER (WHERE ((estado_notifiacion <> 'PERIODO_CERRADO'::modulo7.enum_notificaciones_weebhook_tipo) AND ((fecha_envio)::date = CURRENT_DATE))) AS en_curso_hoy,
    count(*) FILTER (WHERE ((estado_notifiacion = 'PERIODO_CERRADO'::modulo7.enum_notificaciones_weebhook_tipo) AND ((fecha_envio)::date = CURRENT_DATE))) AS fallidos_hoy
   FROM modulo7.notificaciones_weebhook;


ALTER VIEW modulo7.v_rf99_stats_webhooks OWNER TO postgres;

--
-- Name: VIEW v_rf99_stats_webhooks; Type: COMMENT; Schema: modulo7; Owner: postgres
--

COMMENT ON VIEW modulo7.v_rf99_stats_webhooks IS 'RF-99: Contadores diarios para las stat-cards de la pantalla de webhooks.';


--
-- Name: v_rf99_webhooks; Type: VIEW; Schema: modulo7; Owner: postgres
--

CREATE VIEW modulo7.v_rf99_webhooks AS
 SELECT nw.id_notificacion_weebhook,
    nw.tipo_evento,
    nw.estado_notifiacion AS estado,
    nw.url_destino,
    nw.payload_sha256,
    nw.codigo_respuesta,
    nw.fecha_envio,
    nw.fecha_recepcion,
    EXTRACT(millisecond FROM (nw.fecha_recepcion - nw.fecha_envio)) AS latencia_ms,
    (nw.payload_sha256 IS NOT NULL) AS firma_valida,
    ce.id_cliente_externo,
    ce.nombre AS cliente_nombre,
    ce.codigo AS cliente_codigo,
    ce.estado AS cliente_estado,
    ins.id_integracion_solicitud,
    ins.estado AS estado_solicitud,
    ins.correlacion_id,
    ins.duracion_ms AS duracion_solicitud_ms,
    ( SELECT count(*) AS count
           FROM modulo7.notificaciones_weebhook nx
          WHERE (nx.id_integracion_solicitudes = nw.id_integracion_solicitudes)) AS intentos_totales
   FROM ((modulo7.notificaciones_weebhook nw
     JOIN modulo7.integraciones_solicitudes ins ON ((ins.id_integracion_solicitud = nw.id_integracion_solicitudes)))
     JOIN modulo7.clientes_externos ce ON ((ce.id_cliente_externo = ins.id_cliente_externo)));


ALTER VIEW modulo7.v_rf99_webhooks OWNER TO postgres;

--
-- Name: VIEW v_rf99_webhooks; Type: COMMENT; Schema: modulo7; Owner: postgres
--

COMMENT ON VIEW modulo7.v_rf99_webhooks IS 'RF-99: Historial de notificaciones webhook enriquecido con datos del cliente y la solicitud. Columna intentos_totales facilita mostrar el chip de reintentos.';


