--
-- Name: acciones_critica_log; Type: TABLE; Schema: modulo8; Owner: postgres
--

CREATE TABLE modulo8.acciones_critica_log (
    id_accion_critica_log integer NOT NULL,
    id_usuario integer NOT NULL,
    id_operacion uuid NOT NULL,
    tipo_accion character varying(50) NOT NULL,
    resultado_operacion modulo8.acciones_critica_log_resultado_operacion,
    requiere_confirmacion boolean DEFAULT false NOT NULL,
    confirmacion boolean,
    fecha_ejecucion timestamp with time zone DEFAULT now() NOT NULL,
    clave_error_funcional character varying(80),
    CONSTRAINT chk_accion_clave_error_no_vacia CHECK (((clave_error_funcional IS NULL) OR (char_length(TRIM(BOTH FROM clave_error_funcional)) > 0))),
    CONSTRAINT chk_accion_critica_clave_error_cuando_falla CHECK (((resultado_operacion <> 'FALLIDO'::modulo8.acciones_critica_log_resultado_operacion) OR ((clave_error_funcional IS NOT NULL) AND (TRIM(BOTH FROM clave_error_funcional) <> ''::text)))),
    CONSTRAINT chk_accion_critica_confirmacion_obligatoria CHECK (((requiere_confirmacion = false) OR (confirmacion IS NOT NULL))),
    CONSTRAINT chk_accion_critica_tipo_valido CHECK (((tipo_accion)::text = ANY (ARRAY[('REGISTRO_ACTIVO'::character varying)::text, ('BAJA_ACTIVO'::character varying)::text, ('CIERRE_PERIODO'::character varying)::text, ('EXPORTACION_SIGCON'::character varying)::text, ('REVOCACION_CREDENCIALES'::character varying)::text, ('REVERSION_RECONOCIMIENTO'::character varying)::text, ('GENERACION_REPORTE'::character varying)::text, ('CANCELACION_REPORTE'::character varying)::text]))),
    CONSTRAINT chk_accion_fecha_no_futura CHECK ((fecha_ejecucion <= now())),
    CONSTRAINT chk_accion_tipo_no_vacio CHECK ((char_length(TRIM(BOTH FROM tipo_accion)) > 0))
);


ALTER TABLE modulo8.acciones_critica_log OWNER TO postgres;

--
-- Name: TABLE acciones_critica_log; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON TABLE modulo8.acciones_critica_log IS 'Bitácora de auditoría de acciones críticas ejecutadas en el sistema.
Registra cada operación de alto impacto con su resultado, si requirió confirmación,
y si hubo errores funcionales. Soporta trazabilidad completa para auditorías internas
y es clave para la seguridad operativa del sistema.';


--
-- Name: COLUMN acciones_critica_log.id_accion_critica_log; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.acciones_critica_log.id_accion_critica_log IS 'Identificador único del registro de acción crítica. Clave primaria (serial).';


--
-- Name: COLUMN acciones_critica_log.id_usuario; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.acciones_critica_log.id_usuario IS 'FK hacia modulo1.usuarios. Usuario que ejecutó la acción crítica registrada.';


--
-- Name: COLUMN acciones_critica_log.id_operacion; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.acciones_critica_log.id_operacion IS 'UUID único que identifica la operación de negocio en toda la cadena de ejecución.
Permite correlacionar este log con registros en otros sistemas o microservicios.';


--
-- Name: COLUMN acciones_critica_log.tipo_accion; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.acciones_critica_log.tipo_accion IS 'Tipo de acción crítica ejecutada (ej: ELIMINACION_MASIVA, CIERRE_PERIODO,
EXPORTACION_SENSIBLE). Máximo 50 caracteres.';


--
-- Name: COLUMN acciones_critica_log.resultado_operacion; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.acciones_critica_log.resultado_operacion IS 'Resultado final de la ejecución de la acción. ENUM definido en modulo8
(ej: EXITOSO, FALLIDO, PARCIAL).';


--
-- Name: COLUMN acciones_critica_log.requiere_confirmacion; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.acciones_critica_log.requiere_confirmacion IS 'Indica si esta acción requería una confirmación explícita del usuario antes
de ejecutarse, como doble factor de validación operativa.';


--
-- Name: COLUMN acciones_critica_log.confirmacion; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.acciones_critica_log.confirmacion IS 'Registra si el usuario efectivamente confirmó la acción cuando esta lo requería.
NULL si la acción no requería confirmación. (Nota: typo en nombre heredado del diseño.)';


--
-- Name: COLUMN acciones_critica_log.fecha_ejecucion; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.acciones_critica_log.fecha_ejecucion IS 'Marca temporal (con zona horaria) del momento exacto en que se ejecutó la acción.';


--
-- Name: COLUMN acciones_critica_log.clave_error_funcional; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.acciones_critica_log.clave_error_funcional IS 'Código o clave del error funcional ocurrido durante la ejecución, si aplica.
Permite mapear el error a un catálogo de errores del sistema. Máximo 80 caracteres.';


--
-- Name: acciones_critica_log_id_accion_critica_log_seq; Type: SEQUENCE; Schema: modulo8; Owner: postgres
--

CREATE SEQUENCE modulo8.acciones_critica_log_id_accion_critica_log_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo8.acciones_critica_log_id_accion_critica_log_seq OWNER TO postgres;

