CREATE TABLE modulo8.auditorias_reportes (
    id_auditoria_reporte integer NOT NULL,
    id_reporte_regulatoria integer NOT NULL,
    filtros_aplicados jsonb NOT NULL,
    id_usuario integer NOT NULL,
    timestamp_snapshot timestamp with time zone NOT NULL,
    estado_final character varying(15),
    CONSTRAINT chk_auditoria_reporte_estado_final_valido CHECK (((estado_final IS NULL) OR ((estado_final)::text = ANY (ARRAY[('GENERADO'::character varying)::text, ('FALLIDO'::character varying)::text, ('CANCELADO'::character varying)::text, ('EXPIRADO'::character varying)::text])))),
    CONSTRAINT chk_auditoria_reporte_filtros_no_vacios CHECK (((filtros_aplicados IS NOT NULL) AND (filtros_aplicados <> '{}'::jsonb))),
    CONSTRAINT chk_auditoria_reporte_timestamp_no_futuro CHECK ((timestamp_snapshot <= now()))
);


ALTER TABLE modulo8.auditorias_reportes OWNER TO postgres;

--
-- Name: TABLE auditorias_reportes; Type: COMMENT; Schema: modulo8; Owner: postgres
