--
-- Name: configuraciones_semaforo; Type: TABLE; Schema: modulo8; Owner: postgres
--

CREATE TABLE modulo8.configuraciones_semaforo (
    id_configuracion_semaforo integer NOT NULL,
    id_indicador_kpi integer NOT NULL,
    id_activo_biologico integer,
    umbral_verde_min numeric(12,2),
    umbral_verde_max numeric(12,2),
    umbral_amarillo_min numeric(12,2),
    umbral_amarillo_max numeric(12,2),
    umbral_rojo_max numeric(12,2),
    umbral_rojo_min numeric(12,2),
    fecha_vigencia date NOT NULL,
    es_activo boolean DEFAULT true NOT NULL,
    id_infraestructura integer,
    CONSTRAINT chk_semaforo_al_menos_un_rango CHECK (((umbral_verde_min IS NOT NULL) OR (umbral_rojo_min IS NOT NULL))),
    CONSTRAINT chk_semaforo_amarillo_menor_que_rojo CHECK (((umbral_amarillo_max IS NULL) OR (umbral_rojo_min IS NULL) OR (umbral_amarillo_max < umbral_rojo_min))),
    CONSTRAINT chk_semaforo_rango_amarillo_coherente CHECK (((umbral_amarillo_min IS NULL) OR (umbral_amarillo_max IS NULL) OR (umbral_amarillo_min <= umbral_amarillo_max))),
    CONSTRAINT chk_semaforo_rango_rojo_coherente CHECK (((umbral_rojo_min IS NULL) OR (umbral_rojo_max IS NULL) OR (umbral_rojo_min <= umbral_rojo_max))),
    CONSTRAINT chk_semaforo_rango_verde_coherente CHECK (((umbral_verde_min IS NULL) OR (umbral_verde_max IS NULL) OR (umbral_verde_min <= umbral_verde_max))),
    CONSTRAINT chk_semaforo_rangos_sin_solapamiento CHECK (((umbral_verde_max IS NULL) OR (umbral_amarillo_min IS NULL) OR (umbral_verde_max < umbral_amarillo_min))),
    CONSTRAINT chk_semaforo_umbrales_positivos CHECK (((COALESCE(umbral_verde_min, (0)::numeric) >= (0)::numeric) AND (COALESCE(umbral_verde_max, (0)::numeric) >= (0)::numeric) AND (COALESCE(umbral_amarillo_min, (0)::numeric) >= (0)::numeric) AND (COALESCE(umbral_amarillo_max, (0)::numeric) >= (0)::numeric) AND (COALESCE(umbral_rojo_min, (0)::numeric) >= (0)::numeric) AND (COALESCE(umbral_rojo_max, (0)::numeric) >= (0)::numeric))),
    CONSTRAINT chk_semaforo_vigencia_no_futura CHECK ((fecha_vigencia <= CURRENT_DATE))
);


ALTER TABLE modulo8.configuraciones_semaforo OWNER TO postgres;

--
-- Name: TABLE configuraciones_semaforo; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON TABLE modulo8.configuraciones_semaforo IS 'Define los umbrales de alerta (semáforo) para cada indicador KPI.
Establece los rangos verde, amarillo y rojo que determinan el estado de salud
de un indicador en función de su valor calculado. Puede aplicarse a nivel
de activo biológico o de infraestructura específica.';


--
-- Name: COLUMN configuraciones_semaforo.id_configuracion_semaforo; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.configuraciones_semaforo.id_configuracion_semaforo IS 'Identificador único de la configuración de semáforo. Clave primaria (serial).';


--
-- Name: COLUMN configuraciones_semaforo.id_indicador_kpi; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.configuraciones_semaforo.id_indicador_kpi IS 'FK hacia modulo8.indicadores_kpi. KPI al que aplica esta configuración de umbrales.';


--
-- Name: COLUMN configuraciones_semaforo.id_activo_biologico; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.configuraciones_semaforo.id_activo_biologico IS 'FK hacia modulo2.activos_biologicos. Permite configurar umbrales específicos
por activo biológico. NULL si la configuración aplica de forma general.';


--
-- Name: COLUMN configuraciones_semaforo.umbral_verde_min; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.configuraciones_semaforo.umbral_verde_min IS 'Valor mínimo del rango verde (estado óptimo/normal) del indicador.';


--
-- Name: COLUMN configuraciones_semaforo.umbral_verde_max; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.configuraciones_semaforo.umbral_verde_max IS 'Valor máximo del rango verde (estado óptimo/normal) del indicador.';


--
-- Name: COLUMN configuraciones_semaforo.umbral_amarillo_min; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.configuraciones_semaforo.umbral_amarillo_min IS 'Valor mínimo del rango amarillo (estado de alerta o atención) del indicador.';


--
-- Name: COLUMN configuraciones_semaforo.umbral_amarillo_max; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.configuraciones_semaforo.umbral_amarillo_max IS 'Valor máximo del rango amarillo (estado de alerta o atención) del indicador.';


--
-- Name: COLUMN configuraciones_semaforo.umbral_rojo_max; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.configuraciones_semaforo.umbral_rojo_max IS 'Valor máximo del rango rojo (estado crítico) del indicador.';


--
-- Name: COLUMN configuraciones_semaforo.umbral_rojo_min; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.configuraciones_semaforo.umbral_rojo_min IS 'Valor mínimo del rango rojo (estado crítico) del indicador.';


--
-- Name: COLUMN configuraciones_semaforo.fecha_vigencia; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.configuraciones_semaforo.fecha_vigencia IS 'Fecha desde la cual esta configuración de umbrales entra en vigencia.
Permite manejar histórico de cambios en los umbrales a lo largo del tiempo.';


--
-- Name: COLUMN configuraciones_semaforo.es_activo; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.configuraciones_semaforo.es_activo IS 'Indica si esta configuración de semáforo está actualmente activa.
Solo la configuración activa se usa para evaluar el estado del KPI.
(Nota: nombre de columna con typo heredado del diseño original.)';


--
-- Name: COLUMN configuraciones_semaforo.id_infraestructura; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.configuraciones_semaforo.id_infraestructura IS 'FK hacia modulo9.infraestructuras. Permite configurar umbrales específicos
por infraestructura. NULL si aplica de forma general o solo por activo biológico.';


--
-- Name: configuraciones_semaforo_id_configuracion_semaforo_seq; Type: SEQUENCE; Schema: modulo8; Owner: postgres
--

CREATE SEQUENCE modulo8.configuraciones_semaforo_id_configuracion_semaforo_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo8.configuraciones_semaforo_id_configuracion_semaforo_seq OWNER TO postgres;

--
-- Name: configuraciones_semaforo_id_configuracion_semaforo_seq; Type: SEQUENCE OWNED BY; Schema: modulo8; Owner: postgres
--

ALTER SEQUENCE modulo8.configuraciones_semaforo_id_configuracion_semaforo_seq OWNED BY modulo8.configuraciones_semaforo.id_configuracion_semaforo;


--
-- Name: consultas_auditoria_externas; Type: TABLE; Schema: modulo8; Owner: postgres
--

CREATE TABLE modulo8.consultas_auditoria_externas (
    id_consulta_auditoria_externa integer NOT NULL,
    id_usuario integer NOT NULL,
    id_auditoria_peticion integer NOT NULL,
    fecha_consulta timestamp with time zone DEFAULT now() NOT NULL,
    ip_origen inet,
    observaciones text,
    CONSTRAINT chk_auditoria_ip_origen_real CHECK (((ip_origen IS NOT NULL) AND (NOT (ip_origen <<= '127.0.0.0/8'::inet)) AND (NOT (ip_origen <<= '::1'::inet)))),
    CONSTRAINT chk_consulta_fecha_no_futura CHECK ((fecha_consulta <= now())),
    CONSTRAINT chk_consulta_observaciones_no_vacias CHECK (((observaciones IS NULL) OR (char_length(TRIM(BOTH FROM observaciones)) > 0)))
);


ALTER TABLE modulo8.consultas_auditoria_externas OWNER TO postgres;

--
-- Name: TABLE consultas_auditoria_externas; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON TABLE modulo8.consultas_auditoria_externas IS 'Registro de las consultas realizadas por usuarios a las auditorías externas del sistema.
Lleva trazabilidad de quién consultó qué auditoría, desde qué IP y en qué momento.
Tiene Row Level Security (RLS) habilitado para controlar el acceso por usuario o rol.';


--
-- Name: COLUMN consultas_auditoria_externas.id_consulta_auditoria_externa; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.consultas_auditoria_externas.id_consulta_auditoria_externa IS 'Identificador único de la consulta de auditoría externa. Clave primaria (serial).';


--
-- Name: COLUMN consultas_auditoria_externas.id_usuario; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.consultas_auditoria_externas.id_usuario IS 'FK hacia modulo1.usuarios. Usuario que realizó la consulta de auditoría.';


--
-- Name: COLUMN consultas_auditoria_externas.id_auditoria_peticion; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.consultas_auditoria_externas.id_auditoria_peticion IS 'FK hacia modulo7.auditoria_peticiones. Registro de auditoría específico que fue consultado.';


--
-- Name: COLUMN consultas_auditoria_externas.fecha_consulta; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.consultas_auditoria_externas.fecha_consulta IS 'Marca temporal (con zona horaria) del momento exacto en que se realizó la consulta.';


--
-- Name: COLUMN consultas_auditoria_externas.ip_origen; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.consultas_auditoria_externas.ip_origen IS 'Dirección IP desde la que se originó la consulta. Tipo inet de PostgreSQL,
soporta IPv4 e IPv6. Útil para auditorías de seguridad.';


--
-- Name: COLUMN consultas_auditoria_externas.observaciones; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.consultas_auditoria_externas.observaciones IS 'Notas adicionales sobre el propósito o resultado de la consulta de auditoría.';


--
-- Name: consultas_auditoria_externas_id_consulta_auditoria_externa_seq; Type: SEQUENCE; Schema: modulo8; Owner: postgres
--

CREATE SEQUENCE modulo8.consultas_auditoria_externas_id_consulta_auditoria_externa_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo8.consultas_auditoria_externas_id_consulta_auditoria_externa_seq OWNER TO postgres;

--
-- Name: consultas_auditoria_externas_id_consulta_auditoria_externa_seq; Type: SEQUENCE OWNED BY; Schema: modulo8; Owner: postgres
--

ALTER SEQUENCE modulo8.consultas_auditoria_externas_id_consulta_auditoria_externa_seq OWNED BY modulo8.consultas_auditoria_externas.id_consulta_auditoria_externa;


--
-- Name: dashboards; Type: TABLE; Schema: modulo8; Owner: postgres
--

CREATE TABLE modulo8.dashboards (
    id_dashboard integer NOT NULL,
    nombre character varying(120) NOT NULL,
    tipo character varying(40) NOT NULL,
    id_usuario integer NOT NULL,
    es_predeterminado boolean DEFAULT false NOT NULL,
    fecha_creacion timestamp with time zone DEFAULT now() NOT NULL,
    estado_sincronizacion modulo8.dashboards_estado_sincronizacion NOT NULL,
    CONSTRAINT chk_dashboard_fecha_no_futura CHECK ((fecha_creacion <= now())),
    CONSTRAINT chk_dashboard_nombre_notempty CHECK ((TRIM(BOTH FROM nombre) <> ''::text)),
    CONSTRAINT chk_dashboard_tipo_no_vacio CHECK ((char_length(TRIM(BOTH FROM tipo)) > 0))
);


ALTER TABLE modulo8.dashboards OWNER TO postgres;

--
-- Name: TABLE dashboards; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON TABLE modulo8.dashboards IS 'Almacena los dashboards personalizados creados por los usuarios del sistema.
Cada dashboard es un espacio visual configurable que agrupa múltiples widgets
para el monitoreo de indicadores, reportes y métricas del negocio.';


--
-- Name: COLUMN dashboards.id_dashboard; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.dashboards.id_dashboard IS 'Identificador único del dashboard. Clave primaria generada automáticamente (serial).';


--
-- Name: COLUMN dashboards.nombre; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.dashboards.nombre IS 'Nombre descriptivo del dashboard asignado por el usuario. Máximo 120 caracteres.';


--
-- Name: COLUMN dashboards.tipo; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.dashboards.tipo IS 'Categoría o tipo funcional del dashboard (ej: OPERATIVO, FINANCIERO, SANITARIO).
Determina el contexto de uso y los widgets disponibles. Máximo 40 caracteres.';


--
-- Name: COLUMN dashboards.id_usuario; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.dashboards.id_usuario IS 'FK hacia modulo1.usuarios. Identifica al usuario propietario del dashboard.';


--
-- Name: COLUMN dashboards.es_predeterminado; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.dashboards.es_predeterminado IS 'Indica si este dashboard es el que se muestra por defecto al usuario al iniciar sesión.
Un usuario solo debería tener un dashboard predeterminado activo a la vez.';


--
-- Name: COLUMN dashboards.fecha_creacion; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.dashboards.fecha_creacion IS 'Marca temporal (con zona horaria) del momento en que se creó el dashboard. Se asigna automáticamente.';


--
-- Name: COLUMN dashboards.estado_sincronizacion; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.dashboards.estado_sincronizacion IS 'Estado actual de la sincronización del dashboard con las fuentes de datos.
Tipo ENUM definido en el esquema modulo8 (ej: SINCRONIZADO, PENDIENTE, ERROR).';


--
-- Name: dashboards_id_dashboard_seq; Type: SEQUENCE; Schema: modulo8; Owner: postgres
--

CREATE SEQUENCE modulo8.dashboards_id_dashboard_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo8.dashboards_id_dashboard_seq OWNER TO postgres;

--
-- Name: dashboards_id_dashboard_seq; Type: SEQUENCE OWNED BY; Schema: modulo8; Owner: postgres
--

ALTER SEQUENCE modulo8.dashboards_id_dashboard_seq OWNED BY modulo8.dashboards.id_dashboard;


--
-- Name: historiales_clinicos; Type: TABLE; Schema: modulo8; Owner: postgres
--

CREATE TABLE modulo8.historiales_clinicos (
    id_historial_clinicos integer NOT NULL,
    id_activo_biologico integer NOT NULL,
    procentaje_probabilidad numeric(5,2) NOT NULL,
    nivel_riesgo character varying(20),
    observaciones text,
    fecha_registro timestamp with time zone DEFAULT now() NOT NULL,
    modo_visualizacion modulo8.historiales_clinicos_predictivos_modo_visualizacion DEFAULT 'LINEAL'::modulo8.historiales_clinicos_predictivos_modo_visualizacion,
    total_eventos_sanitarios integer DEFAULT 0,
    fecha_inicio date NOT NULL,
    fecha_fin date NOT NULL,
    tvco_porcentaje numeric(5,2),
    CONSTRAINT check_fecha_historial_clinicos CHECK ((fecha_fin >= fecha_inicio)),
    CONSTRAINT checlk_tvco_porcentaje CHECK (((tvco_porcentaje >= (0)::numeric) AND (tvco_porcentaje <= (100)::numeric))),
    CONSTRAINT chk_historial_fechas_orden CHECK ((fecha_fin >= fecha_inicio)),
    CONSTRAINT chk_historial_nivel_riesgo_valido CHECK (((nivel_riesgo IS NULL) OR ((nivel_riesgo)::text = ANY (ARRAY[('BAJO'::character varying)::text, ('MEDIO'::character varying)::text, ('ALTO'::character varying)::text])))),
    CONSTRAINT chk_historial_probabilidad_rango CHECK (((procentaje_probabilidad >= 0.00) AND (procentaje_probabilidad <= 100.00))),
    CONSTRAINT chk_historial_rango_max_24_meses CHECK (((fecha_fin - fecha_inicio) <= 730)),
    CONSTRAINT chk_historial_registro_no_futuro CHECK ((fecha_registro <= now())),
    CONSTRAINT chk_historial_riesgo_eventos_coherente CHECK ((((nivel_riesgo)::text <> 'ALTO'::text) OR (total_eventos_sanitarios >= 0))),
    CONSTRAINT chk_historial_total_eventos_positivo CHECK ((total_eventos_sanitarios >= 0)),
    CONSTRAINT chk_historial_tvco_rango CHECK (((tvco_porcentaje IS NULL) OR ((tvco_porcentaje >= 0.00) AND (tvco_porcentaje <= 100.00))))
);


ALTER TABLE modulo8.historiales_clinicos OWNER TO postgres;

--
-- Name: TABLE historiales_clinicos; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON TABLE modulo8.historiales_clinicos IS 'Almacena el historial clínico predictivo de los activos biológicos.
Registra la evaluación de riesgo sanitario de un activo en un período de tiempo,
incluyendo la probabilidad calculada de eventos adversos, el nivel de riesgo
clasificado y métricas como la tasa de variación (TVCO).';


--
-- Name: COLUMN historiales_clinicos.id_historial_clinicos; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.historiales_clinicos.id_historial_clinicos IS 'Identificador único del registro de historial clínico. Clave primaria (serial).';


--
-- Name: COLUMN historiales_clinicos.id_activo_biologico; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.historiales_clinicos.id_activo_biologico IS 'FK hacia modulo2.activos_biologicos. Activo biológico al que pertenece este historial.';


--
-- Name: COLUMN historiales_clinicos.procentaje_probabilidad; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.historiales_clinicos.procentaje_probabilidad IS 'Porcentaje de probabilidad de ocurrencia de un evento sanitario adverso,
calculado por el modelo predictivo. Valor entre 0.00 y 100.00.';


--
-- Name: COLUMN historiales_clinicos.nivel_riesgo; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.historiales_clinicos.nivel_riesgo IS 'Clasificación del nivel de riesgo derivada del porcentaje de probabilidad
(ej: BAJO, MEDIO, ALTO, CRÍTICO). Máximo 20 caracteres.';


--
-- Name: COLUMN historiales_clinicos.observaciones; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.historiales_clinicos.observaciones IS 'Notas clínicas o comentarios adicionales del evaluador o del sistema
sobre la condición sanitaria del activo en el período analizado.';


--
-- Name: COLUMN historiales_clinicos.fecha_registro; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.historiales_clinicos.fecha_registro IS 'Marca temporal (con zona horaria) del momento en que se registró la evaluación.';


--
-- Name: COLUMN historiales_clinicos.modo_visualizacion; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.historiales_clinicos.modo_visualizacion IS 'Modo gráfico sugerido para visualizar la evolución del historial en el dashboard.
ENUM definido en modulo8 (ej: LINEAL, BARRAS, TABLA).';


--
-- Name: COLUMN historiales_clinicos.total_eventos_sanitarios; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.historiales_clinicos.total_eventos_sanitarios IS 'Contador acumulado de eventos sanitarios registrados para el activo
dentro del período definido por fecha_inicio y fecha_fin.';


--
-- Name: COLUMN historiales_clinicos.fecha_inicio; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.historiales_clinicos.fecha_inicio IS 'Fecha de inicio del período de análisis clínico evaluado en este registro.';


--
-- Name: COLUMN historiales_clinicos.fecha_fin; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.historiales_clinicos.fecha_fin IS 'Fecha de fin del período de análisis clínico evaluado en este registro.';


--
-- Name: COLUMN historiales_clinicos.tvco_porcentaje; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.historiales_clinicos.tvco_porcentaje IS 'Tasa de Variación en Condición Operativa (TVCO) expresada como porcentaje.
Mide el cambio relativo en la condición del activo respecto a un período base.';


--
-- Name: historiales_clinicos_id_historial_clinicos_seq; Type: SEQUENCE; Schema: modulo8; Owner: postgres
--

CREATE SEQUENCE modulo8.historiales_clinicos_id_historial_clinicos_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo8.historiales_clinicos_id_historial_clinicos_seq OWNER TO postgres;

--
-- Name: historiales_clinicos_id_historial_clinicos_seq; Type: SEQUENCE OWNED BY; Schema: modulo8; Owner: postgres
--

ALTER SEQUENCE modulo8.historiales_clinicos_id_historial_clinicos_seq OWNED BY modulo8.historiales_clinicos.id_historial_clinicos;


--
-- Name: indicadores_kpi; Type: TABLE; Schema: modulo8; Owner: postgres
--

CREATE TABLE modulo8.indicadores_kpi (
    id_indicador_kpi integer NOT NULL,
    codigo character varying(50) NOT NULL,
    descripcion text,
    categoria character varying(40) NOT NULL,
    unidad_medida character varying(40),
    modulo_origen modulo8.indicadores_kpi_modulo_origen DEFAULT 'MODULO4'::modulo8.indicadores_kpi_modulo_origen NOT NULL,
    formula text,
    es_critico boolean DEFAULT false NOT NULL,
    fecha_creacion timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_kpi_categoria_valida CHECK (((categoria)::text = ANY (ARRAY[('PRODUCTIVO'::character varying)::text, ('SANITARIO'::character varying)::text, ('FINANCIERO'::character varying)::text, ('AMBIENTAL'::character varying)::text, ('IOT'::character varying)::text]))),
    CONSTRAINT chk_kpi_codigo_notempty CHECK (((TRIM(BOTH FROM codigo) <> ''::text) AND (length((codigo)::text) >= 3))),
    CONSTRAINT chk_kpi_formula_no_vacia CHECK (((formula IS NULL) OR (char_length(TRIM(BOTH FROM formula)) > 0))),
    CONSTRAINT chk_kpi_unidad_no_vacia CHECK (((unidad_medida IS NULL) OR (char_length(TRIM(BOTH FROM unidad_medida)) > 0)))
);


ALTER TABLE modulo8.indicadores_kpi OWNER TO postgres;

--
-- Name: TABLE indicadores_kpi; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON TABLE modulo8.indicadores_kpi IS 'Catálogo maestro de Indicadores Clave de Rendimiento (KPI) del sistema.
Define qué se mide, cómo se calcula y desde qué módulo proviene cada indicador.
Es la tabla de referencia para configurar semáforos y calcular snapshots.';


--
-- Name: COLUMN indicadores_kpi.id_indicador_kpi; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.indicadores_kpi.id_indicador_kpi IS 'Identificador único del indicador KPI. Clave primaria (serial).';


--
-- Name: COLUMN indicadores_kpi.codigo; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.indicadores_kpi.codigo IS 'Código único e irrepetible del indicador (ej: KPI_MORT_001, KPI_PROD_003).
Usado como referencia técnica en fórmulas e integraciones. Máximo 50 caracteres.';


--
-- Name: COLUMN indicadores_kpi.descripcion; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.indicadores_kpi.descripcion IS 'Explicación detallada del indicador: qué mide, su relevancia para el negocio
y cómo debe interpretarse su resultado.';


--
-- Name: COLUMN indicadores_kpi.categoria; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.indicadores_kpi.categoria IS 'Agrupación temática del indicador (ej: SANITARIO, PRODUCTIVO, FINANCIERO, AMBIENTAL).
Permite filtrar y organizar los KPIs en los dashboards. Máximo 40 caracteres.';


--
-- Name: COLUMN indicadores_kpi.unidad_medida; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.indicadores_kpi.unidad_medida IS 'Unidad en la que se expresa el valor del indicador (ej: %, kg, cabezas, COP).
Puede ser nulo para indicadores adimensionales. Máximo 40 caracteres.';


--
-- Name: COLUMN indicadores_kpi.modulo_origen; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.indicadores_kpi.modulo_origen IS 'Módulo del sistema que genera o alimenta los datos de este KPI.
ENUM definido en modulo8. Por defecto apunta a MODULO4.';


--
-- Name: COLUMN indicadores_kpi.formula; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.indicadores_kpi.formula IS 'Expresión o descripción de la fórmula de cálculo del indicador.
Puede ser pseudocódigo, SQL o una descripción matemática del cálculo.';


--
-- Name: COLUMN indicadores_kpi.es_critico; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.indicadores_kpi.es_critico IS 'Indica si el indicador es crítico para la operación del negocio.
Los KPIs críticos generan alertas prioritarias cuando entran en zona roja.';


--
-- Name: COLUMN indicadores_kpi.fecha_creacion; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.indicadores_kpi.fecha_creacion IS 'Marca temporal (con zona horaria) del momento en que se registró el KPI en el sistema.';


--
-- Name: indicadores_kpi_id_indicador_kpi_seq; Type: SEQUENCE; Schema: modulo8; Owner: postgres
--

CREATE SEQUENCE modulo8.indicadores_kpi_id_indicador_kpi_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo8.indicadores_kpi_id_indicador_kpi_seq OWNER TO postgres;

--
-- Name: indicadores_kpi_id_indicador_kpi_seq; Type: SEQUENCE OWNED BY; Schema: modulo8; Owner: postgres
--

ALTER SEQUENCE modulo8.indicadores_kpi_id_indicador_kpi_seq OWNED BY modulo8.indicadores_kpi.id_indicador_kpi;


--
-- Name: preferencias_visualizacion; Type: TABLE; Schema: modulo8; Owner: postgres
--

CREATE TABLE modulo8.preferencias_visualizacion (
    id_preferencia_visualizacion integer NOT NULL,
    id_usuario integer NOT NULL,
    idioma character varying(20),
    tamano_fuente character varying(20),
    modo_accesebilidad boolean DEFAULT false NOT NULL,
    mostrar_tooltips boolean DEFAULT true NOT NULL,
    fecha_actualizacion timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_preferencia_idioma_no_vacio CHECK (((idioma IS NULL) OR (char_length(TRIM(BOTH FROM idioma)) > 0)))
);


ALTER TABLE modulo8.preferencias_visualizacion OWNER TO postgres;

--
-- Name: TABLE preferencias_visualizacion; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON TABLE modulo8.preferencias_visualizacion IS 'Almacena la configuración de experiencia visual personalizada de cada usuario.
Permite adaptar la interfaz en cuanto a idioma, tipografía y accesibilidad,
garantizando una experiencia consistente entre sesiones.';


--
-- Name: COLUMN preferencias_visualizacion.id_preferencia_visualizacion; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.preferencias_visualizacion.id_preferencia_visualizacion IS 'Identificador único de las preferencias de visualización. Clave primaria (serial).';


--
-- Name: COLUMN preferencias_visualizacion.id_usuario; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.preferencias_visualizacion.id_usuario IS 'FK hacia modulo1.usuarios. Usuario al que pertenecen estas preferencias.';


--
-- Name: COLUMN preferencias_visualizacion.idioma; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.preferencias_visualizacion.idioma IS 'Idioma preferido por el usuario para la interfaz del sistema (ej: es-CO, en-US).
Máximo 20 caracteres.';


--
-- Name: COLUMN preferencias_visualizacion.tamano_fuente; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.preferencias_visualizacion.tamano_fuente IS 'Tamaño de fuente preferido por el usuario (ej: PEQUEÑO, MEDIANO, GRANDE).
Máximo 20 caracteres.';


--
-- Name: COLUMN preferencias_visualizacion.modo_accesebilidad; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.preferencias_visualizacion.modo_accesebilidad IS 'Indica si el usuario tiene activado el modo de accesibilidad, que puede incluir
alto contraste, lectores de pantalla u otras adaptaciones visuales.';


--
