--
-- Name: reportes_financieros; Type: TABLE; Schema: modulo8; Owner: postgres
--

CREATE TABLE modulo8.reportes_financieros (
    id_reporte_financiero integer NOT NULL,
    id_usuario integer NOT NULL,
    id_periodo_contable integer NOT NULL,
    tipo_reporte character varying(40) NOT NULL,
    formato character varying(20) NOT NULL,
    ruta_archivo text NOT NULL,
    sha256_archivo character varying(64),
    fecha_generacion timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_reporte_fin_fecha_no_futura CHECK ((fecha_generacion <= now())),
    CONSTRAINT chk_reporte_fin_formato_no_vacio CHECK ((char_length(TRIM(BOTH FROM formato)) > 0)),
    CONSTRAINT chk_reporte_fin_tipo_no_vacio CHECK ((char_length(TRIM(BOTH FROM tipo_reporte)) > 0)),
    CONSTRAINT chk_reporte_financiero_ruta_notempty CHECK ((TRIM(BOTH FROM ruta_archivo) <> ''::text)),
    CONSTRAINT chk_reporte_financiero_sha256_formato CHECK (((sha256_archivo IS NULL) OR ((sha256_archivo)::text ~ '^[a-f0-9]{64}$'::text)))
);


ALTER TABLE modulo8.reportes_financieros OWNER TO postgres;

--
-- Name: TABLE reportes_financieros; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON TABLE modulo8.reportes_financieros IS 'Registro de los reportes financieros generados por el sistema.
Cada fila representa un archivo de reporte producido para un período contable
específico, con su ruta de almacenamiento y metadatos de integridad.';


--
-- Name: COLUMN reportes_financieros.id_reporte_financiero; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.reportes_financieros.id_reporte_financiero IS 'Identificador único del reporte financiero. Clave primaria (serial).';


--
-- Name: COLUMN reportes_financieros.id_usuario; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.reportes_financieros.id_usuario IS 'FK hacia modulo1.usuarios. Usuario que solicitó o generó el reporte.';


--
-- Name: COLUMN reportes_financieros.id_periodo_contable; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.reportes_financieros.id_periodo_contable IS 'FK hacia modulo6.periodos_contables. Período contable al que corresponden
los datos del reporte generado.';


--
-- Name: COLUMN reportes_financieros.tipo_reporte; Type: COMMENT; Schema: modulo8; Owner: postgres
