COMMENT ON COLUMN modulo8.reportes_financieros.tipo_reporte IS 'Tipo o plantilla del reporte financiero generado (ej: BALANCE_GENERAL,
ESTADO_RESULTADOS, FLUJO_CAJA). Máximo 40 caracteres.';


--
-- Name: COLUMN reportes_financieros.formato; Type: COMMENT; Schema: modulo8; Owner: postgres
