--
-- Name: reportes_regulatorios; Type: TABLE; Schema: modulo8; Owner: postgres
--

CREATE TABLE modulo8.reportes_regulatorios (
    id_reporte_regulatorio integer NOT NULL,
    id_usuario integer NOT NULL,
    formato modulo8.reportes_regulatorios_formato NOT NULL,
    ruta_archivo text,
    fecha_generacion timestamp with time zone DEFAULT now() NOT NULL,
    estado modulo8.reportes_regulatorios_estado DEFAULT 'EN_PROCESO'::modulo8.reportes_regulatorios_estado NOT NULL,
    id_finca integer NOT NULL,
    tipo_reporte modulo8.reportes_regulatorios_tipo NOT NULL,
    id_periodo_contable integer NOT NULL,
    id_activo_biologico integer NOT NULL,
    tamano_archivo_kb integer,
    tipo character varying(40),
    CONSTRAINT chk_reporte_reg_fecha_no_futura CHECK ((fecha_generacion <= now())),
    CONSTRAINT chk_reporte_reg_ruta_cuando_generado CHECK (((estado <> 'GENERADO'::modulo8.reportes_regulatorios_estado) OR (ruta_archivo IS NOT NULL))),
    CONSTRAINT chk_reporte_reg_tamano_max_50mb CHECK (((tamano_archivo_kb IS NULL) OR ((tamano_archivo_kb > 0) AND (tamano_archivo_kb <= 51200)))),
    CONSTRAINT chk_reporte_reg_tamano_positivo CHECK (((tamano_archivo_kb IS NULL) OR (tamano_archivo_kb > 0))),
    CONSTRAINT chk_reporte_reg_tipo_ente_valido CHECK (((tipo)::text = ANY (ARRAY[('ICA'::character varying)::text, ('UPRA'::character varying)::text, ('BANCO_AGRARIO'::character varying)::text, ('SIGCON'::character varying)::text, ('INTERNO'::character varying)::text])))
);


ALTER TABLE modulo8.reportes_regulatorios OWNER TO postgres;

--
-- Name: TABLE reportes_regulatorios; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON TABLE modulo8.reportes_regulatorios IS 'Gestiona los reportes exigidos por organismos regulatorios (ICA, INVIMA, etc.)
en materia sanitaria, productiva o ambiental. Registra el estado de generación,
el archivo resultante y las entidades relacionadas (finca, activo, período).';


--
