--
-- Name: snapshots_kpi; Type: TABLE; Schema: modulo8; Owner: postgres
--

CREATE TABLE modulo8.snapshots_kpi (
    id_snapshot_kpi integer NOT NULL,
    id_indicador_kpi integer NOT NULL,
    id_activo_biologico integer NOT NULL,
    id_infraestructura integer NOT NULL,
    estado_semaforo modulo8.snapshots_kpi_estado_semaforo NOT NULL,
    fecha_calculo timestamp with time zone NOT NULL,
    metadatos jsonb,
    CONSTRAINT chk_snapshot_fecha_calculo_no_futura CHECK ((fecha_calculo <= now()))
);


ALTER TABLE modulo8.snapshots_kpi OWNER TO postgres;

--
-- Name: TABLE snapshots_kpi; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON TABLE modulo8.snapshots_kpi IS 'Registro histórico de los valores calculados de los KPIs en momentos específicos.
Cada fila representa una "fotografía" del estado de un indicador en una fecha dada,
asociada a un activo biológico y una infraestructura. Permite análisis de tendencias
y comparación histórica de rendimiento.';


--
-- Name: COLUMN snapshots_kpi.id_snapshot_kpi; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.snapshots_kpi.id_snapshot_kpi IS 'Identificador único del snapshot de KPI. Clave primaria (serial).';


--
-- Name: COLUMN snapshots_kpi.id_indicador_kpi; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.snapshots_kpi.id_indicador_kpi IS 'FK hacia modulo8.indicadores_kpi. KPI que fue calculado en este snapshot.';


--
-- Name: COLUMN snapshots_kpi.id_activo_biologico; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.snapshots_kpi.id_activo_biologico IS 'FK hacia modulo2.activos_biologicos. Activo al que corresponde el valor calculado.';


--
-- Name: COLUMN snapshots_kpi.id_infraestructura; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.snapshots_kpi.id_infraestructura IS 'FK hacia modulo9.infraestructuras. Infraestructura donde se encontraba el activo
al momento del cálculo del KPI.';


--
-- Name: COLUMN snapshots_kpi.estado_semaforo; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.snapshots_kpi.estado_semaforo IS 'Estado resultante del KPI según los umbrales configurados al momento del cálculo.
ENUM definido en modulo8 (ej: VERDE, AMARILLO, ROJO).';


--
-- Name: COLUMN snapshots_kpi.fecha_calculo; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.snapshots_kpi.fecha_calculo IS 'Marca temporal exacta (con zona horaria) en que se calculó y registró el snapshot.';


--
-- Name: COLUMN snapshots_kpi.metadatos; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.snapshots_kpi.metadatos IS 'Objeto JSON con información adicional del cálculo: valores intermedios,
parámetros usados en la fórmula, fuentes de datos consultadas, etc.';


--
-- Name: snapshots_kpi_id_snapshot_kpi_seq; Type: SEQUENCE; Schema: modulo8; Owner: postgres
