--
-- Name: vw_dashboard_activos_riesgo_alto; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_dashboard_activos_riesgo_alto AS
 SELECT ab.identificador AS activo_id,
    e.nombre AS especie,
    rrc.nivel_riesgo_contagio AS nivel_riesgo,
    round(((rrc.probabilidad_contagio)::numeric * (100)::numeric), 2) AS probabilidad_pct,
    rrc.fecha_calculo
   FROM ((modulo4.resultados_riesgo_contagio rrc
     JOIN modulo2.activos_biologicos ab ON ((rrc.id_activo_biologico = ab.id_activo_biologico)))
     JOIN modulo9.especies e ON ((ab.id_especie = e.id_especie)))
  WHERE (rrc.nivel_riesgo_contagio >= 8)
  ORDER BY rrc.probabilidad_contagio DESC;


ALTER VIEW modulo8.vw_dashboard_activos_riesgo_alto OWNER TO postgres;

--
-- Name: vw_dashboard_alertas_activas; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_dashboard_alertas_activas AS
 SELECT count(*) AS total_alertas,
    count(*) FILTER (WHERE (severidad = 'CRITICO'::modulo3.enum_buffer_nivel_severidad)) AS alertas_rojo,
    count(*) FILTER (WHERE (severidad = 'MODERADO'::modulo3.enum_buffer_nivel_severidad)) AS alertas_amarillo,
    count(*) FILTER (WHERE (severidad = 'LEVE'::modulo3.enum_buffer_nivel_severidad)) AS alertas_verde
   FROM modulo3.alertas
  WHERE (estado_alerta = 'ACTIVA'::modulo3.enum_estado_alerta);


ALTER VIEW modulo8.vw_dashboard_alertas_activas OWNER TO postgres;

--
-- Name: vw_dashboard_alertas_patologicas_activas; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_dashboard_alertas_patologicas_activas AS
 SELECT ap.id_alerta_patologica,
    ab.identificador AS activo_id,
    p.nombre AS patologia,
    ap.nivel_criticidad,
    ap.probabilidad_pct,
    ap.fecha_generacion
   FROM ((modulo4.alertas_patologicas ap
     JOIN modulo2.activos_biologicos ab ON ((ap.id_activo_biologico = ab.id_activo_biologico)))
     JOIN modulo9.patologias p ON ((ap.id_patologia = p.id_patologia)))
  WHERE (ap.estado_alerta = 'PENDIENTE'::modulo4.enum_alerta_patologia_estado)
  ORDER BY ap.probabilidad_pct DESC;


ALTER VIEW modulo8.vw_dashboard_alertas_patologicas_activas OWNER TO postgres;

--
-- Name: vw_dashboard_conversion_alimenticia; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_dashboard_conversion_alimenticia AS
 SELECT ca_calculado AS ratio_kg_kg,
    clasificacion_ca AS estado,
    fecha_fin_periodo
   FROM modulo5.resultado_ica
  ORDER BY fecha_fin_periodo DESC
 LIMIT 1;


ALTER VIEW modulo8.vw_dashboard_conversion_alimenticia OWNER TO postgres;

--
-- Name: vw_dashboard_dispositivos_iot_estado; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_dashboard_dispositivos_iot_estado AS
 SELECT d.id_dispositivo_iot,
    d.serial AS dispositivo,
    i.nombre AS lugar,
    edi.estado_actual AS estado,
    edi.fecha_ultimo_contacto AS ult_lectura
   FROM ((((modulo9.dispositivos_iot d
     JOIN modulo3.estados_dispositivos_iot edi ON ((d.id_dispositivo_iot = edi.id_dispositivo_iot)))
     LEFT JOIN modulo9.sensores s ON ((d.id_dispositivo_iot = s.id_dispositivo_iot)))
     LEFT JOIN modulo9.sensores_areas_asociadas saa ON ((s.id_sensores = saa.id_sensor)))
     LEFT JOIN modulo9.infraestructuras i ON ((saa.id_infraestructura = i.id_infraestructura)))
  GROUP BY d.id_dispositivo_iot, d.serial, i.nombre, edi.estado_actual, edi.fecha_ultimo_contacto;


ALTER VIEW modulo8.vw_dashboard_dispositivos_iot_estado OWNER TO postgres;

--
-- Name: vw_dashboard_dispositivos_sin_heartbeat; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_dashboard_dispositivos_sin_heartbeat AS
 SELECT d.id_dispositivo_iot,
    d.serial,
    max(h.fecha_registro) AS ultimo_hearbeat
   FROM (modulo9.dispositivos_iot d
     LEFT JOIN modulo3.heartbeats h ON ((d.id_dispositivo_iot = h.id_dispositivo_iot)))
  GROUP BY d.id_dispositivo_iot, d.serial
 HAVING ((max(h.fecha_registro) IS NULL) OR (max(h.fecha_registro) < (CURRENT_TIMESTAMP - '00:10:00'::interval)));


ALTER VIEW modulo8.vw_dashboard_dispositivos_sin_heartbeat OWNER TO postgres;

--
-- Name: vw_dashboard_distribucion_probabilidad; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_dashboard_distribucion_probabilidad AS
 SELECT count(*) FILTER (WHERE (nivel_riesgo >= 8)) AS alta,
    count(*) FILTER (WHERE ((nivel_riesgo >= 5) AND (nivel_riesgo <= 7))) AS media,
    count(*) FILTER (WHERE (nivel_riesgo < 5)) AS baja
   FROM modulo4.resultados_inferencia
  WHERE (fecha_inferencia >= (CURRENT_DATE - '30 days'::interval));


ALTER VIEW modulo8.vw_dashboard_distribucion_probabilidad OWNER TO postgres;

--
-- Name: vw_dashboard_exportaciones_sigcon; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_dashboard_exportaciones_sigcon AS
 SELECT id_integracion_solicitud AS exportacion_id,
    estado,
        CASE
            WHEN (id_error IS NOT NULL) THEN 1
            ELSE 0
        END AS reintentos,
    fecha_comienzoo,
    fecha_finalizacion
   FROM modulo7.integraciones_solicitudes
  ORDER BY fecha_comienzoo DESC
 LIMIT 10;


ALTER VIEW modulo8.vw_dashboard_exportaciones_sigcon OWNER TO postgres;

--
-- Name: vw_dashboard_inventario_biologico; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_dashboard_inventario_biologico AS
 SELECT e.nombre AS especie,
    count(*) FILTER (WHERE (((ea.nombre)::text ~~* '%activo%'::text) OR ((ea.nombre)::text ~~* '%vivo%'::text))) AS activos,
    count(*) FILTER (WHERE ((ea.nombre)::text ~~* '%tratamiento%'::text)) AS en_tratamiento,
    count(*) FILTER (WHERE (((ea.nombre)::text ~~* '%baja%'::text) OR ((ea.nombre)::text ~~* '%muerto%'::text) OR ((ea.nombre)::text ~~* '%fa%'::text))) AS bajas
   FROM ((modulo2.activos_biologicos ab
     JOIN modulo2.estados_activos_biologicos ea ON ((ab.id_estado = ea.id_estado_activo_biologico)))
     JOIN modulo9.especies e ON ((ab.id_especie = e.id_especie)))
  WHERE (e.es_activo = true)
  GROUP BY e.nombre;


ALTER VIEW modulo8.vw_dashboard_inventario_biologico OWNER TO postgres;

--
-- Name: vw_dashboard_lecturas_tiempo_real; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_dashboard_lecturas_tiempo_real AS
 WITH ultimos_datos AS (
         SELECT telemetrias.id_sensor,
            telemetrias.id_variable,
            telemetrias.valor_ajustado,
            telemetrias.estado_calidad,
            row_number() OVER (PARTITION BY telemetrias.id_sensor ORDER BY telemetrias.timestamp_captura DESC) AS rn
           FROM modulo3.telemetrias
        )
 SELECT s.nombre AS sensor,
    va.nombre AS tipo,
    ud.valor_ajustado AS valor,
    ud.estado_calidad AS estado
   FROM ((ultimos_datos ud
     JOIN modulo9.sensores s ON ((ud.id_sensor = s.id_sensores)))
     JOIN modulo9.variables_ambientales va ON ((ud.id_variable = va.id_variable_ambiental)))
  WHERE (ud.rn = 1);


ALTER VIEW modulo8.vw_dashboard_lecturas_tiempo_real OWNER TO postgres;

--
-- Name: vw_dashboard_periodos_contables; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_dashboard_periodos_contables AS
 SELECT id_periodo_contable,
    fecha_inicio AS apertura,
    fecha_fin AS cierre,
    estado,
    fecha_cierre
   FROM modulo6.periodos_contables
  ORDER BY fecha_inicio DESC
 LIMIT 5;


ALTER VIEW modulo8.vw_dashboard_periodos_contables OWNER TO postgres;

--
-- Name: vw_dashboard_precios_proximos_vencer; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_dashboard_precios_proximos_vencer AS
 SELECT pm.id_precio_mercado,
    e.nombre AS especie,
    pm.precio_unitario,
    pm.unidad_medida,
    pm.fecha_vencimiento
   FROM (modulo6.precios_mercado pm
     JOIN modulo9.especies e ON ((pm.id_especie = e.id_especie)))
  WHERE ((pm.fecha_vencimiento IS NOT NULL) AND (pm.fecha_vencimiento <= (CURRENT_DATE + '30 days'::interval)) AND (pm.estado = 'ACTIVO'::modulo6.enum_precio_mercado_estado))
  ORDER BY pm.fecha_vencimiento;


ALTER VIEW modulo8.vw_dashboard_precios_proximos_vencer OWNER TO postgres;

--
-- Name: vw_dashboard_reconocimientos_pendientes; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_dashboard_reconocimientos_pendientes AS
 SELECT count(*) AS pendientes
   FROM modulo6.reconocimientos_iniciales
  WHERE (estado = 'PENDIENTE_CONFIRMACION'::modulo6.enum_reconocimientos_iniciales_estado_reconocimiento);


ALTER VIEW modulo8.vw_dashboard_reconocimientos_pendientes OWNER TO postgres;

--
-- Name: vw_dashboard_retroalimentaciones_pendientes; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_dashboard_retroalimentaciones_pendientes AS
 SELECT count(*) AS pendientes,
    min(rf.fecha_registro) AS antiguedad_minima
   FROM (modulo8.retroalimentacion_feedback rf
     JOIN modulo8.historiales_clinicos hc ON ((rf.id_historial_clinico = hc.id_historial_clinicos)))
  WHERE ((rf.estado = 'PARCIAL'::modulo8.retroalimentacion_feedback_estado) AND (rf.fecha_registro < (CURRENT_TIMESTAMP - '48:00:00'::interval)));


ALTER VIEW modulo8.vw_dashboard_retroalimentaciones_pendientes OWNER TO postgres;

--
-- Name: vw_dashboard_telemetria_ambiental; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_dashboard_telemetria_ambiental AS
 WITH lecturas_recientes AS (
         SELECT t.id_variable,
            vl.id_infraestructura,
            t.valor_ajustado,
            t.estado_calidad,
            row_number() OVER (PARTITION BY t.id_variable, vl.id_infraestructura ORDER BY t.timestamp_captura DESC) AS rn
           FROM (modulo3.telemetrias t
             JOIN modulo3.vinculaciones_lecturas vl ON ((t.id_telemetria = vl.id_telemetria)))
          WHERE (t.estado_calidad = 'LECTURA_VALIDA'::modulo3.enum_telemetria_estado_calidad)
        )
 SELECT i.nombre AS lugar,
    max(
        CASE
            WHEN ((va.nombre)::text ~~* '%temperatura%'::text) THEN lr.valor_ajustado
            ELSE NULL::numeric
        END) AS temp_c,
    max(
        CASE
            WHEN (((va.nombre)::text ~~* '%humedad%'::text) OR ((va.nombre)::text ~~* '%hr%'::text)) THEN lr.valor_ajustado
            ELSE NULL::numeric
        END) AS humedad_pct,
        CASE
            WHEN (count(*) > 0) THEN 'OK'::text
            ELSE 'SIN DATOS'::text
        END AS estado
   FROM ((lecturas_recientes lr
     JOIN modulo9.infraestructuras i ON ((lr.id_infraestructura = i.id_infraestructura)))
     JOIN modulo9.variables_ambientales va ON ((lr.id_variable = va.id_variable_ambiental)))
  WHERE (lr.rn = 1)
  GROUP BY i.nombre;


ALTER VIEW modulo8.vw_dashboard_telemetria_ambiental OWNER TO postgres;

--
-- Name: vw_dashboard_valor_inventario; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_dashboard_valor_inventario AS
 SELECT COALESCE(sum(cv.valor_neto), (0)::numeric) AS valor_razonable,
    COALESCE(sum(vc.valor_contable_por_costo), (0)::numeric) AS valor_costo,
    (COALESCE(sum(cv.valor_neto), (0)::numeric) + COALESCE(sum(vc.valor_contable_por_costo), (0)::numeric)) AS valor_total_cop,
    CURRENT_DATE AS fecha_valoracion
   FROM ((modulo2.activos_biologicos ab
     LEFT JOIN modulo6.calculos_valor_razonable cv ON (((ab.id_activo_biologico = cv.id_activo_biologico) AND (cv.estado = 'CALCULADO'::modulo6.enum_calculos_valor_razonable_estado))))
     LEFT JOIN modulo6.valoraciones_por_costos vc ON (((ab.id_activo_biologico = vc.id_activo_biologico) AND (vc.es_activa = true))));


ALTER VIEW modulo8.vw_dashboard_valor_inventario OWNER TO postgres;

--
-- Name: vw_historial_predictivo_activo; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_historial_predictivo_activo AS
 SELECT id_historial_clinicos,
    id_activo_biologico,
    procentaje_probabilidad,
    nivel_riesgo,
    fecha_inicio,
    fecha_fin,
    modo_visualizacion
   FROM modulo8.historiales_clinicos hc;


ALTER VIEW modulo8.vw_historial_predictivo_activo OWNER TO postgres;

--
-- Name: vw_linea_tiempo_predictiva; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_linea_tiempo_predictiva AS
 SELECT 'PREDICCION'::text AS tipo_evento,
    (r.id_resultado_inferencia)::text AS id_referencia,
    r.id_activo_biologico,
    r.nivel_riesgo,
    r.probabilidad_riesgo,
    r.fecha_inferencia AS fecha,
    NULL::text AS observaciones
   FROM modulo4.resultados_inferencia r
UNION ALL
 SELECT 'EVENTO_SANITARIO'::text AS tipo_evento,
    (es.id_evento)::text AS id_referencia,
    ab.id_activo_biologico,
    0 AS nivel_riesgo,
    NULL::jsonb AS probabilidad_riesgo,
    ea.fecha,
    ea.descripcion AS observaciones
   FROM ((modulo2.eventos_sanitarios es
     JOIN modulo2.eventos_activos ea ON ((es.id_evento = ea.id_eventos)))
     JOIN modulo2.activos_biologicos ab ON ((ea.id_activo_biologico = ab.id_activo_biologico)))
  ORDER BY 6 DESC;


ALTER VIEW modulo8.vw_linea_tiempo_predictiva OWNER TO postgres;

--
-- Name: vw_metricas_validacion_predictiva; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_metricas_validacion_predictiva AS
 SELECT count(*) AS total_retroalimentaciones,
    count(*) FILTER (WHERE (((estado_registro)::text = 'ACTIVO'::text) AND (NOT es_conflicto_retroalimentacion))) AS validadas_clinicamente,
    round((((count(*) FILTER (WHERE (((estado_registro)::text = 'ACTIVO'::text) AND (NOT es_conflicto_retroalimentacion))))::numeric / (NULLIF(count(*), 0))::numeric) * (100)::numeric), 2) AS tasa_validacion_pct
   FROM modulo4.retroalimentaciones_clinicas;


ALTER VIEW modulo8.vw_metricas_validacion_predictiva OWNER TO postgres;

--
-- Name: vw_retroalimentaciones_contradictorias; Type: VIEW; Schema: modulo8; Owner: postgres
--

CREATE VIEW modulo8.vw_retroalimentaciones_contradictorias AS
 SELECT rc.id_retroalimentacion,
    (((u.nombre)::text || ' '::text) || (u.apellidos)::text) AS veterinario,
        CASE
            WHEN rc.es_conflicto_retroalimentacion THEN 'Conflicto'::character varying
            ELSE rc.estado_registro
        END AS valoracion,
    rc.fecha_retroalimentacion AS fecha
   FROM (modulo4.retroalimentaciones_clinicas rc
     JOIN modulo1.usuarios u ON ((rc.id_usuario_veterinario = u.id_usuario)))
  WHERE (rc.es_conflicto_retroalimentacion = true)
  ORDER BY rc.fecha_retroalimentacion DESC;


ALTER VIEW modulo8.vw_retroalimentaciones_contradictorias OWNER TO postgres;

--
-- Name: widgets_dashboard; Type: TABLE; Schema: modulo8; Owner: postgres
--

CREATE TABLE modulo8.widgets_dashboard (
    id_widget_dashboard integer NOT NULL,
    id_dashboard integer NOT NULL,
    titulo character varying(120) NOT NULL,
    tipo_widget character varying(40) NOT NULL,
    fuente_datos character varying(120) NOT NULL,
    posicion_x smallint NOT NULL,
    posicion_y smallint NOT NULL,
    ancho smallint NOT NULL,
    alto smallint NOT NULL,
    configuracion jsonb,
    fecha_creacion timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_widget_dimensiones_positivas CHECK (((ancho > 0) AND (alto > 0))),
    CONSTRAINT chk_widget_posicion_positiva CHECK (((posicion_x >= 0) AND (posicion_y >= 0))),
    CONSTRAINT chk_widget_tipo_fuente_no_vacios CHECK (((char_length(TRIM(BOTH FROM tipo_widget)) > 0) AND (char_length(TRIM(BOTH FROM fuente_datos)) > 0))),
    CONSTRAINT chk_widget_titulo_notempty CHECK ((TRIM(BOTH FROM titulo) <> ''::text))
);


ALTER TABLE modulo8.widgets_dashboard OWNER TO postgres;

--
-- Name: TABLE widgets_dashboard; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON TABLE modulo8.widgets_dashboard IS 'Representa los componentes visuales (widgets) que forman parte de un dashboard.
Cada widget tiene una posición, tamaño y fuente de datos propia dentro del grid
del dashboard al que pertenece.';


--
-- Name: COLUMN widgets_dashboard.id_widget_dashboard; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.widgets_dashboard.id_widget_dashboard IS 'Identificador único del widget dentro del dashboard. Clave primaria (serial).';


--
-- Name: COLUMN widgets_dashboard.id_dashboard; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.widgets_dashboard.id_dashboard IS 'FK hacia modulo8.dashboards. Indica a qué dashboard pertenece este widget.';


--
-- Name: COLUMN widgets_dashboard.titulo; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.widgets_dashboard.titulo IS 'Título visible del widget en la interfaz del usuario. Máximo 120 caracteres.';


--
-- Name: COLUMN widgets_dashboard.tipo_widget; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.widgets_dashboard.tipo_widget IS 'Tipo de visualización del widget (ej: GRAFICO_BARRAS, TABLA, KPI_CARD, MAPA).
Define la forma en que se renderizan los datos. Máximo 40 caracteres.';


--
-- Name: COLUMN widgets_dashboard.fuente_datos; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.widgets_dashboard.fuente_datos IS 'Identificador o nombre de la fuente de datos que alimenta el widget
(ej: nombre de vista, endpoint o consulta configurada). Máximo 120 caracteres.';


--
-- Name: COLUMN widgets_dashboard.posicion_x; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.widgets_dashboard.posicion_x IS 'Posición horizontal del widget en el grid del dashboard (columna, base 0).';


--
-- Name: COLUMN widgets_dashboard.posicion_y; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.widgets_dashboard.posicion_y IS 'Posición vertical del widget en el grid del dashboard (fila, base 0).';


--
-- Name: COLUMN widgets_dashboard.ancho; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.widgets_dashboard.ancho IS 'Ancho del widget expresado en unidades de columna del grid del dashboard.';


--
-- Name: COLUMN widgets_dashboard.alto; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.widgets_dashboard.alto IS 'Alto del widget expresado en unidades de fila del grid del dashboard.';


--
-- Name: COLUMN widgets_dashboard.configuracion; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.widgets_dashboard.configuracion IS 'Objeto JSON con la configuración específica del widget: filtros, colores,
métricas a mostrar, rangos de fechas, etc. Flexible según el tipo de widget.';


--
-- Name: COLUMN widgets_dashboard.fecha_creacion; Type: COMMENT; Schema: modulo8; Owner: postgres
--

COMMENT ON COLUMN modulo8.widgets_dashboard.fecha_creacion IS 'Marca temporal (con zona horaria) del momento en que se añadió el widget al dashboard.';


--
-- Name: widgets_dashboard_id_widget_dashboard_seq; Type: SEQUENCE; Schema: modulo8; Owner: postgres
--

CREATE SEQUENCE modulo8.widgets_dashboard_id_widget_dashboard_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER SEQUENCE modulo8.widgets_dashboard_id_widget_dashboard_seq OWNER TO postgres;

