--
-- Name: vw_rf15_dependencias_especie; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf15_dependencias_especie AS
 SELECT e.id_especie,
    e.nombre,
    count(DISTINCT ua.id_umbral_ambiental) FILTER (WHERE (ua.es_activo IS TRUE)) AS umbrales_activos,
    count(DISTINCT cb.id_ciclo_biologico) FILTER (WHERE (cb.es_activo IS TRUE)) AS ciclos_activos,
    count(DISTINCT ep.id_especies_patologias) AS patologias_asociadas
   FROM (((modulo9.especies e
     LEFT JOIN modulo9.umbrales_ambientales ua ON ((ua.id_especie = e.id_especie)))
     LEFT JOIN modulo9.ciclos_biologicos cb ON ((cb.id_especie = e.id_especie)))
     LEFT JOIN modulo9.especies_patologias ep ON ((ep.id_especie = e.id_especie)))
  GROUP BY e.id_especie, e.nombre;


ALTER VIEW modulo9.vw_rf15_dependencias_especie OWNER TO postgres;

--
-- Name: vw_rf15_especies_activas_selector; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf15_especies_activas_selector AS
 SELECT id_especie,
    nombre,
    descripcion
   FROM modulo9.especies e
  WHERE (es_activo IS TRUE);


ALTER VIEW modulo9.vw_rf15_especies_activas_selector OWNER TO postgres;

--
-- Name: vw_rf15_especies_nombre_normalizado; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf15_especies_nombre_normalizado AS
 SELECT id_especie,
    nombre,
    lower((nombre)::text) AS nombre_normalizado
   FROM modulo9.especies e;


ALTER VIEW modulo9.vw_rf15_especies_nombre_normalizado OWNER TO postgres;

--
-- Name: vw_rf15_especies_resumen; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf15_especies_resumen AS
 SELECT e.id_especie,
    e.nombre,
    e.descripcion,
    e.es_activo,
    e.fecha_creacion,
    e.fecha_actualizacion,
    count(DISTINCT cb.id_ciclo_biologico) AS total_ciclos,
    count(DISTINCT ep.id_especies_patologias) AS total_patologias
   FROM ((modulo9.especies e
     LEFT JOIN modulo9.ciclos_biologicos cb ON ((cb.id_especie = e.id_especie)))
     LEFT JOIN modulo9.especies_patologias ep ON ((ep.id_especie = e.id_especie)))
  GROUP BY e.id_especie, e.nombre, e.descripcion, e.es_activo, e.fecha_creacion, e.fecha_actualizacion;


ALTER VIEW modulo9.vw_rf15_especies_resumen OWNER TO postgres;

--
-- Name: vw_rf16_cabecera_especie; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf16_cabecera_especie AS
 SELECT e.id_especie,
    e.nombre,
    count(DISTINCT cb.id_ciclo_biologico) AS total_etapas,
    count(DISTINCT ep.id_especies_patologias) AS total_patologias
   FROM ((modulo9.especies e
     LEFT JOIN modulo9.ciclos_biologicos cb ON ((cb.id_especie = e.id_especie)))
     LEFT JOIN modulo9.especies_patologias ep ON ((ep.id_especie = e.id_especie)))
  GROUP BY e.id_especie, e.nombre;


ALTER VIEW modulo9.vw_rf16_cabecera_especie OWNER TO postgres;

--
-- Name: vw_rf16_ciclos_biologicos_especie; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf16_ciclos_biologicos_especie AS
 SELECT cb.id_especie,
    cb.id_ciclo_biologico,
    cb.nombre,
    cb.descripcion,
    cb.duracion_dias,
    cb.es_activo AS ciclo_activo,
    e.nombre AS especie,
    e.es_activo AS especie_activa
   FROM (modulo9.ciclos_biologicos cb
     JOIN modulo9.especies e ON ((e.id_especie = cb.id_especie)));


ALTER VIEW modulo9.vw_rf16_ciclos_biologicos_especie OWNER TO postgres;

--
-- Name: vw_rf16_ciclos_nombre_normalizado; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf16_ciclos_nombre_normalizado AS
 SELECT id_ciclo_biologico,
    id_especie,
    nombre,
    lower((nombre)::text) AS nombre_normalizado
   FROM modulo9.ciclos_biologicos cb;


ALTER VIEW modulo9.vw_rf16_ciclos_nombre_normalizado OWNER TO postgres;

--
-- Name: vw_rf16_dependencias_ciclos; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf16_dependencias_ciclos AS
 SELECT cb.id_ciclo_biologico,
    cb.nombre,
    count(cpb.id_ciclos_productivo_biologico) AS referencias_productivas
   FROM (modulo9.ciclos_biologicos cb
     LEFT JOIN modulo9.ciclos_productivos_biologicos cpb ON ((cpb.id_ciclo_biologico = cb.id_ciclo_biologico)))
  GROUP BY cb.id_ciclo_biologico, cb.nombre;


ALTER VIEW modulo9.vw_rf16_dependencias_ciclos OWNER TO postgres;

--
-- Name: vw_rf16_dependencias_patologias; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf16_dependencias_patologias AS
 SELECT p.id_patologia AS id_patologias,
    p.nombre,
    count(DISTINCT ep.id_especies_patologias) AS especies_asociadas,
    count(DISTINCT ps.id_patologia_signo) AS signos_asociados,
    count(DISTINCT pr.id_prediccion) AS predicciones_asociadas,
    count(DISTINCT ap.id_alerta_patologica) AS alertas_asociadas
   FROM ((((modulo9.patologias p
     LEFT JOIN modulo9.especies_patologias ep ON ((ep.id_patologia = p.id_patologia)))
     LEFT JOIN modulo4.patologias_signos ps ON ((ps.id_patologia = p.id_patologia)))
     LEFT JOIN modulo4.predicciones pr ON ((pr.id_patologia = p.id_patologia)))
     LEFT JOIN modulo4.alertas_patologicas ap ON ((ap.id_patologia = p.id_patologia)))
  GROUP BY p.id_patologia, p.nombre;


ALTER VIEW modulo9.vw_rf16_dependencias_patologias OWNER TO postgres;

--
-- Name: vw_rf16_patologias_especie; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf16_patologias_especie AS
 SELECT ep.id_especie,
    ep.id_especies_patologias,
    p.id_patologia AS id_patologias,
    p.nombre,
    p.descripcion,
    p.es_activo,
    p.nombre_tecnico,
    p.etiologia,
    p.categoria,
    p.codigo_cie
   FROM (modulo9.especies_patologias ep
     JOIN modulo9.patologias p ON ((p.id_patologia = ep.id_patologia)));


ALTER VIEW modulo9.vw_rf16_patologias_especie OWNER TO postgres;

--
-- Name: vw_rf16_patologias_nombre_normalizado; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf16_patologias_nombre_normalizado AS
 SELECT id_patologia AS id_patologias,
    nombre,
    lower((nombre)::text) AS nombre_normalizado
   FROM modulo9.patologias p;


ALTER VIEW modulo9.vw_rf16_patologias_nombre_normalizado OWNER TO postgres;

--
-- Name: vw_rf17_gestion_especies_historial; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf17_gestion_especies_historial AS
 SELECT ge.id_ediciones_especies,
    ge.id_usuario,
    concat_ws(' '::text, u.nombre, u.apellidos) AS usuario,
    ge.fecha_gestion,
    ge.id_especie,
    e.nombre AS especie,
    ge.id_umbral_ambiental,
    ua.nombre AS umbral_relacionado
   FROM (((modulo9.gestion_especies ge
     JOIN modulo1.usuarios u ON ((u.id_usuario = ge.id_usuario)))
     JOIN modulo9.especies e ON ((e.id_especie = ge.id_especie)))
     LEFT JOIN modulo9.umbrales_ambientales ua ON ((ua.id_umbral_ambiental = ge.id_umbral_ambiental)));


ALTER VIEW modulo9.vw_rf17_gestion_especies_historial OWNER TO postgres;

--
-- Name: vw_rf17_umbral_activo_por_especie_variable; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf17_umbral_activo_por_especie_variable AS
 SELECT id_especie,
    id_variable_ambiental,
    count(*) AS total_configuraciones_activas,
    array_agg(id_umbral_ambiental ORDER BY id_umbral_ambiental) AS umbrales_activos
   FROM modulo9.umbrales_ambientales ua
  WHERE (es_activo IS TRUE)
  GROUP BY id_especie, id_variable_ambiental;


ALTER VIEW modulo9.vw_rf17_umbral_activo_por_especie_variable OWNER TO postgres;

--
-- Name: vw_rf17_umbrales_detalle_niveles; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf17_umbrales_detalle_niveles AS
 SELECT ua.id_umbral_ambiental,
    ua.id_especie,
    e.nombre AS especie,
    ua.nombre,
    ua.unidad_medida,
    ua.descripcion,
    ua.es_activo,
    va.id_variable_ambiental,
    va.nombre AS variable,
    va.unidad,
    va.valor_fisico_min,
    va.valor_fisico_max,
    COALESCE(json_agg(json_build_object('id', na.id_nivel_alerta_ambiental, 'nivel', na.nivel, 'limite_inferior', na.limite_inferior, 'limite_superior', na.limite_superior) ORDER BY na.limite_inferior) FILTER (WHERE (na.id_nivel_alerta_ambiental IS NOT NULL)), '[]'::json) AS niveles_alerta
   FROM (((modulo9.umbrales_ambientales ua
     JOIN modulo9.especies e ON ((e.id_especie = ua.id_especie)))
     JOIN modulo9.variables_ambientales va ON ((va.id_variable_ambiental = ua.id_variable_ambiental)))
     LEFT JOIN modulo9.niveles_alerta_ambientales na ON ((na.id_umbral_ambiental = ua.id_umbral_ambiental)))
  GROUP BY ua.id_umbral_ambiental, ua.id_especie, e.nombre, ua.nombre, ua.unidad_medida, ua.descripcion, ua.es_activo, va.id_variable_ambiental, va.nombre, va.unidad, va.valor_fisico_min, va.valor_fisico_max;


ALTER VIEW modulo9.vw_rf17_umbrales_detalle_niveles OWNER TO postgres;

--
-- Name: vw_rf17_variables_configuracion_especie; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf17_variables_configuracion_especie AS
 SELECT e.id_especie,
    e.nombre AS especie,
    va.id_variable_ambiental,
    va.nombre,
    va.unidad,
    va.valor_fisico_min,
    va.valor_fisico_max,
    va.es_activo,
    (count(ua.id_umbral_ambiental) > 0) AS ya_configurada,
    min(ua.id_umbral_ambiental) AS id_umbral_ambiental,
    min((ua.nombre)::text) AS nombre_umbral,
    count(ua.id_umbral_ambiental) AS total_umbrales_activos
   FROM ((modulo9.especies e
     CROSS JOIN modulo9.variables_ambientales va)
     LEFT JOIN modulo9.umbrales_ambientales ua ON (((ua.id_variable_ambiental = va.id_variable_ambiental) AND (ua.id_especie = e.id_especie) AND (ua.es_activo IS TRUE))))
  WHERE (va.es_activo IS TRUE)
  GROUP BY e.id_especie, e.nombre, va.id_variable_ambiental, va.nombre, va.unidad, va.valor_fisico_min, va.valor_fisico_max, va.es_activo;


ALTER VIEW modulo9.vw_rf17_variables_configuracion_especie OWNER TO postgres;

--
-- Name: vw_rf18_configuracion_global_activa; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf18_configuracion_global_activa AS
 SELECT cg.id_configuracion_global,
    cg.frecuencia_muestreo,
    cg.heartbeat,
    cg.fecha_actualizacion,
    cg.es_activo,
    cg.id_usuario,
    concat_ws(' '::text, u.nombre, u.apellidos) AS modificado_por,
    u.correo_electronico
   FROM (modulo9.configuraciones_globales cg
     JOIN modulo1.usuarios u ON ((u.id_usuario = cg.id_usuario)))
  WHERE (cg.es_activo IS TRUE);


ALTER VIEW modulo9.vw_rf18_configuracion_global_activa OWNER TO postgres;

--
-- Name: vw_rf18_configuraciones_globales_historial; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf18_configuraciones_globales_historial AS
 SELECT cg.id_configuracion_global,
    cg.frecuencia_muestreo,
    cg.heartbeat,
    cg.fecha_actualizacion,
    cg.es_activo,
    cg.id_usuario,
    concat_ws(' '::text, u.nombre, u.apellidos) AS modificado_por
   FROM (modulo9.configuraciones_globales cg
     JOIN modulo1.usuarios u ON ((u.id_usuario = cg.id_usuario)));


ALTER VIEW modulo9.vw_rf18_configuraciones_globales_historial OWNER TO postgres;

--
-- Name: vw_rf19_dependencias_fincas; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf19_dependencias_fincas AS
 SELECT f.id_finca,
    f.nombre,
    count(DISTINCT i.id_infraestructura) FILTER (WHERE (i.es_activo IS TRUE)) AS infra_activas,
    count(DISTINCT d.id_dispositivo_iot) FILTER (WHERE (d.es_activo IS TRUE)) AS dispositivos_activos
   FROM ((modulo9.fincas f
     LEFT JOIN modulo9.infraestructuras i ON ((i.id_finca = f.id_finca)))
     LEFT JOIN ( SELECT DISTINCT ON (d0.id_dispositivo_iot) d0.id_dispositivo_iot,
            d0.serial,
            d0.descripcion,
            d0.es_activo,
            d0.fecha_creacion,
            COALESCE(saa.id_infraestructura, ab.id_infraestructura) AS id_infraestructura
           FROM (((modulo9.dispositivos_iot d0
             LEFT JOIN modulo9.sensores s ON ((s.id_dispositivo_iot = d0.id_dispositivo_iot)))
             LEFT JOIN modulo9.sensores_areas_asociadas saa ON (((saa.id_sensor = s.id_sensores) AND ((saa.fecha_finalizacion IS NULL) OR (saa.fecha_finalizacion > now())))))
             LEFT JOIN modulo2.activos_biologicos ab ON ((ab.id_dispositivo_iot = d0.id_dispositivo_iot)))
          ORDER BY d0.id_dispositivo_iot, saa.fecha_asociacion DESC NULLS LAST, saa.id_sensores_area_asociada DESC NULLS LAST) d ON ((d.id_infraestructura = i.id_infraestructura)))
  GROUP BY f.id_finca, f.nombre;


ALTER VIEW modulo9.vw_rf19_dependencias_fincas OWNER TO postgres;

--
-- Name: vw_rf19_fincas_nombre_normalizado; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf19_fincas_nombre_normalizado AS
 SELECT id_finca,
    id_usuario,
    nombre,
    lower((nombre)::text) AS nombre_normalizado
   FROM modulo9.fincas f;


ALTER VIEW modulo9.vw_rf19_fincas_nombre_normalizado OWNER TO postgres;

--
-- Name: vw_rf19_fincas_productor_resumen; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf19_fincas_productor_resumen AS
 SELECT f.id_usuario,
    f.id_finca,
    f.nombre,
    f.ubicacion,
    f.tamano_h,
    f.es_activo,
    f.fecha_creacion,
    f.fecha_actualizacion,
    concat_ws(' '::text, u.nombre, u.apellidos) AS productor,
    u.correo_electronico,
    count(i.id_infraestructura) FILTER (WHERE (i.es_activo IS TRUE)) AS areas_activas,
    count(i.id_infraestructura) AS total_areas
   FROM ((modulo9.fincas f
     JOIN modulo1.usuarios u ON ((u.id_usuario = f.id_usuario)))
     LEFT JOIN modulo9.infraestructuras i ON ((i.id_finca = f.id_finca)))
  GROUP BY f.id_usuario, f.id_finca, f.nombre, f.ubicacion, f.tamano_h, f.es_activo, f.fecha_creacion, f.fecha_actualizacion, u.nombre, u.apellidos, u.correo_electronico;


ALTER VIEW modulo9.vw_rf19_fincas_productor_resumen OWNER TO postgres;

--
