--
-- Name: vw_rf21_dispositivos_area_sensores; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf21_dispositivos_area_sensores AS
 SELECT d.id_infraestructura,
    d.id_dispositivo_iot,
    d.serial,
    d.descripcion,
    d.es_activo,
    d.fecha_creacion,
    count(s.id_sensores) AS total_sensores,
    count(s.id_sensores) FILTER (WHERE (s.es_activo IS TRUE)) AS sensores_activos
   FROM (( SELECT DISTINCT ON (d0.id_dispositivo_iot) d0.id_dispositivo_iot,
            d0.serial,
            d0.descripcion,
            d0.es_activo,
            d0.fecha_creacion,
            COALESCE(saa.id_infraestructura, ab.id_infraestructura) AS id_infraestructura
           FROM (((modulo9.dispositivos_iot d0
             LEFT JOIN modulo9.sensores s_1 ON ((s_1.id_dispositivo_iot = d0.id_dispositivo_iot)))
             LEFT JOIN modulo9.sensores_areas_asociadas saa ON (((saa.id_sensor = s_1.id_sensores) AND ((saa.fecha_finalizacion IS NULL) OR (saa.fecha_finalizacion > now())))))
             LEFT JOIN modulo2.activos_biologicos ab ON ((ab.id_dispositivo_iot = d0.id_dispositivo_iot)))
          ORDER BY d0.id_dispositivo_iot, saa.fecha_asociacion DESC NULLS LAST, saa.id_sensores_area_asociada DESC NULLS LAST) d
     LEFT JOIN modulo9.sensores s ON ((s.id_dispositivo_iot = d.id_dispositivo_iot)))
  GROUP BY d.id_infraestructura, d.id_dispositivo_iot, d.serial, d.descripcion, d.es_activo, d.fecha_creacion;


ALTER VIEW modulo9.vw_rf21_dispositivos_area_sensores OWNER TO postgres;

--
-- Name: vw_rf21_dispositivos_sensores_asociacion; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf21_dispositivos_sensores_asociacion AS
 SELECT d.id_dispositivo_iot,
    d.serial,
    d.descripcion,
    d.es_activo,
    i.id_infraestructura,
    i.nombre AS area,
    f.id_finca,
    f.nombre AS finca,
    count(s.id_sensores) AS total_sensores,
    count(s.id_sensores) FILTER (WHERE (NOT (EXISTS ( SELECT 1
           FROM modulo9.sensores_areas_asociadas saa
          WHERE ((saa.id_sensor = s.id_sensores) AND (saa.tiene_estado IS TRUE)))))) AS sensores_libres,
    count(s.id_sensores) FILTER (WHERE (EXISTS ( SELECT 1
           FROM modulo9.sensores_areas_asociadas saa
          WHERE ((saa.id_sensor = s.id_sensores) AND (saa.tiene_estado IS TRUE))))) AS sensores_asociados
   FROM (((( SELECT DISTINCT ON (d0.id_dispositivo_iot) d0.id_dispositivo_iot,
            d0.serial,
            d0.descripcion,
            d0.es_activo,
            d0.fecha_creacion,
            COALESCE(saa.id_infraestructura, ab.id_infraestructura) AS id_infraestructura
           FROM (((modulo9.dispositivos_iot d0
             LEFT JOIN modulo9.sensores s_1 ON ((s_1.id_dispositivo_iot = d0.id_dispositivo_iot)))
             LEFT JOIN modulo9.sensores_areas_asociadas saa ON (((saa.id_sensor = s_1.id_sensores) AND ((saa.fecha_finalizacion IS NULL) OR (saa.fecha_finalizacion > now())))))
             LEFT JOIN modulo2.activos_biologicos ab ON ((ab.id_dispositivo_iot = d0.id_dispositivo_iot)))
          ORDER BY d0.id_dispositivo_iot, saa.fecha_asociacion DESC NULLS LAST, saa.id_sensores_area_asociada DESC NULLS LAST) d
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = d.id_infraestructura)))
     JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)))
     LEFT JOIN modulo9.sensores s ON ((s.id_dispositivo_iot = d.id_dispositivo_iot)))
  WHERE (d.es_activo IS TRUE)
  GROUP BY d.id_dispositivo_iot, d.serial, d.descripcion, d.es_activo, i.id_infraestructura, i.nombre, f.id_finca, f.nombre;


ALTER VIEW modulo9.vw_rf21_dispositivos_sensores_asociacion OWNER TO postgres;

--
-- Name: vw_rf21_dispositivos_seriales; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf21_dispositivos_seriales AS
 SELECT id_dispositivo_iot,
    serial,
    lower((serial)::text) AS serial_normalizado
   FROM ( SELECT DISTINCT ON (d0.id_dispositivo_iot) d0.id_dispositivo_iot,
            d0.serial,
            d0.descripcion,
            d0.es_activo,
            d0.fecha_creacion,
            COALESCE(saa.id_infraestructura, ab.id_infraestructura) AS id_infraestructura
           FROM (((modulo9.dispositivos_iot d0
             LEFT JOIN modulo9.sensores s ON ((s.id_dispositivo_iot = d0.id_dispositivo_iot)))
             LEFT JOIN modulo9.sensores_areas_asociadas saa ON (((saa.id_sensor = s.id_sensores) AND ((saa.fecha_finalizacion IS NULL) OR (saa.fecha_finalizacion > now())))))
             LEFT JOIN modulo2.activos_biologicos ab ON ((ab.id_dispositivo_iot = d0.id_dispositivo_iot)))
          ORDER BY d0.id_dispositivo_iot, saa.fecha_asociacion DESC NULLS LAST, saa.id_sensores_area_asociada DESC NULLS LAST) d;


ALTER VIEW modulo9.vw_rf21_dispositivos_seriales OWNER TO postgres;

--
-- Name: vw_rf22_areas_destino_disponibles; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf22_areas_destino_disponibles AS
 SELECT i.id_infraestructura,
    i.nombre,
    i.tipo,
    f.id_finca,
    f.nombre AS finca
   FROM (modulo9.infraestructuras i
     JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)))
  WHERE ((i.es_activo IS TRUE) AND (f.es_activo IS TRUE));


ALTER VIEW modulo9.vw_rf22_areas_destino_disponibles OWNER TO postgres;

--
-- Name: vw_rf22_sensores_dispositivo_asociacion; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf22_sensores_dispositivo_asociacion AS
 SELECT s.id_dispositivo_iot,
    s.id_sensores,
    s.nombre,
    s.es_activo,
    saa.id_sensores_area_asociada,
    saa.tiene_estado AS asociado_activo,
    saa.punto_instalacion,
    i.id_infraestructura,
    i.nombre AS area_asociada,
    f.id_finca,
    f.nombre AS finca_asociada,
    saa.fecha_asociacion
   FROM (((modulo9.sensores s
     LEFT JOIN LATERAL ( SELECT saa_actual.id_sensores_area_asociada,
            saa_actual.tiene_estado,
            saa_actual.punto_instalacion,
            saa_actual.id_infraestructura,
            saa_actual.fecha_asociacion
           FROM modulo9.sensores_areas_asociadas saa_actual
          WHERE ((saa_actual.id_sensor = s.id_sensores) AND (saa_actual.tiene_estado IS TRUE))
          ORDER BY saa_actual.fecha_asociacion DESC, saa_actual.id_sensores_area_asociada DESC
         LIMIT 1) saa ON (true))
     LEFT JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = saa.id_infraestructura)))
     LEFT JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)));


ALTER VIEW modulo9.vw_rf22_sensores_dispositivo_asociacion OWNER TO postgres;

--
-- Name: vw_rf23_configuraciones_pendientes; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf23_configuraciones_pendientes AS
 SELECT id_dispositivo_iot,
    id_configuracion_remota,
    frecuencia_captura,
    intervalo_transmision,
    estado,
    fecha_creacion
   FROM ( SELECT cr_base.id_configuracion_remota,
            cr_base.frecuencia_captura,
            cr_base.intervalo_transmision,
            cr_base.id_dispositivo_iot,
            cr_base.estado,
            cr_base.id_usuario,
            cr_base.fecha_creacion,
            cr_base.fecha_aplicacion,
            row_number() OVER (PARTITION BY cr_base.id_dispositivo_iot ORDER BY cr_base.fecha_creacion DESC NULLS LAST, cr_base.id_configuracion_remota DESC) AS orden_pendiente
           FROM modulo9.configuraciones_remotas cr_base
          WHERE ((cr_base.estado)::text = 'PENDIENTE'::text)) cr
  WHERE (orden_pendiente = 1);


ALTER VIEW modulo9.vw_rf23_configuraciones_pendientes OWNER TO postgres;

--
-- Name: vw_rf23_dispositivos_configuracion_area; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf23_dispositivos_configuracion_area AS
 SELECT d.id_dispositivo_iot,
    d.serial,
    d.descripcion,
    d.es_activo,
    cr.id_configuracion_remota,
    cr.frecuencia_captura,
    cr.intervalo_transmision,
    cr.estado AS estado_configuracion,
    cr.fecha_creacion AS fecha_configuracion,
    cr.fecha_aplicacion,
    i.id_infraestructura,
    i.nombre AS area,
    f.id_finca,
    f.nombre AS finca
   FROM (((( SELECT DISTINCT ON (d0.id_dispositivo_iot) d0.id_dispositivo_iot,
            d0.serial,
            d0.descripcion,
            d0.es_activo,
            d0.fecha_creacion,
            COALESCE(saa.id_infraestructura, ab.id_infraestructura) AS id_infraestructura
           FROM (((modulo9.dispositivos_iot d0
             LEFT JOIN modulo9.sensores s ON ((s.id_dispositivo_iot = d0.id_dispositivo_iot)))
             LEFT JOIN modulo9.sensores_areas_asociadas saa ON (((saa.id_sensor = s.id_sensores) AND ((saa.fecha_finalizacion IS NULL) OR (saa.fecha_finalizacion > now())))))
             LEFT JOIN modulo2.activos_biologicos ab ON ((ab.id_dispositivo_iot = d0.id_dispositivo_iot)))
          ORDER BY d0.id_dispositivo_iot, saa.fecha_asociacion DESC NULLS LAST, saa.id_sensores_area_asociada DESC NULLS LAST) d
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = d.id_infraestructura)))
     JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)))
     LEFT JOIN LATERAL ( SELECT cr_actual.id_configuracion_remota,
            cr_actual.frecuencia_captura,
            cr_actual.intervalo_transmision,
            cr_actual.estado,
            cr_actual.fecha_creacion,
            cr_actual.fecha_aplicacion
           FROM modulo9.configuraciones_remotas cr_actual
          WHERE (cr_actual.id_dispositivo_iot = d.id_dispositivo_iot)
          ORDER BY cr_actual.fecha_creacion DESC NULLS LAST, cr_actual.id_configuracion_remota DESC
         LIMIT 1) cr ON (true));


ALTER VIEW modulo9.vw_rf23_dispositivos_configuracion_area OWNER TO postgres;

--
-- Name: vw_rf24_dispositivos_activos_calibraciones; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf24_dispositivos_activos_calibraciones AS
 SELECT d.id_dispositivo_iot,
    d.serial,
    d.descripcion,
    d.es_activo,
    i.id_infraestructura,
    i.nombre AS area,
    f.id_finca,
    f.nombre AS finca,
    count(DISTINCT s.id_sensores) AS total_sensores,
    count(DISTINCT c.id_calibracion) AS total_calibraciones,
    max(c.fecha_calibracion) AS ultima_calibracion
   FROM ((((( SELECT DISTINCT ON (d0.id_dispositivo_iot) d0.id_dispositivo_iot,
            d0.serial,
            d0.descripcion,
            d0.es_activo,
            d0.fecha_creacion,
            COALESCE(saa.id_infraestructura, ab.id_infraestructura) AS id_infraestructura
           FROM (((modulo9.dispositivos_iot d0
             LEFT JOIN modulo9.sensores s_1 ON ((s_1.id_dispositivo_iot = d0.id_dispositivo_iot)))
             LEFT JOIN modulo9.sensores_areas_asociadas saa ON (((saa.id_sensor = s_1.id_sensores) AND ((saa.fecha_finalizacion IS NULL) OR (saa.fecha_finalizacion > now())))))
             LEFT JOIN modulo2.activos_biologicos ab ON ((ab.id_dispositivo_iot = d0.id_dispositivo_iot)))
          ORDER BY d0.id_dispositivo_iot, saa.fecha_asociacion DESC NULLS LAST, saa.id_sensores_area_asociada DESC NULLS LAST) d
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = d.id_infraestructura)))
     JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)))
     LEFT JOIN modulo9.sensores s ON ((s.id_dispositivo_iot = d.id_dispositivo_iot)))
     LEFT JOIN modulo9.calibraciones c ON ((c.id_dispositivo_iot = d.id_dispositivo_iot)))
  WHERE (d.es_activo IS TRUE)
  GROUP BY d.id_dispositivo_iot, d.serial, d.descripcion, d.es_activo, i.id_infraestructura, i.nombre, f.id_finca, f.nombre;


ALTER VIEW modulo9.vw_rf24_dispositivos_activos_calibraciones OWNER TO postgres;

--
-- Name: vw_rf24_historial_calibraciones_sensor; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf24_historial_calibraciones_sensor AS
 SELECT c.id_sensor,
    c.id_calibracion,
    c.fecha_calibracion,
    c.valor_referencia,
    c.observaciones,
    c.id_usuario,
    concat_ws(' '::text, u.nombre, u.apellidos) AS tecnico
   FROM (modulo9.calibraciones c
     LEFT JOIN modulo1.usuarios u ON ((u.id_usuario = c.id_usuario)));


ALTER VIEW modulo9.vw_rf24_historial_calibraciones_sensor OWNER TO postgres;

--
-- Name: vw_rf24_sensores_dispositivo_calibracion; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf24_sensores_dispositivo_calibracion AS
 SELECT s.id_dispositivo_iot,
    s.id_sensores,
    s.nombre,
    s.es_activo,
    ultima.fecha_calibracion AS ultima_calibracion,
    ultima.valor_referencia AS ultimo_valor_referencia
   FROM (modulo9.sensores s
     LEFT JOIN LATERAL ( SELECT c.fecha_calibracion,
            c.valor_referencia
           FROM modulo9.calibraciones c
          WHERE (c.id_sensor = s.id_sensores)
          ORDER BY c.fecha_calibracion DESC, c.id_calibracion DESC
         LIMIT 1) ultima ON (true))
  WHERE (s.es_activo IS TRUE);


ALTER VIEW modulo9.vw_rf24_sensores_dispositivo_calibracion OWNER TO postgres;

--
-- Name: vw_rf25_contexto_usuario; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf25_contexto_usuario AS
 SELECT u.id_usuario,
    concat_ws(' '::text, u.nombre, u.apellidos) AS nombre_completo,
    r.id_rol,
    r.nombre_rol,
    f.id_finca,
    f.nombre AS finca_activa,
    (f.ubicacion ->> 'departamento'::text) AS departamento,
    f.es_activo AS finca_activa_estado,
    especies.especies_configuradas AS especies_en_finca
   FROM (((modulo1.usuarios u
     JOIN modulo1.roles r ON ((r.id_rol = u.id_rol)))
     LEFT JOIN modulo9.fincas f ON (((f.id_usuario = u.id_usuario) AND (f.es_activo IS TRUE))))
     LEFT JOIN LATERAL ( SELECT COALESCE(array_agg(DISTINCT (e.nombre)::text ORDER BY (e.nombre)::text), ARRAY[]::text[]) AS especies_configuradas
           FROM (modulo9.umbrales_ambientales ua
             JOIN modulo9.especies e ON ((e.id_especie = ua.id_especie)))
          WHERE ((ua.es_activo IS TRUE) AND (e.es_activo IS TRUE))) especies ON (true));


ALTER VIEW modulo9.vw_rf25_contexto_usuario OWNER TO postgres;

--
-- Name: vw_rf25_permisos_roles; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf25_permisos_roles AS
 SELECT r.id_rol,
    r.nombre_rol,
    rec.nombre_recurso AS modulo,
    a.descripcion AS accion,
    a.codigo AS codigo_accion,
    p.id_permiso,
    p.nombre AS permiso,
    p.es_activo
   FROM (((modulo1.roles r
     JOIN modulo1.permisos p ON ((p.id_rol = r.id_rol)))
     JOIN modulo1.recursos rec ON ((rec.id_recurso = p.id_recurso)))
     JOIN modulo1.acciones a ON ((a.id_accion = p.id_accion)));


ALTER VIEW modulo9.vw_rf25_permisos_roles OWNER TO postgres;

--
-- Name: vw_rf26_auditorias_visuales_historial; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf26_auditorias_visuales_historial AS
 SELECT av.id_auditoria_visual,
    av.fecha_creacion,
    av.valor_anterior,
    av.valor_nuevo,
    av.id_usuario,
    concat_ws(' '::text, u.nombre, u.apellidos) AS usuario
   FROM (modulo9.auditorias_visuales av
     JOIN modulo1.usuarios u ON ((u.id_usuario = av.id_usuario)));


ALTER VIEW modulo9.vw_rf26_auditorias_visuales_historial OWNER TO postgres;

--
-- Name: vw_rf26_identidad_visual_activa; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf26_identidad_visual_activa AS
 SELECT DISTINCT ON (iv.id_finca) iv.id_finca,
    iv.id_identidad_visual,
    iv.logo_path,
    iv.primary_color,
    iv.secondary_color,
    iv.org_display_name,
    iv.version,
    iv.fecha_creacion,
    f.nombre AS finca,
    iv.id_usuario,
    concat_ws(' '::text, u.nombre, u.apellidos) AS modificado_por
   FROM ((modulo9.identidad_visuales iv
     JOIN modulo9.fincas f ON ((f.id_finca = iv.id_finca)))
     JOIN modulo1.usuarios u ON ((u.id_usuario = iv.id_usuario)))
  ORDER BY iv.id_finca, iv.version DESC NULLS LAST, iv.fecha_creacion DESC NULLS LAST, iv.id_identidad_visual DESC;


ALTER VIEW modulo9.vw_rf26_identidad_visual_activa OWNER TO postgres;

--
-- Name: vw_rf27_preferencias_tema_usuarios; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf27_preferencias_tema_usuarios AS
 SELECT u.id_usuario,
    concat_ws(' '::text, u.nombre, u.apellidos) AS usuario,
    r.nombre_rol,
    tv.id_tema_visual,
    tv.theme_mode,
    tv.es_global,
    tv.fecha_actualizacion
   FROM ((modulo9.temas_visuales tv
     JOIN modulo1.usuarios u ON ((u.id_usuario = tv.id_usuario)))
     JOIN modulo1.roles r ON ((r.id_rol = u.id_rol)));


ALTER VIEW modulo9.vw_rf27_preferencias_tema_usuarios OWNER TO postgres;

--
-- Name: vw_rf27_tema_usuario_global; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf27_tema_usuario_global AS
 SELECT u.id_usuario,
    tv_user.id_tema_visual AS id_preferencia_usuario,
    tv_user.theme_mode AS tema_usuario,
    tv_user.fecha_actualizacion AS actualizado_en,
    tv_global.theme_mode AS tema_global,
    concat_ws(' '::text, u.nombre, u.apellidos) AS usuario
   FROM ((modulo1.usuarios u
     LEFT JOIN LATERAL ( SELECT tv.id_tema_visual,
            tv.theme_mode,
            tv.fecha_actualizacion
           FROM modulo9.temas_visuales tv
          WHERE ((tv.id_usuario = u.id_usuario) AND (tv.es_global IS FALSE))
          ORDER BY tv.fecha_actualizacion DESC, tv.id_tema_visual DESC
         LIMIT 1) tv_user ON (true))
     LEFT JOIN LATERAL ( SELECT tv.theme_mode
           FROM modulo9.temas_visuales tv
          WHERE (tv.es_global IS TRUE)
          ORDER BY tv.fecha_actualizacion DESC, tv.id_tema_visual DESC
         LIMIT 1) tv_global ON (true));


ALTER VIEW modulo9.vw_rf27_tema_usuario_global OWNER TO postgres;

--
-- Name: vw_rf28_dashboard_layout_usuario; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf28_dashboard_layout_usuario AS
 SELECT DISTINCT ON (id_usuario) id_usuario,
    id_dashboard_layout,
    config,
    active_widget,
    fecha_actualizacion,
    jsonb_array_length(COALESCE((config -> 'grid'::text), '[]'::jsonb)) AS total_widgets_configurados
   FROM modulo9.dashboard_layouts dl
  ORDER BY id_usuario, fecha_actualizacion DESC NULLS LAST, id_dashboard_layout DESC;


ALTER VIEW modulo9.vw_rf28_dashboard_layout_usuario OWNER TO postgres;

--
-- Name: vw_rf28_widget_dispositivos_sin_configuracion; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf28_widget_dispositivos_sin_configuracion AS
 SELECT d.id_dispositivo_iot,
    d.serial,
    d.descripcion,
    i.id_infraestructura,
    i.nombre AS area,
    f.id_finca,
    f.nombre AS finca
   FROM ((( SELECT DISTINCT ON (d0.id_dispositivo_iot) d0.id_dispositivo_iot,
            d0.serial,
            d0.descripcion,
            d0.es_activo,
            d0.fecha_creacion,
            COALESCE(saa.id_infraestructura, ab.id_infraestructura) AS id_infraestructura
           FROM (((modulo9.dispositivos_iot d0
             LEFT JOIN modulo9.sensores s ON ((s.id_dispositivo_iot = d0.id_dispositivo_iot)))
             LEFT JOIN modulo9.sensores_areas_asociadas saa ON (((saa.id_sensor = s.id_sensores) AND ((saa.fecha_finalizacion IS NULL) OR (saa.fecha_finalizacion > now())))))
             LEFT JOIN modulo2.activos_biologicos ab ON ((ab.id_dispositivo_iot = d0.id_dispositivo_iot)))
          ORDER BY d0.id_dispositivo_iot, saa.fecha_asociacion DESC NULLS LAST, saa.id_sensores_area_asociada DESC NULLS LAST) d
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = d.id_infraestructura)))
     JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)))
  WHERE ((d.es_activo IS TRUE) AND (NOT (EXISTS ( SELECT 1
           FROM modulo9.configuraciones_remotas cr
          WHERE (cr.id_dispositivo_iot = d.id_dispositivo_iot)))));


ALTER VIEW modulo9.vw_rf28_widget_dispositivos_sin_configuracion OWNER TO postgres;

--
-- Name: vw_rf28_widget_estado_dispositivos; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf28_widget_estado_dispositivos AS
 SELECT d.id_dispositivo_iot,
    d.serial,
    d.es_activo,
    i.id_infraestructura,
    i.nombre AS area,
    f.id_finca,
    f.nombre AS finca,
    ultima_cal.ultima_calibracion,
    cr.frecuencia_captura,
    cr.intervalo_transmision,
    cr.estado AS estado_configuracion
   FROM ((((( SELECT DISTINCT ON (d0.id_dispositivo_iot) d0.id_dispositivo_iot,
            d0.serial,
            d0.descripcion,
            d0.es_activo,
            d0.fecha_creacion,
            COALESCE(saa.id_infraestructura, ab.id_infraestructura) AS id_infraestructura
           FROM (((modulo9.dispositivos_iot d0
             LEFT JOIN modulo9.sensores s ON ((s.id_dispositivo_iot = d0.id_dispositivo_iot)))
             LEFT JOIN modulo9.sensores_areas_asociadas saa ON (((saa.id_sensor = s.id_sensores) AND ((saa.fecha_finalizacion IS NULL) OR (saa.fecha_finalizacion > now())))))
             LEFT JOIN modulo2.activos_biologicos ab ON ((ab.id_dispositivo_iot = d0.id_dispositivo_iot)))
          ORDER BY d0.id_dispositivo_iot, saa.fecha_asociacion DESC NULLS LAST, saa.id_sensores_area_asociada DESC NULLS LAST) d
     JOIN modulo9.infraestructuras i ON ((i.id_infraestructura = d.id_infraestructura)))
     JOIN modulo9.fincas f ON ((f.id_finca = i.id_finca)))
     LEFT JOIN LATERAL ( SELECT max(c.fecha_calibracion) AS ultima_calibracion
           FROM modulo9.calibraciones c
          WHERE (c.id_dispositivo_iot = d.id_dispositivo_iot)) ultima_cal ON (true))
     LEFT JOIN LATERAL ( SELECT cr_actual.frecuencia_captura,
            cr_actual.intervalo_transmision,
            cr_actual.estado
           FROM modulo9.configuraciones_remotas cr_actual
          WHERE (cr_actual.id_dispositivo_iot = d.id_dispositivo_iot)
          ORDER BY cr_actual.fecha_creacion DESC NULLS LAST, cr_actual.id_configuracion_remota DESC
         LIMIT 1) cr ON (true));


ALTER VIEW modulo9.vw_rf28_widget_estado_dispositivos OWNER TO postgres;

--
-- Name: vw_rf28_widget_estado_fincas; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf28_widget_estado_fincas AS
 SELECT f.id_finca,
    f.nombre,
    f.es_activo,
    (f.ubicacion ->> 'departamento'::text) AS departamento,
    count(DISTINCT i.id_infraestructura) FILTER (WHERE (i.es_activo IS TRUE)) AS areas_activas,
    count(DISTINCT d.id_dispositivo_iot) FILTER (WHERE (d.es_activo IS TRUE)) AS dispositivos_activos
   FROM ((modulo9.fincas f
     LEFT JOIN modulo9.infraestructuras i ON ((i.id_finca = f.id_finca)))
     LEFT JOIN ( SELECT DISTINCT ON (d0.id_dispositivo_iot) d0.id_dispositivo_iot,
            d0.serial,
            d0.descripcion,
            d0.es_activo,
            d0.fecha_creacion,
            COALESCE(saa.id_infraestructura, ab.id_infraestructura) AS id_infraestructura
           FROM (((modulo9.dispositivos_iot d0
             LEFT JOIN modulo9.sensores s ON ((s.id_dispositivo_iot = d0.id_dispositivo_iot)))
             LEFT JOIN modulo9.sensores_areas_asociadas saa ON (((saa.id_sensor = s.id_sensores) AND ((saa.fecha_finalizacion IS NULL) OR (saa.fecha_finalizacion > now())))))
             LEFT JOIN modulo2.activos_biologicos ab ON ((ab.id_dispositivo_iot = d0.id_dispositivo_iot)))
          ORDER BY d0.id_dispositivo_iot, saa.fecha_asociacion DESC NULLS LAST, saa.id_sensores_area_asociada DESC NULLS LAST) d ON ((d.id_infraestructura = i.id_infraestructura)))
  GROUP BY f.id_finca, f.nombre, f.es_activo, f.ubicacion;


ALTER VIEW modulo9.vw_rf28_widget_estado_fincas OWNER TO postgres;

--
-- Name: vw_rf29_idioma_usuario_global; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf29_idioma_usuario_global AS
 SELECT u.id_usuario,
    pi_user.id_preferencia_idioma,
    pi_user.locale_code AS idioma_usuario,
    pi_user.es_por_defecto,
    pi_user.fecha_actualizacion,
    pi_global.locale_code AS idioma_global,
    concat_ws(' '::text, u.nombre, u.apellidos) AS usuario
   FROM ((modulo1.usuarios u
     LEFT JOIN LATERAL ( SELECT pi.id_preferencia_idioma,
            pi.locale_code,
            pi.es_por_defecto,
            pi.fecha_actualizacion
           FROM modulo9.preferencias_idiomas pi
          WHERE ((pi.id_usuario = u.id_usuario) AND (pi.es_por_defecto IS FALSE))
          ORDER BY pi.fecha_actualizacion DESC NULLS LAST, pi.id_preferencia_idioma DESC
         LIMIT 1) pi_user ON (true))
     LEFT JOIN LATERAL ( SELECT pi.locale_code
           FROM modulo9.preferencias_idiomas pi
          WHERE (pi.es_por_defecto IS TRUE)
          ORDER BY pi.fecha_actualizacion DESC NULLS LAST, pi.id_preferencia_idioma DESC
         LIMIT 1) pi_global ON (true));


ALTER VIEW modulo9.vw_rf29_idioma_usuario_global OWNER TO postgres;

--
-- Name: vw_rf29_preferencias_idioma_usuarios; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf29_preferencias_idioma_usuarios AS
 SELECT u.id_usuario,
    concat_ws(' '::text, u.nombre, u.apellidos) AS usuario,
    r.nombre_rol,
    pi.id_preferencia_idioma,
    pi.locale_code,
    pi.es_por_defecto,
    pi.fecha_actualizacion
   FROM ((modulo9.preferencias_idiomas pi
     JOIN modulo1.usuarios u ON ((u.id_usuario = pi.id_usuario)))
     JOIN modulo1.roles r ON ((r.id_rol = u.id_rol)));


ALTER VIEW modulo9.vw_rf29_preferencias_idioma_usuarios OWNER TO postgres;

--
-- Name: vw_rf31_params_disponibles_especie; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf31_params_disponibles_especie AS
 SELECT id_especie,
    nombre AS especie,
    json_build_object('umbrales', ( SELECT COALESCE(json_agg(json_build_object('id', ua.id_umbral_ambiental, 'nombre', ua.nombre) ORDER BY ua.nombre), '[]'::json) AS "coalesce"
           FROM modulo9.umbrales_ambientales ua
          WHERE ((ua.id_especie = e.id_especie) AND (ua.es_activo IS TRUE))), 'ciclos', ( SELECT COALESCE(json_agg(json_build_object('id', cb.id_ciclo_biologico, 'nombre', cb.nombre) ORDER BY cb.nombre), '[]'::json) AS "coalesce"
           FROM modulo9.ciclos_biologicos cb
          WHERE ((cb.id_especie = e.id_especie) AND (cb.es_activo IS TRUE))), 'patologias', ( SELECT COALESCE(json_agg(json_build_object('id', p.id_patologia, 'nombre', p.nombre) ORDER BY p.nombre), '[]'::json) AS "coalesce"
           FROM (modulo9.especies_patologias ep
             JOIN modulo9.patologias p ON ((p.id_patologia = ep.id_patologia)))
          WHERE ((ep.id_especie = e.id_especie) AND (p.es_activo IS TRUE)))) AS params_disponibles
   FROM modulo9.especies e;


ALTER VIEW modulo9.vw_rf31_params_disponibles_especie OWNER TO postgres;

--
-- Name: vw_rf31_plantillas_listado; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf31_plantillas_listado AS
 SELECT p.id_plantilla,
    p.template_name,
    p.version,
    p.fecha_creacion,
    p.id_especie,
    e.nombre AS especie,
    p.id_usuario,
    concat_ws(' '::text, u.nombre, u.apellidos) AS creado_por,
    jsonb_array_length(COALESCE((p.params_snapshot -> 'umbrales'::text), '[]'::jsonb)) AS total_umbrales,
    jsonb_array_length(COALESCE((p.params_snapshot -> 'ciclos_biologicos'::text), '[]'::jsonb)) AS total_ciclos,
    jsonb_array_length(COALESCE((p.params_snapshot -> 'metricas'::text), '[]'::jsonb)) AS total_metricas
   FROM ((modulo9.plantillas p
     JOIN modulo9.especies e ON ((e.id_especie = p.id_especie)))
     JOIN modulo1.usuarios u ON ((u.id_usuario = p.id_usuario)));


ALTER VIEW modulo9.vw_rf31_plantillas_listado OWNER TO postgres;

--
-- Name: vw_rf31_plantillas_nombre_normalizado; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf31_plantillas_nombre_normalizado AS
 SELECT id_plantilla,
    template_name,
    lower((template_name)::text) AS template_name_normalizado
   FROM modulo9.plantillas p;


ALTER VIEW modulo9.vw_rf31_plantillas_nombre_normalizado OWNER TO postgres;

--
-- Name: vw_rf31_plantillas_resumen; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf31_plantillas_resumen AS
 SELECT count(*) AS total_plantillas,
    count(DISTINCT id_especie) AS especies_cubiertas,
    count(DISTINCT template_name) AS nombres_unicos
   FROM modulo9.plantillas p;


ALTER VIEW modulo9.vw_rf31_plantillas_resumen OWNER TO postgres;

--
-- Name: vw_rf32_plantillas_detalle; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf32_plantillas_detalle AS
 SELECT p.id_plantilla,
    p.template_name,
    p.version,
    p.fecha_creacion,
    p.params_snapshot,
    e.id_especie,
    e.nombre AS especie,
    e.es_activo AS especie_activa,
    p.id_usuario,
    concat_ws(' '::text, u.nombre, u.apellidos) AS creado_por
   FROM ((modulo9.plantillas p
     JOIN modulo9.especies e ON ((e.id_especie = p.id_especie)))
     JOIN modulo1.usuarios u ON ((u.id_usuario = p.id_usuario)));


ALTER VIEW modulo9.vw_rf32_plantillas_detalle OWNER TO postgres;

--
-- Name: vw_rf33_aplicaciones_plantillas_historial; Type: VIEW; Schema: modulo9; Owner: postgres
--

CREATE VIEW modulo9.vw_rf33_aplicaciones_plantillas_historial AS
 SELECT ap.id_plantilla,
    ap.id_aplicacion_plantilla,
    ap.target_config,
    ap.before_snapshot,
    ap.after_snapshot,
    ap.fecha_aplicacion,
    ap.id_usuario,
    concat_ws(' '::text, u.nombre, u.apellidos) AS aplicado_por,
    p.template_name,
    p.version
   FROM ((modulo9.aplicaciones_plantillas ap
     JOIN modulo1.usuarios u ON ((u.id_usuario = ap.id_usuario)))
     JOIN modulo9.plantillas p ON ((p.id_plantilla = ap.id_plantilla)));


ALTER VIEW modulo9.vw_rf33_aplicaciones_plantillas_historial OWNER TO postgres;

