--
-- Name: TRIGGER tgr_m06_01_inmutabilidad_reconocimiento ON reconocimientos_iniciales; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TRIGGER tgr_m06_01_inmutabilidad_reconocimiento ON modulo6.reconocimientos_iniciales IS 'TGR-M06-01 | RF-82 Restricción 2 y RNF-82-03 | Garantiza la inmutabilidad de reconocimientos en estado CONFIRMADO o REVERTIDO. Bloquea cualquier UPDATE o DELETE directo sobre estos registros. Solo permite modificaciones sobre PENDIENTE_CONFIRMACION.';


--
-- Name: reconocimientos_iniciales tgr_m06_02_unicidad_reconocimiento_confirmado; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

CREATE TRIGGER tgr_m06_02_unicidad_reconocimiento_confirmado BEFORE INSERT OR UPDATE OF estado ON modulo6.reconocimientos_iniciales FOR EACH ROW EXECUTE FUNCTION modulo6.fn_tgr_m06_02_unicidad_reconocimiento_confirmado();


--
-- Name: TRIGGER tgr_m06_02_unicidad_reconocimiento_confirmado ON reconocimientos_iniciales; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TRIGGER tgr_m06_02_unicidad_reconocimiento_confirmado ON modulo6.reconocimientos_iniciales IS 'TGR-M06-02 | RF-82 Restricción 3 y FA-1 | Impide que exista más de un reconocimiento inicial en estado CONFIRMADO para el mismo activo biológico. Permite un nuevo reconocimiento solo si el anterior fue REVERTIDO.';


--
-- Name: revisiones_reconocimiento tgr_m06_03_inmutabilidad_revisiones; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

CREATE TRIGGER tgr_m06_03_inmutabilidad_revisiones BEFORE DELETE OR UPDATE ON modulo6.revisiones_reconocimiento FOR EACH ROW EXECUTE FUNCTION modulo6.fn_tgr_m06_03_inmutabilidad_revisiones();


--
-- Name: TRIGGER tgr_m06_03_inmutabilidad_revisiones ON revisiones_reconocimiento; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TRIGGER tgr_m06_03_inmutabilidad_revisiones ON modulo6.revisiones_reconocimiento IS 'TGR-M06-03 | RF-82 Restricciones 2f y 2g | Garantiza inmutabilidad absoluta de los asientos de reversión. Ningún UPDATE o DELETE está permitido sobre esta tabla. Las reversiones son evidencia contable permanente.';


--
-- Name: mediciones_posteriores tgr_m06_04_consistencia_medicion; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

CREATE TRIGGER tgr_m06_04_consistencia_medicion BEFORE INSERT OR UPDATE ON modulo6.mediciones_posteriores FOR EACH ROW EXECUTE FUNCTION modulo6.fn_tgr_m06_04_consistencia_medicion();


--
-- Name: TRIGGER tgr_m06_04_consistencia_medicion ON mediciones_posteriores; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TRIGGER tgr_m06_04_consistencia_medicion ON modulo6.mediciones_posteriores IS 'TGR-M06-04 | RF-83 RNF-83-05 y CA-6 | Valida que variacion_total = ganancia_perdida_transformacion + ganancia_perdida_precio_mercado, y que variacion_total = valor_razonable_actual - valor_razonable_anterior. Tolerancia de ±0.01 COP para redondeo.';


--
-- Name: mediciones_posteriores tgr_m06_05_inmutabilidad_medicion; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

