-- Name: TRIGGER tgr_m06_07_inmutabilidad_precios ON precios_mercado; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TRIGGER tgr_m06_07_inmutabilidad_precios ON modulo6.precios_mercado IS 'TGR-M06-07 | RF-89 Restricciones (append-only), FA-6, CA-6 | Garantiza que ningún precio de mercado pueda ser editado o eliminado. El mecanismo de corrección es exclusivamente un nuevo INSERT con id_precio_coregido referenciando el original.';


--
-- Name: precios_mercado tgr_m06_08_validacion_fechas_precio; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

CREATE TRIGGER tgr_m06_08_validacion_fechas_precio BEFORE INSERT ON modulo6.precios_mercado FOR EACH ROW EXECUTE FUNCTION modulo6.fn_tgr_m06_08_validacion_fechas_precio();


