--

COMMENT ON TRIGGER tgr_m06_10_inmutabilidad_variaciones ON modulo6.variaciones_valor_razonable IS 'TGR-M06-10 | RF-86 Restricciones (append-only) y CA-12 | Bloquea UPDATE y DELETE sobre variaciones de valor razonable. Las correcciones se realizan mediante nuevos registros con id_variacion_corregida referenciando el original.';


--
-- Name: variaciones_valor_razonable tgr_m06_11_consistencia_variacion; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

CREATE TRIGGER tgr_m06_11_consistencia_variacion BEFORE INSERT ON modulo6.variaciones_valor_razonable FOR EACH ROW EXECUTE FUNCTION modulo6.fn_tgr_m06_11_consistencia_variacion();


--
-- Name: TRIGGER tgr_m06_11_consistencia_variacion ON variaciones_valor_razonable; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TRIGGER tgr_m06_11_consistencia_variacion ON modulo6.variaciones_valor_razonable IS 'TGR-M06-11 | RF-86 Restricciones, CA-8, CA-14 y CA-16 | Valida en INSERT: (1) monto_variacion != 0, (2) monto_variacion = variacion_transformacion + variacion_precio_mercado con tolerancia ±0.01, (3) valores de referencia positivos.';


--
-- Name: valoraciones_por_costos tgr_m06_12_valor_contable_no_negativo; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

CREATE TRIGGER tgr_m06_12_valor_contable_no_negativo BEFORE INSERT OR UPDATE ON modulo6.valoraciones_por_costos FOR EACH ROW EXECUTE FUNCTION modulo6.fn_tgr_m06_12_valor_contable_no_negativo();


