--

COMMENT ON TRIGGER tgr_m06_14b_accounting_cotizaciones ON modulo6.cotizaciones IS 'TGR-M06-14b | RF-COT Restricción 5.2 | Valida que accounting_account tenga 1 o 2 elementos válidos en cotizaciones.';


--
-- Name: registros_costos tgr_m06_15_costos_restricciones; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

CREATE TRIGGER tgr_m06_15_costos_restricciones BEFORE INSERT OR UPDATE ON modulo6.registros_costos FOR EACH ROW EXECUTE FUNCTION modulo6.fn_tgr_m06_15_costos_restricciones();


--
-- Name: TRIGGER tgr_m06_15_costos_restricciones ON registros_costos; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TRIGGER tgr_m06_15_costos_restricciones ON modulo6.registros_costos IS 'TGR-M06-15 | RF-90 Restricciones 5.1 y 5.7 | Valida: (1) monto_costo > 0, (2) naturaleza MANTENIMIENTO no puede reclasificarse a ningún otro valor, (3) naturaleza VENTA no puede reclasificarse a MANTENIMIENTO.';


--
-- Name: revisiones_reconocimiento tgr_m06_16_motivo_revision_minimo; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

CREATE TRIGGER tgr_m06_16_motivo_revision_minimo BEFORE INSERT ON modulo6.revisiones_reconocimiento FOR EACH ROW EXECUTE FUNCTION modulo6.fn_tgr_m06_16_motivo_revision_minimo();


