-- Name: TRIGGER tgr_m06_16_motivo_revision_minimo ON revisiones_reconocimiento; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TRIGGER tgr_m06_16_motivo_revision_minimo ON modulo6.revisiones_reconocimiento IS 'TGR-M06-16 | RF-82 Restricción 2c y CA-15 | Garantiza que motivo_revision tenga al menos 20 caracteres no vacíos antes de confirmar cualquier reversión de reconocimiento inicial.';


--
-- Name: cotizaciones tgr_m06_17_cotizacion_periodo_cerrado; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

CREATE TRIGGER tgr_m06_17_cotizacion_periodo_cerrado BEFORE DELETE OR UPDATE ON modulo6.cotizaciones FOR EACH ROW EXECUTE FUNCTION modulo6.fn_tgr_m06_17_cotizacion_periodo_cerrado();


