-- Name: TRIGGER tgr_m06_17_cotizacion_periodo_cerrado ON cotizaciones; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TRIGGER tgr_m06_17_cotizacion_periodo_cerrado ON modulo6.cotizaciones IS 'TGR-M06-17 | RF-COT Restricción 5.12, FA-10 y FA-11 | Bloquea UPDATE y DELETE sobre cotizaciones cuyo período contable está CERRADO. El período de emisión determina la inmutabilidad de la cotización.';


--
-- Name: cotizaciones tgr_m06_18_fecha_vencimiento_cotizacion; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

CREATE TRIGGER tgr_m06_18_fecha_vencimiento_cotizacion BEFORE INSERT OR UPDATE OF fecha_vencimiento, valor_cotizacion_propuesto ON modulo6.cotizaciones FOR EACH ROW EXECUTE FUNCTION modulo6.fn_tgr_m06_18_fecha_vencimiento_cotizacion();


--
-- Name: cotizaciones tgr_m06_19_campos_inmutables_cotizacion; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

CREATE TRIGGER tgr_m06_19_campos_inmutables_cotizacion BEFORE UPDATE ON modulo6.cotizaciones FOR EACH ROW EXECUTE FUNCTION modulo6.fn_tgr_m06_19_campos_inmutables_cotizacion();


--
-- Name: TRIGGER tgr_m06_19_campos_inmutables_cotizacion ON cotizaciones; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TRIGGER tgr_m06_19_campos_inmutables_cotizacion ON modulo6.cotizaciones IS 'TGR-M06-19 | RF-COT Restricción 5.8 | Protege los campos de identidad de la cotización que no pueden modificarse: fecha_emision, id_periodo_contable, activos_cotizados, accounting_account, line_type y type_code.';


--
-- Name: deterorios_activos tgr_m06_20_deterioro_positivo; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

CREATE TRIGGER tgr_m06_20_deterioro_positivo BEFORE INSERT ON modulo6.deterorios_activos FOR EACH ROW EXECUTE FUNCTION modulo6.fn_tgr_m06_20_deterioro_positivo();


--
-- Name: TRIGGER tgr_m06_20_deterioro_positivo ON deterorios_activos; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TRIGGER tgr_m06_20_deterioro_positivo ON modulo6.deterorios_activos IS 'TGR-M06-20 | RF-88 Entradas y Proceso Pasos 5a y 5c | Valida que impacto_economico_cop > 0 y que justificacion no esté vacía al registrar un deterioro de activo biológico.';


--
-- Name: ejecuciones_cierre_periodo tgr_m06_21_inmutabilidad_cierre; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

CREATE TRIGGER tgr_m06_21_inmutabilidad_cierre BEFORE DELETE OR UPDATE ON modulo6.ejecuciones_cierre_periodo FOR EACH ROW EXECUTE FUNCTION modulo6.fn_tgr_m06_21_inmutabilidad_cierre();


--
-- Name: TRIGGER tgr_m06_21_inmutabilidad_cierre ON ejecuciones_cierre_periodo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TRIGGER tgr_m06_21_inmutabilidad_cierre ON modulo6.ejecuciones_cierre_periodo IS 'TGR-M06-21 | RF-87 Restricciones y RNF Fiabilidad | Garantiza que las ejecuciones de cierre en estado COMPLETADO o FALLIDO sean inmutables. Bloquea todos los DELETE. Permite UPDATE solo sobre estado EN_PROCESO.';


--
-- Name: ejecuciones_cierre_periodo tgr_m06_22_unicidad_cierre_activo; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

CREATE TRIGGER tgr_m06_22_unicidad_cierre_activo BEFORE INSERT OR UPDATE OF estado ON modulo6.ejecuciones_cierre_periodo FOR EACH ROW EXECUTE FUNCTION modulo6.fn_tgr_m06_22_unicidad_cierre_activo();


--
-- Name: TRIGGER tgr_m06_22_unicidad_cierre_activo ON ejecuciones_cierre_periodo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TRIGGER tgr_m06_22_unicidad_cierre_activo ON modulo6.ejecuciones_cierre_periodo IS 'TGR-M06-22 | RF-87 Restricciones (exclusive lock) y FA-5 | Impide que existan dos ejecuciones de cierre en estado EN_PROCESO para el mismo período contable simultáneamente.';


--
-- Name: estados_resultados_periodo tgr_m06_23_inmutabilidad_estado_resultados; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

CREATE TRIGGER tgr_m06_23_inmutabilidad_estado_resultados BEFORE DELETE OR UPDATE ON modulo6.estados_resultados_periodo FOR EACH ROW EXECUTE FUNCTION modulo6.fn_tgr_m06_23_inmutabilidad_estado_resultados();


--
-- Name: TRIGGER tgr_m06_23_inmutabilidad_estado_resultados ON estados_resultados_periodo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TRIGGER tgr_m06_23_inmutabilidad_estado_resultados ON modulo6.estados_resultados_periodo IS 'TGR-M06-23 | RF-93 Restricción 5 | Garantiza inmutabilidad del estado de resultados en estado GENERADO o APROBADO. Bloquea todos los DELETE. Contenido base es permanente; versiones alternativas se crean como nuevos registros.';


--
-- Name: estados_resultados_periodo tgr_m06_24_consistencia_resultado_neto; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

CREATE TRIGGER tgr_m06_24_consistencia_resultado_neto BEFORE INSERT OR UPDATE ON modulo6.estados_resultados_periodo FOR EACH ROW EXECUTE FUNCTION modulo6.fn_tgr_m06_24_consistencia_resultado_neto();


--
-- Name: TRIGGER tgr_m06_24_consistencia_resultado_neto ON estados_resultados_periodo; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TRIGGER tgr_m06_24_consistencia_resultado_neto ON modulo6.estados_resultados_periodo IS 'TGR-M06-24 | RF-93 Restricción 2 (REGLA DE CONCILIACIÓN) y CA-4 | Valida que resultado_neto = ingresos_transformacion + ingresos_precio + ingresos_cosecha - gastos_mantenimiento - bajas_deterioro. Tolerancia de ±0.01 COP para redondeo.';


--
-- Name: informes_revelacion_nic41 tgr_m06_25_inmutabilidad_informe_revelacion; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

CREATE TRIGGER tgr_m06_25_inmutabilidad_informe_revelacion BEFORE DELETE OR UPDATE ON modulo6.informes_revelacion_nic41 FOR EACH ROW EXECUTE FUNCTION modulo6.fn_tgr_m06_25_inmutabilidad_informe_revelacion();


--
-- Name: TRIGGER tgr_m06_25_inmutabilidad_informe_revelacion ON informes_revelacion_nic41; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TRIGGER tgr_m06_25_inmutabilidad_informe_revelacion ON modulo6.informes_revelacion_nic41 IS 'TGR-M06-25 | RF-92 Restricciones 4 y 5 | Garantiza que los informes de revelaciones en estado APROBADO o ARCHIVADO sean inmutables. Bloquea todos los DELETE. Solo BORRADOR y RECHAZADO pueden modificarse.';


--
-- Name: cadenas_trazabilidad_contable tgr_m06_26_trazabilidad_periodo_cerrado; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

CREATE TRIGGER tgr_m06_26_trazabilidad_periodo_cerrado BEFORE INSERT OR DELETE OR UPDATE ON modulo6.cadenas_trazabilidad_contable FOR EACH ROW EXECUTE FUNCTION modulo6.fn_tgr_m06_26_trazabilidad_periodo_cerrado();


--
-- Name: TRIGGER tgr_m06_26_trazabilidad_periodo_cerrado ON cadenas_trazabilidad_contable; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TRIGGER tgr_m06_26_trazabilidad_periodo_cerrado ON modulo6.cadenas_trazabilidad_contable IS 'TGR-M06-26 | RF-91 Restricción 4, RF-87 | Garantiza que las cadenas de trazabilidad vinculadas a variaciones de períodos CERRADOS sean inmutables. No se permite modificar ni completar retroactivamente cadenas de períodos cerrados.';


--
-- Name: auditorias_financieras tgr_m06_27_tipo_actor_auditoria; Type: TRIGGER; Schema: modulo6; Owner: postgres
--

CREATE TRIGGER tgr_m06_27_tipo_actor_auditoria BEFORE INSERT ON modulo6.auditorias_financieras FOR EACH ROW EXECUTE FUNCTION modulo6.fn_tgr_m06_27_tipo_actor_auditoria();


--
-- Name: TRIGGER tgr_m06_27_tipo_actor_auditoria ON auditorias_financieras; Type: COMMENT; Schema: modulo6; Owner: postgres
--

COMMENT ON TRIGGER tgr_m06_27_tipo_actor_auditoria ON modulo6.auditorias_financieras IS 'TGR-M06-27 | RF-94 Restricción 6, CA-4 y RNF-04 | Valida en INSERT: (1) tipo_actor=USUARIO requiere id_usuario no nulo, (2) tipo_actor=SISTEMA requiere id_usuario nulo, (3) hash_integridad obligatorio y con exactamente 64 caracteres (SHA-256).';


